    private static SectorData[] ImportDerivedSectors(FlowNavigationGridAsset.SectorDerivedData[] source)
    {
        if (source == null)
            throw new InvalidOperationException("ImportDerivedSectors failed: source is null.");

        SectorData[] result = new SectorData[source.Length];
        for (int i = 0; i < source.Length; i++)
        {
            FlowNavigationGridAsset.SectorDerivedData sector = source[i];
            if (sector == null)
                throw new InvalidOperationException($"ImportDerivedSectors failed: sector is null at index={i}.");

            SectorData imported = new SectorData
            {
                SectorId = sector.SectorId,
                StartX = sector.StartX,
                StartY = sector.StartY,
                Width = sector.Width,
                Height = sector.Height,
                Center = sector.Center,
                DirtyVersion = sector.DirtyVersion,
                IsClearCostField = sector.IsClearCostField,
                IsClearFlowTile = sector.IsClearFlowTile,
                UniformIslandId = sector.UniformIslandId,
                LocalComponentIds = sector.LocalComponentIds != null ? (int[])sector.LocalComponentIds.Clone() : Array.Empty<int>(),
                LocalComponentCount = sector.LocalComponentCount
            };
            if (sector.PortalIds != null)
                imported.PortalIds.AddRange(sector.PortalIds);
            if (sector.PortalTransitions != null)
            {
                for (int j = 0; j < sector.PortalTransitions.Length; j++)
                {
                    FlowNavigationGridAsset.PortalTransitionDerivedData transition = sector.PortalTransitions[j];
                    if (transition == null)
                        throw new InvalidOperationException($"ImportDerivedSectors failed: transition is null sector={sector.SectorId} index={j}.");

                    imported.PortalTransitions.Add(new PortalTransition
                    {
                        FromPortalId = transition.FromPortalId,
                        ToPortalId = transition.ToPortalId
                    });
                }
            }
            RebuildIncomingPortalTransitionIndex(imported);

            result[i] = imported;
        }

        return result;
    }

    private static PortalData[] ImportDerivedPortals(FlowNavigationGridAsset.PortalDerivedData[] source)
    {
        if (source == null)
            throw new InvalidOperationException("ImportDerivedPortals failed: source is null.");

        PortalData[] result = new PortalData[source.Length];
        for (int i = 0; i < source.Length; i++)
        {
            FlowNavigationGridAsset.PortalDerivedData portal = source[i];
            if (portal == null)
                throw new InvalidOperationException($"ImportDerivedPortals failed: portal is null at index={i}.");
            if (portal.CellsA == null || portal.CellsA.Length == 0 || portal.CellsB == null || portal.CellsB.Length == 0)
                throw new InvalidOperationException($"ImportDerivedPortals failed: portal cells are invalid portal={portal.PortalId}.");
            if (portal.CellsA.Length != portal.CellsB.Length)
                throw new InvalidOperationException($"ImportDerivedPortals failed: portal side count mismatch portal={portal.PortalId} a={portal.CellsA.Length} b={portal.CellsB.Length}.");

            result[i] = new PortalData
            {
                PortalId = portal.PortalId,
                SectorAId = portal.SectorAId,
                SectorBId = portal.SectorBId,
                CellsA = (Vector2Int[])portal.CellsA.Clone(),
                CellsB = (Vector2Int[])portal.CellsB.Clone(),
                WorldCenter = portal.WorldCenter,
                WidthCells = portal.WidthCells,
                IsNarrow = portal.IsNarrow,
                IsVerticalBoundary = portal.IsVerticalBoundary
            };
        }

        return result;
    }

    private static void ValidateImportedDerivedNavigationWorld(NavigationWorld world)
    {
        if (world == null)
            throw new InvalidOperationException("ValidateImportedDerivedNavigationWorld failed: world is null.");
        int cellCount = world.Width * world.Height;
        if (world.IslandIds == null || world.IslandIds.Length != cellCount)
            throw new InvalidOperationException("ValidateImportedDerivedNavigationWorld failed: island ids length mismatch.");
        if (world.Sectors == null || world.Sectors.Length != world.SectorCountX * world.SectorCountY)
            throw new InvalidOperationException("ValidateImportedDerivedNavigationWorld failed: sector array length mismatch.");
        if (world.Portals == null || world.PortalsById == null)
            throw new InvalidOperationException("ValidateImportedDerivedNavigationWorld failed: portal storage is invalid.");

        for (int i = 0; i < world.Sectors.Length; i++)
        {
            SectorData sector = world.Sectors[i];
            if (sector == null)
                throw new InvalidOperationException($"ValidateImportedDerivedNavigationWorld failed: sector is null index={i}.");
            if (sector.SectorId != i)
                throw new InvalidOperationException($"ValidateImportedDerivedNavigationWorld failed: sector id mismatch index={i} sectorId={sector.SectorId}.");
            if (sector.LocalComponentIds == null || sector.LocalComponentIds.Length != sector.Width * sector.Height)
                throw new InvalidOperationException($"ValidateImportedDerivedNavigationWorld failed: local component length mismatch sector={sector.SectorId}.");
        }

        for (int i = 0; i < world.Portals.Length; i++)
        {
            PortalData portal = world.Portals[i];
            if (portal.SectorAId < 0 || portal.SectorAId >= world.Sectors.Length || portal.SectorBId < 0 || portal.SectorBId >= world.Sectors.Length)
                throw new InvalidOperationException($"ValidateImportedDerivedNavigationWorld failed: portal sector out of range portal={portal.PortalId}.");
            if (!world.Sectors[portal.SectorAId].PortalIds.Contains(portal.PortalId)
                || !world.Sectors[portal.SectorBId].PortalIds.Contains(portal.PortalId))
            {
                throw new InvalidOperationException($"ValidateImportedDerivedNavigationWorld failed: portal is not referenced by both sectors portal={portal.PortalId}.");
            }
        }
    }

    private static NavigationWorld ApplyInitialRuntimeOverlayToPrebakedWorldIfNeeded(
        NavigationWorld staticWorld,
        int agentTypeId,
        out List<PendingSectorPortalAccess> pendingPortalAccessEntries)
    {
        pendingPortalAccessEntries = null;
        if (staticWorld == null)
            throw new InvalidOperationException("ApplyInitialRuntimeOverlayToPrebakedWorldIfNeeded failed: static world is null.");
        if (CircleObstacles.Count == 0 && BoxObstacles.Count == 0 && CostStamps.Count == 0)
            return staticWorld;

        HashSet<int> dirtySectors = new HashSet<int>();
        foreach (CircleObstacle circle in CircleObstacles.Values)
        {
            FixVector2 radius = new FixVector2(circle.RadiusFixed, circle.RadiusFixed);
            CollectDirtySectorsFixed(staticWorld, circle.PositionFixed - radius, circle.PositionFixed + radius, dirtySectors, includeNeighbors: true);
        }

        foreach (BoxObstacle box in BoxObstacles.Values)
        {
            FixVector2 halfExtents = ResolveBoxObstacleNavigationHalfExtentsFixed(staticWorld, box);
            CollectDirtySectorsFixed(staticWorld, box.CenterFixed - halfExtents, box.CenterFixed + halfExtents, dirtySectors, includeNeighbors: true);
        }

        foreach (CostStamp stamp in CostStamps.Values)
        {
            if (stamp.AgentTypeId != AnyAgentTypeId && stamp.AgentTypeId != agentTypeId)
                continue;

            CollectDirtySectorsFixed(staticWorld, stamp.BoundsMinFixed, stamp.BoundsMaxFixed, dirtySectors, includeNeighbors: true);
        }

        if (dirtySectors.Count == 0)
            return staticWorld;

        HashSet<int> costDirtySectors = ExpandDirtySectorsByCellRadius(
            staticWorld,
            dirtySectors,
            ResolveWallCostPaddingCells(staticWorld, 1));
        NavigationWorld patchedWorld = ApplyRuntimeDirtyOverlayImmediate(
            staticWorld,
            dirtySectors,
            costDirtySectors,
            CreateSortedCircleObstacleSnapshot(CircleObstacles.Values),
            CreateSortedBoxObstacleSnapshot(BoxObstacles.Values),
            CreateSortedCostStampSnapshot(CostStamps.Values),
            "initial-prebaked-overlay",
            out pendingPortalAccessEntries);
        LogNoStacktrace(
            $"[FlowPrebakedWorldOverlay] agentType={agentTypeId} dirtySectors={dirtySectors.Count} costSectors={costDirtySectors.Count} " +
            $"circleCount={CircleObstacles.Count} boxCount={BoxObstacles.Count} costStampCount={CostStamps.Count}");
        return patchedWorld;
    }

    private static NavigationWorld ApplyRuntimeDirtyOverlayImmediate(
        NavigationWorld targetWorld,
        HashSet<int> dirtySectors,
        HashSet<int> costDirtySectors,
        List<CircleObstacle> circleObstacles,
        List<BoxObstacle> boxObstacles,
        List<CostStamp> costStamps,
        string reason,
        out List<PendingSectorPortalAccess> pendingPortalAccessEntries)
    {
        pendingPortalAccessEntries = null;
        if (targetWorld == null)
            throw new InvalidOperationException("ApplyRuntimeDirtyOverlayImmediate failed: target world is null.");
        if (dirtySectors == null || dirtySectors.Count == 0)
            return targetWorld;
        if (costDirtySectors == null)
            throw new InvalidOperationException("ApplyRuntimeDirtyOverlayImmediate failed: cost dirty sectors are null.");

        RuntimeDirtyRebuildJob job = new RuntimeDirtyRebuildJob
        {
            TargetWorld = targetWorld,
            WorkingWorld = CloneNavigationWorldForRuntimeDirty(targetWorld, dirtySectors),
            DirtySectors = dirtySectors,
            CostDirtySectors = costDirtySectors,
            DirtySectorIds = CreateSortedSectorIdSnapshot(dirtySectors, "dirty sectors"),
            CostDirtySectorIds = CreateSortedSectorIdSnapshot(costDirtySectors, "cost dirty sectors"),
            CircleObstacles = CreateSortedCircleObstacleSnapshot(circleObstacles),
            BoxObstacles = CreateSortedBoxObstacleSnapshot(boxObstacles),
            CostStamps = CreateSortedCostStampSnapshot(costStamps),
            Stage = RuntimeDirtyRebuildStage.ResetWalkable,
            Reason = reason
        };

        while (job.Stage != RuntimeDirtyRebuildStage.Complete)
        {
            switch (job.Stage)
            {
                case RuntimeDirtyRebuildStage.ResetWalkable:
                    ProcessRuntimeDirtyResetWalkable(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.ApplyObstacles:
                    ProcessRuntimeDirtyObstacles(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.NeighborMask:
                    ProcessRuntimeDirtyNeighborMask(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.SymmetrizeNeighborMask:
                    SymmetrizeNeighborTraversalMaskForSectors(job.WorkingWorld, job.DirtySectors);
                    PruneIsolatedWalkableCellsForSectors(job.WorkingWorld, job.DirtySectors, "initial-prebaked-overlay");
                    job.SectorCursor = 0;
                    job.Stage = RuntimeDirtyRebuildStage.CostField;
                    break;
                case RuntimeDirtyRebuildStage.CostField:
                    ProcessRuntimeDirtyCostField(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.IslandField:
                    ProcessRuntimeDirtyIslandField(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.SectorComponents:
                    ProcessRuntimeDirtySectorComponents(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.PortalGraph:
                    ProcessRuntimeDirtyPortalGraph(job, long.MaxValue, forceComplete: true);
                    break;
                case RuntimeDirtyRebuildStage.PrepareCommit:
                    job.Stage = RuntimeDirtyRebuildStage.Complete;
                    break;
                case RuntimeDirtyRebuildStage.Commit:
                    job.Stage = RuntimeDirtyRebuildStage.Complete;
                    break;
                default:
                    throw new InvalidOperationException($"ApplyRuntimeDirtyOverlayImmediate failed: unknown stage {job.Stage}.");
            }
        }

        pendingPortalAccessEntries = job.PendingPortalAccessEntries;
        return job.WorkingWorld;
    }

    private static TestTerrainOverride ResolveDefaultAuthoredTerrainSource()
    {
        if (AuthoredTerrainSources.TryGetValue(AnyAgentTypeId, out TestTerrainOverride anySource))
            return anySource;
        if (AuthoredTerrainSources.TryGetValue(ResolvePreferredAgentTypeId(0), out TestTerrainOverride defaultSource))
            return defaultSource;

        TestTerrainOverride selectedSource = null;
        int selectedAgentTypeId = int.MaxValue;
        foreach (KeyValuePair<int, TestTerrainOverride> pair in AuthoredTerrainSources)
        {
            if (pair.Value == null)
                throw new InvalidOperationException($"Authored navigation source is null. agentTypeId={pair.Key}.");
            if (pair.Key >= selectedAgentTypeId)
                continue;

            selectedAgentTypeId = pair.Key;
            selectedSource = pair.Value;
        }

        return selectedSource;
    }

    public static void SetConfig(FlowFieldNavigationConfig config)
    {
        if (config == null)
            throw new InvalidOperationException("FlowFieldCrowdMovementSystem.SetConfig failed: config is null.");

        bool requiresRebuild = Config.SectorSizeInCells != config.SectorSizeInCells
                               || Config.PortalNarrowWidthCells != config.PortalNarrowWidthCells
                               || Config.PortalMaxWindowWidthCells != config.PortalMaxWindowWidthCells;

        Config.SectorSizeInCells = Mathf.Max(4, config.SectorSizeInCells);
        Config.PortalNarrowWidthCells = Mathf.Max(1, config.PortalNarrowWidthCells);
        Config.PortalMaxWindowWidthCells = Mathf.Max(2, config.PortalMaxWindowWidthCells);
        Config.FlowTileCacheLimit = Mathf.Max(16, config.FlowTileCacheLimit);
        Config.WorldBuildOperationQuota = Mathf.Max(1, config.WorldBuildOperationQuota);
        Config.RuntimeRebuildOperationQuota = Mathf.Max(1, config.RuntimeRebuildOperationQuota);
        Config.DeterministicFlowTileCommitQuota = Mathf.Max(1, config.DeterministicFlowTileCommitQuota);
        Config.SharedGoalBuildOperationQuota = Mathf.Max(1, config.SharedGoalBuildOperationQuota);
        Config.RequireAuthoredNavigationSource = config.RequireAuthoredNavigationSource;
        Config.EnableDeterministicStaticCollisionShadow = config.EnableDeterministicStaticCollisionShadow;
        Config.StaticCollisionShadowMismatchTolerance = Mathf.Max(0f, config.StaticCollisionShadowMismatchTolerance);
        Config.StaticCollisionShadowLogIntervalTicks = Mathf.Max(1, config.StaticCollisionShadowLogIntervalTicks);
        LogicStaticCollisionShadowService.Configure(
            Config.EnableDeterministicStaticCollisionShadow,
            Config.StaticCollisionShadowMismatchTolerance,
            Config.StaticCollisionShadowLogIntervalTicks);
        Config.DrawNavigationDebug = config.DrawNavigationDebug;
        Config.DrawFlowFieldDebug = config.DrawFlowFieldDebug;
        Config.StrictNoFallback = true;

        if (requiresRebuild)
            MarkWorldDirty();
    }

    public static void PrepareRuntimeDependencies()
    {
        Fix64 smallRadius = ResolveConfiguredAgentTypeRadiusFixed("SmallUnitCollisionRadius");
        Fix64 mediumRadius = ResolveConfiguredAgentTypeRadiusFixed("MediumUnitCollisionRadius");
        Fix64 largeRadius = ResolveConfiguredAgentTypeRadiusFixed("LargeUnitCollisionRadius");

        s_SmallAgentTypeRadiusFixed = smallRadius;
        s_MediumAgentTypeRadiusFixed = mediumRadius;
        s_LargeAgentTypeRadiusFixed = largeRadius;
        s_RuntimeAgentTypeRadiiPrepared = true;
        Debug.Log(
            $"[FlowField] Runtime agent radii prepared. smallRaw={smallRadius.RawValue}, " +
            $"mediumRaw={mediumRadius.RawValue}, largeRaw={largeRadius.RawValue}.");
    }

    public static void MarkWorldDirty(string reason = null)
    {
        _lastWorldDirtyReason = string.IsNullOrWhiteSpace(reason) ? "unspecified" : reason;

        foreach (WorldRuntimeState state in WorldStates.Values)
        {
            state.IsDirty = true;
            state.DirtyRuntimeObstacleSectors.Clear();
            ReturnRuntimeDirtyWorkingWorld(state.RuntimeDirtyJob);
            state.RuntimeDirtyJob = null;
            state.BuildJob = null;
        }

        ClearFlowTileCache();
        ReturnPendingFlowTileBuildIntegrations();
        FlowTileBuildQueue.Clear();
        PendingFlowTileBuildJobs.Clear();
        ActiveFlowTileBuildKeys.Clear();
        ClearSectorPathCache();
        ClearSectorPortalAccessCache();
        StartPortalChoiceCache.Clear();
        ClearSharedGoalFieldCache();
        SharedGoalFieldBuildQueue.Clear();
        PendingSharedGoalFieldBuildJobs.Clear();
        ActiveSharedGoalFieldBuildKeys.Clear();
        ActiveSharedGoalFieldDemandStartSectors.Clear();
        ActiveSharedGoalFieldDemandStartCells.Clear();
        s_NavigationDistancePrewarmCompleted = false;
        MovingTargetAnchors.Clear();
        CombatTargetSlotCache.Clear();
        FixedPortalOwners.Clear();
        FixedPortalOwnerEvaluatedFrameByWorld.Clear();
        FixedCorridorLookupByWorldVersion.Clear();
        AgentSpatialBuckets.Clear();
        NearbyAgentScratch.Clear();
        _lastAgentSpatialBucketFrame = -1;
        _lastAgentSpatialBucketWorldVersion = -1;
        foreach (KeyValuePair<int, AgentRuntimeData> pair in Agents)
        {
            pair.Value.NavState.PathHandle = null;
            ClearStableGoal(pair.Value);
        }

        if (GameDebugSettings.IsEnabled(DebugCategory.Move))
            LogNoStacktrace($"[FlowWorld] MarkWorldDirty reason={_lastWorldDirtyReason} states={WorldStates.Count} agents={Agents.Count}");
    }

    public static void PrewarmNavigationWorlds()
    {
        List<int> agentTypeIds = CollectNavigationWorldAgentTypes();
        Stopwatch stopwatch = Stopwatch.StartNew();
        LogNoStacktrace(
            $"[FlowWorld] Prewarm begin agentTypes=[{string.Join(",", agentTypeIds)}] agents={Agents.Count} " +
            $"config(sector={Config.SectorSizeInCells}, tileCacheLimit={Config.FlowTileCacheLimit})");
        int builtCount = 0;
        int skippedCount = 0;
        foreach (int agentTypeId in agentTypeIds)
        {
            bool hadWorld = WorldStates.TryGetValue(agentTypeId, out WorldRuntimeState existingState)
                            && existingState.World != null
                            && !existingState.IsDirty;
            if (!TryEnsureWorldBuilt(agentTypeId, allowSynchronousBuild: true))
            {
                skippedCount++;
                LogWarningNoStacktrace($"[FlowWorld] Prewarm skipped agentType={agentTypeId}: terrain source unavailable.");
                continue;
            }

            if (!hadWorld)
                builtCount++;
        }

        stopwatch.Stop();
        LogNoStacktrace(
            $"[FlowWorld] Prewarm end elapsed={stopwatch.Elapsed.TotalMilliseconds:F3}ms built={builtCount} skipped={skippedCount} " +
            $"worldStates={WorldStates.Count} activeWorld={(_world != null ? _world.Version.ToString() : "null")}");
    }

    public static bool HasActiveNavigationAgents()
    {
        foreach (AgentRuntimeData agent in Agents.Values)
        {
            if (agent == null || agent.IgnoreAgentCollision)
                continue;
            if (agent.HasNavigationIntent)
                return true;
        }

        return false;
    }

    private static List<int> CollectNavigationWorldAgentTypes()
    {
        List<int> agentTypeIds = NavigationWorldAgentTypeIdsScratch;
        HashSet<int> seen = NavigationWorldAgentTypeIdsSeenScratch;
        agentTypeIds.Clear();
        seen.Clear();

        if (AuthoredTerrainSources.Count > 1
            || (AuthoredTerrainSources.Count == 1 && !AuthoredTerrainSources.ContainsKey(AnyAgentTypeId)))
        {
            foreach (int agentTypeId in AuthoredTerrainSources.Keys)
                AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(agentTypeId));

            return SortNavigationWorldAgentTypes(agentTypeIds);
        }

#if UNITY_EDITOR
        if (_testTerrainOverride != null)
        {
            if (_testTerrainOverride.AgentTypeId != AnyAgentTypeId)
            {
                AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(_testTerrainOverride.AgentTypeId));
                return SortNavigationWorldAgentTypes(agentTypeIds);
            }

            AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(0));
            foreach (AgentRuntimeData agent in Agents.Values)
                AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(agent.AgentTypeId));

            return SortNavigationWorldAgentTypes(agentTypeIds);
        }
#endif

        if (AuthoredTerrainSources.Count > 0)
        {
            if (!AuthoredTerrainSources.ContainsKey(AnyAgentTypeId))
            {
                foreach (int agentTypeId in AuthoredTerrainSources.Keys)
                    AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(agentTypeId));
            }
            else
            {
                AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(0));
                foreach (AgentRuntimeData agent in Agents.Values)
                    AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(agent.AgentTypeId));
            }

            return SortNavigationWorldAgentTypes(agentTypeIds);
        }

        AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(0));
        foreach (AgentRuntimeData agent in Agents.Values)
            AddNavigationWorldAgentType(agentTypeIds, seen, ResolvePreferredAgentTypeId(agent.AgentTypeId));

        return SortNavigationWorldAgentTypes(agentTypeIds);
    }

    private static List<int> SortNavigationWorldAgentTypes(List<int> agentTypeIds)
    {
        if (agentTypeIds == null)
            throw new ArgumentNullException(nameof(agentTypeIds));
        agentTypeIds.Sort();
        return agentTypeIds;
    }

    private static void AddNavigationWorldAgentType(List<int> agentTypeIds, HashSet<int> seen, int agentTypeId)
    {
        if (!seen.Add(agentTypeId))
            return;

        int insertIndex = agentTypeIds.BinarySearch(agentTypeId);
        if (insertIndex >= 0)
            throw new InvalidOperationException($"AddNavigationWorldAgentType failed: duplicate agent type {agentTypeId} escaped the seen set.");
        agentTypeIds.Insert(~insertIndex, agentTypeId);
    }

    private static void MarkRuntimeObstacleDirty(FixVector2 boundsMinimum, FixVector2 boundsMaximum)
    {
        if (boundsMinimum.x > boundsMaximum.x || boundsMinimum.y > boundsMaximum.y)
            throw new ArgumentOutOfRangeException(nameof(boundsMinimum), "Runtime obstacle bounds minimum exceeds maximum.");

        _lastRuntimeObstacleDirtyReason =
            $"boundsMinRaw=({boundsMinimum.x.RawValue},{boundsMinimum.y.RawValue}) boundsMaxRaw=({boundsMaximum.x.RawValue},{boundsMaximum.y.RawValue}) " +
            $"circleCount={CircleObstacles.Count} boxCount={BoxObstacles.Count} costStampCount={CostStamps.Count}";
        if (WorldStates.Count == 0)
        {
            MarkWorldDirty();
            return;
        }

        foreach (KeyValuePair<int, WorldRuntimeState> pair in WorldStates)
        {
            WorldRuntimeState state = pair.Value;
            if (state.IsDirty)
            {
                state.BuildJob = null;
                continue;
            }

            if (state.World == null)
                continue;

            CollectDirtySectorsFixed(state.World, boundsMinimum, boundsMaximum, state.DirtyRuntimeObstacleSectors, includeNeighbors: true);
            InvalidateRuntimeDirtyJob(state);
        }
    }

    public static void ProcessRuntimeRebuildQueue()
    {
        BeginPerfCall();
        long queueStartTicks = Stopwatch.GetTimestamp();
        BeginNavigationWorkBudget(Config.RuntimeRebuildOperationQuota);
        try
        {
            const long deadlineTicks = 0L;

            RuntimeRebuildQueueScratch.Clear();
            foreach (WorldRuntimeState state in WorldStates.Values)
            {
                if (state == null || state.IsDirty || state.World == null)
                    continue;
                if (state.DirtyRuntimeObstacleSectors.Count == 0 && state.RuntimeDirtyJob == null)
                    continue;

                RuntimeRebuildQueueScratch.Add(state);
            }

            RuntimeRebuildQueueScratch.Sort((left, right) =>
            {
                int priorityOrder = ResolveRuntimeDirtyPriority(right).CompareTo(ResolveRuntimeDirtyPriority(left));
                return priorityOrder != 0 ? priorityOrder : left.AgentTypeId.CompareTo(right.AgentTypeId);
            });
            for (int i = 0; i < RuntimeRebuildQueueScratch.Count; i++)
            {
                WorldRuntimeState state = RuntimeRebuildQueueScratch[i];
                if (!EnsureRuntimeDirtyJob(state))
                    continue;
                RuntimeDirtyRebuildJob job = state.RuntimeDirtyJob;
                RuntimeDirtyRebuildStage stageBefore = job.Stage;
                long jobStartTicks = Stopwatch.GetTimestamp();
                ProcessRuntimeDirtyJob(state, deadlineTicks, forceComplete: false);
                long jobElapsedTicks = Stopwatch.GetTimestamp() - jobStartTicks;
                if (jobElapsedTicks > _editorSlowestRuntimeDirtyCallTicks)
                {
                    _editorSlowestRuntimeDirtyCallTicks = jobElapsedTicks;
                    _editorSlowestRuntimeDirtyCallDiagnostics =
                        $"elapsedMs={TicksToMilliseconds(jobElapsedTicks):F3},agent={state.AgentTypeId}," +
                        $"stage={stageBefore}->{job.Stage},cloneShellStage={job.CloneShellStage},cloneSectorCursor={job.CloneSectorCursor}," +
                        $"islandScanIndex={job.IslandScanIndex},islandCurrentSize={job.IslandCurrentSize}," +
                        $"portalStage={job.PortalStage},portalSectorCursor={job.PortalSectorCursor}," +
                        BuildRuntimeDirtyStageAccumulatedTiming(job) + "," +
                        BuildRuntimeDirtyCommitTiming(job);
                }
                if (IsNavigationWorkBudgetExhausted())
                    break;
            }
        }
        finally
        {
            EndNavigationWorkBudget();
            _perf.RuntimeRebuildQueueTicks += Stopwatch.GetTimestamp() - queueStartTicks;
        }
    }

    public static int CompleteRuntimeRebuildQueue()
    {
        if (_navigationWorkBudgetActive)
            throw new InvalidOperationException("CompleteRuntimeRebuildQueue failed: navigation work budget is already active.");
        if (WorldStates.Count == 0)
            throw new InvalidOperationException("CompleteRuntimeRebuildQueue failed: no navigation worlds are registered.");

        RuntimeRebuildQueueScratch.Clear();
        foreach (WorldRuntimeState state in WorldStates.Values)
        {
            if (state == null)
                throw new InvalidOperationException("CompleteRuntimeRebuildQueue failed: navigation world state is null.");
            if (state.IsDirty || state.World == null)
            {
                throw new InvalidOperationException(
                    $"CompleteRuntimeRebuildQueue failed: navigation world is not ready. agentType={state.AgentTypeId}, isDirty={state.IsDirty}, hasWorld={state.World != null}.");
            }
            if (state.DirtyRuntimeObstacleSectors.Count == 0 && state.RuntimeDirtyJob == null)
                continue;

            RuntimeRebuildQueueScratch.Add(state);
        }

        RuntimeRebuildQueueScratch.Sort((left, right) => left.AgentTypeId.CompareTo(right.AgentTypeId));
        int completedCount = 0;
        for (int i = 0; i < RuntimeRebuildQueueScratch.Count; i++)
        {
            WorldRuntimeState state = RuntimeRebuildQueueScratch[i];
            if (!EnsureRuntimeDirtyJob(state))
                throw new InvalidOperationException($"CompleteRuntimeRebuildQueue failed: pending state has no rebuild job. agentType={state.AgentTypeId}.");

            ProcessRuntimeDirtyJob(state, long.MaxValue, forceComplete: true);
            if (state.RuntimeDirtyJob != null || state.DirtyRuntimeObstacleSectors.Count != 0)
            {
                throw new InvalidOperationException(
                    $"CompleteRuntimeRebuildQueue failed: rebuild remains pending. agentType={state.AgentTypeId}, diagnostics={GetEditorRuntimeDirtyJobDiagnostics()}.");
            }

            completedCount++;
        }

        return completedCount;
    }

    public static void ProcessWorldBuildQueue()
    {
        BeginPerfCall();
        long queueStartTicks = Stopwatch.GetTimestamp();
        BeginNavigationWorkBudget(Config.WorldBuildOperationQuota);
        try
        {
            if (Config.RequireAuthoredNavigationSource && !HasAuthoredNavigationSource())
            {
                if (HasActiveNavigationAgents())
                {
                    throw new InvalidOperationException(
                        "ProcessWorldBuildQueue failed: active navigation agents exist before any FlowNavigationGridSource has applied a FlowNavigationGridAsset.");
                }

                return;
            }

            const long deadlineTicks = 0L;

            EnsureWorldBuildStatesForKnownAgentTypes();
            RuntimeRebuildQueueScratch.Clear();
            foreach (WorldRuntimeState state in WorldStates.Values)
            {
                if (state == null || !state.IsDirty)
                    continue;

                RuntimeRebuildQueueScratch.Add(state);
            }

            RuntimeRebuildQueueScratch.Sort((left, right) =>
            {
                int priorityOrder = ResolveWorldBuildPriority(right).CompareTo(ResolveWorldBuildPriority(left));
                return priorityOrder != 0 ? priorityOrder : left.AgentTypeId.CompareTo(right.AgentTypeId);
            });
            for (int i = 0; i < RuntimeRebuildQueueScratch.Count; i++)
            {
                WorldRuntimeState state = RuntimeRebuildQueueScratch[i];
                if (!EnsureWorldBuildJob(state))
                    continue;

                ProcessWorldBuildJob(state, deadlineTicks, forceComplete: false);
                if (IsNavigationWorkBudgetExhausted())
                    break;
            }
        }
        finally
        {
            EndNavigationWorkBudget();
            _perf.WorldBuildQueueTicks += Stopwatch.GetTimestamp() - queueStartTicks;
        }
    }

    public static void ProcessFlowTileBuildQueue()
    {
        BeginPerfCall();
        long queueStartTicks = Stopwatch.GetTimestamp();
        NavigationWorld previousWorld = _world;
        WorldRuntimeState previousActiveWorldState = _activeWorldState;
        try
        {
            if (!CanProcessFlowTileBuildQueue())
                return;

            const long deadlineTicks = 0L;

            FlowBuildQueueWorldScratch.Clear();
            foreach (WorldRuntimeState state in WorldStates.Values)
                FlowBuildQueueWorldScratch.Add(state);
            FlowBuildQueueWorldScratch.Sort((left, right) => left.AgentTypeId.CompareTo(right.AgentTypeId));

            int worldCount = FlowBuildQueueWorldScratch.Count;
            int startIndex = worldCount > 0 ? _flowBuildQueueWorldStartIndex % worldCount : 0;
            for (int reverseOffset = worldCount - 1; reverseOffset >= 0; reverseOffset--)
            {
                int worldIndex = (startIndex + reverseOffset) % worldCount;
                ActivateFlowBuildQueueWorld(FlowBuildQueueWorldScratch[worldIndex]);

                long phaseTicks = Stopwatch.GetTimestamp();
                EnqueueSharedGoalFieldsForActiveAgents(OrderedAgentIds);
                _perf.SharedGoalActiveEnqueueTicks += Stopwatch.GetTimestamp() - phaseTicks;

                phaseTicks = Stopwatch.GetTimestamp();
                PruneInactivePendingSharedGoalFieldBuildJobs(OrderedAgentIds);
                _perf.SharedGoalPruneTicks += Stopwatch.GetTimestamp() - phaseTicks;

                phaseTicks = Stopwatch.GetTimestamp();
                EnqueueFlowTileBuildsForActiveAgents(OrderedAgentIds);
                _perf.FlowTileActiveEnqueueTicks += Stopwatch.GetTimestamp() - phaseTicks;

                phaseTicks = Stopwatch.GetTimestamp();
                PruneInactivePendingFlowTileBuildJobs(OrderedAgentIds);
                _perf.FlowTilePruneTicks += Stopwatch.GetTimestamp() - phaseTicks;

                phaseTicks = Stopwatch.GetTimestamp();
                RefreshFlowTileReferenceCounts();
                TrimTileCache();
                _perf.FlowTileReferenceTicks += Stopwatch.GetTimestamp() - phaseTicks;
            }

            int remainingDeterministicCommits = Config.DeterministicFlowTileCommitQuota;
            for (int offset = 0; offset < worldCount && remainingDeterministicCommits > 0; offset++)
            {
                int worldIndex = (startIndex + offset) % worldCount;
                ActivateFlowBuildQueueWorld(FlowBuildQueueWorldScratch[worldIndex]);
                remainingDeterministicCommits -= CommitPendingDeterministicFlowTilePayloads(remainingDeterministicCommits);
            }

            BeginNavigationWorkBudget(Config.SharedGoalBuildOperationQuota);
            try
            {
                for (int offset = 0; offset < worldCount; offset++)
                {
                    int worldIndex = (startIndex + offset) % worldCount;
                    ActivateFlowBuildQueueWorld(FlowBuildQueueWorldScratch[worldIndex]);

                    long phaseTicks = Stopwatch.GetTimestamp();
                    ProcessSharedGoalFieldBuildQueue(deadlineTicks, forceComplete: false, requiredKey: null);
                    _perf.SharedGoalProcessTicks += Stopwatch.GetTimestamp() - phaseTicks;
                    if (IsNavigationWorkBudgetExhausted())
                        break;
                }
            }
            finally
            {
                EndNavigationWorkBudget();
            }

            if (worldCount > 0)
                _flowBuildQueueWorldStartIndex = (startIndex + 1) % worldCount;

            if (!s_NavigationDistancePrewarmCompleted
                && NavigationDistancePrewarmRequests.Count > 0)
            {
                s_NavigationDistancePrewarmCompletionMayHaveChanged = false;
                RefreshNavigationDistancePrewarmCompletion();
            }
        }
        finally
        {
            _world = previousWorld;
            _activeWorldState = previousActiveWorldState;
            _perf.FlowTileQueueTicks += Stopwatch.GetTimestamp() - queueStartTicks;
        }
    }

    private static bool CanProcessFlowTileBuildQueue()
    {
        if (WorldStates.Count == 0)
            return false;

        foreach (WorldRuntimeState state in WorldStates.Values)
        {
            if (state == null)
                throw new InvalidOperationException("CanProcessFlowTileBuildQueue failed: world state is null.");
            if (state.IsDirty || state.BuildJob != null)
                return false;
            if (state.World == null)
                throw new InvalidOperationException($"CanProcessFlowTileBuildQueue failed: ready world is null agentType={state.AgentTypeId}.");
            if (state.World.AgentTypeId != state.AgentTypeId)
                throw new InvalidOperationException($"CanProcessFlowTileBuildQueue failed: world agent type mismatch state={state.AgentTypeId} world={state.World.AgentTypeId}.");
        }

        return true;
    }

    private static void ActivateFlowBuildQueueWorld(WorldRuntimeState state)
    {
        if (state == null || state.World == null)
            throw new InvalidOperationException("ActivateFlowBuildQueueWorld failed: state or world is null.");
        if (state.IsDirty || state.BuildJob != null)
            throw new InvalidOperationException($"ActivateFlowBuildQueueWorld failed: world is not ready agentType={state.AgentTypeId}.");

        _activeWorldState = state;
        _world = state.World;
    }

    private static bool IsAgentInActiveFlowBuildQueueWorld(AgentRuntimeData agent)
    {
        if (agent == null)
            throw new InvalidOperationException("IsAgentInActiveFlowBuildQueueWorld failed: agent is null.");
        if (_activeWorldState == null || _world == null)
            throw new InvalidOperationException("IsAgentInActiveFlowBuildQueueWorld failed: active world is null.");

        return ResolvePreferredAgentTypeId(agent.AgentTypeId) == _activeWorldState.AgentTypeId
               && _world.AgentTypeId == _activeWorldState.AgentTypeId;
    }

    private static bool IsAgentInCurrentNavigationWorld(AgentRuntimeData agent)
    {
        if (agent == null)
            throw new InvalidOperationException("IsAgentInCurrentNavigationWorld failed: agent is null.");
        if (_world == null)
            throw new InvalidOperationException("IsAgentInCurrentNavigationWorld failed: world is null.");

        return ResolvePreferredAgentTypeId(agent.AgentTypeId) == _world.AgentTypeId;
    }

    private static bool IsAgentPathInCurrentNavigationWorld(AgentRuntimeData agent)
    {
        return IsAgentInCurrentNavigationWorld(agent)
               && agent.NavState.PathHandle != null
               && agent.NavState.PathHandle.WorldVersion == _world.Version;
    }

    private static void EnqueueFlowTileBuildsForActiveAgents(IList<int> orderedAgentIds)
    {
        if (orderedAgentIds == null)
            throw new ArgumentNullException(nameof(orderedAgentIds));

        for (int i = 0; i < orderedAgentIds.Count; i++)
        {
            if (!Agents.TryGetValue(orderedAgentIds[i], out AgentRuntimeData agent) || agent == null)
                throw new InvalidOperationException($"EnqueueFlowTileBuildsForActiveAgents failed: ordered agent is missing id={orderedAgentIds[i]}.");
            if (!IsAgentInActiveFlowBuildQueueWorld(agent))
                continue;

            PathHandle handle = agent.NavState.PathHandle;
            if (handle == null || handle.WorldVersion != _world.Version || handle.SectorIds == null || handle.SectorIds.Length == 0)
                continue;
            if (PathReferencesMissingPortal(handle))
                continue;

            int sectorPathIndex = Mathf.Clamp(handle.CurrentSectorIndex, 0, handle.SectorIds.Length - 1);
            EnqueueActiveFlowTileBuilds(handle, sectorPathIndex, handle.GoalX, handle.GoalY, agent.AgentTypeId);
        }
    }

    private static void PruneInactivePendingFlowTileBuildJobs(IList<int> orderedAgentIds)
    {
        if (FlowTileBuildQueue.Count == 0)
            return;

        BuildActiveFlowTileBuildKeySet(orderedAgentIds);
        LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First;
        while (node != null)
        {
            LinkedListNode<FlowTileBuildJob> next = node.Next;
            FlowTileBuildJob job = node.Value;
            FlowTileCacheKey key = job.BuildKey.CacheKey;
            if (key.WorldVersion == _world.Version && !ActiveFlowTileBuildKeys.Contains(key))
            {
                FlowTileBuildQueue.Remove(node);
                PendingFlowTileBuildJobs.Remove(key);
                ReleasePendingFlowTileBuildJobPayloads(job);
                _perf.FlowTileQueuePruned++;
            }

            node = next;
        }
    }

    private static void BuildActiveFlowTileBuildKeySet(IList<int> orderedAgentIds)
    {
        if (orderedAgentIds == null)
            throw new ArgumentNullException(nameof(orderedAgentIds));

        ActiveFlowTileBuildKeys.Clear();
        if (_world == null)
            return;

        for (int i = 0; i < orderedAgentIds.Count; i++)
        {
            if (!Agents.TryGetValue(orderedAgentIds[i], out AgentRuntimeData agent) || agent == null)
                throw new InvalidOperationException($"BuildActiveFlowTileBuildKeySet failed: ordered agent is missing id={orderedAgentIds[i]}.");
            if (!IsAgentInActiveFlowBuildQueueWorld(agent))
                continue;

            PathHandle handle = agent.NavState.PathHandle;
            if (handle == null
                || handle.WorldVersion != _world.Version
                || handle.SectorIds == null
                || handle.SectorIds.Length == 0
                || PathReferencesMissingPortal(handle))
            {
                continue;
            }

            int startIndex = Mathf.Clamp(handle.CurrentSectorIndex, 0, handle.SectorIds.Length - 1);
            AddActiveFlowTileBuildKeys(handle, startIndex, handle.GoalX, handle.GoalY, agent.AgentTypeId);
        }
    }

    private static void EnqueueSharedGoalFieldsForActiveAgents(IList<int> orderedAgentIds)
    {
        BuildActiveSharedGoalFieldBuildKeySet(orderedAgentIds);
        ActiveSharedGoalFieldKeyOrderScratch.Clear();
        ActiveSharedGoalFieldKeyOrderScratch.AddRange(ActiveSharedGoalFieldBuildKeys);
        ActiveSharedGoalFieldKeyOrderScratch.Sort(SharedGoalFieldKeyComparison);
        for (int i = 0; i < ActiveSharedGoalFieldKeyOrderScratch.Count; i++)
        {
            SharedGoalFieldKey key = ActiveSharedGoalFieldKeyOrderScratch[i];
            if (ActiveSharedGoalFieldDemandStartCells.TryGetValue(key, out Dictionary<int, int> demandStartCells))
                EnqueueSharedGoalFieldBuild(key, true, demandStartCells);
            else if (ActiveSharedGoalFieldDemandStartSectors.TryGetValue(key, out HashSet<int> demandStartSectors))
                EnqueueSharedGoalFieldBuild(key, true, demandStartSectors);
            else
                EnqueueSharedGoalFieldBuild(key, prependToFront: true);
        }
    }

    private static void BuildActiveSharedGoalFieldBuildKeySet(IList<int> orderedAgentIds)
    {
        if (orderedAgentIds == null)
            throw new ArgumentNullException(nameof(orderedAgentIds));

        ActiveSharedGoalFieldBuildKeys.Clear();
        ActiveSharedGoalFieldDemandStartSectors.Clear();
        ActiveSharedGoalFieldDemandStartCells.Clear();
        if (_world == null)
            return;

        for (int i = 0; i < orderedAgentIds.Count; i++)
        {
            if (!Agents.TryGetValue(orderedAgentIds[i], out AgentRuntimeData agent) || agent == null)
                throw new InvalidOperationException($"BuildActiveSharedGoalFieldBuildKeySet failed: ordered agent is missing id={orderedAgentIds[i]}.");
            if (!IsAgentInActiveFlowBuildQueueWorld(agent))
                continue;

            if (agent.NavState.StableGoalX < 0 || agent.NavState.StableGoalY < 0)
                continue;
            if (agent.NavState.StableGoalTargetId != int.MinValue)
            {
                AddActiveMovingTargetSharedGoalFieldBuildKeys(agent);
                continue;
            }
            if (agent.NavState.CurrentSectorId < 0)
                continue;
            if (!_world.TryGetSectorId(agent.NavState.StableGoalX, agent.NavState.StableGoalY, out int goalSectorId))
                continue;
            if (goalSectorId == agent.NavState.CurrentSectorId)
                continue;

            AddActiveSharedGoalFieldBuildKey(CreateSharedGoalFieldKey(
                goalSectorId,
                agent.NavState.StableGoalX,
                agent.NavState.StableGoalY,
                ResolvePreferredAgentTypeId(agent.AgentTypeId)), agent.NavState.CurrentSectorId, agent.NavState.CurrentCell.x, agent.NavState.CurrentCell.y);
        }

        AddNavigationDistancePrewarmBuildKeysForActiveWorld();

    }

    private static void AddNavigationDistancePrewarmBuildKeysForActiveWorld()
    {
        if (_world == null)
            throw new InvalidOperationException("Navigation distance prewarm requires an active world.");

        for (int i = 0; i < NavigationDistancePrewarmRequests.Count; i++)
        {
            NavigationDistancePrewarmRequest request = NavigationDistancePrewarmRequests[i];
            if (request.AgentTypeId != _world.AgentTypeId)
                continue;
            if (request.ResolvedWorldVersion != _world.Version
                || request.ResolvedTopologyVersion != _navigationTopologyVersion)
            {
                if (!TryResolveReachableNavigationQueryCellsFixed(
                        _world,
                        request.From,
                        request.RawGoal,
                        out request.StartX,
                        out request.StartY,
                        out request.GoalX,
                        out request.GoalY,
                        out _,
                        out string failureReason)
                    || !_world.TryGetSectorId(request.StartX, request.StartY, out request.StartSectorId)
                    || !_world.TryGetSectorId(request.GoalX, request.GoalY, out request.GoalSectorId))
                {
                    throw new InvalidOperationException(
                        $"Navigation distance prewarm cannot resolve route agentType={request.AgentTypeId} " +
                        $"fromRaw=({request.From.x.RawValue},{request.From.y.RawValue}) " +
                        $"goalRaw=({request.RawGoal.x.RawValue},{request.RawGoal.y.RawValue}) reason={failureReason}.");
                }

                request.ResolvedWorldVersion = _world.Version;
                request.ResolvedTopologyVersion = _navigationTopologyVersion;
                s_NavigationDistancePrewarmCompletionMayHaveChanged = true;
            }

            AddActiveSharedGoalFieldBuildKey(
                CreateSharedGoalFieldKey(request.GoalSectorId, request.GoalX, request.GoalY, request.AgentTypeId),
                request.StartSectorId,
                request.StartX,
                request.StartY);
        }
    }

    private static int CompareNavigationDistancePrewarmRequests(
        NavigationDistancePrewarmRequest left,
        NavigationDistancePrewarmRequest right)
    {
        int order = left.AgentTypeId.CompareTo(right.AgentTypeId);
        if (order != 0) return order;
        order = left.From.x.RawValue.CompareTo(right.From.x.RawValue);
        if (order != 0) return order;
        order = left.From.y.RawValue.CompareTo(right.From.y.RawValue);
        if (order != 0) return order;
        order = left.RawGoal.x.RawValue.CompareTo(right.RawGoal.x.RawValue);
        return order != 0 ? order : left.RawGoal.y.RawValue.CompareTo(right.RawGoal.y.RawValue);
    }

    private static void RefreshNavigationDistancePrewarmCompletion()
    {
        if (s_NavigationDistancePrewarmCompleted || NavigationDistancePrewarmRequests.Count == 0)
            return;

        for (int i = 0; i < NavigationDistancePrewarmRequests.Count; i++)
        {
            NavigationDistancePrewarmRequest request = NavigationDistancePrewarmRequests[i];
            if (!WorldStates.TryGetValue(request.AgentTypeId, out WorldRuntimeState state)
                || state == null
                || state.IsDirty
                || state.BuildJob != null
                || state.World == null
                || request.ResolvedWorldVersion != state.World.Version
                || request.ResolvedTopologyVersion != _navigationTopologyVersion)
            {
                return;
            }

            NavigationWorld world = state.World;
            if (request.StartX == request.GoalX && request.StartY == request.GoalY)
                continue;
            if (request.StartSectorId == request.GoalSectorId)
                continue;

            var key = new SharedGoalFieldKey(
                world.Version,
                request.AgentTypeId,
                request.GoalSectorId,
                world.GetIndex(request.GoalX, request.GoalY),
                world.Sectors[request.GoalSectorId].DirtyVersion);
            if (!SharedGoalFields.TryGetValue(key, out SharedGoalField field) || field == null)
            {
                if (PendingSharedGoalFieldBuildJobs.Contains(key))
                    return;
                throw new InvalidOperationException(
                    $"Navigation distance prewarm failed to build a route agentType={request.AgentTypeId} " +
                    $"start=({request.StartX},{request.StartY}) goal=({request.GoalX},{request.GoalY}).");
            }

            int startCellIndex = world.GetIndex(request.StartX, request.StartY);
            if (!IsSharedGoalFieldDemandCovered(
                    world,
                    field,
                    request.StartSectorId,
                    startCellIndex))
                return;
        }

        for (int i = 0; i < NavigationDistancePrewarmRequests.Count; i++)
        {
            NavigationDistancePrewarmRequest request = NavigationDistancePrewarmRequests[i];
            if (!TryEstimatePrewarmedNavigationDistanceToReachableGoalFixed(
                    request.From,
                    request.RawGoal,
                    request.AgentTypeId,
                    out _,
                    out _,
                    out string failureReason))
            {
                throw new InvalidOperationException(
                    $"Navigation distance prewarm completed without a queryable route agentType={request.AgentTypeId} " +
                    $"fromRaw=({request.From.x.RawValue},{request.From.y.RawValue}) " +
                    $"goalRaw=({request.RawGoal.x.RawValue},{request.RawGoal.y.RawValue}) reason={failureReason}.");
            }
        }

        s_NavigationDistancePrewarmCompleted = true;
        EventHandler<NavigationDistancePrewarmCompletedEventArgs> handler = NavigationDistancePrewarmCompleted;
        if (handler == null)
            return;

        NavigationDistancePrewarmCompletedEventArgs eventArgs =
            ReferencePool.Acquire<NavigationDistancePrewarmCompletedEventArgs>();
        eventArgs.RequestCount = NavigationDistancePrewarmRequests.Count;
        try
        {
            handler(null, eventArgs);
        }
        finally
        {
            ReferencePool.Release(eventArgs);
        }
    }

    private static void AddActiveMovingTargetSharedGoalFieldBuildKeys(AgentRuntimeData agent)
    {
        if (agent == null)
            throw new InvalidOperationException("AddActiveMovingTargetSharedGoalFieldBuildKeys failed: agent is null.");
        if (agent.NavState.CurrentSectorId < 0)
            return;

        int islandId = ResolveIslandIdForDiagnostics(_world, agent.NavState.CurrentCell.x, agent.NavState.CurrentCell.y);
        if (islandId <= 0)
            return;

        int sharedAgentTypeId = ResolvePreferredAgentTypeId(agent.AgentTypeId);
        MovingTargetAnchorKey anchorKey = new MovingTargetAnchorKey(agent.NavState.StableGoalTargetId, sharedAgentTypeId, islandId);
        if (!MovingTargetAnchors.TryGetValue(anchorKey, out MovingTargetAnchor anchor) || anchor == null)
            throw new InvalidOperationException($"AddActiveMovingTargetSharedGoalFieldBuildKeys failed: missing anchor target={agent.NavState.StableGoalTargetId} agentType={sharedAgentTypeId} island={islandId} agent={agent.CharacterKey} id={agent.Id}.");

        AddActiveMovingTargetSharedGoalFieldBuildKey(
            anchor.ActiveGoalSectorId,
            anchor.ActiveGoalX,
            anchor.ActiveGoalY,
            anchor.ActiveWorldVersion,
            sharedAgentTypeId,
            agent.NavState.CurrentSectorId,
            agent.NavState.CurrentCell.x,
            agent.NavState.CurrentCell.y);

        AddActiveMovingTargetSharedGoalFieldBuildKey(
            anchor.PendingGoalSectorId,
            anchor.PendingGoalX,
            anchor.PendingGoalY,
            anchor.PendingWorldVersion,
            sharedAgentTypeId,
            agent.NavState.CurrentSectorId,
            agent.NavState.CurrentCell.x,
            agent.NavState.CurrentCell.y);
    }

    private static void AddActiveMovingTargetSharedGoalFieldBuildKey(
        int goalSectorId,
        int goalX,
        int goalY,
        int worldVersion,
        int sharedAgentTypeId,
        int demandStartSectorId,
        int demandStartX,
        int demandStartY)
    {
        if (worldVersion != _world.Version || goalX < 0 || goalY < 0 || goalSectorId < 0)
            return;
        if (goalSectorId == demandStartSectorId)
            return;

        AddActiveSharedGoalFieldBuildKey(
            CreateSharedGoalFieldKey(goalSectorId, goalX, goalY, sharedAgentTypeId),
            demandStartSectorId,
            demandStartX,
            demandStartY);
    }

    private static void AddActiveSharedGoalFieldBuildKey(SharedGoalFieldKey key, int demandStartSectorId)
    {
        ActiveSharedGoalFieldBuildKeys.Add(key);
        if (demandStartSectorId < 0)
            return;

        if (!ActiveSharedGoalFieldDemandStartSectors.TryGetValue(key, out HashSet<int> demandStartSectors))
        {
            demandStartSectors = new HashSet<int>();
            ActiveSharedGoalFieldDemandStartSectors.Add(key, demandStartSectors);
        }

        demandStartSectors.Add(demandStartSectorId);
    }

    private static void AddActiveSharedGoalFieldBuildKey(SharedGoalFieldKey key, int demandStartSectorId, int demandStartX, int demandStartY)
    {
        AddActiveSharedGoalFieldBuildKey(key, demandStartSectorId);
        if (demandStartSectorId < 0
            || demandStartX < 0
            || demandStartX >= _world.Width
            || demandStartY < 0
            || demandStartY >= _world.Height)
        {
            return;
        }

        if (!ActiveSharedGoalFieldDemandStartCells.TryGetValue(key, out Dictionary<int, int> demandStartCells))
        {
            demandStartCells = new Dictionary<int, int>();
            ActiveSharedGoalFieldDemandStartCells.Add(key, demandStartCells);
        }

        demandStartCells[_world.GetIndex(demandStartX, demandStartY)] = demandStartSectorId;
    }

    private static void PruneInactivePendingSharedGoalFieldBuildJobs(IList<int> orderedAgentIds)
    {
        if (SharedGoalFieldBuildQueue.Count == 0)
            return;

        if (ActiveSharedGoalFieldBuildKeys.Count == 0)
            BuildActiveSharedGoalFieldBuildKeySet(orderedAgentIds);

        LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First;
        while (node != null)
        {
            LinkedListNode<SharedGoalFieldBuildJob> next = node.Next;
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || (job.Key.WorldVersion == _world.Version && !ActiveSharedGoalFieldBuildKeys.Contains(job.Key)))
            {
                SharedGoalFieldBuildQueue.Remove(node);
                if (job != null)
                    PendingSharedGoalFieldBuildJobs.Remove(job.Key);
            }

            node = next;
        }
    }

    private static void ProcessSharedGoalFieldBuildQueue(long deadlineTicks, bool forceComplete, SharedGoalFieldKey? requiredKey)
    {
        if (_world == null)
            throw new InvalidOperationException("ProcessSharedGoalFieldBuildQueue failed: world is null.");
        if (requiredKey.HasValue && requiredKey.Value.WorldVersion != _world.Version)
            throw new InvalidOperationException($"ProcessSharedGoalFieldBuildQueue failed: required key world mismatch required={requiredKey.Value.WorldVersion} active={_world.Version}.");

        int guard = 0;
        while (true)
        {
            if (!forceComplete && IsDeadlineExpired(deadlineTicks))
                return;

            LinkedListNode<SharedGoalFieldBuildJob> jobNode = FindSharedGoalFieldBuildJobForActiveWorld();
            if (jobNode == null)
                return;

            SharedGoalFieldBuildJob job = jobNode.Value;
            SharedGoalFieldBuildQueue.Remove(jobNode);
            PendingSharedGoalFieldBuildJobs.Remove(job.Key);

            if (SharedGoalFields.ContainsKey(job.Key))
            {
                if (requiredKey.HasValue && SharedGoalFields.ContainsKey(requiredKey.Value))
                    return;
                continue;
            }

            if (IsSharedGoalFieldBuildJobStale(job))
            {
                if (requiredKey.HasValue && SharedGoalFields.ContainsKey(requiredKey.Value))
                    return;
                continue;
            }

            if (!AdvanceSharedGoalFieldBuildJob(job, deadlineTicks, forceComplete))
            {
                SharedGoalFieldBuildQueue.AddFirst(job);
                PendingSharedGoalFieldBuildJobs.Add(job.Key);
                return;
            }

            if (requiredKey.HasValue && SharedGoalFields.ContainsKey(requiredKey.Value))
                return;
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;

            guard++;
            if (guard > Config.FlowTileCacheLimit * 4 + 1024)
                throw new InvalidOperationException("ProcessSharedGoalFieldBuildQueue failed: queue processing exceeded guard.");
        }
    }

    private static bool IsSharedGoalFieldBuildJobStale(SharedGoalFieldBuildJob job)
    {
        if (job == null || _world == null)
            return true;
        if (job.GoalSectorId < 0 || job.GoalSectorId >= _world.Sectors.Length)
            return true;

        SharedGoalFieldKey expectedKey = CreateSharedGoalFieldKey(job.GoalSectorId, job.GoalX, job.GoalY, job.AgentTypeId);
        return !expectedKey.Equals(job.Key);
    }

    private static LinkedListNode<SharedGoalFieldBuildJob> FindSharedGoalFieldBuildJobForActiveWorld()
    {
        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job != null && job.Key.WorldVersion == _world.Version)
                return node;
        }

        return null;
    }

    private static int CommitPendingDeterministicFlowTilePayloads(int maxCount)
    {
        if (maxCount <= 0)
            throw new ArgumentOutOfRangeException(nameof(maxCount), maxCount, "Deterministic flow tile commit quota must be positive.");
        if (_world == null)
            throw new InvalidOperationException("CommitPendingDeterministicFlowTilePayloads failed: world is null.");

        int committedCount = 0;
        LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First;
        while (node != null && committedCount < maxCount)
        {
            LinkedListNode<FlowTileBuildJob> next = node.Next;
            FlowTileBuildJob job = node.Value;
            if (job == null)
                throw new InvalidOperationException("CommitPendingDeterministicFlowTilePayloads encountered a null job.");
            if (job.BuildKey.CacheKey.WorldVersion != _world.Version)
            {
                node = next;
                continue;
            }
            if (IsFlowTileBuildJobStale(job))
            {
                node = next;
                continue;
            }

            CommitDeterministicFlowTilePayload(job);
            FlowTileBuildQueue.Remove(node);
            if (!PendingFlowTileBuildJobs.Remove(job.BuildKey.CacheKey))
                throw new InvalidOperationException($"CommitPendingDeterministicFlowTilePayloads failed: committed job was absent from pending set key={FormatTileKey(job.BuildKey.CacheKey)}.");
            committedCount++;
            node = next;
        }

        if (committedCount > 0)
        {
            RefreshFlowTileReferenceCounts();
            TrimTileCache();
        }

        return committedCount;
    }

    private static int CommitRequiredDeterministicFlowTilePayload(FlowTileCacheKey requiredKey)
    {
        if (_world == null)
            throw new InvalidOperationException("CommitRequiredDeterministicFlowTilePayload failed: world is null.");
        if (requiredKey.WorldVersion != _world.Version)
        {
            throw new InvalidOperationException(
                $"CommitRequiredDeterministicFlowTilePayload failed: required world mismatch required={requiredKey.WorldVersion}, active={_world.Version}.");
        }
        if (DeterministicFlowTileCache.ContainsKey(requiredKey))
            return 0;

        LinkedListNode<FlowTileBuildJob> requiredNode = FindPendingFlowTileBuildJob(requiredKey);
        if (requiredNode == null)
        {
            throw new InvalidOperationException(
                $"CommitRequiredDeterministicFlowTilePayload failed: required job is absent key={FormatTileKey(requiredKey)}.");
        }

        FlowTileBuildJob requiredJob = requiredNode.Value;
        if (IsFlowTileBuildJobStale(requiredJob))
        {
            throw new InvalidOperationException(
                $"CommitRequiredDeterministicFlowTilePayload failed: required job is stale key={FormatTileKey(requiredKey)}.");
        }

        int committedCount = 0;
        PathHandle handle = requiredJob.HandleSnapshot;
        int sectorPathIndex = requiredJob.BuildKey.SectorPathIndex;
        if (requiredKey.GoalKind == TileGoalKind.Portal
            && sectorPathIndex + 1 == handle.SectorIds.Length - 1)
        {
            FlowTileCacheKey downstreamFinalKey = CreateTileCacheKeyForPathSegment(
                handle,
                sectorPathIndex + 1,
                requiredJob.BuildKey.GoalX,
                requiredJob.BuildKey.GoalY,
                requiredJob.BuildKey.AgentTypeId,
                out TileGoalKind downstreamGoalKind,
                out _);
            if (downstreamGoalKind != TileGoalKind.FinalGoal)
            {
                throw new InvalidOperationException(
                    $"CommitRequiredDeterministicFlowTilePayload failed: required downstream dependency is not final key={FormatTileKey(downstreamFinalKey)}.");
            }

            committedCount += CommitRequiredDeterministicFlowTilePayload(downstreamFinalKey);
            requiredNode = FindPendingFlowTileBuildJob(requiredKey);
            if (requiredNode == null)
            {
                throw new InvalidOperationException(
                    $"CommitRequiredDeterministicFlowTilePayload failed: required job disappeared after dependency commit key={FormatTileKey(requiredKey)}.");
            }
            requiredJob = requiredNode.Value;
        }

        CommitDeterministicFlowTilePayload(requiredJob);
        FlowTileBuildQueue.Remove(requiredNode);
        if (!PendingFlowTileBuildJobs.Remove(requiredKey))
        {
            throw new InvalidOperationException(
                $"CommitRequiredDeterministicFlowTilePayload failed: committed job was absent from pending set key={FormatTileKey(requiredKey)}.");
        }

        return committedCount + 1;
    }

    private static LinkedListNode<FlowTileBuildJob> FindPendingFlowTileBuildJob(FlowTileCacheKey key)
    {
        for (LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First; node != null; node = node.Next)
        {
            FlowTileBuildJob job = node.Value;
            if (job == null)
                throw new InvalidOperationException("FindPendingFlowTileBuildJob encountered a null job.");
            if (job.BuildKey.CacheKey.Equals(key))
                return node;
        }

        return null;
    }

    private static void CommitDeterministicFlowTilePayload(FlowTileBuildJob job)
    {
        if (job == null)
            throw new ArgumentNullException(nameof(job));
        FlowTileCacheKey key = job.BuildKey.CacheKey;
        SectorData sector = _world.Sectors[key.SectorId];
        Vector2Int[] goalCells = ResolveGoalCells(sector, key, job.BuildKey.GoalX, job.BuildKey.GoalY);
        if (goalCells == null || goalCells.Length == 0)
            throw new InvalidOperationException($"CommitDeterministicFlowTilePayload failed: tile has no goal cells key={FormatTileKey(key)}.");

        var tile = new FlowTileCacheEntry
        {
            Key = key,
            StartX = sector.StartX,
            StartY = sector.StartY,
            Width = sector.Width,
            Height = sector.Height,
            GoalCells = goalCells,
            UsesClearFlowDescriptor = sector.IsClearFlowTile
        };
        BuildDeterministicFlowDirections(tile, job);
        BuildFlowTileDiagnosticShadow(tile);
        tile.LastUsedFrame = GetFrameCount();
        SetDeterministicFlowTileCacheEntry(key, tile);
        FlowTileCache.Add(key, tile);
    }

    private static void BuildFlowTileDiagnosticShadow(FlowTileCacheEntry tile)
    {
        if (tile == null)
            throw new ArgumentNullException(nameof(tile));
        int count = tile.Width * tile.Height;
        if (tile.DeterministicIntegrationCosts == null || tile.DeterministicIntegrationCosts.Length != count)
            throw new InvalidOperationException($"BuildFlowTileDiagnosticShadow failed: invalid deterministic integration payload key={FormatTileKey(tile.Key)}.");
        if (tile.DeterministicFlowDirectionIndices == null || tile.DeterministicFlowDirectionIndices.Length != count)
            throw new InvalidOperationException($"BuildFlowTileDiagnosticShadow failed: invalid deterministic direction payload key={FormatTileKey(tile.Key)}.");

        tile.FlowFieldValues = new byte[count];
        for (int localIndex = 0; localIndex < count; localIndex++)
        {
            int worldX = tile.StartX + localIndex % tile.Width;
            int worldY = tile.StartY + localIndex / tile.Width;
            if (_world.IsWalkable(worldX, worldY))
                tile.FlowFieldValues[localIndex] |= FlowPathableFlag;
            if (tile.DeterministicIntegrationCosts[localIndex] != int.MaxValue)
                tile.FlowFieldValues[localIndex] |= FlowReachableFlag;
            tile.FlowFieldValues[localIndex] |= (byte)(tile.DeterministicFlowDirectionIndices[localIndex] & FlowDirectionMask);
        }
    }

    private static bool IsFlowTileBuildJobStale(FlowTileBuildJob job)
    {
        if (job == null || job.HandleSnapshot == null || _world == null)
            return true;
        if (job.HandleSnapshot.WorldVersion != _world.Version)
            return true;
        if (job.HandleSnapshot.SectorIds == null
            || job.BuildKey.SectorPathIndex < 0
            || job.BuildKey.SectorPathIndex >= job.HandleSnapshot.SectorIds.Length)
        {
            return true;
        }
        if (PathReferencesMissingPortal(job.HandleSnapshot))
            return true;

        FlowTileCacheKey expectedKey = CreateTileCacheKeyForPathSegment(
            job.HandleSnapshot,
            job.BuildKey.SectorPathIndex,
            job.BuildKey.GoalX,
            job.BuildKey.GoalY,
            job.BuildKey.AgentTypeId,
            out _,
            out _);
        return !expectedKey.Equals(job.BuildKey.CacheKey);
    }

    private static void BuildDeterministicFlowDirections(FlowTileCacheEntry tile, FlowTileBuildJob job)
    {
        if (tile == null)
            throw new InvalidOperationException("BuildDeterministicFlowDirections failed: tile is null.");
        if (_world == null)
            throw new InvalidOperationException("BuildDeterministicFlowDirections failed: world is null.");
        if (tile.GoalCells == null || tile.GoalCells.Length == 0)
            throw new InvalidOperationException($"BuildDeterministicFlowDirections failed: tile has no goals key={FormatTileKey(tile.Key)}.");

        int count = tile.Width * tile.Height;
        int[] costs = new int[count];
        byte[] directions = new byte[count];
        for (int i = 0; i < count; i++)
            costs[i] = int.MaxValue;

        int[] goalSeedCosts = ResolveDeterministicFlowGoalSeedCosts(
            tile,
            job,
            out byte[] portalHandoffDirectionIndices);
        var open = new SortedSet<DeterministicFlowNode>();
        for (int i = 0; i < tile.GoalCells.Length; i++)
        {
            Vector2Int goal = tile.GoalCells[i];
            if (!IsInsideSector(tile, goal.x, goal.y) || !_world.IsWalkable(goal.x, goal.y))
                continue;
            int seedCost = goalSeedCosts[i];
            if (seedCost == int.MaxValue)
                continue;
            int index = tile.GetLocalIndex(goal.x, goal.y);
            costs[index] = seedCost;
            open.Add(new DeterministicFlowNode(seedCost, index));
        }
        if (open.Count == 0)
            throw new InvalidOperationException($"BuildDeterministicFlowDirections failed: tile has no walkable goals key={FormatTileKey(tile.Key)}.");

        while (open.Count > 0)
        {
            DeterministicFlowNode node = open.Min;
            open.Remove(node);
            if (node.Cost != costs[node.Index])
                continue;

            int worldX = tile.StartX + node.Index % tile.Width;
            int worldY = tile.StartY + node.Index / tile.Width;
            for (int directionIndex = 0; directionIndex < CardinalOffsetX.Length; directionIndex++)
            {
                int nextX = worldX + CardinalOffsetX[directionIndex];
                int nextY = worldY + CardinalOffsetY[directionIndex];
                if (!IsInsideSector(tile, nextX, nextY)
                    || !CanTraverseNeighborCells(_world, nextX, nextY, worldX, worldY))
                {
                    continue;
                }

                int candidateCost = ResolveDeterministicEikonalIntegrationCost(tile, costs, nextX, nextY);
                int nextIndex = tile.GetLocalIndex(nextX, nextY);
                if (candidateCost >= costs[nextIndex])
                    continue;

                costs[nextIndex] = candidateCost;
                open.Add(new DeterministicFlowNode(candidateCost, nextIndex));
            }
        }

        for (int localIndex = 0; localIndex < count; localIndex++)
        {
            if (costs[localIndex] == int.MaxValue)
                continue;
            int worldX = tile.StartX + localIndex % tile.Width;
            int worldY = tile.StartY + localIndex / tile.Width;
            int goalCellIndex = IndexOfGoalCell(tile.GoalCells, worldX, worldY);
            if (goalCellIndex >= 0)
            {
                if (tile.Key.GoalKind == TileGoalKind.Portal)
                    directions[localIndex] = portalHandoffDirectionIndices[goalCellIndex];
                continue;
            }

            int bestCost = costs[localIndex];
            int bestDirectionIndex = -1;
            for (int directionIndex = 0; directionIndex < NeighborOffsetX.Length; directionIndex++)
            {
                int nextX = worldX + NeighborOffsetX[directionIndex];
                int nextY = worldY + NeighborOffsetY[directionIndex];
                if (!IsInsideSector(tile, nextX, nextY)
                    || !CanTraverseNeighborCells(_world, worldX, worldY, nextX, nextY))
                {
                    continue;
                }

                int nextCost = costs[tile.GetLocalIndex(nextX, nextY)];
                if (nextCost >= bestCost)
                    continue;
                bestCost = nextCost;
                bestDirectionIndex = directionIndex;
            }

            if (bestDirectionIndex >= 0)
                directions[localIndex] = checked((byte)(bestDirectionIndex + 1));
        }

        tile.DeterministicIntegrationCosts = costs;
        tile.DeterministicFlowDirectionIndices = directions;
        tile.DeterministicPortalTargetSlotIndices = tile.Key.GoalKind == TileGoalKind.Portal
            ? BuildDeterministicPortalTargetSlotIndices(tile, costs, directions)
            : null;
    }

    private static int[] ResolveDeterministicFlowGoalSeedCosts(
        FlowTileCacheEntry tile,
        FlowTileBuildJob job,
        out byte[] portalHandoffDirectionIndices)
    {
        var seedCosts = new int[tile.GoalCells.Length];
        if (tile.Key.GoalKind == TileGoalKind.FinalGoal)
        {
            portalHandoffDirectionIndices = null;
            return seedCosts;
        }
        portalHandoffDirectionIndices = new byte[tile.GoalCells.Length];
        for (int i = 0; i < seedCosts.Length; i++)
            seedCosts[i] = int.MaxValue;

        PathHandle handle = job?.HandleSnapshot;
        int sectorPathIndex = job?.BuildKey.SectorPathIndex ?? -1;
        if (handle?.SectorIds == null || handle.PortalIds == null)
            throw new InvalidOperationException($"ResolveDeterministicFlowGoalSeedCosts failed: portal tile has no path handle key={FormatTileKey(tile.Key)}.");
        if (sectorPathIndex < 0 || sectorPathIndex >= handle.SectorIds.Length - 1)
            throw new InvalidOperationException($"ResolveDeterministicFlowGoalSeedCosts failed: portal tile path index is invalid index={sectorPathIndex}, key={FormatTileKey(tile.Key)}.");

        PortalData portal = GetPortalById(_world, tile.Key.GoalId);
        int downstreamSectorId = handle.SectorIds[sectorPathIndex + 1];
        Vector2Int[] downstreamCells = GetPortalCellsForSector(portal, downstreamSectorId);
        if (tile.GoalCells.Length != downstreamCells.Length)
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicFlowGoalSeedCosts failed: portal side count mismatch current={tile.GoalCells.Length}, downstream={downstreamCells.Length}, key={FormatTileKey(tile.Key)}.");
        }

        bool downstreamIsFinalSector = sectorPathIndex + 1 == handle.SectorIds.Length - 1;
        FlowTileCacheEntry downstreamFinalTile = null;
        SectorPortalAccessEntry downstreamPortalAccess = null;
        SectorData downstreamSector = _world.Sectors[downstreamSectorId];
        if (downstreamIsFinalSector)
        {
            FlowTileCacheKey downstreamKey = CreateTileCacheKeyForPathSegment(
                handle,
                sectorPathIndex + 1,
                job.BuildKey.GoalX,
                job.BuildKey.GoalY,
                job.BuildKey.AgentTypeId,
                out TileGoalKind downstreamGoalKind,
                out _);
            if (downstreamGoalKind != TileGoalKind.FinalGoal
                || !DeterministicFlowTileCache.TryGetValue(downstreamKey, out downstreamFinalTile))
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowGoalSeedCosts failed: downstream final tile is not committed before adjacent portal tile downstream={FormatTileKey(downstreamKey)}, key={FormatTileKey(tile.Key)}.");
            }
            if (downstreamFinalTile.DeterministicIntegrationCosts == null
                || downstreamFinalTile.DeterministicFlowDirectionIndices == null)
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowGoalSeedCosts failed: downstream final tile payload is invalid downstream={FormatTileKey(downstreamKey)}, key={FormatTileKey(tile.Key)}.");
            }
        }
        else
        {
            int nextPortalId = handle.PortalIds[sectorPathIndex + 1];
            downstreamPortalAccess = GetPrebuiltSectorPortalAccess(
                downstreamSector,
                downstreamSectorId,
                nextPortalId);
        }

        for (int i = 0; i < downstreamCells.Length; i++)
        {
            Vector2Int downstreamCell = downstreamCells[i];
            int downstreamCost;
            byte downstreamDirectionIndex;
            if (downstreamIsFinalSector)
            {
                if (!IsInsideSector(downstreamFinalTile, downstreamCell.x, downstreamCell.y))
                    continue;
                int downstreamLocalIndex = downstreamFinalTile.GetLocalIndex(downstreamCell.x, downstreamCell.y);
                downstreamCost = downstreamFinalTile.DeterministicIntegrationCosts[downstreamLocalIndex];
                downstreamDirectionIndex = downstreamFinalTile.DeterministicFlowDirectionIndices[downstreamLocalIndex];
            }
            else
            {
                long portalAccessCost = ResolveDeterministicPortalAccessIntegrationCost(
                    _world,
                    downstreamSector,
                    downstreamPortalAccess,
                    downstreamCell.x,
                    downstreamCell.y);
                downstreamCost = ConvertPortalAccessCostToFlowCost(portalAccessCost);
                downstreamDirectionIndex = TryResolveLowestPortalAccessNeighbor(
                    downstreamSector,
                    downstreamPortalAccess,
                    downstreamCell.x,
                    downstreamCell.y,
                    portalAccessCost,
                    out int downstreamOffsetIndex,
                    out _)
                        ? checked((byte)(downstreamOffsetIndex + 1))
                        : (byte)0;
            }
            if (downstreamCost == int.MaxValue)
                continue;

            seedCosts[i] = downstreamCost > int.MaxValue - 1024
                ? int.MaxValue
                : downstreamCost + 1024;
            portalHandoffDirectionIndices[i] = ResolveDeterministicPortalHandoffDirectionIndex(
                portal,
                tile.GoalCells[i],
                downstreamCell,
                downstreamDirectionIndex);
        }

        return seedCosts;
    }

    private static int ResolveDeterministicEikonalIntegrationCost(
        FlowTileCacheEntry tile,
        int[] integrationCosts,
        int worldX,
        int worldY)
    {
        long horizontal = long.MaxValue;
        long vertical = long.MaxValue;
        for (int i = 0; i < CardinalOffsetX.Length; i++)
        {
            int neighborX = worldX + CardinalOffsetX[i];
            int neighborY = worldY + CardinalOffsetY[i];
            if (!IsInsideSector(tile, neighborX, neighborY)
                || !CanTraverseNeighborCells(_world, worldX, worldY, neighborX, neighborY))
            {
                continue;
            }

            int neighborCost = integrationCosts[tile.GetLocalIndex(neighborX, neighborY)];
            if (neighborCost == int.MaxValue)
                continue;
            if (neighborX != worldX)
                horizontal = Math.Min(horizontal, neighborCost);
            else
                vertical = Math.Min(vertical, neighborCost);
        }

        if (!TryGetCostFieldValue(_world, worldX, worldY, out byte cellCost)
            || cellCost == byte.MaxValue)
        {
            return int.MaxValue;
        }

        long stepCost = checked(1024L * Math.Max(1, (int)cellCost));
        return checked((int)ResolveDeterministicEikonalUpdate(
            horizontal,
            vertical,
            stepCost,
            int.MaxValue));
    }

    private static long ResolveDeterministicEikonalUpdate(
        long horizontal,
        long vertical,
        long stepCost,
        long unreachableCost)
    {
        if (stepCost <= 0L)
            throw new ArgumentOutOfRangeException(nameof(stepCost), stepCost, "Eikonal step cost must be positive.");
        if (unreachableCost <= 0L)
            throw new ArgumentOutOfRangeException(nameof(unreachableCost), unreachableCost, "Eikonal unreachable cost must be positive.");
        if (horizontal == unreachableCost)
        {
            return vertical == unreachableCost
                ? unreachableCost
                : ClampDeterministicIntegrationCost(checked(vertical + stepCost), unreachableCost);
        }
        if (vertical == unreachableCost)
            return ClampDeterministicIntegrationCost(checked(horizontal + stepCost), unreachableCost);

        long low = Math.Min(horizontal, vertical);
        long high = Math.Max(horizontal, vertical);
        long difference = high - low;
        if (difference >= stepCost)
            return ClampDeterministicIntegrationCost(checked(low + stepCost), unreachableCost);

        long discriminant = checked(2L * stepCost * stepCost - difference * difference);
        long root = ResolveIntegerSquareRoot(discriminant);
        return ClampDeterministicIntegrationCost(checked((low + high + root + 1L) / 2L), unreachableCost);
    }

    private static long ResolveIntegerSquareRoot(long value)
    {
        if (value < 0)
            throw new ArgumentOutOfRangeException(nameof(value), value, "Integer square root requires a non-negative value.");

        ulong remainder = (ulong)value;
        ulong result = 0;
        ulong bit = 1UL << 62;
        while (bit > remainder)
            bit >>= 2;
        while (bit != 0)
        {
            if (remainder >= result + bit)
            {
                remainder -= result + bit;
                result = (result >> 1) + bit;
            }
            else
            {
                result >>= 1;
            }
            bit >>= 2;
        }
        return checked((long)result);
    }

    private static long ClampDeterministicIntegrationCost(long cost, long unreachableCost)
    {
        if (cost < 0L)
            throw new ArgumentOutOfRangeException(nameof(cost), cost, "Integration cost must be non-negative.");
        return cost >= unreachableCost ? unreachableCost : cost;
    }

    private static int ConvertPortalAccessCostToFlowCost(long portalAccessCost)
    {
        if (portalAccessCost == long.MaxValue)
            return int.MaxValue;
        long converted = checked((portalAccessCost + 2L) / 4L);
        return converted >= int.MaxValue ? int.MaxValue : checked((int)converted);
    }

    private static int IndexOfGoalCell(Vector2Int[] goalCells, int worldX, int worldY)
    {
        for (int i = 0; i < goalCells.Length; i++)
        {
            if (goalCells[i].x == worldX && goalCells[i].y == worldY)
                return i;
        }
        return -1;
    }

    private static ushort[] BuildDeterministicPortalTargetSlotIndices(
        FlowTileCacheEntry tile,
        int[] integrationCosts,
        byte[] directionIndices)
    {
        if (tile.GoalCells.Length > ushort.MaxValue - 1)
        {
            throw new InvalidOperationException(
                $"BuildDeterministicPortalTargetSlotIndices failed: portal has too many slots count={tile.GoalCells.Length}, key={FormatTileKey(tile.Key)}.");
        }

        int count = tile.Width * tile.Height;
        var slotIndices = new ushort[count];
        for (int i = 0; i < tile.GoalCells.Length; i++)
        {
            Vector2Int goal = tile.GoalCells[i];
            if (!IsInsideSector(tile, goal.x, goal.y))
                throw new InvalidOperationException($"BuildDeterministicPortalTargetSlotIndices failed: portal goal is outside tile goal={goal}, key={FormatTileKey(tile.Key)}.");
            slotIndices[tile.GetLocalIndex(goal.x, goal.y)] = checked((ushort)(i + 1));
        }

        for (int localIndex = 0; localIndex < count; localIndex++)
        {
            if (integrationCosts[localIndex] == int.MaxValue || slotIndices[localIndex] != 0)
                continue;

            ushort resolvedSlot = ResolveDeterministicPortalTargetSlotIndex(
                tile,
                integrationCosts,
                directionIndices,
                slotIndices,
                localIndex);
            int cursor = localIndex;
            int guard = count + 1;
            while (slotIndices[cursor] == 0 && guard-- > 0)
            {
                slotIndices[cursor] = resolvedSlot;
                int offsetIndex = directionIndices[cursor] - 1;
                int worldX = tile.StartX + cursor % tile.Width;
                int worldY = tile.StartY + cursor / tile.Width;
                cursor = tile.GetLocalIndex(
                    worldX + NeighborOffsetX[offsetIndex],
                    worldY + NeighborOffsetY[offsetIndex]);
            }
            if (guard <= 0)
                throw new InvalidOperationException($"BuildDeterministicPortalTargetSlotIndices failed: flow path fill exceeded tile size key={FormatTileKey(tile.Key)}.");
        }

        return slotIndices;
    }

    private static ushort ResolveDeterministicPortalTargetSlotIndex(
        FlowTileCacheEntry tile,
        int[] integrationCosts,
        byte[] directionIndices,
        ushort[] slotIndices,
        int startLocalIndex)
    {
        int cursor = startLocalIndex;
        int guard = tile.Width * tile.Height + 1;
        while (guard-- > 0)
        {
            ushort slotIndex = slotIndices[cursor];
            if (slotIndex != 0)
                return slotIndex;

            byte directionIndex = directionIndices[cursor];
            if (directionIndex == 0)
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicPortalTargetSlotIndex failed: reachable portal flow has no direction localIndex={cursor}, key={FormatTileKey(tile.Key)}.");
            }

            int offsetIndex = directionIndex - 1;
            int worldX = tile.StartX + cursor % tile.Width;
            int worldY = tile.StartY + cursor / tile.Width;
            int nextX = worldX + NeighborOffsetX[offsetIndex];
            int nextY = worldY + NeighborOffsetY[offsetIndex];
            if (!IsInsideSector(tile, nextX, nextY))
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicPortalTargetSlotIndex failed: flow leaves tile before reaching portal cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");
            }

            int nextLocalIndex = tile.GetLocalIndex(nextX, nextY);
            if (integrationCosts[nextLocalIndex] >= integrationCosts[cursor])
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicPortalTargetSlotIndex failed: flow does not descend current={integrationCosts[cursor]}, next={integrationCosts[nextLocalIndex]}, key={FormatTileKey(tile.Key)}.");
            }
            cursor = nextLocalIndex;
        }

        throw new InvalidOperationException($"ResolveDeterministicPortalTargetSlotIndex failed: flow path contains a cycle key={FormatTileKey(tile.Key)}.");
    }

    private static byte ResolveDeterministicPortalHandoffDirectionIndex(
        PortalData portal,
        Vector2Int currentCell,
        Vector2Int downstreamCell,
        byte downstreamDirectionIndex)
    {
        if (portal == null)
            throw new InvalidOperationException("ResolveDeterministicPortalHandoffDirectionIndex failed: portal is null.");

        int normalX = downstreamCell.x - currentCell.x;
        int normalY = downstreamCell.y - currentCell.y;
        if ((portal.IsVerticalBoundary && (normalX == 0 || normalY != 0))
            || (!portal.IsVerticalBoundary && (normalY == 0 || normalX != 0)))
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicPortalHandoffDirectionIndex failed: portal {portal.PortalId} pair does not match boundary orientation current={currentCell}, downstream={downstreamCell}.");
        }

        int tangentX = 0;
        int tangentY = 0;
        if (downstreamDirectionIndex != 0)
        {
            int downstreamOffsetIndex = downstreamDirectionIndex - 1;
            if (downstreamOffsetIndex < 0 || downstreamOffsetIndex >= NeighborOffsetX.Length)
                throw new InvalidOperationException($"ResolveDeterministicPortalHandoffDirectionIndex failed: invalid downstream direction {downstreamDirectionIndex}.");
            tangentX = portal.IsVerticalBoundary ? 0 : NeighborOffsetX[downstreamOffsetIndex];
            tangentY = portal.IsVerticalBoundary ? NeighborOffsetY[downstreamOffsetIndex] : 0;
        }

        int offsetIndex = ResolveNeighborOffsetIndex(normalX + tangentX, normalY + tangentY);
        if (offsetIndex < 0)
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicPortalHandoffDirectionIndex failed: portal {portal.PortalId} handoff is not an adjacent direction normal=({normalX},{normalY}), tangent=({tangentX},{tangentY}).");
        }
        return checked((byte)(offsetIndex + 1));
    }

    private static int ResolveWorldBuildPriority(WorldRuntimeState state)
    {
        if (state == null)
            return 0;

        int agentTypeId = state.BuildJob != null ? state.BuildJob.AgentTypeId : state.AgentTypeId;
        int priority = 1;
        foreach (AgentRuntimeData agent in Agents.Values)
        {
            if (ResolvePreferredAgentTypeId(agent.AgentTypeId) == agentTypeId)
                priority += 100;
        }

        return priority;
    }

    private static void EnsureWorldBuildStatesForKnownAgentTypes()
    {
        List<int> agentTypeIds = CollectNavigationWorldAgentTypes();
        for (int i = 0; i < agentTypeIds.Count; i++)
        {
            int agentTypeId = ResolvePreferredAgentTypeId(agentTypeIds[i]);
            GetOrCreateWorldState(agentTypeId);
        }
    }

    private static int ResolveRuntimeDirtyPriority(WorldRuntimeState state)
    {
        if (state == null || state.World == null)
            return int.MinValue;

        HashSet<int> dirtySectors = state.RuntimeDirtyJob != null
            ? state.RuntimeDirtyJob.DirtySectors
            : state.DirtyRuntimeObstacleSectors;
        if (dirtySectors == null || dirtySectors.Count == 0)
            return 0;

        NavigationWorld world = state.World;
        int priority = dirtySectors.Count;
        foreach (AgentRuntimeData agent in Agents.Values)
        {
            if (ResolvePreferredAgentTypeId(agent.AgentTypeId) != world.AgentTypeId)
                continue;

            if (world.WorldToGridFixed(agent.PositionFixed, out int agentX, out int agentY)
                && world.TryGetSectorId(agentX, agentY, out int agentSectorId)
                && dirtySectors.Contains(agentSectorId))
            {
                priority += 1000;
                continue;
            }

            if (PathTouchesAnySector(agent.NavState.PathHandle, dirtySectors))
                priority += 100;
        }

        return priority;
    }

    public static void RegisterAgent(IEntityContext entity)
    {
        Fix64 radiusFixed = ResolveCollisionRadiusFixed(entity);
        RegisterAgentInternal(entity, (float)radiusFixed, ResolveExplicitAgentTypeId(entity, nameof(RegisterAgent)));
    }

