    public static bool TryResolveCombatApproachPointFixed(
        IEntityContext self,
        IEntityContext target,
        FixVector2 targetPoint,
        Fix64 standOff,
        Fix64 minimumStandOff,
        Fix64 ringSpacing,
        int ringCount,
        int candidateCount,
        Fix64 requiredClearance,
        out FixVector2 approachPoint,
        out string failureReason,
        out NavigationQueryFailureKind failureKind)
    {
        approachPoint = targetPoint;
        failureReason = string.Empty;
        failureKind = NavigationQueryFailureKind.None;
        if (self == null)
            throw new InvalidOperationException("TryResolveCombatApproachPoint failed: self is null.");
        if (target == null)
            throw new InvalidOperationException("TryResolveCombatApproachPoint failed: target is null.");

        FixVector2 selfFramePosition = self.LogicFramePositionFixed();
        FixVector2 targetPointFixed = targetPoint;

        int selfId = ResolveAgentId(self);
        if (!Agents.TryGetValue(selfId, out AgentRuntimeData agent))
        {
            RegisterSyntheticAgent(self);
            agent = Agents[selfId];
        }
        else
        {
            agent.PositionFixed = self.LogicFramePositionFixed();
            agent.Position = ToWorldVector3(agent.PositionFixed);
            agent.RadiusFixed = ResolveCollisionRadiusFixed(self);
            agent.Radius = (float)agent.RadiusFixed;
            agent.AgentTypeId = self is ILogicFrameEntity logicEntity ? logicEntity.NavigationAgentTypeId : agent.AgentTypeId;
        }

        if (!TryEnsureWorldBuilt(agent.AgentTypeId))
        {
            failureKind = NavigationQueryFailureKind.Unavailable;
            failureReason = $"world unavailable agentType={agent.AgentTypeId}";
            return false;
        }

        if (HasPendingRuntimeDirty(_activeWorldState))
        {
            failureKind = NavigationQueryFailureKind.PendingRuntimeUpdate;
            failureReason = $"runtime dirty pending agentType={agent.AgentTypeId}";
            return false;
        }

        if (!TryResolveStartCellForReachabilityFixed(self, out int startX, out int startY, out int startIsland))
        {
            failureKind = NavigationQueryFailureKind.Unreachable;
            failureReason = $"start reachability failed {BuildReachabilityStartDiagnostics(self)}";
            return false;
        }

        if (!_world.WorldToGridFixed(targetPointFixed, out int targetX, out int targetY))
        {
            failureKind = NavigationQueryFailureKind.Unreachable;
            failureReason = $"target point outside grid targetRaw=({targetPoint.x.RawValue},{targetPoint.y.RawValue})";
            return false;
        }

        Fix64 navigationClearance = Fix64.Max(agent.RadiusFixed, ResolveCollisionRadiusFixed(self));
        CombatTargetSlotKey key = CreateCombatTargetSlotKey(
            target,
            agent.AgentTypeId,
            targetPoint,
            targetX,
            targetY,
            standOff,
            minimumStandOff,
            ringSpacing,
            navigationClearance,
            ringCount,
            candidateCount);
        CombatTargetSlotEntry entry = GetOrBuildCombatTargetSlotEntry(
            key,
            targetPoint,
            standOff,
            minimumStandOff,
            ringSpacing,
            ringCount,
            candidateCount,
            targetX,
            targetY,
            navigationClearance);
        if (entry == null || entry.Points == null)
            throw new InvalidOperationException("TryResolveCombatApproachPoint failed: combat target slot entry is invalid.");

        FixVector2 toTargetFromSelf = selfFramePosition - targetPointFixed;
        if (FixVector2.SqrMagnitude(toTargetFromSelf) <= Fix64.FromRaw(1))
            toTargetFromSelf = new FixVector2(Fix64.Zero, Fix64.One);
        toTargetFromSelf = toTargetFromSelf.GetNormalized();

        int ignoredTargetId = ResolveAgentId(target);
        Fix64 bestScore = Fix64.FromRaw(long.MaxValue);
        int bestIndex = -1;
        bool bestOccupied = false;
        int bestBlockingAgentId = 0;
        int occupiedSlotCount = 0;
        int availableSlotCount = 0;
        for (int i = 0; i < entry.Points.Length; i++)
        {
            if (entry.IslandIds[i] != startIsland)
                continue;

            FixVector2 candidate = entry.Points[i];
            bool occupied = IsNavigationGoalOccupiedByOtherFixed(
                selfId,
                ignoredTargetId,
                candidate,
                requiredClearance,
                includeReservations: true,
                out int blockingAgentId);
            if (occupied)
                occupiedSlotCount++;
            else
                availableSlotCount++;
            FixVector2 candidateDirection = candidate - targetPointFixed;
            Fix64 anglePenalty = ResolveCombatAnglePenalty(candidateDirection, toTargetFromSelf);
            Fix64 distanceToSelf = FixVector2.Distance(selfFramePosition, candidate);
            Fix64 distanceToTargetError = Fix64.Abs(FixVector2.Distance(candidate, targetPointFixed) - standOff);
            Fix64 score = distanceToSelf + distanceToTargetError * (Fix64)3 + anglePenalty;
            if (occupied)
                score += (Fix64)1000;
            if (score >= bestScore)
                continue;

            bestScore = score;
            bestIndex = i;
            bestOccupied = occupied;
            bestBlockingAgentId = blockingAgentId;
        }

        bool usedExpandedSlot = false;
        int expandedRing = -1;
        if (bestIndex < 0)
        {
            if (TryResolveExpandedCombatApproachPoint(
                    selfId,
                    ignoredTargetId,
                    startIsland,
                    targetPoint,
                    targetX,
                    targetY,
                    standOff,
                    minimumStandOff,
                    ringSpacing,
                    ringCount,
                    candidateCount,
                    requiredClearance,
                    toTargetFromSelf,
                    selfFramePosition,
                    out approachPoint,
                    out expandedRing,
                    out Fix64 expandedScore))
            {
                bestScore = expandedScore;
                bestOccupied = false;
                bestBlockingAgentId = 0;
                usedExpandedSlot = true;
            }
            else
            {
                failureReason =
                    $"no combat approach slot in start island target={target.CharacterKey} start=({startX},{startY}) startIsland={startIsland} " +
                    $"targetPoint={targetPoint} standOff=[{minimumStandOff:F3},{standOff:F3}] slots={entry.Points.Length} build={entry.BuildSummary} " +
                    $"candidateIslands={BuildCombatApproachIslandSummary(entry, startIsland)} expandedFailed=True";
                failureKind = NavigationQueryFailureKind.Unreachable;
                return false;
            }
        }
        else
        {
            approachPoint = entry.Points[bestIndex];
        }

        if (!usedExpandedSlot
            && bestOccupied
            && TryResolveExpandedCombatApproachPoint(
                selfId,
                ignoredTargetId,
                startIsland,
                targetPoint,
                targetX,
                targetY,
                standOff,
                minimumStandOff,
                ringSpacing,
                ringCount,
                candidateCount,
                requiredClearance,
                toTargetFromSelf,
                selfFramePosition,
                out FixVector2 expandedApproachPoint,
                out expandedRing,
                out Fix64 occupiedExpandedScore))
        {
            approachPoint = expandedApproachPoint;
            bestScore = occupiedExpandedScore;
            bestOccupied = false;
            bestBlockingAgentId = 0;
            usedExpandedSlot = true;
        }

        RegisterNavigationGoalReservationFixed(selfId, approachPoint, requiredClearance);
        if (GameDebugSettings.IsEnabled(DebugCategory.Move)
            && GameDebugSettings.ShouldLogMovementForCharacter(self.CharacterKey)
            && TryConsumeSuccessfulMoveDiagnosticBudget())
        {
            GameDebugSettings.Log(DebugCategory.Move,
                $"[FlowCombatSlot] self={self.CharacterKey} selfId={selfId} target={target.CharacterKey} targetId={ignoredTargetId} " +
                $"selfPos={self.Position} targetPoint={targetPoint} previousGoal={agent.NavState.LastGoalWorld} " +
                $"approach={approachPoint} slotIndex={bestIndex} occupied={bestOccupied} blocker={bestBlockingAgentId} score={bestScore:F3} " +
                $"start=({startX},{startY}) startIsland={startIsland} keyTargetCell={key.TargetCellIndex} slots={entry.Points.Length} " +
                $"standOff=[{minimumStandOff:F3},{standOff:F3}] availableSlots={availableSlotCount} occupiedSlots={occupiedSlotCount} " +
                $"expanded={usedExpandedSlot} expandedRing={expandedRing}");
        }

        return true;
    }

    private static string BuildCombatApproachIslandSummary(CombatTargetSlotEntry entry, int startIsland)
    {
        if (entry == null || entry.IslandIds == null || entry.IslandIds.Length == 0)
            return "none";

        Dictionary<int, int> counts = new Dictionary<int, int>();
        for (int i = 0; i < entry.IslandIds.Length; i++)
        {
            int island = entry.IslandIds[i];
            counts.TryGetValue(island, out int count);
            counts[island] = count + 1;
        }

        System.Text.StringBuilder builder = new System.Text.StringBuilder(64);
        builder.Append("start=").Append(startIsland).Append('[');
        int emitted = 0;
        foreach (KeyValuePair<int, int> pair in counts)
        {
            if (emitted > 0)
                builder.Append(',');
            builder.Append(pair.Key).Append(':').Append(pair.Value);
            emitted++;
            if (emitted >= 8 && counts.Count > emitted)
            {
                builder.Append(",...");
                break;
            }
        }
        builder.Append(']');
        return builder.ToString();
    }

    private static bool TryResolveExpandedCombatApproachPoint(
        int selfId,
        int ignoredTargetId,
        int startIsland,
        FixVector2 targetPoint,
        int targetX,
        int targetY,
        Fix64 standOff,
        Fix64 minimumStandOff,
        Fix64 ringSpacing,
        int baseRingCount,
        int candidateCount,
        Fix64 requiredClearance,
        FixVector2 preferredDirection,
        FixVector2 selfPosition,
        out FixVector2 approachPoint,
        out int selectedRing,
        out Fix64 selectedScore)
    {
        approachPoint = targetPoint;
        selectedRing = -1;
        selectedScore = Fix64.FromRaw(long.MaxValue);
        if (_world == null)
            throw new InvalidOperationException("TryResolveExpandedCombatApproachPoint failed: world is null.");

        FixVector2 targetPointFixed = targetPoint;
        bool targetLineCellValid = _world.IsWalkable(targetX, targetY);
        int targetIsland = targetLineCellValid ? ResolveIslandIdForDiagnostics(_world, targetX, targetY) : 0;
        Fix64 spacing = Fix64.Max(Fix64.FromRaw(205), ringSpacing);
        Fix64 maximumRadius = Fix64.Max(Fix64.FromRaw(205), standOff);
        Fix64 minimumRadius = Fix64.Clamp(minimumStandOff, Fix64.FromRaw(205), maximumRadius);
        int inwardSteps = checked((int)(long)Fix64.Ceiling(Fix64.Max(Fix64.Zero, standOff - minimumRadius) / spacing));
        int generatedRingCount = Mathf.Max(Mathf.Max(1, baseRingCount), inwardSteps + 1);
        int samplesPerRing = Mathf.Max(16, candidateCount * 2);
        for (int ring = 0; ring < generatedRingCount; ring++)
        {
            Fix64 radius = Fix64.Max(minimumRadius, standOff - (Fix64)ring * spacing);
            for (int i = 0; i < samplesPerRing; i++)
            {
                FixVector2 direction = ResolveCombatSampleDirection(i, samplesPerRing, halfStep: true);
                FixVector2 candidate = targetPointFixed + direction * radius;
                if (!_world.WorldToGridFixed(candidate, out int x, out int y))
                    continue;
                if (!_world.IsWalkable(x, y))
                    continue;

                int islandId = ResolveIslandIdForDiagnostics(_world, x, y);
                if (islandId != startIsland)
                    continue;

                FixVector2 worldPoint = candidate;
                if (!IsNavigationPointClearFixed(
                        _world,
                        worldPoint,
                        ResolveNavigationQueryClearanceFixed(_world, requiredClearance),
                        includeRuntimeObstacleOverlay: true))
                    continue;
                if (targetLineCellValid
                    && targetIsland == islandId
                    && !HasSoftCostTolerantGridLineOfSight(_world, x, y, targetX, targetY, maxAllowedCost: 15))
                    continue;
                if (IsNavigationGoalOccupiedByOtherFixed(
                        selfId,
                        ignoredTargetId,
                        worldPoint,
                        requiredClearance,
                        includeReservations: true,
                        out _))
                    continue;

                FixVector2 candidateDirection = worldPoint - targetPointFixed;
                Fix64 anglePenalty = ResolveCombatAnglePenalty(candidateDirection, preferredDirection);
                Fix64 distanceToSelf = FixVector2.Distance(selfPosition, worldPoint);
                Fix64 distanceToPreferredRadius = Fix64.Abs(FixVector2.Distance(worldPoint, targetPointFixed) - standOff);
                Fix64 score = distanceToSelf + anglePenalty + distanceToPreferredRadius * (Fix64)3;
                if (score >= selectedScore)
                    continue;

                selectedScore = score;
                approachPoint = worldPoint;
                selectedRing = ring;
            }

            if (selectedRing == ring)
                return true;
        }

        return selectedRing >= 0;
    }

    private static FixVector2 ResolveCombatSampleDirection(int index, int sampleCount, bool halfStep)
    {
        if (sampleCount <= 0)
            throw new ArgumentOutOfRangeException(nameof(sampleCount), sampleCount, "Combat sample count must be positive.");
        if (index < 0 || index >= sampleCount)
            throw new ArgumentOutOfRangeException(nameof(index), index, "Combat sample index is outside the sample range.");

        int numerator = halfStep ? checked(index * 2 + 1) : index;
        int denominator = halfStep ? checked(sampleCount * 2) : sampleCount;
        Fix64 angle = Fix64.PITimes2 * (Fix64)numerator / (Fix64)denominator;
        return new FixVector2(Fix64.Sin(angle), Fix64.Cos(angle));
    }

    private static Fix64 ResolveCombatAnglePenalty(FixVector2 direction, FixVector2 preferredDirection)
    {
        if (FixVector2.SqrMagnitude(direction) <= Fix64.FromRaw(1)
            || FixVector2.SqrMagnitude(preferredDirection) <= Fix64.FromRaw(1))
        {
            return Fix64.Zero;
        }

        FixVector2 normalizedDirection = direction.GetNormalized();
        FixVector2 normalizedPreferred = preferredDirection.GetNormalized();
        Fix64 cross = Fix64.Abs(
            normalizedDirection.x * normalizedPreferred.y
            - normalizedDirection.y * normalizedPreferred.x);
        Fix64 dot = normalizedDirection.x * normalizedPreferred.x
                    + normalizedDirection.y * normalizedPreferred.y;
        Fix64 angleDegrees = Fix64.Atan2(cross, dot) * (Fix64)180 / Fix64.PI;
        return angleDegrees * Fix64.FromRaw(62);
    }

    private static Vector3 ToWorldVector3(FixVector2 point)
    {
        return new Vector3((float)point.x, 0f, (float)point.y);
    }

    public static bool TryPrepareSharedGoalRequest(Vector3 goalPosition, IReadOnlyList<IEntityContext> sources, out string failureReason)
    {
        failureReason = string.Empty;
        if (sources == null)
            throw new InvalidOperationException("TryPrepareSharedGoalRequest failed: sources is null.");
        if (sources.Count == 0)
        {
            failureReason = "sources is empty";
            return false;
        }

        int preparedCount = 0;
        for (int i = 0; i < sources.Count; i++)
        {
            IEntityContext source = sources[i];
            if (source == null)
            {
                failureReason = $"source[{i}] is null";
                return false;
            }

            if (!TryPrepareNavigationRequest(source, goalPosition, out failureReason))
                return false;

            preparedCount++;
        }

        return preparedCount == sources.Count;
    }

    public static bool TryPrepareNavigationRequestFixed(
        IEntityContext source,
        FixVector2 goalPosition,
        out string failureReason)
    {
        return TryPrepareNavigationRequestFixedCore(source, goalPosition, rejectPendingRuntimeDirty: true, out failureReason);
    }

    private static bool TryPrepareNavigationRequestFixedCore(
        IEntityContext source,
        FixVector2 goalPosition,
        bool rejectPendingRuntimeDirty,
        out string failureReason)
    {
        failureReason = string.Empty;
        if (source == null)
            throw new InvalidOperationException("TryPrepareNavigationRequestFixed failed: source is null.");

        int sourceId = ResolveAgentId(source);
        if (!Agents.TryGetValue(sourceId, out AgentRuntimeData agent))
        {
            RegisterSyntheticAgent(source);
            agent = Agents[sourceId];
        }
        else
        {
            agent.PositionFixed = source.LogicFramePositionFixed();
            agent.Position = ToWorldVector3(agent.PositionFixed);
            agent.RadiusFixed = ResolveCollisionRadiusFixed(source);
            agent.Radius = (float)agent.RadiusFixed;
            agent.AgentTypeId = source is ILogicFrameEntity logicEntity ? logicEntity.NavigationAgentTypeId : agent.AgentTypeId;
        }

        if (!TryEnsureWorldBuilt(agent.AgentTypeId))
        {
            failureReason = $"world unavailable source={source.CharacterKey} agentType={agent.AgentTypeId}";
            return false;
        }

        if (rejectPendingRuntimeDirty && HasPendingRuntimeDirty(_activeWorldState))
        {
            failureReason = $"runtime dirty pending source={source.CharacterKey} agentType={agent.AgentTypeId}";
            return false;
        }

        if (!TryResolveStartCellForReachabilityFixed(source, out int startX, out int startY, out int startIsland))
        {
            failureReason = $"start reachability failed source={source.CharacterKey} {BuildReachabilityStartDiagnostics(source)}";
            return false;
        }

        if (!TryResolveStableGoalCellFixed(
                agent,
                source,
                goalPosition,
                out int goalX,
                out int goalY,
                out FixVector2 stableGoalPosition,
                out bool shouldEnqueueSharedGoal))
        {
            failureReason = $"goal reachability failed source={source.CharacterKey} {BuildGoalResolutionFailure(source, ToWorldVector3(goalPosition))}";
            return false;
        }

        if (!_world.TryGetSectorId(startX, startY, out int startSectorId))
        {
            failureReason = $"start sector failed source={source.CharacterKey} start=({startX},{startY})";
            return false;
        }

        if (!_world.TryGetSectorId(goalX, goalY, out int goalSectorId))
        {
            failureReason = $"goal sector failed source={source.CharacterKey} goal=({goalX},{goalY}) stableGoalRaw=({stableGoalPosition.x.RawValue},{stableGoalPosition.y.RawValue})";
            return false;
        }

        agent.NavState.CurrentCell = new Vector2Int(startX, startY);
        agent.NavState.CurrentSectorId = startSectorId;
        agent.NavState.HasGoal = true;
        agent.NavState.LastGoalWorldFixed = stableGoalPosition;
        agent.NavState.LastGoalWorld = ToWorldVector3(stableGoalPosition);
        if (!EnsurePathHandle(agent, startSectorId, goalSectorId, startX, startY, goalX, goalY))
        {
            failureReason = $"path handle failed source={source.CharacterKey} startSector={startSectorId} goalSector={goalSectorId}";
            return false;
        }

        if (shouldEnqueueSharedGoal)
            EnqueueSharedGoalFieldBuild(goalSectorId, goalX, goalY, ResolvePreferredAgentTypeId(agent.AgentTypeId), startSectorId, startX, startY);
        EnqueueFlowTileBuildChain(agent.NavState.PathHandle, agent.NavState.PathHandle.CurrentSectorIndex, goalX, goalY, agent.AgentTypeId);
        return true;
    }

    public static bool TryPrepareNavigationRequest(IEntityContext source, Vector3 goalPosition, out string failureReason)
    {
        return TryPrepareNavigationRequestFixed(
            source,
            new FixVector2((Fix64)goalPosition.x, (Fix64)goalPosition.z),
            out failureReason);
    }

    private static CombatTargetSlotKey CreateCombatTargetSlotKey(
        IEntityContext target,
        int agentTypeId,
        FixVector2 targetPoint,
        int targetX,
        int targetY,
        Fix64 standOff,
        Fix64 minimumStandOff,
        Fix64 ringSpacing,
        Fix64 requiredClearance,
        int ringCount,
        int candidateCount)
    {
        int targetId = ResolveAgentId(target);
        return new CombatTargetSlotKey(
            _world.Version,
            ResolvePreferredAgentTypeId(agentTypeId),
            targetId,
            _world.GetIndex(targetX, targetY),
            targetPoint.x.RawValue,
            targetPoint.y.RawValue,
            standOff.RawValue,
            minimumStandOff.RawValue,
            ringSpacing.RawValue,
            Fix64.Max(Fix64.Zero, requiredClearance).RawValue,
            Mathf.Max(1, ringCount),
            Mathf.Max(4, candidateCount));
    }

    private static CombatTargetSlotEntry GetOrBuildCombatTargetSlotEntry(
        CombatTargetSlotKey key,
        FixVector2 targetPoint,
        Fix64 standOff,
        Fix64 minimumStandOff,
        Fix64 ringSpacing,
        int ringCount,
        int candidateCount,
        int targetX,
        int targetY,
        Fix64 requiredClearance)
    {
        if (CombatTargetSlotCache.TryGetValue(key, out CombatTargetSlotEntry cached)
            && cached?.Points != null)
        {
            cached.LastUsedFrame = GetFrameCount();
            return cached;
        }

        List<FixVector2> points = new List<FixVector2>(Mathf.Max(4, ringCount * candidateCount));
        List<int> cellX = new List<int>(points.Capacity);
        List<int> cellY = new List<int>(points.Capacity);
        List<int> islandIds = new List<int>(points.Capacity);
        int rejectedOutside = 0;
        int rejectedBlocked = 0;
        int rejectedClearance = 0;
        int rejectedNoLos = 0;
        bool targetLineCellValid = _world.IsWalkable(targetX, targetY);

        FixVector2 targetPointFixed = targetPoint;
        Fix64 spacing = Fix64.Max(Fix64.FromRaw(205), ringSpacing);
        Fix64 maximumRadius = Fix64.Max(Fix64.FromRaw(205), standOff);
        Fix64 minimumRadius = Fix64.Clamp(minimumStandOff, Fix64.FromRaw(205), maximumRadius);
        int inwardSteps = checked((int)(long)Fix64.Ceiling(Fix64.Max(Fix64.Zero, standOff - minimumRadius) / spacing));
        int generatedRingCount = Mathf.Max(Mathf.Max(1, ringCount), inwardSteps + 1);
        for (int ring = 0; ring < generatedRingCount; ring++)
        {
            Fix64 radius = Fix64.Max(minimumRadius, standOff - (Fix64)ring * spacing);
            for (int i = 0; i < Mathf.Max(4, candidateCount); i++)
            {
                int samplesPerRing = Mathf.Max(4, candidateCount);
                FixVector2 direction = ResolveCombatSampleDirection(i, samplesPerRing, halfStep: false);
                FixVector2 candidate = targetPointFixed + direction * radius;
                if (!_world.WorldToGridFixed(candidate, out int x, out int y))
                {
                    rejectedOutside++;
                    continue;
                }

                if (!_world.IsWalkable(x, y))
                {
                    rejectedBlocked++;
                    continue;
                }

                int islandId = ResolveIslandIdForDiagnostics(_world, x, y);
                if (islandId <= 0)
                {
                    rejectedBlocked++;
                    continue;
                }

                FixVector2 worldPoint = candidate;
                if (!IsNavigationPointClearFixed(
                        _world,
                        worldPoint,
                        ResolveNavigationQueryClearanceFixed(_world, requiredClearance),
                        includeRuntimeObstacleOverlay: true))
                {
                    rejectedClearance++;
                    continue;
                }

                if (targetLineCellValid
                    && ResolveIslandIdForDiagnostics(_world, targetX, targetY) == islandId
                    && !HasSoftCostTolerantGridLineOfSight(_world, x, y, targetX, targetY, maxAllowedCost: 15))
                {
                    rejectedNoLos++;
                    continue;
                }

                bool duplicate = false;
                for (int existing = 0; existing < points.Count; existing++)
                {
                    if (points[existing].x.RawValue == worldPoint.x.RawValue
                        && points[existing].y.RawValue == worldPoint.y.RawValue)
                    {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate)
                    continue;

                points.Add(worldPoint);
                cellX.Add(x);
                cellY.Add(y);
                islandIds.Add(islandId);
            }
        }

        CombatTargetSlotEntry entry = new CombatTargetSlotEntry
        {
            TargetPoint = targetPointFixed,
            Points = points.ToArray(),
            CellX = cellX.ToArray(),
            CellY = cellY.ToArray(),
            IslandIds = islandIds.ToArray(),
            LastUsedFrame = GetFrameCount(),
            BuildSummary =
                $"built={points.Count} rings={generatedRingCount} radius=[{minimumRadius:F3},{standOff:F3}] " +
                $"rejectedOutside={rejectedOutside} rejectedBlocked={rejectedBlocked} rejectedClearance={rejectedClearance} rejectedNoLos={rejectedNoLos}"
        };
        CombatTargetSlotCache[key] = entry;
        return entry;
    }

    private static void LogReachableGoalTargetSnapDiagnostics(
        NavigationWorld world,
        IEntityContext self,
        Vector3 desiredGoal,
        int startX,
        int startY,
        int goalX,
        int goalY,
        int resultX,
        int resultY,
        float distance,
        bool fullIsland)
    {
        if (!IsMovementDiagnosticsEnabled())
            return;
        if (world == null || self == null)
            return;

        IEntityContext target = self.TargetComp?.CurrentTarget;
        if (target == null)
            return;

        int desiredIsland = ResolveIslandIdForDiagnostics(world, goalX, goalY);
        bool targetInGrid = world.WorldToGrid(target.Position, out int targetX, out int targetY);
        int targetIsland = targetInGrid ? ResolveIslandIdForDiagnostics(world, targetX, targetY) : -1;
        if (desiredIsland == targetIsland && distance <= Mathf.Max(0.35f, world.CellSize * 1.5f))
            return;

        Vector3 resultWorld = world.GridToWorldCenter(resultX, resultY);
        Debug.LogWarning(
            $"[FlowReachableTargetSnapDiag] self={self.CharacterKey} target={target.CharacterKey} fullIsland={fullIsland} " +
            $"selfPos={self.Position} targetPos={target.Position} desired={desiredGoal} desiredCell=({goalX},{goalY}) desiredIsland={desiredIsland} " +
            $"targetCell={(targetInGrid ? $"({targetX},{targetY})" : "out")} targetIsland={targetIsland} result=({resultX},{resultY}) resultWorld={resultWorld} " +
            $"resultIsland={ResolveIslandIdForDiagnostics(world, resultX, resultY)} snapDistance={distance:F3} start=({startX},{startY}) " +
            $"startIsland={ResolveIslandIdForDiagnostics(world, startX, startY)} worldVersion={world.Version}");
    }

    private static void LogReachableGoalResolution(
        NavigationWorld world,
        IEntityContext self,
        Vector3 desiredGoal,
        int startX,
        int startY,
        int rawGoalX,
        int rawGoalY,
        int resolvedX,
        int resolvedY,
        float distance,
        int radiusCells,
        bool fullIsland)
    {
        if (!GameDebugSettings.IsEnabled(DebugCategory.Move)
            || self == null
            || !GameDebugSettings.ShouldLogMovementForCharacter(self.CharacterKey)
            || world == null)
        {
            return;
        }

        int startIsland = ResolveIslandIdForDiagnostics(world, startX, startY);
        int rawGoalIsland = ResolveIslandIdForDiagnostics(world, rawGoalX, rawGoalY);
        int resolvedIsland = ResolveIslandIdForDiagnostics(world, resolvedX, resolvedY);
        bool changed = rawGoalX != resolvedX || rawGoalY != resolvedY;
        if (!changed && !fullIsland)
            return;

        Vector3 resolvedWorld = world.GridToWorldCenter(resolvedX, resolvedY);
        GameDebugSettings.Log(DebugCategory.Move,
            $"[FlowReachableGoalResolve] key={self.CharacterKey} desired={desiredGoal} start=({startX},{startY}) startIsland={startIsland} " +
            $"raw=({rawGoalX},{rawGoalY}) rawIsland={rawGoalIsland} resolved=({resolvedX},{resolvedY}) resolvedIsland={resolvedIsland} " +
            $"resolvedWorld={resolvedWorld} distance={distance:F3} radiusCells={radiusCells} fullIsland={fullIsland} " +
            $"rawGrid={FormatGridSampleDiagnostics(desiredGoal)} resolvedGrid={FormatGridSampleDiagnostics(resolvedWorld)}");
    }

    public static bool TryGetSteeringVelocityFixed(
        IEntityContext self,
        FixVector2 goalPosition,
        Fix64 maxSpeed,
        out FixVector2 velocity)
    {
        BeginPerfCall();
        bool profile = MainThreadFrameProfiler.LoggingEnabled;
        long setupStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        if (self == null)
            throw new InvalidOperationException("TryGetSteeringVelocityFixed failed: self is null.");
        if (maxSpeed < Fix64.Zero)
            throw new ArgumentOutOfRangeException(nameof(maxSpeed), "Flow steering speed cannot be negative.");
        if (maxSpeed == Fix64.Zero)
        {
            velocity = FixVector2.Zero;
            return true;
        }

        int selfId = ResolveAgentId(self);
        if (!Agents.TryGetValue(selfId, out AgentRuntimeData agent))
        {
            RegisterSyntheticAgent(self);
            agent = Agents[selfId];
        }

        agent.PositionFixed = self.LogicFramePositionFixed();
        agent.Position = ToWorldVector3(agent.PositionFixed);
        agent.RadiusFixed = ResolveCollisionRadiusFixed(self);
        agent.Radius = (float)agent.RadiusFixed;
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringSetupAgent,
                Stopwatch.GetTimestamp() - setupStartTicks);
        }

        long worldStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        if (!TryEnsureWorldBuilt(agent.AgentTypeId))
        {
            string message = $"[{self.CharacterKey}] Flow strict fail: world unavailable agentType={agent.AgentTypeId}";
            Debug.LogError(message);
            throw new InvalidOperationException(message);
        }
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringSetupWorld,
                Stopwatch.GetTimestamp() - worldStartTicks);
        }

        long occupancyStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        bool hasMovingTarget = self.TargetComp?.CurrentTarget != null
                               && !ReferenceEquals(self.TargetComp.CurrentTarget, self)
                               && IsNavigationMovingTarget(self.TargetComp.CurrentTarget);
        FixVector2 occupiedGoalPosition = ResolveNavigationGoalOccupancyFixed(self, agent, goalPosition);
        FixVector2 navigationGoalPosition = hasMovingTarget ? goalPosition : occupiedGoalPosition;
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringSetupOccupancy,
                Stopwatch.GetTimestamp() - occupancyStartTicks);
        }

        long prepareStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        if (!TryPrepareNavigationRequestFixedCore(
                self,
                navigationGoalPosition,
                rejectPendingRuntimeDirty: false,
                out string prepareFailureReason))
        {
            agent.NavState.LastFixedFlowResult = $"prepare-failed: {prepareFailureReason}";
            velocity = FixVector2.Zero;
            string reason = prepareFailureReason.StartsWith("start reachability failed", StringComparison.Ordinal)
                ? $"start blocked: {prepareFailureReason}"
                : $"navigation prepare failed: {prepareFailureReason}";
            string message = $"[{self.CharacterKey}] Flow strict fail: {reason}";
            Debug.LogError(message);
            throw new InvalidOperationException(message);
        }
        long prepareElapsedTicks = profile ? Stopwatch.GetTimestamp() - prepareStartTicks : 0L;
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringSetupPrepare,
                prepareElapsedTicks);
            if (prepareElapsedTicks >= Stopwatch.Frequency * 2L / 1000L)
            {
                int startIsland = ResolveIslandIdForDiagnostics(
                    _world,
                    agent.NavState.CurrentCell.x,
                    agent.NavState.CurrentCell.y);
                Debug.LogFormat(
                    LogType.Log,
                    LogOption.NoStacktrace,
                    null,
                    "[FlowSteeringPrepareSlow] frame={0} elapsed={1:F3}ms entity={2}/{3} agentType={4} world={5} startCell=({6},{7}) startIsland={8} target={9} goalRaw=({10},{11}).",
                    GetFrameCount(),
                    prepareElapsedTicks * 1000.0 / Stopwatch.Frequency,
                    self.LogicEntityId.Value,
                    self.CharacterKey,
                    agent.AgentTypeId,
                    _world.Version,
                    agent.NavState.CurrentCell.x,
                    agent.NavState.CurrentCell.y,
                    startIsland,
                    agent.NavState.StableGoalTargetId,
                    goalPosition.x.RawValue,
                    goalPosition.y.RawValue);
            }
        }
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringSetup,
                Stopwatch.GetTimestamp() - setupStartTicks);
        }

        long pathStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        if (!TryAdvancePathToCurrentSector(agent, agent.NavState.CurrentSectorId))
        {
            PathHandle invalidHandle = agent.NavState.PathHandle;
            int goalX = invalidHandle?.GoalX ?? -1;
            int goalY = invalidHandle?.GoalY ?? -1;
            agent.NavState.PathHandle = null;
            if (goalX < 0
                || goalY < 0
                || !_world.TryGetSectorId(goalX, goalY, out int goalSectorId)
                || !EnsurePathHandle(
                    agent,
                    agent.NavState.CurrentSectorId,
                    goalSectorId,
                    agent.NavState.CurrentCell.x,
                    agent.NavState.CurrentCell.y,
                    goalX,
                    goalY)
                || !TryAdvancePathToCurrentSector(agent, agent.NavState.CurrentSectorId))
            {
                agent.NavState.LastFixedFlowResult =
                    $"path-rebuild-failed current=({agent.NavState.CurrentCell.x},{agent.NavState.CurrentCell.y}) goal=({goalX},{goalY})";
                velocity = FixVector2.Zero;
                return false;
            }
        }
        EnqueueActiveFlowTileBuilds(
            agent.NavState.PathHandle,
            agent.NavState.PathHandle.CurrentSectorIndex,
            agent.NavState.PathHandle.GoalX,
            agent.NavState.PathHandle.GoalY,
            agent.AgentTypeId);
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringPath,
                Stopwatch.GetTimestamp() - pathStartTicks);
        }

        agent.NavState.HasGoal = true;
        long portalOwnerStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        EnsureFixedPortalOwnerFrame();
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringPortalOwner,
                Stopwatch.GetTimestamp() - portalOwnerStartTicks);
        }
        long velocityStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
        velocity = ResolveDeterministicFlowVelocityFixed(self, agent, maxSpeed);
        velocity = ApplyFixedPortalOwner(agent, velocity);
        if (profile)
        {
            MainThreadFrameProfiler.Record(
                MainThreadPerfScope.FlowSteeringVelocity,
                Stopwatch.GetTimestamp() - velocityStartTicks);
        }

        int frame = GetFrameCount();
        Vector3 velocityView = ToWorldVector3(velocity);
        agent.NavState.DesiredVelocity = velocityView;
        agent.NavState.ResolvedVelocity = velocityView;
        agent.NavState.ResolvedVelocityFrame = frame;
        agent.NavState.CurrentFlowDirection = velocity == FixVector2.Zero
            ? Vector3.zero
            : ToWorldVector3(velocity.GetNormalized());
        agent.NavState.LastSteeringFrame = frame;
        agent.NavState.LastSteeringGoal = ToWorldVector3(occupiedGoalPosition);
        agent.NavState.LastSteeringDesiredDirection = agent.NavState.CurrentFlowDirection;
        agent.NavState.LastSteeringDesiredVelocity = velocityView;
        agent.NavState.LastSteeringBaseVelocity = velocityView;
        agent.NavState.LastSteeringResultPreClamp = velocityView;
        agent.NavState.LastSteeringResult = velocityView;
        agent.NavState.LastSteeringMaxSpeed = (float)maxSpeed;
        bool usedDirectLineOfSight = agent.NavState.LastFixedFlowResult.StartsWith("direct-static-clear", StringComparison.Ordinal);
        agent.NavState.LastSteeringDesiredSource = usedDirectLineOfSight
            ? DesiredDirectionSource.LineOfSight
            : DesiredDirectionSource.FlowField;
        agent.NavState.LastSteeringHasLineOfSight = usedDirectLineOfSight;
        agent.HasNavigationIntent = velocity != FixVector2.Zero;
        return true;
    }

    public static bool TryGetSteeringVelocity(IEntityContext self, Vector3 goalPosition, float maxSpeed, out Vector3 velocity)
    {
        velocity = Vector3.zero;
        bool success = TryGetSteeringVelocityFixed(
            self,
            new FixVector2((Fix64)goalPosition.x, (Fix64)goalPosition.z),
            (Fix64)maxSpeed,
            out FixVector2 velocityFixed);
        velocity = ToWorldVector3(velocityFixed);
        return success;
    }

    private static FixVector2 ClampFixedVelocity(FixVector2 velocity, Fix64 maxSpeed)
    {
        if (maxSpeed <= Fix64.Zero)
            return FixVector2.Zero;

        Fix64 squaredMagnitude = FixVector2.SqrMagnitude(velocity);
        Fix64 squaredMaxSpeed = maxSpeed * maxSpeed;
        return squaredMagnitude > squaredMaxSpeed
            ? velocity / Fix64.Sqrt(squaredMagnitude) * maxSpeed
            : velocity;
    }

    private static FixVector2 ScaleFixedDirectionToSpeed(FixVector2 direction, Fix64 speed)
    {
        if (direction == FixVector2.Zero || speed <= Fix64.Zero)
            return FixVector2.Zero;

        FixVector2 velocity = direction / Fix64.Sqrt(FixVector2.SqrMagnitude(direction)) * speed;
        return ClampFixedVelocity(velocity, speed);
    }

    private static Fix64 ResolveFunnelTriangleArea2(
        FixVector2 apex,
        FixVector2 first,
        FixVector2 second)
    {
        FixVector2 fromApexToFirst = first - apex;
        FixVector2 fromApexToSecond = second - apex;
        return fromApexToFirst.x * fromApexToSecond.y
               - fromApexToFirst.y * fromApexToSecond.x;
    }

    private static void ResolvePortalFunnelSegmentFixed(
        PathHandle handle,
        int portalPathIndex,
        out FixVector2 left,
        out FixVector2 right)
    {
        if (handle?.SectorIds == null
            || handle.PortalIds == null
            || portalPathIndex < 0
            || portalPathIndex >= handle.PortalIds.Length
            || portalPathIndex + 1 >= handle.SectorIds.Length)
        {
            throw new InvalidOperationException(
                $"ResolvePortalFunnelSegmentFixed failed: path index is invalid index={portalPathIndex}, handle={FormatPathHandle(handle)}.");
        }

        int currentSectorId = handle.SectorIds[portalPathIndex];
        int downstreamSectorId = handle.SectorIds[portalPathIndex + 1];
        PortalData portal = GetPortalById(_world, handle.PortalIds[portalPathIndex]);
        if (GetOppositeSectorId(portal, currentSectorId) != downstreamSectorId)
        {
            throw new InvalidOperationException(
                $"ResolvePortalFunnelSegmentFixed failed: portal does not connect path sectors portal={portal.PortalId}, current={currentSectorId}, downstream={downstreamSectorId}.");
        }

        Vector2Int[] currentCells = GetPortalCellsForSector(portal, currentSectorId);
        Vector2Int[] downstreamCells = GetPortalCellsForSector(portal, downstreamSectorId);
        if (currentCells.Length == 0 || currentCells.Length != downstreamCells.Length)
        {
            throw new InvalidOperationException(
                $"ResolvePortalFunnelSegmentFixed failed: portal sides are invalid portal={portal.PortalId}, current={currentCells.Length}, downstream={downstreamCells.Length}.");
        }

        FixVector2 first = (_world.GridToWorldCenterFixed(currentCells[0].x, currentCells[0].y)
                            + _world.GridToWorldCenterFixed(downstreamCells[0].x, downstreamCells[0].y))
                           / (Fix64)2;
        int lastIndex = currentCells.Length - 1;
        FixVector2 last = (_world.GridToWorldCenterFixed(currentCells[lastIndex].x, currentCells[lastIndex].y)
                           + _world.GridToWorldCenterFixed(downstreamCells[lastIndex].x, downstreamCells[lastIndex].y))
                          / (Fix64)2;
        FixVector2 travel = _world.GridToWorldCenterFixed(downstreamCells[0].x, downstreamCells[0].y)
                            - _world.GridToWorldCenterFixed(currentCells[0].x, currentCells[0].y);
        FixVector2 center = (first + last) / (Fix64)2;
        if (ResolveFunnelTriangleArea2(FixVector2.Zero, travel, first - center) >= Fix64.Zero)
        {
            left = first;
            right = last;
        }
        else
        {
            left = last;
            right = first;
        }
    }

    private static FixVector2 ResolvePortalCorridorFunnelTargetFixed(
        PathHandle handle,
        FixVector2 position,
        int portalStartPathIndex,
        int portalEndPathIndex,
        FixVector2 terminal,
        out int cornerPortalPathIndex)
    {
        if (handle == null
            || handle.CurrentSectorIndex < 0
            || handle.CurrentSectorIndex >= handle.SectorIds.Length)
        {
            throw new InvalidOperationException(
                $"ResolvePortalCorridorFunnelTargetFixed failed: handle is invalid handle={FormatPathHandle(handle)}.");
        }

        FixVector2 apex = position;
        FixVector2 funnelLeft = apex;
        FixVector2 funnelRight = apex;
        if (portalStartPathIndex < handle.CurrentSectorIndex
            || portalStartPathIndex > portalEndPathIndex
            || portalEndPathIndex > handle.PortalIds.Length)
        {
            throw new InvalidOperationException(
                $"ResolvePortalCorridorFunnelTargetFixed failed: corridor range is invalid start={portalStartPathIndex}, end={portalEndPathIndex}, handle={FormatPathHandle(handle)}.");
        }
        int leftIndex = portalStartPathIndex;
        int rightIndex = portalStartPathIndex;
        for (int portalIndex = portalStartPathIndex; portalIndex <= portalEndPathIndex; portalIndex++)
        {
            FixVector2 portalLeft;
            FixVector2 portalRight;
            if (portalIndex == portalEndPathIndex)
            {
                portalLeft = terminal;
                portalRight = portalLeft;
            }
            else
            {
                ResolvePortalFunnelSegmentFixed(handle, portalIndex, out portalLeft, out portalRight);
            }

            if (ResolveFunnelTriangleArea2(apex, funnelRight, portalRight) >= Fix64.Zero)
            {
                if (funnelRight == apex
                    || ResolveFunnelTriangleArea2(apex, funnelLeft, portalRight) < Fix64.Zero)
                {
                    funnelRight = portalRight;
                    rightIndex = portalIndex;
                }
                else
                {
                    cornerPortalPathIndex = leftIndex;
                    return funnelLeft;
                }
            }

            if (ResolveFunnelTriangleArea2(apex, funnelLeft, portalLeft) <= Fix64.Zero)
            {
                if (funnelLeft == apex
                    || ResolveFunnelTriangleArea2(apex, funnelRight, portalLeft) > Fix64.Zero)
                {
                    funnelLeft = portalLeft;
                    leftIndex = portalIndex;
                }
                else
                {
                    cornerPortalPathIndex = rightIndex;
                    return funnelRight;
                }
            }
        }

        cornerPortalPathIndex = portalEndPathIndex;
        return terminal;
    }

    private static void CommitCurrentFunnelCorridor(PathHandle handle, FlowTileCacheKey key)
    {
        if (handle == null
            || handle.SectorIds == null
            || handle.PortalIds == null
            || key.GoalKind != TileGoalKind.Portal
            || handle.CurrentSectorIndex < 0
            || handle.CurrentSectorIndex >= handle.PortalIds.Length
            || handle.SectorIds[handle.CurrentSectorIndex] != key.SectorId
            || handle.PortalIds[handle.CurrentSectorIndex] != key.GoalId)
        {
            throw new InvalidOperationException(
                $"CommitCurrentFunnelCorridor failed: path does not match current tile key={FormatTileKey(key)}, handle={FormatPathHandle(handle)}.");
        }

        int sectorCount = handle.SectorIds.Length - handle.CurrentSectorIndex;
        int portalCount = handle.PortalIds.Length - handle.CurrentSectorIndex;
        handle.CommittedCorridorGoalX = handle.GoalX;
        handle.CommittedCorridorGoalY = handle.GoalY;
        handle.CommittedCorridorSectorIds = new int[sectorCount];
        handle.CommittedCorridorPortalIds = new int[portalCount];
        Array.Copy(handle.SectorIds, handle.CurrentSectorIndex, handle.CommittedCorridorSectorIds, 0, sectorCount);
        Array.Copy(handle.PortalIds, handle.CurrentSectorIndex, handle.CommittedCorridorPortalIds, 0, portalCount);
    }

    private static PathHandle BuildCommittedFunnelCorridorFixed(PathHandle handle, FlowTileCacheKey key)
    {
        if (handle == null
            || !handle.HasCommittedCurrentTileKey
            || !handle.CommittedCurrentTileKey.Equals(key)
            || handle.CommittedCorridorSectorIds == null
            || handle.CommittedCorridorPortalIds == null
            || handle.CommittedCorridorSectorIds.Length != handle.CommittedCorridorPortalIds.Length + 1
            || handle.CommittedCorridorPortalIds.Length == 0
            || handle.CommittedCorridorSectorIds[0] != key.SectorId
            || handle.CommittedCorridorPortalIds[0] != key.GoalId)
        {
            throw new InvalidOperationException(
                $"BuildCommittedFunnelCorridorFixed failed: committed corridor is absent or inconsistent key={FormatTileKey(key)}, handle={FormatPathHandle(handle)}.");
        }

        return new PathHandle
        {
            WorldVersion = key.WorldVersion,
            GoalX = handle.CommittedCorridorGoalX,
            GoalY = handle.CommittedCorridorGoalY,
            SectorIds = handle.CommittedCorridorSectorIds,
            PortalIds = handle.CommittedCorridorPortalIds,
            CurrentSectorIndex = 0,
            BuildSource = "committedCorridor"
        };
    }

    private static bool DoesPortalLookaheadRayCrossCurrentApertureFixed(
        PathHandle handle,
        FixVector2 position,
        FixVector2 target)
    {
        int portalPathIndex = handle.CurrentSectorIndex;
        ResolvePortalFunnelSegmentFixed(handle, portalPathIndex, out FixVector2 left, out FixVector2 right);
        PortalData portal = GetPortalById(_world, handle.PortalIds[portalPathIndex]);
        FixVector2 displacement = target - position;
        int currentSectorId = handle.SectorIds[portalPathIndex];
        int downstreamSectorId = handle.SectorIds[portalPathIndex + 1];
        Vector2Int[] currentCells = GetPortalCellsForSector(portal, currentSectorId);
        Vector2Int[] downstreamCells = GetPortalCellsForSector(portal, downstreamSectorId);
        FixVector2 travel = _world.GridToWorldCenterFixed(downstreamCells[0].x, downstreamCells[0].y)
                            - _world.GridToWorldCenterFixed(currentCells[0].x, currentCells[0].y);

        Fix64 normalDisplacement = portal.IsVerticalBoundary ? displacement.x : displacement.y;
        Fix64 normalTravel = portal.IsVerticalBoundary ? travel.x : travel.y;
        if (normalDisplacement == Fix64.Zero || normalDisplacement * normalTravel <= Fix64.Zero)
            return false;

        Fix64 plane = portal.IsVerticalBoundary ? left.x : left.y;
        Fix64 normalPosition = portal.IsVerticalBoundary ? position.x : position.y;
        Fix64 planeDelta = plane - normalPosition;
        if (normalDisplacement > Fix64.Zero)
        {
            if (planeDelta < Fix64.Zero || planeDelta > normalDisplacement)
                return false;
        }
        else if (planeDelta > Fix64.Zero || planeDelta < normalDisplacement)
        {
            return false;
        }

        Fix64 tangentPosition = portal.IsVerticalBoundary ? position.y : position.x;
        Fix64 tangentDisplacement = portal.IsVerticalBoundary ? displacement.y : displacement.x;
        Fix64 leftTangent = portal.IsVerticalBoundary ? left.y : left.x;
        Fix64 rightTangent = portal.IsVerticalBoundary ? right.y : right.x;
        Fix64 intersectionNumerator = (tangentPosition - leftTangent) * normalDisplacement
                                     + tangentDisplacement * planeDelta;
        Fix64 rightNumerator = (rightTangent - leftTangent) * normalDisplacement;
        Fix64 minimumNumerator = Fix64.Min(Fix64.Zero, rightNumerator);
        Fix64 maximumNumerator = Fix64.Max(Fix64.Zero, rightNumerator);
        return intersectionNumerator >= minimumNumerator
               && intersectionNumerator <= maximumNumerator;
    }

    private static bool TryResolvePortalCorridorFunnelVelocityFixed(
        AgentRuntimeData agent,
        PathHandle handle,
        FlowTileCacheKey key,
        FixVector2 position,
        Fix64 maxSpeed,
        bool currentPortalReached,
        out FixVector2 velocity,
        out string diagnostic)
    {
        velocity = FixVector2.Zero;
        diagnostic = null;
        if (handle?.PortalIds == null
            || handle.CurrentSectorIndex < 0
            || handle.CurrentSectorIndex >= handle.PortalIds.Length)
        {
            return false;
        }
        PathHandle committedCorridor = BuildCommittedFunnelCorridorFixed(handle, key);
        int portalEndPathIndex = committedCorridor.PortalIds.Length;
        FixVector2 terminal = _world.GridToWorldCenterFixed(
            committedCorridor.GoalX,
            committedCorridor.GoalY);

        string portalLookahead = "not-requested";
        FixVector2 target;
        int cornerPortalPathIndex;
        if (currentPortalReached)
        {
            FixVector2 lookaheadTarget = ResolvePortalCorridorFunnelTargetFixed(
                committedCorridor,
                position,
                committedCorridor.CurrentSectorIndex + 1,
                portalEndPathIndex,
                terminal,
                out int lookaheadCornerPortalPathIndex);
            if (DoesPortalLookaheadRayCrossCurrentApertureFixed(committedCorridor, position, lookaheadTarget))
            {
                target = lookaheadTarget;
                cornerPortalPathIndex = lookaheadCornerPortalPathIndex;
                portalLookahead = "accepted";
            }
            else
            {
                target = ResolvePortalCorridorFunnelTargetFixed(
                    committedCorridor,
                    position,
                    committedCorridor.CurrentSectorIndex,
                    portalEndPathIndex,
                    terminal,
                    out cornerPortalPathIndex);
                portalLookahead = "rejected";
            }
        }
        else
        {
            target = ResolvePortalCorridorFunnelTargetFixed(
                committedCorridor,
                position,
                committedCorridor.CurrentSectorIndex,
                portalEndPathIndex,
                terminal,
                out cornerPortalPathIndex);
        }
        FixVector2 displacement = target - position;
        if (FixVector2.SqrMagnitude(displacement) == Fix64.Zero)
        {
            diagnostic =
                $"corridor-funnel-rejected reason=subresolution-displacement portalLookahead={portalLookahead} cornerPathIndex={cornerPortalPathIndex} " +
                $"targetRaw=({target.x.RawValue},{target.y.RawValue})";
            return false;
        }
        if (!HasFixedGridLineOfSight(_world, position, target, allowTargetSoftCost: true))
        {
            diagnostic =
                $"corridor-funnel-rejected reason=grid-los-failed portalLookahead={portalLookahead} cornerPathIndex={cornerPortalPathIndex} " +
                $"targetRaw=({target.x.RawValue},{target.y.RawValue})";
            return false;
        }
        if (!LogicStaticCollisionShadowService.TrySolveFixed(
                agent.AgentTypeId,
                position,
                displacement,
                agent.RadiusFixed,
                out LogicStaticCollisionShadowResult solveResult))
        {
            throw new InvalidOperationException(
                $"TryResolvePortalCorridorFunnelVelocityFixed failed: static collision world is unavailable for agentType={agent.AgentTypeId}.");
        }
        if (!solveResult.SolveResult.Success)
        {
            throw new InvalidOperationException(
                $"TryResolvePortalCorridorFunnelVelocityFixed failed: direct corridor query failed for agent={agent.Id}, failure={solveResult.SolveResult.Failure}.");
        }
        if (solveResult.SolveResult.ResolvedDisplacement != displacement)
        {
            diagnostic =
                $"corridor-funnel-rejected reason=static-sweep-clipped portalLookahead={portalLookahead} cornerPathIndex={cornerPortalPathIndex} " +
                $"targetRaw=({target.x.RawValue},{target.y.RawValue}) " +
                $"desiredRaw=({displacement.x.RawValue},{displacement.y.RawValue}) " +
                $"resolvedRaw=({solveResult.SolveResult.ResolvedDisplacement.x.RawValue},{solveResult.SolveResult.ResolvedDisplacement.y.RawValue})";
            return false;
        }

        velocity = ScaleFixedDirectionToSpeed(displacement, maxSpeed);
        diagnostic =
            $"corridor-funnel portalLookahead={portalLookahead} cornerPathIndex={cornerPortalPathIndex} " +
            $"targetRaw=({target.x.RawValue},{target.y.RawValue}) corridor={FormatPathHandle(committedCorridor)}";
        return true;
    }

    private static FixVector2 ResolveDeterministicFlowVelocityFixed(
        IEntityContext self,
        AgentRuntimeData agent,
        Fix64 maxSpeed)
    {
        AgentNavState nav = agent.NavState;
        int flowFrame = GetFrameCount();
        FixVector2 recentFlowVelocity = nav.LastFixedFlowFrame == flowFrame
                                        || nav.LastFixedFlowFrame == flowFrame - 1
            ? nav.LastFixedFlowVelocity
            : FixVector2.Zero;
        nav.LastFixedFlowFrame = flowFrame;
        nav.LastFixedFlowVelocity = FixVector2.Zero;
        if (!nav.HasGoal)
            throw new InvalidOperationException("ResolveDeterministicFlowVelocityFixed failed: resolved navigation goal is missing.");
        FixVector2 resolvedNavigationGoal = nav.LastGoalWorldFixed;
        if (_world == null)
            throw new InvalidOperationException("ResolveDeterministicFlowVelocityFixed failed: world is null.");
        PathHandle handle = agent.NavState.PathHandle;
        if (handle == null || handle.SectorIds == null || handle.SectorIds.Length == 0)
        {
            nav.LastFixedFlowResult = "handle-empty";
            return FixVector2.Zero;
        }
        if (handle.CurrentSectorIndex < 0 || handle.CurrentSectorIndex >= handle.SectorIds.Length)
            throw new InvalidOperationException("ResolveDeterministicFlowVelocityFixed failed: path sector index is invalid.");

        FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(
            handle,
            handle.CurrentSectorIndex,
            handle.GoalX,
            handle.GoalY,
            agent.AgentTypeId,
            out TileGoalKind goalKind,
            out _);

        FixVector2 position = agent.PositionFixed;
        if (!_world.WorldToGridFixed(position, out int worldX, out int worldY))
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicFlowVelocityFixed failed: position is outside world. entity={self.LogicEntityId.Value}, raw=({position.x.RawValue},{position.y.RawValue}).");
        }

        bool hasCachedTile = DeterministicFlowTileCache.TryGetValue(key, out FlowTileCacheEntry tile);
        bool hasPendingRuntimeDirty = HasPendingRuntimeDirty(_activeWorldState);
        if (hasPendingRuntimeDirty && FixVector2.SqrMagnitude(recentFlowVelocity) == Fix64.Zero)
        {
            nav.LastFixedFlowResult = $"runtime-dirty-no-committed-flow key={FormatTileKey(key)}";
            return FixVector2.Zero;
        }
        if (hasPendingRuntimeDirty
            && !hasCachedTile
            && FixVector2.SqrMagnitude(recentFlowVelocity) > Fix64.Zero)
        {
            FixVector2 continuedVelocity = ScaleFixedDirectionToSpeed(recentFlowVelocity, maxSpeed);
            nav.LastFixedFlowVelocity = continuedVelocity;
            nav.LastFixedFlowResult = $"tile-pending-last-flow key={FormatTileKey(key)}";
            return continuedVelocity;
        }

        bool directStaticClear = false;
        bool directCostClear = false;
        FixVector2 toNavigationGoal = resolvedNavigationGoal - position;
        if (goalKind == TileGoalKind.FinalGoal
            && FixVector2.SqrMagnitude(toNavigationGoal) > Fix64.Zero
            && (!hasPendingRuntimeDirty || !hasCachedTile))
        {
            bool profile = MainThreadFrameProfiler.LoggingEnabled;
            long directStaticStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
            if (!LogicStaticCollisionShadowService.TrySolveFixed(
                    agent.AgentTypeId,
                    position,
                    toNavigationGoal,
                    agent.RadiusFixed,
                    out LogicStaticCollisionShadowResult directPathResult))
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowVelocityFixed failed: static collision world is unavailable for agentType={agent.AgentTypeId}.");
            }
            if (!directPathResult.SolveResult.Success)
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowVelocityFixed failed: direct path query failed for entity={self.LogicEntityId.Value}, " +
                    $"failure={directPathResult.SolveResult.Failure}.");
            }
            if (profile)
            {
                MainThreadFrameProfiler.Record(
                    MainThreadPerfScope.FlowSteeringDirectStatic,
                    Stopwatch.GetTimestamp() - directStaticStartTicks);
            }
            directStaticClear = directPathResult.SolveResult.ResolvedDisplacement == toNavigationGoal;
            if (!hasPendingRuntimeDirty)
            {
                long directLineOfSightStartTicks = profile ? Stopwatch.GetTimestamp() : 0L;
                directCostClear = HasFixedGridLineOfSight(
                    _world,
                    position,
                    resolvedNavigationGoal,
                    allowTargetSoftCost: true);
                if (profile)
                {
                    MainThreadFrameProfiler.Record(
                        MainThreadPerfScope.FlowSteeringDirectLineOfSight,
                        Stopwatch.GetTimestamp() - directLineOfSightStartTicks);
                }
            }
            if (directStaticClear && directCostClear)
            {
                FixVector2 directVelocity = ScaleFixedDirectionToSpeed(toNavigationGoal, maxSpeed);
                nav.LastFixedFlowVelocity = directVelocity;
                nav.LastFixedFlowResult =
                    $"direct-static-clear cell=({worldX},{worldY}) goalRaw=({resolvedNavigationGoal.x.RawValue},{resolvedNavigationGoal.y.RawValue}) key={FormatTileKey(key)}";
                return directVelocity;
            }
        }
        if (!hasCachedTile)
        {
            long requiredCommitStartTicks = Stopwatch.GetTimestamp();
            int requiredCommitCount = CommitRequiredDeterministicFlowTilePayload(key);
            _perf.RequiredFlowTileCommits += requiredCommitCount;
            _perf.FlowTileQueueTicks += Stopwatch.GetTimestamp() - requiredCommitStartTicks;
            if (requiredCommitCount <= 0
                || !DeterministicFlowTileCache.TryGetValue(key, out tile))
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowVelocityFixed failed: required current tile was not committed key={FormatTileKey(key)}.");
            }

            hasCachedTile = true;
        }
        if (tile.DeterministicIntegrationCosts == null
            || tile.DeterministicIntegrationCosts.Length != tile.Width * tile.Height
            || tile.DeterministicFlowDirectionIndices == null
            || tile.DeterministicFlowDirectionIndices.Length != tile.Width * tile.Height)
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicFlowVelocityFixed failed: deterministic tile payload is invalid key={FormatTileKey(key)}.");
        }
        if (!IsInsideSector(tile, worldX, worldY))
        {
            nav.LastFixedFlowResult = $"outside-tile cell=({worldX},{worldY}) tile=({tile.StartX},{tile.StartY},{tile.Width},{tile.Height})";
            return FixVector2.Zero;
        }

        int localIndex = tile.GetLocalIndex(worldX, worldY);
        if (tile.DeterministicIntegrationCosts[localIndex] == int.MaxValue)
        {
            nav.LastFixedFlowResult = $"unreachable cell=({worldX},{worldY}) key={FormatTileKey(key)}";
            return FixVector2.Zero;
        }
        int recommendedPortalSlotIndexForDiagnostic = -1;
        int selectedPortalSlotIndexForDiagnostic = -1;
        if (goalKind == TileGoalKind.Portal)
        {
            if (!handle.HasCommittedCurrentTileKey || !handle.CommittedCurrentTileKey.Equals(key))
                CommitCurrentFunnelCorridor(handle, key);
            handle.HasCommittedCurrentTileKey = true;
            handle.CommittedCurrentTileKey = key;
            if (tile.DeterministicPortalTargetSlotIndices == null
                || tile.DeterministicPortalTargetSlotIndices.Length != tile.Width * tile.Height)
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowVelocityFixed failed: portal target slots are invalid key={FormatTileKey(key)}.");
            }

            int recommendedPortalSlotIndex = tile.DeterministicPortalTargetSlotIndices[localIndex] - 1;
            PortalData portal = GetPortalById(_world, key.GoalId);
            Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, GetOppositeSectorId(portal, key.SectorId));
            if (recommendedPortalSlotIndex < 0 || recommendedPortalSlotIndex >= oppositeCells.Length)
            {
                throw new InvalidOperationException(
                    $"ResolveDeterministicFlowVelocityFixed failed: portal target slot is invalid slot={recommendedPortalSlotIndex}, key={FormatTileKey(key)}.");
            }

            int selectedPortalSlotIndex = ResolveStablePortalTraversalSlotIndex(
                nav,
                key,
                recommendedPortalSlotIndex,
                oppositeCells.Length,
                recommendationFromCommittedTile: true);
            recommendedPortalSlotIndexForDiagnostic = recommendedPortalSlotIndex;
            selectedPortalSlotIndexForDiagnostic = selectedPortalSlotIndex;
        }
        string funnelDiagnostic = null;
        bool currentPortalReached = goalKind == TileGoalKind.Portal
                                    && IndexOfGoalCell(tile.GoalCells, worldX, worldY) >= 0;
        if (goalKind == TileGoalKind.Portal
            && !hasPendingRuntimeDirty)
        {
            if (TryResolvePortalCorridorFunnelVelocityFixed(
                    agent,
                    handle,
                    key,
                    position,
                    maxSpeed,
                    currentPortalReached,
                    out FixVector2 funnelVelocity,
                    out funnelDiagnostic))
            {
                nav.LastFixedFlowVelocity = funnelVelocity;
                nav.LastFixedFlowResult = funnelDiagnostic;
                return funnelVelocity;
            }
        }
        byte directionIndex = tile.DeterministicFlowDirectionIndices[localIndex];
        if (directionIndex == 0)
        {
            if (goalKind != TileGoalKind.FinalGoal)
            {
                FixVector2 portalHandoffVelocity = ResolvePortalGoalCellVelocityFixed(
                    tile,
                    position,
                    worldX,
                    worldY,
                    maxSpeed);
                nav.LastFixedFlowVelocity = portalHandoffVelocity;
                nav.LastFixedFlowResult = $"portal-handoff cell=({worldX},{worldY}) key={FormatTileKey(key)}";
                return portalHandoffVelocity;
            }
            FixVector2 toGoal = resolvedNavigationGoal - position;
            FixVector2 finalGoalVelocity = FixVector2.SqrMagnitude(toGoal) > Fix64.Zero
                ? ScaleFixedDirectionToSpeed(toGoal, maxSpeed)
                : FixVector2.Zero;
            nav.LastFixedFlowVelocity = finalGoalVelocity;
            nav.LastFixedFlowResult = "final-goal";
            return finalGoalVelocity;
        }

        int offsetIndex = directionIndex - 1;
        if (offsetIndex < 0 || offsetIndex >= NeighborOffsetX.Length)
            throw new InvalidOperationException($"ResolveDeterministicFlowVelocityFixed failed: invalid direction {directionIndex}.");
        long gradientX;
        long gradientY;
        FixVector2 direction = ResolveSpatiallyInterpolatedDeterministicGradientFixed(
            handle,
            agent,
            tile,
            position,
            worldX,
            worldY,
            localIndex,
            out gradientX,
            out gradientY);
        if (direction == FixVector2.Zero)
            direction = new FixVector2(NeighborOffsetX[offsetIndex], NeighborOffsetY[offsetIndex]);
        FixVector2 result = ResolveSpatiallyIntegratedFieldVelocityFixed(
            handle,
            agent,
            tile,
            null,
            null,
            position,
            direction,
            maxSpeed,
            out int integrationSubsteps,
            out int domainBoundarySubsteps,
            out int sampledTileTransitions);
        nav.LastFixedFlowVelocity = result;
        nav.LastFixedFlowResult =
            $"direction={directionIndex}/gradient=({gradientX},{gradientY})/gradientFixedRaw=({direction.x.RawValue},{direction.y.RawValue})" +
            $"/integrationSubsteps={integrationSubsteps}" +
            $"/domainBoundarySubsteps={domainBoundarySubsteps}" +
            $"/sampledTileTransitions={sampledTileTransitions}" +
            $"/cell=({worldX},{worldY})/cost={tile.DeterministicIntegrationCosts[localIndex]}" +
            $"/portalSlot={recommendedPortalSlotIndexForDiagnostic}:{selectedPortalSlotIndexForDiagnostic}" +
            $"/portalGoals={(goalKind == TileGoalKind.Portal ? FormatGoalCells(tile.GoalCells) : "n/a")}" +
            $"/directStaticClear={directStaticClear}/directCostClear={directCostClear}" +
            $"/funnel={(funnelDiagnostic ?? "not-evaluated")}";
        return result;
    }

    private static FixVector2 ResolvePortalGoalDownstreamTraceFixed(
        FlowTileCacheKey steeringKey,
        PortalData portal,
        int portalGoalIndex,
        FixVector2 position,
        Vector2Int currentCell,
        Vector2Int downstreamCell)
    {
        if (portal == null)
            throw new InvalidOperationException("ResolvePortalGoalDownstreamTraceFixed failed: portal is null.");
        if (steeringKey.GoalKind != TileGoalKind.Portal || steeringKey.GoalId != portal.PortalId)
        {
            throw new InvalidOperationException(
                $"ResolvePortalGoalDownstreamTraceFixed failed: steering key does not own portal key={FormatTileKey(steeringKey)}, portal={portal.PortalId}.");
        }

        int downstreamSectorId = GetOppositeSectorId(portal, steeringKey.SectorId);
        if (!_world.TryGetSectorId(downstreamCell.x, downstreamCell.y, out int pairedSectorId)
            || pairedSectorId != downstreamSectorId)
        {
            throw new InvalidOperationException(
                $"ResolvePortalGoalDownstreamTraceFixed failed: paired cell sector mismatch cell=({downstreamCell.x},{downstreamCell.y}), expected={downstreamSectorId}, actual={pairedSectorId}.");
        }

        FixVector2 currentCenter = _world.GridToWorldCenterFixed(currentCell.x, currentCell.y);
        FixVector2 downstreamCenter = _world.GridToWorldCenterFixed(downstreamCell.x, downstreamCell.y);
        FixVector2 downstreamPosition = position + downstreamCenter - currentCenter;
        FixVector2 downstreamDirection;
        bool downstreamIsFinalSector = steeringKey.DownstreamGoalHint < 0;
        if (downstreamIsFinalSector)
        {
            FlowTileCacheKey downstreamKey = CreatePortalContinuationFinalTileKey(steeringKey, downstreamSectorId);
            if (!DeterministicFlowTileCache.TryGetValue(downstreamKey, out FlowTileCacheEntry downstreamTile))
            {
                throw new InvalidOperationException(
                    $"ResolvePortalGoalDownstreamTraceFixed failed: downstream final tile is unavailable key={FormatTileKey(downstreamKey)}.");
            }
            downstreamTile.LastUsedFrame = GetFrameCount();

            int downstreamLocalIndex = downstreamTile.GetLocalIndex(downstreamCell.x, downstreamCell.y);
            byte downstreamDirectionIndex = downstreamTile.DeterministicFlowDirectionIndices[downstreamLocalIndex];
            if (downstreamDirectionIndex == 0)
            {
                int finalGoalX = steeringKey.FinalGoalIndex % _world.Width;
                int finalGoalY = steeringKey.FinalGoalIndex / _world.Width;
                downstreamDirection = _world.GridToWorldCenterFixed(finalGoalX, finalGoalY) - downstreamPosition;
            }
            else
            {
                downstreamDirection = ResolveSpatiallyInterpolatedDeterministicGradientFixed(
                    null,
                    null,
                    downstreamTile,
                    downstreamPosition,
                    downstreamCell.x,
                    downstreamCell.y,
                    downstreamLocalIndex,
                    out _,
                    out _);
            }
        }
        else
        {
            int nextPortalId = steeringKey.DownstreamGoalHint;
            SectorData downstreamSector = _world.Sectors[downstreamSectorId];
            SectorPortalAccessEntry downstreamAccess = GetPrebuiltSectorPortalAccess(
                downstreamSector,
                downstreamSectorId,
                nextPortalId);
            long downstreamCost = ResolveDeterministicPortalAccessIntegrationCost(
                _world,
                downstreamSector,
                downstreamAccess,
                downstreamCell.x,
                downstreamCell.y);
            downstreamDirection = ResolveSpatiallyInterpolatedPortalAccessGradientFixed(
                downstreamSector,
                downstreamAccess,
                downstreamPosition,
                downstreamCell.x,
                downstreamCell.y,
                downstreamCost,
                out _,
                out _);
        }

        int normalX = downstreamCell.x - currentCell.x;
        int normalY = downstreamCell.y - currentCell.y;
        if (Math.Abs(normalX) + Math.Abs(normalY) != 1)
        {
            throw new InvalidOperationException(
                $"ResolvePortalGoalDownstreamTraceFixed failed: portal pair is not cardinally adjacent current=({currentCell.x},{currentCell.y}), downstream=({downstreamCell.x},{downstreamCell.y}), slot={portalGoalIndex}.");
        }

        return portal.IsVerticalBoundary
            ? new FixVector2((Fix64)normalX, downstreamDirection.y)
            : new FixVector2(downstreamDirection.x, (Fix64)normalY);
    }

    private static FlowTileCacheKey CreatePortalContinuationFinalTileKey(
        FlowTileCacheKey portalTileKey,
        int downstreamSectorId)
    {
        if (portalTileKey.GoalKind != TileGoalKind.Portal || portalTileKey.DownstreamGoalHint >= 0)
        {
            throw new InvalidOperationException(
                $"CreatePortalContinuationFinalTileKey failed: key has no final continuation key={FormatTileKey(portalTileKey)}.");
        }
        if (portalTileKey.FinalGoalIndex < 0 || portalTileKey.FinalGoalIndex >= _world.Width * _world.Height)
        {
            throw new InvalidOperationException(
                $"CreatePortalContinuationFinalTileKey failed: final goal index is invalid key={FormatTileKey(portalTileKey)}.");
        }

        return new FlowTileCacheKey(
            portalTileKey.WorldVersion,
            downstreamSectorId,
            TileGoalKind.FinalGoal,
            portalTileKey.FinalGoalIndex,
            0,
            portalTileKey.FinalGoalIndex,
            portalTileKey.AgentTypeId,
            _world.Sectors[downstreamSectorId].DirtyVersion);
    }

    private static FixVector2 ResolveSpatiallyInterpolatedDeterministicGradientFixed(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry tile,
        FixVector2 position,
        int worldX,
        int worldY,
        int localIndex,
        out long currentGradientX,
        out long currentGradientY)
    {
        FixVector2 currentDirection = ResolveDeterministicIntegrationGradientFixed(
            tile,
            worldX,
            worldY,
            localIndex,
            false,
            0,
            0,
            0,
            out currentGradientX,
            out currentGradientY);

        ResolveSpatialGradientSampleGridFixed(
            position,
            worldX,
            worldY,
            out int x0,
            out int x1,
            out int y0,
            out int y1,
            out Fix64 tx,
            out Fix64 ty);
        Fix64 oneMinusX = Fix64.One - tx;
        Fix64 oneMinusY = Fix64.One - ty;
        FixVector2 weightedDirection = FixVector2.Zero;
        Fix64 totalWeight = Fix64.Zero;
        AccumulateSpatialGradientSample(handle, agent, tile, worldX, worldY, x0, y0, oneMinusX * oneMinusY, ref weightedDirection, ref totalWeight);
        AccumulateSpatialGradientSample(handle, agent, tile, worldX, worldY, x1, y0, tx * oneMinusY, ref weightedDirection, ref totalWeight);
        AccumulateSpatialGradientSample(handle, agent, tile, worldX, worldY, x0, y1, oneMinusX * ty, ref weightedDirection, ref totalWeight);
        AccumulateSpatialGradientSample(handle, agent, tile, worldX, worldY, x1, y1, tx * ty, ref weightedDirection, ref totalWeight);

        return totalWeight > Fix64.Zero && weightedDirection != FixVector2.Zero
            ? weightedDirection
            : currentDirection;
    }

    private static void ResolveSpatialGradientSampleGridFixed(
        FixVector2 position,
        int worldX,
        int worldY,
        out int x0,
        out int x1,
        out int y0,
        out int y1,
        out Fix64 tx,
        out Fix64 ty)
    {
        long positionXGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(position.x);
        long positionYGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(position.y);
        long centerXGridRaw = checked(_world.OriginXGridRaw + checked((long)worldX * _world.CellSizeGridRaw) + _world.CellSizeGridRaw / 2);
        long centerYGridRaw = checked(_world.OriginZGridRaw + checked((long)worldY * _world.CellSizeGridRaw) + _world.CellSizeGridRaw / 2);
        if (positionXGridRaw >= centerXGridRaw)
        {
            x0 = worldX;
            x1 = worldX + 1;
            tx = NavigationGridFixedMath.ResolveCellFraction(positionXGridRaw, centerXGridRaw, _world.CellSizeGridRaw);
        }
        else
        {
            x0 = worldX - 1;
            x1 = worldX;
            tx = NavigationGridFixedMath.ResolveCellFraction(
                positionXGridRaw,
                checked(centerXGridRaw - _world.CellSizeGridRaw),
                _world.CellSizeGridRaw);
        }

        if (positionYGridRaw >= centerYGridRaw)
        {
            y0 = worldY;
            y1 = worldY + 1;
            ty = NavigationGridFixedMath.ResolveCellFraction(positionYGridRaw, centerYGridRaw, _world.CellSizeGridRaw);
        }
        else
        {
            y0 = worldY - 1;
            y1 = worldY;
            ty = NavigationGridFixedMath.ResolveCellFraction(
                positionYGridRaw,
                checked(centerYGridRaw - _world.CellSizeGridRaw),
                _world.CellSizeGridRaw);
        }
    }

    private static void AccumulateSpatialGradientSample(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry tile,
        int currentX,
        int currentY,
        int sampleX,
        int sampleY,
        Fix64 weight,
        ref FixVector2 weightedDirection,
        ref Fix64 totalWeight)
    {
        if (weight <= Fix64.Zero || !IsInsideSector(tile, sampleX, sampleY))
            return;
        if ((sampleX != currentX || sampleY != currentY)
            && !CanTraverseNeighborCells(_world, currentX, currentY, sampleX, sampleY))
        {
            return;
        }
        if (sampleX != currentX
            && sampleY != currentY
            && !IsDiagonalPassable(_world, currentX, currentY, sampleX, sampleY))
        {
            return;
        }
        int sampleLocalIndex = tile.GetLocalIndex(sampleX, sampleY);
        if (tile.DeterministicIntegrationCosts[sampleLocalIndex] == int.MaxValue)
            return;

        int portalGoalIndex = tile.Key.GoalKind == TileGoalKind.Portal
            ? IndexOfGoalCell(tile.GoalCells, sampleX, sampleY)
            : -1;
        FixVector2 sampleDirection;
        if (portalGoalIndex >= 0)
        {
            if (handle == null || agent == null)
            {
                throw new InvalidOperationException(
                    $"AccumulateSpatialGradientSample failed: portal goal sampling requires path context key={FormatTileKey(tile.Key)}.");
            }

            PortalData portal = GetPortalById(_world, tile.Key.GoalId);
            Vector2Int[] oppositeCells = GetPortalCellsForSector(
                portal,
                GetOppositeSectorId(portal, tile.Key.SectorId));
            if (portalGoalIndex >= oppositeCells.Length)
            {
                throw new InvalidOperationException(
                    $"AccumulateSpatialGradientSample failed: portal goal pair is missing index={portalGoalIndex}, key={FormatTileKey(tile.Key)}.");
            }

            Vector2Int currentCell = tile.GoalCells[portalGoalIndex];
            sampleDirection = ResolvePortalGoalDownstreamTraceFixed(
                tile.Key,
                portal,
                portalGoalIndex,
                _world.GridToWorldCenterFixed(currentCell.x, currentCell.y),
                currentCell,
                oppositeCells[portalGoalIndex]);
        }
        else
        {
            sampleDirection = ResolveDeterministicIntegrationGradientFixed(
                tile,
                sampleX,
                sampleY,
                sampleLocalIndex,
                false,
                0,
                0,
                0,
                out _,
                out _);
        }
        if (sampleDirection == FixVector2.Zero)
        {
            byte storedDirection = tile.DeterministicFlowDirectionIndices[sampleLocalIndex];
            int offsetIndex = storedDirection - 1;
            if (offsetIndex < 0 || offsetIndex >= NeighborOffsetX.Length)
                return;
            sampleDirection = new FixVector2(NeighborOffsetX[offsetIndex], NeighborOffsetY[offsetIndex]);
        }

        weightedDirection += sampleDirection * weight;
        totalWeight += weight;
    }

    private static FixVector2 ResolveDeterministicIntegrationGradientFixed(
        FlowTileCacheEntry tile,
        int worldX,
        int worldY,
        int localIndex,
        bool hasExternalSample,
        int externalSampleX,
        int externalSampleY,
        int externalSampleCost,
        out long gradientX,
        out long gradientY)
    {
        int currentCost = tile.DeterministicIntegrationCosts[localIndex];
        if (currentCost == int.MaxValue)
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicIntegrationGradientFixed failed: current cell is unreachable cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");
        }

        gradientX = ResolveDeterministicIntegrationGradientAxis(
            tile,
            worldX,
            worldY,
            currentCost,
            -1,
            0,
            1,
            0,
            hasExternalSample,
            externalSampleX,
            externalSampleY,
            externalSampleCost);
        gradientY = ResolveDeterministicIntegrationGradientAxis(
            tile,
            worldX,
            worldY,
            currentCost,
            0,
            -1,
            0,
            1,
            hasExternalSample,
            externalSampleX,
            externalSampleY,
            externalSampleCost);
        long maximumMagnitude = Math.Max(Math.Abs(gradientX), Math.Abs(gradientY));
        if (maximumMagnitude == 0)
            return FixVector2.Zero;

        Fix64 scale = Fix64.FromRaw(maximumMagnitude);
        return new FixVector2(
            Fix64.FromRaw(gradientX) / scale,
            Fix64.FromRaw(gradientY) / scale);
    }

    private static long ResolveDeterministicIntegrationGradientAxis(
        FlowTileCacheEntry tile,
        int worldX,
        int worldY,
        int currentCost,
        int negativeOffsetX,
        int negativeOffsetY,
        int positiveOffsetX,
        int positiveOffsetY,
        bool hasExternalSample,
        int externalSampleX,
        int externalSampleY,
        int externalSampleCost)
    {
        bool hasNegative = TryGetDeterministicIntegrationGradientSample(
            tile,
            worldX,
            worldY,
            worldX + negativeOffsetX,
            worldY + negativeOffsetY,
            hasExternalSample,
            externalSampleX,
            externalSampleY,
            externalSampleCost,
            out int negativeCost);
        bool hasPositive = TryGetDeterministicIntegrationGradientSample(
            tile,
            worldX,
            worldY,
            worldX + positiveOffsetX,
            worldY + positiveOffsetY,
            hasExternalSample,
            externalSampleX,
            externalSampleY,
            externalSampleCost,
            out int positiveCost);

        if (hasNegative && hasPositive)
            return (long)negativeCost - positiveCost;
        if (hasNegative)
            return Math.Min(0L, negativeCost - (long)currentCost);
        if (hasPositive)
            return Math.Max(0L, (long)currentCost - positiveCost);
        return 0L;
    }

    private static bool TryGetDeterministicIntegrationGradientSample(
        FlowTileCacheEntry tile,
        int worldX,
        int worldY,
        int sampleX,
        int sampleY,
        bool hasExternalSample,
        int externalSampleX,
        int externalSampleY,
        int externalSampleCost,
        out int cost)
    {
        if (hasExternalSample && sampleX == externalSampleX && sampleY == externalSampleY)
        {
            cost = externalSampleCost;
            return true;
        }

        cost = int.MaxValue;
        if (!IsInsideSector(tile, sampleX, sampleY)
            || !CanTraverseSamplePath(_world, worldX, worldY, sampleX, sampleY))
        {
            return false;
        }

        cost = tile.DeterministicIntegrationCosts[tile.GetLocalIndex(sampleX, sampleY)];
        return cost != int.MaxValue;
    }

    private static FixVector2 ResolvePendingPortalVelocityFixed(
        AgentRuntimeData agent,
        FlowTileCacheKey key,
        FixVector2 position,
        int worldX,
        int worldY,
        Fix64 maxSpeed,
        out long portalAccessCost,
        out int directionIndex,
        out int portalSlotIndex,
        out string portalTraversalDiagnostic)
    {
        portalAccessCost = long.MaxValue;
        directionIndex = 0;
        portalSlotIndex = -1;
        portalTraversalDiagnostic = "portalTraversal=unresolved";
        if (agent == null)
            throw new InvalidOperationException("ResolvePendingPortalVelocityFixed failed: agent is null.");
        if (key.GoalKind != TileGoalKind.Portal)
            throw new InvalidOperationException($"ResolvePendingPortalVelocityFixed failed: key is not a portal goal key={FormatTileKey(key)}.");
        if (key.SectorId != agent.NavState.CurrentSectorId)
        {
            throw new InvalidOperationException(
                $"ResolvePendingPortalVelocityFixed failed: current sector mismatch key={key.SectorId}, nav={agent.NavState.CurrentSectorId}.");
        }

        PortalData portal = GetPortalById(_world, key.GoalId);
        Vector2Int[] currentCells = GetPortalCellsForSector(portal, key.SectorId);
        Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, GetOppositeSectorId(portal, key.SectorId));
        if (currentCells.Length == 0 || currentCells.Length != oppositeCells.Length)
        {
            throw new InvalidOperationException(
                $"ResolvePendingPortalVelocityFixed failed: portal side cells are invalid portal={portal.PortalId}, current={currentCells.Length}, opposite={oppositeCells.Length}.");
        }

        for (int i = 0; i < currentCells.Length; i++)
        {
            if (currentCells[i].x != worldX || currentCells[i].y != worldY)
                continue;

            int previousTraversalWorldVersion = agent.NavState.PortalTraversalWorldVersion;
            int previousTraversalSectorId = agent.NavState.PortalTraversalSectorId;
            int previousTraversalPortalId = agent.NavState.PortalTraversalId;
            int previousTraversalSlotIndex = agent.NavState.PortalTraversalSlotIndex;
            bool previousTraversalCommitted = agent.NavState.PortalTraversalHasCommittedTileSlot;
            portalSlotIndex = ResolveStablePortalTraversalSlotIndex(
                agent.NavState,
                key,
                i,
                oppositeCells.Length,
                recommendationFromCommittedTile: false);
            portalTraversalDiagnostic =
                $"portalTraversal=current-cell recommendedSlot={i} selectedSlot={portalSlotIndex} currentSlot={i} " +
                $"previousTraversal=({previousTraversalWorldVersion},{previousTraversalSectorId},{previousTraversalPortalId},{previousTraversalSlotIndex},committed={previousTraversalCommitted}) " +
                $"currentCells={FormatGoalCells(currentCells)} oppositeCells={FormatGoalCells(oppositeCells)} " +
                $"selectedOpposite=({oppositeCells[portalSlotIndex].x},{oppositeCells[portalSlotIndex].y}) cell=({worldX},{worldY})";
            if (TryResolveSharedBoundaryPortalHandoffTargetFixed(
                    agent,
                    key,
                    portal,
                    portalSlotIndex,
                    position,
                    worldX,
                    worldY,
                    out FixVector2 handoffTarget,
                    out string handoffDiagnostic))
            {
                portalTraversalDiagnostic += " " + handoffDiagnostic;
                return ScaleFixedDirectionToSpeed(handoffTarget - position, maxSpeed);
            }
            if (key.DownstreamGoalHint >= 0)
            {
                FixVector2 continuationDirection = ResolvePortalGoalDownstreamTraceFixed(
                    key,
                    portal,
                    portalSlotIndex,
                    position,
                    currentCells[portalSlotIndex],
                    oppositeCells[portalSlotIndex]);
                if (continuationDirection == FixVector2.Zero)
                {
                    throw new InvalidOperationException(
                        $"ResolvePendingPortalVelocityFixed failed: portal continuation direction is zero portal={portal.PortalId}, slot={portalSlotIndex}.");
                }
                portalTraversalDiagnostic +=
                    $" portalContinuationRaw=({continuationDirection.x.RawValue},{continuationDirection.y.RawValue})";
                return ScaleFixedDirectionToSpeed(continuationDirection, maxSpeed);
            }
            FixVector2 oppositeCellCenter = _world.GridToWorldCenterFixed(
                oppositeCells[portalSlotIndex].x,
                oppositeCells[portalSlotIndex].y);
            FixVector2 target = ResolvePortalApproachTargetFixed(
                position,
                currentCells[portalSlotIndex],
                oppositeCellCenter,
                portal.IsVerticalBoundary);
            return ScaleFixedDirectionToSpeed(target - position, maxSpeed);
        }

        SectorData sector = _world.Sectors[key.SectorId];
        if (!IsInsideSector(sector, worldX, worldY))
            throw new InvalidOperationException(
                $"ResolvePendingPortalVelocityFixed failed: current cell is outside sector cell=({worldX},{worldY}) sector={key.SectorId}.");

        SectorPortalAccessEntry access = GetPrebuiltSectorPortalAccess(sector, key.SectorId, portal.PortalId);
        portalAccessCost = ResolveDeterministicPortalAccessIntegrationCost(
            _world,
            sector,
            access,
            worldX,
            worldY);
        if (portalAccessCost == long.MaxValue)
        {
            throw new InvalidOperationException(
                $"ResolvePendingPortalVelocityFixed failed: current cell cannot reach portal agent={agent.Id}, " +
                $"cell=({worldX},{worldY}), portal={portal.PortalId}, sector={key.SectorId}.");
        }

        int recommendedPortalSlotIndex = ResolvePendingPortalTargetSlotIndex(
            sector,
            access,
            currentCells,
            worldX,
            worldY,
            portalAccessCost);
        int previousWorldVersion = agent.NavState.PortalTraversalWorldVersion;
        int previousSectorId = agent.NavState.PortalTraversalSectorId;
        int previousPortalId = agent.NavState.PortalTraversalId;
        int previousSlotIndex = agent.NavState.PortalTraversalSlotIndex;
        bool previousCommitted = agent.NavState.PortalTraversalHasCommittedTileSlot;
        portalSlotIndex = ResolveStablePortalTraversalSlotIndex(
            agent.NavState,
            key,
            recommendedPortalSlotIndex,
            oppositeCells.Length,
            recommendationFromCommittedTile: false);
        Vector2Int selectedOppositeCell = oppositeCells[portalSlotIndex];
        portalTraversalDiagnostic =
            $"portalTraversal=access-field recommendedSlot={recommendedPortalSlotIndex} selectedSlot={portalSlotIndex} currentSlot=-1 " +
            $"previousTraversal=({previousWorldVersion},{previousSectorId},{previousPortalId},{previousSlotIndex},committed={previousCommitted}) " +
            $"currentCells={FormatGoalCells(currentCells)} oppositeCells={FormatGoalCells(oppositeCells)} " +
            $"selectedOpposite=({selectedOppositeCell.x},{selectedOppositeCell.y}) cell=({worldX},{worldY})";
        if (!TryResolveLowestPortalAccessNeighbor(
                sector,
                access,
                worldX,
                worldY,
                portalAccessCost,
                out int bestDirectionIndex,
                out _))
        {
            throw new InvalidOperationException(
                $"ResolvePendingPortalVelocityFixed failed: portal access field has no descending neighbor agent={agent.Id}, " +
                $"cell=({worldX},{worldY}), cost={portalAccessCost}, portal={portal.PortalId}, sector={key.SectorId}.");
        }

        directionIndex = bestDirectionIndex + 1;
        FixVector2 direction = ResolveSpatiallyInterpolatedPortalAccessGradientFixed(
            sector,
            access,
            position,
            worldX,
            worldY,
            portalAccessCost,
            out long gradientX,
            out long gradientY);
        if (direction == FixVector2.Zero)
        {
            direction = new FixVector2(
                NeighborOffsetX[bestDirectionIndex],
                NeighborOffsetY[bestDirectionIndex]);
        }
        portalTraversalDiagnostic +=
            $" accessGradient=({gradientX},{gradientY}) accessGradientFixedRaw=({direction.x.RawValue},{direction.y.RawValue})";
        FixVector2 velocity = ResolveSpatiallyIntegratedFieldVelocityFixed(
            null,
            null,
            null,
            sector,
            access,
            position,
            direction,
            maxSpeed,
            out int integrationSubsteps,
            out int domainBoundarySubsteps,
            out int sampledTileTransitions);
        portalTraversalDiagnostic +=
            $" integrationSubsteps={integrationSubsteps} domainBoundarySubsteps={domainBoundarySubsteps} " +
            $"sampledTileTransitions={sampledTileTransitions}";
        return velocity;
    }

    private static FixVector2 ResolveSpatiallyIntegratedFieldVelocityFixed(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry tile,
        SectorData portalAccessSector,
        SectorPortalAccessEntry portalAccess,
        FixVector2 position,
        FixVector2 initialDirection,
        Fix64 maxSpeed,
        out int substepCount,
        out int domainBoundarySubsteps,
        out int sampledTileTransitions)
    {
        bool samplesTile = tile != null;
        bool samplesPortalAccess = portalAccessSector != null && portalAccess != null;
        if (samplesTile == samplesPortalAccess)
            throw new InvalidOperationException("ResolveSpatiallyIntegratedFieldVelocityFixed failed: exactly one spatial field is required.");
        if (initialDirection == FixVector2.Zero)
            throw new InvalidOperationException("ResolveSpatiallyIntegratedFieldVelocityFixed failed: initial direction is zero.");

        Fix64 deltaTime = LogicFrameRuntime.FixedDeltaTime;
        Fix64 travelDistance = maxSpeed * deltaTime;
        if (_world.CellSizeGridRaw <= 0)
            throw new InvalidOperationException("ResolveSpatiallyIntegratedFieldVelocityFixed failed: navigation cell size is not positive.");
        if (travelDistance <= Fix64.Zero)
        {
            substepCount = 0;
            domainBoundarySubsteps = 0;
            sampledTileTransitions = 0;
            return FixVector2.Zero;
        }

        substepCount = ResolveSpatialIntegrationSubstepCount(travelDistance, _world.CellSizeGridRaw);
        if (substepCount <= 0)
            throw new InvalidOperationException($"ResolveSpatiallyIntegratedFieldVelocityFixed failed: invalid substep count={substepCount}.");

        Fix64 substepDistance = travelDistance / (Fix64)substepCount;
        Fix64 half = Fix64.FromRaw(2048);
        FixVector2 integratedPosition = position;
        FixVector2 direction = initialDirection.GetNormalized();
        domainBoundarySubsteps = 0;
        sampledTileTransitions = 0;
        FlowTileCacheEntry sampledTile = tile;
        int sampledPathIndex = samplesTile ? handle.CurrentSectorIndex : -1;
        for (int i = 0; i < substepCount; i++)
        {
            if (samplesTile)
            {
                sampledTile = ResolveSpatialIntegrationTileForPosition(
                    handle,
                    agent,
                    sampledTile,
                    integratedPosition,
                    ref sampledPathIndex,
                    ref sampledTileTransitions);
                if (IsDeterministicFinalGoalFieldMinimum(sampledTile, integratedPosition))
                    return (integratedPosition - position) / deltaTime;
            }
            bool hasStepStartDirection;
            FixVector2 stepStartDirection = FixVector2.Zero;
            try
            {
                hasStepStartDirection = i > 0 && TryResolveSpatialFieldDirectionFixed(
                    handle,
                    agent,
                    sampledTile,
                    portalAccessSector,
                    portalAccess,
                    integratedPosition,
                    out stepStartDirection);
            }
            catch (InvalidOperationException exception)
            {
                throw new InvalidOperationException(
                    $"ResolveSpatiallyIntegratedFieldVelocityFixed failed at step start substep={i}/{substepCount}, " +
                    $"originRaw=({position.x.RawValue},{position.y.RawValue}), integratedRaw=({integratedPosition.x.RawValue},{integratedPosition.y.RawValue}), " +
                    $"directionRaw=({direction.x.RawValue},{direction.y.RawValue}), substepDistanceRaw={substepDistance.RawValue}.",
                    exception);
            }
            if (hasStepStartDirection)
            {
                direction = stepStartDirection.GetNormalized();
            }

            FixVector2 midpoint = integratedPosition + direction * substepDistance * half;
            bool midpointInFieldDomain = true;
            FlowTileCacheEntry midpointSampleTile = sampledTile;
            int midpointTileTransitions = 0;
            if (samplesTile)
            {
                midpointInFieldDomain = TryResolveSpatialIntegrationTileForCandidatePosition(
                    handle,
                    agent,
                    sampledTile,
                    midpoint,
                    sampledPathIndex,
                    out midpointSampleTile,
                    out _,
                    out midpointTileTransitions)
                    && IsSpatialFieldCandidateReachable(midpointSampleTile, null, null, midpoint);
                sampledTileTransitions += midpointTileTransitions;
                if (midpointInFieldDomain
                    && IsDeterministicFinalGoalFieldMinimum(midpointSampleTile, midpoint))
                {
                    return (midpoint - position) / deltaTime;
                }
            }
            bool hasMidpointDirection;
            FixVector2 midpointDirection = FixVector2.Zero;
            if (!midpointInFieldDomain)
            {
                midpointDirection = ResolveMonotoneSpatialFieldDirectionFixed(
                    handle,
                    agent,
                    sampledTile,
                    portalAccessSector,
                    portalAccess,
                    integratedPosition);
                hasMidpointDirection = true;
                domainBoundarySubsteps++;
            }
            else
            {
                try
                {
                    hasMidpointDirection = TryResolveSpatialFieldDirectionFixed(
                        handle,
                        agent,
                        midpointSampleTile,
                        portalAccessSector,
                        portalAccess,
                        midpoint,
                        out midpointDirection);
                }
                catch (InvalidOperationException exception)
                {
                    throw new InvalidOperationException(
                        $"ResolveSpatiallyIntegratedFieldVelocityFixed failed at midpoint substep={i}/{substepCount}, " +
                        $"originRaw=({position.x.RawValue},{position.y.RawValue}), integratedRaw=({integratedPosition.x.RawValue},{integratedPosition.y.RawValue}), " +
                        $"midpointRaw=({midpoint.x.RawValue},{midpoint.y.RawValue}), directionRaw=({direction.x.RawValue},{direction.y.RawValue}), " +
                        $"substepDistanceRaw={substepDistance.RawValue}.",
                        exception);
                }
            }
            if (hasMidpointDirection)
            {
                direction = midpointDirection.GetNormalized();
            }

            FixVector2 candidatePosition = integratedPosition + direction * substepDistance;
            FlowTileCacheEntry candidateTile = sampledTile;
            int candidatePathIndex = sampledPathIndex;
            int candidateTileTransitions = 0;
            bool candidateInFieldDomain = true;
            if (samplesTile)
            {
                candidateInFieldDomain = TryResolveSpatialIntegrationTileForCandidatePosition(
                    handle,
                    agent,
                    sampledTile,
                    candidatePosition,
                    sampledPathIndex,
                    out candidateTile,
                    out candidatePathIndex,
                    out candidateTileTransitions);
            }
            if (!candidateInFieldDomain
                || !IsSpatialFieldCandidateReachable(
                    candidateTile,
                    portalAccessSector,
                    portalAccess,
                    candidatePosition))
            {
                direction = ResolveMonotoneSpatialFieldDirectionFixed(
                    handle,
                    agent,
                    sampledTile,
                    portalAccessSector,
                    portalAccess,
                    integratedPosition).GetNormalized();
                candidatePosition = integratedPosition + direction * substepDistance;
                domainBoundarySubsteps++;
                candidateTile = sampledTile;
                candidatePathIndex = sampledPathIndex;
                candidateTileTransitions = 0;
                candidateInFieldDomain = true;
                if (samplesTile)
                {
                    candidateInFieldDomain = TryResolveSpatialIntegrationTileForCandidatePosition(
                        handle,
                        agent,
                        sampledTile,
                        candidatePosition,
                        sampledPathIndex,
                        out candidateTile,
                        out candidatePathIndex,
                        out candidateTileTransitions);
                }
                if (!candidateInFieldDomain
                    || !IsSpatialFieldCandidateReachable(
                        candidateTile,
                        portalAccessSector,
                        portalAccess,
                        candidatePosition))
                {
                    throw new InvalidOperationException(
                        $"ResolveSpatiallyIntegratedFieldVelocityFixed failed: monotone upwind step leaves the reachable domain " +
                        $"substep={i}/{substepCount}, integratedRaw=({integratedPosition.x.RawValue},{integratedPosition.y.RawValue}), " +
                        $"candidateRaw=({candidatePosition.x.RawValue},{candidatePosition.y.RawValue}), directionRaw=({direction.x.RawValue},{direction.y.RawValue}).");
                }
            }

            integratedPosition = candidatePosition;
            sampledTile = candidateTile;
            sampledPathIndex = candidatePathIndex;
            sampledTileTransitions += candidateTileTransitions;
        }

        return (integratedPosition - position) / deltaTime;
    }

    private static int ResolveSpatialIntegrationSubstepCount(Fix64 travelDistance, long cellSizeGridRaw)
    {
        int result = NavigationGridFixedMath.DivideCeilingByHalfCellSize(travelDistance, cellSizeGridRaw);
        if (result <= 0)
            throw new InvalidOperationException($"ResolveSpatialIntegrationSubstepCount failed: invalid result={result} travelRaw={travelDistance.RawValue} cellSizeGridRaw={cellSizeGridRaw}.");
        return result;
    }

    private static bool IsDeterministicFinalGoalFieldMinimum(
        FlowTileCacheEntry tile,
        FixVector2 position)
    {
        if (tile == null || tile.Key.GoalKind != TileGoalKind.FinalGoal)
            return false;
        if (!_world.WorldToGridFixed(position, out int worldX, out int worldY)
            || !IsInsideSector(tile, worldX, worldY)
            || worldX + worldY * _world.Width != tile.Key.FinalGoalIndex)
        {
            return false;
        }

        int localIndex = tile.GetLocalIndex(worldX, worldY);
        if (tile.DeterministicIntegrationCosts[localIndex] != 0
            || tile.DeterministicFlowDirectionIndices[localIndex] != 0)
        {
            throw new InvalidOperationException(
                $"IsDeterministicFinalGoalFieldMinimum failed: final goal cell is not a zero-cost minimum " +
                $"cell=({worldX},{worldY}), cost={tile.DeterministicIntegrationCosts[localIndex]}, " +
                $"direction={tile.DeterministicFlowDirectionIndices[localIndex]}, key={FormatTileKey(tile.Key)}.");
        }

        return true;
    }

    private static bool TryResolveSpatialIntegrationTileForCandidatePosition(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry currentTile,
        FixVector2 candidatePosition,
        int currentPathIndex,
        out FlowTileCacheEntry candidateTile,
        out int candidatePathIndex,
        out int candidateTileTransitions)
    {
        candidateTile = currentTile;
        candidatePathIndex = currentPathIndex;
        candidateTileTransitions = 0;
        if (!_world.WorldToGridFixed(candidatePosition, out int worldX, out int worldY)
            || !_world.TryGetSectorId(worldX, worldY, out int sectorId)
            || FindSectorIndex(handle, sectorId, handle.CurrentSectorIndex) < 0)
        {
            return false;
        }

        candidateTile = ResolveSpatialIntegrationTileForPosition(
            handle,
            agent,
            currentTile,
            candidatePosition,
            ref candidatePathIndex,
            ref candidateTileTransitions);
        return true;
    }

    private static FlowTileCacheEntry ResolveSpatialIntegrationTileForPosition(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry currentTile,
        FixVector2 position,
        ref int sectorPathIndex,
        ref int sampledTileTransitions)
    {
        if (handle == null || agent == null || currentTile == null)
            throw new InvalidOperationException("ResolveSpatialIntegrationTileForPosition failed: path, agent, or tile is null.");
        if (!_world.WorldToGridFixed(position, out int worldX, out int worldY)
            || !_world.TryGetSectorId(worldX, worldY, out int sectorId))
        {
            throw new InvalidOperationException(
                $"ResolveSpatialIntegrationTileForPosition failed: sample is outside navigation world raw=({position.x.RawValue},{position.y.RawValue}).");
        }
        if (currentTile.Key.SectorId == sectorId)
            return currentTile;

        int resolvedPathIndex = FindSectorIndex(handle, sectorId, handle.CurrentSectorIndex);
        if (resolvedPathIndex < 0)
        {
            throw new InvalidOperationException(
                $"ResolveSpatialIntegrationTileForPosition failed: sampled sector is not in the remaining path sector={sectorId}, " +
                $"committedIndex={handle.CurrentSectorIndex}, sampledIndex={sectorPathIndex}, cell=({worldX},{worldY}), handle={FormatPathHandle(handle)}.");
        }

        EnqueueActiveFlowTileBuilds(
            handle,
            resolvedPathIndex,
            handle.GoalX,
            handle.GoalY,
            agent.AgentTypeId);
        FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(
            handle,
            resolvedPathIndex,
            handle.GoalX,
            handle.GoalY,
            agent.AgentTypeId,
            out _,
            out _);
        if (!DeterministicFlowTileCache.TryGetValue(key, out FlowTileCacheEntry resolvedTile))
        {
            long requiredCommitStartTicks = Stopwatch.GetTimestamp();
            int requiredCommitCount = CommitRequiredDeterministicFlowTilePayload(key);
            _perf.RequiredFlowTileCommits += requiredCommitCount;
            _perf.FlowTileQueueTicks += Stopwatch.GetTimestamp() - requiredCommitStartTicks;
            if (requiredCommitCount <= 0
                || !DeterministicFlowTileCache.TryGetValue(key, out resolvedTile))
            {
                throw new InvalidOperationException(
                    $"ResolveSpatialIntegrationTileForPosition failed: sampled tile was not committed key={FormatTileKey(key)}.");
            }
        }

        resolvedTile.LastUsedFrame = GetFrameCount();
        sectorPathIndex = resolvedPathIndex;
        sampledTileTransitions++;
        return resolvedTile;
    }

    private static bool IsSpatialFieldCandidateReachable(
        FlowTileCacheEntry tile,
        SectorData portalAccessSector,
        SectorPortalAccessEntry portalAccess,
        FixVector2 position)
    {
        if (!_world.WorldToGridFixed(position, out int worldX, out int worldY))
            return false;
        if (tile != null)
        {
            return !IsInsideSector(tile, worldX, worldY)
                   || tile.DeterministicIntegrationCosts[tile.GetLocalIndex(worldX, worldY)] != int.MaxValue;
        }

        if (!IsInsideSector(portalAccessSector, worldX, worldY))
            return true;
        return ResolveDeterministicPortalAccessIntegrationCost(
                   _world,
                   portalAccessSector,
                   portalAccess,
                   worldX,
                   worldY)
               != long.MaxValue;
    }

    private static FixVector2 ResolveMonotoneSpatialFieldDirectionFixed(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry tile,
        SectorData portalAccessSector,
        SectorPortalAccessEntry portalAccess,
        FixVector2 position)
    {
        if (!_world.WorldToGridFixed(position, out int worldX, out int worldY))
            throw new InvalidOperationException("ResolveMonotoneSpatialFieldDirectionFixed failed: position is outside world.");
        if (tile != null)
        {
            if (!IsInsideSector(tile, worldX, worldY))
                throw new InvalidOperationException($"ResolveMonotoneSpatialFieldDirectionFixed failed: position is outside tile key={FormatTileKey(tile.Key)}.");
            int localIndex = tile.GetLocalIndex(worldX, worldY);
            if (tile.DeterministicIntegrationCosts[localIndex] == int.MaxValue)
                throw new InvalidOperationException($"ResolveMonotoneSpatialFieldDirectionFixed failed: current cell is unreachable cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");

            int portalGoalIndex = tile.Key.GoalKind == TileGoalKind.Portal
                ? IndexOfGoalCell(tile.GoalCells, worldX, worldY)
                : -1;
            if (portalGoalIndex >= 0)
            {
                PortalData portal = GetPortalById(_world, tile.Key.GoalId);
                Vector2Int[] oppositeCells = GetPortalCellsForSector(
                    portal,
                    GetOppositeSectorId(portal, tile.Key.SectorId));
                FixVector2 oppositeCellCenter = _world.GridToWorldCenterFixed(
                    oppositeCells[portalGoalIndex].x,
                    oppositeCells[portalGoalIndex].y);
                FixVector2 approachTarget = ResolvePortalApproachTargetFixed(
                    position,
                    tile.GoalCells[portalGoalIndex],
                    oppositeCellCenter,
                    portal.IsVerticalBoundary);
                return approachTarget - position;
            }

            int directionIndex = tile.DeterministicFlowDirectionIndices[localIndex] - 1;
            if (directionIndex < 0 || directionIndex >= NeighborOffsetX.Length)
            {
                throw new InvalidOperationException(
                    $"ResolveMonotoneSpatialFieldDirectionFixed failed: tile cell has no strict descending direction cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");
            }
            return new FixVector2(NeighborOffsetX[directionIndex], NeighborOffsetY[directionIndex]);
        }

        if (!IsInsideSector(portalAccessSector, worldX, worldY))
            throw new InvalidOperationException("ResolveMonotoneSpatialFieldDirectionFixed failed: position is outside portal access sector.");
        long currentCost = ResolveDeterministicPortalAccessIntegrationCost(
            _world,
            portalAccessSector,
            portalAccess,
            worldX,
            worldY);
        if (currentCost == long.MaxValue
            || !TryResolveLowestPortalAccessNeighbor(
                portalAccessSector,
                portalAccess,
                worldX,
                worldY,
                currentCost,
                out int bestDirectionIndex,
                out _))
        {
            throw new InvalidOperationException(
                $"ResolveMonotoneSpatialFieldDirectionFixed failed: portal access cell has no strict descending direction cell=({worldX},{worldY}), sector={portalAccessSector.SectorId}, portal={portalAccess.PortalId}.");
        }
        return new FixVector2(NeighborOffsetX[bestDirectionIndex], NeighborOffsetY[bestDirectionIndex]);
    }

    private static bool TryResolveSpatialFieldDirectionFixed(
        PathHandle handle,
        AgentRuntimeData agent,
        FlowTileCacheEntry tile,
        SectorData portalAccessSector,
        SectorPortalAccessEntry portalAccess,
        FixVector2 position,
        out FixVector2 direction)
    {
        direction = FixVector2.Zero;
        if (!_world.WorldToGridFixed(position, out int worldX, out int worldY))
            return false;

        if (tile != null)
        {
            if (!IsInsideSector(tile, worldX, worldY))
                return false;
            int localIndex = tile.GetLocalIndex(worldX, worldY);
            if (tile.DeterministicIntegrationCosts[localIndex] == int.MaxValue)
                throw new InvalidOperationException($"TryResolveSpatialFieldDirectionFixed failed: tile sample is unreachable cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");
            direction = ResolveSpatiallyInterpolatedDeterministicGradientFixed(
                handle,
                agent,
                tile,
                position,
                worldX,
                worldY,
                localIndex,
                out _,
                out _);
            if (direction != FixVector2.Zero)
                return true;

            byte storedDirection = tile.DeterministicFlowDirectionIndices[localIndex];
            int offsetIndex = storedDirection - 1;
            if (offsetIndex < 0 || offsetIndex >= NeighborOffsetX.Length)
                throw new InvalidOperationException($"TryResolveSpatialFieldDirectionFixed failed: tile sample has no direction cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");
            direction = new FixVector2(NeighborOffsetX[offsetIndex], NeighborOffsetY[offsetIndex]);
            return true;
        }

        if (!IsInsideSector(portalAccessSector, worldX, worldY))
            return false;
        long currentCost = ResolveDeterministicPortalAccessIntegrationCost(
            _world,
            portalAccessSector,
            portalAccess,
            worldX,
            worldY);
        if (currentCost == long.MaxValue)
        {
            throw new InvalidOperationException(
                $"TryResolveSpatialFieldDirectionFixed failed: portal access sample is unreachable cell=({worldX},{worldY}), " +
                $"sector={portalAccessSector.SectorId}, portal={portalAccess.PortalId}.");
        }

        direction = ResolveSpatiallyInterpolatedPortalAccessGradientFixed(
            portalAccessSector,
            portalAccess,
            position,
            worldX,
            worldY,
            currentCost,
            out _,
            out _);
        if (direction != FixVector2.Zero)
            return true;
        if (!TryResolveLowestPortalAccessNeighbor(
                portalAccessSector,
                portalAccess,
                worldX,
                worldY,
                currentCost,
                out int bestDirectionIndex,
                out _))
        {
            throw new InvalidOperationException(
                $"TryResolveSpatialFieldDirectionFixed failed: portal access sample has no descending neighbor cell=({worldX},{worldY}), " +
                $"sector={portalAccessSector.SectorId}, portal={portalAccess.PortalId}.");
        }

        direction = new FixVector2(NeighborOffsetX[bestDirectionIndex], NeighborOffsetY[bestDirectionIndex]);
        return true;
    }

    private static FixVector2 ResolveSpatiallyInterpolatedPortalAccessGradientFixed(
        SectorData sector,
        SectorPortalAccessEntry access,
        FixVector2 position,
        int worldX,
        int worldY,
        long currentCost,
        out long currentGradientX,
        out long currentGradientY)
    {
        FixVector2 currentDirection = ResolveDeterministicPortalAccessGradientFixed(
            sector,
            access,
            worldX,
            worldY,
            currentCost,
            out currentGradientX,
            out currentGradientY);
        ResolveSpatialGradientSampleGridFixed(
            position,
            worldX,
            worldY,
            out int x0,
            out int x1,
            out int y0,
            out int y1,
            out Fix64 tx,
            out Fix64 ty);

        Fix64 oneMinusX = Fix64.One - tx;
        Fix64 oneMinusY = Fix64.One - ty;
        FixVector2 weightedDirection = FixVector2.Zero;
        Fix64 totalWeight = Fix64.Zero;
        AccumulateSpatialPortalAccessGradientSample(sector, access, worldX, worldY, x0, y0, oneMinusX * oneMinusY, ref weightedDirection, ref totalWeight);
        AccumulateSpatialPortalAccessGradientSample(sector, access, worldX, worldY, x1, y0, tx * oneMinusY, ref weightedDirection, ref totalWeight);
        AccumulateSpatialPortalAccessGradientSample(sector, access, worldX, worldY, x0, y1, oneMinusX * ty, ref weightedDirection, ref totalWeight);
        AccumulateSpatialPortalAccessGradientSample(sector, access, worldX, worldY, x1, y1, tx * ty, ref weightedDirection, ref totalWeight);

        return totalWeight > Fix64.Zero && weightedDirection != FixVector2.Zero
            ? weightedDirection
            : currentDirection;
    }

    private static void AccumulateSpatialPortalAccessGradientSample(
        SectorData sector,
        SectorPortalAccessEntry access,
        int currentX,
        int currentY,
        int sampleX,
        int sampleY,
        Fix64 weight,
        ref FixVector2 weightedDirection,
        ref Fix64 totalWeight)
    {
        if (weight <= Fix64.Zero || !IsInsideSector(sector, sampleX, sampleY))
            return;
        if ((sampleX != currentX || sampleY != currentY)
            && !CanTraverseNeighborCells(_world, currentX, currentY, sampleX, sampleY))
        {
            return;
        }
        if (sampleX != currentX
            && sampleY != currentY
            && !IsDiagonalPassable(_world, currentX, currentY, sampleX, sampleY))
        {
            return;
        }

        long sampleCost = ResolveDeterministicPortalAccessIntegrationCost(
            _world,
            sector,
            access,
            sampleX,
            sampleY);
        if (sampleCost == long.MaxValue)
            return;

        FixVector2 sampleDirection = ResolveDeterministicPortalAccessGradientFixed(
            sector,
            access,
            sampleX,
            sampleY,
            sampleCost,
            out _,
            out _);
        if (sampleDirection == FixVector2.Zero
            && TryResolveLowestPortalAccessNeighbor(
                sector,
                access,
                sampleX,
                sampleY,
                sampleCost,
                out int bestDirectionIndex,
                out _))
        {
            sampleDirection = new FixVector2(
                NeighborOffsetX[bestDirectionIndex],
                NeighborOffsetY[bestDirectionIndex]);
        }
        if (sampleDirection == FixVector2.Zero)
            return;

        weightedDirection += sampleDirection * weight;
        totalWeight += weight;
    }

    private static FixVector2 ResolveDeterministicPortalAccessGradientFixed(
        SectorData sector,
        SectorPortalAccessEntry access,
        int worldX,
        int worldY,
        long currentCost,
        out long gradientX,
        out long gradientY)
    {
        if (currentCost == long.MaxValue)
        {
            throw new InvalidOperationException(
                $"ResolveDeterministicPortalAccessGradientFixed failed: current cell is unreachable cell=({worldX},{worldY}), sector={sector.SectorId}, portal={access.PortalId}.");
        }

        gradientX = ResolveDeterministicPortalAccessGradientAxis(
            sector,
            access,
            worldX,
            worldY,
            currentCost,
            -2,
            0,
            2,
            0);
        gradientY = ResolveDeterministicPortalAccessGradientAxis(
            sector,
            access,
            worldX,
            worldY,
            currentCost,
            0,
            -2,
            0,
            2);
        long maximumMagnitude = Math.Max(Math.Abs(gradientX), Math.Abs(gradientY));
        if (maximumMagnitude == 0)
            return FixVector2.Zero;

        Fix64 scale = Fix64.FromRaw(maximumMagnitude);
        return new FixVector2(
            Fix64.FromRaw(gradientX) / scale,
            Fix64.FromRaw(gradientY) / scale);
    }

    private static long ResolveDeterministicPortalAccessGradientAxis(
        SectorData sector,
        SectorPortalAccessEntry access,
        int worldX,
        int worldY,
        long currentCost,
        int negativeOffsetX,
        int negativeOffsetY,
        int positiveOffsetX,
        int positiveOffsetY)
    {
        bool hasNegative = TryGetDeterministicPortalAccessGradientSample(
            sector,
            access,
            worldX,
            worldY,
            worldX + negativeOffsetX,
            worldY + negativeOffsetY,
            out long negativeCost);
        bool hasPositive = TryGetDeterministicPortalAccessGradientSample(
            sector,
            access,
            worldX,
            worldY,
            worldX + positiveOffsetX,
            worldY + positiveOffsetY,
            out long positiveCost);

        if (hasNegative && hasPositive)
            return negativeCost - positiveCost;
        if (hasNegative)
            return checked(2L * (negativeCost - currentCost));
        if (hasPositive)
            return checked(2L * (currentCost - positiveCost));
        return 0L;
    }

    private static bool TryGetDeterministicPortalAccessGradientSample(
        SectorData sector,
        SectorPortalAccessEntry access,
        int worldX,
        int worldY,
        int sampleX,
        int sampleY,
        out long cost)
    {
        cost = long.MaxValue;
        if (!IsInsideSector(sector, sampleX, sampleY)
            || !CanTraverseSamplePath(_world, worldX, worldY, sampleX, sampleY))
        {
            return false;
        }

        cost = ResolveDeterministicPortalAccessIntegrationCost(
            _world,
            sector,
            access,
            sampleX,
            sampleY);
        return cost != long.MaxValue;
    }

    private static bool TryResolveSharedBoundaryPortalHandoffTargetFixed(
        AgentRuntimeData agent,
        FlowTileCacheKey key,
        PortalData currentPortal,
        int currentPortalSlotIndex,
        FixVector2 position,
        int worldX,
        int worldY,
        out FixVector2 target,
        out string diagnostic)
    {
        target = FixVector2.Zero;
        diagnostic = "sharedBoundaryHandoff=unavailable";
        if (agent == null)
            throw new InvalidOperationException("TryResolveSharedBoundaryPortalHandoffTargetFixed failed: agent is null.");
        if (currentPortal == null)
            throw new InvalidOperationException("TryResolveSharedBoundaryPortalHandoffTargetFixed failed: current portal is null.");
        if (key.DownstreamGoalHint < 0
            || !TryGetPortalById(_world, key.DownstreamGoalHint, out PortalData nextPortal))
        {
            diagnostic = $"sharedBoundaryHandoff=unavailable reason=no-next-portal hint={key.DownstreamGoalHint}";
            return false;
        }

        int downstreamSectorId = GetOppositeSectorId(currentPortal, key.SectorId);
        if (nextPortal.SectorAId != downstreamSectorId && nextPortal.SectorBId != downstreamSectorId)
        {
            throw new InvalidOperationException(
                $"TryResolveSharedBoundaryPortalHandoffTargetFixed failed: downstream portal {nextPortal.PortalId} does not touch sector {downstreamSectorId}, key={FormatTileKey(key)}.");
        }

        Vector2Int[] currentOppositeCells = GetPortalCellsForSector(currentPortal, downstreamSectorId);
        if (currentPortalSlotIndex < 0 || currentPortalSlotIndex >= currentOppositeCells.Length)
            throw new ArgumentOutOfRangeException(nameof(currentPortalSlotIndex));
        Vector2Int downstreamStartCell = currentOppositeCells[currentPortalSlotIndex];
        Vector2Int[] nextCurrentCells = GetPortalCellsForSector(nextPortal, downstreamSectorId);
        int nextOppositeSectorId = GetOppositeSectorId(nextPortal, downstreamSectorId);
        Vector2Int[] nextOppositeCells = GetPortalCellsForSector(nextPortal, nextOppositeSectorId);
        if (nextCurrentCells.Length == 0 || nextCurrentCells.Length != nextOppositeCells.Length)
        {
            throw new InvalidOperationException(
                $"TryResolveSharedBoundaryPortalHandoffTargetFixed failed: downstream portal cells are invalid portal={nextPortal.PortalId}.");
        }

        int nextSlotIndex = ResolveSharedBoundaryPortalHandoffSlotIndex(
            downstreamStartCell,
            nextCurrentCells,
            nextOppositeCells,
            out Vector2Int targetCell);
        if (nextSlotIndex < 0)
        {
            diagnostic = $"sharedBoundaryHandoff=unavailable reason=slot-not-shared downstreamStart=({downstreamStartCell.x},{downstreamStartCell.y}) nextPortal={nextPortal.PortalId} nextCurrent={FormatGoalCells(nextCurrentCells)}";
            return false;
        }
        if (!HasGridLineOfSight(_world, worldX, worldY, targetCell.x, targetCell.y))
        {
            diagnostic = $"sharedBoundaryHandoff=unavailable reason=grid-los-failed targetCell=({targetCell.x},{targetCell.y}) nextPortal={nextPortal.PortalId}";
            return false;
        }

        FixVector2 candidateTarget = _world.GridToWorldCenterFixed(targetCell.x, targetCell.y);
        FixVector2 displacement = candidateTarget - position;
        if (!LogicStaticCollisionShadowService.TrySolveFixed(
                agent.AgentTypeId,
                position,
                displacement,
                agent.RadiusFixed,
                out LogicStaticCollisionShadowResult staticResult))
        {
            throw new InvalidOperationException(
                $"TryResolveSharedBoundaryPortalHandoffTargetFixed failed: static collision world is unavailable agent={agent.Id}.");
        }
        if (!staticResult.SolveResult.Success)
        {
            throw new InvalidOperationException(
                $"TryResolveSharedBoundaryPortalHandoffTargetFixed failed: static query failed agent={agent.Id}, failure={staticResult.SolveResult.Failure}.");
        }
        if (staticResult.SolveResult.ResolvedDisplacement != displacement)
        {
            diagnostic = $"sharedBoundaryHandoff=unavailable reason=static-los-failed targetCell=({targetCell.x},{targetCell.y}) nextPortal={nextPortal.PortalId}";
            return false;
        }

        target = candidateTarget;
        diagnostic =
            $"sharedBoundaryHandoff=nextPortal nextPortal={nextPortal.PortalId} nextSlot={nextSlotIndex} " +
            $"fromOpposite=({downstreamStartCell.x},{downstreamStartCell.y}) targetCell=({targetCell.x},{targetCell.y})";
        return true;
    }

    private static int ResolveSharedBoundaryPortalHandoffSlotIndex(
        Vector2Int downstreamStartCell,
        Vector2Int[] nextCurrentCells,
        Vector2Int[] nextOppositeCells,
        out Vector2Int targetCell)
    {
        if (nextCurrentCells == null)
            throw new InvalidOperationException("ResolveSharedBoundaryPortalHandoffSlotIndex failed: current cells are null.");
        if (nextOppositeCells == null)
            throw new InvalidOperationException("ResolveSharedBoundaryPortalHandoffSlotIndex failed: opposite cells are null.");
        if (nextCurrentCells.Length == 0 || nextCurrentCells.Length != nextOppositeCells.Length)
        {
            throw new InvalidOperationException(
                $"ResolveSharedBoundaryPortalHandoffSlotIndex failed: portal cells are invalid current={nextCurrentCells.Length}, opposite={nextOppositeCells.Length}.");
        }

        for (int i = 0; i < nextCurrentCells.Length; i++)
        {
            if (nextCurrentCells[i] != downstreamStartCell)
                continue;

            targetCell = nextOppositeCells[i];
            return i;
        }

        targetCell = default;
        return -1;
    }

    private static FixVector2 ResolvePortalCrossingTargetFixed(
        FixVector2 position,
        FixVector2 oppositeCellCenter,
        bool isVerticalBoundary)
    {
        return isVerticalBoundary
            ? new FixVector2(oppositeCellCenter.x, position.y)
            : new FixVector2(position.x, oppositeCellCenter.y);
    }

    private static FixVector2 ResolvePortalApproachTargetFixed(
        FixVector2 position,
        Vector2Int selectedCurrentCell,
        FixVector2 oppositeCellCenter,
        bool isVerticalBoundary)
    {
        _world.GetGridCellBoundsFixed(
            selectedCurrentCell.x,
            selectedCurrentCell.y,
            out FixVector2 minimum,
            out FixVector2 maximum);
        if (isVerticalBoundary)
        {
            Fix64 tangent = Fix64.Clamp(position.y, minimum.y, maximum.y);
            return new FixVector2(oppositeCellCenter.x, tangent);
        }

        Fix64 horizontalTangent = Fix64.Clamp(position.x, minimum.x, maximum.x);
        return new FixVector2(horizontalTangent, oppositeCellCenter.y);
    }

    private static int FindPortalCellSlotIndex(Vector2Int[] portalCells, int worldX, int worldY)
    {
        if (portalCells == null)
            throw new InvalidOperationException("FindPortalCellSlotIndex failed: portal cells are null.");

        for (int i = 0; i < portalCells.Length; i++)
        {
            if (portalCells[i].x == worldX && portalCells[i].y == worldY)
                return i;
        }

        return -1;
    }

    private static int ResolveStablePortalTraversalSlotIndex(
        AgentNavState nav,
        FlowTileCacheKey key,
        int recommendedSlotIndex,
        int slotCount,
        bool recommendationFromCommittedTile)
    {
        if (nav == null)
            throw new InvalidOperationException("ResolveStablePortalTraversalSlotIndex failed: nav is null.");
        if (slotCount <= 0)
            throw new ArgumentOutOfRangeException(nameof(slotCount), slotCount, "Portal slot count must be positive.");
        if (recommendedSlotIndex < 0 || recommendedSlotIndex >= slotCount)
            throw new ArgumentOutOfRangeException(nameof(recommendedSlotIndex), recommendedSlotIndex, "Recommended portal slot is invalid.");

        bool matchesCurrentPortal = nav.PortalTraversalWorldVersion == key.WorldVersion
                                    && nav.PortalTraversalSectorId == key.SectorId
                                    && nav.PortalTraversalId == key.GoalId
                                    && nav.PortalTraversalSlotIndex >= 0
                                    && nav.PortalTraversalSlotIndex < slotCount;
        if (!matchesCurrentPortal
            || (recommendationFromCommittedTile && !nav.PortalTraversalHasCommittedTileSlot))
        {
            return SetStablePortalTraversalSlotIndex(
                nav,
                key,
                recommendedSlotIndex,
                recommendationFromCommittedTile);
        }

        return nav.PortalTraversalSlotIndex;
    }

    private static int SetStablePortalTraversalSlotIndex(
        AgentNavState nav,
        FlowTileCacheKey key,
        int slotIndex,
        bool hasCommittedTileSlot)
    {
        nav.PortalTraversalWorldVersion = key.WorldVersion;
        nav.PortalTraversalSectorId = key.SectorId;
        nav.PortalTraversalId = key.GoalId;
        nav.PortalTraversalSlotIndex = slotIndex;
        nav.PortalTraversalHasCommittedTileSlot = hasCommittedTileSlot;
        return slotIndex;
    }

    private static int ResolvePendingPortalTargetSlotIndex(
        SectorData sector,
        SectorPortalAccessEntry access,
        Vector2Int[] portalCells,
        int startX,
        int startY,
        long startCost)
    {
        int worldX = startX;
        int worldY = startY;
        long currentCost = startCost;
        int guard = sector.Width * sector.Height + 1;
        while (guard-- > 0)
        {
            for (int i = 0; i < portalCells.Length; i++)
            {
                if (portalCells[i].x == worldX && portalCells[i].y == worldY)
                    return i;
            }

            if (!TryResolveLowestPortalAccessNeighbor(
                    sector,
                    access,
                    worldX,
                    worldY,
                    currentCost,
                    out int directionIndex,
                    out long nextCost))
            {
                throw new InvalidOperationException(
                    $"ResolvePendingPortalTargetSlotIndex failed: portal access field has no descending neighbor " +
                    $"cell=({worldX},{worldY}), cost={currentCost}, portal={access.PortalId}, sector={sector.SectorId}.");
            }

            worldX += NeighborOffsetX[directionIndex];
            worldY += NeighborOffsetY[directionIndex];
            currentCost = nextCost;
        }

        throw new InvalidOperationException(
            $"ResolvePendingPortalTargetSlotIndex failed: portal access path contains a cycle portal={access.PortalId}, sector={sector.SectorId}.");
    }

    private static bool TryResolveLowestPortalAccessNeighbor(
        SectorData sector,
        SectorPortalAccessEntry access,
        int worldX,
        int worldY,
        long currentCost,
        out int bestDirectionIndex,
        out long bestCost)
    {
        bestDirectionIndex = -1;
        bestCost = currentCost;
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int nextX = worldX + NeighborOffsetX[i];
            int nextY = worldY + NeighborOffsetY[i];
            if (!IsInsideSector(sector, nextX, nextY)
                || !CanTraverseNeighborCells(_world, worldX, worldY, nextX, nextY))
            {
                continue;
            }
            if (NeighborOffsetX[i] != 0
                && NeighborOffsetY[i] != 0
                && !IsDiagonalPassable(_world, worldX, worldY, nextX, nextY))
            {
                continue;
            }

            long nextCost = ResolveDeterministicPortalAccessIntegrationCost(
                _world,
                sector,
                access,
                nextX,
                nextY);
            if (nextCost >= bestCost)
                continue;

            bestCost = nextCost;
            bestDirectionIndex = i;
        }

        return bestDirectionIndex >= 0;
    }

    private static FixVector2 ResolvePortalGoalCellVelocityFixed(
        FlowTileCacheEntry tile,
        FixVector2 position,
        int worldX,
        int worldY,
        Fix64 maxSpeed)
    {
        PortalData portal = GetPortalById(_world, tile.Key.GoalId);
        Vector2Int[] currentCells = GetPortalCellsForSector(portal, tile.Key.SectorId);
        Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, GetOppositeSectorId(portal, tile.Key.SectorId));
        if (currentCells.Length != oppositeCells.Length)
        {
            throw new InvalidOperationException(
                $"ResolvePortalGoalCellVelocityFixed failed: portal side cell count mismatch portal={portal.PortalId}, current={currentCells.Length}, opposite={oppositeCells.Length}.");
        }

        for (int i = 0; i < currentCells.Length; i++)
        {
            if (currentCells[i].x != worldX || currentCells[i].y != worldY)
                continue;

            FixVector2 oppositeCellCenter = _world.GridToWorldCenterFixed(oppositeCells[i].x, oppositeCells[i].y);
            FixVector2 target = ResolvePortalCrossingTargetFixed(position, oppositeCellCenter, portal.IsVerticalBoundary);
            return ScaleFixedDirectionToSpeed(target - position, maxSpeed);
        }

        throw new InvalidOperationException(
            $"ResolvePortalGoalCellVelocityFixed failed: zero direction cell is not a portal goal cell. cell=({worldX},{worldY}), key={FormatTileKey(tile.Key)}.");
    }

    private const int FixedPortalInfluenceCells = 2;
    private const int FixedPortalMinimumOwnerTicks = 3;
    private const int FixedPortalMaximumOwnerTicks = 45;
    private const int FixedCorridorBuildOperationQuota = 256;

    private static void EnsureFixedPortalOwnerFrame()
    {
        if (_world == null)
            throw new InvalidOperationException("EnsureFixedPortalOwnerFrame failed: world is null.");

        int frame = GetFrameCount();
        if (FixedPortalOwnerEvaluatedFrameByWorld.TryGetValue(_world.Version, out int evaluatedFrame)
            && evaluatedFrame == frame)
        {
            return;
        }

        FixedCorridorLookup corridorLookup = GetOrCreateFixedCorridorLookup(_world);
        int corridorOperations = AdvanceFixedCorridorBuilds(_world, corridorLookup, FixedCorridorBuildOperationQuota);
        CollectFixedPortalParticipants();
        if (corridorOperations < FixedCorridorBuildOperationQuota)
        {
            int additionalOperations = AdvanceFixedCorridorBuilds(
                _world,
                corridorLookup,
                FixedCorridorBuildOperationQuota - corridorOperations);
            if (additionalOperations > 0)
                CollectFixedPortalParticipants();
        }

        FixedPortalOwnerKeyScratch.Clear();
        foreach (FixedPortalOwnerKey key in FixedPortalOwners.Keys)
        {
            if (key.WorldVersion == _world.Version && !FixedPortalParticipantScratch.ContainsKey(key))
                FixedPortalOwnerKeyScratch.Add(key);
        }
        for (int i = 0; i < FixedPortalOwnerKeyScratch.Count; i++)
            FixedPortalOwners.Remove(FixedPortalOwnerKeyScratch[i]);

        FixedPortalOwnerKeyScratch.Clear();
        foreach (FixedPortalOwnerKey key in FixedPortalParticipantScratch.Keys)
            FixedPortalOwnerKeyScratch.Add(key);
        FixedPortalOwnerKeyScratch.Sort(FixedPortalOwnerKeyComparison);
        for (int i = 0; i < FixedPortalOwnerKeyScratch.Count; i++)
        {
            FixedPortalOwnerKey key = FixedPortalOwnerKeyScratch[i];
            FixedPortalParticipantSnapshot participants = FixedPortalParticipantScratch[key];
            if (!FixedPortalOwners.TryGetValue(key, out FixedPortalOwnerState state))
            {
                state = new FixedPortalOwnerState
                {
                    Key = key,
                    OwnerDirection = ResolveInitialFixedPortalOwnerDirection(participants),
                    OwnerSinceFrame = frame,
                };
                FixedPortalOwners.Add(key, state);
            }
            else
            {
                UpdateFixedPortalOwner(state, participants, frame);
            }

            state.PositiveMinimumAgentId = participants.PositiveMinimumAgentId;
            state.NegativeMinimumAgentId = participants.NegativeMinimumAgentId;
            state.LastEvaluatedFrame = frame;
        }

        FixedPortalOwnerEvaluatedFrameByWorld[_world.Version] = frame;
    }

    private static void CollectFixedPortalParticipants()
    {
        FixedPortalParticipantScratch.Clear();

        for (int i = 0; i < OrderedAgentIds.Count; i++)
        {
            AgentRuntimeData agent = Agents[OrderedAgentIds[i]];
            if (agent == null || !IsAgentInActiveFlowBuildQueueWorld(agent))
                continue;
            if (ResolveFixedPortalTraversal(agent, out FixedPortalOwnerKey key, out int direction, out int distanceInCells)
                != FixedCorridorResolution.Ready)
                continue;
            if (distanceInCells > FixedPortalInfluenceCells)
                continue;

            if (!FixedPortalParticipantScratch.TryGetValue(key, out FixedPortalParticipantSnapshot snapshot))
            {
                snapshot = new FixedPortalParticipantSnapshot();
                FixedPortalParticipantScratch.Add(key, snapshot);
            }

            bool onPortal = distanceInCells == 0;
            if (direction > 0)
            {
                snapshot.PositiveMinimumAgentId = Math.Min(snapshot.PositiveMinimumAgentId, agent.Id);
                snapshot.PositiveOnPortal |= onPortal;
            }
            else
            {
                snapshot.NegativeMinimumAgentId = Math.Min(snapshot.NegativeMinimumAgentId, agent.Id);
                snapshot.NegativeOnPortal |= onPortal;
            }
        }
    }

    private static FixVector2 ApplyFixedPortalOwner(AgentRuntimeData agent, FixVector2 velocity)
    {
        if (velocity == FixVector2.Zero)
            return velocity;
        FixedCorridorResolution resolution = ResolveFixedPortalTraversal(
            agent,
            out FixedPortalOwnerKey key,
            out int direction,
            out int distanceInCells);
        if (resolution == FixedCorridorResolution.Pending)
        {
            agent.NavState.LastFixedFlowResult = "bottleneck-owner-pending";
            agent.NavState.LastFixedFlowVelocity = FixVector2.Zero;
            return FixVector2.Zero;
        }
        if (resolution != FixedCorridorResolution.Ready
            || distanceInCells > FixedPortalInfluenceCells
            || !FixedPortalOwners.TryGetValue(key, out FixedPortalOwnerState state)
            || state.OwnerDirection == direction)
        {
            return velocity;
        }

        agent.NavState.LastFixedFlowResult =
            $"bottleneck-owner-wait kind={key.Kind} id={key.LocalBottleneckId} owner={state.OwnerDirection} direction={direction} frame={state.LastEvaluatedFrame}";
        agent.NavState.LastFixedFlowVelocity = FixVector2.Zero;
        return FixVector2.Zero;
    }

    private static FixedCorridorResolution ResolveFixedPortalTraversal(
        AgentRuntimeData agent,
        out FixedPortalOwnerKey key,
        out int direction,
        out int distanceInCells)
    {
        key = default;
        direction = 0;
        distanceInCells = int.MaxValue;
        if (agent?.NavState?.PathHandle == null || !agent.NavState.HasGoal || _world == null)
            return FixedCorridorResolution.Absent;

        PathHandle handle = agent.NavState.PathHandle;
        int portalId = ResolveCurrentDownstreamPortalId(handle);
        if (portalId >= 0 && TryGetPortalById(_world, portalId, out PortalData portal) && portal.IsNarrow)
        {
            int currentSectorId = agent.NavState.CurrentSectorId;
            if (currentSectorId == portal.SectorAId)
                direction = 1;
            else if (currentSectorId == portal.SectorBId)
                direction = -1;
            else
                return FixedCorridorResolution.Absent;

            distanceInCells = ResolveFixedPortalCellDistance(agent.NavState.CurrentCell, portal);
            key = new FixedPortalOwnerKey(_world.Version, _world.AgentTypeId, portalId);
            return FixedCorridorResolution.Ready;
        }

        return ResolveFixedCorridorTraversal(agent, out key, out direction, out distanceInCells);
    }

    private static FixedCorridorResolution ResolveFixedCorridorTraversal(
        AgentRuntimeData agent,
        out FixedPortalOwnerKey key,
        out int direction,
        out int distanceInCells)
    {
        key = default;
        direction = 0;
        distanceInCells = int.MaxValue;
        if (agent?.NavState?.PathHandle == null || !agent.NavState.HasGoal || _world == null)
            return FixedCorridorResolution.Absent;

        PathHandle handle = agent.NavState.PathHandle;
        if (handle.WorldVersion != _world.Version)
            return FixedCorridorResolution.Absent;
        if (!_world.IsWalkable(agent.NavState.CurrentCell.x, agent.NavState.CurrentCell.y))
        {
            throw new InvalidOperationException(
                $"Fixed corridor owner cannot resolve non-walkable current cell ({agent.NavState.CurrentCell.x},{agent.NavState.CurrentCell.y}) for agent {agent.Id}.");
        }

        FixedCorridorLookup lookup = GetOrCreateFixedCorridorLookup(_world);
        FixedCorridorResolution resolution = ResolveFixedCorridorNearCell(
                _world,
                lookup,
                agent.NavState.CurrentCell,
                out FixedCorridorDescriptor descriptor,
                out distanceInCells);
        if (resolution != FixedCorridorResolution.Ready)
            return resolution;

        long distanceToA = ResolveFixedCorridorEndpointDistance(_world, handle.GoalX, handle.GoalY, descriptor.EndpointACellIndices);
        long distanceToB = ResolveFixedCorridorEndpointDistance(_world, handle.GoalX, handle.GoalY, descriptor.EndpointBCellIndices);
        if (distanceToA == distanceToB)
            return FixedCorridorResolution.Absent;

        direction = distanceToB < distanceToA ? 1 : -1;
        long currentDistanceToDestination = direction > 0
            ? ResolveFixedCorridorEndpointDistance(
                _world,
                agent.NavState.CurrentCell.x,
                agent.NavState.CurrentCell.y,
                descriptor.EndpointBCellIndices)
            : ResolveFixedCorridorEndpointDistance(
                _world,
                agent.NavState.CurrentCell.x,
                agent.NavState.CurrentCell.y,
                descriptor.EndpointACellIndices);
        if (currentDistanceToDestination == 0)
            return FixedCorridorResolution.Absent;

        key = descriptor.Key;
        return FixedCorridorResolution.Ready;
    }

    private static FixedCorridorLookup GetOrCreateFixedCorridorLookup(NavigationWorld world)
    {
        if (world == null)
            throw new ArgumentNullException(nameof(world));
        if (world.Version <= 0)
            throw new InvalidOperationException("Fixed corridor lookup requires a committed navigation world version.");
        if (FixedCorridorLookupByWorldVersion.TryGetValue(world.Version, out FixedCorridorLookup existing))
            return existing;
        if (world.WalkableMask == null || world.WalkableMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("Fixed corridor lookup encountered an invalid walkable mask.");

        int narrowWidth = Math.Max(1, ResolvePortalNarrowWidthCells(world));
        var lookup = new FixedCorridorLookup(narrowWidth);
        FixedCorridorLookupByWorldVersion.Add(world.Version, lookup);
        return lookup;
    }

    private static FixedCorridorResolution ResolveFixedCorridorDescriptor(
        NavigationWorld world,
        FixedCorridorLookup lookup,
        int startIndex,
        out FixedCorridorDescriptor descriptor)
    {
        descriptor = null;
        int cellCount = checked(world.Width * world.Height);
        if (startIndex < 0 || startIndex >= cellCount)
            throw new ArgumentOutOfRangeException(nameof(startIndex), startIndex, "Fixed corridor cell index is outside the navigation world.");
        if (lookup == null)
            throw new ArgumentNullException(nameof(lookup));
        if (lookup.ResolvedNonCorridorCells.Contains(startIndex))
            return FixedCorridorResolution.Absent;
        if (lookup.ComponentIdByCell.TryGetValue(startIndex, out int componentId))
        {
            if (!lookup.CompletedComponentIds.Contains(componentId))
                return FixedCorridorResolution.Pending;
            return lookup.DescriptorByComponentId.TryGetValue(componentId, out descriptor)
                ? FixedCorridorResolution.Ready
                : FixedCorridorResolution.Absent;
        }
        if (!IsFixedCorridorCandidate(world, lookup, startIndex))
        {
            lookup.ResolvedNonCorridorCells.Add(startIndex);
            return FixedCorridorResolution.Absent;
        }

        if (lookup.PendingStartIndices.Add(startIndex))
            lookup.PendingStartContentHash ^= ComputeFixedCorridorCellToken(startIndex);
        return FixedCorridorResolution.Pending;
    }

    private static int AdvanceFixedCorridorBuilds(
        NavigationWorld world,
        FixedCorridorLookup lookup,
        int operationQuota)
    {
        if (world == null)
            throw new ArgumentNullException(nameof(world));
        if (lookup == null)
            throw new ArgumentNullException(nameof(lookup));
        if (operationQuota <= 0)
            throw new ArgumentOutOfRangeException(nameof(operationQuota));

        int operations = 0;
        while (operations < operationQuota)
        {
            if (lookup.ActiveBuildJob == null && !TryStartNextFixedCorridorBuildJob(world, lookup))
                break;

            FixedCorridorBuildJob job = lookup.ActiveBuildJob;
            if (job.Head >= job.Queue.Count)
            {
                CompleteFixedCorridorBuildJob(world, lookup, job);
                lookup.ActiveBuildJob = null;
                continue;
            }

            int currentIndex = job.Queue[job.Head++];
            _fixedCorridorExpandedCellCount++;
            operations++;
            int currentX = currentIndex % world.Width;
            int currentY = currentIndex / world.Width;
            for (int offsetIndex = 0; offsetIndex < CardinalOffsetX.Length; offsetIndex++)
            {
                int nextX = currentX + CardinalOffsetX[offsetIndex];
                int nextY = currentY + CardinalOffsetY[offsetIndex];
                if (!world.IsWalkable(nextX, nextY)
                    || !CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                {
                    continue;
                }

                int nextIndex = world.GetIndex(nextX, nextY);
                if (IsFixedCorridorCandidate(world, lookup, nextIndex))
                    AddFixedCorridorBuildCell(lookup, job, nextIndex);
                else
                    AddFixedCorridorEndpointCell(
                        job.ExternalEndpointCells,
                        ref job.ExternalEndpointContentHash,
                        ref job.ExternalEndpointOverflow,
                        nextIndex,
                        lookup.NarrowWidth);
            }

            byte orientation = GetFixedCorridorOrientation(world, lookup, currentIndex);
            bool horizontalTerminal = (orientation & 1) != 0
                                      && (!HasFixedCorridorCandidateNeighbor(world, lookup, currentX, currentY, -1, 0)
                                          || !HasFixedCorridorCandidateNeighbor(world, lookup, currentX, currentY, 1, 0));
            bool verticalTerminal = (orientation & 2) != 0
                                    && (!HasFixedCorridorCandidateNeighbor(world, lookup, currentX, currentY, 0, -1)
                                        || !HasFixedCorridorCandidateNeighbor(world, lookup, currentX, currentY, 0, 1));
            if (horizontalTerminal || verticalTerminal)
                AddFixedCorridorEndpointCell(
                    job.TerminalEndpointCells,
                    ref job.TerminalEndpointContentHash,
                    ref job.TerminalEndpointOverflow,
                    currentIndex,
                    lookup.NarrowWidth);
        }

        if (lookup.ActiveBuildJob != null
            && lookup.ActiveBuildJob.Head >= lookup.ActiveBuildJob.Queue.Count)
        {
            CompleteFixedCorridorBuildJob(world, lookup, lookup.ActiveBuildJob);
            lookup.ActiveBuildJob = null;
        }

        return operations;
    }

    private static bool TryStartNextFixedCorridorBuildJob(NavigationWorld world, FixedCorridorLookup lookup)
    {
        while (lookup.PendingStartIndices.Count > 0)
        {
            int startIndex = lookup.PendingStartIndices.Min;
            lookup.PendingStartIndices.Remove(startIndex);
            lookup.PendingStartContentHash ^= ComputeFixedCorridorCellToken(startIndex);
            if (lookup.ResolvedNonCorridorCells.Contains(startIndex)
                || lookup.ComponentIdByCell.ContainsKey(startIndex))
            {
                continue;
            }
            if (!IsFixedCorridorCandidate(world, lookup, startIndex))
            {
                lookup.ResolvedNonCorridorCells.Add(startIndex);
                continue;
            }

            var job = new FixedCorridorBuildJob
            {
                ComponentId = lookup.NextComponentId++,
                StartIndex = startIndex,
                MinimumCellIndex = startIndex,
            };
            AddFixedCorridorBuildCell(lookup, job, startIndex);
            lookup.ActiveBuildJob = job;
            return true;
        }

        return false;
    }

    private static void AddFixedCorridorBuildCell(
        FixedCorridorLookup lookup,
        FixedCorridorBuildJob job,
        int cellIndex)
    {
        if (lookup.ComponentIdByCell.TryGetValue(cellIndex, out int existingComponentId))
        {
            if (existingComponentId != job.ComponentId)
            {
                throw new InvalidOperationException(
                    $"Fixed corridor incremental build encountered overlapping components existing={existingComponentId} active={job.ComponentId} cell={cellIndex}.");
            }
            return;
        }

        lookup.ComponentIdByCell.Add(cellIndex, job.ComponentId);
        lookup.ComponentAssignmentContentHash ^= ComputeFixedCorridorComponentCellToken(job.ComponentId, cellIndex);
        job.Queue.Add(cellIndex);
        job.MinimumCellIndex = Math.Min(job.MinimumCellIndex, cellIndex);
        job.ComponentCellContentHash ^= ComputeFixedCorridorCellToken(cellIndex);
    }

    private static void AddFixedCorridorEndpointCell(
        HashSet<int> cells,
        ref ulong contentHash,
        ref bool overflow,
        int cellIndex,
        int narrowWidth)
    {
        if (overflow || cells.Contains(cellIndex))
            return;
        int maximumEndpointCells = checked(Math.Max(1, narrowWidth) * 8);
        if (cells.Count >= maximumEndpointCells)
        {
            overflow = true;
            cells.Clear();
            contentHash = 0;
            return;
        }
        if (cells.Add(cellIndex))
            contentHash ^= ComputeFixedCorridorCellToken(cellIndex);
    }

    private static ulong ComputeFixedCorridorCellToken(int cellIndex)
    {
        ulong token = 14695981039346656037UL;
        AddAuthorityToken(ref token, cellIndex);
        return token;
    }

    private static ulong ComputeFixedCorridorComponentCellToken(int componentId, int cellIndex)
    {
        ulong token = 14695981039346656037UL;
        AddAuthorityToken(ref token, componentId);
        AddAuthorityToken(ref token, cellIndex);
        return token;
    }

    private static void CompleteFixedCorridorBuildJob(
        NavigationWorld world,
        FixedCorridorLookup lookup,
        FixedCorridorBuildJob job)
    {
        bool endpointOverflow = job.ExternalEndpointOverflow
                                || (job.ExternalEndpointCells.Count == 0 && job.TerminalEndpointOverflow);
        HashSet<int> endpointCells = job.ExternalEndpointCells.Count > 0
            ? job.ExternalEndpointCells
            : job.TerminalEndpointCells;
        List<int[]> endpointGroups = endpointOverflow
            ? new List<int[]>()
            : BuildFixedCorridorCellGroups(world, endpointCells);
        FixedCorridorDescriptor descriptor = null;

        if (endpointGroups.Count == 2)
        {
            endpointGroups.Sort((left, right) => left[0].CompareTo(right[0]));
            descriptor = new FixedCorridorDescriptor
            {
                Key = new FixedPortalOwnerKey(world.Version, world.AgentTypeId, 2, job.MinimumCellIndex),
                ComponentId = job.ComponentId,
                ComponentCellCount = job.Queue.Count,
                EndpointACellIndices = endpointGroups[0],
                EndpointBCellIndices = endpointGroups[1],
            };
            lookup.DescriptorByComponentId.Add(job.ComponentId, descriptor);
            lookup.DescriptorContentHash ^= ComputeFixedCorridorDescriptorToken(descriptor);
        }

        lookup.CompletedComponentIds.Add(job.ComponentId);
        lookup.CompletedComponentContentHash ^= ComputeFixedCorridorCellToken(job.ComponentId);
    }

    private static ulong ComputeFixedCorridorDescriptorToken(FixedCorridorDescriptor descriptor)
    {
        if (descriptor == null)
            throw new ArgumentNullException(nameof(descriptor));
        ulong token = 14695981039346656037UL;
        AddAuthorityToken(ref token, descriptor.Key.WorldVersion);
        AddAuthorityToken(ref token, descriptor.Key.AgentTypeId);
        AddAuthorityToken(ref token, descriptor.Key.Kind);
        AddAuthorityToken(ref token, descriptor.Key.LocalBottleneckId);
        AddAuthorityToken(ref token, descriptor.ComponentId);
        AddAuthorityToken(ref token, descriptor.ComponentCellCount);
        for (int i = 0; i < descriptor.EndpointACellIndices.Length; i++)
            AddAuthorityToken(ref token, descriptor.EndpointACellIndices[i]);
        AddAuthorityToken(ref token, int.MinValue);
        for (int i = 0; i < descriptor.EndpointBCellIndices.Length; i++)
            AddAuthorityToken(ref token, descriptor.EndpointBCellIndices[i]);
        return token;
    }

    private static bool IsFixedCorridorCandidate(NavigationWorld world, FixedCorridorLookup lookup, int cellIndex)
    {
        if (lookup.CandidateByCell.TryGetValue(cellIndex, out bool existing))
            return existing;

        byte orientation = GetFixedCorridorOrientation(world, lookup, cellIndex);
        bool candidate = orientation != 0 || IsFixedCorridorCornerConnector(world, lookup, cellIndex);
        lookup.CandidateByCell.Add(cellIndex, candidate);
        return candidate;
    }

    private static byte GetFixedCorridorOrientation(NavigationWorld world, FixedCorridorLookup lookup, int cellIndex)
    {
        if (lookup.OrientationsByCell.TryGetValue(cellIndex, out byte existing))
            return existing;

        _fixedCorridorClassifiedCellCount++;
        int cellX = cellIndex % world.Width;
        int cellY = cellIndex / world.Width;
        byte orientation = 0;
        if (world.IsWalkable(cellX, cellY))
        {
            if (MeasureFixedCorridorSpan(world, cellX, cellY, 0, 1, lookup.NarrowWidth) <= lookup.NarrowWidth)
                orientation |= 1;
            if (MeasureFixedCorridorSpan(world, cellX, cellY, 1, 0, lookup.NarrowWidth) <= lookup.NarrowWidth)
                orientation |= 2;
        }

        lookup.OrientationsByCell.Add(cellIndex, orientation);
        return orientation;
    }

    private static bool IsFixedCorridorCornerConnector(
        NavigationWorld world,
        FixedCorridorLookup lookup,
        int startIndex)
    {
        bool hasHorizontalSeed = false;
        bool hasVerticalSeed = false;
        int head = 0;
        int tail = 0;
        lookup.ConnectorQueue[tail] = startIndex;
        lookup.ConnectorDistances[tail++] = 0;
        while (head < tail)
        {
            int currentIndex = lookup.ConnectorQueue[head];
            int currentDistance = lookup.ConnectorDistances[head++];
            byte orientation = GetFixedCorridorOrientation(world, lookup, currentIndex);
            hasHorizontalSeed |= (orientation & 1) != 0;
            hasVerticalSeed |= (orientation & 2) != 0;
            if (hasHorizontalSeed && hasVerticalSeed)
                return true;
            if (currentDistance >= lookup.NarrowWidth)
                continue;

            int currentX = currentIndex % world.Width;
            int currentY = currentIndex / world.Width;
            for (int offsetIndex = 0; offsetIndex < CardinalOffsetX.Length; offsetIndex++)
            {
                int nextX = currentX + CardinalOffsetX[offsetIndex];
                int nextY = currentY + CardinalOffsetY[offsetIndex];
                if (!world.IsWalkable(nextX, nextY)
                    || !CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                {
                    continue;
                }

                int nextIndex = world.GetIndex(nextX, nextY);
                bool alreadyQueued = false;
                for (int i = 0; i < tail; i++)
                {
                    if (lookup.ConnectorQueue[i] == nextIndex)
                    {
                        alreadyQueued = true;
                        break;
                    }
                }
                if (alreadyQueued)
                    continue;
                if (tail >= lookup.ConnectorQueue.Length)
                    throw new InvalidOperationException("Fixed corridor connector search exceeded its bounded queue.");
                lookup.ConnectorQueue[tail] = nextIndex;
                lookup.ConnectorDistances[tail++] = currentDistance + 1;
            }
        }

        return false;
    }

    private static int MeasureFixedCorridorSpan(
        NavigationWorld world,
        int startX,
        int startY,
        int stepX,
        int stepY,
        int limit)
    {
        if (!world.IsWalkable(startX, startY))
            throw new InvalidOperationException($"Fixed corridor span requires walkable cell ({startX},{startY}).");
        if (limit <= 0)
            throw new ArgumentOutOfRangeException(nameof(limit));

        int count = 1;
        for (int sign = -1; sign <= 1; sign += 2)
        {
            int currentX = startX;
            int currentY = startY;
            while (count <= limit)
            {
                int nextX = currentX + stepX * sign;
                int nextY = currentY + stepY * sign;
                if (!world.IsWalkable(nextX, nextY)
                    || !CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                {
                    break;
                }

                count++;
                currentX = nextX;
                currentY = nextY;
            }
        }

        return count;
    }

    private static bool HasFixedCorridorCandidateNeighbor(
        NavigationWorld world,
        FixedCorridorLookup lookup,
        int fromX,
        int fromY,
        int offsetX,
        int offsetY)
    {
        int toX = fromX + offsetX;
        int toY = fromY + offsetY;
        return world.IsWalkable(toX, toY)
               && CanTraverseNeighborCells(world, fromX, fromY, toX, toY)
               && IsFixedCorridorCandidate(world, lookup, world.GetIndex(toX, toY));
    }

    private static List<int[]> BuildFixedCorridorCellGroups(NavigationWorld world, HashSet<int> cellIndices)
    {
        if (cellIndices == null)
            throw new ArgumentNullException(nameof(cellIndices));

        var groups = new List<int[]>();
        var visited = new HashSet<int>();
        var orderedCells = new List<int>(cellIndices);
        orderedCells.Sort();
        for (int startCellIndex = 0; startCellIndex < orderedCells.Count; startCellIndex++)
        {
            int startIndex = orderedCells[startCellIndex];
            if (!visited.Add(startIndex))
                continue;

            var group = new List<int>();
            var queue = new List<int> { startIndex };
            for (int head = 0; head < queue.Count; head++)
            {
                int currentIndex = queue[head];
                group.Add(currentIndex);
                int currentX = currentIndex % world.Width;
                int currentY = currentIndex / world.Width;
                for (int offsetIndex = 0; offsetIndex < CardinalOffsetX.Length; offsetIndex++)
                {
                    int nextX = currentX + CardinalOffsetX[offsetIndex];
                    int nextY = currentY + CardinalOffsetY[offsetIndex];
                    if (!world.IsWalkable(nextX, nextY)
                        || !CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                    {
                        continue;
                    }

                    int nextIndex = world.GetIndex(nextX, nextY);
                    if (!cellIndices.Contains(nextIndex) || !visited.Add(nextIndex))
                        continue;
                    queue.Add(nextIndex);
                }
            }

            group.Sort();
            groups.Add(group.ToArray());
        }

        groups.Sort((left, right) => left[0].CompareTo(right[0]));
        return groups;
    }

    private static FixedCorridorResolution ResolveFixedCorridorNearCell(
        NavigationWorld world,
        FixedCorridorLookup lookup,
        Vector2Int startCell,
        out FixedCorridorDescriptor descriptor,
        out int distanceInCells)
    {
        descriptor = null;
        distanceInCells = int.MaxValue;
        if (lookup == null)
            throw new InvalidOperationException("Fixed corridor resolver encountered invalid lookup data.");

        int queueCapacity = 1 + 2 * FixedPortalInfluenceCells * (FixedPortalInfluenceCells + 1);
        var queue = new int[queueCapacity];
        var distances = new int[queueCapacity];
        int head = 0;
        int tail = 0;
        bool hasPending = false;
        queue[tail] = world.GetIndex(startCell.x, startCell.y);
        distances[tail++] = 0;
        while (head < tail)
        {
            int currentIndex = queue[head];
            int currentDistance = distances[head++];
            FixedCorridorResolution resolution = ResolveFixedCorridorDescriptor(world, lookup, currentIndex, out FixedCorridorDescriptor candidate);
            hasPending |= resolution == FixedCorridorResolution.Pending;
            if (resolution == FixedCorridorResolution.Ready
                && (descriptor == null
                    || currentDistance < distanceInCells
                    || (currentDistance == distanceInCells
                        && CompareFixedPortalOwnerKeys(candidate.Key, descriptor.Key) < 0)))
            {
                descriptor = candidate;
                distanceInCells = currentDistance;
            }

            if (currentDistance >= FixedPortalInfluenceCells)
                continue;

            int currentX = currentIndex % world.Width;
            int currentY = currentIndex / world.Width;
            for (int offsetIndex = 0; offsetIndex < CardinalOffsetX.Length; offsetIndex++)
            {
                int nextX = currentX + CardinalOffsetX[offsetIndex];
                int nextY = currentY + CardinalOffsetY[offsetIndex];
                if (!world.IsWalkable(nextX, nextY)
                    || !CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                {
                    continue;
                }

                int nextIndex = world.GetIndex(nextX, nextY);
                bool alreadyQueued = false;
                for (int i = 0; i < tail; i++)
                {
                    if (queue[i] == nextIndex)
                    {
                        alreadyQueued = true;
                        break;
                    }
                }
                if (alreadyQueued)
                    continue;
                if (tail >= queueCapacity)
                    throw new InvalidOperationException("Fixed corridor resolver exceeded its bounded influence queue.");
                queue[tail] = nextIndex;
                distances[tail++] = currentDistance + 1;
            }
        }

        if (hasPending)
            return FixedCorridorResolution.Pending;
        return descriptor != null ? FixedCorridorResolution.Ready : FixedCorridorResolution.Absent;
    }

    private static long ResolveFixedCorridorEndpointDistance(
        NavigationWorld world,
        int goalX,
        int goalY,
        int[] endpointCellIndices)
    {
        if (endpointCellIndices == null || endpointCellIndices.Length == 0)
            throw new InvalidOperationException("Fixed corridor descriptor has no endpoint cells.");

        long best = long.MaxValue;
        for (int i = 0; i < endpointCellIndices.Length; i++)
        {
            int index = endpointCellIndices[i];
            if (index < 0 || index >= world.Width * world.Height)
                throw new InvalidOperationException("Fixed corridor descriptor contains an invalid endpoint cell.");
            int endpointX = index % world.Width;
            int endpointY = index / world.Width;
            long distance = Math.Abs((long)goalX - endpointX) + Math.Abs((long)goalY - endpointY);
            if (distance < best)
                best = distance;
        }

        return best;
    }

    private static int ResolveFixedPortalCellDistance(Vector2Int cell, PortalData portal)
    {
        int best = int.MaxValue;
        ResolveFixedPortalCellDistance(cell, portal.CellsA, ref best);
        ResolveFixedPortalCellDistance(cell, portal.CellsB, ref best);
        if (best == int.MaxValue)
            throw new InvalidOperationException($"Fixed portal owner cannot resolve cells for portal {portal.PortalId}.");
        return best;
    }

    private static void ResolveFixedPortalCellDistance(Vector2Int cell, Vector2Int[] portalCells, ref int best)
    {
        if (portalCells == null)
            return;
        for (int i = 0; i < portalCells.Length; i++)
        {
            int distance = Math.Max(
                Math.Abs(cell.x - portalCells[i].x),
                Math.Abs(cell.y - portalCells[i].y));
            if (distance < best)
                best = distance;
        }
    }

    private static int ResolveInitialFixedPortalOwnerDirection(FixedPortalParticipantSnapshot participants)
    {
        bool hasPositive = participants.PositiveMinimumAgentId != int.MaxValue;
        bool hasNegative = participants.NegativeMinimumAgentId != int.MaxValue;
        if (!hasPositive && !hasNegative)
            throw new InvalidOperationException("Fixed portal owner requires at least one participant.");
        if (!hasNegative)
            return 1;
        if (!hasPositive)
            return -1;
        return participants.PositiveMinimumAgentId < participants.NegativeMinimumAgentId ? 1 : -1;
    }

    private static void UpdateFixedPortalOwner(
        FixedPortalOwnerState state,
        FixedPortalParticipantSnapshot participants,
        int frame)
    {
        bool positiveAvailable = participants.PositiveMinimumAgentId != int.MaxValue;
        bool negativeAvailable = participants.NegativeMinimumAgentId != int.MaxValue;
        bool ownerAvailable = state.OwnerDirection > 0 ? positiveAvailable : negativeAvailable;
        bool opposingAvailable = state.OwnerDirection > 0 ? negativeAvailable : positiveAvailable;
        bool ownerOnPortal = state.OwnerDirection > 0 ? participants.PositiveOnPortal : participants.NegativeOnPortal;
        int ownerElapsed = Math.Max(0, frame - state.OwnerSinceFrame);
        bool canRelease = ownerElapsed >= FixedPortalMinimumOwnerTicks && !ownerOnPortal;
        bool maximumElapsed = ownerElapsed >= FixedPortalMaximumOwnerTicks;
        if (opposingAvailable && canRelease && (!ownerAvailable || maximumElapsed))
        {
            state.OwnerDirection = -state.OwnerDirection;
            state.OwnerSinceFrame = frame;
        }
    }

    private static int CompareFixedPortalOwnerKeys(FixedPortalOwnerKey left, FixedPortalOwnerKey right)
    {
        int result = left.WorldVersion.CompareTo(right.WorldVersion);
        if (result != 0)
            return result;
        result = left.AgentTypeId.CompareTo(right.AgentTypeId);
        if (result != 0)
            return result;
        result = left.Kind.CompareTo(right.Kind);
        return result != 0 ? result : left.LocalBottleneckId.CompareTo(right.LocalBottleneckId);
    }

    private static void ClearFixedPortalOwnersForWorld(int worldVersion)
    {
        if (worldVersion <= 0)
            return;

        FixedPortalOwnerKeyScratch.Clear();
        foreach (FixedPortalOwnerKey key in FixedPortalOwners.Keys)
        {
            if (key.WorldVersion == worldVersion)
                FixedPortalOwnerKeyScratch.Add(key);
        }
        for (int i = 0; i < FixedPortalOwnerKeyScratch.Count; i++)
            FixedPortalOwners.Remove(FixedPortalOwnerKeyScratch[i]);
        FixedPortalOwnerKeyScratch.Clear();
        FixedPortalOwnerEvaluatedFrameByWorld.Remove(worldVersion);
        FixedCorridorLookupByWorldVersion.Remove(worldVersion);
    }

    public static void LogCombatClusterDiagnostic(IEntityContext self, IEntityContext target, bool moveLockedByAttack, float attackRange)
    {
        if (!GameDebugSettings.IsEnabled(DebugCategory.Attack))
            return;
        if (self == null)
            throw new InvalidOperationException("LogCombatClusterDiagnostic failed: self is null.");
        if (_world == null)
            throw new InvalidOperationException("LogCombatClusterDiagnostic failed: world is null.");

        int selfId = ResolveAgentId(self);
        if (!Agents.TryGetValue(selfId, out AgentRuntimeData agent))
            return;

        int frame = GetFrameCount();
        if (agent.NavState.LastCombatClusterDiagnosticFrame >= 0
            && frame - agent.NavState.LastCombatClusterDiagnosticFrame < 20)
        {
            return;
        }

        agent.NavState.LastCombatClusterDiagnosticFrame = frame;
        Vector3 targetPos = target != null ? target.Position : Vector3.zero;
        float selfToTarget = target != null ? self.DistanceToTargetSurface(target) : float.PositiveInfinity;
        float clusterRadius = Mathf.Max(agent.Radius * 3f, attackRange * 1.5f);
        List<AgentRuntimeData> nearby = CollectNearbyDynamicNeighbors(agent, clusterRadius);
        CombatClusterScratch.Clear();
        for (int i = 0; i < nearby.Count; i++)
        {
            AgentRuntimeData other = nearby[i];
            if (other.Id == agent.Id)
                continue;
            if (target != null && ResolveAgentId(target) == other.Id)
                continue;
            if (!CanIncludeInSpatialDiagnostics(other))
                continue;

            Vector3 delta = other.Position - agent.Position;
            delta.y = 0f;
            if (delta.magnitude > clusterRadius)
                continue;

            CombatClusterScratch.Add(other);
        }

        CombatClusterScratch.Sort((left, right) =>
        {
            float leftDist = (left.Position - agent.Position).sqrMagnitude;
            float rightDist = (right.Position - agent.Position).sqrMagnitude;
            return leftDist.CompareTo(rightDist);
        });

        System.Text.StringBuilder builder = new System.Text.StringBuilder(1024);
        builder.Append("[FlowCombatClusterDiag] frame=").Append(frame)
            .Append(" selfKey=").Append(agent.CharacterKey)
            .Append(" selfId=").Append(agent.Id)
            .Append(" selfPos=").Append(agent.Position)
            .Append(" target=").Append(target != null ? target.CharacterKey : "null")
            .Append(" targetPos=").Append(targetPos)
            .Append(" selfToTarget=").Append(selfToTarget.ToString("F3"))
            .Append(" attackRange=").Append(attackRange.ToString("F3"))
            .Append(" moveLockedByAttack=").Append(moveLockedByAttack)
            .Append(" moveCanRun=").Append(self.CanRun(self.MoveComp))
            .Append(" moveMode=").Append(agent.NavState.LastMovementMode)
            .Append(" intent=").Append(agent.HasNavigationIntent)
            .Append(" near=[");

        for (int i = 0; i < CombatClusterScratch.Count && i < 10; i++)
        {
            if (i > 0)
                builder.Append(" | ");

            AgentRuntimeData other = CombatClusterScratch[i];
            Vector3 delta = other.Position - agent.Position;
            delta.y = 0f;
            builder.Append("id=").Append(other.Id)
                .Append(",key=").Append(other.CharacterKey)
                .Append(",pos=").Append(other.Position)
                .Append(",dist=").Append(delta.magnitude.ToString("F3"))
                .Append(",radius=").Append(other.Radius.ToString("F3"))
                .Append(",intent=").Append(other.HasNavigationIntent)
                .Append(",moveMode=").Append(other.NavState.LastMovementMode)
                .Append(",moveComp=").Append(other.MoveCompTypeName);
        }

        if (CombatClusterScratch.Count == 0)
            builder.Append("none");
        builder.Append("]");
        Debug.LogWarning(builder.ToString());
    }

    public static void LogConstraintFailureDiagnostic(
        IEntityContext self,
        Vector3 currentPosition,
        Vector3 desiredHorizontalDisplacement,
        Vector3 inputVelocity,
        string executorReason)
    {
        if (!IsMovementDiagnosticsEnabled())
            return;
        if (self == null)
            throw new InvalidOperationException("FlowFieldCrowdMovementSystem.LogConstraintFailureDiagnostic failed: self is null.");

        int agentId = ResolveAgentId(self);
        if (!Agents.TryGetValue(agentId, out AgentRuntimeData agent))
        {
            LogMissingConstraintAgentDiagnostic(self, agentId, currentPosition, desiredHorizontalDisplacement, inputVelocity, executorReason);
            return;
        }

        int frameCount = GetFrameCount();
        if (agent.NavState.LastConstraintDiagnosticFrame >= 0
            && frameCount - agent.NavState.LastConstraintDiagnosticFrame < 20)
        {
            return;
        }

        agent.NavState.LastConstraintDiagnosticFrame = frameCount;
        agent.Position = self.Position;
        agent.Radius = ResolveCollisionRadius(self);
        agent.NavState.LastMovementMode = self.MoveExecutor?.MovementMode ?? MovementMode.Normal;

        AgentNavState nav = agent.NavState;
        string gridEdge = BuildGridEdgeDiagnostic(currentPosition, nav.LastSteeringDesiredDirection);
        string cell = BuildAgentCellDiagnostic(agent, currentPosition);
        string executorGrid = BuildExecutorGridSegmentDiagnostic(currentPosition, desiredHorizontalDisplacement, inputVelocity);
        Debug.LogWarning(
            $"[FlowConstraintDiag] reason={executorReason} key={agent.CharacterKey} id={agent.Id} frame={frameCount} " +
            $"pos={currentPosition} agentPos={agent.Position} radius={agent.Radius:F3} agentType={agent.AgentTypeId} mode={nav.LastMovementMode} " +
            $"inputVelocity={inputVelocity} desiredDisp={desiredHorizontalDisplacement} {executorGrid} " +
            $"steerFrame={nav.LastSteeringFrame} goal={nav.LastSteeringGoal} desiredSrc={nav.LastSteeringDesiredSource} " +
            $"desiredDir={nav.LastSteeringDesiredDirection} desiredVel={nav.LastSteeringDesiredVelocity} " +
            $"los={nav.LastSteeringHasLineOfSight} baseVel={nav.LastSteeringBaseVelocity} " +
            $"resultPreClamp={nav.LastSteeringResultPreClamp} result={nav.LastSteeringResult} maxSpeed={nav.LastSteeringMaxSpeed:F3} " +
            $"fixedResult={nav.LastFixedFlowResult} fixedVelocity={nav.LastFixedFlowVelocity} {cell} {gridEdge}");
    }

    private static string BuildLineOfSightFailureDiagnostic(Vector3 fromPosition, Vector3 targetPosition, int agentTypeId)
    {
        if (_world == null)
            return "[FlowLineOfSightDiag] world=null";

        bool fromInGrid = _world.WorldToGrid(fromPosition, out int fromX, out int fromY);
        bool targetInGrid = _world.WorldToGrid(targetPosition, out int targetX, out int targetY);
        if (!fromInGrid || !targetInGrid)
        {
            return $"[FlowLineOfSightDiag] fromInGrid={fromInGrid} targetInGrid={targetInGrid} " +
                   $"fromPos={fromPosition} targetPos={targetPosition}";
        }

        bool gridLos = HasGridLineOfSight(_world, fromX, fromY, targetX, targetY);
        return $"[FlowLineOfSightDiag] from=({fromX},{fromY}) target=({targetX},{targetY}) " +
               $"fromPos={fromPosition} targetPos={targetPosition} gridLos={gridLos} " +
               $"cells={BuildLineOfSightCellTrace(_world, fromX, fromY, targetX, targetY)} " +
               $"obstacles={BuildNearbyObstacleDiagnostics(fromPosition, targetPosition, agentTypeId)}";
    }

    private static string BuildLineOfSightCellTrace(NavigationWorld world, int x0, int y0, int x1, int y1)
    {
        if (world == null)
            return "world-null";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append("[");
        int dx = Mathf.Abs(x1 - x0);
        int dy = Mathf.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1;
        int sy = y0 < y1 ? 1 : -1;
        int err = dx - dy;
        int cx = x0;
        int cy = y0;
        int previousX = x0;
        int previousY = y0;
        int count = 0;
        const int maxCells = 96;

        while (true)
        {
            if (count > 0)
                builder.Append(" -> ");

            AppendCellDiagnostic(builder, world, cx, cy, previousX, previousY, count == 0);
            count++;

            if (cx == x1 && cy == y1)
                break;
            if (count >= maxCells)
            {
                builder.Append(" -> truncated");
                break;
            }

            int oldX = cx;
            int oldY = cy;
            int e2 = err * 2;
            if (e2 > -dy)
            {
                err -= dy;
                cx += sx;
            }

            if (e2 < dx)
            {
                err += dx;
                cy += sy;
            }

            previousX = oldX;
            previousY = oldY;
        }

        builder.Append("]");
        return builder.ToString();
    }

    private static void AppendCellDiagnostic(System.Text.StringBuilder builder, NavigationWorld world, int x, int y, int previousX, int previousY, bool isFirst)
    {
        bool inBounds = x >= 0 && x < world.Width && y >= 0 && y < world.Height;
        builder.Append("(").Append(x).Append(",").Append(y).Append(")");
        if (!inBounds)
        {
            builder.Append("{out}");
            return;
        }

        int index = world.GetIndex(x, y);
        bool walkable = world.WalkableMask != null && world.WalkableMask.Length == world.Width * world.Height && world.WalkableMask[index];
        bool baseWalkable = world.BaseWalkableMask != null && world.BaseWalkableMask.Length == world.Width * world.Height && world.BaseWalkableMask[index];
        int cost = TryGetCostFieldValue(world, x, y, out byte resolvedCost) ? resolvedCost : -1;
        int island = world.IslandIds != null && world.IslandIds.Length == world.Width * world.Height ? world.IslandIds[index] : -1;
        string mask = world.NeighborTraversalMask != null && world.NeighborTraversalMask.Length == world.Width * world.Height
            ? world.NeighborTraversalMask[index].ToString("X2")
            : "NA";
        bool link = isFirst || CanTraverseNeighborCells(world, previousX, previousY, x, y);
        builder.Append("{walk=").Append(walkable)
            .Append(",base=").Append(baseWalkable)
            .Append(",cost=").Append(cost)
            .Append(",island=").Append(island)
            .Append(",mask=0x").Append(mask)
            .Append(",link=").Append(link)
            .Append("}");
    }

    private static string BuildNearbyObstacleDiagnostics(Vector3 fromPosition, Vector3 targetPosition, int agentTypeId)
    {
        if (_world == null)
            return "world-null";

        Vector3 min = Vector3.Min(fromPosition, targetPosition);
        Vector3 max = Vector3.Max(fromPosition, targetPosition);
        float padding = Mathf.Max(2f, _world.CellSize * 4f);
        Bounds corridor = new Bounds((min + max) * 0.5f, max - min);
        corridor.Expand(new Vector3(padding * 2f, 0f, padding * 2f));

        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append("[boxes=");
        int count = 0;
        foreach (BoxObstacle box in BoxObstacles.Values)
        {
            Bounds bounds = new Bounds(box.Center, box.HalfExtents * 2f);
            Bounds navBounds = ResolveBoxObstacleNavigationBounds(_world, box);
            if (!IntersectsXZ(corridor, navBounds))
                continue;

            if (count > 0)
                builder.Append(" | ");

            AppendBoxObstacleDiagnostic(builder, box, bounds);
            builder.Append(",navGrid=").Append(FormatBoundsGridRange(navBounds));
            count++;
            if (count >= 12)
            {
                builder.Append(" | truncated");
                break;
            }
        }

        if (count == 0)
            builder.Append("none");

        builder.Append(" circles=");
        count = 0;
        foreach (CircleObstacle circle in CircleObstacles.Values)
        {
            Bounds bounds = new Bounds(circle.Position, new Vector3(circle.Radius * 2f, 0f, circle.Radius * 2f));
            if (!IntersectsXZ(corridor, bounds))
                continue;

            if (count > 0)
                builder.Append(" | ");

            builder.Append("{id=").Append(circle.Id)
                .Append(",pos=").Append(circle.Position)
                .Append(",r=").Append(circle.Radius.ToString("F3"))
                .Append(",grid=").Append(FormatBoundsGridRange(bounds))
                .Append("}");
            count++;
            if (count >= 12)
            {
                builder.Append(" | truncated");
                break;
            }
        }

        if (count == 0)
            builder.Append("none");

        builder.Append(",agentType=").Append(agentTypeId).Append("]");
        return builder.ToString();
    }

    private static bool IntersectsXZ(Bounds a, Bounds b)
    {
        return a.min.x <= b.max.x && a.max.x >= b.min.x
               && a.min.z <= b.max.z && a.max.z >= b.min.z;
    }

    private static void AppendBoxObstacleDiagnostic(System.Text.StringBuilder builder, BoxObstacle box, Bounds bounds)
    {
        builder.Append("{id=").Append(box.Id)
            .Append(",center=").Append(box.Center)
            .Append(",half=").Append(box.HalfExtents)
            .Append(",grid=").Append(FormatBoundsGridRange(bounds))
            .Append("}");
    }

    private static Bounds ResolveBoxObstacleNavigationBounds(NavigationWorld world, BoxObstacle box)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveBoxObstacleNavigationBounds failed: world is null.");
        if (box == null)
            throw new InvalidOperationException("ResolveBoxObstacleNavigationBounds failed: box is null.");

        float clearance = ResolveNavigationSegmentClearance(world, ResolveAgentTypeRadius(world.AgentTypeId));
        Vector3 halfExtents = box.HalfExtents + new Vector3(clearance, 0f, clearance);
        return new Bounds(box.Center, halfExtents * 2f);
    }

    private static FixVector2 ResolveBoxObstacleNavigationHalfExtentsFixed(NavigationWorld world, BoxObstacle box)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveBoxObstacleNavigationHalfExtentsFixed failed: world is null.");
        if (box == null)
            throw new InvalidOperationException("ResolveBoxObstacleNavigationHalfExtentsFixed failed: box is null.");

        Fix64 clearance = Fix64.Max(Fix64.Zero, world.AgentRadiusFixed - world.CellSizeFixed * Fix64.FromRaw(820));
        return box.HalfExtentsFixed + new FixVector2(clearance, clearance);
    }

    private static FixVector2 ResolveBoxObstacleDirtyHalfExtentsFixed(FixVector2 halfExtents)
    {
        Fix64 maxRadius = Fix64.FromRaw(2048);
        foreach (int agentTypeId in CollectNavigationWorldAgentTypes())
            maxRadius = Fix64.Max(maxRadius, ResolveAgentTypeRadiusFixed(agentTypeId));

        Fix64 clearance = Fix64.Max(Fix64.Zero, maxRadius - Fix64.FromRaw(82));
        return halfExtents + new FixVector2(clearance, clearance);
    }

    private static string FormatBoundsGridRange(Bounds bounds)
    {
        if (_world == null)
            return "world-null";

        int minX = Mathf.Clamp(Mathf.FloorToInt((bounds.min.x - _world.Origin.x) / _world.CellSize), 0, _world.Width - 1);
        int maxX = Mathf.Clamp(Mathf.FloorToInt((bounds.max.x - _world.Origin.x) / _world.CellSize), 0, _world.Width - 1);
        int minY = Mathf.Clamp(Mathf.FloorToInt((bounds.min.z - _world.Origin.z) / _world.CellSize), 0, _world.Height - 1);
        int maxY = Mathf.Clamp(Mathf.FloorToInt((bounds.max.z - _world.Origin.z) / _world.CellSize), 0, _world.Height - 1);
        return $"({minX},{minY})-({maxX},{maxY})";
    }

    private static bool ShouldLogSuccessfulMoveDiagnostic(AgentRuntimeData agent, IEntityContext self)
    {
        if (!GameDebugSettings.IsEnabled(DebugCategory.Move))
            return false;
        if (agent == null || self == null)
            return false;
        if (!GameDebugSettings.ShouldLogMovementForCharacter(self.CharacterKey))
            return false;

        int frame = GetFrameCount();
        if (agent.NavState.LastSuccessfulMoveDiagnosticFrame >= 0
            && frame - agent.NavState.LastSuccessfulMoveDiagnosticFrame < FlowSuccessfulMoveDiagnosticCooldownFrames)
        {
            return false;
        }

        if (_successfulMoveDiagnosticFrame != frame)
        {
            _successfulMoveDiagnosticFrame = frame;
            _successfulMoveDiagnosticCountThisFrame = 0;
        }

        if (_successfulMoveDiagnosticCountThisFrame >= MaxSuccessfulMoveDiagnosticsPerFrame)
            return false;

        _successfulMoveDiagnosticCountThisFrame++;
        agent.NavState.LastSuccessfulMoveDiagnosticFrame = frame;
        return true;
    }

