            $"boundaryMs={TicksToMilliseconds(boundaryTicks):F3} addMs={TicksToMilliseconds(addTicks):F3} " +
            $"accessFields={accessCount} analyticAccessFields={analyticAccessCount} transitionSources={transitionCostChecks} " +
            $"analyticChecks={analyticCheckCount} analyticClearSectors={analyticClearSectorCount} analyticRejects(component={analyticMultiComponentRejectCount},nonClear={analyticNonClearRejectCount}) " +
            "authority=deterministic-topology";
    }

    private static double TicksToMilliseconds(long ticks)
    {
        return ticks * 1000.0 / Stopwatch.Frequency;
    }

    private static bool[] RentCopiedBoolArray(bool[] source)
    {
        if (source == null)
            throw new InvalidOperationException("RentCopiedBoolArray failed: source is null.");

        bool[] copy = RentBoolArray(source.Length, clear: false);
        Array.Copy(source, copy, source.Length);
        return copy;
    }

    private static byte[] RentCopiedByteArray(byte[] source)
    {
        if (source == null)
            throw new InvalidOperationException("RentCopiedByteArray failed: source is null.");

        byte[] copy = RentByteArray(source.Length, clear: false);
        Array.Copy(source, copy, source.Length);
        return copy;
    }

    private static bool[] RentBoolArray(int length, bool clear)
    {
        if (length <= 0)
            throw new InvalidOperationException($"RentBoolArray failed: invalid length={length}.");

        bool[] array = RentArray(BoolArrayPool, length);
        if (array == null)
            array = new bool[length];
        else if (clear)
            Array.Clear(array, 0, array.Length);
        return array;
    }

    private static byte[] RentByteArray(int length, bool clear)
    {
        if (length <= 0)
            throw new InvalidOperationException($"RentByteArray failed: invalid length={length}.");

        byte[] array = RentArray(ByteArrayPool, length);
        if (array == null)
            array = new byte[length];
        else if (clear)
            Array.Clear(array, 0, array.Length);
        return array;
    }

    private static int[] RentIntArray(int length, bool clear)
    {
        if (length <= 0)
            throw new InvalidOperationException($"RentIntArray failed: invalid length={length}.");

        int[] array = RentArray(IntArrayPool, length);
        if (array == null)
            array = new int[length];
        else if (clear)
            Array.Clear(array, 0, array.Length);
        return array;
    }

    private static T[] RentArray<T>(Dictionary<int, Stack<T[]>> pool, int length)
    {
        if (pool.TryGetValue(length, out Stack<T[]> stack) && stack.Count > 0)
            return stack.Pop();

        return null;
    }

    private static void ReturnWorldArrayIfOwned(bool[] array, bool[] readOnlySource, bool[] current)
    {
        if (array == null || ReferenceEquals(array, readOnlySource) || ReferenceEquals(array, current))
            return;

        ReturnArray(BoolArrayPool, array);
    }

    private static void ReturnWorldArrayIfOwned(byte[] array, byte[] readOnlySource, byte[] current)
    {
        if (array == null || ReferenceEquals(array, readOnlySource) || ReferenceEquals(array, current))
            return;

        ReturnArray(ByteArrayPool, array);
    }

    private static void ReturnWorldArrayIfOwned(int[] array, int[] readOnlySource, int[] current)
    {
        if (array == null || ReferenceEquals(array, readOnlySource) || ReferenceEquals(array, current))
            return;

        ReturnArray(IntArrayPool, array);
    }

    private static void ReturnByteArray(byte[] array)
    {
        if (array == null)
            return;

        ReturnArray(ByteArrayPool, array);
    }

    private static void ReturnArray<T>(Dictionary<int, Stack<T[]>> pool, T[] array)
    {
        if (array == null || array.Length == 0)
            return;

        if (!pool.TryGetValue(array.Length, out Stack<T[]> stack))
        {
            stack = new Stack<T[]>();
            pool.Add(array.Length, stack);
        }

        if (stack.Count >= MaxRuntimeArrayPoolEntriesPerLength)
            return;

        stack.Push(array);
    }

    private static void LogNoStacktrace(string message)
    {
        if (!IsMovementDiagnosticsEnabled())
            return;
        Debug.LogFormat(LogType.Log, LogOption.NoStacktrace, null, "{0}", message);
    }

    private static void LogWarningNoStacktrace(string message)
    {
        if (!IsMovementDiagnosticsEnabled())
            return;
        Debug.LogFormat(LogType.Warning, LogOption.NoStacktrace, null, "{0}", message);
    }

    private static bool InitializeWorldBuildJob(WorldBuildJob job)
    {
        if (job == null)
            throw new InvalidOperationException("InitializeWorldBuildJob failed: job is null.");

        if (TryResolveTerrainSourceForAgentType(job.AgentTypeId, out TestTerrainOverride terrainSource))
        {
            job.Width = terrainSource.Width;
            job.Height = terrainSource.Height;
            job.CellSize = terrainSource.CellSize;
            job.EncodedCenterClearance = terrainSource.EncodedCenterClearance;
            job.Origin = terrainSource.Origin;
            if (terrainSource.HasFixedAuthorityPayload)
            {
                job.SetAuthorityGridMetadata(
                    terrainSource.CellSizeGridRaw,
                    terrainSource.EncodedCenterClearanceFixedRaw,
                    terrainSource.AgentRadiusFixedRaw,
                    terrainSource.OriginXGridRaw,
                    terrainSource.OriginZGridRaw);
            }
            else
            {
                job.FreezeAuthorityGridMetadata();
            }
            if (terrainSource.DerivedNavigationData != null)
            {
                NavigationWorld prebakedWorld = ImportDerivedNavigationWorld(terrainSource);
                job.WorkingWorld = ApplyInitialRuntimeOverlayToPrebakedWorldIfNeeded(
                    prebakedWorld,
                    job.AgentTypeId,
                    out job.PendingPortalAccessEntries);
                RefreshWorldBuildAuthorityInputHash(job);
                job.Stage = WorldBuildStage.Commit;
                return true;
            }

            job.BaseWalkableMask = (bool[])terrainSource.WalkableMask.Clone();
            job.BaseCostField = terrainSource.CostField != null
                ? (byte[])terrainSource.CostField.Clone()
                : null;
            job.BaseNeighborTraversalMask = terrainSource.NeighborTraversalMask != null
                ? (byte[])terrainSource.NeighborTraversalMask.Clone()
                : null;
            job.StaticCollisionVertices = terrainSource.StaticCollisionVertices != null
                ? (FixVector2[])terrainSource.StaticCollisionVertices.Clone()
                : null;
            job.StaticCollisionPathStarts = terrainSource.StaticCollisionPathStarts != null
                ? (int[])terrainSource.StaticCollisionPathStarts.Clone()
                : null;
            job.CellNavAnchors = terrainSource.CellNavAnchors != null
                ? (Vector3[])terrainSource.CellNavAnchors.Clone()
                : null;
            job.CellNavAnchorsFixedXZ = terrainSource.HasFixedAuthorityPayload
                ? (FixVector2[])terrainSource.CellNavAnchorsFixedXZ.Clone()
                : CreateNavigationAnchorFixedXZSnapshot(job.CellNavAnchors);
            job.HasProvidedCellNavAnchors = job.CellNavAnchors != null;
            job.HasProvidedNeighborTraversalMask = job.BaseNeighborTraversalMask != null;
            RefreshWorldBuildAuthorityInputHash(job);
            job.Stage = WorldBuildStage.CreateWorldShell;
            return true;
        }

        throw new InvalidOperationException(
            "InitializeWorldBuildJob failed: FlowNavigationGridSource has not applied a FlowNavigationGridAsset. " +
            "Runtime navigation is strict authored-grid only and will not fall back to any legacy navigation source.");
    }

    private static bool TryResolveTerrainSourceForAgentType(int agentTypeId, out TestTerrainOverride terrainSource)
    {
        if (AuthoredTerrainSources.TryGetValue(agentTypeId, out terrainSource))
            return true;

        if (_testTerrainOverride != null)
        {
            if (_testTerrainOverride.AgentTypeId == AnyAgentTypeId || _testTerrainOverride.AgentTypeId == agentTypeId)
            {
                terrainSource = _testTerrainOverride;
                return true;
            }
        }

        if (AuthoredTerrainSources.TryGetValue(AnyAgentTypeId, out terrainSource))
            return true;

        terrainSource = null;
        return false;
    }

    private static void CreateWorldBuildShell(WorldBuildJob job)
    {
        bool[] runtimeWalkableMask = (bool[])job.BaseWalkableMask.Clone();
        job.WorkingWorld = new NavigationWorld
        {
            AgentTypeId = job.AgentTypeId,
            Width = job.Width,
            Height = job.Height,
            CellSize = job.CellSize,
            EncodedCenterClearance = job.EncodedCenterClearance,
            Origin = job.Origin,
            BaseWalkableMask = job.BaseWalkableMask,
            BaseNeighborTraversalMask = job.BaseNeighborTraversalMask != null && job.BaseNeighborTraversalMask.Length == job.Width * job.Height
                ? (byte[])job.BaseNeighborTraversalMask.Clone()
                : null,
            StaticCollisionVertices = job.StaticCollisionVertices,
            StaticCollisionPathStarts = job.StaticCollisionPathStarts,
            SourceCostField = job.BaseCostField != null && job.BaseCostField.Length == job.Width * job.Height
                ? (byte[])job.BaseCostField.Clone()
                : null,
            WalkableMask = runtimeWalkableMask,
            CostField = job.BaseCostField != null && job.BaseCostField.Length == job.Width * job.Height
                ? (byte[])job.BaseCostField.Clone()
                : new byte[job.Width * job.Height],
            CellNavAnchors = job.CellNavAnchors != null && job.CellNavAnchors.Length == job.Width * job.Height ? job.CellNavAnchors : new Vector3[job.Width * job.Height],
            CellNavAnchorsFixedXZ = job.CellNavAnchorsFixedXZ != null && job.CellNavAnchorsFixedXZ.Length == job.Width * job.Height
                ? job.CellNavAnchorsFixedXZ
                : new FixVector2[job.Width * job.Height],
            NeighborTraversalMask = job.BaseNeighborTraversalMask != null && job.BaseNeighborTraversalMask.Length == job.Width * job.Height
                ? (byte[])job.BaseNeighborTraversalMask.Clone()
                : new byte[job.Width * job.Height],
            IslandIds = new int[job.Width * job.Height],
            SectorSizeInCells = ResolveRuntimeSectorSizeInCells(job.CellSize)
        };
        job.WorkingWorld.SetAuthorityGridMetadata(
            job.CellSizeGridRaw,
            job.EncodedCenterClearanceFixedRaw,
            job.AgentRadiusFixedRaw,
            job.OriginXGridRaw,
            job.OriginZGridRaw);
        if (!job.HasAuthorityGridMetadata
            || job.WorkingWorld.CellSizeGridRaw != job.CellSizeGridRaw
            || job.WorkingWorld.EncodedCenterClearanceFixedRaw != job.EncodedCenterClearanceFixedRaw
            || job.WorkingWorld.AgentRadiusFixedRaw != job.AgentRadiusFixedRaw
            || job.WorkingWorld.OriginXGridRaw != job.OriginXGridRaw
            || job.WorkingWorld.OriginZGridRaw != job.OriginZGridRaw)
        {
            throw new InvalidOperationException("CreateWorldBuildShell authority grid metadata does not match the frozen build input.");
        }
        job.CircleObstacles = job.IncludeRuntimeObstacles
            ? CreateSortedCircleObstacleSnapshot(CircleObstacles.Values)
            : new List<CircleObstacle>();
        job.BoxObstacles = job.IncludeRuntimeObstacles
            ? CreateSortedBoxObstacleSnapshot(BoxObstacles.Values)
            : new List<BoxObstacle>();
        job.CostStamps = job.IncludeRuntimeObstacles
            ? CreateSortedCostStampSnapshot(CostStamps.Values)
            : new List<CostStamp>();
        RefreshWorldBuildAuthorityInputHash(job);
        job.ObstacleCursor = 0;
        job.ApplyingCircleObstacles = true;
        job.Stage = WorldBuildStage.ApplyRuntimeObstacles;
    }

    private static void ProcessWorldBuildObstacles(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildObstacles failed: working world is null.");

        if (job.ApplyingCircleObstacles)
        {
            while (job.ObstacleCursor < job.CircleObstacles.Count)
            {
                CircleObstacle circle = job.CircleObstacles[job.ObstacleCursor++];
                BlockCellsByCircleFixed(
                    world,
                    circle.PositionFixed,
                    circle.RadiusFixed);
                if (!forceComplete && IsBudgetExpired(deadlineTicks, job.ObstacleCursor))
                    return;
            }

            job.ApplyingCircleObstacles = false;
            job.ObstacleCursor = 0;
        }

        while (job.ObstacleCursor < job.BoxObstacles.Count)
        {
            BoxObstacle box = job.BoxObstacles[job.ObstacleCursor++];
            BlockCellsByBoxFixed(
                world,
                box.CenterFixed,
                ResolveBoxObstacleNavigationHalfExtentsFixed(world, box));
            if (!forceComplete && IsBudgetExpired(deadlineTicks, job.ObstacleCursor))
                return;
        }

        job.ObstacleCursor = 0;
        job.Stage = WorldBuildStage.InitializeSectors;
    }

    private static void InitializeWorldBuildSectors(WorldBuildJob job)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("InitializeWorldBuildSectors failed: working world is null.");

        world.SectorCountX = Mathf.CeilToInt((float)world.Width / world.SectorSizeInCells);
        world.SectorCountY = Mathf.CeilToInt((float)world.Height / world.SectorSizeInCells);
        world.Sectors = new SectorData[world.SectorCountX * world.SectorCountY];

        for (int sectorY = 0; sectorY < world.SectorCountY; sectorY++)
        {
            for (int sectorX = 0; sectorX < world.SectorCountX; sectorX++)
            {
                int sectorId = sectorY * world.SectorCountX + sectorX;
                int startX = sectorX * world.SectorSizeInCells;
                int startY = sectorY * world.SectorSizeInCells;
                int sectorWidth = Mathf.Min(world.SectorSizeInCells, world.Width - startX);
                int sectorHeight = Mathf.Min(world.SectorSizeInCells, world.Height - startY);

                world.Sectors[sectorId] = new SectorData
                {
                    SectorId = sectorId,
                    StartX = startX,
                    StartY = startY,
                    Width = sectorWidth,
                    Height = sectorHeight,
                    DirtyVersion = 1,
                    LocalComponentIds = new int[sectorWidth * sectorHeight],
                    Center = world.Origin + new Vector3(
                        (startX + sectorWidth * 0.5f) * world.CellSize,
                        0f,
                        (startY + sectorHeight * 0.5f) * world.CellSize)
                };
            }
        }

        job.CellCursor = 0;
        job.Stage = WorldBuildStage.BuildCellNavAnchors;
    }

    private static int ResolveRuntimeSectorSizeInCells(float cellSize)
    {
        return Mathf.Max(4, Config.SectorSizeInCells);
    }

    private static int ResolvePortalNarrowWidthCells(NavigationWorld world)
    {
        return ResolveScaledCellCount(world, Config.PortalNarrowWidthCells);
    }

    private static int ResolveScaledCellCount(NavigationWorld world, int referenceCellCount)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveScaledCellCount failed: world is null.");

        return ResolveScaledCellCount(world.CellSize, referenceCellCount);
    }

    private static int ResolveScaledCellCount(float cellSize, int referenceCellCount)
    {
        if (referenceCellCount <= 0)
            throw new InvalidOperationException($"ResolveScaledCellCount failed: invalid referenceCellCount={referenceCellCount}.");

        return referenceCellCount;
    }

    private static void ProcessWorldBuildCellNavAnchors(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildCellNavAnchors failed: working world is null.");

        int cellCount = world.Width * world.Height;
        if (job.HasProvidedCellNavAnchors)
        {
            job.CellCursor = 0;
            job.Stage = WorldBuildStage.NeighborMask;
            return;
        }

        while (job.CellCursor < cellCount)
        {
            int index = job.CellCursor++;
            if (!world.BaseWalkableMask[index])
                continue;

            int x = index % world.Width;
            int y = index / world.Width;
            world.CellNavAnchors[index] = world.GridToWorldCenter(x, y);
            world.CellNavAnchorsFixedXZ[index] = world.GridToWorldCenterFixed(x, y);
            if (!forceComplete && IsBudgetExpired(deadlineTicks, job.CellCursor))
                return;
        }

        job.CellCursor = 0;
        job.Stage = WorldBuildStage.NeighborMask;
    }

    private static void ProcessWorldBuildNeighborMask(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildNeighborMask failed: working world is null.");

        int cellCount = world.Width * world.Height;
        while (job.CellCursor < cellCount)
        {
            int index = job.CellCursor++;
            RebuildNeighborTraversalMaskCell(world, index % world.Width, index / world.Width);
            if (!forceComplete && IsBudgetExpired(deadlineTicks, job.CellCursor))
                return;
        }

        job.CellCursor = 0;
        job.Stage = WorldBuildStage.SymmetrizeNeighborMask;
    }

    private static void ProcessWorldBuildSymmetrizeNeighborMask(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildSymmetrizeNeighborMask failed: working world is null.");
        if (world.NeighborTraversalMask == null || world.NeighborTraversalMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("ProcessWorldBuildSymmetrizeNeighborMask failed: neighbor traversal mask is invalid.");

        int cellCount = world.Width * world.Height;
        while (job.CellCursor < cellCount)
        {
            int index = job.CellCursor++;
            int x = index % world.Width;
            int y = index / world.Width;
            SymmetrizeNeighborTraversalMaskCell(world, x, y, "ProcessWorldBuildSymmetrizeNeighborMask");
            if (!forceComplete && IsBudgetExpired(deadlineTicks, job.CellCursor))
                return;
        }

        PruneIsolatedWalkableCells(world, "world-build");
        job.SectorCursor = 0;
        job.CellCursor = 0;
        job.Stage = WorldBuildStage.CostField;
    }

    private static void ProcessWorldBuildCostField(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildCostField failed: working world is null.");

        while (job.SectorCursor < world.Sectors.Length)
        {
            if (world.SourceCostField != null && world.SourceCostField.Length == world.Width * world.Height)
                InitializeAuthoredCostFieldForSector(world, world.Sectors[job.SectorCursor], job.CostStamps);
            else
                RebuildCostFieldForSector(world, job.SectorCursor, job.CostStamps);

            job.SectorCursor++;
            if (!forceComplete && IsBudgetExpired(deadlineTicks, job.SectorCursor))
                return;
        }

        job.SectorCursor = 0;
        job.Stage = WorldBuildStage.IslandField;
    }

    private static void ProcessWorldBuildIslandField(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        ProcessWorldBuildIslandFieldInternal(job, deadlineTicks, forceComplete);
    }

    private static void ProcessWorldBuildIslandFieldInternal(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildIslandField failed: working world is null.");

        if (!job.IslandInitialized)
        {
            Array.Clear(world.IslandIds, 0, world.IslandIds.Length);
            world.IslandCount = 0;
            world.MainIslandId = 0;
            world.MainIslandSize = 0;
            job.IslandOpenQueue = new Queue<int>(256);
            job.IslandScanIndex = 0;
            job.IslandCurrentId = 0;
            job.IslandCurrentSize = 0;
            job.IslandMainId = 0;
            job.IslandMainSize = 0;
            job.IslandBfsActive = false;
            job.IslandInitialized = true;
        }

        AdvanceIslandFieldBuild(
            world,
            job.IslandOpenQueue,
            ref job.IslandScanIndex,
            ref job.IslandCurrentId,
            ref job.IslandCurrentSize,
            ref job.IslandMainId,
            ref job.IslandMainSize,
            ref job.IslandBfsActive,
            deadlineTicks,
            forceComplete,
            out bool complete);
        if (!complete)
            return;

        RebuildAllSectorLocalComponents(world);
        LogIslandFieldDiagnostics(world, "world-build-pending");
        job.Stage = WorldBuildStage.PortalGraph;
    }

    private static void ProcessWorldBuildPortalGraph(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (world == null)
            throw new InvalidOperationException("ProcessWorldBuildPortalGraph failed: working world is null.");

        if (!job.PortalInitialized)
        {
            job.PendingPortalAccessEntries ??= new List<PendingSectorPortalAccess>();
            job.PendingPortalAccessEntries.Clear();
            world.UsedPortalIds.Clear();
            for (int i = 0; i < world.Sectors.Length; i++)
            {
                world.Sectors[i].PortalIds.Clear();
                world.Sectors[i].PortalTransitions.Clear();
            }

            world.PortalsById = new Dictionary<int, PortalData>();
            job.PortalRebuiltPortals = new List<PortalData>();
            job.PortalStage = RuntimeDirtyPortalStage.RebuildBoundaries;
            job.PortalAddCursor = 0;
            job.PortalTransitionCursor = 0;
            job.PortalTransitionFromCursor = 0;
            job.PortalInitialized = true;
        }

        while (job.PortalStage != RuntimeDirtyPortalStage.Complete)
        {
            switch (job.PortalStage)
            {
                case RuntimeDirtyPortalStage.RebuildBoundaries:
                    long boundaryStartTicks = Stopwatch.GetTimestamp();
                    BuildVerticalPortals(world, job.PortalRebuiltPortals);
                    BuildHorizontalPortals(world, job.PortalRebuiltPortals);
                    job.PortalGraphBoundaryTicks += Stopwatch.GetTimestamp() - boundaryStartTicks;
                    job.PortalStage = RuntimeDirtyPortalStage.AddRebuiltPortals;
                    break;
                case RuntimeDirtyPortalStage.AddRebuiltPortals:
                    while (job.PortalAddCursor < job.PortalRebuiltPortals.Count)
                    {
                        long addStartTicks = Stopwatch.GetTimestamp();
                        PortalData portal = job.PortalRebuiltPortals[job.PortalAddCursor++];
                        if (world.PortalsById.ContainsKey(portal.PortalId))
                            throw new InvalidOperationException($"ProcessWorldBuildPortalGraph failed: duplicate portal id {portal.PortalId}.");

                        world.PortalsById.Add(portal.PortalId, portal);
                        world.Sectors[portal.SectorAId].PortalIds.Add(portal.PortalId);
                        world.Sectors[portal.SectorBId].PortalIds.Add(portal.PortalId);
                        job.PortalGraphAddTicks += Stopwatch.GetTimestamp() - addStartTicks;
                        if (!forceComplete && IsBudgetExpired(deadlineTicks, job.PortalAddCursor))
                            return;
                    }

                    world.Portals = job.PortalRebuiltPortals.ToArray();
                    job.PortalStage = RuntimeDirtyPortalStage.RebuildTransitions;
                    break;
                case RuntimeDirtyPortalStage.RebuildTransitions:
                    ProcessWorldBuildPortalTransitions(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyPortalStage.RemoveOldPortals:
                    job.PortalStage = RuntimeDirtyPortalStage.RebuildBoundaries;
                    break;
                default:
                    throw new InvalidOperationException($"ProcessWorldBuildPortalGraph failed: unknown portal stage {job.PortalStage}.");
            }

            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        LogWorldBuildPortalGraphTiming(job);
        RemoveStalePortalSignatures(world);
        job.Stage = WorldBuildStage.Commit;
    }

    private static void ProcessWorldBuildPortalTransitions(WorldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        while (job.PortalTransitionCursor < world.Sectors.Length)
        {
            SectorData sector = world.Sectors[job.PortalTransitionCursor];
            if (job.PortalTransitionFromCursor == 0)
                sector.PortalTransitions.Clear();

            if (sector.PortalIds.Count == 0)
            {
                RebuildIncomingPortalTransitionIndex(sector);
                job.PortalTransitionCursor++;
                job.PortalTransitionFromCursor = 0;
                continue;
            }

            while (job.PortalTransitionFromCursor < sector.PortalIds.Count)
            {
                int fromPortalId = sector.PortalIds[job.PortalTransitionFromCursor];
                bool analytic = CanUseAnalyticPortalAccess(
                    world,
                    sector,
                    fromPortalId,
                    out AnalyticPortalAccessDiagnostics analyticDiagnostics);
                job.PortalGraphAnalyticCheckCount++;
                if (analyticDiagnostics.IsClearSector)
                    job.PortalGraphAnalyticClearSectorCount++;
                if (analyticDiagnostics.RejectReason == AnalyticPortalAccessRejectReason.MultipleLocalComponents)
                    job.PortalGraphAnalyticMultiComponentRejectCount++;
                else if (analyticDiagnostics.RejectReason == AnalyticPortalAccessRejectReason.NonClearSector)
                    job.PortalGraphAnalyticNonClearRejectCount++;

                if (analytic)
                    AddPendingAnalyticSectorPortalAccess(job.PendingPortalAccessEntries, sector, fromPortalId);
                else
                    AddPendingDeterministicSectorPortalAccess(job.PendingPortalAccessEntries, sector, fromPortalId);

                AddDeterministicPortalTransitionTopology(world, sector, fromPortalId);
                job.PortalGraphAccessCount++;
                job.PortalGraphTransitionCostChecks++;
                if (analytic)
                    job.PortalGraphAnalyticAccessCount++;

                job.PortalTransitionFromCursor++;
                if (!forceComplete && IsBudgetExpired(deadlineTicks, job.PortalTransitionFromCursor))
                    return;
            }

            RebuildIncomingPortalTransitionIndex(sector);
            job.PortalTransitionCursor++;
            job.PortalTransitionFromCursor = 0;
        }

        job.PortalStage = RuntimeDirtyPortalStage.Complete;
    }

    private static void AddDeterministicPortalTransitionTopology(
        NavigationWorld world,
        SectorData sector,
        int fromPortalId)
    {
        if (world == null)
            throw new InvalidOperationException("AddDeterministicPortalTransitionTopology failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("AddDeterministicPortalTransitionTopology failed: sector is null.");

        for (int i = 0; i < sector.PortalIds.Count; i++)
        {
            int toPortalId = sector.PortalIds[i];
            if (toPortalId == fromPortalId
                || !PortalsShareSectorLocalComponent(world, sector, fromPortalId, toPortalId))
            {
                continue;
            }

            AddPortalTransitionIfMissing(sector, fromPortalId, toPortalId);
        }
    }

    private static void CommitWorldBuildJob(WorldRuntimeState state, WorldBuildJob job)
    {
        if (job.WorkingWorld == null)
            throw new InvalidOperationException("CommitWorldBuildJob failed: working world is null.");

        int previousWorldVersion = state.World != null ? state.World.Version : 0;
        _perf.WorldBuilds++;
        state.World = job.WorkingWorld;
        state.World.Version = _nextWorldVersion++;
        _navigationTopologyVersion++;
        LogIslandFieldDiagnostics(state.World, "world-build");
        state.IsDirty = false;
        state.DirtyRuntimeObstacleSectors.Clear();
        state.RuntimeDirtyJob = null;
        ClearFlowTileCache();
        ReturnPendingFlowTileBuildIntegrations();
        FlowTileBuildQueue.Clear();
        PendingFlowTileBuildJobs.Clear();
        ActiveFlowTileBuildKeys.Clear();
        ClearSectorPathCache();
        StartPortalChoiceCache.Clear();
        RemoveSectorPortalAccessCacheEntriesForWorldVersion(previousWorldVersion);
        ClearSharedGoalFieldCache();
        SharedGoalFieldBuildQueue.Clear();
        PendingSharedGoalFieldBuildJobs.Clear();
        ActiveSharedGoalFieldBuildKeys.Clear();
        ActiveSharedGoalFieldDemandStartSectors.Clear();
        ActiveSharedGoalFieldDemandStartCells.Clear();
        s_NavigationDistancePrewarmCompleted = false;
        CommitPendingSectorPortalAccessEntries(
            state.World,
            job.PendingPortalAccessEntries,
            entriesAreFinalized: false);
        EnsureAllSectorPortalAccessCoverage(state.World, "world-build-commit");
        FinalizeWorldCostStorage(state.World);
        RebuildDeterministicPortalTransitionCosts(state.World);
        ValidateAllSectorPortalAccessCoverage(state.World, "world-build-commit");
        RefreshNavigationWorldDeterministicHash(state.World);
        CombatTargetSlotCache.Clear();
        ClearFixedPortalOwnersForWorld(previousWorldVersion);
        _world = state.World;

        if (GameDebugSettings.IsEnabled(DebugCategory.Move))
        {
            int walkableCount = 0;
            bool[] walkableMask = state.World.WalkableMask;
            for (int i = 0; i < walkableMask.Length; i++)
            {
                if (walkableMask[i])
                    walkableCount++;
            }

            LogNoStacktrace(
                $"[FlowWorld] Rebuilt worldVersion={state.World.Version} agentType={job.AgentTypeId} size={job.Width}x{job.Height} cellSize={job.CellSize:F3} " +
                $"origin={job.Origin} walkable={walkableCount}/{walkableMask.Length} dirtyReason={job.Reason}");
        }
    }

    private static WorldRuntimeState GetOrCreateWorldState(int agentTypeId)
    {
        if (!WorldStates.TryGetValue(agentTypeId, out WorldRuntimeState state))
        {
            state = new WorldRuntimeState { AgentTypeId = agentTypeId };
            WorldStates.Add(agentTypeId, state);
        }

        state.AgentTypeId = agentTypeId;
        return state;
    }

    private static string BuildCellProbeDiagnostics(NavigationWorld world, int x, int y)
    {
        if (world == null)
            return "centerProbe=world-null";
        if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
            return $"centerProbe={{cell=({x},{y}) inGrid=False}}";

        int index = world.GetIndex(x, y);
        return $"centerProbe={{cell=({x},{y}) center={world.GridToWorldCenter(x, y)} walk={world.WalkableMask[index]} base={world.BaseWalkableMask[index]} island={ResolveIslandIdForDiagnostics(world, x, y)} mask=0x{(world.NeighborTraversalMask != null && world.NeighborTraversalMask.Length == world.Width * world.Height ? world.NeighborTraversalMask[index].ToString("X2") : "NA")}}}";
    }

    private static string BuildWalkableNeighborhoodDiagnostics(NavigationWorld world, int centerX, int centerY, int radius)
    {
        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append("neighborhood=[");
        bool first = true;
        for (int y = centerY - radius; y <= centerY + radius; y++)
        {
            for (int x = centerX - radius; x <= centerX + radius; x++)
            {
                if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
                    continue;

                if (!first)
                    builder.Append("; ");
                first = false;

                int index = world.GetIndex(x, y);
                Vector3 cellCenter = world.GridToWorldCenter(x, y);
                builder.Append("(");
                builder.Append(x);
                builder.Append(",");
                builder.Append(y);
                builder.Append(")");
                builder.Append("{walk=");
                builder.Append(world.WalkableMask[index]);
                builder.Append(",base=");
                builder.Append(world.BaseWalkableMask[index]);
                builder.Append(",island=");
                builder.Append(world.IslandIds != null && world.IslandIds.Length == world.Width * world.Height ? world.IslandIds[index] : -1);
                builder.Append(",mask=0x");
                builder.Append(world.NeighborTraversalMask != null && world.NeighborTraversalMask.Length == world.Width * world.Height
                    ? world.NeighborTraversalMask[index].ToString("X2")
                    : "NA");
                builder.Append(",center=");
                builder.Append(cellCenter);
                builder.Append("}");
            }
        }

        builder.Append("]");
        return builder.ToString();
    }

    private static string BuildNearestWalkableSearchDiagnostics(NavigationWorld world, int startX, int startY, int radius)
    {
        System.Text.StringBuilder builder = new System.Text.StringBuilder(256);
        builder.Append("nearestSearch=[");
        bool first = true;
        for (int r = 1; r <= radius; r++)
        {
            int foundCount = 0;
            for (int y = -r; y <= r; y++)
            {
                for (int x = -r; x <= r; x++)
                {
                    int nx = startX + x;
                    int ny = startY + y;
                    if (!world.IsWalkable(nx, ny))
                        continue;

                    foundCount++;
                }
            }

            if (!first)
                builder.Append("; ");
            first = false;
            builder.Append("r=");
            builder.Append(r);
            builder.Append(" found=");
            builder.Append(foundCount);
        }

        builder.Append("]");
        return builder.ToString();
    }

    private static void BlockCellsByCircle(bool[] walkableMask, int width, int height, float cellSize, Vector3 origin, Vector3 center, float radius)
    {
        Bounds bounds = new Bounds(center, new Vector3(radius * 2f, 0f, radius * 2f));
        int minX = Mathf.Clamp(Mathf.FloorToInt((bounds.min.x - origin.x) / cellSize), 0, width - 1);
        int maxX = Mathf.Clamp(Mathf.FloorToInt((bounds.max.x - origin.x) / cellSize), 0, width - 1);
        int minY = Mathf.Clamp(Mathf.FloorToInt((bounds.min.z - origin.z) / cellSize), 0, height - 1);
        int maxY = Mathf.Clamp(Mathf.FloorToInt((bounds.max.z - origin.z) / cellSize), 0, height - 1);
        float blockRadius = radius + cellSize * 0.45f;
        float blockRadiusSq = blockRadius * blockRadius;

        Vector2 centerXZ = new Vector2(center.x, center.z);
        for (int y = minY; y <= maxY; y++)
        {
            for (int x = minX; x <= maxX; x++)
            {
                Vector2 cellCenter = new Vector2(origin.x + (x + 0.5f) * cellSize, origin.z + (y + 0.5f) * cellSize);
                if ((cellCenter - centerXZ).sqrMagnitude <= blockRadiusSq)
                    walkableMask[x + y * width] = false;
            }
        }
    }

    private static void BlockCellsByCircleFixed(
        NavigationWorld world,
        FixVector2 center,
        Fix64 radius)
    {
        if (world == null)
            throw new InvalidOperationException("BlockCellsByCircleFixed failed: world is null.");
        if (world.WalkableMask == null || world.WalkableMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("BlockCellsByCircleFixed failed: invalid walkable mask.");
        if (world.Width <= 0 || world.Height <= 0 || world.CellSizeGridRaw <= 0 || radius < Fix64.Zero)
            throw new ArgumentOutOfRangeException(nameof(radius), "BlockCellsByCircleFixed received invalid geometry.");

        int minX = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.x - radius, world.OriginXGridRaw, world.CellSizeGridRaw), 0, world.Width - 1);
        int maxX = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.x + radius, world.OriginXGridRaw, world.CellSizeGridRaw), 0, world.Width - 1);
        int minY = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.y - radius, world.OriginZGridRaw, world.CellSizeGridRaw), 0, world.Height - 1);
        int maxY = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.y + radius, world.OriginZGridRaw, world.CellSizeGridRaw), 0, world.Height - 1);
        Fix64 cellSize = world.CellSizeFixed;
        Fix64 blockRadius = radius + cellSize * Fix64.FromRaw(1844);
        Fix64 blockRadiusSquared = blockRadius * blockRadius;
        for (int y = minY; y <= maxY; y++)
        {
            for (int x = minX; x <= maxX; x++)
            {
                FixVector2 cellCenter = world.GridToWorldGeometricCenterFixed(x, y);
                if (FixVector2.SqrMagnitude(cellCenter - center) <= blockRadiusSquared)
                    world.WalkableMask[x + y * world.Width] = false;
            }
        }
    }

    private static void BlockCellsByBounds(bool[] walkableMask, int width, int height, float cellSize, Vector3 origin, Bounds bounds)
    {
        int minX = Mathf.Clamp(Mathf.FloorToInt((bounds.min.x - origin.x) / cellSize), 0, width - 1);
        int maxX = Mathf.Clamp(Mathf.FloorToInt((bounds.max.x - origin.x) / cellSize), 0, width - 1);
        int minY = Mathf.Clamp(Mathf.FloorToInt((bounds.min.z - origin.z) / cellSize), 0, height - 1);
        int maxY = Mathf.Clamp(Mathf.FloorToInt((bounds.max.z - origin.z) / cellSize), 0, height - 1);

        for (int y = minY; y <= maxY; y++)
        {
            for (int x = minX; x <= maxX; x++)
            {
                Vector3 cellCenter = new Vector3(origin.x + (x + 0.5f) * cellSize, bounds.center.y, origin.z + (y + 0.5f) * cellSize);
                if (bounds.Contains(cellCenter))
                    walkableMask[x + y * width] = false;
            }
        }
    }

    private static void BlockCellsByBoxFixed(
        NavigationWorld world,
        FixVector2 center,
        FixVector2 halfExtents)
    {
        if (world == null)
            throw new InvalidOperationException("BlockCellsByBoxFixed failed: world is null.");
        if (world.WalkableMask == null || world.WalkableMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("BlockCellsByBoxFixed failed: invalid walkable mask.");
        if (world.Width <= 0 || world.Height <= 0 || world.CellSizeGridRaw <= 0
            || halfExtents.x < Fix64.Zero || halfExtents.y < Fix64.Zero)
        {
            throw new ArgumentOutOfRangeException(nameof(halfExtents), "BlockCellsByBoxFixed received invalid geometry.");
        }

        int minX = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.x - halfExtents.x, world.OriginXGridRaw, world.CellSizeGridRaw), 0, world.Width - 1);
        int maxX = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.x + halfExtents.x, world.OriginXGridRaw, world.CellSizeGridRaw), 0, world.Width - 1);
        int minY = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.y - halfExtents.y, world.OriginZGridRaw, world.CellSizeGridRaw), 0, world.Height - 1);
        int maxY = Mathf.Clamp(NavigationGridFixedMath.WorldToGridCell(center.y + halfExtents.y, world.OriginZGridRaw, world.CellSizeGridRaw), 0, world.Height - 1);
        for (int y = minY; y <= maxY; y++)
        {
            for (int x = minX; x <= maxX; x++)
            {
                FixVector2 cellCenter = world.GridToWorldGeometricCenterFixed(x, y);
                FixVector2 delta = cellCenter - center;
                if (Fix64.Abs(delta.x) <= halfExtents.x && Fix64.Abs(delta.y) <= halfExtents.y)
                    world.WalkableMask[x + y * world.Width] = false;
            }
        }
    }

    private static void RemovePortalsTouchingSectors(NavigationWorld world, HashSet<int> affectedSectors, HashSet<int> transitionDirtySectors)
    {
        List<int> portalIdsToRemove = null;
        foreach (KeyValuePair<int, PortalData> pair in world.PortalsById)
        {
            PortalData portal = pair.Value;
            if (!affectedSectors.Contains(portal.SectorAId) && !affectedSectors.Contains(portal.SectorBId))
                continue;

            portalIdsToRemove ??= new List<int>();
            portalIdsToRemove.Add(pair.Key);
        }

        if (portalIdsToRemove == null)
            return;

        for (int i = 0; i < portalIdsToRemove.Count; i++)
        {
            int portalId = portalIdsToRemove[i];
            if (!world.PortalsById.TryGetValue(portalId, out PortalData portal))
                continue;

            world.PortalsById.Remove(portalId);
            world.UsedPortalIds.Remove(portalId);
            PortalSignature signature = BuildPortalSignature(
                portal.SectorAId,
                portal.SectorBId,
                portal.CellsA,
                portal.IsVerticalBoundary);
            if (!world.PortalIdsBySignature.TryGetValue(signature, out int signaturePortalId)
                || signaturePortalId != portalId)
            {
                throw new InvalidOperationException(
                    $"RemovePortalsTouchingSectors failed: portal signature mismatch portal={portalId} signaturePortal={signaturePortalId}.");
            }
            world.PortalIdsBySignature.Remove(signature);
            world.Sectors[portal.SectorAId].PortalIds.Remove(portalId);
            world.Sectors[portal.SectorBId].PortalIds.Remove(portalId);
            transitionDirtySectors.Add(portal.SectorAId);
            transitionDirtySectors.Add(portal.SectorBId);
        }
    }

    private static void RebuildPortalBoundariesForSector(
        NavigationWorld world,
        int sectorId,
        HashSet<int> affectedSectors,
        HashSet<long> processedBoundaries,
        List<PortalData> portals)
    {
        if (sectorId < 0 || sectorId >= world.Sectors.Length)
            return;

        int sectorX = sectorId % world.SectorCountX;
        int sectorY = sectorId / world.SectorCountX;
        TryRebuildPortalBoundary(world, sectorId, sectorX + 1, sectorY, affectedSectors, processedBoundaries, portals);
        TryRebuildPortalBoundary(world, sectorId, sectorX - 1, sectorY, affectedSectors, processedBoundaries, portals);
        TryRebuildPortalBoundary(world, sectorId, sectorX, sectorY + 1, affectedSectors, processedBoundaries, portals);
        TryRebuildPortalBoundary(world, sectorId, sectorX, sectorY - 1, affectedSectors, processedBoundaries, portals);
    }

    private static void TryRebuildPortalBoundary(
        NavigationWorld world,
        int sectorId,
        int neighborSectorX,
        int neighborSectorY,
        HashSet<int> affectedSectors,
        HashSet<long> processedBoundaries,
        List<PortalData> portals)
    {
        if (neighborSectorX < 0 || neighborSectorX >= world.SectorCountX || neighborSectorY < 0 || neighborSectorY >= world.SectorCountY)
            return;

        int neighborSectorId = neighborSectorY * world.SectorCountX + neighborSectorX;
        if (!affectedSectors.Contains(sectorId) && !affectedSectors.Contains(neighborSectorId))
            return;

        int minSectorId = Mathf.Min(sectorId, neighborSectorId);
        int maxSectorId = Mathf.Max(sectorId, neighborSectorId);
        long boundaryKey = ((long)minSectorId << 32) | (uint)maxSectorId;
        if (!processedBoundaries.Add(boundaryKey))
            return;

        int sectorX = sectorId % world.SectorCountX;
        int sectorY = sectorId / world.SectorCountX;
        if (neighborSectorY == sectorY)
        {
            int leftId = sectorX < neighborSectorX ? sectorId : neighborSectorId;
            int rightId = sectorX < neighborSectorX ? neighborSectorId : sectorId;
            BuildVerticalBoundaryPortals(world, portals, world.Sectors[leftId], world.Sectors[rightId]);
            return;
        }

        int topId = sectorY < neighborSectorY ? sectorId : neighborSectorId;
        int bottomId = sectorY < neighborSectorY ? neighborSectorId : sectorId;
        BuildHorizontalBoundaryPortals(world, portals, world.Sectors[topId], world.Sectors[bottomId]);
    }

    private static PortalData[] BuildPortalArray(NavigationWorld world)
    {
        if (world == null || world.PortalsById == null)
            throw new InvalidOperationException("BuildPortalArray failed: world or portal lookup is null.");

        PortalData[] portals = new PortalData[world.PortalsById.Count];
        var portalIds = new List<int>(world.PortalsById.Keys);
        portalIds.Sort();
        for (int i = 0; i < portalIds.Count; i++)
        {
            int portalId = portalIds[i];
            PortalData portal = world.PortalsById[portalId];
            if (portal == null || portal.PortalId != portalId)
                throw new InvalidOperationException($"BuildPortalArray failed: portal lookup mismatch key={portalId}, value={portal?.PortalId.ToString() ?? "null"}.");
            portals[i] = portal;
        }
        return portals;
    }

    private static void InvalidateRuntimeDirtyJob(WorldRuntimeState state)
    {
        if (state == null)
            throw new InvalidOperationException("InvalidateRuntimeDirtyJob failed: state is null.");

        if (state.RuntimeDirtyJob != null)
        {
            foreach (int sectorId in state.RuntimeDirtyJob.DirtySectors)
                state.DirtyRuntimeObstacleSectors.Add(sectorId);
            foreach (int sectorId in state.RuntimeDirtyJob.CostDirtySectors)
                state.DirtyRuntimeObstacleSectors.Add(sectorId);
            ReturnRuntimeDirtyWorkingWorld(state.RuntimeDirtyJob);
        }

        state.RuntimeDirtyJob = null;
    }

    private static bool EnsureRuntimeDirtyJob(WorldRuntimeState state)
    {
        if (state == null || state.World == null)
            return false;
        if (state.RuntimeDirtyJob != null)
            return true;
        if (state.DirtyRuntimeObstacleSectors.Count == 0)
            return false;

        NavigationWorld world = state.World;
        HashSet<int> dirtySectors = new HashSet<int>(state.DirtyRuntimeObstacleSectors);
        HashSet<int> costDirtySectors = ExpandDirtySectorsByCellRadius(world, dirtySectors, ResolveWallCostPaddingCells(world, 1));
        RuntimeDirtyRebuildJob job = new RuntimeDirtyRebuildJob
        {
            TargetWorld = world,
            DirtySectors = dirtySectors,
            CostDirtySectors = costDirtySectors,
            DirtySectorIds = CreateSortedSectorIdSnapshot(dirtySectors, "dirty sectors"),
            CostDirtySectorIds = CreateSortedSectorIdSnapshot(costDirtySectors, "cost dirty sectors"),
            CircleObstacles = CreateSortedCircleObstacleSnapshot(CircleObstacles.Values),
            BoxObstacles = CreateSortedBoxObstacleSnapshot(BoxObstacles.Values),
            CostStamps = CreateSortedCostStampSnapshot(CostStamps.Values),
            Stage = RuntimeDirtyRebuildStage.InitializeClone,
            Reason = _lastRuntimeObstacleDirtyReason
        };
        RefreshRuntimeDirtyAuthorityInputHash(job);

        state.RuntimeDirtyJob = job;
        state.DirtyRuntimeObstacleSectors.Clear();
        _perf.RuntimeDirtyApplications++;
        _perf.RuntimeDirtySectorCount += dirtySectors.Count;
        LogNoStacktrace(
            $"[FlowRuntimeDirtyQueued] worldVersion={world.Version} dirtySectors={dirtySectors.Count} costSectors={costDirtySectors.Count} " +
            $"reason={job.Reason} circleCount={job.CircleObstacles.Count} boxCount={job.BoxObstacles.Count} costStampCount={CostStamps.Count}");
        return true;
    }

    private static void ProcessRuntimeDirtyJob(WorldRuntimeState state, long deadlineTicks, bool forceComplete)
    {
        RuntimeDirtyRebuildJob job = state.RuntimeDirtyJob;
        if (job == null)
            return;

        EnsureRuntimeDirtyTimingStarted(job);
        while (job.Stage != RuntimeDirtyRebuildStage.Complete)
        {
            RuntimeDirtyRebuildStage stageBefore = job.Stage;
            long stageStartTimestamp = Stopwatch.GetTimestamp();
            switch (job.Stage)
            {
                case RuntimeDirtyRebuildStage.InitializeClone:
                    ProcessRuntimeDirtyClone(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.ResetWalkable:
                    ProcessRuntimeDirtyResetWalkable(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.ApplyObstacles:
                    ProcessRuntimeDirtyObstacles(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.NeighborMask:
                    ProcessRuntimeDirtyNeighborMask(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.SymmetrizeNeighborMask:
                    SymmetrizeNeighborTraversalMaskForSectors(job.WorkingWorld, job.DirtySectors);
                    PruneIsolatedWalkableCellsForSectors(job.WorkingWorld, job.DirtySectors, "runtime-dirty");
                    job.SectorCursor = 0;
                    job.Stage = RuntimeDirtyRebuildStage.CostField;
                    break;
                case RuntimeDirtyRebuildStage.CostField:
                    ProcessRuntimeDirtyCostField(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.IslandField:
                    ProcessRuntimeDirtyIslandField(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.SectorComponents:
                    ProcessRuntimeDirtySectorComponents(job, deadlineTicks, forceComplete);
                    break;
                case RuntimeDirtyRebuildStage.PortalGraph:
                    if (!ProcessRuntimeDirtyPortalGraph(job, deadlineTicks, forceComplete))
                        return;
                    break;
                case RuntimeDirtyRebuildStage.PrepareCommit:
                    PrepareRuntimeDirtyCommit(job);
                    job.Stage = RuntimeDirtyRebuildStage.WorldHash;
                    break;
                case RuntimeDirtyRebuildStage.WorldHash:
                    ProcessNavigationWorldHashBuildJob(job.WorldHashBuildJob, deadlineTicks, forceComplete);
                    if (job.WorldHashBuildJob.Complete)
                    {
                        job.WorkingWorld.DeterministicContentHash = job.WorldHashBuildJob.Hash;
                        job.WorkingWorld.HasDeterministicContentHash = true;
                        job.Stage = RuntimeDirtyRebuildStage.Commit;
                    }
                    break;
                case RuntimeDirtyRebuildStage.Commit:
                    CommitRuntimeDirtyJob(state, job);
                    job.Stage = RuntimeDirtyRebuildStage.Complete;
                    break;
                default:
                    throw new InvalidOperationException($"ProcessRuntimeDirtyJob failed: unknown stage {job.Stage}.");
            }

            long stageElapsedTicks = Stopwatch.GetTimestamp() - stageStartTimestamp;
            if (stageBefore >= 0 && stageBefore < RuntimeDirtyRebuildStage.Complete)
                job.StageAccumulatedTicks[(int)stageBefore] += stageElapsedTicks;

            LogRuntimeDirtyStageTimingIfNeeded(job, stageBefore, stageStartTimestamp, forceComplete);
            if (job.Stage == RuntimeDirtyRebuildStage.Complete)
                break;

            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        state.RuntimeDirtyJob = null;
    }

    private static void EnsureRuntimeDirtyTimingStarted(RuntimeDirtyRebuildJob job)
    {
        if (job == null)
            throw new InvalidOperationException("EnsureRuntimeDirtyTimingStarted failed: job is null.");
        if (job.TimingInitialized)
            return;

        long now = Stopwatch.GetTimestamp();
        job.BuildStartedTimestamp = now;
        job.StageStartedTimestamp = now;
        job.TimedStage = job.Stage;
        job.TimingInitialized = true;
        LogNoStacktrace($"[FlowRuntimeDirtyStage] begin worldVersion={job.TargetWorld?.Version ?? 0} reason={job.Reason} {BuildRuntimeDirtyTimingSummary(job)}");
    }

    private static void LogRuntimeDirtyStageTimingIfNeeded(RuntimeDirtyRebuildJob job, RuntimeDirtyRebuildStage stageBefore, long stageStartTimestamp, bool forceComplete)
    {
        if (job == null)
            throw new InvalidOperationException("LogRuntimeDirtyStageTimingIfNeeded failed: job is null.");

        bool stageChanged = job.Stage != stageBefore;
        long now = Stopwatch.GetTimestamp();
        double elapsedMs = TicksToMilliseconds(now - stageStartTimestamp);
        if (!stageChanged && (!forceComplete || elapsedMs < 5.0))
            return;

        double totalMs = TicksToMilliseconds(now - job.BuildStartedTimestamp);
        LogNoStacktrace(
            $"[FlowRuntimeDirtyStage] worldVersion={job.TargetWorld?.Version ?? 0} stage={stageBefore} next={job.Stage} " +
            $"elapsedMs={elapsedMs:F3} totalMs={totalMs:F3} forceComplete={forceComplete} {BuildRuntimeDirtyTimingSummary(job)}");
    }

    private static string BuildRuntimeDirtyTimingSummary(RuntimeDirtyRebuildJob job)
    {
        NavigationWorld world = job.WorkingWorld ?? job.TargetWorld;
        int sectorCount = world?.Sectors != null ? world.Sectors.Length : 0;
        int portalCount = world?.PortalsById != null ? world.PortalsById.Count : 0;
        int transitionCount = CountPortalTransitions(world);
        int dirtyCount = job.DirtySectorIds != null ? job.DirtySectorIds.Count : 0;
        int costDirtyCount = job.CostDirtySectorIds != null ? job.CostDirtySectorIds.Count : 0;
        int circleCount = job.CircleObstacles != null ? job.CircleObstacles.Count : 0;
        int boxCount = job.BoxObstacles != null ? job.BoxObstacles.Count : 0;
        int costStampCount = job.CostStamps != null ? job.CostStamps.Count : 0;
        int pendingPortalAccessCount = job.PendingPortalAccessEntries != null ? job.PendingPortalAccessEntries.Count : 0;
        int sectorSize = world != null ? world.SectorSizeInCells : Config.SectorSizeInCells;
        int sectorCountX = world != null ? world.SectorCountX : 0;
        int sectorCountY = world != null ? world.SectorCountY : 0;
        int islandCount = world != null ? world.IslandCount : 0;
        int mainIslandSize = world != null ? world.MainIslandSize : 0;

        return
            $"size={(world != null ? world.Width : 0)}x{(world != null ? world.Height : 0)} cellSize={(world != null ? world.CellSize : 0f):F3} " +
            $"sectorSize={sectorSize} sectors={sectorCount}({sectorCountX}x{sectorCountY}) dirtySectors={dirtyCount} costSectors={costDirtyCount} " +
            $"portals={portalCount} transitions={transitionCount} pendingPortalAccess={pendingPortalAccessCount} " +
            $"islands={islandCount} mainIslandSize={mainIslandSize} obstacles(circle={circleCount},box={boxCount},cost={costStampCount}) " +
            $"cursors(sector={job.SectorCursor},obstacle={job.ObstacleCursor},portalSector={job.PortalTransitionCursor},portalFrom={job.PortalTransitionFromCursor}) " +
            BuildRuntimeDirtyStageAccumulatedTiming(job);
    }

    private static string BuildRuntimeDirtyStageAccumulatedTiming(RuntimeDirtyRebuildJob job)
    {
        if (job?.StageAccumulatedTicks == null || job.StageAccumulatedTicks.Length < (int)RuntimeDirtyRebuildStage.Complete)
            return "stageAccum=invalid";

        return
            $"stageAccum(reset={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.ResetWalkable]):F3}ms," +
            $"obstacles={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.ApplyObstacles]):F3}ms," +
            $"neighbor={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.NeighborMask]):F3}ms," +
            $"sym={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.SymmetrizeNeighborMask]):F3}ms," +
            $"cost={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.CostField]):F3}ms," +
            $"island={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.IslandField]):F3}ms," +
            $"portal={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.PortalGraph]):F3}ms," +
            $"prepare={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.PrepareCommit]):F3}ms," +
            $"hash={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.WorldHash]):F3}ms," +
            $"commit={TicksToMilliseconds(job.StageAccumulatedTicks[(int)RuntimeDirtyRebuildStage.Commit]):F3}ms)";
    }

    private static string BuildRuntimeDirtyCommitTiming(RuntimeDirtyRebuildJob job)
    {
        return
            $"commitDetail(swap={TicksToMilliseconds(job.CommitSwapTicks):F3}ms," +
            $"cache={TicksToMilliseconds(job.CommitCacheInvalidationTicks):F3}ms," +
            $"portalAccess={TicksToMilliseconds(job.CommitPortalAccessTicks):F3}ms," +
            $"costStorage={TicksToMilliseconds(job.CommitCostStorageTicks):F3}ms," +
            $"transitionCost={TicksToMilliseconds(job.CommitTransitionCostTicks):F3}ms," +
            $"validation={TicksToMilliseconds(job.CommitValidationTicks):F3}ms," +
            $"worldHash={TicksToMilliseconds(job.CommitWorldHashTicks):F3}ms," +
            $"agents={TicksToMilliseconds(job.CommitAgentInvalidationTicks):F3}ms)";
    }

    private static void ProcessRuntimeDirtyClone(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld source = job.TargetWorld;
        if (source == null)
            throw new InvalidOperationException("ProcessRuntimeDirtyClone failed: target world is null.");

        while (!job.CloneShellInitialized)
        {
            switch (job.CloneShellStage)
            {
                case RuntimeDirtyCloneShellStage.CreateMetadata:
                    job.WorkingWorld = new NavigationWorld
                    {
                        Version = source.Version,
                        AgentTypeId = source.AgentTypeId,
                        Width = source.Width,
                        Height = source.Height,
                        CellSize = source.CellSize,
                        EncodedCenterClearance = source.EncodedCenterClearance,
                        Origin = source.Origin,
                        BaseWalkableMask = source.BaseWalkableMask,
                        BaseNeighborTraversalMask = source.BaseNeighborTraversalMask,
                        StaticCollisionVertices = source.StaticCollisionVertices,
                        StaticCollisionPathStarts = source.StaticCollisionPathStarts,
                        SourceCostField = source.SourceCostField,
                        SectorCostFields = null,
                        CellNavAnchors = source.CellNavAnchors,
                        CellNavAnchorsFixedXZ = source.CellNavAnchorsFixedXZ,
                        IslandCount = source.IslandCount,
                        MainIslandId = source.MainIslandId,
                        MainIslandSize = source.MainIslandSize,
                        SectorSizeInCells = source.SectorSizeInCells,
                        SectorCountX = source.SectorCountX,
                        SectorCountY = source.SectorCountY,
                        NextPortalId = source.NextPortalId
                    };
                    job.WorkingWorld.CopyAuthorityGridMetadataFrom(source);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.RentWalkableMask;
                    break;
                case RuntimeDirtyCloneShellStage.RentWalkableMask:
                    job.WorkingWorld.WalkableMask = RentBoolArray(source.Width * source.Height, clear: false);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.RentCostField;
                    break;
                case RuntimeDirtyCloneShellStage.RentCostField:
                    job.WorkingWorld.CostField = RentByteArray(source.Width * source.Height, clear: false);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.RentNeighborTraversalMask;
                    break;
                case RuntimeDirtyCloneShellStage.RentNeighborTraversalMask:
                    job.WorkingWorld.NeighborTraversalMask = RentByteArray(source.Width * source.Height, clear: false);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.RentIslandIds;
                    break;
                case RuntimeDirtyCloneShellStage.RentIslandIds:
                    job.WorkingWorld.IslandIds = RentIntArray(source.Width * source.Height, clear: false);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.CreateSectorSlots;
                    break;
                case RuntimeDirtyCloneShellStage.CreateSectorSlots:
                    job.WorkingWorld.Sectors = new SectorData[source.Sectors.Length];
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.ClonePortalArray;
                    break;
                case RuntimeDirtyCloneShellStage.ClonePortalArray:
                    job.WorkingWorld.Portals = source.Portals != null
                        ? (PortalData[])source.Portals.Clone()
                        : Array.Empty<PortalData>();
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.ClonePortalLookup;
                    break;
                case RuntimeDirtyCloneShellStage.ClonePortalLookup:
                    job.WorkingWorld.PortalsById = new Dictionary<int, PortalData>(source.PortalsById);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.ClonePortalSignatures;
                    break;
                case RuntimeDirtyCloneShellStage.ClonePortalSignatures:
                    foreach (KeyValuePair<PortalSignature, int> pair in source.PortalIdsBySignature)
                        job.WorkingWorld.PortalIdsBySignature.Add(pair.Key, pair.Value);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.CloneUsedPortalIds;
                    break;
                case RuntimeDirtyCloneShellStage.CloneUsedPortalIds:
                    foreach (int portalId in source.UsedPortalIds)
                        job.WorkingWorld.UsedPortalIds.Add(portalId);
                    job.CloneShellStage = RuntimeDirtyCloneShellStage.Complete;
                    break;
                case RuntimeDirtyCloneShellStage.Complete:
                    job.CloneCellCursor = 0;
                    job.CloneSectorCursor = 0;
                    job.CloneShellInitialized = true;
                    break;
                default:
                    throw new InvalidOperationException(
                        $"ProcessRuntimeDirtyClone failed: unknown clone shell stage {job.CloneShellStage}.");
            }

            if (!forceComplete)
            {
                ExhaustNavigationWorkBudget();
                return;
            }
        }

        NavigationWorld working = job.WorkingWorld;
        int cellCount = source.Width * source.Height;
        while (job.CloneCellCursor < cellCount)
        {
            int end = Mathf.Min(cellCount, job.CloneCellCursor + 4096);
            int copyCount = end - job.CloneCellCursor;
            Array.Copy(source.WalkableMask, job.CloneCellCursor, working.WalkableMask, job.CloneCellCursor, copyCount);
            Array.Copy(source.NeighborTraversalMask, job.CloneCellCursor, working.NeighborTraversalMask, job.CloneCellCursor, copyCount);
            if (source.CostField != null)
            {
                Array.Copy(source.CostField, job.CloneCellCursor, working.CostField, job.CloneCellCursor, copyCount);
            }
            else
            {
                for (int index = job.CloneCellCursor; index < end; index++)
                    working.CostField[index] = source.WalkableMask[index] ? (byte)1 : byte.MaxValue;
            }

            job.CloneCellCursor = end;
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        while (job.CloneSectorCursor < source.Sectors.Length)
        {
            int sectorIndex = job.CloneSectorCursor++;
            SectorData sourceSector = source.Sectors[sectorIndex];
            working.Sectors[sectorIndex] = CloneSectorData(sourceSector, job.DirtySectors, job.CostDirtySectors);
            if (source.CostField == null)
                CopyRuntimeDirtySectorCost(source, working, sourceSector);
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        ValidateRuntimeDirtyPortalCloneOwnership(job);
        job.SectorCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.ResetWalkable;
    }

    private static void ValidateRuntimeDirtyPortalCloneOwnership(RuntimeDirtyRebuildJob job)
    {
        if (job == null || job.TargetWorld == null || job.WorkingWorld == null)
            throw new InvalidOperationException("ValidateRuntimeDirtyPortalCloneOwnership failed: runtime-dirty world is missing.");
        if (job.DirtySectors == null || job.CostDirtySectors == null)
            throw new InvalidOperationException("ValidateRuntimeDirtyPortalCloneOwnership failed: dirty sector sets are missing.");
        if (job.TargetWorld.Sectors.Length != job.WorkingWorld.Sectors.Length)
            throw new InvalidOperationException("ValidateRuntimeDirtyPortalCloneOwnership failed: sector count mismatch.");

        for (int i = 0; i < job.TargetWorld.Sectors.Length; i++)
        {
            SectorData source = job.TargetWorld.Sectors[i];
            SectorData working = job.WorkingWorld.Sectors[i];
            bool mutable = job.CostDirtySectors.Contains(i);
            bool sharesPortalCollections = ReferenceEquals(source.PortalIds, working.PortalIds)
                                           && ReferenceEquals(source.PortalTransitions, working.PortalTransitions)
                                           && ReferenceEquals(source.IncomingPortalTransitionsByToPortalId, working.IncomingPortalTransitionsByToPortalId)
                                           && ReferenceEquals(source.OutgoingPortalTransitionsByFromPortalId, working.OutgoingPortalTransitionsByFromPortalId);
            if (mutable == sharesPortalCollections)
            {
                throw new InvalidOperationException(
                    $"ValidateRuntimeDirtyPortalCloneOwnership failed: sector {i} mutable={mutable}, sharesPortalCollections={sharesPortalCollections}.");
            }
        }

        foreach (PortalData portal in job.TargetWorld.PortalsById.Values)
        {
            if (!job.DirtySectors.Contains(portal.SectorAId) && !job.DirtySectors.Contains(portal.SectorBId))
                continue;
            if (!job.CostDirtySectors.Contains(portal.SectorAId) || !job.CostDirtySectors.Contains(portal.SectorBId))
            {
                throw new InvalidOperationException(
                    $"ValidateRuntimeDirtyPortalCloneOwnership failed: portal {portal.PortalId} touches dirty sectors outside mutable coverage. " +
                    $"sectorA={portal.SectorAId}, sectorB={portal.SectorBId}.");
            }
        }
    }

    private static void CopyRuntimeDirtySectorCost(NavigationWorld source, NavigationWorld working, SectorData sector)
    {
        if (sector == null)
            throw new InvalidOperationException("CopyRuntimeDirtySectorCost failed: sector is null.");

        byte[] chunk = source.SectorCostFields != null ? source.SectorCostFields[sector.SectorId] : null;
        if (chunk == null)
        {
            if (!sector.IsClearCostField)
                throw new InvalidOperationException($"CopyRuntimeDirtySectorCost failed: missing non-clear cost chunk sector={sector.SectorId}.");
            return;
        }
        if (chunk.Length != sector.Width * sector.Height)
            throw new InvalidOperationException($"CopyRuntimeDirtySectorCost failed: invalid cost chunk sector={sector.SectorId} length={chunk.Length}.");

        for (int localY = 0; localY < sector.Height; localY++)
        {
            int sourceOffset = localY * sector.Width;
            int targetOffset = (sector.StartY + localY) * working.Width + sector.StartX;
            Array.Copy(chunk, sourceOffset, working.CostField, targetOffset, sector.Width);
        }
    }

    private static void ProcessRuntimeDirtyResetWalkable(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        while (job.SectorCursor < job.DirtySectorIds.Count)
        {
            int sectorId = job.DirtySectorIds[job.SectorCursor++];
            ResetSectorWalkableFromBase(job.WorkingWorld, job.WorkingWorld.Sectors[sectorId]);
            job.WorkingWorld.Sectors[sectorId].DirtyVersion++;
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        job.SectorCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.ApplyObstacles;
    }

    private static void ProcessRuntimeDirtyObstacles(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        if (job.ApplyingCircleObstacles)
        {
            while (job.ObstacleCursor < job.CircleObstacles.Count)
            {
                CircleObstacle circle = job.CircleObstacles[job.ObstacleCursor++];
                BlockCellsByCircleInSectorsFixed(job.WorkingWorld, job.DirtySectors, circle.PositionFixed, circle.RadiusFixed);
                if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                    return;
            }

            job.ApplyingCircleObstacles = false;
            job.ObstacleCursor = 0;
        }

        while (job.ObstacleCursor < job.BoxObstacles.Count)
        {
            BoxObstacle box = job.BoxObstacles[job.ObstacleCursor++];
            BlockCellsByBoxInSectorsFixed(
                job.WorkingWorld,
                job.DirtySectors,
                box.CenterFixed,
                ResolveBoxObstacleNavigationHalfExtentsFixed(job.WorkingWorld, box));
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        job.ObstacleCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.NeighborMask;
    }

    private static void ProcessRuntimeDirtyNeighborMask(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        while (job.SectorCursor < job.DirtySectorIds.Count)
        {
            SectorData sector = job.WorkingWorld.Sectors[job.DirtySectorIds[job.SectorCursor++]];
            for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
            {
                for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
                    RebuildNeighborTraversalMaskCell(job.WorkingWorld, x, y);
            }

            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        job.SectorCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.SymmetrizeNeighborMask;
    }

    private static void ProcessRuntimeDirtyCostField(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        while (job.SectorCursor < job.CostDirtySectorIds.Count)
        {
            RebuildCostFieldForSector(job.WorkingWorld, job.CostDirtySectorIds[job.SectorCursor++], job.CostStamps);
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        job.SectorCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.IslandField;
    }

    private static void ProcessRuntimeDirtyIslandField(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (!job.IslandInitialized)
        {
            if (world.IslandIds == null || world.IslandIds.Length != world.Width * world.Height)
                world.IslandIds = RentIntArray(world.Width * world.Height, clear: false);

            Array.Clear(world.IslandIds, 0, world.IslandIds.Length);
            world.IslandCount = 0;
            world.MainIslandId = 0;
            world.MainIslandSize = 0;
            job.IslandOpenQueue = new Queue<int>(256);
            job.IslandScanIndex = 0;
            job.IslandCurrentId = 0;
            job.IslandCurrentSize = 0;
            job.IslandMainId = 0;
            job.IslandMainSize = 0;
            job.IslandBfsActive = false;
            job.IslandInitialized = true;
        }

        AdvanceIslandFieldBuild(
            world,
            job.IslandOpenQueue,
            ref job.IslandScanIndex,
            ref job.IslandCurrentId,
            ref job.IslandCurrentSize,
            ref job.IslandMainId,
            ref job.IslandMainSize,
            ref job.IslandBfsActive,
            deadlineTicks,
            forceComplete,
            out bool complete);
        if (!complete)
            return;

        job.SectorCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.SectorComponents;
    }

    private static void ProcessRuntimeDirtySectorComponents(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        HashSet<int> dirtySectors = job.DirtySectors;
        if (world == null)
            throw new InvalidOperationException("ProcessRuntimeDirtySectorComponents failed: world is null.");
        if (world.Sectors == null)
            throw new InvalidOperationException("ProcessRuntimeDirtySectorComponents failed: sectors are null.");
        if (dirtySectors == null)
            throw new InvalidOperationException("ProcessRuntimeDirtySectorComponents failed: dirty sectors are null.");

        while (job.SectorCursor < world.Sectors.Length)
        {
            SectorData sector = world.Sectors[job.SectorCursor++];
            RebuildSectorIslandMetadata(world, sector);
            if (dirtySectors.Contains(sector.SectorId))
                RebuildSectorLocalComponents(world, sector);
            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return;
        }

        LogIslandFieldDiagnostics(world, "runtime-dirty");
        job.SectorCursor = 0;
        job.Stage = RuntimeDirtyRebuildStage.PortalGraph;
    }

    private static void RebuildAllSectorLocalComponents(NavigationWorld world)
    {
        if (world == null)
            throw new InvalidOperationException("RebuildAllSectorLocalComponents failed: world is null.");
        if (world.Sectors == null)
            throw new InvalidOperationException("RebuildAllSectorLocalComponents failed: sectors are null.");

        for (int i = 0; i < world.Sectors.Length; i++)
        {
            RebuildSectorIslandMetadata(world, world.Sectors[i]);
            RebuildSectorLocalComponents(world, world.Sectors[i]);
        }
    }

    private static void RebuildSectorIslandMetadata(NavigationWorld world, SectorData sector)
    {
        if (world == null)
            throw new InvalidOperationException("RebuildSectorIslandMetadata failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("RebuildSectorIslandMetadata failed: sector is null.");
        if (world.IslandIds == null || world.IslandIds.Length != world.Width * world.Height)
            throw new InvalidOperationException("RebuildSectorIslandMetadata failed: island field is missing or invalid.");

        int uniformIslandId = 0;
        bool mixed = false;
        for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
        {
            int rowStart = y * world.Width;
            for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
            {
                int index = rowStart + x;
                if (!world.WalkableMask[index])
                    continue;

                int islandId = world.IslandIds[index];
                if (islandId <= 0)
                    throw new InvalidOperationException($"RebuildSectorIslandMetadata failed: walkable cell ({x},{y}) has invalid island {islandId}.");

                if (uniformIslandId == 0)
                {
                    uniformIslandId = islandId;
                    continue;
                }

                if (uniformIslandId == islandId)
                    continue;

                mixed = true;
                break;
            }

            if (mixed)
                break;
        }

        sector.UniformIslandId = mixed ? -1 : uniformIslandId;
    }

    private static void RebuildSectorLocalComponents(NavigationWorld world, SectorData sector)
    {
        if (sector == null)
            throw new InvalidOperationException("RebuildSectorLocalComponents failed: sector is null.");

        int cellCount = sector.Width * sector.Height;
        if (sector.LocalComponentIds == null || sector.LocalComponentIds.Length != cellCount)
            sector.LocalComponentIds = new int[cellCount];
        else
            Array.Clear(sector.LocalComponentIds, 0, sector.LocalComponentIds.Length);

        int componentId = 0;
        Queue<int> open = new Queue<int>(Mathf.Min(256, Mathf.Max(1, cellCount)));
        for (int localIndex = 0; localIndex < cellCount; localIndex++)
        {
            if (sector.LocalComponentIds[localIndex] != 0)
                continue;

            int worldX = sector.StartX + localIndex % sector.Width;
            int worldY = sector.StartY + localIndex / sector.Width;
            if (!world.IsWalkable(worldX, worldY))
                continue;

            componentId++;
            sector.LocalComponentIds[localIndex] = componentId;
            open.Enqueue(localIndex);
            while (open.Count > 0)
            {
                int currentLocal = open.Dequeue();
                int currentX = sector.StartX + currentLocal % sector.Width;
                int currentY = sector.StartY + currentLocal / sector.Width;
                byte traversalMask = world.NeighborTraversalMask[world.GetIndex(currentX, currentY)];
                for (int i = 0; i < NeighborOffsetX.Length; i++)
                {
                    if ((traversalMask & (1 << i)) == 0)
                        continue;

                    int nextX = currentX + NeighborOffsetX[i];
                    int nextY = currentY + NeighborOffsetY[i];
                    if (!IsInsideSector(sector, nextX, nextY) || !world.IsWalkable(nextX, nextY))
                        continue;

                    int nextLocal = GetSectorLocalIndex(sector, nextX, nextY);
                    if (sector.LocalComponentIds[nextLocal] != 0)
                        continue;

                    sector.LocalComponentIds[nextLocal] = componentId;
                    open.Enqueue(nextLocal);
                }
            }
        }

        sector.LocalComponentCount = componentId;
    }

    private static void AdvanceIslandFieldBuild(
        NavigationWorld world,
        Queue<int> openQueue,
        ref int scanIndex,
        ref int currentId,
        ref int currentSize,
        ref int mainId,
        ref int mainSize,
        ref bool bfsActive,
        long deadlineTicks,
        bool forceComplete,
        out bool complete)
    {
        if (world == null)
            throw new InvalidOperationException("AdvanceIslandFieldBuild failed: world is null.");
        if (openQueue == null)
            throw new InvalidOperationException("AdvanceIslandFieldBuild failed: open queue is null.");

        complete = false;
        while (true)
        {
            if (bfsActive)
            {
                int budgetWork = 0;
                while (openQueue.Count > 0)
                {
                    int currentIndex = openQueue.Dequeue();
                    currentSize++;
                    int currentX = currentIndex % world.Width;
                    int currentY = currentIndex / world.Width;
                    byte traversalMask = world.NeighborTraversalMask[currentIndex];
                    for (int i = 0; i < NeighborOffsetX.Length; i++)
                    {
                        if ((traversalMask & (1 << i)) == 0)
                            continue;

                        int nextX = currentX + NeighborOffsetX[i];
                        int nextY = currentY + NeighborOffsetY[i];
                        if (!world.IsWalkable(nextX, nextY))
                            continue;

                        int nextIndex = world.GetIndex(nextX, nextY);
                        if (world.IslandIds[nextIndex] != 0)
                            continue;

                        world.IslandIds[nextIndex] = currentId;
                        openQueue.Enqueue(nextIndex);
                    }

                    if (!forceComplete && IsBudgetExpired(deadlineTicks, ++budgetWork))
                        return;
                }

                if (currentSize > mainSize)
                {
                    mainId = currentId;
                    mainSize = currentSize;
                }

                bfsActive = false;
                currentSize = 0;
            }

            while (scanIndex < world.Width * world.Height)
            {
                int index = scanIndex++;
                if (!world.WalkableMask[index] || world.IslandIds[index] != 0)
                    continue;

                currentId++;
                world.IslandIds[index] = currentId;
                openQueue.Enqueue(index);
                bfsActive = true;
                break;
            }

            if (bfsActive)
            {
                if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                    return;

                continue;
            }

            world.IslandCount = currentId;
            world.MainIslandId = mainId;
            world.MainIslandSize = mainSize;
            complete = true;
            return;
        }
    }

    private static bool ProcessRuntimeDirtyPortalGraph(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        if (!job.PortalInitialized)
        {
            job.PendingPortalAccessEntries ??= new List<PendingSectorPortalAccess>();
            job.PendingPortalAccessEntries.Clear();
            job.PortalTransitionDirtySectors = new HashSet<int>(job.DirtySectors);
            foreach (int sectorId in job.CostDirtySectors)
                job.PortalTransitionDirtySectors.Add(sectorId);

            job.PortalRebuiltPortals = new List<PortalData>(32);
            job.PortalProcessedBoundaries = new HashSet<long>();
            job.PortalStage = RuntimeDirtyPortalStage.RemoveOldPortals;
            job.PortalSectorCursor = 0;
            job.PortalAddCursor = 0;
            job.PortalTransitionCursor = 0;
            job.PortalTransitionFromCursor = 0;
            job.PortalInitialized = true;
        }

        while (job.PortalStage != RuntimeDirtyPortalStage.Complete)
        {
            switch (job.PortalStage)
            {
                case RuntimeDirtyPortalStage.RemoveOldPortals:
                    long removeStartTicks = Stopwatch.GetTimestamp();
                    RemovePortalsTouchingSectors(world, job.DirtySectors, job.PortalTransitionDirtySectors);
                    job.PortalGraphBoundaryTicks += Stopwatch.GetTimestamp() - removeStartTicks;
                    job.PortalStage = RuntimeDirtyPortalStage.RebuildBoundaries;
                    break;
                case RuntimeDirtyPortalStage.RebuildBoundaries:
                    while (job.PortalSectorCursor < job.DirtySectorIds.Count)
                    {
                        int sectorId = job.DirtySectorIds[job.PortalSectorCursor++];
                        long boundaryStartTicks = Stopwatch.GetTimestamp();
                        RebuildPortalBoundariesForSector(
                            world,
                            sectorId,
                            job.DirtySectors,
                            job.PortalProcessedBoundaries,
                            job.PortalRebuiltPortals);
                        job.PortalGraphBoundaryTicks += Stopwatch.GetTimestamp() - boundaryStartTicks;

                        if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                            return false;
                    }

                    job.PortalStage = RuntimeDirtyPortalStage.AddRebuiltPortals;
                    break;
                case RuntimeDirtyPortalStage.AddRebuiltPortals:
                    while (job.PortalAddCursor < job.PortalRebuiltPortals.Count)
                    {
                        long addStartTicks = Stopwatch.GetTimestamp();
                        PortalData portal = job.PortalRebuiltPortals[job.PortalAddCursor++];
                        if (world.PortalsById.ContainsKey(portal.PortalId))
                            throw new InvalidOperationException($"ProcessRuntimeDirtyPortalGraph failed: duplicate portal id {portal.PortalId}.");

                        world.PortalsById.Add(portal.PortalId, portal);
                        world.Sectors[portal.SectorAId].PortalIds.Add(portal.PortalId);
                        world.Sectors[portal.SectorBId].PortalIds.Add(portal.PortalId);
                        job.PortalTransitionDirtySectors.Add(portal.SectorAId);
                        job.PortalTransitionDirtySectors.Add(portal.SectorBId);
                        job.PortalGraphAddTicks += Stopwatch.GetTimestamp() - addStartTicks;

                        if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                            return false;
                    }

                    world.Portals = BuildPortalArray(world);
                    job.PortalTransitionSectorIds = CreateSortedSectorIdSnapshot(
                        job.PortalTransitionDirtySectors,
                        "portal transition dirty sectors");
                    job.PortalTransitionCursor = 0;
                    job.PortalTransitionFromCursor = 0;
                    job.PortalStage = RuntimeDirtyPortalStage.RebuildTransitions;
                    break;
                case RuntimeDirtyPortalStage.RebuildTransitions:
                    if (!ProcessRuntimeDirtyPortalTransitions(job, deadlineTicks, forceComplete))
                        return false;
                    break;
                default:
                    throw new InvalidOperationException($"ProcessRuntimeDirtyPortalGraph failed: unknown portal stage {job.PortalStage}.");
            }

            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return false;
        }

        LogRuntimeDirtyPortalGraphTiming(job);
        job.Stage = RuntimeDirtyRebuildStage.PrepareCommit;
        return true;
    }

    private static bool ProcessRuntimeDirtyPortalTransitions(RuntimeDirtyRebuildJob job, long deadlineTicks, bool forceComplete)
    {
        NavigationWorld world = job.WorkingWorld;
        int processedSourceCount = 0;
        while (job.PortalTransitionCursor < job.PortalTransitionSectorIds.Count)
        {
            int sectorId = job.PortalTransitionSectorIds[job.PortalTransitionCursor];
            if (sectorId < 0 || sectorId >= world.Sectors.Length)
            {
                job.PortalTransitionCursor++;
                job.PortalTransitionFromCursor = 0;
                continue;
            }

            SectorData sector = world.Sectors[sectorId];
            if (job.PortalTransitionFromCursor == 0)
                sector.PortalTransitions.Clear();

            if (sector.PortalIds.Count == 0)
            {
                RebuildIncomingPortalTransitionIndex(sector);
                job.PortalTransitionCursor++;
                job.PortalTransitionFromCursor = 0;
                continue;
            }

            while (job.PortalTransitionFromCursor < sector.PortalIds.Count)
            {
                int fromPortalId = sector.PortalIds[job.PortalTransitionFromCursor];
                bool analytic = CanUseAnalyticPortalAccess(
                    world,
                    sector,
                    fromPortalId,
                    out AnalyticPortalAccessDiagnostics analyticDiagnostics);
                job.PortalGraphAnalyticCheckCount++;
                if (analyticDiagnostics.IsClearSector)
                    job.PortalGraphAnalyticClearSectorCount++;
                if (analyticDiagnostics.RejectReason == AnalyticPortalAccessRejectReason.MultipleLocalComponents)
                    job.PortalGraphAnalyticMultiComponentRejectCount++;
                else if (analyticDiagnostics.RejectReason == AnalyticPortalAccessRejectReason.NonClearSector)
                    job.PortalGraphAnalyticNonClearRejectCount++;

                PendingSectorPortalAccess pending = analytic
                    ? AddPendingAnalyticSectorPortalAccess(job.PendingPortalAccessEntries, sector, fromPortalId)
                    : AddPendingPrebuiltDeterministicSectorPortalAccess(
                        world,
                        job.PendingPortalAccessEntries,
                        sector,
                        fromPortalId);

                AddDeterministicPortalTransitionTopology(world, sector, fromPortalId);
                ApplyPendingPortalTransitionCosts(world, sector, pending);
                job.PortalGraphAccessCount++;
                job.PortalGraphTransitionCostChecks++;
                if (analytic)
                    job.PortalGraphAnalyticAccessCount++;

                job.PortalTransitionFromCursor++;
                processedSourceCount++;
                if (!forceComplete
                    && (IsBudgetExpired(deadlineTicks, job.PortalTransitionFromCursor)
                        || processedSourceCount >= RuntimeDirtyPortalTransitionSourceQuota))
                {
                    return false;
                }
            }

            RebuildIncomingPortalTransitionIndex(sector);
            job.PortalTransitionCursor++;
            job.PortalTransitionFromCursor = 0;
        }

        job.PortalStage = RuntimeDirtyPortalStage.Complete;
        return true;
    }

    private static void PrepareRuntimeDirtyCommit(RuntimeDirtyRebuildJob job)
    {
        if (job == null)
            throw new InvalidOperationException("PrepareRuntimeDirtyCommit failed: job is null.");
        if (job.WorkingWorld == null)
            throw new InvalidOperationException("PrepareRuntimeDirtyCommit failed: working world is null.");
        if (job.WorldHashBuildJob != null)
            throw new InvalidOperationException("PrepareRuntimeDirtyCommit failed: world hash job already exists.");

        ValidatePendingSectorPortalAccessCoverage(job.WorkingWorld, job.PendingPortalAccessEntries, "runtime-dirty-prepare");
        FinalizeWorldCostStorage(job.WorkingWorld);
        job.WorldHashBuildJob = CreateNavigationWorldHashBuildJob(job.WorkingWorld);
    }

    private static bool CanUseAnalyticPortalAccess(NavigationWorld world, SectorData sector, int portalId)
    {
        return CanUseAnalyticPortalAccess(world, sector, portalId, out _);
    }

    private static bool CanUseAnalyticPortalAccess(NavigationWorld world, SectorData sector, int portalId, out AnalyticPortalAccessDiagnostics diagnostics)
    {
        if (world == null)
            throw new InvalidOperationException("CanUseAnalyticPortalAccess failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("CanUseAnalyticPortalAccess failed: sector is null.");

        diagnostics = default;
        if (sector.LocalComponentCount > 1)
        {
            diagnostics.RejectReason = AnalyticPortalAccessRejectReason.MultipleLocalComponents;
            return false;
        }

        if (sector.IsClearFlowTile)
        {
            diagnostics.IsClearSector = true;
            return true;
        }

        diagnostics.RejectReason = AnalyticPortalAccessRejectReason.NonClearSector;
        return false;
    }

    private static void CommitRuntimeDirtyJob(WorldRuntimeState state, RuntimeDirtyRebuildJob job)
    {
        long stepStartTicks = Stopwatch.GetTimestamp();
        NavigationWorld target = job.TargetWorld;
        NavigationWorld working = job.WorkingWorld;
        if (state.World != target)
            throw new InvalidOperationException("CommitRuntimeDirtyJob failed: target world changed while job was pending.");
        if (!working.HasDeterministicContentHash || job.WorldHashBuildJob == null || !job.WorldHashBuildJob.Complete)
            throw new InvalidOperationException("CommitRuntimeDirtyJob failed: working world hash is incomplete.");

        bool[] oldWalkableMask = target.WalkableMask;
        byte[] oldNeighborTraversalMask = target.NeighborTraversalMask;
        int[] oldIslandIds = target.IslandIds;
        List<SectorPortalAccessKey> oldPortalAccessKeys = CreatePortalAccessInvalidationKeys(
            target,
            job.PortalTransitionSectorIds);

        target.WalkableMask = working.WalkableMask;
        target.CostField = working.CostField;
        target.SectorCostFields = working.SectorCostFields;
        target.NeighborTraversalMask = working.NeighborTraversalMask;
        target.IslandIds = working.IslandIds;
        target.IslandCount = working.IslandCount;
        target.MainIslandId = working.MainIslandId;
        target.MainIslandSize = working.MainIslandSize;
        target.Sectors = working.Sectors;
        target.Portals = working.Portals;
        target.PortalsById = working.PortalsById;
        target.NextPortalId = working.NextPortalId;
        target.DeterministicContentHash = working.DeterministicContentHash;
        target.HasDeterministicContentHash = true;
        target.PortalIdsBySignature = working.PortalIdsBySignature;
        target.UsedPortalIds = working.UsedPortalIds;

        ReturnWorldArrayIfOwned(oldWalkableMask, target.BaseWalkableMask, target.WalkableMask);
        ReturnWorldArrayIfOwned(oldNeighborTraversalMask, target.BaseNeighborTraversalMask, target.NeighborTraversalMask);
        ReturnWorldArrayIfOwned(oldIslandIds, null, target.IslandIds);
        job.CommitSwapTicks = Stopwatch.GetTimestamp() - stepStartTicks;

        stepStartTicks = Stopwatch.GetTimestamp();
        InvalidateCachesForDirtySectors(target, job.CostDirtySectors, oldPortalAccessKeys);
        job.CommitCacheInvalidationTicks = Stopwatch.GetTimestamp() - stepStartTicks;

        stepStartTicks = Stopwatch.GetTimestamp();
        CommitPendingSectorPortalAccessEntries(
            target,
            job.PendingPortalAccessEntries,
            entriesAreFinalized: true);
        job.CommitPortalAccessTicks = Stopwatch.GetTimestamp() - stepStartTicks;

        stepStartTicks = Stopwatch.GetTimestamp();
        DeterministicWorldHashRefreshCount++;
        RefreshCommittedWorldSetHash();
        job.CommitWorldHashTicks = Stopwatch.GetTimestamp() - stepStartTicks;

        stepStartTicks = Stopwatch.GetTimestamp();
        MovingTargetAnchors.Clear();
        CombatTargetSlotCache.Clear();
        ClearFixedPortalOwnersForWorld(target.Version);
        foreach (KeyValuePair<int, AgentRuntimeData> pair in Agents)
        {
            if (PathTouchesAnySector(pair.Value.NavState.PathHandle, job.CostDirtySectors)
                || PathReferencesMissingPortal(target, pair.Value.NavState.PathHandle))
            {
                pair.Value.NavState.PathHandle = null;
            }

            ClearStableGoal(pair.Value);
        }

        _world = target;
        _navigationTopologyVersion++;
        s_NavigationDistancePrewarmCompleted = false;
        job.CommitAgentInvalidationTicks = Stopwatch.GetTimestamp() - stepStartTicks;
        LogNoStacktrace(
            $"[FlowRuntimeDirtyCommit] worldVersion={target.Version} dirtySectors={job.DirtySectors.Count} costSectors={job.CostDirtySectors.Count} " +
            $"reason={job.Reason}");
    }

    private static NavigationWorld CloneNavigationWorldForRuntimeDirty(NavigationWorld source, HashSet<int> dirtySectors)
    {
        if (source == null)
            throw new InvalidOperationException("CloneNavigationWorldForRuntimeDirty failed: source is null.");
        if (dirtySectors == null)
            throw new InvalidOperationException("CloneNavigationWorldForRuntimeDirty failed: dirty sectors are null.");

        NavigationWorld clone = new NavigationWorld
        {
            Version = source.Version,
            AgentTypeId = source.AgentTypeId,
            Width = source.Width,
            Height = source.Height,
            CellSize = source.CellSize,
            EncodedCenterClearance = source.EncodedCenterClearance,
            Origin = source.Origin,
            BaseWalkableMask = source.BaseWalkableMask,
            BaseNeighborTraversalMask = source.BaseNeighborTraversalMask,
            StaticCollisionVertices = source.StaticCollisionVertices,
            StaticCollisionPathStarts = source.StaticCollisionPathStarts,
            SourceCostField = source.SourceCostField,
            WalkableMask = RentCopiedBoolArray(source.WalkableMask),
            CostField = MaterializeMutableCostField(source),
            SectorCostFields = null,
            CellNavAnchors = source.CellNavAnchors,
            CellNavAnchorsFixedXZ = source.CellNavAnchorsFixedXZ,
            NeighborTraversalMask = RentCopiedByteArray(source.NeighborTraversalMask),
            IslandIds = RentIntArray(source.Width * source.Height, clear: false),
            IslandCount = source.IslandCount,
            MainIslandId = source.MainIslandId,
            MainIslandSize = source.MainIslandSize,
            SectorSizeInCells = source.SectorSizeInCells,
            SectorCountX = source.SectorCountX,
            SectorCountY = source.SectorCountY,
            Sectors = CloneSectors(source.Sectors, dirtySectors),
            Portals = (PortalData[])source.Portals.Clone(),
            PortalsById = new Dictionary<int, PortalData>(source.PortalsById),
            NextPortalId = source.NextPortalId
        };
        clone.CopyAuthorityGridMetadataFrom(source);

        foreach (KeyValuePair<PortalSignature, int> pair in source.PortalIdsBySignature)
            clone.PortalIdsBySignature.Add(pair.Key, pair.Value);
        foreach (int portalId in source.UsedPortalIds)
            clone.UsedPortalIds.Add(portalId);

        return clone;
    }

    private static SectorData[] CloneSectors(SectorData[] source)
    {
        return CloneSectors(source, null);
    }

    private static SectorData[] CloneSectors(SectorData[] source, HashSet<int> dirtySectors)
    {
        if (source == null)
            throw new InvalidOperationException("CloneSectors failed: source is null.");

        SectorData[] clone = new SectorData[source.Length];
        for (int i = 0; i < source.Length; i++)
            clone[i] = CloneSectorData(source[i], dirtySectors);

        return clone;
    }

    private static SectorData CloneSectorData(
        SectorData sector,
        HashSet<int> dirtySectors,
        HashSet<int> portalMutableSectors = null)
    {
        if (sector == null)
            throw new InvalidOperationException("CloneSectorData failed: sector is null.");

        bool sharePortalCollections = portalMutableSectors != null
                                      && !portalMutableSectors.Contains(sector.SectorId);
        SectorData copy = sharePortalCollections ? new SectorData(sector) : new SectorData();
        copy.SectorId = sector.SectorId;
        copy.StartX = sector.StartX;
        copy.StartY = sector.StartY;
        copy.Width = sector.Width;
        copy.Height = sector.Height;
        copy.Center = sector.Center;
        copy.DirtyVersion = sector.DirtyVersion;
        copy.IsClearCostField = sector.IsClearCostField;
        copy.IsClearFlowTile = sector.IsClearFlowTile;
        copy.UniformIslandId = sector.UniformIslandId;
        copy.LocalComponentIds = dirtySectors == null || dirtySectors.Contains(sector.SectorId) || sector.LocalComponentIds == null
            ? new int[sector.Width * sector.Height]
            : sector.LocalComponentIds;
        copy.LocalComponentCount = sector.LocalComponentCount;
        if (!sharePortalCollections)
        {
            copy.PortalIds.AddRange(sector.PortalIds);
            copy.PortalTransitions.AddRange(sector.PortalTransitions);
            RebuildIncomingPortalTransitionIndex(copy);
        }
        return copy;
    }

    private static void ResetSectorWalkableFromBase(NavigationWorld world, SectorData sector)
    {
        for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
        {
            int rowStart = y * world.Width;
            for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
            {
                int index = rowStart + x;
                world.WalkableMask[index] = world.BaseWalkableMask[index];
            }
        }
    }

    private static void BlockCellsByCircleInSectorsFixed(
        NavigationWorld world,
        HashSet<int> sectorIds,
        FixVector2 center,
        Fix64 radius)
    {
        if (world == null)
            throw new InvalidOperationException("BlockCellsByCircleInSectorsFixed failed: world is null.");
        if (sectorIds == null)
            throw new ArgumentNullException(nameof(sectorIds));

        int rawMinX = NavigationGridFixedMath.WorldToGridCell(center.x - radius, world.OriginXGridRaw, world.CellSizeGridRaw);
        int rawMaxX = NavigationGridFixedMath.WorldToGridCell(center.x + radius, world.OriginXGridRaw, world.CellSizeGridRaw);
        int rawMinY = NavigationGridFixedMath.WorldToGridCell(center.y - radius, world.OriginZGridRaw, world.CellSizeGridRaw);
        int rawMaxY = NavigationGridFixedMath.WorldToGridCell(center.y + radius, world.OriginZGridRaw, world.CellSizeGridRaw);
        Fix64 cellSize = world.CellSizeFixed;
        Fix64 blockRadius = radius + cellSize * Fix64.FromRaw(1844);
        Fix64 blockRadiusSquared = blockRadius * blockRadius;

        foreach (int sectorId in sectorIds)
        {
            SectorData sector = world.Sectors[sectorId];
            int minX = Mathf.Max(rawMinX, sector.StartX);
            int maxX = Mathf.Min(rawMaxX, sector.StartX + sector.Width - 1);
            int minY = Mathf.Max(rawMinY, sector.StartY);
            int maxY = Mathf.Min(rawMaxY, sector.StartY + sector.Height - 1);
            if (minX > maxX || minY > maxY)
                continue;

            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    FixVector2 cellCenter = world.GridToWorldGeometricCenterFixed(x, y);
                    if (FixVector2.SqrMagnitude(cellCenter - center) <= blockRadiusSquared)
                        world.WalkableMask[x + y * world.Width] = false;
                }
            }
        }
    }

    private static void BlockCellsByBoxInSectorsFixed(
        NavigationWorld world,
        HashSet<int> sectorIds,
        FixVector2 center,
        FixVector2 halfExtents)
    {
        if (world == null)
            throw new InvalidOperationException("BlockCellsByBoxInSectorsFixed failed: world is null.");
        if (sectorIds == null)
            throw new ArgumentNullException(nameof(sectorIds));

        int rawMinX = NavigationGridFixedMath.WorldToGridCell(center.x - halfExtents.x, world.OriginXGridRaw, world.CellSizeGridRaw);
        int rawMaxX = NavigationGridFixedMath.WorldToGridCell(center.x + halfExtents.x, world.OriginXGridRaw, world.CellSizeGridRaw);
        int rawMinY = NavigationGridFixedMath.WorldToGridCell(center.y - halfExtents.y, world.OriginZGridRaw, world.CellSizeGridRaw);
        int rawMaxY = NavigationGridFixedMath.WorldToGridCell(center.y + halfExtents.y, world.OriginZGridRaw, world.CellSizeGridRaw);
        foreach (int sectorId in sectorIds)
        {
            SectorData sector = world.Sectors[sectorId];
            int minX = Mathf.Max(rawMinX, sector.StartX);
            int maxX = Mathf.Min(rawMaxX, sector.StartX + sector.Width - 1);
            int minY = Mathf.Max(rawMinY, sector.StartY);
            int maxY = Mathf.Min(rawMaxY, sector.StartY + sector.Height - 1);
            if (minX > maxX || minY > maxY)
                continue;

            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    FixVector2 cellCenter = world.GridToWorldGeometricCenterFixed(x, y);
                    FixVector2 delta = cellCenter - center;
                    if (Fix64.Abs(delta.x) <= halfExtents.x && Fix64.Abs(delta.y) <= halfExtents.y)
                        world.WalkableMask[x + y * world.Width] = false;
                }
            }
        }
    }

    private static void RebuildNeighborTraversalMaskForSectors(NavigationWorld world, HashSet<int> sectorIds)
    {
        if (world == null)
            throw new InvalidOperationException("RebuildNeighborTraversalMaskForSectors failed: world is null.");

        foreach (int sectorId in sectorIds)
        {
            SectorData sector = world.Sectors[sectorId];
            for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
            {
                for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
                    RebuildNeighborTraversalMaskCell(world, x, y);
            }
        }
    }

    private static void RebuildNeighborTraversalMaskCell(NavigationWorld world, int x, int y)
    {
        if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
            return;

        int fromIndex = world.GetIndex(x, y);
        if (!world.IsWalkable(x, y))
        {
            world.NeighborTraversalMask[fromIndex] = 0;
            return;
        }

        byte mask = 0;
        byte baseMask = world.BaseNeighborTraversalMask != null && world.BaseNeighborTraversalMask.Length == world.Width * world.Height
            ? world.BaseNeighborTraversalMask[fromIndex]
            : byte.MaxValue;
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int toX = x + NeighborOffsetX[i];
            int toY = y + NeighborOffsetY[i];
            if ((baseMask & (1 << i)) == 0)
                continue;
            if (!world.IsWalkable(toX, toY))
                continue;

            mask |= (byte)(1 << i);
        }

        world.NeighborTraversalMask[fromIndex] = mask;
    }

    private static void SymmetrizeNeighborTraversalMaskForSectors(NavigationWorld world, HashSet<int> sectorIds)
    {
        if (world == null)
            throw new InvalidOperationException("SymmetrizeNeighborTraversalMaskForSectors failed: world is null.");
        if (sectorIds == null || sectorIds.Count == 0)
            return;
        if (world.NeighborTraversalMask == null || world.NeighborTraversalMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("SymmetrizeNeighborTraversalMaskForSectors failed: neighbor traversal mask is invalid.");

        ResolveSectorBounds(world, sectorIds, out int startX, out int startY, out int endX, out int endY);
        startX = Mathf.Max(0, startX - 1);
        startY = Mathf.Max(0, startY - 1);
        endX = Mathf.Min(world.Width - 1, endX + 1);
        endY = Mathf.Min(world.Height - 1, endY + 1);

        for (int y = startY; y <= endY; y++)
        {
            for (int x = startX; x <= endX; x++)
                SymmetrizeNeighborTraversalMaskCell(world, x, y, "SymmetrizeNeighborTraversalMaskForSectors");
        }
    }

    private static void SymmetrizeNeighborTraversalMaskCell(NavigationWorld world, int x, int y, string caller)
    {
        int fromIndex = world.GetIndex(x, y);
        if (!world.IsWalkable(x, y))
        {
            world.NeighborTraversalMask[fromIndex] = 0;
            return;
        }

        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int toX = x + NeighborOffsetX[i];
            int toY = y + NeighborOffsetY[i];
            if (!world.IsWalkable(toX, toY))
            {
                world.NeighborTraversalMask[fromIndex] &= (byte)~(1 << i);
                continue;
            }

            int oppositeIndex = ResolveNeighborOffsetIndex(-NeighborOffsetX[i], -NeighborOffsetY[i]);
            if (oppositeIndex < 0)
                throw new InvalidOperationException($"{caller} failed: missing opposite offset for {NeighborOffsetX[i]},{NeighborOffsetY[i]}.");

            int toIndex = world.GetIndex(toX, toY);
            bool forward = (world.NeighborTraversalMask[fromIndex] & (1 << i)) != 0;
            bool backward = (world.NeighborTraversalMask[toIndex] & (1 << oppositeIndex)) != 0;
            if (!forward && !backward)
                continue;

            world.NeighborTraversalMask[fromIndex] |= (byte)(1 << i);
            world.NeighborTraversalMask[toIndex] |= (byte)(1 << oppositeIndex);
        }
    }

    private static int PruneIsolatedWalkableCells(NavigationWorld world, string reason)
    {
        if (world == null)
            throw new InvalidOperationException("PruneIsolatedWalkableCells failed: world is null.");
        if (world.WalkableMask == null || world.WalkableMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("PruneIsolatedWalkableCells failed: walkable mask is invalid.");
        if (world.NeighborTraversalMask == null || world.NeighborTraversalMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("PruneIsolatedWalkableCells failed: neighbor traversal mask is invalid.");

        int pruned = 0;
        for (int i = 0; i < world.WalkableMask.Length; i++)
        {
            if (!world.WalkableMask[i] || world.NeighborTraversalMask[i] != 0)
                continue;

            world.WalkableMask[i] = false;
            pruned++;
        }

        LogIsolatedWalkablePrune(world, reason, pruned);
        return pruned;
    }

    private static int PruneIsolatedWalkableCellsForSectors(NavigationWorld world, HashSet<int> sectorIds, string reason)
    {
        if (world == null)
            throw new InvalidOperationException("PruneIsolatedWalkableCellsForSectors failed: world is null.");
        if (world.WalkableMask == null || world.WalkableMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("PruneIsolatedWalkableCellsForSectors failed: walkable mask is invalid.");
        if (world.NeighborTraversalMask == null || world.NeighborTraversalMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("PruneIsolatedWalkableCellsForSectors failed: neighbor traversal mask is invalid.");
        if (sectorIds == null || sectorIds.Count == 0)
            return 0;

        ResolveSectorBounds(world, sectorIds, out int startX, out int startY, out int endX, out int endY);
        startX = Mathf.Max(0, startX - 1);
        startY = Mathf.Max(0, startY - 1);
        endX = Mathf.Min(world.Width - 1, endX + 1);
        endY = Mathf.Min(world.Height - 1, endY + 1);

        int pruned = 0;
        for (int y = startY; y <= endY; y++)
        {
            for (int x = startX; x <= endX; x++)
            {
                int index = world.GetIndex(x, y);
                if (!world.WalkableMask[index] || world.NeighborTraversalMask[index] != 0)
                    continue;

                world.WalkableMask[index] = false;
                pruned++;
            }
        }

        LogIsolatedWalkablePrune(world, reason, pruned);
        return pruned;
    }

    private static void LogIsolatedWalkablePrune(NavigationWorld world, string reason, int pruned)
    {
        if (pruned <= 0)
            return;

        LogNoStacktrace(
            $"[FlowIsolatedWalkablePrune] reason={reason} pruned={pruned} " +
            $"worldVersion={world.Version} size={world.Width}x{world.Height} agentType={world.AgentTypeId}");
    }

    private static List<SectorPortalAccessKey> CreatePortalAccessInvalidationKeys(
        NavigationWorld world,
        IReadOnlyList<int> sectorIds)
    {
        if (world?.Sectors == null)
            throw new InvalidOperationException("CreatePortalAccessInvalidationKeys failed: world is unavailable.");
        if (sectorIds == null)
            throw new InvalidOperationException("CreatePortalAccessInvalidationKeys failed: sector ids are null.");

        var result = new List<SectorPortalAccessKey>();
        int previousSectorId = -1;
        for (int i = 0; i < sectorIds.Count; i++)
        {
            int sectorId = sectorIds[i];
            if (sectorId <= previousSectorId || sectorId < 0 || sectorId >= world.Sectors.Length)
            {
                throw new InvalidOperationException(
                    $"CreatePortalAccessInvalidationKeys failed: sector ids must be sorted, unique and in range previous={previousSectorId} current={sectorId}.");
            }
            previousSectorId = sectorId;

            SectorData sector = world.Sectors[sectorId]
                                ?? throw new InvalidOperationException(
                                    $"CreatePortalAccessInvalidationKeys failed: sector is null id={sectorId}.");
            for (int portalIndex = 0; portalIndex < sector.PortalIds.Count; portalIndex++)
            {
                int portalId = sector.PortalIds[portalIndex];
                var key = new SectorPortalAccessKey(world.Version, sectorId, portalId, sector.DirtyVersion);
                if (!SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry entry)
                    || !IsValidSectorPortalAccessEntry(entry))
                {
                    throw new InvalidOperationException(
                        $"CreatePortalAccessInvalidationKeys failed: committed portal access is missing sector={sectorId} portal={portalId} dirty={sector.DirtyVersion}.");
                }
                result.Add(key);
            }
        }

        return result;
    }

    private static void InvalidateCachesForDirtySectors(
        NavigationWorld world,
        HashSet<int> dirtySectors,
        IReadOnlyList<SectorPortalAccessKey> portalAccessKeysToRemove)
    {
        if (world == null)
            throw new InvalidOperationException("InvalidateCachesForDirtySectors failed: world is null.");
        if (dirtySectors == null || dirtySectors.Count == 0)
            return;
        if (portalAccessKeysToRemove == null)
            throw new InvalidOperationException("InvalidateCachesForDirtySectors failed: portal access keys are null.");

        List<FlowTileCacheKey> tileKeysToRemove = null;
        foreach (KeyValuePair<FlowTileCacheKey, FlowTileCacheEntry> pair in FlowTileCache)
        {
            if (pair.Key.WorldVersion != world.Version || !dirtySectors.Contains(pair.Key.SectorId))
                continue;

            tileKeysToRemove ??= new List<FlowTileCacheKey>();
            tileKeysToRemove.Add(pair.Key);
        }

        if (tileKeysToRemove != null)
        {
            for (int i = 0; i < tileKeysToRemove.Count; i++)
                RemoveFlowTileCacheEntry(tileKeysToRemove[i]);
        }

        List<SectorPathCacheKey> pathKeysToRemove = null;
        foreach (KeyValuePair<SectorPathCacheKey, SectorPathCacheEntry> pair in SectorPathCache)
        {
            if (pair.Key.WorldVersion != world.Version)
                continue;

            if (!dirtySectors.Contains(pair.Key.StartSectorId)
                && !dirtySectors.Contains(pair.Key.GoalSectorId)
                && !SectorPathTouchesAnySector(pair.Value, dirtySectors)
                && !SectorPathReferencesMissingPortal(world, pair.Value))
            {
                continue;
            }

            pathKeysToRemove ??= new List<SectorPathCacheKey>();
            pathKeysToRemove.Add(pair.Key);
        }

        if (pathKeysToRemove != null)
        {
            for (int i = 0; i < pathKeysToRemove.Count; i++)
                RemoveSectorPathCacheEntry(pathKeysToRemove[i]);
        }

        for (int i = 0; i < portalAccessKeysToRemove.Count; i++)
            RemoveSectorPortalAccessCacheEntry(portalAccessKeysToRemove[i]);

        List<SharedGoalFieldKey> sharedFieldKeysToRemove = null;
        foreach (KeyValuePair<SharedGoalFieldKey, SharedGoalField> pair in SharedGoalFields)
        {
            if (pair.Key.WorldVersion != world.Version)
                continue;

            if (!dirtySectors.Contains(pair.Key.GoalSectorId)
                && !SharedGoalFieldTouchesAnySector(pair.Value, dirtySectors)
                && !SharedGoalFieldReferencesMissingPortal(world, pair.Value))
            {
                continue;
            }

            sharedFieldKeysToRemove ??= new List<SharedGoalFieldKey>();
            sharedFieldKeysToRemove.Add(pair.Key);
        }

        if (sharedFieldKeysToRemove != null)
        {
            for (int i = 0; i < sharedFieldKeysToRemove.Count; i++)
                RemoveSharedGoalFieldCacheEntry(sharedFieldKeysToRemove[i]);
        }

        InvalidatePendingBuildJobsForDirtySectors(world, dirtySectors);
    }

    private static void InvalidatePendingBuildJobsForDirtySectors(NavigationWorld world, HashSet<int> dirtySectors)
    {
        if (world == null)
            throw new InvalidOperationException("InvalidatePendingBuildJobsForDirtySectors failed: world is null.");
        if (dirtySectors == null || dirtySectors.Count == 0)
            return;

        InvalidatePendingFlowTileBuildJobsForDirtySectors(world, dirtySectors);
        InvalidatePendingSharedGoalFieldBuildJobsForDirtySectors(world, dirtySectors);
    }

    private static void InvalidatePendingFlowTileBuildJobsForDirtySectors(NavigationWorld world, HashSet<int> dirtySectors)
    {
        LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First;
        while (node != null)
        {
            LinkedListNode<FlowTileBuildJob> next = node.Next;
            FlowTileBuildJob job = node.Value;
            if (job != null
                && job.BuildKey.CacheKey.WorldVersion == world.Version
                && (FlowTileBuildJobTouchesAnySector(job, dirtySectors) || FlowTileBuildJobReferencesMissingPortal(world, job)))
            {
                ReleasePendingFlowTileBuildJobPayloads(job);
                FlowTileBuildQueue.Remove(node);
                PendingFlowTileBuildJobs.Remove(job.BuildKey.CacheKey);
            }

            node = next;
        }
    }

    private static bool FlowTileBuildJobTouchesAnySector(FlowTileBuildJob job, HashSet<int> dirtySectors)
    {
        if (job == null || dirtySectors == null || dirtySectors.Count == 0)
            return false;

        if (dirtySectors.Contains(job.BuildKey.CacheKey.SectorId))
            return true;

        return PathTouchesAnySector(job.HandleSnapshot, dirtySectors);
    }

    private static bool FlowTileBuildJobReferencesMissingPortal(NavigationWorld world, FlowTileBuildJob job)
    {
        if (world == null)
            throw new InvalidOperationException("FlowTileBuildJobReferencesMissingPortal failed: world is null.");
        if (job == null)
            return false;

        FlowTileCacheKey key = job.BuildKey.CacheKey;
        if (key.GoalKind == TileGoalKind.Portal && !TryGetPortalById(world, key.GoalId, out _))
            return true;

        return PathReferencesMissingPortal(world, job.HandleSnapshot);
    }

    private static void InvalidatePendingSharedGoalFieldBuildJobsForDirtySectors(NavigationWorld world, HashSet<int> dirtySectors)
    {
        LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First;
        while (node != null)
        {
            LinkedListNode<SharedGoalFieldBuildJob> next = node.Next;
            SharedGoalFieldBuildJob job = node.Value;
            if (job != null
                && job.Key.WorldVersion == world.Version
                && (SharedGoalFieldBuildJobTouchesAnySector(job, dirtySectors) || SharedGoalFieldBuildJobReferencesMissingPortal(world, job)))
            {
                SharedGoalFieldBuildQueue.Remove(node);
                PendingSharedGoalFieldBuildJobs.Remove(job.Key);
            }

            node = next;
        }
    }

    private static bool SharedGoalFieldBuildJobTouchesAnySector(SharedGoalFieldBuildJob job, HashSet<int> dirtySectors)
    {
        if (job == null || dirtySectors == null || dirtySectors.Count == 0)
            return false;

        if (dirtySectors.Contains(job.GoalSectorId))
            return true;

        return job.Field != null && SharedGoalFieldTouchesAnySector(job.Field, dirtySectors);
    }

    private static bool SharedGoalFieldBuildJobReferencesMissingPortal(NavigationWorld world, SharedGoalFieldBuildJob job)
    {
        return job?.Field != null && SharedGoalFieldReferencesMissingPortal(world, job.Field);
    }

    private static bool SharedGoalFieldTouchesAnySector(SharedGoalField field, HashSet<int> dirtySectors)
    {
        if (field == null || dirtySectors == null || dirtySectors.Count == 0)
            return false;

        foreach (int node in field.NodeCosts.Keys)
        {
            DecodePortalNode(node, out int sectorId, out _);
            if (dirtySectors.Contains(sectorId))
                return true;
        }

        foreach (KeyValuePair<int, int> pair in field.NextNodeTowardGoal)
        {
            DecodePortalNode(pair.Key, out int fromSectorId, out _);
            DecodePortalNode(pair.Value, out int toSectorId, out _);
            if (dirtySectors.Contains(fromSectorId) || dirtySectors.Contains(toSectorId))
                return true;
        }

        return false;
    }

    private static bool SharedGoalFieldReferencesMissingPortal(NavigationWorld world, SharedGoalField field)
    {
        if (world == null)
            throw new InvalidOperationException("SharedGoalFieldReferencesMissingPortal failed: world is null.");
        if (field == null)
            return false;

        foreach (int node in field.NodeCosts.Keys)
        {
            DecodePortalNode(node, out _, out int portalId);
            if (!TryGetPortalById(world, portalId, out _))
                return true;
        }

        foreach (KeyValuePair<int, int> pair in field.NextNodeTowardGoal)
        {
            DecodePortalNode(pair.Key, out _, out int fromPortalId);
            DecodePortalNode(pair.Value, out _, out int toPortalId);
            if (!TryGetPortalById(world, fromPortalId, out _) || !TryGetPortalById(world, toPortalId, out _))
                return true;
        }

        return false;
    }

    private static bool SectorPathTouchesAnySector(SectorPathCacheEntry entry, HashSet<int> dirtySectors)
    {
        if (entry == null || entry.SectorIds == null || dirtySectors == null || dirtySectors.Count == 0)
            return false;

        for (int i = 0; i < entry.SectorIds.Length; i++)
        {
            if (dirtySectors.Contains(entry.SectorIds[i]))
                return true;
        }

        return false;
    }

    private static bool SectorPathReferencesMissingPortal(NavigationWorld world, SectorPathCacheEntry entry)
    {
        if (world == null)
            throw new InvalidOperationException("SectorPathReferencesMissingPortal failed: world is null.");
        if (entry == null || entry.PortalIds == null)
            return false;

        for (int i = 0; i < entry.PortalIds.Length; i++)
        {
            if (!TryGetPortalById(world, entry.PortalIds[i], out _))
                return true;
        }

        return false;
    }

    private static bool PathTouchesAnySector(PathHandle handle, HashSet<int> dirtySectors)
    {
        if (handle == null || handle.SectorIds == null || dirtySectors == null || dirtySectors.Count == 0)
            return false;

        for (int i = 0; i < handle.SectorIds.Length; i++)
        {
            if (dirtySectors.Contains(handle.SectorIds[i]))
                return true;
        }

        return false;
    }

    private static bool PathReferencesMissingPortal(PathHandle handle)
    {
        return PathReferencesMissingPortal(_world, handle);
    }

    private static bool PathReferencesMissingPortal(NavigationWorld world, PathHandle handle)
    {
        if (world == null)
            throw new InvalidOperationException("PathReferencesMissingPortal failed: world is null.");
        if (handle == null || handle.PortalIds == null)
            return false;

        for (int i = 0; i < handle.PortalIds.Length; i++)
        {
            if (!TryGetPortalById(world, handle.PortalIds[i], out _))
                return true;
        }

        return false;
    }

    private static void CollectDirtySectorsFixed(
        NavigationWorld world,
        FixVector2 boundsMinimum,
        FixVector2 boundsMaximum,
        HashSet<int> dirtySectors,
        bool includeNeighbors)
    {
        if (world == null)
            throw new ArgumentNullException(nameof(world));
        if (dirtySectors == null)
            throw new ArgumentNullException(nameof(dirtySectors));
        if (boundsMinimum.x > boundsMaximum.x || boundsMinimum.y > boundsMaximum.y)
            throw new ArgumentOutOfRangeException(nameof(boundsMinimum), "Dirty-sector bounds minimum exceeds maximum.");

        world.WorldToGridFixed(boundsMinimum, out int rawMinCellX, out int rawMinCellY);
        world.WorldToGridFixed(boundsMaximum, out int rawMaxCellX, out int rawMaxCellY);
        int minCellX = Mathf.Clamp(rawMinCellX, 0, world.Width - 1);
        int maxCellX = Mathf.Clamp(rawMaxCellX, 0, world.Width - 1);
        int minCellY = Mathf.Clamp(rawMinCellY, 0, world.Height - 1);
        int maxCellY = Mathf.Clamp(rawMaxCellY, 0, world.Height - 1);

        int minSectorX = Mathf.Clamp(minCellX / world.SectorSizeInCells, 0, world.SectorCountX - 1);
        int maxSectorX = Mathf.Clamp(maxCellX / world.SectorSizeInCells, 0, world.SectorCountX - 1);
        int minSectorY = Mathf.Clamp(minCellY / world.SectorSizeInCells, 0, world.SectorCountY - 1);
        int maxSectorY = Mathf.Clamp(maxCellY / world.SectorSizeInCells, 0, world.SectorCountY - 1);

        int padding = includeNeighbors ? 1 : 0;
        for (int sectorY = Mathf.Max(0, minSectorY - padding); sectorY <= Mathf.Min(world.SectorCountY - 1, maxSectorY + padding); sectorY++)
        {
            for (int sectorX = Mathf.Max(0, minSectorX - padding); sectorX <= Mathf.Min(world.SectorCountX - 1, maxSectorX + padding); sectorX++)
            {
                dirtySectors.Add(sectorY * world.SectorCountX + sectorX);
            }
        }
    }

    private static void BuildVerticalPortals(NavigationWorld world, List<PortalData> portals)
    {
        for (int sectorY = 0; sectorY < world.SectorCountY; sectorY++)
        {
            for (int sectorX = 0; sectorX < world.SectorCountX - 1; sectorX++)
            {
                SectorData sectorA = world.Sectors[sectorY * world.SectorCountX + sectorX];
                SectorData sectorB = world.Sectors[sectorY * world.SectorCountX + sectorX + 1];
                BuildVerticalBoundaryPortals(world, portals, sectorA, sectorB);
            }
        }
    }

    private static void BuildHorizontalPortals(NavigationWorld world, List<PortalData> portals)
    {
        for (int sectorY = 0; sectorY < world.SectorCountY - 1; sectorY++)
        {
            for (int sectorX = 0; sectorX < world.SectorCountX; sectorX++)
            {
                SectorData sectorA = world.Sectors[sectorY * world.SectorCountX + sectorX];
                SectorData sectorB = world.Sectors[(sectorY + 1) * world.SectorCountX + sectorX];
                BuildHorizontalBoundaryPortals(world, portals, sectorA, sectorB);
            }
        }
    }

    private static void BuildVerticalBoundaryPortals(NavigationWorld world, List<PortalData> portals, SectorData sectorA, SectorData sectorB)
    {
        int boundaryAX = sectorA.StartX + sectorA.Width - 1;
        int boundaryBX = sectorB.StartX;

        List<Vector2Int> cellsA = null;
        List<Vector2Int> cellsB = null;
        for (int y = Mathf.Max(sectorA.StartY, sectorB.StartY); y < Mathf.Min(sectorA.StartY + sectorA.Height, sectorB.StartY + sectorB.Height); y++)
        {
            bool passable = CanTraverseNeighborCells(world, boundaryAX, y, boundaryBX, y);
            if (passable)
            {
                cellsA ??= new List<Vector2Int>(8);
                cellsB ??= new List<Vector2Int>(8);
                cellsA.Add(new Vector2Int(boundaryAX, y));
                cellsB.Add(new Vector2Int(boundaryBX, y));
                continue;
            }

            FlushPortalRun(world, portals, sectorA.SectorId, sectorB.SectorId, cellsA, cellsB, true);
            cellsA = null;
            cellsB = null;
        }

        FlushPortalRun(world, portals, sectorA.SectorId, sectorB.SectorId, cellsA, cellsB, true);
    }

    private static void BuildHorizontalBoundaryPortals(NavigationWorld world, List<PortalData> portals, SectorData sectorA, SectorData sectorB)
    {
        int boundaryAY = sectorA.StartY + sectorA.Height - 1;
        int boundaryBY = sectorB.StartY;

        List<Vector2Int> cellsA = null;
        List<Vector2Int> cellsB = null;
        for (int x = Mathf.Max(sectorA.StartX, sectorB.StartX); x < Mathf.Min(sectorA.StartX + sectorA.Width, sectorB.StartX + sectorB.Width); x++)
        {
            bool passable = CanTraverseNeighborCells(world, x, boundaryAY, x, boundaryBY);
            if (passable)
            {
                cellsA ??= new List<Vector2Int>(8);
                cellsB ??= new List<Vector2Int>(8);
                cellsA.Add(new Vector2Int(x, boundaryAY));
                cellsB.Add(new Vector2Int(x, boundaryBY));
                continue;
            }

            FlushPortalRun(world, portals, sectorA.SectorId, sectorB.SectorId, cellsA, cellsB, false);
            cellsA = null;
            cellsB = null;
        }

        FlushPortalRun(world, portals, sectorA.SectorId, sectorB.SectorId, cellsA, cellsB, false);
    }

    private static void FlushPortalRun(
        NavigationWorld world,
        List<PortalData> portals,
        int sectorAId,
        int sectorBId,
        List<Vector2Int> cellsA,
        List<Vector2Int> cellsB,
        bool isVerticalBoundary)
    {
        if (cellsA == null || cellsB == null || cellsA.Count == 0 || cellsB.Count == 0)
            return;

        if (cellsA.Count != cellsB.Count)
            throw new InvalidOperationException($"FlushPortalRun failed: side cell count mismatch A={cellsA.Count} B={cellsB.Count}.");

        bool runIsNarrow = IsPortalBottleneck(world, sectorAId, sectorBId, cellsA, cellsB, isVerticalBoundary);
        int maxSegmentWidth = ResolvePortalMaxWindowWidthCells(world);
        int segmentStart = 0;
        for (int i = 1; i <= cellsA.Count; i++)
        {
            bool reachedEnd = i == cellsA.Count;
            bool reachedMaxWidth = i - segmentStart >= maxSegmentWidth;
            bool costSplit = !reachedEnd && ShouldSplitPortalRunBeforeIndex(world, cellsA, cellsB, i);
            if (!reachedEnd && !reachedMaxWidth && !costSplit)
                continue;

            AddPortalSegment(world, portals, sectorAId, sectorBId, cellsA, cellsB, segmentStart, i - segmentStart, isVerticalBoundary, runIsNarrow);
            segmentStart = i;
        }
    }

    private static int ResolvePortalMaxWindowWidthCells(NavigationWorld world)
    {
        return Mathf.Max(ResolvePortalNarrowWidthCells(world), ResolveScaledCellCount(world, Config.PortalMaxWindowWidthCells));
    }

    private static bool ShouldSplitPortalRunBeforeIndex(NavigationWorld world, List<Vector2Int> cellsA, List<Vector2Int> cellsB, int index)
    {
        if (index <= 0 || index >= cellsA.Count || index >= cellsB.Count)
            return false;

        int previousCost = ResolvePortalPairCost(world, cellsA[index - 1], cellsB[index - 1]);
        int currentCost = ResolvePortalPairCost(world, cellsA[index], cellsB[index]);
        return Mathf.Abs(currentCost - previousCost) >= PortalWindowSplitCostDelta;
    }

    private static int ResolvePortalPairCost(NavigationWorld world, Vector2Int cellA, Vector2Int cellB)
    {
        int costA = GetCostFieldValueStrict(world, cellA.x, cellA.y);
        int costB = GetCostFieldValueStrict(world, cellB.x, cellB.y);
        if (costA >= 255 || costB >= 255)
            return 255;

        return Mathf.Max(1, (costA + costB) / 2);
    }

    private static void AddPortalSegment(
        NavigationWorld world,
        List<PortalData> portals,
        int sectorAId,
        int sectorBId,
        List<Vector2Int> runCellsA,
        List<Vector2Int> runCellsB,
        int start,
        int count,
        bool isVerticalBoundary,
        bool runIsNarrow)
    {
        if (count <= 0)
            throw new InvalidOperationException("AddPortalSegment failed: segment count must be positive.");

        List<Vector2Int> cellsA = runCellsA.GetRange(start, count);
        List<Vector2Int> cellsB = runCellsB.GetRange(start, count);
        Vector3 center = Vector3.zero;
        for (int i = 0; i < cellsA.Count; i++)
        {
            center += world.GridToWorldCenter(cellsA[i].x, cellsA[i].y);
            center += world.GridToWorldCenter(cellsB[i].x, cellsB[i].y);
        }

        center /= cellsA.Count * 2f;

        PortalData portal = new PortalData
        {
            PortalId = ResolveStablePortalId(world, BuildPortalSignature(sectorAId, sectorBId, cellsA, isVerticalBoundary)),
            SectorAId = sectorAId,
            SectorBId = sectorBId,
            CellsA = cellsA.ToArray(),
            CellsB = cellsB.ToArray(),
            WorldCenter = center,
            WidthCells = cellsA.Count,
            IsNarrow = runIsNarrow,
            IsVerticalBoundary = isVerticalBoundary
        };
        portals.Add(portal);
    }

    private static float ResolvePortalCrossingCost(PortalData portal)
    {
        if (portal == null)
            throw new InvalidOperationException("ResolvePortalCrossingCost failed: portal is null.");

        return PortalBaseCrossingCost;
    }

    private static PortalSignature BuildPortalSignature(int sectorAId, int sectorBId, List<Vector2Int> cellsA, bool isVerticalBoundary)
    {
        if (cellsA == null || cellsA.Count == 0)
            throw new InvalidOperationException("BuildPortalSignature failed: cells are empty.");

        int firstAxis = isVerticalBoundary ? cellsA[0].y : cellsA[0].x;
        int lastAxis = isVerticalBoundary ? cellsA[cellsA.Count - 1].y : cellsA[cellsA.Count - 1].x;
        int boundary = isVerticalBoundary ? cellsA[0].x : cellsA[0].y;
        return new PortalSignature(sectorAId, sectorBId, isVerticalBoundary, boundary, firstAxis, lastAxis, cellsA.Count);
    }

    private static PortalSignature BuildPortalSignature(int sectorAId, int sectorBId, Vector2Int[] cellsA, bool isVerticalBoundary)
    {
        if (cellsA == null || cellsA.Length == 0)
            throw new InvalidOperationException("BuildPortalSignature failed: cells are empty.");

        int firstAxis = isVerticalBoundary ? cellsA[0].y : cellsA[0].x;
        int lastAxis = isVerticalBoundary ? cellsA[cellsA.Length - 1].y : cellsA[cellsA.Length - 1].x;
        int boundary = isVerticalBoundary ? cellsA[0].x : cellsA[0].y;
        return new PortalSignature(sectorAId, sectorBId, isVerticalBoundary, boundary, firstAxis, lastAxis, cellsA.Length);
    }

    private static int ResolveStablePortalId(NavigationWorld world, PortalSignature signature)
    {
        if (world.PortalIdsBySignature.TryGetValue(signature, out int existingId))
        {
            world.UsedPortalIds.Add(existingId);
            return existingId;
        }

        int id = world.NextPortalId;
        while (world.UsedPortalIds.Contains(id))
        {
            id++;
            if (id > ushort.MaxValue)
                throw new InvalidOperationException("ResolveStablePortalId failed: portal id range exhausted.");
        }

        world.NextPortalId = id + 1;
        world.PortalIdsBySignature.Add(signature, id);
        world.UsedPortalIds.Add(id);
        return id;
    }

    private static void RemoveStalePortalSignatures(NavigationWorld world)
    {
        List<PortalSignature> staleSignatures = null;
        foreach (KeyValuePair<PortalSignature, int> pair in world.PortalIdsBySignature)
        {
            if (world.UsedPortalIds.Contains(pair.Value))
                continue;

            staleSignatures ??= new List<PortalSignature>();
            staleSignatures.Add(pair.Key);
        }

        if (staleSignatures == null)
            return;

        for (int i = 0; i < staleSignatures.Count; i++)
            world.PortalIdsBySignature.Remove(staleSignatures[i]);
    }

    private static bool IsPortalBottleneck(
        NavigationWorld world,
        int sectorAId,
        int sectorBId,
        List<Vector2Int> cellsA,
        List<Vector2Int> cellsB,
        bool isVerticalBoundary)
    {
        if (cellsA == null || cellsB == null || cellsA.Count == 0 || cellsB.Count == 0)
            throw new InvalidOperationException("IsPortalBottleneck failed: portal cells are empty.");

        return cellsA.Count <= ResolvePortalNarrowWidthCells(world);
    }

    private static Vector2Int[] GetPortalCellsForSector(PortalData portal, int sectorId)
    {
        if (portal.SectorAId == sectorId)
            return portal.CellsA;
        if (portal.SectorBId == sectorId)
            return portal.CellsB;

        throw new InvalidOperationException($"GetPortalCellsForSector failed: sector {sectorId} is not connected to portal {portal.PortalId}.");
    }

    private static int GetOppositeSectorId(PortalData portal, int sectorId)
    {
        if (portal.SectorAId == sectorId)
            return portal.SectorBId;
        if (portal.SectorBId == sectorId)
            return portal.SectorAId;

        throw new InvalidOperationException($"GetOppositeSectorId failed: sector {sectorId} is not connected to portal {portal.PortalId}.");
    }

    private static void InitializeIntegrationField(float[] integration)
    {
        if (integration == null)
            throw new InvalidOperationException("InitializeIntegrationField failed: integration is null.");

        for (int i = 0; i < integration.Length; i++)
            integration[i] = float.PositiveInfinity;
    }

    private static bool IsSignificantIntegrationImprovement(float newCost, float existingCost)
    {
        if (float.IsPositiveInfinity(newCost))
            return false;
        if (float.IsPositiveInfinity(existingCost))
            return true;

        return newCost < existingCost - IntegrationSignificantImprovement;
    }

    private static float ResolveEikonalIntegrationCost(
        NavigationWorld world,
        SectorData sector,
        float[] integration,
        int worldX,
        int worldY,
        bool reverseTraversal)
    {
        float horizontal = float.PositiveInfinity;
        float vertical = float.PositiveInfinity;
        for (int i = 0; i < CardinalOffsetX.Length; i++)
        {
            int neighborX = worldX + CardinalOffsetX[i];
            int neighborY = worldY + CardinalOffsetY[i];
            if (!IsInsideSector(sector, neighborX, neighborY) || !world.IsWalkable(neighborX, neighborY))
                continue;
            if (!CanUseNeighborForIntegration(world, worldX, worldY, neighborX, neighborY, reverseTraversal))
                continue;

            float neighborCost = integration[GetSectorLocalIndex(sector, neighborX, neighborY)];
            if (float.IsPositiveInfinity(neighborCost))
                continue;

            if (neighborX != worldX)
                horizontal = Mathf.Min(horizontal, neighborCost);
            else
                vertical = Mathf.Min(vertical, neighborCost);
        }

        float cellCost = ResolveCellIntegrationCost(world, worldX, worldY);
        if (float.IsPositiveInfinity(cellCost))
            return float.PositiveInfinity;

        if (float.IsPositiveInfinity(horizontal))
            return float.IsPositiveInfinity(vertical) ? float.PositiveInfinity : vertical + cellCost;
        if (float.IsPositiveInfinity(vertical))
            return horizontal + cellCost;

        float a = Mathf.Min(horizontal, vertical);
        float b = Mathf.Max(horizontal, vertical);
        if (b - a >= cellCost)
            return a + cellCost;

        float discriminant = Mathf.Max(0f, 2f * cellCost * cellCost - (b - a) * (b - a));
        return (a + b + Mathf.Sqrt(discriminant)) * 0.5f;
    }

    private static bool CanUseNeighborForIntegration(
        NavigationWorld world,
        int worldX,
        int worldY,
        int neighborX,
        int neighborY,
        bool reverseTraversal)
    {
        return CanTraverseNeighborCells(
            world,
            reverseTraversal ? worldX : neighborX,
            reverseTraversal ? worldY : neighborY,
            reverseTraversal ? neighborX : worldX,
            reverseTraversal ? neighborY : worldY);
    }

    private static float ResolveCellIntegrationCost(NavigationWorld world, int worldX, int worldY)
    {
        int cost = GetCostFieldValueStrict(world, worldX, worldY);
        if (cost >= 255)
            return float.PositiveInfinity;

        if (cost <= 1)
            return 1f;

        return Mathf.Max(1f, cost);
    }

    private static int GetCostFieldValueStrict(
        NavigationWorld world,
        int worldX,
        int worldY,
        [CallerMemberName] string caller = null)
    {
        if (!TryGetCostFieldValue(world, worldX, worldY, out byte cost))
        {
            throw new InvalidOperationException(
                $"GetCostFieldValueStrict failed: invalid cost field read caller={caller} cell=({worldX},{worldY}) " +
                $"world={(world != null ? world.Width + "x" + world.Height : "null")} walkable={world?.WalkableMask?.Length ?? -1} " +
                $"cost={world?.CostField?.Length ?? -1} sectorCosts={world?.SectorCostFields?.Length ?? -1}.");
        }

        return cost;
    }

    private static bool TryGetCostFieldValue(NavigationWorld world, int worldX, int worldY, out byte cost)
    {
        cost = 0;
        if (world == null)
            return false;
        if (worldX < 0 || worldX >= world.Width || worldY < 0 || worldY >= world.Height)
            return false;
        if (world.WalkableMask == null || world.WalkableMask.Length != world.Width * world.Height)
            return false;

        int index = world.GetIndex(worldX, worldY);
        if (TryGetSectorForCell(world, worldX, worldY, out SectorData sector) && sector.IsClearCostField)
        {
            cost = world.WalkableMask[index] ? (byte)1 : byte.MaxValue;
            return true;
        }

        if (sector != null && world.SectorCostFields != null)
        {
            if (sector.SectorId < 0 || sector.SectorId >= world.SectorCostFields.Length)
                return false;

            byte[] sectorCost = world.SectorCostFields[sector.SectorId];
            if (sectorCost == null || sectorCost.Length != sector.Width * sector.Height)
                return false;

            cost = sectorCost[GetSectorLocalIndex(sector, worldX, worldY)];
            return true;
        }

        if (world.CostField == null || world.CostField.Length != world.Width * world.Height)
            return false;

        cost = world.CostField[index];
        return true;
    }

    private static void FinalizeWorldCostStorage(NavigationWorld world)
    {
        if (world == null)
            throw new InvalidOperationException("FinalizeWorldCostStorage failed: world is null.");
        if (world.CostField == null || world.CostField.Length != world.Width * world.Height)
            throw new InvalidOperationException("FinalizeWorldCostStorage failed: mutable cost field is missing.");
        if (world.Sectors == null || world.Sectors.Length != world.SectorCountX * world.SectorCountY)
            throw new InvalidOperationException("FinalizeWorldCostStorage failed: sectors are missing.");

        byte[][] sectorCostFields = new byte[world.Sectors.Length][];
        for (int i = 0; i < world.Sectors.Length; i++)
        {
            SectorData sector = world.Sectors[i];
            if (sector.IsClearCostField)
                continue;

            byte[] chunk = new byte[sector.Width * sector.Height];
            for (int y = 0; y < sector.Height; y++)
            {
                for (int x = 0; x < sector.Width; x++)
                {
                    int worldX = sector.StartX + x;
                    int worldY = sector.StartY + y;
                    chunk[x + y * sector.Width] = world.CostField[world.GetIndex(worldX, worldY)];
                }
            }

            sectorCostFields[sector.SectorId] = chunk;
        }

        world.SectorCostFields = sectorCostFields;
        ReturnByteArray(world.CostField);
        world.CostField = null;
    }

    private static byte[] MaterializeMutableCostField(NavigationWorld world)
    {
        if (world == null)
            throw new InvalidOperationException("MaterializeMutableCostField failed: world is null.");
        int cellCount = checked(world.Width * world.Height);
        if (world.WalkableMask == null || world.WalkableMask.Length != cellCount)
            throw new InvalidOperationException("MaterializeMutableCostField failed: walkable mask is missing.");
        if (world.Sectors == null || world.Sectors.Length != world.SectorCountX * world.SectorCountY)
            throw new InvalidOperationException("MaterializeMutableCostField failed: sectors are missing.");
        if (world.CostField != null)
        {
            if (world.CostField.Length != cellCount)
                throw new InvalidOperationException($"MaterializeMutableCostField failed: invalid full cost field length={world.CostField.Length} expected={cellCount}.");
            if (world.SectorCostFields != null)
                throw new InvalidOperationException("MaterializeMutableCostField failed: full and sector cost fields are both present.");

            return RentCopiedByteArray(world.CostField);
        }

        byte[] costField = RentByteArray(cellCount, clear: false);
        for (int i = 0; i < costField.Length; i++)
            costField[i] = world.WalkableMask[i] ? (byte)1 : byte.MaxValue;

        for (int i = 0; i < world.Sectors.Length; i++)
        {
            SectorData sector = world.Sectors[i];
            byte[] chunk = world.SectorCostFields != null && sector.SectorId >= 0 && sector.SectorId < world.SectorCostFields.Length
                ? world.SectorCostFields[sector.SectorId]
                : null;
            if (chunk == null)
            {
                if (!sector.IsClearCostField)
                    throw new InvalidOperationException($"MaterializeMutableCostField failed: missing non-clear cost chunk sector={sector.SectorId}.");
                continue;
            }
            if (chunk.Length != sector.Width * sector.Height)
                throw new InvalidOperationException($"MaterializeMutableCostField failed: invalid cost chunk sector={sector.SectorId} length={chunk.Length}.");

            for (int y = 0; y < sector.Height; y++)
            {
                for (int x = 0; x < sector.Width; x++)
                {
                    int worldX = sector.StartX + x;
                    int worldY = sector.StartY + y;
                    costField[world.GetIndex(worldX, worldY)] = chunk[x + y * sector.Width];
                }
            }
        }

        return costField;
    }

    private static float ResolveMinimumIntegrationCost(SectorData sector, float[] integration, Vector2Int[] targetCells)
    {
        float best = float.PositiveInfinity;
        for (int i = 0; i < targetCells.Length; i++)
        {
            Vector2Int cell = targetCells[i];
            if (!IsInsideSector(sector, cell.x, cell.y))
                continue;

            float cost = integration[GetSectorLocalIndex(sector, cell.x, cell.y)];
            if (cost < best)
                best = cost;
        }

        return best;
    }

    private static float ResolvePortalAccessCost(SectorData sector, int sectorId, int portalId, int worldX, int worldY)
    {
        return DequantizeDeterministicPortalCost(
            ResolveDeterministicPortalAccessCost(sector, sectorId, portalId, worldX, worldY));
    }

    private static long ResolveDeterministicPortalAccessCost(SectorData sector, int sectorId, int portalId, int worldX, int worldY)
    {
        return ResolveDeterministicPortalAccessCost(
            _world,
            sector,
            sectorId,
            portalId,
            worldX,
            worldY);
    }

    private static long ResolveDeterministicPortalAccessCost(
        NavigationWorld world,
        SectorData sector,
        int sectorId,
        int portalId,
        int worldX,
        int worldY)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveDeterministicPortalAccessCost failed: world is null.");
        if (!IsInsideSector(sector, worldX, worldY))
            return long.MaxValue;

        SectorPortalAccessEntry entry = GetPrebuiltSectorPortalAccess(
            world,
            sector,
            sectorId,
            portalId);
        return ResolveDeterministicPortalAccessIntegrationCost(
            world,
            sector,
            entry,
            worldX,
            worldY);
    }

    private static float ResolveGoalSectorPortalAccessCost(SectorData goalSector, int goalSectorId, int portalId, int goalX, int goalY)
    {
        if (_world == null)
            throw new InvalidOperationException("ResolveGoalSectorPortalAccessCost failed: world is null.");
        if (goalSector == null)
            throw new InvalidOperationException("ResolveGoalSectorPortalAccessCost failed: goal sector is null.");
        if (!IsInsideSector(goalSector, goalX, goalY))
            return float.PositiveInfinity;
        if (!TryGetPortalById(_world, portalId, out PortalData portal))
            throw new InvalidOperationException($"ResolveGoalSectorPortalAccessCost failed: portal missing sector={goalSectorId} portal={portalId}.");
        if (!PortalTouchesSector(portal, goalSectorId))
            return float.PositiveInfinity;

        return ResolvePortalAccessCost(goalSector, goalSectorId, portalId, goalX, goalY);
    }

    private static long ResolveDeterministicGoalSectorPortalAccessCost(SectorData goalSector, int goalSectorId, int portalId, int goalX, int goalY)
    {
        if (_world == null)
            throw new InvalidOperationException("ResolveDeterministicGoalSectorPortalAccessCost failed: world is null.");
        if (goalSector == null)
            throw new InvalidOperationException("ResolveDeterministicGoalSectorPortalAccessCost failed: goal sector is null.");
        if (!IsInsideSector(goalSector, goalX, goalY))
            return long.MaxValue;
        if (!TryGetPortalById(_world, portalId, out PortalData portal))
            throw new InvalidOperationException($"ResolveDeterministicGoalSectorPortalAccessCost failed: portal missing sector={goalSectorId} portal={portalId}.");
        if (!PortalTouchesSector(portal, goalSectorId))
            return long.MaxValue;

        return ResolveDeterministicPortalAccessCost(goalSector, goalSectorId, portalId, goalX, goalY);
    }

    private static float ResolvePortalAccessIntegrationCost(NavigationWorld world, SectorData sector, SectorPortalAccessEntry entry, int worldX, int worldY)
    {
        return DequantizeDeterministicPortalCost(
            ResolveDeterministicPortalAccessIntegrationCost(world, sector, entry, worldX, worldY));
    }

    private static long ResolveDeterministicPortalAccessIntegrationCost(NavigationWorld world, SectorData sector, SectorPortalAccessEntry entry, int worldX, int worldY)
    {
        if (entry == null)
            throw new InvalidOperationException("ResolveDeterministicPortalAccessIntegrationCost failed: entry is null.");
        if (sector == null)
            throw new InvalidOperationException("ResolveDeterministicPortalAccessIntegrationCost failed: sector is null.");
        if (!IsInsideSector(sector, worldX, worldY))
            return long.MaxValue;

        if (entry.IsAnalyticClearSector)
            return ResolveDeterministicAnalyticPortalAccessCost(world, sector, entry.PortalId, worldX, worldY);

        if (entry.DeterministicIntegration == null)
            throw new InvalidOperationException($"ResolveDeterministicPortalAccessIntegrationCost failed: deterministic integration is null sector={entry.SectorId} portal={entry.PortalId}.");
        int localIndex = GetSectorLocalIndex(sector, worldX, worldY);
        if (localIndex < 0 || localIndex >= entry.DeterministicIntegration.Length)
            throw new InvalidOperationException($"ResolveDeterministicPortalAccessIntegrationCost failed: local index out of range index={localIndex} length={entry.DeterministicIntegration.Length}.");
        return entry.DeterministicIntegration[localIndex];
    }

    private static long ResolveDeterministicPortalCenterSeedCost(PortalData portal, Vector2Int cell)
    {
        if (portal == null)
            throw new InvalidOperationException("ResolveDeterministicPortalCenterSeedCost failed: portal is null.");

        Vector2Int[] cells = portal.CellsA;
        if (cells == null || cells.Length == 0)
            throw new InvalidOperationException($"ResolveDeterministicPortalCenterSeedCost failed: portal has no cells portal={portal.PortalId}.");

        int firstAxis = portal.IsVerticalBoundary ? cells[0].y : cells[0].x;
        int lastAxis = portal.IsVerticalBoundary ? cells[cells.Length - 1].y : cells[cells.Length - 1].x;
        int cellAxis = portal.IsVerticalBoundary ? cell.y : cell.x;
        long doubledDistance = Math.Abs(checked((long)cellAxis * 2L - firstAxis - lastAxis));
        return checked(doubledDistance * (DeterministicPortalCostScale / 2L));
    }

    private static long[] BuildDeterministicPortalAccessIntegration(
        NavigationWorld world,
        SectorData sector,
        PortalData portal)
    {
        if (world == null)
            throw new InvalidOperationException("BuildDeterministicPortalAccessIntegration failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("BuildDeterministicPortalAccessIntegration failed: sector is null.");
        if (portal == null)
            throw new InvalidOperationException("BuildDeterministicPortalAccessIntegration failed: portal is null.");

        long[] integration = RentPortalAccessIntegrationArray(sector.Width * sector.Height);
        for (int i = 0; i < integration.Length; i++)
            integration[i] = long.MaxValue;

        DeterministicCostHeap openSet = PortalAccessIntegrationOpenSet;
        openSet.Clear();
        Vector2Int[] portalCells = GetPortalCellsForSector(portal, sector.SectorId);
        for (int i = 0; i < portalCells.Length; i++)
        {
            Vector2Int cell = portalCells[i];
            if (!IsInsideSector(sector, cell.x, cell.y) || !world.IsWalkable(cell.x, cell.y))
                continue;

            int localIndex = GetSectorLocalIndex(sector, cell.x, cell.y);
            long seedCost = ResolveDeterministicPortalCenterSeedCost(portal, cell);
            if (seedCost >= integration[localIndex])
                continue;

            integration[localIndex] = seedCost;
            openSet.Push(localIndex, seedCost);
        }

        if (openSet.Count == 0)
            throw new InvalidOperationException($"BuildDeterministicPortalAccessIntegration failed: portal has no walkable seed sector={sector.SectorId} portal={portal.PortalId}.");

        while (openSet.Count > 0)
        {
            DeterministicCostQueueNode node = openSet.Pop();
            if (node.Cost != integration[node.Index])
                continue;

            int worldX = sector.StartX + node.Index % sector.Width;
            int worldY = sector.StartY + node.Index / sector.Width;
            for (int i = 0; i < CardinalOffsetX.Length; i++)
            {
                int nextX = worldX + CardinalOffsetX[i];
                int nextY = worldY + CardinalOffsetY[i];
                if (!IsInsideSector(sector, nextX, nextY) || !world.IsWalkable(nextX, nextY))
                    continue;
                if (!CanTraverseNeighborCells(world, nextX, nextY, worldX, worldY))
                    continue;

                long newCost = ResolveDeterministicPortalAccessEikonalIntegrationCost(
                    world,
                    sector,
                    integration,
                    nextX,
                    nextY);
                int nextLocalIndex = GetSectorLocalIndex(sector, nextX, nextY);
                if (newCost >= integration[nextLocalIndex])
                    continue;

                integration[nextLocalIndex] = newCost;
                openSet.Push(nextLocalIndex, newCost);
            }
        }

        return integration;
    }

    private static long ResolveDeterministicPortalAccessEikonalIntegrationCost(
        NavigationWorld world,
        SectorData sector,
        long[] integration,
        int worldX,
        int worldY)
    {
        long horizontal = long.MaxValue;
        long vertical = long.MaxValue;
        for (int i = 0; i < CardinalOffsetX.Length; i++)
        {
            int neighborX = worldX + CardinalOffsetX[i];
            int neighborY = worldY + CardinalOffsetY[i];
            if (!IsInsideSector(sector, neighborX, neighborY)
                || !world.IsWalkable(neighborX, neighborY)
                || !CanTraverseNeighborCells(world, worldX, worldY, neighborX, neighborY))
            {
                continue;
            }

            long neighborCost = integration[GetSectorLocalIndex(sector, neighborX, neighborY)];
            if (neighborCost == long.MaxValue)
                continue;
            if (neighborX != worldX)
                horizontal = Math.Min(horizontal, neighborCost);
            else
                vertical = Math.Min(vertical, neighborCost);
        }

        int cellCost = GetCostFieldValueStrict(world, worldX, worldY);
        if (cellCost >= byte.MaxValue)
            return long.MaxValue;

        long stepCost = checked((long)Math.Max(1, cellCost) * DeterministicPortalCostScale);
        return ResolveDeterministicEikonalUpdate(
            horizontal,
            vertical,
            stepCost,
            long.MaxValue);
    }

    private static long ResolveDeterministicAnalyticPortalAccessCost(
        NavigationWorld world,
        SectorData sector,
        int portalId,
        int worldX,
        int worldY)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveDeterministicAnalyticPortalAccessCost failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("ResolveDeterministicAnalyticPortalAccessCost failed: sector is null.");
        if (!IsInsideSector(sector, worldX, worldY) || !world.IsWalkable(worldX, worldY))
            return long.MaxValue;
        if (!TryGetPortalById(world, portalId, out PortalData portal))
            throw new InvalidOperationException($"ResolveDeterministicAnalyticPortalAccessCost failed: portal missing sector={sector.SectorId} portal={portalId}.");

        long best = long.MaxValue;
        Vector2Int[] portalCells = GetPortalCellsForSector(portal, sector.SectorId);
        for (int i = 0; i < portalCells.Length; i++)
        {
            Vector2Int portalCell = portalCells[i];
            if (!IsInsideSector(sector, portalCell.x, portalCell.y) || !world.IsWalkable(portalCell.x, portalCell.y))
                continue;

            int dx = Math.Abs(portalCell.x - worldX);
            int dy = Math.Abs(portalCell.y - worldY);
            int diagonalSteps = Math.Min(dx, dy);
            int cardinalSteps = Math.Max(dx, dy) - diagonalSteps;
            long distanceCost = checked((long)diagonalSteps * 5793L + (long)cardinalSteps * DeterministicPortalCostScale);
            long cost = AddDeterministicPortalCosts(
                distanceCost,
                ResolveDeterministicPortalCenterSeedCost(portal, portalCell));
            if (cost < best)
                best = cost;
        }

        return best;
    }

    private static long ResolveDeterministicPortalTransitionCostFromAccess(
        NavigationWorld world,
        SectorData sector,
        int fromPortalId,
        int toPortalId)
    {
        SectorPortalAccessKey key = new SectorPortalAccessKey(world.Version, sector.SectorId, fromPortalId, sector.DirtyVersion);
        if (!SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry entry) || !IsValidSectorPortalAccessEntry(entry))
            throw new InvalidOperationException($"ResolveDeterministicPortalTransitionCostFromAccess failed: access field missing sector={sector.SectorId} portal={fromPortalId}.");

        return ResolveDeterministicPortalTransitionCostFromAccess(world, sector, entry, toPortalId);
    }

    private static long ResolveDeterministicPortalTransitionCostFromAccess(
        NavigationWorld world,
        SectorData sector,
        SectorPortalAccessEntry entry,
        int toPortalId)
    {
        if (entry == null)
            throw new InvalidOperationException("ResolveDeterministicPortalTransitionCostFromAccess failed: access entry is null.");

        PortalData targetPortal = GetPortalById(world, toPortalId);
        Vector2Int[] targetCells = GetPortalCellsForSector(targetPortal, sector.SectorId);
        long best = long.MaxValue;
        for (int i = 0; i < targetCells.Length; i++)
        {
            Vector2Int cell = targetCells[i];
            long accessCost = ResolveDeterministicPortalAccessIntegrationCost(world, sector, entry, cell.x, cell.y);
            long totalCost = AddDeterministicPortalCosts(
                accessCost,
                ResolveDeterministicPortalCenterSeedCost(targetPortal, cell));
            if (totalCost < best)
                best = totalCost;
        }

        return best;
    }

    private static void RebuildDeterministicPortalTransitionCosts(NavigationWorld world)
    {
        if (world?.Sectors == null)
            throw new InvalidOperationException("RebuildDeterministicPortalTransitionCosts failed: world is unavailable.");

        for (int sectorIndex = 0; sectorIndex < world.Sectors.Length; sectorIndex++)
        {
            SectorData sector = world.Sectors[sectorIndex];
            for (int portalIndex = 0; portalIndex < sector.PortalIds.Count; portalIndex++)
            {
                int portalId = sector.PortalIds[portalIndex];
                SectorPortalAccessKey key = new SectorPortalAccessKey(world.Version, sector.SectorId, portalId, sector.DirtyVersion);
                if (!SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry entry)
                    || entry == null
                    || entry.SectorId != sector.SectorId
                    || entry.PortalId != portalId
                    || entry.SectorDirtyVersion != sector.DirtyVersion)
                {
                    throw new InvalidOperationException($"RebuildDeterministicPortalTransitionCosts failed: access entry missing sector={sector.SectorId} portal={portalId}.");
                }

                entry.DeterministicIntegration = entry.IsAnalyticClearSector
                    ? null
                    : BuildDeterministicPortalAccessIntegration(world, sector, GetPortalById(world, portalId));
            }
        }

        for (int sectorIndex = 0; sectorIndex < world.Sectors.Length; sectorIndex++)
        {
            SectorData sector = world.Sectors[sectorIndex];
            for (int transitionIndex = 0; transitionIndex < sector.PortalTransitions.Count; transitionIndex++)
            {
                PortalTransition transition = sector.PortalTransitions[transitionIndex];
                transition.DeterministicCost = ResolveDeterministicPortalTransitionCostFromAccess(
                    world,
                    sector,
                    transition.FromPortalId,
                    transition.ToPortalId);
                if (transition.DeterministicCost == long.MaxValue)
                {
                    throw new InvalidOperationException(
                        $"RebuildDeterministicPortalTransitionCosts failed: transition is unreachable sector={sector.SectorId} from={transition.FromPortalId} to={transition.ToPortalId}.");
                }

            }
        }

        RefreshSectorPortalAccessAuthorityContentHashes();
        PortalAccessIntegrationArrayPool.Clear();
    }

    private static void RebuildDeterministicPortalTransitionCosts(
        NavigationWorld world,
        List<int> sectorIds)
    {
        if (world?.Sectors == null)
            throw new InvalidOperationException("RebuildDeterministicPortalTransitionCosts failed: world is unavailable.");
        if (sectorIds == null)
            throw new InvalidOperationException("RebuildDeterministicPortalTransitionCosts failed: sector ids are null.");

        int previousSectorId = -1;
        for (int sectorIndex = 0; sectorIndex < sectorIds.Count; sectorIndex++)
        {
            int sectorId = sectorIds[sectorIndex];
            if (sectorId <= previousSectorId || sectorId < 0 || sectorId >= world.Sectors.Length)
            {
                throw new InvalidOperationException(
                    $"RebuildDeterministicPortalTransitionCosts failed: sector ids must be sorted, unique and in range previous={previousSectorId} current={sectorId}.");
            }
            previousSectorId = sectorId;

            SectorData sector = world.Sectors[sectorId];
            for (int portalIndex = 0; portalIndex < sector.PortalIds.Count; portalIndex++)
            {
                int portalId = sector.PortalIds[portalIndex];
                var key = new SectorPortalAccessKey(world.Version, sector.SectorId, portalId, sector.DirtyVersion);
                if (!SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry entry)
                    || entry == null
                    || entry.SectorId != sector.SectorId
                    || entry.PortalId != portalId
                    || entry.SectorDirtyVersion != sector.DirtyVersion)
                {
                    throw new InvalidOperationException(
                        $"RebuildDeterministicPortalTransitionCosts failed: access entry missing sector={sector.SectorId} portal={portalId}.");
                }

                ReturnPortalAccessIntegrationArray(entry.DeterministicIntegration);
                entry.DeterministicIntegration = entry.IsAnalyticClearSector
                    ? null
                    : BuildDeterministicPortalAccessIntegration(world, sector, GetPortalById(world, portalId));
                RefreshSectorPortalAccessAuthorityContentHash(key, entry);
            }
        }

        for (int sectorIndex = 0; sectorIndex < sectorIds.Count; sectorIndex++)
        {
            SectorData sector = world.Sectors[sectorIds[sectorIndex]];
            for (int transitionIndex = 0; transitionIndex < sector.PortalTransitions.Count; transitionIndex++)
            {
                PortalTransition transition = sector.PortalTransitions[transitionIndex];
                transition.DeterministicCost = ResolveDeterministicPortalTransitionCostFromAccess(
                    world,
                    sector,
                    transition.FromPortalId,
                    transition.ToPortalId);
                if (transition.DeterministicCost == long.MaxValue)
                {
                    throw new InvalidOperationException(
                        $"RebuildDeterministicPortalTransitionCosts failed: transition is unreachable sector={sector.SectorId} from={transition.FromPortalId} to={transition.ToPortalId}.");
                }
            }
        }

        PortalAccessIntegrationArrayPool.Clear();
    }

    private static SectorPortalAccessEntry GetPrebuiltSectorPortalAccess(SectorData sector, int sectorId, int portalId)
    {
        return GetPrebuiltSectorPortalAccess(_world, sector, sectorId, portalId);
    }

    private static SectorPortalAccessEntry GetPrebuiltSectorPortalAccess(
        NavigationWorld world,
        SectorData sector,
        int sectorId,
        int portalId)
    {
        return GetRequiredSectorPortalAccess(world, sector, sectorId, portalId);
    }

    private static SectorPortalAccessEntry GetRequiredSectorPortalAccess(SectorData sector, int sectorId, int portalId)
    {
        return GetRequiredSectorPortalAccess(_world, sector, sectorId, portalId);
    }

    private static SectorPortalAccessEntry GetRequiredSectorPortalAccess(
        NavigationWorld world,
        SectorData sector,
        int sectorId,
        int portalId)
    {
        if (world == null)
            throw new InvalidOperationException("GetPrebuiltSectorPortalAccess failed: world is null.");
        SectorPortalAccessKey key = new SectorPortalAccessKey(
            world.Version,
            sectorId,
            portalId,
            sector.DirtyVersion);
        if (SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry cached)
            && IsValidSectorPortalAccessEntry(cached))
        {
            cached.LastUsedFrame = GetFrameCount();
            return cached;
        }

        throw new InvalidOperationException(
            $"GetPrebuiltSectorPortalAccess failed: missing prebuilt portal access field world={world.Version} sector={sectorId} portal={portalId} dirty={sector.DirtyVersion}. " +
            $"{BuildMissingPortalAccessDiagnostics(world, sectorId, portalId, sector.DirtyVersion)} " +
            "Portal access integration must be produced by world/runtime portal transition jobs, not synchronously in query/tile build.");
    }

    private static PendingSectorPortalAccess AddPendingAnalyticSectorPortalAccess(
        List<PendingSectorPortalAccess> pendingEntries,
        SectorData sector,
        int portalId)
    {
        if (pendingEntries == null)
            throw new InvalidOperationException("AddPendingAnalyticSectorPortalAccess failed: pendingEntries is null.");
        if (sector == null)
            throw new InvalidOperationException("AddPendingAnalyticSectorPortalAccess failed: sector is null.");

        var pending = new PendingSectorPortalAccess(
            sector.SectorId,
            portalId,
            sector.DirtyVersion,
            true);
        pendingEntries.Add(pending);
        return pending;
    }

    private static PendingSectorPortalAccess AddPendingDeterministicSectorPortalAccess(
        List<PendingSectorPortalAccess> pendingEntries,
        SectorData sector,
        int portalId)
    {
        if (pendingEntries == null)
            throw new InvalidOperationException("AddPendingDeterministicSectorPortalAccess failed: pendingEntries is null.");
        if (sector == null)
            throw new InvalidOperationException("AddPendingDeterministicSectorPortalAccess failed: sector is null.");

        var pending = new PendingSectorPortalAccess(
            sector.SectorId,
            portalId,
            sector.DirtyVersion,
            false);
        pendingEntries.Add(pending);
        return pending;
    }

    private static PendingSectorPortalAccess AddPendingPrebuiltDeterministicSectorPortalAccess(
        NavigationWorld world,
        List<PendingSectorPortalAccess> pendingEntries,
        SectorData sector,
        int portalId)
    {
        if (world == null)
            throw new InvalidOperationException("AddPendingPrebuiltDeterministicSectorPortalAccess failed: world is null.");
        if (pendingEntries == null)
            throw new InvalidOperationException("AddPendingPrebuiltDeterministicSectorPortalAccess failed: pendingEntries is null.");
        if (sector == null)
            throw new InvalidOperationException("AddPendingPrebuiltDeterministicSectorPortalAccess failed: sector is null.");

        long[] integration = BuildDeterministicPortalAccessIntegration(
            world,
            sector,
            GetPortalById(world, portalId));
        var pending = new PendingSectorPortalAccess(
            sector.SectorId,
            portalId,
            sector.DirtyVersion,
            false,
            integration);
        pendingEntries.Add(pending);
        return pending;
    }

    private static void ApplyPendingPortalTransitionCosts(
        NavigationWorld world,
        SectorData sector,
        PendingSectorPortalAccess pending)
    {
        if (pending == null)
            throw new InvalidOperationException("ApplyPendingPortalTransitionCosts failed: pending access is null.");
        if (pending.SectorId != sector.SectorId || pending.SectorDirtyVersion != sector.DirtyVersion)
        {
            throw new InvalidOperationException(
                $"ApplyPendingPortalTransitionCosts failed: pending access identity mismatch sector={sector.SectorId} portal={pending.PortalId}.");
        }

        var entry = new SectorPortalAccessEntry
        {
            DeterministicIntegration = pending.DeterministicIntegration,
            IsAnalyticClearSector = pending.IsAnalyticClearSector,
            SectorId = pending.SectorId,
            PortalId = pending.PortalId,
            SectorDirtyVersion = pending.SectorDirtyVersion
        };
        for (int i = 0; i < sector.PortalTransitions.Count; i++)
        {
            PortalTransition transition = sector.PortalTransitions[i];
            if (transition.FromPortalId != pending.PortalId)
                continue;

            transition.DeterministicCost = ResolveDeterministicPortalTransitionCostFromAccess(
                world,
                sector,
                entry,
                transition.ToPortalId);
            if (transition.DeterministicCost == long.MaxValue)
            {
                throw new InvalidOperationException(
                    $"ApplyPendingPortalTransitionCosts failed: transition is unreachable sector={sector.SectorId} from={pending.PortalId} to={transition.ToPortalId}.");
            }
        }
    }

    private static void CommitPendingSectorPortalAccessEntries(
        NavigationWorld world,
        List<PendingSectorPortalAccess> pendingEntries,
        bool entriesAreFinalized)
    {
        if (pendingEntries == null || pendingEntries.Count == 0)
            return;
        if (world == null)
            throw new InvalidOperationException("CommitPendingSectorPortalAccessEntries failed: world is null.");

        for (int i = 0; i < pendingEntries.Count; i++)
        {
            PendingSectorPortalAccess pending = pendingEntries[i]
                ?? throw new InvalidOperationException($"CommitPendingSectorPortalAccessEntries failed: pending entry is null index={i}.");
            SectorPortalAccessKey key = new SectorPortalAccessKey(
                world.Version,
                pending.SectorId,
                pending.PortalId,
                pending.SectorDirtyVersion);
            var entry = new SectorPortalAccessEntry
            {
                DeterministicIntegration = pending.DeterministicIntegration,
                IsAnalyticClearSector = pending.IsAnalyticClearSector,
                SectorId = pending.SectorId,
                PortalId = pending.PortalId,
                SectorDirtyVersion = pending.SectorDirtyVersion,
                LastUsedFrame = GetFrameCount()
            };
            SetSectorPortalAccessCacheEntry(key, entry);
            if (entriesAreFinalized)
                RefreshSectorPortalAccessAuthorityContentHash(key, entry);
            pending.DeterministicIntegration = null;
        }

        TrimSectorPortalAccessCache();
    }

    private static void ReturnPendingSectorPortalAccessIntegrations(List<PendingSectorPortalAccess> pendingEntries)
    {
        if (pendingEntries == null)
            return;

        for (int i = 0; i < pendingEntries.Count; i++)
        {
            PendingSectorPortalAccess pending = pendingEntries[i];
            if (pending == null || pending.DeterministicIntegration == null)
                continue;
            ReturnPortalAccessIntegrationArray(pending.DeterministicIntegration);
            pending.DeterministicIntegration = null;
        }
    }

    private static void ValidatePendingSectorPortalAccessCoverage(
        NavigationWorld world,
        List<PendingSectorPortalAccess> pendingEntries,
        string stage)
    {
        if (world?.Sectors == null)
            throw new InvalidOperationException($"ValidatePendingSectorPortalAccessCoverage failed: world is unavailable stage={stage}.");
        if (pendingEntries == null)
            throw new InvalidOperationException($"ValidatePendingSectorPortalAccessCoverage failed: pending entries are null stage={stage}.");

        var pendingByKey = new Dictionary<SectorPortalAccessKey, PendingSectorPortalAccess>(pendingEntries.Count);
        for (int i = 0; i < pendingEntries.Count; i++)
        {
            PendingSectorPortalAccess pending = pendingEntries[i]
                ?? throw new InvalidOperationException($"ValidatePendingSectorPortalAccessCoverage failed: null entry stage={stage} index={i}.");
            if (!pending.IsAnalyticClearSector && pending.DeterministicIntegration == null)
            {
                throw new InvalidOperationException(
                    $"ValidatePendingSectorPortalAccessCoverage failed: deterministic integration is missing stage={stage} sector={pending.SectorId} portal={pending.PortalId}.");
            }

            var key = new SectorPortalAccessKey(world.Version, pending.SectorId, pending.PortalId, pending.SectorDirtyVersion);
            if (!pendingByKey.TryAdd(key, pending))
                throw new InvalidOperationException($"ValidatePendingSectorPortalAccessCoverage failed: duplicate entry stage={stage} sector={pending.SectorId} portal={pending.PortalId}.");
        }

        for (int sectorId = 0; sectorId < world.Sectors.Length; sectorId++)
        {
            SectorData sector = world.Sectors[sectorId]
                ?? throw new InvalidOperationException($"ValidatePendingSectorPortalAccessCoverage failed: null sector stage={stage} sector={sectorId}.");
            for (int i = 0; i < sector.PortalIds.Count; i++)
            {
                int portalId = sector.PortalIds[i];
                var key = new SectorPortalAccessKey(world.Version, sectorId, portalId, sector.DirtyVersion);
                if (pendingByKey.ContainsKey(key))
                    continue;
                if (SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry cached)
                    && IsValidSectorPortalAccessEntry(cached))
                {
                    continue;
                }

                throw new InvalidOperationException(
                    $"ValidatePendingSectorPortalAccessCoverage failed: future committed coverage is missing stage={stage} sector={sectorId} portal={portalId} dirty={sector.DirtyVersion}.");
            }
        }
    }

    private static void EnsureAllSectorPortalAccessCoverage(NavigationWorld world, string stage)
    {
        if (world == null)
            throw new InvalidOperationException("EnsureAllSectorPortalAccessCoverage failed: world is null.");
        if (world.Sectors == null)
            throw new InvalidOperationException($"EnsureAllSectorPortalAccessCoverage failed: sectors are null stage={stage}.");

        for (int sectorId = 0; sectorId < world.Sectors.Length; sectorId++)
        {
            SectorData sector = world.Sectors[sectorId];
            if (sector == null)
                throw new InvalidOperationException($"EnsureAllSectorPortalAccessCoverage failed: sector is null stage={stage} sector={sectorId}.");

            for (int i = 0; i < sector.PortalIds.Count; i++)
            {
                int portalId = sector.PortalIds[i];
                SectorPortalAccessKey key = new SectorPortalAccessKey(world.Version, sectorId, portalId, sector.DirtyVersion);
                if (SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry existing)
                    && IsValidSectorPortalAccessEntry(existing))
                {
                    continue;
                }

                SetSectorPortalAccessCacheEntry(key, BuildSectorPortalAccessForCommit(world, sector, sectorId, portalId));
            }
        }
    }

    private static SectorPortalAccessEntry BuildSectorPortalAccessForCommit(NavigationWorld world, SectorData sector, int sectorId, int portalId)
    {
        if (world == null)
            throw new InvalidOperationException("BuildSectorPortalAccessForCommit failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("BuildSectorPortalAccessForCommit failed: sector is null.");
        if (sector.SectorId != sectorId)
            throw new InvalidOperationException($"BuildSectorPortalAccessForCommit failed: sector id mismatch expected={sectorId} actual={sector.SectorId}.");
        if (!TryGetPortalById(world, portalId, out PortalData portal))
            throw new InvalidOperationException($"BuildSectorPortalAccessForCommit failed: portal missing world={world.Version} sector={sectorId} portal={portalId}.");

        return new SectorPortalAccessEntry
        {
            IsAnalyticClearSector = CanUseAnalyticPortalAccess(world, sector, portalId),
            SectorId = sectorId,
            PortalId = portalId,
            SectorDirtyVersion = sector.DirtyVersion,
            LastUsedFrame = GetFrameCount()
        };
    }

    private static bool IsValidSectorPortalAccessEntry(SectorPortalAccessEntry entry)
    {
        if (entry == null)
            return false;
        if (entry.IsAnalyticClearSector)
            return entry.SectorId >= 0 && entry.PortalId >= 0;

        return entry.DeterministicIntegration != null;
    }

    private static void ValidateSectorPortalAccessCoverage(NavigationWorld world, HashSet<int> sectorIds, string stage)
    {
        if (world == null)
            throw new InvalidOperationException("ValidateSectorPortalAccessCoverage failed: world is null.");
        if (sectorIds == null || sectorIds.Count == 0)
            return;

        foreach (int sectorId in sectorIds)
        {
            if (sectorId < 0 || sectorId >= world.Sectors.Length)
                throw new InvalidOperationException($"ValidateSectorPortalAccessCoverage failed: sector out of range sector={sectorId} stage={stage}.");

            SectorData sector = world.Sectors[sectorId];
            for (int i = 0; i < sector.PortalIds.Count; i++)
            {
                int portalId = sector.PortalIds[i];
                SectorPortalAccessKey key = new SectorPortalAccessKey(world.Version, sectorId, portalId, sector.DirtyVersion);
                if (!SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry entry) || !IsValidSectorPortalAccessEntry(entry))
                {
                    throw new InvalidOperationException(
                        $"ValidateSectorPortalAccessCoverage failed: missing portal access stage={stage} world={world.Version} sector={sectorId} portal={portalId} dirty={sector.DirtyVersion}.");
                }
            }
        }
    }

    private static void ValidateAllSectorPortalAccessCoverage(NavigationWorld world, string stage)
    {
        if (world == null)
            throw new InvalidOperationException("ValidateAllSectorPortalAccessCoverage failed: world is null.");
        if (world.Sectors == null)
            throw new InvalidOperationException($"ValidateAllSectorPortalAccessCoverage failed: sectors are null stage={stage}.");

        for (int sectorId = 0; sectorId < world.Sectors.Length; sectorId++)
        {
            SectorData sector = world.Sectors[sectorId];
            if (sector == null)
                throw new InvalidOperationException($"ValidateAllSectorPortalAccessCoverage failed: sector is null stage={stage} sector={sectorId}.");

            for (int i = 0; i < sector.PortalIds.Count; i++)
            {
                int portalId = sector.PortalIds[i];
                SectorPortalAccessKey key = new SectorPortalAccessKey(world.Version, sectorId, portalId, sector.DirtyVersion);
                if (!SectorPortalAccessCache.TryGetValue(key, out SectorPortalAccessEntry entry) || !IsValidSectorPortalAccessEntry(entry))
                {
                    throw new InvalidOperationException(
                        $"ValidateAllSectorPortalAccessCoverage failed: missing portal access stage={stage} world={world.Version} sector={sectorId} portal={portalId} dirty={sector.DirtyVersion}. " +
                        BuildMissingPortalAccessDiagnostics(world, sectorId, portalId, sector.DirtyVersion));
                }
            }
        }
    }

    private static void RemoveSectorPortalAccessCacheEntriesForWorldVersion(int worldVersion)
    {
        if (worldVersion <= 0 || SectorPortalAccessCache.Count == 0)
            return;

        List<SectorPortalAccessKey> keysToRemove = null;
        foreach (SectorPortalAccessKey key in SectorPortalAccessCache.Keys)
        {
            if (key.WorldVersion != worldVersion)
                continue;

            keysToRemove ??= new List<SectorPortalAccessKey>();
            keysToRemove.Add(key);
        }

        if (keysToRemove == null)
            return;

        for (int i = 0; i < keysToRemove.Count; i++)
            RemoveSectorPortalAccessCacheEntry(keysToRemove[i]);
    }

    private static string BuildMissingPortalAccessDiagnostics(NavigationWorld world, int sectorId, int portalId, int dirtyVersion)
    {
        if (world == null)
            return "diag=world-null";

        int sameWorldSectorEntries = 0;
        int sameWorldEntries = 0;
        int samePortalAnyWorldEntries = 0;
        string sampleSameWorldSector = "none";
        string sampleSamePortal = "none";
        foreach (SectorPortalAccessKey existingKey in SectorPortalAccessCache.Keys)
        {
            if (existingKey.WorldVersion == world.Version)
            {
                sameWorldEntries++;
                if (existingKey.SectorId == sectorId)
                {
                    sameWorldSectorEntries++;
                    if (sampleSameWorldSector == "none")
                        sampleSameWorldSector = $"world={existingKey.WorldVersion},sector={existingKey.SectorId},portal={existingKey.PortalId},dirty={existingKey.SectorDirtyVersion}";
                }
            }

            if (existingKey.PortalId == portalId)
            {
                samePortalAnyWorldEntries++;
                if (sampleSamePortal == "none")
                    sampleSamePortal = $"world={existingKey.WorldVersion},sector={existingKey.SectorId},portal={existingKey.PortalId},dirty={existingKey.SectorDirtyVersion}";
            }
        }

        string sectorInfo = "sector=out-of-range";
        if (world.Sectors != null && sectorId >= 0 && sectorId < world.Sectors.Length)
        {
            SectorData sector = world.Sectors[sectorId];
            sectorInfo = sector == null
                ? "sector=null"
                : $"sectorPortalCount={sector.PortalIds.Count} sectorTransitionCount={sector.PortalTransitions.Count} sectorDirty={sector.DirtyVersion} sectorBounds=({sector.StartX},{sector.StartY},{sector.Width},{sector.Height}) sectorPortals=[{string.Join(",", sector.PortalIds)}]";
        }

        string portalInfo = "portal=missing";
        if (TryGetPortalById(world, portalId, out PortalData portal))
        {
            portalInfo = $"portalSectors=({portal.SectorAId},{portal.SectorBId}) portalWidth={portal.WidthCells} portalNarrow={portal.IsNarrow} portalVertical={portal.IsVerticalBoundary} cellsA={FormatPortalCellsForDiagnostics(portal.CellsA, 4)} cellsB={FormatPortalCellsForDiagnostics(portal.CellsB, 4)}";
        }

        string states = BuildWorldStateDiagnosticsForPortalAccess();
        return $"diag=cacheCount={SectorPortalAccessCache.Count} sameWorldEntries={sameWorldEntries} sameWorldSectorEntries={sameWorldSectorEntries} samePortalAnyWorldEntries={samePortalAnyWorldEntries} sampleSameWorldSector={sampleSameWorldSector} sampleSamePortal={sampleSamePortal} worldAgentType={world.AgentTypeId} worldDirtyExpected={dirtyVersion} sectors={(world.Sectors != null ? world.Sectors.Length : -1)} portals={(world.Portals != null ? world.Portals.Length : -1)} {sectorInfo} {portalInfo} {states}";
    }

    private static string FormatPortalCellsForDiagnostics(Vector2Int[] cells, int maxCells)
    {
        if (cells == null)
            return "null";
        if (cells.Length == 0)
            return "empty";

        int count = Mathf.Min(cells.Length, Mathf.Max(1, maxCells));
        System.Text.StringBuilder builder = new System.Text.StringBuilder(96);
        builder.Append('[');
        for (int i = 0; i < count; i++)
        {
            if (i > 0)
                builder.Append(';');

            builder.Append(cells[i].x);
            builder.Append(',');
            builder.Append(cells[i].y);
        }

        if (cells.Length > count)
        {
            builder.Append(";...");
            builder.Append(cells.Length);
        }

        builder.Append(']');
        return builder.ToString();
    }

    private static string BuildWorldStateDiagnosticsForPortalAccess()
    {
        System.Text.StringBuilder builder = new System.Text.StringBuilder(256);
        builder.Append("worldStates=[");
        int appended = 0;
        foreach (KeyValuePair<int, WorldRuntimeState> pair in WorldStates)
        {
            if (appended > 0)
                builder.Append(" | ");

            WorldRuntimeState state = pair.Value;
            builder.Append("agentType=");
            builder.Append(pair.Key);
            builder.Append(",world=");
            builder.Append(state?.World != null ? state.World.Version.ToString() : "null");
            builder.Append(",dirty=");
            builder.Append(state != null && state.IsDirty);
            builder.Append(",build=");
            builder.Append(state?.BuildJob != null ? state.BuildJob.Stage.ToString() : "null");
            builder.Append(",runtime=");
            builder.Append(state?.RuntimeDirtyJob != null ? state.RuntimeDirtyJob.Stage.ToString() : "null");
            appended++;
            if (appended >= 8)
                break;
        }

        if (appended == 0)
            builder.Append("none");
        builder.Append(']');
        return builder.ToString();
    }

    private static void TrimSectorPortalAccessCache()
    {
        // Sector portal access fields are required graph data for strict path building.
        // Dirty-sector invalidation removes stale entries; LRU eviction would create missing-field failures.
    }

    private static bool IsInsideSector(SectorData sector, int worldX, int worldY)
    {
        return worldX >= sector.StartX
               && worldX < sector.StartX + sector.Width
               && worldY >= sector.StartY
               && worldY < sector.StartY + sector.Height;
    }

    private static int GetSectorLocalIndex(SectorData sector, int worldX, int worldY)
    {
        return (worldX - sector.StartX) + (worldY - sector.StartY) * sector.Width;
    }

    private static bool IsCellReachableInTile(FlowTileCacheEntry tile, int worldX, int worldY)
    {
        int localIndex = tile.GetLocalIndex(worldX, worldY);
        return IsFlowReachable(tile, localIndex);
    }

    private static bool AreCellsConnectedInsideSector(SectorData sector, int startX, int startY, int goalX, int goalY)
    {
        if (sector == null)
            throw new InvalidOperationException("AreCellsConnectedInsideSector failed: sector is null.");
        if (!IsInsideSector(sector, startX, startY) || !IsInsideSector(sector, goalX, goalY))
            return false;
        if (sector.LocalComponentIds == null || sector.LocalComponentIds.Length != sector.Width * sector.Height)
            throw new InvalidOperationException($"AreCellsConnectedInsideSector failed: local components missing sector={sector.SectorId}.");

        int startComponent = sector.LocalComponentIds[GetSectorLocalIndex(sector, startX, startY)];
        int goalComponent = sector.LocalComponentIds[GetSectorLocalIndex(sector, goalX, goalY)];
        return startComponent > 0 && startComponent == goalComponent;
    }

    private static void LogTileReachabilityFailure(
        AgentRuntimeData agent,
        FlowTileCacheEntry tile,
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        TileGoalKind goalKind,
        int downstreamPortalId)
    {
        PathHandle handle = agent?.NavState.PathHandle;
        SectorData startSector = _world != null && startSectorId >= 0 && startSectorId < _world.Sectors.Length
            ? _world.Sectors[startSectorId]
            : null;
        bool startWalkable = _world != null && _world.IsWalkable(startX, startY);
        bool insideTile = tile != null && IsInsideSector(tile, startX, startY);
        string startCost = "tile=null";
        string startFlow = "tile=null";
        if (tile != null && insideTile)
        {
            int localIndex = tile.GetLocalIndex(startX, startY);
            float cost = GetTileIntegrationCostForDiagnostics(tile, startX, startY);
            startCost = float.IsPositiveInfinity(cost) ? "INF" : cost.ToString("F3");
            startFlow = ResolveRuntimeFlowDirection(tile, startX, startY, localIndex).ToString();
        }

        Debug.LogError(
            $"[FlowTileReachabilityFail] agent={agent?.CharacterKey ?? "null"} start=({startX},{startY}) goal=({goalX},{goalY}) " +
            $"startSector={startSectorId} goalSector={goalSectorId} startWalkable={startWalkable} insideTile={insideTile} " +
            $"startCost={startCost} startFlow={startFlow} goalKind={goalKind} downstreamPortal={downstreamPortalId} " +
            $"sectorDirty={(startSector != null ? startSector.DirtyVersion : -1)} tileKey={(tile != null ? FormatTileKey(tile.Key) : "null")} " +
            $"tileRect={(tile != null ? $"({tile.StartX},{tile.StartY},{tile.Width},{tile.Height})" : "null")} " +
            $"tileGoals={(tile != null ? FormatGoalCells(tile.GoalCells) : "null")} goalCosts={(tile != null ? FormatIntegrationCosts(tile, tile.GoalCells) : "null")} " +
            $"tileSummary={DescribeTileIntegrationSummary(tile)} handle={FormatPathHandle(handle)}");
    }

    private static int EncodePortalNode(int sectorId, int portalId)
    {
        return (sectorId << 16) | (portalId & 0xFFFF);
    }

    private static void DecodePortalNode(int node, out int sectorId, out int portalId)
    {
        sectorId = node >> 16;
        portalId = node & 0xFFFF;
    }

    private static bool EnsurePathHandle(AgentRuntimeData agent, int startSectorId, int goalSectorId, int startX, int startY, int goalX, int goalY)
    {
        PathHandle handle = agent.NavState.PathHandle;
        if (handle != null
            && handle.WorldVersion == _world.Version
            && handle.SectorIds != null
            && handle.SectorIds.Length > 0
            && !PathReferencesMissingPortal(handle)
            && FindSectorIndex(handle, startSectorId, 0) >= 0
            && handle.SectorIds[handle.SectorIds.Length - 1] == goalSectorId)
        {
            if (!handle.MatchesGoal(goalX, goalY))
            {
                int oldGoalX = handle.GoalX;
                int oldGoalY = handle.GoalY;
                _perf.PathBuildGoalCellMismatch++;
                handle.GoalX = goalX;
                handle.GoalY = goalY;
                if (GameDebugSettings.IsEnabled(DebugCategory.Move)
                    && TryConsumeSuccessfulMoveDiagnosticBudget())
                {
                    GameDebugSettings.Log(DebugCategory.Move,
                        $"[FlowPathGoalCellUpdate] agent={agent.CharacterKey} action=updateFinalGoal startSector={startSectorId} goalSector={goalSectorId} " +
                        $"start=({startX},{startY}) oldGoal=({oldGoalX},{oldGoalY}) newGoal=({goalX},{goalY}) " +
                        $"source={handle.BuildSource ?? "unknown"} decision={BuildPathRepathDecisionDiagnostics(handle, startSectorId, goalSectorId, startX, startY, goalX, goalY)} " +
                        $"handle={FormatPathHandle(handle)}");
                }
            }

            return true;
        }

        int startCellIndex = _world.GetIndex(startX, startY);
        int goalCellIndex = _world.GetIndex(goalX, goalY);
        int startSectorDirtyVersion = _world.Sectors[startSectorId].DirtyVersion;
        int goalSectorDirtyVersion = _world.Sectors[goalSectorId].DirtyVersion;
        if (agent.NavState.HasFailedPathRequest
            && agent.NavState.FailedPathWorldVersion == _world.Version
            && agent.NavState.FailedPathStartCellIndex == startCellIndex
            && agent.NavState.FailedPathGoalCellIndex == goalCellIndex
            && agent.NavState.FailedPathStartSectorDirtyVersion == startSectorDirtyVersion
            && agent.NavState.FailedPathGoalSectorDirtyVersion == goalSectorDirtyVersion)
        {
            return false;
        }

        PathHandle oldHandle = handle;
        string rebuildReason = ResolvePathHandleRebuildReason(oldHandle, startSectorId, goalSectorId, goalX, goalY);
        IncrementPathHandleRebuildReason(rebuildReason);
        handle = rebuildReason == "goalSectorMismatch"
                 && TryBuildPathHandleWithCommittedPortalPrefix(
                     agent,
                     oldHandle,
                     startSectorId,
                     goalSectorId,
                     goalX,
                     goalY,
                     out PathHandle committedPrefixHandle)
            ? committedPrefixHandle
            : BuildPathHandle(startSectorId, goalSectorId, startX, startY, goalX, goalY);
        agent.NavState.PathHandle = handle;
        agent.NavState.HasFailedPathRequest = handle == null;
        agent.NavState.FailedPathWorldVersion = _world.Version;
        agent.NavState.FailedPathStartCellIndex = startCellIndex;
        agent.NavState.FailedPathGoalCellIndex = goalCellIndex;
        agent.NavState.FailedPathStartSectorDirtyVersion = startSectorDirtyVersion;
        agent.NavState.FailedPathGoalSectorDirtyVersion = goalSectorDirtyVersion;
        if (GameDebugSettings.IsEnabled(DebugCategory.Move)
            && TryConsumeSuccessfulMoveDiagnosticBudget())
        {
            GameDebugSettings.Log(DebugCategory.Move,
                $"[FlowPathRebuild] agent={agent.CharacterKey} reason={rebuildReason} startSector={startSectorId} goalSector={goalSectorId} " +
                $"start=({startX},{startY}) goal=({goalX},{goalY}) oldHandle={FormatPathHandle(oldHandle)} result={(handle != null ? "ok" : "null")} newHandle={FormatPathHandle(handle)}");
        }
        return handle != null;
    }

    private static bool TryBuildPathHandleWithCommittedPortalPrefix(
        AgentRuntimeData agent,
        PathHandle previousHandle,
        int startSectorId,
        int goalSectorId,
        int goalX,
        int goalY,
        out PathHandle handle)
    {
        handle = null;
        AgentNavState nav = agent?.NavState;
        if (nav == null
            || nav.StableGoalTargetId == int.MinValue
            || previousHandle == null
            || previousHandle.WorldVersion != _world.Version
            || goalSectorId == startSectorId
            || !nav.PortalTraversalHasCommittedTileSlot
            || nav.PortalTraversalWorldVersion != _world.Version
            || nav.PortalTraversalSectorId != startSectorId)
        {
            return false;
        }

        int previousSectorIndex = previousHandle.CurrentSectorIndex;
        if (previousHandle.SectorIds == null
            || previousSectorIndex < 0
            || previousSectorIndex >= previousHandle.SectorIds.Length
            || previousHandle.SectorIds[previousSectorIndex] != startSectorId)
        {
            return false;
        }

        int committedPortalId = ResolveCurrentDownstreamPortalId(previousHandle);
        if (committedPortalId < 0 || committedPortalId != nav.PortalTraversalId)
            return false;

        FlowTileCacheKey committedTileKey = previousHandle.HasCommittedCurrentTileKey
            ? previousHandle.CommittedCurrentTileKey
            : CreateTileCacheKeyForPathSegment(
                previousHandle,
                previousSectorIndex,
                previousHandle.GoalX,
                previousHandle.GoalY,
                agent.AgentTypeId,
                out _,
                out _);
        if (committedTileKey.WorldVersion != _world.Version
            || committedTileKey.SectorId != startSectorId
            || committedTileKey.GoalKind != TileGoalKind.Portal
            || committedTileKey.GoalId != committedPortalId
            || committedTileKey.AgentTypeId != agent.AgentTypeId
            || committedTileKey.DirtyVersion != _world.Sectors[startSectorId].DirtyVersion)
        {
            throw new InvalidOperationException(
                $"TryBuildPathHandleWithCommittedPortalPrefix failed: committed tile key is inconsistent key={FormatTileKey(committedTileKey)}, portal={committedPortalId}, sector={startSectorId}.");
        }
        if (!DeterministicFlowTileCache.ContainsKey(committedTileKey))
        {
            throw new InvalidOperationException(
                $"TryBuildPathHandleWithCommittedPortalPrefix failed: committed tile is absent key={FormatTileKey(committedTileKey)}.");
        }
        if (!previousHandle.HasCommittedCurrentTileKey)
        {
            CommitCurrentFunnelCorridor(previousHandle, committedTileKey);
            previousHandle.HasCommittedCurrentTileKey = true;
            previousHandle.CommittedCurrentTileKey = committedTileKey;
        }

        PortalData committedPortal = GetPortalById(_world, committedPortalId);
        int downstreamSectorId = GetOppositeSectorId(committedPortal, startSectorId);
        Vector2Int[] downstreamCells = GetPortalCellsForSector(committedPortal, downstreamSectorId);
        int slotIndex = nav.PortalTraversalSlotIndex;
        if (slotIndex < 0 || slotIndex >= downstreamCells.Length)
        {
            throw new InvalidOperationException(
                $"TryBuildPathHandleWithCommittedPortalPrefix failed: committed slot is invalid portal={committedPortalId}, slot={slotIndex}, count={downstreamCells.Length}.");
        }

        Vector2Int downstreamStart = downstreamCells[slotIndex];
        PathHandle suffix = BuildPathHandle(
            downstreamSectorId,
            goalSectorId,
            downstreamStart.x,
            downstreamStart.y,
            goalX,
            goalY);
        if (suffix == null)
            return false;
        if (suffix.SectorIds == null
            || suffix.SectorIds.Length == 0
            || suffix.SectorIds[0] != downstreamSectorId
            || suffix.PortalIds == null
            || suffix.PortalIds.Length != suffix.SectorIds.Length - 1)
        {
            throw new InvalidOperationException(
                $"TryBuildPathHandleWithCommittedPortalPrefix failed: suffix is invalid portal={committedPortalId}, suffix={FormatPathHandle(suffix)}.");
        }
        if (suffix.PortalIds.Length > 0 && suffix.PortalIds[0] == committedPortalId)
            return false;

        int[] sectorIds = new int[suffix.SectorIds.Length + 1];
        sectorIds[0] = startSectorId;
        Array.Copy(suffix.SectorIds, 0, sectorIds, 1, suffix.SectorIds.Length);
        int[] portalIds = new int[suffix.PortalIds.Length + 1];
        portalIds[0] = committedPortalId;
        Array.Copy(suffix.PortalIds, 0, portalIds, 1, suffix.PortalIds.Length);
        handle = new PathHandle
        {
            HandleId = _nextPathHandleId++,
            WorldVersion = _world.Version,
            GoalX = goalX,
            GoalY = goalY,
            SectorIds = sectorIds,
            PortalIds = portalIds,
            CurrentSectorIndex = 0,
            BuildSource = "committedPortalPrefix",
            HasCommittedCurrentTileKey = true,
            CommittedCurrentTileKey = committedTileKey,
            CommittedCorridorGoalX = previousHandle.CommittedCorridorGoalX,
            CommittedCorridorGoalY = previousHandle.CommittedCorridorGoalY,
            CommittedCorridorSectorIds = previousHandle.CommittedCorridorSectorIds != null
                ? (int[])previousHandle.CommittedCorridorSectorIds.Clone()
                : null,
            CommittedCorridorPortalIds = previousHandle.CommittedCorridorPortalIds != null
                ? (int[])previousHandle.CommittedCorridorPortalIds.Clone()
                : null
        };
        return true;
    }

    private static string ResolvePathHandleRebuildReason(PathHandle handle, int startSectorId, int goalSectorId, int goalX, int goalY)
    {
        if (handle == null)
            return "noHandle";
        if (handle.WorldVersion != _world.Version)
            return "worldMismatch";
        if (handle.SectorIds == null || handle.SectorIds.Length == 0)
            return "invalid";
        if (PathReferencesMissingPortal(handle))
            return "invalid";
        if (FindSectorIndex(handle, startSectorId, 0) < 0)
            return "startSectorMismatch";
        if (handle.SectorIds[handle.SectorIds.Length - 1] != goalSectorId)
            return "goalSectorMismatch";
        if (!handle.MatchesGoal(goalX, goalY))
            return "goalCellMismatch";
        return "invalid";
    }

    private static bool ShouldRebuildPathHandleForCurrentStart(
        PathHandle handle,
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out string reason)
    {
        reason = string.Empty;
        if (handle == null
            || handle.PortalIds == null
            || handle.PortalIds.Length == 0
            || handle.SectorIds == null
            || handle.SectorIds.Length == 0)
        {
            return false;
        }

        int sectorIndex = FindSectorIndex(handle, startSectorId, Mathf.Max(0, handle.CurrentSectorIndex));
        if (sectorIndex < 0 || sectorIndex >= handle.PortalIds.Length)
            return false;

        int selectedPortalId = handle.PortalIds[sectorIndex];
        if (!TryResolveBestStartPortalForCurrentCell(
                startSectorId,
                goalSectorId,
                startX,
                startY,
                goalX,
                goalY,
                selectedPortalId,
                out int bestPortalId,
                out long selectedCost,
                out long bestCost))
        {
            return false;
        }

        if (selectedPortalId == bestPortalId || selectedCost <= bestCost)
            return false;

        reason =
            $"startPortalMismatch selected={selectedPortalId}:{FormatDiagnosticCost(DequantizeDeterministicPortalCost(selectedCost))} best={bestPortalId}:{FormatDiagnosticCost(DequantizeDeterministicPortalCost(bestCost))} sectorIndex={sectorIndex}";
        return true;
    }

    private static bool TryResolveBestStartPortalForCurrentCell(
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        int selectedPortalId,
        out int bestPortalId,
        out long selectedCost,
        out long bestCost)
    {
        bestPortalId = -1;
        selectedCost = long.MaxValue;
        bestCost = long.MaxValue;
        if (_world == null || startSectorId < 0 || startSectorId >= _world.Sectors.Length)
            return false;

        long checkStartTicks = Stopwatch.GetTimestamp();
        int sharedAgentTypeId = ResolvePreferredAgentTypeId(_world.AgentTypeId);
        SectorData startSector = _world.Sectors[startSectorId];
        SectorData goalSector = _world.Sectors[goalSectorId];
        StartPortalChoiceKey cacheKey = new StartPortalChoiceKey(
            _world.Version,
            startSectorId,
            _world.GetIndex(startX, startY),
            goalSectorId,
            _world.GetIndex(goalX, goalY),
            sharedAgentTypeId,
            selectedPortalId,
            startSector.DirtyVersion,
            goalSector.DirtyVersion);
        if (StartPortalChoiceCache.TryGetValue(cacheKey, out StartPortalChoiceEntry cachedChoice))
        {
            cachedChoice.LastUsedFrame = GetFrameCount();
            bestPortalId = cachedChoice.BestPortalId;
            selectedCost = cachedChoice.SelectedCost;
            bestCost = cachedChoice.BestCost;
            _perf.PathStartPortalCacheHits++;
            _perf.PathStartPortalCheckTicks += Stopwatch.GetTimestamp() - checkStartTicks;
            return bestPortalId >= 0;
        }

        _perf.PathStartPortalCacheMisses++;
        if (!TryGetCachedSharedGoalField(goalSectorId, goalX, goalY, sharedAgentTypeId, out SharedGoalField sharedField))
        {
            _perf.PathStartPortalCheckTicks += Stopwatch.GetTimestamp() - checkStartTicks;
            return false;
        }

        long selectedCostRaw = long.MaxValue;
        long bestCostRaw = long.MaxValue;
        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            _perf.PathStartPortalCandidates++;
            int portalId = startSector.PortalIds[i];
            int startNode = EncodePortalNode(startSectorId, portalId);
            if (!sharedField.SettledPortalNodes.Contains(startNode)
                || !sharedField.NodeCosts.TryGetValue(startNode, out long downstreamCost))
                continue;

            long accessCost = ResolveDeterministicPortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            if (accessCost == long.MaxValue)
                continue;

            if (!TryResolveFirstCrossingPortalFromSharedGoalField(sharedField, startNode, startSectorId, goalSectorId, out int firstCrossingPortalId))
                continue;

            long totalCost = AddDeterministicPortalCosts(
                accessCost,
                downstreamCost);
            if (firstCrossingPortalId == selectedPortalId && totalCost < selectedCostRaw)
                selectedCostRaw = totalCost;
            if (totalCost >= bestCostRaw)
                continue;

            bestCostRaw = totalCost;
            bestPortalId = firstCrossingPortalId;
        }

        selectedCost = selectedCostRaw;
        bestCost = bestCostRaw;

        _perf.PathStartPortalChecks++;
        StartPortalChoiceCache[cacheKey] = new StartPortalChoiceEntry
        {
            BestPortalId = bestPortalId,
            SelectedCost = selectedCost,
            BestCost = bestCost,
            LastUsedFrame = GetFrameCount()
        };
        TrimStartPortalChoiceCache();
        _perf.PathStartPortalCheckTicks += Stopwatch.GetTimestamp() - checkStartTicks;
        return bestPortalId >= 0;
    }

    private static void TrimStartPortalChoiceCache()
    {
        int limit = Mathf.Max(128, Config.FlowTileCacheLimit * 8);
        if (StartPortalChoiceCache.Count <= limit)
            return;

        StartPortalChoiceKey oldestKey = default;
        int oldestFrame = int.MaxValue;
        bool found = false;
        foreach (KeyValuePair<StartPortalChoiceKey, StartPortalChoiceEntry> pair in StartPortalChoiceCache)
        {
            int frame = pair.Value?.LastUsedFrame ?? int.MinValue;
            if (found)
            {
                int frameOrder = frame.CompareTo(oldestFrame);
                if (frameOrder > 0 || (frameOrder == 0 && CompareStartPortalChoiceKeys(pair.Key, oldestKey) >= 0))
                    continue;
            }

            oldestKey = pair.Key;
            oldestFrame = frame;
            found = true;
        }

        if (found)
            StartPortalChoiceCache.Remove(oldestKey);
    }

    private static int CompareStartPortalChoiceKeys(StartPortalChoiceKey left, StartPortalChoiceKey right)
    {
        int order = left.WorldVersion.CompareTo(right.WorldVersion);
        if (order != 0) return order;
        order = left.StartSectorId.CompareTo(right.StartSectorId);
        if (order != 0) return order;
        order = left.StartCellIndex.CompareTo(right.StartCellIndex);
        if (order != 0) return order;
        order = left.GoalSectorId.CompareTo(right.GoalSectorId);
        if (order != 0) return order;
        order = left.GoalCellIndex.CompareTo(right.GoalCellIndex);
        if (order != 0) return order;
        order = left.AgentTypeId.CompareTo(right.AgentTypeId);
        if (order != 0) return order;
        order = left.SelectedPortalId.CompareTo(right.SelectedPortalId);
        if (order != 0) return order;
        order = left.StartSectorDirtyVersion.CompareTo(right.StartSectorDirtyVersion);
        return order != 0 ? order : left.GoalSectorDirtyVersion.CompareTo(right.GoalSectorDirtyVersion);
    }

    private static bool TryResolveFirstCrossingPortalFromSharedGoalField(
        SharedGoalField sharedField,
        int startNode,
        int startSectorId,
        int goalSectorId,
        out int firstCrossingPortalId)
    {
        firstCrossingPortalId = -1;
        if (sharedField == null)
            return false;

        if (sharedField.FirstCrossingPortalByStartNode.TryGetValue(startNode, out FirstCrossingPortalCacheEntry cached))
        {
            _perf.PathFirstCrossingCacheHits++;
            firstCrossingPortalId = cached.PortalId;
            return cached.IsValid;
        }

        _perf.PathFirstCrossingCacheMisses++;
        long resolveStartTicks = Stopwatch.GetTimestamp();
        int cursor = startNode;
        int guard = 0;
        while (sharedField.NextNodeTowardGoal.TryGetValue(cursor, out int nextNode))
        {
            DecodePortalNode(cursor, out int fromSectorId, out int fromPortalId);
            DecodePortalNode(nextNode, out int toSectorId, out int toPortalId);
            if (fromPortalId == toPortalId && fromSectorId != toSectorId && firstCrossingPortalId < 0)
                firstCrossingPortalId = fromPortalId;

            cursor = nextNode;
            guard++;
            if (guard > _world.Sectors.Length + _world.PortalsById.Count)
                throw new InvalidOperationException("TryResolveFirstCrossingPortalFromSharedGoalField failed: reconstruction exceeded guard.");
        }

        int endSectorId = DecodePortalSector(cursor);
        bool isValid = firstCrossingPortalId >= 0 && endSectorId == goalSectorId;
        sharedField.FirstCrossingPortalByStartNode[startNode] = new FirstCrossingPortalCacheEntry(isValid, firstCrossingPortalId);
        _perf.PathFirstCrossingTicks += Stopwatch.GetTimestamp() - resolveStartTicks;
        return isValid;
    }

    private static string BuildPathHandleFailure(IEntityContext self, Vector3 stableGoalPosition, int startSectorId, int goalSectorId, int startX, int startY, int goalX, int goalY)
    {
        if (_world != null
            && _world.IslandIds != null
            && _world.IslandIds.Length == _world.Width * _world.Height
            && !AreCellsOnSameIsland(_world, startX, startY, goalX, goalY))
        {
            return BuildIslandMismatchFailure(self, stableGoalPosition, startX, startY, goalX, goalY);
        }

        SectorData startSector = _world.Sectors[startSectorId];
        SectorData goalSector = _world.Sectors[goalSectorId];
        int accessibleStartPortals = 0;
        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            int portalId = startSector.PortalIds[i];
            if (!float.IsPositiveInfinity(ResolvePortalAccessCost(startSector, startSectorId, portalId, startX, startY)))
                accessibleStartPortals++;
        }

        int accessibleGoalPortals = 0;
        for (int i = 0; i < goalSector.PortalIds.Count; i++)
        {
            int portalId = goalSector.PortalIds[i];
            if (!float.IsPositiveInfinity(ResolveGoalSectorPortalAccessCost(goalSector, goalSectorId, portalId, goalX, goalY)))
                accessibleGoalPortals++;
        }

        return $"path handle build failed selfPos={self.Position} stableGoal={stableGoalPosition} " +
               $"startCell=({startX},{startY}) startSector={startSectorId} startIsland={ResolveIslandIdForDiagnostics(_world, startX, startY)} " +
               $"startPortals={startSector.PortalIds.Count} accessibleStartPortals={accessibleStartPortals} " +
               $"goalCell=({goalX},{goalY}) goalSector={goalSectorId} goalIsland={ResolveIslandIdForDiagnostics(_world, goalX, goalY)} " +
               $"goalPortals={goalSector.PortalIds.Count} accessibleGoalPortals={accessibleGoalPortals} " +
               $"worldVersion={_world.Version} pendingRuntimeDirty={HasPendingRuntimeDirty(_activeWorldState)} " +
               $"boxObstacles={BoxObstacles.Count} circleObstacles={CircleObstacles.Count} " +
               $"gridPathDiag={BuildGridPathDiagnostics(self.Position, stableGoalPosition, _world.AgentTypeId)}";
    }

    private static int DecodePortalSector(int node)
    {
        DecodePortalNode(node, out int sectorId, out _);
        return sectorId;
    }

    private static bool TryGetCachedSharedGoalField(int goalSectorId, int goalX, int goalY, int agentTypeId, out SharedGoalField field)
    {
        SharedGoalFieldKey key = CreateSharedGoalFieldKey(goalSectorId, goalX, goalY, agentTypeId);
        if (SharedGoalFields.TryGetValue(key, out field)
            && !SharedGoalFieldReferencesMissingPortal(_world, field))
        {
            field.LastUsedFrame = GetFrameCount();
            return true;
        }

        field = null;
        return false;
    }

    private static SharedGoalFieldKey CreateSharedGoalFieldKey(int goalSectorId, int goalX, int goalY, int agentTypeId)
    {
        SectorData goalSector = _world.Sectors[goalSectorId];
        return new SharedGoalFieldKey(
            _world.Version,
            agentTypeId,
            goalSectorId,
            _world.GetIndex(goalX, goalY),
            goalSector.DirtyVersion);
    }

    private static void EnqueueSharedGoalFieldBuild(int goalSectorId, int goalX, int goalY, int agentTypeId)
    {
        SharedGoalFieldKey key = CreateSharedGoalFieldKey(goalSectorId, goalX, goalY, agentTypeId);
        EnqueueSharedGoalFieldBuild(key, prependToFront: false);
    }

