    private static bool TryHandleCachedSharedGoalFieldDemand(
        SharedGoalFieldKey key,
        bool prependToFront,
        int demandStartSectorId,
        int demandStartX,
        int demandStartY)
    {
        if (!SharedGoalFields.TryGetValue(key, out SharedGoalField field))
            return false;
        if (field == null)
            throw new InvalidOperationException($"Shared-goal cache contains a null field. key={key}.");

        int demandStartCellIndex = demandStartX >= 0
                                   && demandStartX < _world.Width
                                   && demandStartY >= 0
                                   && demandStartY < _world.Height
            ? _world.GetIndex(demandStartX, demandStartY)
            : -1;
        if (IsSharedGoalFieldDemandCovered(field, demandStartSectorId, demandStartCellIndex))
            return true;

        SharedGoalFieldBuildJob job = BeginCachedSharedGoalFieldExpansion(key, field);
        AddSharedGoalFieldBuildDemand(job, demandStartSectorId, demandStartX, demandStartY);
        EnqueueSharedGoalFieldExpansionJob(job, prependToFront);
        return true;
    }

    private static bool TryHandleCachedSharedGoalFieldDemand(
        SharedGoalFieldKey key,
        bool prependToFront,
        Dictionary<int, int> demandStartCells)
    {
        if (!SharedGoalFields.TryGetValue(key, out SharedGoalField field))
            return false;
        if (field == null)
            throw new InvalidOperationException($"Shared-goal cache contains a null field. key={key}.");
        if (demandStartCells == null || demandStartCells.Count == 0 || AreSharedGoalFieldDemandsCovered(field, demandStartCells))
            return true;

        SharedGoalFieldBuildJob job = BeginCachedSharedGoalFieldExpansion(key, field);
        AddSharedGoalFieldBuildDemand(job, demandStartCells);
        EnqueueSharedGoalFieldExpansionJob(job, prependToFront);
        return true;
    }

    private static bool TryHandleCachedSharedGoalFieldDemand(
        SharedGoalFieldKey key,
        bool prependToFront,
        HashSet<int> demandStartSectors)
    {
        if (!SharedGoalFields.TryGetValue(key, out SharedGoalField field))
            return false;
        if (field == null)
            throw new InvalidOperationException($"Shared-goal cache contains a null field. key={key}.");
        if (field.PortalOpenSet == null)
            throw new InvalidOperationException($"Shared-goal field is missing its continuation frontier. key={field.Key}.");
        if (field.PortalOpenSet.Count == 0
            || demandStartSectors != null && demandStartSectors.Count > 0 && AreSharedGoalFieldDemandsCovered(field, demandStartSectors))
            return true;

        SharedGoalFieldBuildJob job = BeginCachedSharedGoalFieldExpansion(key, field);
        AddSharedGoalFieldBuildDemand(job, demandStartSectors);
        EnqueueSharedGoalFieldExpansionJob(job, prependToFront);
        return true;
    }

    private static bool IsSharedGoalFieldDemandCovered(SharedGoalField field, int startSectorId, int startCellIndex)
    {
        return IsSharedGoalFieldDemandCovered(_world, field, startSectorId, startCellIndex);
    }

    private static bool IsSharedGoalFieldDemandCovered(
        NavigationWorld world,
        SharedGoalField field,
        int startSectorId,
        int startCellIndex)
    {
        if (world == null)
            throw new InvalidOperationException("Shared-goal demand coverage requires a navigation world.");
        if (field.PortalOpenSet == null)
            throw new InvalidOperationException($"Shared-goal field is missing its continuation frontier. key={field.Key}.");
        return startCellIndex >= 0
            ? IsSharedGoalFieldDemandStartCellCovered(world, field, startSectorId, startCellIndex)
            : IsSharedGoalFieldDemandStartSectorCovered(world, field, startSectorId);
    }

    private static bool IsSharedGoalFieldDemandStartSectorCovered(SharedGoalField field, int startSectorId)
    {
        return IsSharedGoalFieldDemandStartSectorCovered(_world, field, startSectorId);
    }

    private static bool IsSharedGoalFieldDemandStartSectorCovered(
        NavigationWorld world,
        SharedGoalField field,
        int startSectorId)
    {
        if (world == null)
            throw new InvalidOperationException("Shared-goal sector demand coverage requires a navigation world.");
        if (startSectorId < 0 || startSectorId >= world.Sectors.Length || field.SettledPortalNodes == null)
            return false;

        SectorData sector = world.Sectors[startSectorId];
        if (sector == null || sector.PortalIds == null || sector.PortalIds.Count == 0)
            return false;
        for (int i = 0; i < sector.PortalIds.Count; i++)
        {
            if (!field.SettledPortalNodes.Contains(EncodePortalNode(startSectorId, sector.PortalIds[i])))
                return false;
        }

        return true;
    }

    private static bool IsSharedGoalFieldDemandStartCellCovered(
        SharedGoalField field,
        int startSectorId,
        int startCellIndex)
    {
        return IsSharedGoalFieldDemandStartCellCovered(
            _world,
            field,
            startSectorId,
            startCellIndex);
    }

    private static bool IsSharedGoalFieldDemandStartCellCovered(
        NavigationWorld world,
        SharedGoalField field,
        int startSectorId,
        int startCellIndex)
    {
        if (world == null)
            throw new InvalidOperationException("Shared-goal cell demand coverage requires a navigation world.");
        if (startSectorId < 0
            || startSectorId >= world.Sectors.Length
            || startCellIndex < 0
            || startCellIndex >= world.Width * world.Height
            || field.SettledPortalNodes == null)
        {
            return false;
        }

        SectorData sector = world.Sectors[startSectorId];
        if (sector == null || sector.PortalIds == null || sector.PortalIds.Count == 0)
            return false;

        int startX = startCellIndex % world.Width;
        int startY = startCellIndex / world.Width;
        long bestSettledTotal = long.MaxValue;
        for (int i = 0; i < sector.PortalIds.Count; i++)
        {
            int portalId = sector.PortalIds[i];
            int node = EncodePortalNode(startSectorId, portalId);
            if (!field.SettledPortalNodes.Contains(node)
                || !field.NodeCosts.TryGetValue(node, out long nodeCost))
            {
                continue;
            }

            long accessCost = ResolveDeterministicPortalAccessCost(
                world,
                sector,
                startSectorId,
                portalId,
                startX,
                startY);
            if (accessCost == long.MaxValue)
                continue;

            bestSettledTotal = Math.Min(
                bestSettledTotal,
                AddDeterministicPortalCosts(accessCost, nodeCost));
        }

        return bestSettledTotal != long.MaxValue
               && bestSettledTotal <= field.PortalOpenSet.PeekCost;
    }

    private static bool AreSharedGoalFieldDemandsCovered(SharedGoalField field, Dictionary<int, int> demandStartCells)
    {
        foreach (KeyValuePair<int, int> demand in demandStartCells)
        {
            if (!IsSharedGoalFieldDemandCovered(field, demand.Value, demand.Key))
                return false;
        }

        return true;
    }

    private static bool AreSharedGoalFieldDemandsCovered(SharedGoalField field, HashSet<int> demandStartSectors)
    {
        foreach (int demandStartSectorId in demandStartSectors)
        {
            if (!IsSharedGoalFieldDemandCovered(field, demandStartSectorId, -1))
                return false;
        }

        return true;
    }

    private static SharedGoalFieldBuildJob BeginCachedSharedGoalFieldExpansion(SharedGoalFieldKey key, SharedGoalField field)
    {
        if (field.PortalOpenSet == null || field.SettledPortalNodes == null)
            throw new InvalidOperationException($"Shared-goal field cannot resume without frontier and settled state. key={key}.");
        if (field.PortalOpenSet.Count == 0)
            throw new InvalidOperationException($"Shared-goal field requested expansion after its frontier was exhausted. key={key}.");

        RemoveSharedGoalFieldCacheEntry(key);
        var job = new SharedGoalFieldBuildJob
        {
            Key = key,
            GoalSectorId = field.GoalSectorId,
            GoalX = field.GoalX,
            GoalY = field.GoalY,
            AgentTypeId = key.AgentTypeId,
            Stage = SharedGoalFieldBuildStage.PortalGraph,
            GoalSector = _world.Sectors[field.GoalSectorId],
            Field = field,
            PortalOpenSet = field.PortalOpenSet,
            SettledPortalNodes = field.SettledPortalNodes,
            SettledPortalAuthorityContentHash = field.SettledPortalAuthorityContentHash
        };

        AddSharedGoalFieldBuildDemand(job, field.CompletedDemandStartSectorIds);
        foreach (int cellIndex in field.CompletedDemandStartCellIndices)
        {
            int startX = cellIndex % _world.Width;
            int startY = cellIndex / _world.Width;
            if (!_world.TryGetSectorId(startX, startY, out int startSectorId))
                throw new InvalidOperationException($"Cached shared-goal demand cell is outside the active world. key={key} cell={cellIndex}.");
            AddSharedGoalFieldBuildDemand(job, startSectorId, startX, startY);
        }

        return job;
    }

    private static void EnqueueSharedGoalFieldExpansionJob(SharedGoalFieldBuildJob job, bool prependToFront)
    {
        if (!PendingSharedGoalFieldBuildJobs.Add(job.Key))
            throw new InvalidOperationException($"Shared-goal expansion attempted to enqueue a duplicate key. key={job.Key}.");
        _perf.PathPendingSharedGoal++;
        if (prependToFront)
            SharedGoalFieldBuildQueue.AddFirst(job);
        else
            SharedGoalFieldBuildQueue.AddLast(job);
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldKey key, HashSet<int> demandStartSectors)
    {
        if (demandStartSectors == null || demandStartSectors.Count == 0)
            return;

        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || !job.Key.Equals(key))
                continue;

            AddSharedGoalFieldBuildDemand(job, demandStartSectors);
            return;
        }
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldKey key, int demandStartSectorId)
    {
        if (demandStartSectorId < 0)
            return;

        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || !job.Key.Equals(key))
                continue;

            AddSharedGoalFieldBuildDemand(job, demandStartSectorId);
            return;
        }
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldKey key, int demandStartSectorId, int demandStartX, int demandStartY)
    {
        if (demandStartSectorId < 0)
            return;

        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || !job.Key.Equals(key))
                continue;

            AddSharedGoalFieldBuildDemand(job, demandStartSectorId, demandStartX, demandStartY);
            return;
        }
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldKey key, Dictionary<int, int> demandStartCells)
    {
        if (demandStartCells == null || demandStartCells.Count == 0)
            return;

        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || !job.Key.Equals(key))
                continue;

            AddSharedGoalFieldBuildDemand(job, demandStartCells);
            return;
        }
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldBuildJob job, HashSet<int> demandStartSectors)
    {
        if (job == null)
            throw new InvalidOperationException("AddSharedGoalFieldBuildDemand failed: job is null.");
        if (demandStartSectors == null || demandStartSectors.Count == 0)
            return;

        job.DemandStartSectorIds ??= new HashSet<int>();
        bool changed = false;
        foreach (int sectorId in demandStartSectors)
        {
            if (sectorId >= 0 && AddSharedGoalDemandStartSector(job, sectorId))
                changed = true;
        }
        if (changed)
            job.HasAuthorityProgressHash = false;
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldBuildJob job, int demandStartSectorId)
    {
        if (job == null)
            throw new InvalidOperationException("AddSharedGoalFieldBuildDemand failed: job is null.");
        if (demandStartSectorId < 0)
            return;

        job.DemandStartSectorIds ??= new HashSet<int>();
        if (AddSharedGoalDemandStartSector(job, demandStartSectorId))
            job.HasAuthorityProgressHash = false;
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldBuildJob job, int demandStartSectorId, int demandStartX, int demandStartY)
    {
        if (job == null)
            throw new InvalidOperationException("AddSharedGoalFieldBuildDemand failed: job is null.");
        if (demandStartSectorId < 0)
            return;

        job.DemandStartSectorIds ??= new HashSet<int>();
        bool changed = AddSharedGoalDemandStartSector(job, demandStartSectorId);
        if (demandStartX < 0
            || demandStartX >= _world.Width
            || demandStartY < 0
            || demandStartY >= _world.Height)
        {
            if (changed)
                job.HasAuthorityProgressHash = false;
            return;
        }

        job.DemandStartSectorByCellIndex ??= new Dictionary<int, int>();
        int cellIndex = _world.GetIndex(demandStartX, demandStartY);
        if (SetSharedGoalDemandStartCell(job, cellIndex, demandStartSectorId))
            changed = true;
        if (changed)
            job.HasAuthorityProgressHash = false;
    }

    private static void AddSharedGoalFieldBuildDemand(SharedGoalFieldBuildJob job, Dictionary<int, int> demandStartCells)
    {
        if (job == null)
            throw new InvalidOperationException("AddSharedGoalFieldBuildDemand failed: job is null.");
        if (demandStartCells == null || demandStartCells.Count == 0)
            return;

        job.DemandStartSectorByCellIndex ??= new Dictionary<int, int>();
        job.DemandStartSectorIds ??= new HashSet<int>();
        bool changed = false;
        foreach (KeyValuePair<int, int> pair in demandStartCells)
        {
            if (pair.Value < 0)
                continue;

            if (SetSharedGoalDemandStartCell(job, pair.Key, pair.Value))
                changed = true;
            if (AddSharedGoalDemandStartSector(job, pair.Value))
                changed = true;
        }
        if (changed)
            job.HasAuthorityProgressHash = false;
    }

    private static bool AddSharedGoalDemandStartSector(SharedGoalFieldBuildJob job, int sectorId)
    {
        if (job == null)
            throw new ArgumentNullException(nameof(job));
        if (job.DemandStartSectorIds == null)
            throw new InvalidOperationException("AddSharedGoalDemandStartSector failed: demand sector set is null.");
        if (!job.DemandStartSectorIds.Add(sectorId))
            return false;

        job.DemandStartSectorAuthorityContentHash ^= ComputeAuthorityIntToken(0x534744534543544FUL, sectorId);
        return true;
    }

    private static bool SetSharedGoalDemandStartCell(SharedGoalFieldBuildJob job, int cellIndex, int sectorId)
    {
        if (job == null)
            throw new ArgumentNullException(nameof(job));
        if (job.DemandStartSectorByCellIndex == null)
            throw new InvalidOperationException("SetSharedGoalDemandStartCell failed: demand cell map is null.");
        if (job.DemandStartSectorByCellIndex.TryGetValue(cellIndex, out int previousSectorId))
        {
            if (previousSectorId == sectorId)
                return false;
            job.DemandStartCellAuthorityContentHash ^= ComputeAuthorityIntIntToken(0x53474443454C4C4FUL, cellIndex, previousSectorId);
        }

        job.DemandStartSectorByCellIndex[cellIndex] = sectorId;
        job.DemandStartCellAuthorityContentHash ^= ComputeAuthorityIntIntToken(0x53474443454C4C4FUL, cellIndex, sectorId);
        return true;
    }

    private static void PromotePendingSharedGoalFieldBuildJobToFront(SharedGoalFieldKey key)
    {
        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || !job.Key.Equals(key))
                continue;

            SharedGoalFieldBuildQueue.Remove(node);
            SharedGoalFieldBuildQueue.AddFirst(job);
            return;
        }

        PendingSharedGoalFieldBuildJobs.Remove(key);
    }

    private static bool RemovePendingSharedGoalFieldBuildJob(SharedGoalFieldKey key)
    {
        for (LinkedListNode<SharedGoalFieldBuildJob> node = SharedGoalFieldBuildQueue.First; node != null; node = node.Next)
        {
            SharedGoalFieldBuildJob job = node.Value;
            if (job == null || !job.Key.Equals(key))
                continue;

            SharedGoalFieldBuildQueue.Remove(node);
            PendingSharedGoalFieldBuildJobs.Remove(key);
            return true;
        }

        PendingSharedGoalFieldBuildJobs.Remove(key);
        return false;
    }

    private static bool AdvanceSharedGoalFieldBuildJob(SharedGoalFieldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        if (job == null)
            throw new ArgumentNullException(nameof(job));

        job.HasAuthorityProgressHash = false;
        while (job.Stage != SharedGoalFieldBuildStage.Complete)
        {
            switch (job.Stage)
            {
                case SharedGoalFieldBuildStage.Initialize:
                    if (!InitializeSharedGoalFieldBuild(job))
                        return false;
                    break;
                case SharedGoalFieldBuildStage.PortalGraph:
                    if (!AdvanceSharedGoalFieldPortalGraph(job, deadlineTicks, forceComplete))
                        return false;
                    break;
                case SharedGoalFieldBuildStage.Commit:
                    if (!forceComplete && IsDeadlineExpired(deadlineTicks))
                        return false;
                    CommitSharedGoalFieldBuildJob(job);
                    break;
                default:
                    throw new InvalidOperationException($"AdvanceSharedGoalFieldBuildJob failed: unknown stage {job.Stage}.");
            }

            if (job.Stage == SharedGoalFieldBuildStage.Complete)
                break;

            if (!forceComplete && IsBudgetExpired(deadlineTicks, 0))
                return false;
        }

        return true;
    }

    private static bool InitializeSharedGoalFieldBuild(SharedGoalFieldBuildJob job)
    {
        job.GoalSector ??= _world.Sectors[job.GoalSectorId];
        job.Field = BeginSharedGoalField(job.Key, job.GoalSectorId, job.GoalX, job.GoalY, out job.PortalOpenSet);
        if (job.Field == null)
        {
            job.Stage = SharedGoalFieldBuildStage.Complete;
            return true;
        }

        job.SettledPortalNodes = job.Field.SettledPortalNodes;
        job.Stage = SharedGoalFieldBuildStage.PortalGraph;
        return true;
    }

    private static long QuantizeDeterministicPortalCost(float cost, string source)
    {
        if (float.IsNaN(cost) || float.IsNegativeInfinity(cost) || cost < 0f)
            throw new InvalidOperationException($"Deterministic portal cost is invalid. source={source} cost={cost}.");
        if (float.IsPositiveInfinity(cost))
            return long.MaxValue;

        double scaled = (double)cost * DeterministicPortalCostScale;
        if (scaled >= long.MaxValue)
            throw new OverflowException($"Deterministic portal cost overflow. source={source} cost={cost}.");
        return checked((long)Math.Round(scaled, MidpointRounding.AwayFromZero));
    }

    private static long AddDeterministicPortalCosts(long first, long second)
    {
        if (first == long.MaxValue || second == long.MaxValue)
            return long.MaxValue;
        return first > long.MaxValue - second ? long.MaxValue : first + second;
    }

    private static float DequantizeDeterministicPortalCost(long cost)
    {
        return cost == long.MaxValue ? float.PositiveInfinity : (float)((double)cost / DeterministicPortalCostScale);
    }

    private static bool AdvanceSharedGoalFieldPortalGraph(SharedGoalFieldBuildJob job, long deadlineTicks, bool forceComplete)
    {
        int budgetWork = 0;
        while (job.PortalOpenSet.Count > 0)
        {
            DeterministicCostQueueNode node = job.PortalOpenSet.Pop();
            int currentNode = node.Index;
            if (!job.Field.NodeCosts.TryGetValue(currentNode, out long currentCost) || node.Cost != currentCost)
                continue;

            job.SettledPortalNodes ??= new HashSet<int>();
            if (job.SettledPortalNodes.Add(currentNode))
            {
                job.SettledPortalAuthorityContentHash ^= ComputeAuthorityIntToken(0x5347534554544C45UL, currentNode);
                job.Field.SettledPortalAuthorityContentHash = job.SettledPortalAuthorityContentHash;
            }

            DecodePortalNode(currentNode, out int currentSectorId, out int currentPortalId);
            PortalData currentPortal = GetPortalById(_world, currentPortalId);
            int oppositeSectorId = GetOppositeSectorId(currentPortal, currentSectorId);
            int oppositeNode = EncodePortalNode(oppositeSectorId, currentPortalId);
            AddSharedGoalReverseEdge(
                job.Field,
                job.PortalOpenSet,
                oppositeNode,
                currentNode,
                AddDeterministicPortalCosts(
                    currentCost,
                    DeterministicPortalCrossingCost));

            SectorData sector = _world.Sectors[currentSectorId];
            List<PortalTransition> incomingTransitions = GetIncomingPortalTransitions(sector, currentPortalId);
            _perf.SharedGoalPortalGraphNodeExpansions++;
            if (incomingTransitions != null)
            {
                _perf.SharedGoalPortalGraphIncomingTransitionScans += incomingTransitions.Count;
                for (int i = 0; i < incomingTransitions.Count; i++)
                {
                    PortalTransition transition = incomingTransitions[i];
                    if (transition.ToPortalId != currentPortalId)
                    {
                        throw new InvalidOperationException(
                            $"AdvanceSharedGoalFieldPortalGraph failed: incoming index mismatch sector={currentSectorId} currentPortal={currentPortalId} from={transition.FromPortalId} to={transition.ToPortalId}.");
                    }

                    _perf.SharedGoalPortalGraphIncomingTransitionHits++;
                    int predecessorNode = EncodePortalNode(currentSectorId, transition.FromPortalId);
                    AddSharedGoalReverseEdge(
                        job.Field,
                        job.PortalOpenSet,
                        predecessorNode,
                        currentNode,
                        AddDeterministicPortalCosts(
                            currentCost,
                            transition.DeterministicCost));
                }
            }

            DiscardSettledOrOutdatedSharedGoalFrontierEntries(job);

            if (IsSharedGoalFieldDemandComplete(job))
            {
                FinalizeDemandLimitedSharedGoalField(job);
                job.Stage = SharedGoalFieldBuildStage.Commit;
                return true;
            }

            if (!forceComplete && IsBudgetExpired(deadlineTicks, ++budgetWork))
                return false;
        }

        FinalizeDemandLimitedSharedGoalField(job);
        job.Stage = SharedGoalFieldBuildStage.Commit;
        return true;
    }

    private static void DiscardSettledOrOutdatedSharedGoalFrontierEntries(SharedGoalFieldBuildJob job)
    {
        if (job == null || job.Field == null || job.PortalOpenSet == null || job.SettledPortalNodes == null)
            throw new InvalidOperationException("Shared-goal frontier normalization requires initialized job state.");

        while (job.PortalOpenSet.TryPeek(out DeterministicCostQueueNode node)
               && (job.SettledPortalNodes.Contains(node.Index)
                   || !job.Field.NodeCosts.TryGetValue(node.Index, out long currentCost)
                   || currentCost != node.Cost))
        {
            job.PortalOpenSet.Pop();
            job.HasAuthorityProgressHash = false;
        }
    }

    private static bool IsSharedGoalFieldDemandComplete(SharedGoalFieldBuildJob job)
    {
        if (job == null)
            throw new InvalidOperationException("IsSharedGoalFieldDemandComplete failed: job is null.");
        if (job.SettledPortalNodes == null || job.SettledPortalNodes.Count == 0)
            return false;
        if (job.DemandStartSectorByCellIndex != null && job.DemandStartSectorByCellIndex.Count > 0)
            return IsSharedGoalFieldDemandStartCellComplete(job);
        if (job.DemandStartSectorIds == null || job.DemandStartSectorIds.Count == 0)
            return false;

        bool hasValidDemandSector = false;
        foreach (int sectorId in job.DemandStartSectorIds)
        {
            if (sectorId < 0 || sectorId >= _world.Sectors.Length)
                continue;

            SectorData sector = _world.Sectors[sectorId];
            if (sector == null || sector.PortalIds == null || sector.PortalIds.Count == 0)
                continue;

            hasValidDemandSector = true;
            for (int i = 0; i < sector.PortalIds.Count; i++)
            {
                int node = EncodePortalNode(sectorId, sector.PortalIds[i]);
                if (!job.SettledPortalNodes.Contains(node))
                    return false;
            }
        }

        return hasValidDemandSector;
    }

    private static bool IsSharedGoalFieldDemandStartCellComplete(SharedGoalFieldBuildJob job)
    {
        bool hasValidDemandCell = false;
        foreach (KeyValuePair<int, int> pair in job.DemandStartSectorByCellIndex)
        {
            if (!IsSharedGoalFieldDemandStartCellCovered(job.Field, pair.Value, pair.Key))
                return false;
            hasValidDemandCell = true;
        }

        return hasValidDemandCell;
    }

    private static void FinalizeDemandLimitedSharedGoalField(SharedGoalFieldBuildJob job)
    {
        if (job == null)
            throw new InvalidOperationException("FinalizeDemandLimitedSharedGoalField failed: job is null.");
        if (job.Field == null || job.DemandStartSectorIds == null || job.DemandStartSectorIds.Count == 0)
            return;
        if (job.SettledPortalNodes == null || job.SettledPortalNodes.Count == 0)
            return;

        if (job.DemandStartSectorIds != null)
        {
            foreach (int sectorId in job.DemandStartSectorIds)
            {
                if (sectorId >= 0)
                    AddSharedGoalCompletedDemandStartSector(job.Field, sectorId);
            }
        }

        if (job.DemandStartSectorByCellIndex != null)
        {
            foreach (int cellIndex in job.DemandStartSectorByCellIndex.Keys)
                AddSharedGoalCompletedDemandStartCell(job.Field, cellIndex);
        }
    }

    private static void CommitSharedGoalFieldBuildJob(SharedGoalFieldBuildJob job)
    {
        if (job.Field != null)
        {
            job.Field.SettledPortalAuthorityContentHash = job.SettledPortalAuthorityContentHash;
            SetSharedGoalFieldCacheEntry(job.Key, job.Field);
            _perf.SharedGoalFieldBuilds++;
            TrimSharedGoalFields();
            if (IsNavigationDistancePrewarmSharedGoalKey(job.Key))
                s_NavigationDistancePrewarmCompletionMayHaveChanged = true;
        }

        job.Stage = SharedGoalFieldBuildStage.Complete;
    }

    private static SharedGoalField BeginSharedGoalField(SharedGoalFieldKey key, int goalSectorId, int goalX, int goalY, out DeterministicCostHeap openSet)
    {
        SectorData goalSector = _world.Sectors[goalSectorId];
        SharedGoalField field = new SharedGoalField
        {
            Key = key,
            GoalSectorId = goalSectorId,
            GoalX = goalX,
            GoalY = goalY,
            LastUsedFrame = GetFrameCount()
        };

        openSet = new DeterministicCostHeap();
        field.PortalOpenSet = openSet;
        field.SettledPortalNodes = new HashSet<int>();
        for (int i = 0; i < goalSector.PortalIds.Count; i++)
        {
            int portalId = goalSector.PortalIds[i];
            long deterministicGoalCost = ResolveDeterministicGoalSectorPortalAccessCost(
                goalSector,
                goalSectorId,
                portalId,
                goalX,
                goalY);
            if (deterministicGoalCost == long.MaxValue)
                continue;

            int goalNode = EncodePortalNode(goalSectorId, portalId);
            SetSharedGoalNodeCost(field, goalNode, deterministicGoalCost);
            openSet.Push(goalNode, deterministicGoalCost);
        }

        if (openSet.Count == 0)
            return null;

        return field;
    }

    private static void AddSharedGoalReverseEdge(SharedGoalField field, DeterministicCostHeap openSet, int predecessorNode, int nextNodeTowardGoal, long cost)
    {
        if (cost == long.MaxValue)
            return;
        if (field.NodeCosts.TryGetValue(predecessorNode, out long existingCost) && cost >= existingCost)
            return;

        SetSharedGoalNodeCost(field, predecessorNode, cost);
        SetSharedGoalNextNode(field, predecessorNode, nextNodeTowardGoal);
        openSet.Push(predecessorNode, cost);
    }

    private static void SetSharedGoalNodeCost(SharedGoalField field, int node, long cost)
    {
        if (field == null)
            throw new ArgumentNullException(nameof(field));
        if (field.NodeCosts.TryGetValue(node, out long previousCost))
            field.NodeCostsAuthorityContentHash ^= ComputeAuthorityIntLongToken(0x5347464E434F5354UL, node, previousCost);
        field.NodeCosts[node] = cost;
        field.NodeCostsAuthorityContentHash ^= ComputeAuthorityIntLongToken(0x5347464E434F5354UL, node, cost);
    }

    private static void RemoveSharedGoalNodeCost(SharedGoalField field, int node)
    {
        if (field == null)
            throw new ArgumentNullException(nameof(field));
        if (!field.NodeCosts.TryGetValue(node, out long cost))
            return;
        field.NodeCostsAuthorityContentHash ^= ComputeAuthorityIntLongToken(0x5347464E434F5354UL, node, cost);
        if (!field.NodeCosts.Remove(node))
            throw new InvalidOperationException($"RemoveSharedGoalNodeCost failed: node disappeared during removal node={node}.");
    }

    private static void SetSharedGoalNextNode(SharedGoalField field, int node, int nextNode)
    {
        if (field == null)
            throw new ArgumentNullException(nameof(field));
        if (field.NextNodeTowardGoal.TryGetValue(node, out int previousNextNode))
            field.NextNodeTowardGoalAuthorityContentHash ^= ComputeAuthorityIntIntToken(0x5347464E4558544EUL, node, previousNextNode);
        field.NextNodeTowardGoal[node] = nextNode;
        field.NextNodeTowardGoalAuthorityContentHash ^= ComputeAuthorityIntIntToken(0x5347464E4558544EUL, node, nextNode);
    }

    private static void RemoveSharedGoalNextNode(SharedGoalField field, int node)
    {
        if (field == null)
            throw new ArgumentNullException(nameof(field));
        if (!field.NextNodeTowardGoal.TryGetValue(node, out int nextNode))
            return;
        field.NextNodeTowardGoalAuthorityContentHash ^= ComputeAuthorityIntIntToken(0x5347464E4558544EUL, node, nextNode);
        if (!field.NextNodeTowardGoal.Remove(node))
            throw new InvalidOperationException($"RemoveSharedGoalNextNode failed: node disappeared during removal node={node}.");
    }

    private static void AddSharedGoalCompletedDemandStartSector(SharedGoalField field, int sectorId)
    {
        if (field == null)
            throw new ArgumentNullException(nameof(field));
        if (field.CompletedDemandStartSectorIds.Add(sectorId))
            field.CompletedDemandStartSectorAuthorityContentHash ^= ComputeAuthorityIntToken(0x534746434F4D5053UL, sectorId);
    }

    private static void AddSharedGoalCompletedDemandStartCell(SharedGoalField field, int cellIndex)
    {
        if (field == null)
            throw new ArgumentNullException(nameof(field));
        if (field.CompletedDemandStartCellIndices.Add(cellIndex))
            field.CompletedDemandStartCellAuthorityContentHash ^= ComputeAuthorityIntToken(0x534746434F4D5043UL, cellIndex);
    }

    private static void TrimSharedGoalFields()
    {
        int limit = Mathf.Max(16, Config.FlowTileCacheLimit / 4);
        while (SharedGoalFields.Count > limit)
        {
            SharedGoalFieldKey oldestKey = default;
            int oldestFrame = int.MaxValue;
            bool found = false;
            foreach (KeyValuePair<SharedGoalFieldKey, SharedGoalField> pair in SharedGoalFields)
            {
                if (IsNavigationDistancePrewarmSharedGoalKey(pair.Key))
                    continue;

                int frame = pair.Value?.LastUsedFrame ?? int.MinValue;
                if (found)
                {
                    int frameOrder = frame.CompareTo(oldestFrame);
                    if (frameOrder > 0 || (frameOrder == 0 && CompareSharedGoalKeys(pair.Key, oldestKey) >= 0))
                        continue;
                }

                oldestKey = pair.Key;
                oldestFrame = frame;
                found = true;
            }

            if (!found)
                return;

            RemoveSharedGoalFieldCacheEntry(oldestKey);
        }
    }

    private static void IncrementPathHandleRebuildReason(string reason)
    {
        switch (reason)
        {
            case "noHandle":
                _perf.PathBuildNoHandle++;
                break;
            case "worldMismatch":
                _perf.PathBuildWorldMismatch++;
                break;
            case "goalSectorMismatch":
                _perf.PathBuildGoalSectorMismatch++;
                break;
            case "goalCellMismatch":
                _perf.PathBuildGoalCellMismatch++;
                break;
            case "startSectorMismatch":
                _perf.PathBuildInvalidHandle++;
                break;
            case "startPortalMismatch":
                _perf.PathBuildInvalidHandle++;
                break;
            default:
                _perf.PathBuildInvalidHandle++;
                break;
        }
    }

    private static PathHandle BuildPathHandle(int startSectorId, int goalSectorId, int startX, int startY, int goalX, int goalY)
    {
        _perf.PathBuilds++;
        SectorData startSector = _world.Sectors[startSectorId];
        SectorData goalSector = _world.Sectors[goalSectorId];

        if (startSectorId == goalSectorId)
        {
            if (AreCellsConnectedInsideSector(startSector, startX, startY, goalX, goalY))
            {
                PathHandle sameSectorHandle = new PathHandle
                {
                    HandleId = _nextPathHandleId++,
                    WorldVersion = _world.Version,
                    GoalX = goalX,
                    GoalY = goalY,
                    SectorIds = new[] { startSectorId },
                    PortalIds = Array.Empty<int>(),
                    CurrentSectorIndex = 0,
                    BuildSource = "sameSector"
                };
                if (GameDebugSettings.IsEnabled(DebugCategory.Move)
                    && TryConsumeSuccessfulMoveDiagnosticBudget())
                {
                    GameDebugSettings.Log(DebugCategory.Move,
                        $"[FlowPathHandleBuild] result=ok sameSector=true startSector={startSectorId} goalSector={goalSectorId} " +
                        $"start=({startX},{startY}) goal=({goalX},{goalY}) handle={FormatPathHandle(sameSectorHandle)}");
                }

                return sameSectorHandle;
            }

            if (GameDebugSettings.IsEnabled(DebugCategory.Move))
            {
                GameDebugSettings.Log(DebugCategory.Move,
                    $"[FlowPathHandleBuild] sameSectorLocalBlocked=true startSector={startSectorId} goalSector={goalSectorId} " +
                    $"start=({startX},{startY}) goal=({goalX},{goalY}); trying portal route");
            }
        }

        SectorPathCacheKey sectorPathKey = CreateSectorPathCacheKey(startSectorId, startX, startY, goalSectorId, goalX, goalY);
        if (TryCreatePathHandleFromSectorPathCache(sectorPathKey, startSector, startSectorId, goalSectorId, startX, startY, goalX, goalY, out PathHandle cachedHandle))
            return cachedHandle;

        int sharedAgentTypeId = ResolvePreferredAgentTypeId(_world.AgentTypeId);
        if (TryGetCachedSharedGoalField(goalSectorId, goalX, goalY, sharedAgentTypeId, out SharedGoalField sharedField)
            && TryBuildPathHandleFromSharedGoalField(
                sectorPathKey,
                sharedField,
                startSector,
                startSectorId,
                goalSectorId,
                startX,
                startY,
                goalX,
                goalY,
                out PathHandle sharedHandle))
        {
            return sharedHandle;
        }

        _perf.SectorPathSearches++;
        if (TryBuildPathHandleWithPortalGraphAStar(
            sectorPathKey,
            startSector,
            goalSector,
            startSectorId,
            goalSectorId,
            startX,
            startY,
            goalX,
            goalY,
            out PathHandle graphHandle))
        {
            return graphHandle;
        }

        return null;
    }

    private static bool TryEstimateFlowPathDistanceFixed(
        NavigationWorld world,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out Fix64 distance)
    {
        distance = Fix64.Zero;
        if (world == null)
            throw new ArgumentNullException(nameof(world));
        if (!ReferenceEquals(world, _world))
            throw new InvalidOperationException("Flow path distance estimation requires the active committed navigation world.");
        if (!world.TryGetSectorId(startX, startY, out int startSectorId)
            || !world.TryGetSectorId(goalX, goalY, out int goalSectorId))
        {
            return false;
        }

        if (startSectorId == goalSectorId
            && TryFindSectorPathFixed(
                world,
                world.Sectors[startSectorId],
                startX,
                startY,
                goalX,
                goalY,
                out distance))
        {
            return true;
        }

        int sharedAgentTypeId = ResolvePreferredAgentTypeId(world.AgentTypeId);
        if (!TryGetCachedSharedGoalField(goalSectorId, goalX, goalY, sharedAgentTypeId, out SharedGoalField sharedField))
            return false;
        int startCellIndex = world.GetIndex(startX, startY);
        if (!IsSharedGoalFieldDemandCovered(sharedField, startSectorId, startCellIndex))
            return false;

        SectorData startSector = world.Sectors[startSectorId];
        long bestCost = long.MaxValue;
        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            int portalId = startSector.PortalIds[i];
            int startNode = EncodePortalNode(startSectorId, portalId);
            if (!sharedField.SettledPortalNodes.Contains(startNode)
                || !sharedField.NodeCosts.TryGetValue(startNode, out long downstreamCost))
                continue;
            long startCost = ResolveDeterministicPortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            bestCost = Math.Min(bestCost, AddDeterministicPortalCosts(startCost, downstreamCost));
        }

        if (bestCost == long.MaxValue)
            return false;
        distance = Fix64.FromRaw(bestCost) * world.CellSizeFixed;
        return distance > Fix64.Zero;
    }

    private static bool TryBuildPathHandleFromSharedGoalField(
        SectorPathCacheKey sectorPathKey,
        SharedGoalField sharedField,
        SectorData startSector,
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out PathHandle handle)
    {
        handle = null;
        if (sharedField == null)
            return false;
        int startCellIndex = _world.GetIndex(startX, startY);
        if (!IsSharedGoalFieldDemandCovered(sharedField, startSectorId, startCellIndex))
            return false;

        int bestStartNode = int.MinValue;
        long bestStartCost = long.MaxValue;
        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            int portalId = startSector.PortalIds[i];
            int startNode = EncodePortalNode(startSectorId, portalId);
            if (!sharedField.SettledPortalNodes.Contains(startNode)
                || !sharedField.NodeCosts.TryGetValue(startNode, out long downstreamCost))
                continue;

            long startCost = ResolveDeterministicPortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            if (startCost == long.MaxValue)
                continue;

            long totalCost = AddDeterministicPortalCosts(
                startCost,
                downstreamCost);
            if (totalCost >= bestStartCost)
                continue;

            bestStartCost = totalCost;
            bestStartNode = startNode;
        }

        if (bestStartNode == int.MinValue)
            return false;

        List<int> sectorIds = new List<int>(8) { startSectorId };
        List<int> portalIds = new List<int>(8);
        int cursor = bestStartNode;
        int guard = 0;
        while (sharedField.NextNodeTowardGoal.TryGetValue(cursor, out int nextNode))
        {
            DecodePortalNode(cursor, out int fromSectorId, out int fromPortalId);
            DecodePortalNode(nextNode, out int toSectorId, out int toPortalId);
            if (fromPortalId == toPortalId && fromSectorId != toSectorId)
            {
                portalIds.Add(fromPortalId);
                sectorIds.Add(toSectorId);
            }

            cursor = nextNode;
            guard++;
            if (guard > _world.Sectors.Length + _world.PortalsById.Count)
                throw new InvalidOperationException("BuildPathHandle failed: shared goal field path reconstruction exceeded guard.");
        }

        int endSectorId = DecodePortalSector(cursor);
        if (portalIds.Count == 0 || sectorIds[sectorIds.Count - 1] != goalSectorId)
        {
            if (GameDebugSettings.IsEnabled(DebugCategory.Move))
            {
                GameDebugSettings.Log(DebugCategory.Move,
                    $"[FlowPathHandleBuild] result=null source=sharedGoal startSector={startSectorId} goalSector={goalSectorId} " +
                    $"start=({startX},{startY}) goal=({goalX},{goalY}) bestStartNode={bestStartNode} bestStartCost={DequantizeDeterministicPortalCost(bestStartCost):F3} endSector={endSectorId} " +
                    $"sharedNodes={sharedField.NodeCosts.Count} sectorIdsPartial=[{string.Join(",", sectorIds)}] portalIdsPartial=[{string.Join(",", portalIds)}]");
            }
            return false;
        }

        handle = CreateAndCachePathHandle(sectorPathKey, sectorIds, portalIds, goalX, goalY);
        handle.BuildSource = "sharedGoal";
        if (GameDebugSettings.IsEnabled(DebugCategory.Move)
            && TryConsumeSuccessfulMoveDiagnosticBudget())
        {
            GameDebugSettings.Log(DebugCategory.Move,
                $"[FlowPathHandleBuild] result=ok source=sharedGoal startSector={startSectorId} goalSector={goalSectorId} " +
                $"start=({startX},{startY}) goal=({goalX},{goalY}) handle={FormatPathHandle(handle)}");
        }

        return true;
    }

    private static bool TryBuildPathHandleWithPortalGraphAStar(
        SectorPathCacheKey sectorPathKey,
        SectorData startSector,
        SectorData goalSector,
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out PathHandle handle)
    {
        handle = null;
        DeterministicCostHeap openSet = new DeterministicCostHeap();
        Dictionary<int, long> nodeCosts = new Dictionary<int, long>(256);
        Dictionary<int, int> cameFrom = new Dictionary<int, int>(256);
        Dictionary<int, int> startPortalByNode = new Dictionary<int, int>(64);
        HashSet<int> goalNodes = new HashSet<int>();
        Dictionary<int, long> goalAccessCosts = new Dictionary<int, long>(64);
        Dictionary<int, ExistingPathMergePoint> mergeNodes = BuildExistingPathMergeNodes(startSectorId, goalSectorId, goalX, goalY);

        for (int i = 0; i < goalSector.PortalIds.Count; i++)
        {
            int portalId = goalSector.PortalIds[i];
            long goalAccessCost = ResolveDeterministicGoalSectorPortalAccessCost(goalSector, goalSectorId, portalId, goalX, goalY);
            if (goalAccessCost == long.MaxValue)
                continue;

            int goalNode = EncodePortalNode(goalSectorId, portalId);
            goalNodes.Add(goalNode);
            goalAccessCosts[goalNode] = goalAccessCost;
        }

        if (goalNodes.Count == 0)
            return false;

        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            int portalId = startSector.PortalIds[i];
            long startCost = ResolveDeterministicPortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            if (startCost == long.MaxValue)
                continue;

            int startNode = EncodePortalNode(startSectorId, portalId);
            long startCostRaw = startCost;
            long priority = AddDeterministicPortalCosts(
                startCostRaw,
                ResolveDeterministicPortalGraphHeuristic(startNode, goalX, goalY));
            nodeCosts[startNode] = startCostRaw;
            startPortalByNode[startNode] = portalId;
            openSet.Push(startNode, priority);
        }

        int bestGoalNode = int.MinValue;
        long bestGoalCost = long.MaxValue;
        int bestMergeNode = int.MinValue;
        long bestMergeCost = long.MaxValue;
        ExistingPathMergePoint bestMergePoint = default;
        int guard = 0;
        while (openSet.Count > 0)
        {
            DeterministicCostQueueNode node = openSet.Pop();
            int currentNode = node.Index;
            if (!nodeCosts.TryGetValue(currentNode, out long currentCost))
                continue;
            if (node.Cost != AddDeterministicPortalCosts(
                    currentCost,
                    ResolveDeterministicPortalGraphHeuristic(currentNode, goalX, goalY)))
                continue;

            bool canFinishAtGoalNode = goalNodes.Contains(currentNode)
                                       && (startSectorId != goalSectorId || cameFrom.ContainsKey(currentNode));
            if (canFinishAtGoalNode)
            {
                long goalAccessCost = goalAccessCosts.TryGetValue(currentNode, out long foundGoalAccess)
                    ? foundGoalAccess
                    : 0L;
                long totalGoalCost = AddDeterministicPortalCosts(currentCost, goalAccessCost);
                if (totalGoalCost < bestGoalCost)
                {
                    bestGoalNode = currentNode;
                    bestGoalCost = totalGoalCost;
                }
            }

            if (mergeNodes.TryGetValue(currentNode, out ExistingPathMergePoint mergePoint)
                && TryResolveExistingPathSuffixCost(mergePoint, goalSectorId, goalX, goalY, out long suffixCost))
            {
                long totalMergeCost = AddDeterministicPortalCosts(currentCost, suffixCost);
                if (totalMergeCost <= bestMergeCost
                    && totalMergeCost <= bestGoalCost)
                {
                    bestMergeNode = currentNode;
                    bestMergeCost = totalMergeCost;
                    bestMergePoint = mergePoint;
                }
            }

            DecodePortalNode(currentNode, out int currentSectorId, out int currentPortalId);
            PortalData currentPortal = GetPortalById(_world, currentPortalId);
            int oppositeSectorId = GetOppositeSectorId(currentPortal, currentSectorId);
            int oppositeNode = EncodePortalNode(oppositeSectorId, currentPortalId);
            TryRelaxPortalGraphEdge(
                openSet,
                nodeCosts,
                cameFrom,
                currentNode,
                oppositeNode,
                AddDeterministicPortalCosts(
                    currentCost,
                    DeterministicPortalCrossingCost),
                goalX,
                goalY);

            SectorData sector = _world.Sectors[currentSectorId];
            List<PortalTransition> outgoingTransitions = GetOutgoingPortalTransitions(sector, currentPortalId);
            _perf.PathPortalGraphNodeExpansions++;
            if (outgoingTransitions != null)
            {
                _perf.PathPortalGraphOutgoingTransitionScans += outgoingTransitions.Count;
                for (int i = 0; i < outgoingTransitions.Count; i++)
                {
                    PortalTransition transition = outgoingTransitions[i];
                    if (transition.FromPortalId != currentPortalId)
                    {
                        throw new InvalidOperationException(
                            $"TryBuildPathHandleWithPortalGraphAStar failed: outgoing index mismatch sector={currentSectorId} currentPortal={currentPortalId} from={transition.FromPortalId} to={transition.ToPortalId}.");
                    }

                    _perf.PathPortalGraphOutgoingTransitionHits++;
                    int nextNode = EncodePortalNode(currentSectorId, transition.ToPortalId);
                    TryRelaxPortalGraphEdge(
                        openSet,
                        nodeCosts,
                        cameFrom,
                        currentNode,
                        nextNode,
                        AddDeterministicPortalCosts(
                            currentCost,
                            transition.DeterministicCost),
                        goalX,
                        goalY);
                }
            }

            long bestKnownFinishCost = Math.Min(bestGoalCost, bestMergeCost);
            if (openSet.PeekCost >= bestKnownFinishCost)
                break;

            guard++;
            if (guard > _world.Sectors.Length * Mathf.Max(1, _world.PortalsById.Count + 1))
                throw new InvalidOperationException("TryBuildPathHandleWithPortalGraphAStar failed: graph search exceeded guard.");
        }

        if (bestGoalNode == int.MinValue && bestMergeNode == int.MinValue)
            return false;

        bool useMergedPath = bestMergeNode != int.MinValue && bestMergeCost <= bestGoalCost;
        long finalCost = useMergedPath ? bestMergeCost : bestGoalCost;
        List<int> sectorIds;
        List<int> portalIds;
        int startPortalId;
        if (useMergedPath)
        {
            if (!TryConvertPortalNodesToMergedPath(bestMergeNode, cameFrom, bestMergePoint, startSectorId, goalSectorId, out sectorIds, out portalIds))
                return false;

            startPortalId = DecodePortalId(ResolveFirstPortalGraphNode(bestMergeNode, cameFrom));
        }
        else
        {
            List<int> reversedNodes = new List<int>(16);
            int cursor = bestGoalNode;
            reversedNodes.Add(cursor);
            guard = 0;
            while (cameFrom.TryGetValue(cursor, out int previousNode))
            {
                cursor = previousNode;
                reversedNodes.Add(cursor);
                guard++;
                if (guard > _world.Sectors.Length + _world.PortalsById.Count)
                    throw new InvalidOperationException("TryBuildPathHandleWithPortalGraphAStar failed: reconstruction exceeded guard.");
            }

            reversedNodes.Reverse();
            if (!TryConvertPortalNodesToPath(reversedNodes, startSectorId, goalSectorId, out sectorIds, out portalIds))
                return false;

            startPortalId = startPortalByNode.TryGetValue(reversedNodes[0], out int foundStartPortal) ? foundStartPortal : -1;
        }

        handle = CreateAndCachePathHandle(sectorPathKey, sectorIds, portalIds, goalX, goalY);
        handle.BuildSource = useMergedPath ? "portalGraphMerged" : "portalGraph";
        if (useMergedPath)
            _perf.PortalGraphMergeHits++;
        if (GameDebugSettings.IsEnabled(DebugCategory.Move)
            && TryConsumeSuccessfulMoveDiagnosticBudget())
        {
            long successDiagStartTicks = Stopwatch.GetTimestamp();
            GameDebugSettings.Log(DebugCategory.Move,
                $"[FlowPathHandleBuild] result=ok source={handle.BuildSource} startSector={startSectorId} goalSector={goalSectorId} " +
                $"start=({startX},{startY}) goal=({goalX},{goalY}) startPortal={startPortalId} cost={DequantizeDeterministicPortalCost(finalCost):F3} " +
                $"mergeNode={bestMergeNode} mergeCost={DequantizeDeterministicPortalCost(bestMergeCost):F3} goalCost={DequantizeDeterministicPortalCost(bestGoalCost):F3} handle={FormatPathHandle(handle)}");
            _perf.SuccessfulMoveDiagnosticTicks += Stopwatch.GetTimestamp() - successDiagStartTicks;
        }

        return true;
    }

    private readonly struct ExistingPathMergePoint
    {
        public readonly int[] SectorIds;
        public readonly int[] PortalIds;
        public readonly int SectorIndex;

        public ExistingPathMergePoint(int[] sectorIds, int[] portalIds, int sectorIndex)
        {
            SectorIds = sectorIds;
            PortalIds = portalIds;
            SectorIndex = sectorIndex;
        }
    }

    private static Dictionary<int, ExistingPathMergePoint> BuildExistingPathMergeNodes(int startSectorId, int goalSectorId, int goalX, int goalY)
    {
        Dictionary<int, ExistingPathMergePoint> mergeNodes = null;
        for (int agentIndex = 0; agentIndex < OrderedAgentIds.Count; agentIndex++)
        {
            AgentRuntimeData agent = Agents[OrderedAgentIds[agentIndex]]
                ?? throw new InvalidOperationException($"BuildExistingPathMergeNodes failed: agent is null id={OrderedAgentIds[agentIndex]}.");
            PathHandle handle = agent.NavState.PathHandle;
            if (handle == null
                || handle.WorldVersion != _world.Version
                || handle.SectorIds == null
                || handle.PortalIds == null
                || handle.SectorIds.Length <= 1
                || handle.SectorIds[handle.SectorIds.Length - 1] != goalSectorId
                || handle.GoalX != goalX
                || handle.GoalY != goalY
                || PathReferencesMissingPortal(handle))
            {
                continue;
            }

            for (int i = Mathf.Max(0, handle.CurrentSectorIndex); i < handle.PortalIds.Length; i++)
            {
                int sectorId = handle.SectorIds[i];
                if (sectorId == startSectorId)
                    continue;

                int node = EncodePortalNode(sectorId, handle.PortalIds[i]);
                mergeNodes ??= new Dictionary<int, ExistingPathMergePoint>(32);
                if (!mergeNodes.ContainsKey(node))
                {
                    mergeNodes[node] = new ExistingPathMergePoint(
                        (int[])handle.SectorIds.Clone(),
                        (int[])handle.PortalIds.Clone(),
                        i);
                }
            }
        }

        return mergeNodes ?? EmptyMergeNodes;
    }

    private static readonly Dictionary<int, ExistingPathMergePoint> EmptyMergeNodes = new Dictionary<int, ExistingPathMergePoint>(0);

    private static bool TryResolveExistingPathSuffixCost(ExistingPathMergePoint mergePoint, int goalSectorId, int goalX, int goalY, out long cost)
    {
        cost = 0L;
        if (mergePoint.SectorIds == null
            || mergePoint.PortalIds == null
            || mergePoint.SectorIndex < 0
            || mergePoint.SectorIndex >= mergePoint.PortalIds.Length
            || mergePoint.PortalIds.Length + 1 != mergePoint.SectorIds.Length)
        {
            return false;
        }

        for (int i = mergePoint.SectorIndex; i < mergePoint.PortalIds.Length; i++)
        {
            int fromSectorId = mergePoint.SectorIds[i];
            int portalId = mergePoint.PortalIds[i];
            PortalData portal = GetPortalById(_world, portalId);
            if (!PortalTouchesSector(portal, fromSectorId))
                return false;

            cost = AddDeterministicPortalCosts(
                cost,
                DeterministicPortalCrossingCost);
            int nextSectorId = mergePoint.SectorIds[i + 1];
            if (GetOppositeSectorId(portal, fromSectorId) != nextSectorId)
                return false;

            if (i + 1 < mergePoint.PortalIds.Length)
            {
                long transitionCost = ResolveDeterministicPortalTransitionCost(nextSectorId, portalId, mergePoint.PortalIds[i + 1]);
                if (transitionCost == long.MaxValue)
                    return false;

                cost = AddDeterministicPortalCosts(
                    cost,
                    transitionCost);
            }
            else
            {
                if (nextSectorId != goalSectorId)
                    return false;

                long goalAccessCost = ResolveDeterministicGoalSectorPortalAccessCost(_world.Sectors[goalSectorId], goalSectorId, portalId, goalX, goalY);
                if (goalAccessCost == long.MaxValue)
                    return false;

                cost = AddDeterministicPortalCosts(
                    cost,
                    goalAccessCost);
            }
        }

        return true;
    }

    private static bool PortalTouchesSector(PortalData portal, int sectorId)
    {
        return portal.SectorAId == sectorId || portal.SectorBId == sectorId;
    }

    private static float ResolvePortalTransitionCost(int sectorId, int fromPortalId, int toPortalId)
    {
        return DequantizeDeterministicPortalCost(
            ResolveDeterministicPortalTransitionCost(sectorId, fromPortalId, toPortalId));
    }

    private static long ResolveDeterministicPortalTransitionCost(int sectorId, int fromPortalId, int toPortalId)
    {
        SectorData sector = _world.Sectors[sectorId];
        List<PortalTransition> outgoingTransitions = GetOutgoingPortalTransitions(sector, fromPortalId);
        if (outgoingTransitions == null)
            return long.MaxValue;

        for (int i = 0; i < outgoingTransitions.Count; i++)
        {
            PortalTransition transition = outgoingTransitions[i];
            if (transition.FromPortalId != fromPortalId)
            {
                throw new InvalidOperationException(
                    $"ResolvePortalTransitionCost failed: outgoing index mismatch sector={sectorId} fromPortal={fromPortalId} transitionFrom={transition.FromPortalId} to={transition.ToPortalId}.");
            }

            if (transition.ToPortalId == toPortalId)
                return transition.DeterministicCost;
        }

        return long.MaxValue;
    }

    private static int ResolveFirstPortalGraphNode(int node, Dictionary<int, int> cameFrom)
    {
        int cursor = node;
        int guard = 0;
        while (cameFrom.TryGetValue(cursor, out int previousNode))
        {
            cursor = previousNode;
            guard++;
            if (guard > _world.Sectors.Length + _world.PortalsById.Count)
                throw new InvalidOperationException("ResolveFirstPortalGraphNode failed: reconstruction exceeded guard.");
        }

        return cursor;
    }

    private static int DecodePortalId(int node)
    {
        DecodePortalNode(node, out _, out int portalId);
        return portalId;
    }

    private static bool TryConvertPortalNodesToMergedPath(
        int mergeNode,
        Dictionary<int, int> cameFrom,
        ExistingPathMergePoint mergePoint,
        int startSectorId,
        int goalSectorId,
        out List<int> sectorIds,
        out List<int> portalIds)
    {
        sectorIds = null;
        portalIds = null;
        List<int> prefixNodes = new List<int>(16);
        int cursor = mergeNode;
        prefixNodes.Add(cursor);
        int guard = 0;
        while (cameFrom.TryGetValue(cursor, out int previousNode))
        {
            cursor = previousNode;
            prefixNodes.Add(cursor);
            guard++;
            if (guard > _world.Sectors.Length + _world.PortalsById.Count)
                throw new InvalidOperationException("TryConvertPortalNodesToMergedPath failed: prefix reconstruction exceeded guard.");
        }

        prefixNodes.Reverse();
        if (!TryConvertPortalNodesToPathPrefix(prefixNodes, startSectorId, out sectorIds, out portalIds))
            return false;

        int mergeSector = mergePoint.SectorIds[mergePoint.SectorIndex];
        if (sectorIds[sectorIds.Count - 1] != mergeSector)
            return false;

        for (int i = mergePoint.SectorIndex; i < mergePoint.PortalIds.Length; i++)
        {
            portalIds.Add(mergePoint.PortalIds[i]);
            sectorIds.Add(mergePoint.SectorIds[i + 1]);
        }

        return portalIds.Count > 0 && sectorIds[sectorIds.Count - 1] == goalSectorId;
    }

    private static bool TryConvertPortalNodesToPathPrefix(List<int> nodes, int startSectorId, out List<int> sectorIds, out List<int> portalIds)
    {
        sectorIds = new List<int>(8) { startSectorId };
        portalIds = new List<int>(8);
        if (nodes == null || nodes.Count == 0)
            return false;

        for (int i = 0; i < nodes.Count - 1; i++)
        {
            DecodePortalNode(nodes[i], out int fromSectorId, out int fromPortalId);
            DecodePortalNode(nodes[i + 1], out int toSectorId, out int toPortalId);
            if (fromPortalId == toPortalId && fromSectorId != toSectorId)
            {
                portalIds.Add(fromPortalId);
                sectorIds.Add(toSectorId);
            }
        }

        return sectorIds.Count > 0;
    }

    private static void TryRelaxPortalGraphEdge(
        DeterministicCostHeap openSet,
        Dictionary<int, long> nodeCosts,
        Dictionary<int, int> cameFrom,
        int fromNode,
        int toNode,
        long newCost,
        int goalX,
        int goalY)
    {
        if (newCost == long.MaxValue)
            return;
        if (nodeCosts.TryGetValue(toNode, out long existingCost) && newCost >= existingCost)
            return;

        nodeCosts[toNode] = newCost;
        cameFrom[toNode] = fromNode;
        long priority = AddDeterministicPortalCosts(
            newCost,
            ResolveDeterministicPortalGraphHeuristic(toNode, goalX, goalY));
        openSet.Push(toNode, priority);
    }

    private static long ResolveDeterministicPortalGraphHeuristic(int node, int goalX, int goalY)
    {
        DecodePortalNode(node, out int sectorId, out int portalId);
        PortalData portal = GetPortalById(_world, portalId);
        Vector2Int[] portalCells = GetPortalCellsForSector(portal, sectorId);
        if (portalCells == null || portalCells.Length == 0)
            throw new InvalidOperationException($"ResolveDeterministicPortalGraphHeuristic failed: portal has no cells. node={node} sector={sectorId} portal={portalId}.");

        int minimumCellDistance = int.MaxValue;
        for (int i = 0; i < portalCells.Length; i++)
        {
            int dx = Math.Abs(portalCells[i].x - goalX);
            int dy = Math.Abs(portalCells[i].y - goalY);
            minimumCellDistance = Math.Min(minimumCellDistance, Math.Max(dx, dy));
        }
        return checked((long)minimumCellDistance * DeterministicPortalCostScale);
    }

    private static bool TryConvertPortalNodesToPath(List<int> nodes, int startSectorId, int goalSectorId, out List<int> sectorIds, out List<int> portalIds)
    {
        sectorIds = new List<int>(8) { startSectorId };
        portalIds = new List<int>(8);
        if (nodes == null || nodes.Count == 0)
            return false;

        for (int i = 0; i < nodes.Count - 1; i++)
        {
            DecodePortalNode(nodes[i], out int fromSectorId, out int fromPortalId);
            DecodePortalNode(nodes[i + 1], out int toSectorId, out int toPortalId);
            if (fromPortalId == toPortalId && fromSectorId != toSectorId)
            {
                portalIds.Add(fromPortalId);
                sectorIds.Add(toSectorId);
            }
        }

        return portalIds.Count > 0 && sectorIds[sectorIds.Count - 1] == goalSectorId;
    }

    private static PathHandle CreateAndCachePathHandle(SectorPathCacheKey sectorPathKey, List<int> sectorIds, List<int> portalIds, int goalX, int goalY)
    {
        if (sectorIds == null || sectorIds.Count == 0 || portalIds == null)
            throw new InvalidOperationException("CreateAndCachePathHandle failed: invalid path lists.");

        PathHandle handle = new PathHandle
        {
            HandleId = _nextPathHandleId++,
            WorldVersion = _world.Version,
            GoalX = goalX,
            GoalY = goalY,
            SectorIds = sectorIds.ToArray(),
            PortalIds = portalIds.ToArray(),
            CurrentSectorIndex = 0,
            BuildSource = "created"
        };
        SetSectorPathCacheEntry(sectorPathKey, new SectorPathCacheEntry
        {
            SectorIds = (int[])handle.SectorIds.Clone(),
            PortalIds = (int[])handle.PortalIds.Clone(),
            LastUsedFrame = GetFrameCount()
        });
        TrimSectorPathCache();
        return handle;
    }

    private static void TrimSectorPathCache()
    {
        int limit = Mathf.Max(32, Config.FlowTileCacheLimit * 2);
        if (SectorPathCache.Count <= limit)
            return;

        SectorPathCacheKey oldestKey = default;
        int oldestFrame = int.MaxValue;
        bool found = false;
        foreach (KeyValuePair<SectorPathCacheKey, SectorPathCacheEntry> pair in SectorPathCache)
        {
            int frame = pair.Value?.LastUsedFrame ?? int.MinValue;
            if (found)
            {
                int frameOrder = frame.CompareTo(oldestFrame);
                if (frameOrder > 0 || (frameOrder == 0 && CompareSectorPathKeys(pair.Key, oldestKey) >= 0))
                    continue;
            }

            oldestKey = pair.Key;
            oldestFrame = frame;
            found = true;
        }

        if (found)
            RemoveSectorPathCacheEntry(oldestKey);
    }

    private static SectorPathCacheKey CreateSectorPathCacheKey(int startSectorId, int startX, int startY, int goalSectorId, int goalX, int goalY)
    {
        SectorData startSector = _world.Sectors[startSectorId];
        SectorData goalSector = _world.Sectors[goalSectorId];
        return new SectorPathCacheKey(
            _world.Version,
            startSectorId,
            _world.GetIndex(startX, startY),
            goalSectorId,
            _world.GetIndex(goalX, goalY),
            startSector.DirtyVersion,
            goalSector.DirtyVersion);
    }

    private static bool TryCreatePathHandleFromSectorPathCache(
        SectorPathCacheKey key,
        SectorData startSector,
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out PathHandle handle)
    {
        handle = null;
        if (!SectorPathCache.TryGetValue(key, out SectorPathCacheEntry cached)
            || cached.SectorIds == null
            || cached.PortalIds == null
            || cached.SectorIds.Length == 0
            || cached.PortalIds.Length == 0)
        {
            return false;
        }

        if (cached.SectorIds[0] != startSectorId || cached.SectorIds[cached.SectorIds.Length - 1] != goalSectorId)
        {
            RemoveSectorPathCacheEntry(key);
            return false;
        }

        int firstPortalId = cached.PortalIds[0];
        long startCost = ResolveDeterministicPortalAccessCost(startSector, startSectorId, firstPortalId, startX, startY);
        if (startCost == long.MaxValue)
            return false;

        if (TryResolveBestStartPortalForCurrentCell(
                startSectorId,
                goalSectorId,
                startX,
                startY,
                goalX,
                goalY,
                firstPortalId,
                out int bestPortalId,
                out long selectedCost,
                out long bestCost)
            && firstPortalId != bestPortalId
            && selectedCost > bestCost)
        {
            RemoveSectorPathCacheEntry(key);
            if (GameDebugSettings.IsEnabled(DebugCategory.Move))
            {
                GameDebugSettings.Log(DebugCategory.Move,
                    $"[FlowPathCacheReject] reason=startPortalMismatch startSector={startSectorId} goalSector={goalSectorId} " +
                    $"start=({startX},{startY}) goal=({goalX},{goalY}) selected={firstPortalId}:{FormatDiagnosticCost(DequantizeDeterministicPortalCost(selectedCost))} " +
                    $"best={bestPortalId}:{FormatDiagnosticCost(DequantizeDeterministicPortalCost(bestCost))}");
            }

            return false;
        }

        cached.LastUsedFrame = GetFrameCount();
        _perf.SectorPathCacheHits++;
        handle = new PathHandle
        {
            HandleId = _nextPathHandleId++,
            WorldVersion = _world.Version,
            GoalX = goalX,
            GoalY = goalY,
            SectorIds = (int[])cached.SectorIds.Clone(),
            PortalIds = (int[])cached.PortalIds.Clone(),
            CurrentSectorIndex = 0,
            BuildSource = "sectorPathCache"
        };

        if (GameDebugSettings.IsEnabled(DebugCategory.Move))
        {
            GameDebugSettings.Log(DebugCategory.Move,
                $"[FlowPathCacheHit] startSector={startSectorId} goalSector={goalSectorId} start=({startX},{startY}) goal=({goalX},{goalY}) handle={FormatPathHandle(handle)}");
        }

        return true;
    }

    private static bool TryAdvancePathToCurrentSector(AgentRuntimeData agent, int currentSectorId)
    {
        PathHandle handle = agent.NavState.PathHandle;
        if (handle == null || handle.SectorIds == null || handle.SectorIds.Length == 0)
            return false;

        int startIndex = Mathf.Clamp(handle.CurrentSectorIndex, 0, handle.SectorIds.Length - 1);
        for (int i = startIndex; i < handle.SectorIds.Length; i++)
        {
            if (handle.SectorIds[i] != currentSectorId)
                continue;

            handle.CurrentSectorIndex = i;
            return true;
        }

        for (int i = startIndex - 1; i >= 0; i--)
        {
            if (handle.SectorIds[i] != currentSectorId)
                continue;

            handle.CurrentSectorIndex = i;
            return true;
        }

        return false;
    }

    private static int ResolveCurrentDownstreamPortalId(PathHandle handle)
    {
        if (handle == null || handle.PortalIds == null || handle.SectorIds == null)
            return -1;

        int index = Mathf.Clamp(handle.CurrentSectorIndex, 0, Mathf.Max(0, handle.SectorIds.Length - 1));
        return index >= 0 && index < handle.PortalIds.Length ? handle.PortalIds[index] : -1;
    }

    private static bool TryDecodeExactFinalGoalIndex(int finalGoalIndex, out int finalGoalX, out int finalGoalY)
    {
        finalGoalX = -1;
        finalGoalY = -1;
        if (_world == null || finalGoalIndex < 0)
            return false;

        finalGoalX = finalGoalIndex % _world.Width;
        finalGoalY = finalGoalIndex / _world.Width;
        return finalGoalX >= 0 && finalGoalX < _world.Width && finalGoalY >= 0 && finalGoalY < _world.Height;
    }

    private static void LogPathAdvanceFailure(
        AgentRuntimeData agent,
        int currentSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY)
    {
        PathHandle handle = agent?.NavState.PathHandle;
        int firstIndex = FindSectorIndex(handle, currentSectorId, 0);
        int forwardIndex = handle != null ? FindSectorIndex(handle, currentSectorId, Mathf.Max(0, handle.CurrentSectorIndex)) : -1;
        int currentIndexSector = handle != null
                                 && handle.SectorIds != null
                                 && handle.CurrentSectorIndex >= 0
                                 && handle.CurrentSectorIndex < handle.SectorIds.Length
            ? handle.SectorIds[handle.CurrentSectorIndex]
            : -1;

        LogNoStacktrace(
            $"[FlowPathAdvanceFail] agent={agent?.CharacterKey ?? "null"} currentSector={currentSectorId} goalSector={goalSectorId} " +
            $"start=({startX},{startY}) goal=({goalX},{goalY}) currentIndexSector={currentIndexSector} " +
            $"firstIndex={firstIndex} forwardIndex={forwardIndex} handle={FormatPathHandle(handle)}");
    }

    private static int FindSectorIndex(PathHandle handle, int sectorId, int startIndex)
    {
        if (handle == null || handle.SectorIds == null)
            return -1;

        for (int i = Mathf.Max(0, startIndex); i < handle.SectorIds.Length; i++)
        {
            if (handle.SectorIds[i] == sectorId)
                return i;
        }

        return -1;
    }

    private static bool TryBuildOrGetTile(
        AgentRuntimeData agent,
        int goalX,
        int goalY,
        out FlowTileCacheEntry tile,
        out TileGoalKind goalKind,
        out int downstreamPortalId)
    {
        tile = null;
        goalKind = TileGoalKind.FinalGoal;
        downstreamPortalId = -1;

        PathHandle handle = agent.NavState.PathHandle;
        if (handle == null)
            return false;

        int sectorPathIndex = handle.CurrentSectorIndex;
        int sectorId = handle.SectorIds[sectorPathIndex];
        FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(handle, sectorPathIndex, goalX, goalY, agent.AgentTypeId, out goalKind, out downstreamPortalId);
        if (FlowTileCache.TryGetValue(key, out tile))
        {
            _perf.TileCacheHits++;
            tile.LastUsedFrame = GetFrameCount();
            return true;
        }

        _perf.TileCacheMisses++;
        EnqueueActiveFlowTileBuilds(handle, sectorPathIndex, goalX, goalY, agent.AgentTypeId);
        if (FlowTileCache.TryGetValue(key, out tile))
        {
            _perf.TileCacheHits++;
            tile.LastUsedFrame = GetFrameCount();
            return true;
        }

        _perf.TilePendingBuild++;
        return false;
    }

    private static bool TryBuildOrGetTileWithStrictRepath(
        AgentRuntimeData agent,
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out FlowTileCacheEntry tile,
        out TileGoalKind goalKind,
        out int downstreamPortalId,
        out string failureReason)
    {
        tile = null;
        goalKind = TileGoalKind.FinalGoal;
        downstreamPortalId = -1;
        failureReason = $"tile build failed sector={startSectorId} goal=({goalX},{goalY})";

        try
        {
            bool builtOrCached = TryBuildOrGetTile(agent, goalX, goalY, out tile, out goalKind, out downstreamPortalId);
            if (!builtOrCached && IsCurrentPathSegmentPendingPortal(agent, out int pendingPortalId))
            {
                goalKind = TileGoalKind.Portal;
                downstreamPortalId = pendingPortalId;
                return true;
            }
            if (!builtOrCached && goalKind == TileGoalKind.FinalGoal)
            {
                downstreamPortalId = -1;
                return true;
            }
            if (!builtOrCached)
                failureReason = BuildTileBuildPendingFailure(agent, startSectorId, goalSectorId, goalX, goalY);
            return builtOrCached;
        }
        catch (StrictPortalWindowUnreachableException firstException)
        {
            if (GameDebugSettings.IsEnabled(DebugCategory.Move))
            {
                GameDebugSettings.Log(DebugCategory.Move,
                    $"[FlowStrictRepath] agent={agent.CharacterKey} stage=begin startSector={startSectorId} goalSector={goalSectorId} " +
                    $"start=({startX},{startY}) goal=({goalX},{goalY}) oldHandle={FormatPathHandle(agent.NavState.PathHandle)} " +
                    $"reason={firstException.Message}");
            }

            agent.NavState.PathHandle = null;
            if (!EnsurePathHandle(agent, startSectorId, goalSectorId, startX, startY, goalX, goalY))
            {
                failureReason =
                    $"strict repath failed after unreachable portal window startSector={startSectorId} goalSector={goalSectorId} " +
                    $"start=({startX},{startY}) goal=({goalX},{goalY}) root={firstException.Message}";
                return false;
            }

            try
            {
                bool recovered = TryBuildOrGetTile(agent, goalX, goalY, out tile, out goalKind, out downstreamPortalId);
                if (recovered && GameDebugSettings.IsEnabled(DebugCategory.Move))
                {
                    GameDebugSettings.Log(DebugCategory.Move,
                        $"[FlowStrictRepath] agent={agent.CharacterKey} stage=recovered startSector={startSectorId} goalSector={goalSectorId} " +
                        $"start=({startX},{startY}) goal=({goalX},{goalY}) newHandle={FormatPathHandle(agent.NavState.PathHandle)}");
                }

                if (!recovered)
                {
                    if (IsCurrentPathSegmentPendingPortal(agent, out int pendingPortalId))
                    {
                        goalKind = TileGoalKind.Portal;
                        downstreamPortalId = pendingPortalId;
                        return true;
                    }
                    if (goalKind == TileGoalKind.FinalGoal)
                    {
                        downstreamPortalId = -1;
                        return true;
                    }
                    failureReason = $"tile build failed after strict repath sector={startSectorId} goal=({goalX},{goalY}); {BuildTileBuildPendingFailure(agent, startSectorId, goalSectorId, goalX, goalY)}";
                }
                return recovered;
            }
            catch (StrictPortalWindowUnreachableException secondException)
            {
                failureReason =
                    $"strict repath exhausted: downstream portal window remains unreachable after rebuild startSector={startSectorId} " +
                    $"goalSector={goalSectorId} start=({startX},{startY}) goal=({goalX},{goalY}) " +
                    $"newHandle={FormatPathHandle(agent.NavState.PathHandle)} root={secondException.Message}";
                return false;
            }
        }
    }

    private static bool IsCurrentPathSegmentPendingPortal(AgentRuntimeData agent, out int portalId)
    {
        portalId = -1;
        PathHandle handle = agent?.NavState.PathHandle;
        if (handle == null || handle.SectorIds == null || handle.PortalIds == null)
            return false;

        int currentIndex = Mathf.Clamp(handle.CurrentSectorIndex, 0, Mathf.Max(0, handle.SectorIds.Length - 1));
        if (currentIndex < 0 || currentIndex >= handle.SectorIds.Length - 1)
            return false;
        if (currentIndex >= handle.PortalIds.Length)
            return false;

        portalId = handle.PortalIds[currentIndex];
        return portalId >= 0;
    }

    private static string BuildTileBuildPendingFailure(AgentRuntimeData agent, int startSectorId, int goalSectorId, int goalX, int goalY)
    {
        PathHandle handle = agent?.NavState.PathHandle;
        if (handle == null || handle.SectorIds == null || handle.SectorIds.Length == 0)
            return $"tile pending unavailable: invalid handle={FormatPathHandle(handle)}";

        int sectorPathIndex = Mathf.Clamp(handle.CurrentSectorIndex, 0, handle.SectorIds.Length - 1);
        FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(
            handle,
            sectorPathIndex,
            goalX,
            goalY,
            agent.AgentTypeId,
            out TileGoalKind goalKind,
            out int downstreamPortalId);
        bool cached = FlowTileCache.ContainsKey(key);
        bool pending = PendingFlowTileBuildJobs.Contains(key);
        bool pathMissingPortal = PathReferencesMissingPortal(handle);
        return $"tile pending startSector={startSectorId} goalSector={goalSectorId} sectorPathIndex={sectorPathIndex} " +
               $"goalKind={goalKind} downstreamPortal={downstreamPortalId} key={FormatTileKey(key)} cached={cached} pending={pending} " +
               $"pendingJobs={FlowTileBuildQueue.Count} pendingDetails={BuildPendingFlowTileJobDiagnostics()} " +
               $"cacheCount={FlowTileCache.Count} pathMissingPortal={pathMissingPortal} handle={FormatPathHandle(handle)}";
    }

    private static string BuildPendingFlowTileJobDiagnostics()
    {
        if (FlowTileBuildQueue.Count == 0)
            return "[]";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append('[');
        int count = 0;
        for (LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First; node != null && count < 8; node = node.Next, count++)
        {
            if (count > 0)
                builder.Append(" | ");

            FlowTileBuildJob job = node.Value;
            builder.Append("{key=").Append(FormatTileKey(job.BuildKey.CacheKey))
                .Append(",stage=PendingFixedCommit")
                .Append(",sectorPathIndex=").Append(job.BuildKey.SectorPathIndex)
                .Append('}');
        }

        if (FlowTileBuildQueue.Count > count)
            builder.Append(" | ...");
        builder.Append(']');
        return builder.ToString();
    }

    private static string BuildFlowTileJobDiagnosticForKey(FlowTileCacheKey key)
    {
        int index = 0;
        for (LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First; node != null; node = node.Next, index++)
        {
            FlowTileBuildJob job = node.Value;
            if (!job.BuildKey.CacheKey.Equals(key))
                continue;

            bool stale = IsFlowTileBuildJobStale(job);
            return "{index=" + index +
                   ",stage=PendingFixedCommit" +
                   ",stale=" + stale +
                   ",sectorPathIndex=" + job.BuildKey.SectorPathIndex +
                   "}";
        }

        return "not-in-queue";
    }

    private static bool TryGetFlowTileJobQueueState(
        FlowTileCacheKey key,
        out int queueIndex,
        out string stage,
        out bool waitingForDependency,
        out bool stale)
    {
        queueIndex = -1;
        stage = "none";
        waitingForDependency = false;
        stale = false;
        int index = 0;
        for (LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First; node != null; node = node.Next, index++)
        {
            FlowTileBuildJob job = node.Value;
            if (!job.BuildKey.CacheKey.Equals(key))
                continue;

            queueIndex = index;
            stage = "PendingFixedCommit";
            waitingForDependency = false;
            stale = IsFlowTileBuildJobStale(job);
            return true;
        }

        return false;
    }

    private static FlowTileCacheKey CreateTileCacheKeyForPathSegment(
        PathHandle handle,
        int sectorPathIndex,
        int goalX,
        int goalY,
        int agentTypeId,
        out TileGoalKind goalKind,
        out int downstreamPortalId)
    {
        if (handle == null)
            throw new InvalidOperationException("CreateTileCacheKeyForPathSegment failed: handle is null.");

        int sectorId = handle.SectorIds[sectorPathIndex];
        int goalId;
        int downstreamGoalHint;
        if (sectorPathIndex >= handle.SectorIds.Length - 1)
        {
            goalKind = TileGoalKind.FinalGoal;
            downstreamPortalId = -1;
            goalId = _world.GetIndex(goalX, goalY);
            downstreamGoalHint = 0;
        }
        else
        {
            goalKind = TileGoalKind.Portal;
            downstreamPortalId = handle.PortalIds[sectorPathIndex];
            goalId = downstreamPortalId;
            downstreamGoalHint = ResolveDownstreamGoalHint(handle, sectorPathIndex, goalX, goalY);
        }

        var resolvedKey = new FlowTileCacheKey(
            _world.Version,
            sectorId,
            goalKind,
            goalId,
            downstreamGoalHint,
            ResolveFinalGoalCacheIndex(handle, sectorPathIndex, goalX, goalY),
            agentTypeId,
            _world.Sectors[sectorId].DirtyVersion);
        if (!handle.HasCommittedCurrentTileKey
            || sectorPathIndex != handle.CurrentSectorIndex
            || handle.CommittedCurrentTileKey.SectorId != sectorId)
        {
            return resolvedKey;
        }

        FlowTileCacheKey committedKey = handle.CommittedCurrentTileKey;
        if (goalKind != TileGoalKind.Portal
            || committedKey.WorldVersion != resolvedKey.WorldVersion
            || committedKey.GoalKind != TileGoalKind.Portal
            || committedKey.GoalId != goalId
            || committedKey.AgentTypeId != agentTypeId
            || committedKey.DirtyVersion != resolvedKey.DirtyVersion)
        {
            throw new InvalidOperationException(
                $"CreateTileCacheKeyForPathSegment failed: committed current tile key is inconsistent committed={FormatTileKey(committedKey)}, resolved={FormatTileKey(resolvedKey)}.");
        }
        return committedKey;
    }

    private static int ResolveFinalGoalCacheIndex(PathHandle handle, int sectorPathIndex, int goalX, int goalY)
    {
        if (handle == null || handle.SectorIds == null || handle.SectorIds.Length == 0)
            throw new InvalidOperationException("ResolveFinalGoalCacheIndex failed: handle is invalid.");

        int exactGoalIndex = _world.GetIndex(goalX, goalY);
        if (sectorPathIndex >= handle.SectorIds.Length - 2)
            return exactGoalIndex;

        return 0;
    }

    private static int ResolveDownstreamGoalHint(PathHandle handle, int sectorPathIndex, int goalX, int goalY)
    {
        int nextSectorIndex = sectorPathIndex + 1;
        if (nextSectorIndex >= handle.SectorIds.Length - 1)
            return ~_world.GetIndex(goalX, goalY);

        return handle.PortalIds[nextSectorIndex];
    }

    private static void EnqueueFlowTileBuildChain(
        PathHandle handle,
        int sectorPathIndex,
        int goalX,
        int goalY,
        int agentTypeId,
        bool prependToFront = false)
    {
        if (handle == null)
            throw new InvalidOperationException("EnqueueFlowTileBuildChain failed: handle is null.");
        if (handle.SectorIds == null || handle.SectorIds.Length == 0)
            throw new InvalidOperationException("EnqueueFlowTileBuildChain failed: handle sector path is invalid.");
        if (sectorPathIndex < 0 || sectorPathIndex >= handle.SectorIds.Length)
            throw new InvalidOperationException($"EnqueueFlowTileBuildChain failed: sectorPathIndex out of range {sectorPathIndex}.");

        bool requiresSnapshot = false;
        if (prependToFront)
        {
            int finalIndex = handle.SectorIds.Length - 1;
            int finalAdjacentIndex = finalIndex - 1;
            requiresSnapshot = RequiresNewFlowTileBuildJob(handle, finalIndex, goalX, goalY, agentTypeId)
                               || (finalAdjacentIndex >= sectorPathIndex
                                   && RequiresNewFlowTileBuildJob(handle, finalAdjacentIndex, goalX, goalY, agentTypeId))
                               || (sectorPathIndex != finalIndex
                                   && sectorPathIndex != finalAdjacentIndex
                                   && RequiresNewFlowTileBuildJob(handle, sectorPathIndex, goalX, goalY, agentTypeId));
        }
        else
        {
            for (int i = handle.SectorIds.Length - 1; i >= sectorPathIndex; i--)
            {
                if (!RequiresNewFlowTileBuildJob(handle, i, goalX, goalY, agentTypeId))
                    continue;
                requiresSnapshot = true;
                break;
            }
        }

        PathHandle snapshot = requiresSnapshot ? ClonePathHandle(handle) : handle;
        if (prependToFront)
        {
            EnqueueFlowTileBuildChainToFront(snapshot, sectorPathIndex, goalX, goalY, agentTypeId);
            return;
        }

        for (int i = snapshot.SectorIds.Length - 1; i >= sectorPathIndex; i--)
            EnqueueFlowTileBuildJob(snapshot, i, goalX, goalY, agentTypeId, prependToFront: false);
    }

    private static void EnqueueFlowTileBuildChainToFront(PathHandle snapshot, int sectorPathIndex, int goalX, int goalY, int agentTypeId)
    {
        int finalIndex = snapshot.SectorIds.Length - 1;
        int finalAdjacentIndex = finalIndex - 1;
        if (sectorPathIndex == finalIndex)
        {
            EnqueueFlowTileBuildJob(snapshot, finalIndex, goalX, goalY, agentTypeId, prependToFront: true);
            return;
        }

        if (sectorPathIndex == finalAdjacentIndex)
        {
            EnqueueFlowTileBuildJob(snapshot, finalAdjacentIndex, goalX, goalY, agentTypeId, prependToFront: true);
            EnqueueFlowTileBuildJob(snapshot, finalIndex, goalX, goalY, agentTypeId, prependToFront: true);
            return;
        }

        for (int i = finalAdjacentIndex; i > sectorPathIndex; i--)
            EnqueueFlowTileBuildJob(snapshot, i, goalX, goalY, agentTypeId, prependToFront: true);
        EnqueueFlowTileBuildJob(snapshot, finalIndex, goalX, goalY, agentTypeId, prependToFront: true);
        EnqueueFlowTileBuildJob(snapshot, sectorPathIndex, goalX, goalY, agentTypeId, prependToFront: true);
    }

    private static void EnqueueActiveFlowTileBuilds(PathHandle handle, int sectorPathIndex, int goalX, int goalY, int agentTypeId)
    {
        if (handle == null)
            throw new InvalidOperationException("EnqueueActiveFlowTileBuilds failed: handle is null.");
        if (handle.SectorIds == null || handle.SectorIds.Length == 0)
            throw new InvalidOperationException("EnqueueActiveFlowTileBuilds failed: handle sector path is invalid.");
        if (sectorPathIndex < 0 || sectorPathIndex >= handle.SectorIds.Length)
            throw new InvalidOperationException($"EnqueueActiveFlowTileBuilds failed: sectorPathIndex out of range {sectorPathIndex}.");

        int finalIndex = handle.SectorIds.Length - 1;
        int finalAdjacentIndex = finalIndex - 1;
        bool requiresSnapshot = RequiresNewFlowTileBuildJob(handle, finalIndex, goalX, goalY, agentTypeId)
                                || (finalAdjacentIndex >= sectorPathIndex
                                    && RequiresNewFlowTileBuildJob(handle, finalAdjacentIndex, goalX, goalY, agentTypeId))
                                || (sectorPathIndex != finalIndex
                                    && sectorPathIndex != finalAdjacentIndex
                                     && RequiresNewFlowTileBuildJob(handle, sectorPathIndex, goalX, goalY, agentTypeId));
        PathHandle snapshot = requiresSnapshot ? ClonePathHandle(handle) : handle;
        if (finalAdjacentIndex >= sectorPathIndex)
            EnqueueFlowTileBuildJob(snapshot, finalAdjacentIndex, goalX, goalY, agentTypeId, prependToFront: true);
        EnqueueFlowTileBuildJob(snapshot, finalIndex, goalX, goalY, agentTypeId, prependToFront: true);
        if (sectorPathIndex != finalIndex && sectorPathIndex != finalAdjacentIndex)
            EnqueueFlowTileBuildJob(snapshot, sectorPathIndex, goalX, goalY, agentTypeId, prependToFront: true);
    }

    private static void AddActiveFlowTileBuildKeys(PathHandle handle, int sectorPathIndex, int goalX, int goalY, int agentTypeId)
    {
        if (handle == null)
            throw new InvalidOperationException("AddActiveFlowTileBuildKeys failed: handle is null.");
        if (handle.SectorIds == null || handle.SectorIds.Length == 0)
            throw new InvalidOperationException("AddActiveFlowTileBuildKeys failed: handle sector path is invalid.");
        if (sectorPathIndex < 0 || sectorPathIndex >= handle.SectorIds.Length)
            throw new InvalidOperationException($"AddActiveFlowTileBuildKeys failed: sectorPathIndex out of range {sectorPathIndex}.");

        int finalIndex = handle.SectorIds.Length - 1;
        int finalAdjacentIndex = finalIndex - 1;
        AddActiveFlowTileBuildKey(handle, finalIndex, goalX, goalY, agentTypeId);
        if (finalAdjacentIndex >= sectorPathIndex)
            AddActiveFlowTileBuildKey(handle, finalAdjacentIndex, goalX, goalY, agentTypeId);
        if (sectorPathIndex != finalIndex && sectorPathIndex != finalAdjacentIndex)
            AddActiveFlowTileBuildKey(handle, sectorPathIndex, goalX, goalY, agentTypeId);
    }

    private static bool RequiresNewFlowTileBuildJob(
        PathHandle handle,
        int sectorPathIndex,
        int goalX,
        int goalY,
        int agentTypeId)
    {
        FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(
            handle,
            sectorPathIndex,
            goalX,
            goalY,
            agentTypeId,
            out _,
            out _);
        return !FlowTileCache.ContainsKey(key) && !PendingFlowTileBuildJobs.Contains(key);
    }

    private static void AddActiveFlowTileBuildKey(PathHandle handle, int sectorPathIndex, int goalX, int goalY, int agentTypeId)
    {
        ActiveFlowTileBuildKeys.Add(CreateTileCacheKeyForPathSegment(
            handle,
            sectorPathIndex,
            goalX,
            goalY,
            agentTypeId,
            out _,
            out _));
    }

    private static void EnqueueFlowTileBuildJob(PathHandle snapshot, int sectorPathIndex, int goalX, int goalY, int agentTypeId, bool prependToFront)
    {
        FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(snapshot, sectorPathIndex, goalX, goalY, agentTypeId, out _, out _);
        if (FlowTileCache.ContainsKey(key))
            return;

        FlowTileBuildKey buildKey = new FlowTileBuildKey(key, sectorPathIndex, goalX, goalY, agentTypeId);
        if (!PendingFlowTileBuildJobs.Add(key))
        {
            if (prependToFront)
                PromotePendingFlowTileBuildJobToFront(key);
            return;
        }

        FlowTileBuildJob job = new FlowTileBuildJob
        {
            BuildKey = buildKey,
            HandleSnapshot = snapshot
        };
        if (prependToFront)
            FlowTileBuildQueue.AddFirst(job);
        else
            FlowTileBuildQueue.AddLast(job);
        _perf.FlowTileQueueEnqueued++;
    }

    private static void PromotePendingFlowTileBuildJobToFront(FlowTileCacheKey key)
    {
        for (LinkedListNode<FlowTileBuildJob> node = FlowTileBuildQueue.First; node != null; node = node.Next)
        {
            FlowTileBuildJob job = node.Value;
            if (!job.BuildKey.CacheKey.Equals(key))
                continue;

            FlowTileBuildQueue.Remove(node);
            FlowTileBuildQueue.AddFirst(job);
            _perf.FlowTileQueuePromoted++;
            return;
        }

        PendingFlowTileBuildJobs.Remove(key);
    }

    private static void ReleasePendingFlowTileBuildJobPayloads(FlowTileBuildJob job)
    {
        if (job == null)
            throw new InvalidOperationException("ReleasePendingFlowTileBuildJobPayloads failed: job is null.");
    }

    private static PathHandle ClonePathHandle(PathHandle handle)
    {
        if (handle == null)
            throw new InvalidOperationException("ClonePathHandle failed: handle is null.");

        return new PathHandle
        {
            HandleId = handle.HandleId,
            WorldVersion = handle.WorldVersion,
            GoalX = handle.GoalX,
            GoalY = handle.GoalY,
            SectorIds = handle.SectorIds != null ? (int[])handle.SectorIds.Clone() : null,
            PortalIds = handle.PortalIds != null ? (int[])handle.PortalIds.Clone() : null,
            CurrentSectorIndex = handle.CurrentSectorIndex,
            BuildSource = handle.BuildSource,
            HasCommittedCurrentTileKey = handle.HasCommittedCurrentTileKey,
            CommittedCurrentTileKey = handle.CommittedCurrentTileKey,
            CommittedCorridorGoalX = handle.CommittedCorridorGoalX,
            CommittedCorridorGoalY = handle.CommittedCorridorGoalY,
            CommittedCorridorSectorIds = handle.CommittedCorridorSectorIds != null
                ? (int[])handle.CommittedCorridorSectorIds.Clone()
                : null,
            CommittedCorridorPortalIds = handle.CommittedCorridorPortalIds != null
                ? (int[])handle.CommittedCorridorPortalIds.Clone()
                : null
        };
    }

    private static Vector2Int[] ResolveGoalCells(SectorData sector, FlowTileCacheKey key, int goalX, int goalY)
    {
        if (key.GoalKind == TileGoalKind.FinalGoal)
            return new[] { new Vector2Int(goalX, goalY) };

        return GetPortalCellsForSector(GetPortalById(_world, key.GoalId), sector.SectorId);
    }

    private static bool IsInsideSector(FlowTileCacheEntry tile, int worldX, int worldY)
    {
        return worldX >= tile.StartX
               && worldX < tile.StartX + tile.Width
               && worldY >= tile.StartY
               && worldY < tile.StartY + tile.Height;
    }

    private static void TrimTileCache()
    {
        if (FlowTileCache.Count <= Config.FlowTileCacheLimit)
            return;

        int threshold = GetFrameCount() - 120;
        List<FlowTileCacheKey> expiredKeys = new List<FlowTileCacheKey>();
        foreach (KeyValuePair<FlowTileCacheKey, FlowTileCacheEntry> pair in FlowTileCache)
        {
            if (pair.Value.ActiveReferenceCount > 0)
                continue;
            if (pair.Value.LastUsedFrame < threshold && pair.Value.LastReferencedFrame < threshold)
                expiredKeys.Add(pair.Key);
        }

        for (int i = 0; i < expiredKeys.Count; i++)
            RemoveFlowTileCacheEntry(expiredKeys[i]);

        if (FlowTileCache.Count <= Config.FlowTileCacheLimit)
            return;

        List<FlowTileCacheKey> keys = new List<FlowTileCacheKey>(FlowTileCache.Keys);
        keys.Sort((a, b) =>
        {
            int retainFrameOrder = ResolveFlowTileRetainFrame(FlowTileCache[a]).CompareTo(ResolveFlowTileRetainFrame(FlowTileCache[b]));
            return retainFrameOrder != 0 ? retainFrameOrder : CompareFlowTileCacheKeys(a, b);
        });
        int removeCount = FlowTileCache.Count - Config.FlowTileCacheLimit;
        for (int i = 0; i < keys.Count && removeCount > 0; i++)
        {
            if (FlowTileCache[keys[i]].ActiveReferenceCount > 0)
                continue;

            RemoveFlowTileCacheEntry(keys[i]);
            removeCount--;
        }
    }

    private static void RefreshFlowTileReferenceCounts()
    {
        _perf.FlowTileReferenceRefreshCalls++;
        foreach (KeyValuePair<FlowTileCacheKey, FlowTileCacheEntry> pair in FlowTileCache)
        {
            if (pair.Key.WorldVersion == _world.Version)
                pair.Value.ActiveReferenceCount = 0;
        }

        int frame = GetFrameCount();
        foreach (AgentRuntimeData agent in Agents.Values)
        {
            if (!IsAgentInActiveFlowBuildQueueWorld(agent))
                continue;

            PathHandle handle = agent.NavState.PathHandle;
            if (handle == null
                || handle.WorldVersion != _world.Version
                || handle.SectorIds == null
                || handle.SectorIds.Length == 0
                || PathReferencesMissingPortal(handle))
            {
                continue;
            }

            int startIndex = Mathf.Clamp(handle.CurrentSectorIndex, 0, handle.SectorIds.Length - 1);
            if (handle.HasCommittedCurrentTileKey
                && handle.CommittedCurrentTileKey.GoalKind == TileGoalKind.Portal
                && handle.CommittedCurrentTileKey.DownstreamGoalHint < 0)
            {
                PortalData committedPortal = GetPortalById(_world, handle.CommittedCurrentTileKey.GoalId);
                int continuationSectorId = GetOppositeSectorId(
                    committedPortal,
                    handle.CommittedCurrentTileKey.SectorId);
                FlowTileCacheKey continuationKey = CreatePortalContinuationFinalTileKey(
                    handle.CommittedCurrentTileKey,
                    continuationSectorId);
                if (FlowTileCache.TryGetValue(continuationKey, out FlowTileCacheEntry continuationTile))
                {
                    continuationTile.ActiveReferenceCount++;
                    continuationTile.LastReferencedFrame = frame;
                }
            }

            for (int i = startIndex; i < handle.SectorIds.Length; i++)
            {
                _perf.FlowTileReferenceKeyScans++;
                FlowTileCacheKey key = CreateTileCacheKeyForPathSegment(
                    handle,
                    i,
                    handle.GoalX,
                    handle.GoalY,
                    agent.AgentTypeId,
                    out _,
                    out _);
                if (!FlowTileCache.TryGetValue(key, out FlowTileCacheEntry tile))
                    continue;

                tile.ActiveReferenceCount++;
                tile.LastReferencedFrame = frame;
            }
        }
    }

    private static int ResolveFlowTileRetainFrame(FlowTileCacheEntry tile)
    {
        if (tile == null)
            return int.MinValue;

        return Mathf.Max(tile.LastUsedFrame, tile.LastReferencedFrame);
    }

    private static bool ShouldLogPortalDiagnostics(string characterKey, TileGoalKind goalKind)
    {
        return goalKind == TileGoalKind.Portal
               && GameDebugSettings.IsEnabled(DebugCategory.Move)
               && !string.IsNullOrEmpty(characterKey)
               && GameDebugSettings.ShouldLogMovementForCharacter(characterKey);
    }

    private static string FormatGoalCells(Vector2Int[] cells)
    {
        if (cells == null || cells.Length == 0)
            return "[]";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(cells.Length * 12);
        builder.Append('[');
        for (int i = 0; i < cells.Length; i++)
        {
            if (i > 0)
                builder.Append(", ");
            builder.Append('(');
            builder.Append(cells[i].x);
            builder.Append(',');
            builder.Append(cells[i].y);
            builder.Append(')');
        }
        builder.Append(']');
        return builder.ToString();
    }

    private static string FormatTileKey(FlowTileCacheKey key)
    {
        return $"(world={key.WorldVersion},sector={key.SectorId},goalKind={key.GoalKind},goalId={key.GoalId},downstreamHint={key.DownstreamGoalHint},finalGoal={key.FinalGoalIndex},agentType={key.AgentTypeId},dirty={key.DirtyVersion})";
    }

    private static string FormatSharedGoalFieldKey(SharedGoalFieldKey key)
    {
        return $"(world={key.WorldVersion},sector={key.GoalSectorId},goalCell={key.GoalCellIndex},agentType={key.AgentTypeId},dirty={key.GoalSectorDirtyVersion})";
    }

    private static string FormatPathHandle(PathHandle handle)
    {
        if (handle == null)
            return "null";

        string sectors = handle.SectorIds == null ? "null" : string.Join("->", handle.SectorIds);
        string portals = handle.PortalIds == null ? "null" : string.Join("->", handle.PortalIds);
        string committedTile = handle.HasCommittedCurrentTileKey
            ? FormatTileKey(handle.CommittedCurrentTileKey)
            : "none";
        string committedSectors = handle.CommittedCorridorSectorIds == null
            ? "null"
            : string.Join("->", handle.CommittedCorridorSectorIds);
        string committedPortals = handle.CommittedCorridorPortalIds == null
            ? "null"
            : string.Join("->", handle.CommittedCorridorPortalIds);
        return $"(world={handle.WorldVersion},goal=({handle.GoalX},{handle.GoalY}),currentSectorIndex={handle.CurrentSectorIndex},sectors=[{sectors}],portals=[{portals}]," +
               $"committedTile={committedTile},committedGoal=({handle.CommittedCorridorGoalX},{handle.CommittedCorridorGoalY})," +
               $"committedSectors=[{committedSectors}],committedPortals=[{committedPortals}])";
    }

    private static string BuildCurrentTileSteeringDiagnostics(FlowTileCacheEntry tile, int currentX, int currentY)
    {
        if (tile == null)
            return "tile=null";
        if (!IsInsideSector(tile, currentX, currentY))
            return $"tileKey={FormatTileKey(tile.Key)} cell=outside rect=({tile.StartX},{tile.StartY},{tile.Width},{tile.Height})";

        int localIndex = tile.GetLocalIndex(currentX, currentY);
        TryGetTileIntegrationCostForDiagnostics(tile, currentX, currentY, out float currentCost, out string currentCostSource);
        Vector2 currentFlow = ResolveRuntimeFlowDirection(tile, currentX, currentY, localIndex);
        Vector2 storedFlow = GetFlowDirection(tile, localIndex);
        bool currentPathable = IsFlowPathable(tile, localIndex);
        bool currentReachable = IsFlowReachable(tile, localIndex);
        string goalCellState = BuildTileGoalCellStateDiagnostics(tile, currentX, currentY);

        int bestNeighborX = currentX;
        int bestNeighborY = currentY;
        float bestNeighborCost = currentCost;
        Vector2 bestNeighborFlow = currentFlow;
        bool bestNeighborFound = false;
        System.Text.StringBuilder neighborBuilder = new System.Text.StringBuilder(384);
        neighborBuilder.Append("[");
        int neighborCount = 0;
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int nextX = currentX + NeighborOffsetX[i];
            int nextY = currentY + NeighborOffsetY[i];
            if (!IsInsideSector(tile, nextX, nextY) || !_world.IsWalkable(nextX, nextY))
                continue;

            if (!CanTraverseNeighborCells(_world, currentX, currentY, nextX, nextY))
                continue;

            int nextIndex = tile.GetLocalIndex(nextX, nextY);
            TryGetTileIntegrationCostForDiagnostics(tile, nextX, nextY, out float nextCost, out string nextCostSource);
            Vector2 nextFlow = ResolveRuntimeFlowDirection(tile, nextX, nextY, nextIndex);
            Vector2 nextStoredFlow = GetFlowDirection(tile, nextIndex);
            if (neighborCount > 0)
                neighborBuilder.Append(" | ");
            neighborBuilder.Append("(").Append(nextX).Append(',').Append(nextY).Append("){cost=")
                .Append(float.IsPositiveInfinity(nextCost) ? "INF" : nextCost.ToString("F3"))
                .Append(",costSource=").Append(nextCostSource)
                .Append(",stored=").Append(nextStoredFlow)
                .Append(",runtime=").Append(nextFlow)
                .Append(",pathable=").Append(IsFlowPathable(tile, nextIndex))
                .Append(",reachable=").Append(IsFlowReachable(tile, nextIndex))
                .Append("}");
            neighborCount++;

            if (float.IsPositiveInfinity(nextCost))
                continue;

            if (!bestNeighborFound || nextCost < bestNeighborCost - 0.0001f)
            {
                bestNeighborFound = true;
                bestNeighborX = nextX;
                bestNeighborY = nextY;
                bestNeighborCost = nextCost;
                bestNeighborFlow = nextFlow;
            }
        }

        if (neighborCount == 0)
            neighborBuilder.Append("none");
        neighborBuilder.Append(']');

        return $"tileKey={FormatTileKey(tile.Key)} cell=({currentX},{currentY}) cost={(float.IsPositiveInfinity(currentCost) ? "INF" : currentCost.ToString("F3"))} costSource={currentCostSource} " +
               $"flow={currentFlow} stored={storedFlow} pathable={currentPathable} reachable={currentReachable} " +
               $"{goalCellState} " +
               $"bestNeighbor=({bestNeighborX},{bestNeighborY}) bestNeighborCost={(float.IsPositiveInfinity(bestNeighborCost) ? "INF" : bestNeighborCost.ToString("F3"))} " +
               $"bestNeighborFlow={bestNeighborFlow} neighbors={neighborBuilder}";
    }

    private static string BuildTileGoalCellStateDiagnostics(FlowTileCacheEntry tile, int currentX, int currentY)
    {
        if (tile?.GoalCells == null)
            return "goalCellState=none";

        int goalIndex = -1;
        for (int i = 0; i < tile.GoalCells.Length; i++)
        {
            if (tile.GoalCells[i].x == currentX && tile.GoalCells[i].y == currentY)
            {
                goalIndex = i;
                break;
            }
        }

        if (goalIndex < 0)
            return $"isGoalCell=False goalCells={FormatGoalCells(tile.GoalCells)}";

        if (tile.Key.GoalKind != TileGoalKind.Portal)
            return $"isGoalCell=True goalIndex={goalIndex} goalCells={FormatGoalCells(tile.GoalCells)}";

        PortalData portal = GetPortalById(_world, tile.Key.GoalId);
        int oppositeSectorId = GetOppositeSectorId(portal, tile.Key.SectorId);
        Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, oppositeSectorId);
        if (goalIndex >= oppositeCells.Length)
            return $"isGoalCell=True goalIndex={goalIndex} opposite=out-of-range portal={FormatPortal(portal)}";

        Vector2Int opposite = oppositeCells[goalIndex];
        bool oppositeWalkable = _world.IsWalkable(opposite.x, opposite.y);
        bool traversable = oppositeWalkable && CanTraverseNeighborCells(_world, currentX, currentY, opposite.x, opposite.y);
        return $"isGoalCell=True goalIndex={goalIndex} opposite=({opposite.x},{opposite.y}) oppositeWalkable={oppositeWalkable} oppositeTraversable={traversable} portal={FormatPortal(portal)}";
    }

    private static string BuildGridPathDiagnostics(Vector3 fromPosition, Vector3 toPosition, int agentTypeId)
    {
        if (_world == null)
            return "flowPath=world-null";

        bool fromInGrid = _world.WorldToGrid(fromPosition, out int fromX, out int fromY);
        bool toInGrid = _world.WorldToGrid(toPosition, out int toX, out int toY);
        bool fromWalkable = fromInGrid && _world.IsWalkable(fromX, fromY);
        bool toWalkable = toInGrid && _world.IsWalkable(toX, toY);
        int fromIsland = fromInGrid ? ResolveIslandIdForDiagnostics(_world, fromX, fromY) : -1;
        int toIsland = toInGrid ? ResolveIslandIdForDiagnostics(_world, toX, toY) : -1;
        float distance = ResolveGridPathLengthOrInfinity(fromPosition, toPosition, agentTypeId);
        return $"flowPath={{fromCell={(fromInGrid ? $"({fromX},{fromY})" : "out")},toCell={(toInGrid ? $"({toX},{toY})" : "out")},fromWalk={fromWalkable},toWalk={toWalkable},fromIsland={fromIsland},toIsland={toIsland},sameIsland={fromIsland > 0 && fromIsland == toIsland},gridDistance={FormatDiagnosticCost(distance)}}}";
    }

    private static string BuildSelectedPortalGridTrace(int startSectorId, int startX, int startY, int portalId, int maxSteps)
    {
        if (_world == null)
            return "world-null";
        if (portalId < 0)
            return "none";
        if (!TryGetPortalById(_world, portalId, out PortalData portal))
            return "portal-missing:" + portalId;

        Vector2Int[] currentCells = GetPortalCellsForSector(portal, startSectorId);
        return "portal=" + FormatPortal(portal)
               + ",cells=" + FormatGoalCells(currentCells)
               + ",path=" + BuildGridShortestPathTraceToCells(startX, startY, currentCells, maxSteps);
    }

    private static string BuildHandlePortalRouteDiagnostics(PathHandle handle, int startSectorId, int startX, int startY, int goalX, int goalY, int maxSteps)
    {
        if (_world == null)
            return "world-null";
        if (handle == null || handle.SectorIds == null || handle.PortalIds == null)
            return "handle-null";

        int sectorIndex = FindSectorIndex(handle, startSectorId, Mathf.Max(0, handle.CurrentSectorIndex));
        if (sectorIndex < 0)
            return "start-sector-not-in-handle:" + FormatPathHandle(handle);

        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append(FormatPathHandle(handle));
        int cursorX = -1;
        int cursorY = -1;
        for (int i = sectorIndex; i < handle.PortalIds.Length; i++)
        {
            int sectorId = handle.SectorIds[i];
            int portalId = handle.PortalIds[i];
            if (!TryGetPortalById(_world, portalId, out PortalData portal))
            {
                builder.Append("|missingPortal=").Append(portalId);
                continue;
            }

            Vector2Int[] currentCells = GetPortalCellsForSector(portal, sectorId);
            Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, handle.SectorIds[i + 1]);
            builder.Append("|seg").Append(i)
                .Append("{sector=").Append(sectorId)
                .Append(",portal=").Append(portalId)
                .Append(",cur=").Append(FormatGoalCells(currentCells))
                .Append(",opp=").Append(FormatGoalCells(oppositeCells));
            if (i == sectorIndex)
                builder.Append(",fromStart=").Append(BuildGridShortestPathTraceToCells(startX, startY, currentCells, maxSteps));
            if (oppositeCells != null && oppositeCells.Length > 0)
            {
                Vector2Int opposite = oppositeCells[oppositeCells.Length / 2];
                cursorX = opposite.x;
                cursorY = opposite.y;
            }
            builder.Append('}');
        }

        if (cursorX >= 0)
            builder.Append("|lastOppToGoal=").Append(BuildGridShortestPathTraceToCell(cursorX, cursorY, goalX, goalY, maxSteps));
        return builder.ToString();
    }

    private static string BuildGridShortestPathTraceToCell(int startX, int startY, int goalX, int goalY, int maxSteps)
    {
        if (_world == null)
            return "world-null";
        if (goalX < 0 || goalX >= _world.Width || goalY < 0 || goalY >= _world.Height || !_world.IsWalkable(goalX, goalY))
            return "goal-invalid";

        bool[] targets = new bool[_world.Width * _world.Height];
        targets[_world.GetIndex(goalX, goalY)] = true;
        return BuildGridShortestPathTraceToTargets(startX, startY, targets, maxSteps);
    }

    private static string BuildGridShortestPathTraceToCells(int startX, int startY, Vector2Int[] targetCells, int maxSteps)
    {
        if (_world == null)
            return "world-null";
        if (targetCells == null || targetCells.Length == 0)
            return "no-targets";

        bool[] targets = new bool[_world.Width * _world.Height];
        bool hasTarget = false;
        for (int i = 0; i < targetCells.Length; i++)
        {
            Vector2Int cell = targetCells[i];
            if (cell.x < 0 || cell.x >= _world.Width || cell.y < 0 || cell.y >= _world.Height || !_world.IsWalkable(cell.x, cell.y))
                continue;

            targets[_world.GetIndex(cell.x, cell.y)] = true;
            hasTarget = true;
        }

        return hasTarget ? BuildGridShortestPathTraceToTargets(startX, startY, targets, maxSteps) : "no-walkable-targets";
    }

    private static string BuildGridShortestPathTraceToTargets(int startX, int startY, bool[] targets, int maxSteps)
    {
        if (_world == null)
            return "world-null";
        int cellCount = _world.Width * _world.Height;
        if (targets == null || targets.Length != cellCount)
            return "invalid-targets";
        if (startX < 0 || startX >= _world.Width || startY < 0 || startY >= _world.Height || !_world.IsWalkable(startX, startY))
            return "start-invalid";

        int startIndex = _world.GetIndex(startX, startY);
        if (targets[startIndex])
            return "(" + startX + "," + startY + "):target";

        float[] costs = RentIntegrationArray(cellCount);
        int[] cameFrom = new int[cellCount];
        for (int i = 0; i < cameFrom.Length; i++)
            cameFrom[i] = -1;

        InitializeIntegrationField(costs);
        MinHeap openSet = new MinHeap();
        costs[startIndex] = 0f;
        openSet.Push(startIndex, 0f);
        int reachedIndex = -1;
        int guard = cellCount * 4;
        try
        {
            while (openSet.Count > 0 && guard-- > 0)
            {
                QueueNode node = openSet.Pop();
                if (node.Cost > costs[node.Index] + 0.001f)
                    continue;
                if (targets[node.Index])
                {
                    reachedIndex = node.Index;
                    break;
                }

                int worldX = node.Index % _world.Width;
                int worldY = node.Index / _world.Width;
                for (int i = 0; i < NeighborOffsetX.Length; i++)
                {
                    int nextX = worldX + NeighborOffsetX[i];
                    int nextY = worldY + NeighborOffsetY[i];
                    if (nextX < 0 || nextX >= _world.Width || nextY < 0 || nextY >= _world.Height)
                        continue;
                    if (!_world.IsWalkable(nextX, nextY) || !CanTraverseNeighborCells(_world, worldX, worldY, nextX, nextY))
                        continue;

                    int nextIndex = _world.GetIndex(nextX, nextY);
                    float stepDistance = Mathf.Abs(NeighborOffsetX[i]) + Mathf.Abs(NeighborOffsetY[i]) == 2 ? 1.4142135f : 1f;
                    float stepCost = Mathf.Max(ResolveCellIntegrationCost(_world, nextX, nextY), 0.001f) * stepDistance;
                    float newCost = node.Cost + stepCost;
                    if (!IsSignificantIntegrationImprovement(newCost, costs[nextIndex]))
                        continue;

                    costs[nextIndex] = newCost;
                    cameFrom[nextIndex] = node.Index;
                    openSet.Push(nextIndex, newCost);
                }
            }

            if (reachedIndex < 0)
                return guard <= 0 ? "guard-exceeded" : "unreachable";

            return FormatReconstructedGridPath(cameFrom, startIndex, reachedIndex, maxSteps, costs[reachedIndex]);
        }
        finally
        {
            ReturnIntegrationArray(costs);
        }
    }

    private static string FormatReconstructedGridPath(int[] cameFrom, int startIndex, int reachedIndex, int maxSteps, float totalCost)
    {
        if (_world == null || cameFrom == null)
            return "invalid-reconstruct";

        List<int> reversed = new List<int>(Mathf.Max(8, maxSteps + 1));
        int cursor = reachedIndex;
        int guard = cameFrom.Length + 1;
        while (cursor >= 0 && guard-- > 0)
        {
            reversed.Add(cursor);
            if (cursor == startIndex)
                break;
            cursor = cameFrom[cursor];
        }

        if (reversed[reversed.Count - 1] != startIndex)
            return "reconstruct-failed";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(maxSteps * 12 + 64);
        builder.Append("cost=").Append(FormatDiagnosticCost(totalCost)).Append(",path=");
        int emitted = 0;
        for (int i = reversed.Count - 1; i >= 0 && emitted <= maxSteps; i--, emitted++)
        {
            if (emitted > 0)
                builder.Append("->");
            int index = reversed[i];
            builder.Append('(').Append(index % _world.Width).Append(',').Append(index / _world.Width).Append(')');
        }

        if (emitted < reversed.Count)
            builder.Append("->...");
        return builder.ToString();
    }

    private static bool TryResolveForwardBlockedProbe(int startX, int startY, Vector3 desiredDirection, out string probe, out int blockedX, out int blockedY)
    {
        blockedX = startX;
        blockedY = startY;
        probe = "none";
        if (_world == null)
            return false;

        Vector3 direction = desiredDirection;
        direction.y = 0f;
        if (direction.sqrMagnitude <= 0.0001f)
            return false;
        direction.Normalize();

        int stepX = direction.x > 0.35f ? 1 : direction.x < -0.35f ? -1 : 0;
        int stepY = direction.z > 0.35f ? 1 : direction.z < -0.35f ? -1 : 0;
        if (stepX == 0 && stepY == 0)
            return false;

        System.Text.StringBuilder builder = new System.Text.StringBuilder(256);
        int previousX = startX;
        int previousY = startY;
        bool foundBlocked = false;
        for (int step = 1; step <= 5; step++)
        {
            int x = startX + stepX * step;
            int y = startY + stepY * step;
            if (step > 1)
                builder.Append(" -> ");

            AppendForwardProbeCell(builder, previousX, previousY, x, y);
            bool blocked = x < 0
                           || x >= _world.Width
                           || y < 0
                           || y >= _world.Height
                           || !_world.IsWalkable(x, y)
                           || !CanTraverseNeighborCells(_world, previousX, previousY, x, y);
            if (blocked)
            {
                blockedX = x;
                blockedY = y;
                foundBlocked = true;
                break;
            }

            previousX = x;
            previousY = y;
        }

        probe = builder.ToString();
        return foundBlocked;
    }

    private static void AppendForwardProbeCell(System.Text.StringBuilder builder, int previousX, int previousY, int x, int y)
    {
        builder.Append('(').Append(x).Append(',').Append(y).Append("){");
        if (_world == null || x < 0 || x >= _world.Width || y < 0 || y >= _world.Height)
        {
            builder.Append("out}");
            return;
        }

        int index = _world.GetIndex(x, y);
        bool walkable = _world.IsWalkable(x, y);
        bool baseWalkable = _world.BaseWalkableMask != null
                            && _world.BaseWalkableMask.Length == _world.Width * _world.Height
                            && _world.BaseWalkableMask[index];
        byte cost = 0;
        TryGetCostFieldValue(_world, x, y, out cost);
        int island = _world.IslandIds != null && _world.IslandIds.Length == _world.Width * _world.Height ? _world.IslandIds[index] : -1;
        string mask = _world.NeighborTraversalMask != null && _world.NeighborTraversalMask.Length == _world.Width * _world.Height
            ? _world.NeighborTraversalMask[index].ToString("X2")
            : "null";
        bool link = previousX == x && previousY == y || CanTraverseNeighborCells(_world, previousX, previousY, x, y);
        builder.Append("walk=").Append(walkable)
            .Append(",base=").Append(baseWalkable)
            .Append(",cost=").Append(cost)
            .Append(",island=").Append(island)
            .Append(",mask=0x").Append(mask)
            .Append(",link=").Append(link)
            .Append('}');
    }

    private static string BuildFlowDirectionCostDiagnostics(FlowTileCacheEntry tile, int currentX, int currentY)
    {
        if (_world == null || tile == null)
            return "{worldOrTile=null}";
        if (!IsInsideSector(tile, currentX, currentY))
            return "{cell=outside}";

        bool rebuiltDebug = false;
        if (tile.DebugIntegrationPayload?.Values == null)
            rebuiltDebug = TryRebuildTileDebugIntegration(tile);

        TryGetTileIntegrationCostForDiagnostics(tile, currentX, currentY, out float currentCost, out string currentCostSource);
        int localIndex = tile.GetLocalIndex(currentX, currentY);
        Vector2 runtimeFlow = ResolveRuntimeFlowDirection(tile, currentX, currentY, localIndex);
        int flowStepX = runtimeFlow.x > 0.35f ? 1 : runtimeFlow.x < -0.35f ? -1 : 0;
        int flowStepY = runtimeFlow.y > 0.35f ? 1 : runtimeFlow.y < -0.35f ? -1 : 0;
        int flowNextX = currentX + flowStepX;
        int flowNextY = currentY + flowStepY;
        bool flowNextInside = flowStepX != 0 || flowStepY != 0;
        flowNextInside = flowNextInside && IsInsideSector(tile, flowNextX, flowNextY);
        bool flowNextWalkable = flowNextInside && _world.IsWalkable(flowNextX, flowNextY);
        bool flowNextTraversable = flowNextWalkable && CanTraverseNeighborCells(_world, currentX, currentY, flowNextX, flowNextY);
        float flowNextCost = float.PositiveInfinity;
        string flowNextCostSource = "missing";
        if (flowNextInside)
            TryGetTileIntegrationCostForDiagnostics(tile, flowNextX, flowNextY, out flowNextCost, out flowNextCostSource);

        int bestX = currentX;
        int bestY = currentY;
        float bestCost = currentCost;
        string bestSource = currentCostSource;
        bool foundBetterNeighbor = false;
        System.Text.StringBuilder neighbors = new System.Text.StringBuilder(768);
        neighbors.Append('[');
        int neighborCount = 0;
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int nextX = currentX + NeighborOffsetX[i];
            int nextY = currentY + NeighborOffsetY[i];
            if (!IsInsideSector(tile, nextX, nextY))
                continue;

            bool walkable = _world.IsWalkable(nextX, nextY);
            bool traversable = walkable && CanTraverseNeighborCells(_world, currentX, currentY, nextX, nextY);
            TryGetTileIntegrationCostForDiagnostics(tile, nextX, nextY, out float nextCost, out string nextSource);
            if (neighborCount > 0)
                neighbors.Append(" | ");
            neighbors.Append('(').Append(nextX).Append(',').Append(nextY).Append("){cost=")
                .Append(FormatDiagnosticCost(nextCost))
                .Append(",source=").Append(nextSource)
                .Append(",walk=").Append(walkable)
                .Append(",trav=").Append(traversable)
                .Append(",flow=").Append(ResolveRuntimeFlowDirection(tile, nextX, nextY, tile.GetLocalIndex(nextX, nextY)))
                .Append('}');
            neighborCount++;

            if (!traversable || float.IsPositiveInfinity(nextCost))
                continue;
            if (!foundBetterNeighbor || nextCost < bestCost - 0.001f)
            {
                foundBetterNeighbor = true;
                bestX = nextX;
                bestY = nextY;
                bestCost = nextCost;
                bestSource = nextSource;
            }
        }

        if (neighborCount == 0)
            neighbors.Append("none");
        neighbors.Append(']');

        bool flowDropsCost = flowNextTraversable
                             && !float.IsPositiveInfinity(currentCost)
                             && flowNextCost < currentCost - 0.001f;
        bool flowMatchesBest = foundBetterNeighbor && flowNextX == bestX && flowNextY == bestY;
        return "{rebuiltDebug=" + rebuiltDebug
               + ",currentCost=" + FormatDiagnosticCost(currentCost)
               + ",currentSource=" + currentCostSource
               + ",runtimeFlow=" + runtimeFlow
               + ",flowNext=(" + flowNextX + "," + flowNextY + ")"
               + ",flowNextInside=" + flowNextInside
               + ",flowNextWalkable=" + flowNextWalkable
               + ",flowNextTraversable=" + flowNextTraversable
               + ",flowNextCost=" + FormatDiagnosticCost(flowNextCost)
               + ",flowNextSource=" + flowNextCostSource
               + ",flowDropsCost=" + flowDropsCost
               + ",best=(" + bestX + "," + bestY + ")"
               + ",bestCost=" + FormatDiagnosticCost(bestCost)
               + ",bestSource=" + bestSource
               + ",flowMatchesBest=" + flowMatchesBest
               + ",neighbors=" + neighbors
               + "}";
    }

    private static string BuildFlowDirectionProbeDiagnostics(
        Vector3 startPosition,
        int startX,
        int startY,
        Vector3 desiredDirection,
        Vector2 runtimeFlow,
        int agentTypeId)
    {
        if (_world == null)
            return "{world=null}";

        Vector3 probeDirection = desiredDirection;
        probeDirection.y = 0f;
        if (probeDirection.sqrMagnitude <= 0.0001f && runtimeFlow.sqrMagnitude > 0.0001f)
            probeDirection = new Vector3(runtimeFlow.x, 0f, runtimeFlow.y);
        if (probeDirection.sqrMagnitude <= 0.0001f)
            return "{direction=zero}";

        probeDirection.Normalize();
        float probeDistance = Mathf.Max(_world.CellSize * 8f, 4f);
        Vector3 endPosition = startPosition + probeDirection * probeDistance;
        bool endInGrid = _world.WorldToGrid(endPosition, out int endX, out int endY);

        System.Text.StringBuilder builder = new System.Text.StringBuilder(1536);
        builder.Append("{dir=").Append(probeDirection)
            .Append(",end=").Append(endPosition)
            .Append(",endInGrid=").Append(endInGrid)
            .Append(",segment=");
        if (endInGrid)
            builder.Append(BuildLineDecisionSegmentDiagnostics(startPosition, endPosition, startX, startY, endX, endY, agentTypeId));
        else
            builder.Append("end-out");

        builder.Append(",flowSteps=[");
        int stepX = runtimeFlow.x > 0.35f ? 1 : runtimeFlow.x < -0.35f ? -1 : 0;
        int stepY = runtimeFlow.y > 0.35f ? 1 : runtimeFlow.y < -0.35f ? -1 : 0;
        if (stepX == 0 && stepY == 0)
        {
            builder.Append("none");
        }
        else
        {
            int previousX = startX;
            int previousY = startY;
            for (int step = 1; step <= 6; step++)
            {
                if (step > 1)
                    builder.Append(" -> ");
                int x = startX + stepX * step;
                int y = startY + stepY * step;
                AppendLineDecisionCell(builder, _world, x, y, previousX, previousY, first: false);
                previousX = x;
                previousY = y;
                if (x < 0 || x >= _world.Width || y < 0 || y >= _world.Height || !_world.IsWalkable(x, y))
                    break;
            }
        }

        builder.Append("]}");
        return builder.ToString();
    }

    private static string BuildStartPortalRankDiagnostics(
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        int agentTypeId,
        Vector3 startPosition,
        Vector3 stableGoalPosition,
        PathHandle handle = null)
    {
        if (_world == null)
            return "[FlowPortalRankDiag world=null]";
        if (startSectorId < 0 || startSectorId >= _world.Sectors.Length)
            return $"[FlowPortalRankDiag invalid-start-sector startSector={startSectorId}]";
        if (!TryGetCachedSharedGoalField(goalSectorId, goalX, goalY, ResolvePreferredAgentTypeId(agentTypeId), out SharedGoalField sharedField))
            return "[FlowPortalRankDiag shared-field-not-cached]";

        SectorData startSector = _world.Sectors[startSectorId];
        int selectedPortalId = ResolveSelectedPortalIdForDiagnostics(handle, startSectorId);
        int bestStartNodePortalId = -1;
        int bestFlowCrossingPortalId = -1;
        float bestFlowCrossingTotal = float.PositiveInfinity;
        int bestGridDistancePortalId = -1;
        float bestGridDistanceTotal = float.PositiveInfinity;
        List<string> candidates = new List<string>(startSector.PortalIds.Count);

        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            int portalId = startSector.PortalIds[i];
            int startNode = EncodePortalNode(startSectorId, portalId);
            long downstreamCostRaw = long.MaxValue;
            bool hasDownstream = sharedField.SettledPortalNodes.Contains(startNode)
                                 && sharedField.NodeCosts.TryGetValue(startNode, out downstreamCostRaw);
            float accessCost = ResolvePortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            float downstreamCost = DequantizeDeterministicPortalCost(downstreamCostRaw);
            float flowTotal = hasDownstream && !float.IsPositiveInfinity(accessCost)
                ? DequantizeDeterministicPortalCost(AddDeterministicPortalCosts(
                    QuantizeDeterministicPortalCost(accessCost, "diagnostic-flow-access"),
                    downstreamCostRaw))
                : float.PositiveInfinity;
            int firstCrossingPortalId = -1;
            bool hasCrossing = hasDownstream
                               && !float.IsPositiveInfinity(accessCost)
                               && TryResolveFirstCrossingPortalFromSharedGoalField(sharedField, startNode, startSectorId, goalSectorId, out firstCrossingPortalId);
            if (hasCrossing && flowTotal < bestFlowCrossingTotal)
            {
                bestFlowCrossingTotal = flowTotal;
                bestStartNodePortalId = portalId;
                bestFlowCrossingPortalId = firstCrossingPortalId;
            }

            float gridDistanceTotal = float.PositiveInfinity;
            float gridAccess = float.PositiveInfinity;
            float gridDownstream = float.PositiveInfinity;
            float gridTotal = float.PositiveInfinity;
            string portalStructure = "portal=missing";
            if (TryGetPortalById(_world, portalId, out PortalData portal))
            {
                Vector2Int[] currentCells = GetPortalCellsForSector(portal, startSectorId);
                Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, GetOppositeSectorId(portal, startSectorId));
                portalStructure = BuildPortalCandidateStructureDiagnostics(portal, startSectorId, currentCells, oppositeCells);
                Vector3 currentCenter = ResolveCellGroupCenter(currentCells);
                Vector3 oppositeCenter = ResolveCellGroupCenter(oppositeCells);
                float currentGridDistance = ResolveGridPathLengthOrInfinity(startPosition, currentCenter, agentTypeId)
                                   + ResolveGridPathLengthOrInfinity(currentCenter, stableGoalPosition, agentTypeId);
                float oppositeGridDistance = ResolveGridPathLengthOrInfinity(startPosition, oppositeCenter, agentTypeId)
                                    + ResolveGridPathLengthOrInfinity(oppositeCenter, stableGoalPosition, agentTypeId);
                gridDistanceTotal = Mathf.Min(currentGridDistance, oppositeGridDistance);
                gridAccess = ResolveGridPathCostToAnyOrInfinity(startX, startY, currentCells);
                gridDownstream = ResolveGridPathCostFromAnyToCellOrInfinity(oppositeCells, goalX, goalY);
                bool hasTraversablePortalPair = false;
                int pairCount = Mathf.Min(currentCells.Length, oppositeCells.Length);
                for (int pairIndex = 0; pairIndex < pairCount; pairIndex++)
                {
                    Vector2Int currentCell = currentCells[pairIndex];
                    Vector2Int oppositeCell = oppositeCells[pairIndex];
                    if (CanTraverseNeighborCells(_world, currentCell.x, currentCell.y, oppositeCell.x, oppositeCell.y))
                    {
                        hasTraversablePortalPair = true;
                        break;
                    }
                }

                if (hasTraversablePortalPair
                    && !float.IsPositiveInfinity(gridAccess)
                    && !float.IsPositiveInfinity(gridDownstream))
                {
                    gridTotal = gridAccess + ResolvePortalCrossingCost(portal) + gridDownstream;
                }
            }

            if (gridDistanceTotal < bestGridDistanceTotal)
            {
                bestGridDistanceTotal = gridDistanceTotal;
                bestGridDistancePortalId = portalId;
            }

            candidates.Add(
                "{id=" + portalId
                + ",selected=" + (portalId == selectedPortalId)
                + ",flowAccess=" + FormatDiagnosticCost(accessCost)
                + ",flowDownstream=" + (hasDownstream ? FormatDiagnosticCost(downstreamCost) : "missing")
                + ",flowTotal=" + FormatDiagnosticCost(flowTotal)
                + ",firstCrossing=" + (hasCrossing ? firstCrossingPortalId.ToString() : "missing")
                + ",gridDistanceTotal=" + FormatDiagnosticCost(gridDistanceTotal)
                + ",gridAccess=" + FormatDiagnosticCost(gridAccess)
                + ",gridDownstream=" + FormatDiagnosticCost(gridDownstream)
                + ",gridTotal=" + FormatDiagnosticCost(gridTotal)
                + "," + portalStructure
                + "}");
        }

        return "[FlowPortalRankDiag startSector=" + startSectorId
               + " goalSector=" + goalSectorId
               + " start=(" + startX + "," + startY + ")"
               + " goal=(" + goalX + "," + goalY + ")"
               + " selected=" + selectedPortalId
               + " bestFlowCrossing=" + bestFlowCrossingPortalId + ":" + FormatDiagnosticCost(bestFlowCrossingTotal)
               + " bestStartNode=" + bestStartNodePortalId
               + " bestGridDistance=" + bestGridDistancePortalId + ":" + FormatDiagnosticCost(bestGridDistanceTotal)
               + " handle=" + FormatPathHandle(handle)
               + " candidates=" + string.Join(" | ", candidates)
               + "]";
    }

    private static string BuildPortalCandidateStructureDiagnostics(
        PortalData portal,
        int sectorId,
        Vector2Int[] currentCells,
        Vector2Int[] oppositeCells)
    {
        if (_world == null)
            return "portalStruct=world-null";
        if (portal == null)
            return "portalStruct=null";
        if (currentCells == null || oppositeCells == null || currentCells.Length != oppositeCells.Length)
            return "portalStruct=side-mismatch";

        int pairCount = Mathf.Min(currentCells.Length, oppositeCells.Length);
        int traversablePairs = 0;
        int currentCostSum = 0;
        int oppositeCostSum = 0;
        int currentCostMax = 0;
        int oppositeCostMax = 0;
        int minCurrentAwayRun = int.MaxValue;
        int minOppositeAwayRun = int.MaxValue;
        int minCurrentLateralRun = int.MaxValue;
        int minOppositeLateralRun = int.MaxValue;
        System.Text.StringBuilder pairBuilder = new System.Text.StringBuilder(128);

        for (int i = 0; i < pairCount; i++)
        {
            Vector2Int currentCell = currentCells[i];
            Vector2Int oppositeCell = oppositeCells[i];
            bool traversable = CanTraverseNeighborCells(_world, currentCell.x, currentCell.y, oppositeCell.x, oppositeCell.y);
            if (traversable)
                traversablePairs++;

            int currentCost = GetCostFieldValueStrict(_world, currentCell.x, currentCell.y);
            int oppositeCost = GetCostFieldValueStrict(_world, oppositeCell.x, oppositeCell.y);
            currentCostSum += currentCost;
            oppositeCostSum += oppositeCost;
            currentCostMax = Mathf.Max(currentCostMax, currentCost);
            oppositeCostMax = Mathf.Max(oppositeCostMax, oppositeCost);

            int dx = Math.Sign(oppositeCell.x - currentCell.x);
            int dy = Math.Sign(oppositeCell.y - currentCell.y);
            int currentAwayRun = CountWalkableRun(currentCell.x, currentCell.y, -dx, -dy, 8);
            int oppositeAwayRun = CountWalkableRun(oppositeCell.x, oppositeCell.y, dx, dy, 8);
            int lateralDx = portal.IsVerticalBoundary ? 0 : 1;
            int lateralDy = portal.IsVerticalBoundary ? 1 : 0;
            int currentLateralRun = 1
                                    + CountWalkableRun(currentCell.x, currentCell.y, lateralDx, lateralDy, 8)
                                    + CountWalkableRun(currentCell.x, currentCell.y, -lateralDx, -lateralDy, 8);
            int oppositeLateralRun = 1
                                     + CountWalkableRun(oppositeCell.x, oppositeCell.y, lateralDx, lateralDy, 8)
                                     + CountWalkableRun(oppositeCell.x, oppositeCell.y, -lateralDx, -lateralDy, 8);
            minCurrentAwayRun = Mathf.Min(minCurrentAwayRun, currentAwayRun);
            minOppositeAwayRun = Mathf.Min(minOppositeAwayRun, oppositeAwayRun);
            minCurrentLateralRun = Mathf.Min(minCurrentLateralRun, currentLateralRun);
            minOppositeLateralRun = Mathf.Min(minOppositeLateralRun, oppositeLateralRun);

            if (i < 4)
            {
                if (pairBuilder.Length > 0)
                    pairBuilder.Append(';');
                pairBuilder.Append('i').Append(i)
                    .Append(":c=").Append(currentCell.x).Append(',').Append(currentCell.y)
                    .Append("/o=").Append(oppositeCell.x).Append(',').Append(oppositeCell.y)
                    .Append("/tc=").Append(traversable)
                    .Append("/cost=").Append(currentCost).Append(',').Append(oppositeCost)
                    .Append("/away=").Append(currentAwayRun).Append(',').Append(oppositeAwayRun)
                    .Append("/lat=").Append(currentLateralRun).Append(',').Append(oppositeLateralRun);
            }
        }

        float currentCostAvg = pairCount > 0 ? currentCostSum / (float)pairCount : float.PositiveInfinity;
        float oppositeCostAvg = pairCount > 0 ? oppositeCostSum / (float)pairCount : float.PositiveInfinity;
        return "portalWidth=" + portal.WidthCells
               + ",portalNarrow=" + portal.IsNarrow
               + ",portalCrossCost=" + FormatDiagnosticCost(ResolvePortalCrossingCost(portal))
               + ",travPairs=" + traversablePairs + "/" + pairCount
               + ",avgCost=" + FormatDiagnosticCost(currentCostAvg) + "/" + FormatDiagnosticCost(oppositeCostAvg)
               + ",maxCost=" + currentCostMax + "/" + oppositeCostMax
               + ",minAwayRun=" + (minCurrentAwayRun == int.MaxValue ? "NA" : minCurrentAwayRun.ToString()) + "/" + (minOppositeAwayRun == int.MaxValue ? "NA" : minOppositeAwayRun.ToString())
               + ",minLatRun=" + (minCurrentLateralRun == int.MaxValue ? "NA" : minCurrentLateralRun.ToString()) + "/" + (minOppositeLateralRun == int.MaxValue ? "NA" : minOppositeLateralRun.ToString())
               + ",pairs=[" + pairBuilder + "]";
    }

    private static int CountWalkableRun(int startX, int startY, int stepX, int stepY, int maxSteps)
    {
        if (_world == null)
            throw new InvalidOperationException("CountWalkableRun failed: world is null.");
        return CountWalkableRun(_world, startX, startY, stepX, stepY, maxSteps);
    }

    private static int CountWalkableRun(NavigationWorld world, int startX, int startY, int stepX, int stepY, int maxSteps)
    {
        if (world == null)
            throw new InvalidOperationException("CountWalkableRun failed: world is null.");
        if (stepX == 0 && stepY == 0)
            return 0;

        int count = 0;
        for (int i = 1; i <= maxSteps; i++)
        {
            int x = startX + stepX * i;
            int y = startY + stepY * i;
            if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
                break;
            if (!world.IsWalkable(x, y))
                break;
            if (!CanTraverseNeighborCells(world, x - stepX, y - stepY, x, y))
                break;

            count++;
        }

        return count;
    }

    private static float ResolveGridPathCostToAnyOrInfinity(int startX, int startY, Vector2Int[] goalCells)
    {
        if (_world == null || goalCells == null || goalCells.Length == 0)
            return float.PositiveInfinity;
        if (startX < 0 || startX >= _world.Width || startY < 0 || startY >= _world.Height || !_world.IsWalkable(startX, startY))
            return float.PositiveInfinity;

        bool[] targets = new bool[_world.Width * _world.Height];
        bool hasTarget = false;
        for (int i = 0; i < goalCells.Length; i++)
        {
            Vector2Int cell = goalCells[i];
            if (cell.x < 0 || cell.x >= _world.Width || cell.y < 0 || cell.y >= _world.Height || !_world.IsWalkable(cell.x, cell.y))
                continue;

            targets[_world.GetIndex(cell.x, cell.y)] = true;
            hasTarget = true;
        }

        if (!hasTarget)
            return float.PositiveInfinity;

        return ResolveGridPathCostToTargetsOrInfinity(startX, startY, targets);
    }

    private static float ResolveGridPathCostFromAnyToCellOrInfinity(Vector2Int[] startCells, int goalX, int goalY)
    {
        if (_world == null || startCells == null || startCells.Length == 0)
            return float.PositiveInfinity;

        float best = float.PositiveInfinity;
        for (int i = 0; i < startCells.Length; i++)
        {
            Vector2Int start = startCells[i];
            float cost = ResolveGridPathCostOrInfinity(start.x, start.y, goalX, goalY);
            if (cost < best)
                best = cost;
        }

        return best;
    }

    private static float ResolveGridPathCostOrInfinity(int startX, int startY, int goalX, int goalY)
    {
        if (_world == null)
            return float.PositiveInfinity;
        if (goalX < 0 || goalX >= _world.Width || goalY < 0 || goalY >= _world.Height || !_world.IsWalkable(goalX, goalY))
            return float.PositiveInfinity;

        bool[] targets = new bool[_world.Width * _world.Height];
        targets[_world.GetIndex(goalX, goalY)] = true;
        return ResolveGridPathCostToTargetsOrInfinity(startX, startY, targets);
    }

    private static float ResolveGridPathCostToTargetsOrInfinity(int startX, int startY, bool[] targets)
    {
        if (_world == null || targets == null || targets.Length != _world.Width * _world.Height)
            return float.PositiveInfinity;
        if (startX < 0 || startX >= _world.Width || startY < 0 || startY >= _world.Height || !_world.IsWalkable(startX, startY))
            return float.PositiveInfinity;

        int startIndex = _world.GetIndex(startX, startY);
        if (targets[startIndex])
            return 0f;

        float[] costs = RentIntegrationArray(_world.Width * _world.Height);
        InitializeIntegrationField(costs);
        MinHeap openSet = new MinHeap();
        costs[startIndex] = 0f;
        openSet.Push(startIndex, 0f);
        int guard = _world.Width * _world.Height * 4;
        try
        {
            while (openSet.Count > 0 && guard-- > 0)
            {
                QueueNode node = openSet.Pop();
                if (node.Cost > costs[node.Index] + 0.001f)
                    continue;
                if (targets[node.Index])
                    return node.Cost;

                int worldX = node.Index % _world.Width;
                int worldY = node.Index / _world.Width;
                for (int i = 0; i < NeighborOffsetX.Length; i++)
                {
                    int nextX = worldX + NeighborOffsetX[i];
                    int nextY = worldY + NeighborOffsetY[i];
                    if (nextX < 0 || nextX >= _world.Width || nextY < 0 || nextY >= _world.Height)
                        continue;
                    if (!_world.IsWalkable(nextX, nextY) || !CanTraverseNeighborCells(_world, worldX, worldY, nextX, nextY))
                        continue;

                    int nextIndex = _world.GetIndex(nextX, nextY);
                    float stepDistance = Mathf.Abs(NeighborOffsetX[i]) + Mathf.Abs(NeighborOffsetY[i]) == 2 ? 1.4142135f : 1f;
                    float stepCost = Mathf.Max(ResolveCellIntegrationCost(_world, nextX, nextY), 0.001f) * stepDistance;
                    float newCost = node.Cost + stepCost;
                    if (!IsSignificantIntegrationImprovement(newCost, costs[nextIndex]))
                        continue;

                    costs[nextIndex] = newCost;
                    openSet.Push(nextIndex, newCost);
                }
            }
        }
        finally
        {
            ReturnIntegrationArray(costs);
        }

        return float.PositiveInfinity;
    }

    private static float ResolveGridPathLengthOrInfinity(Vector3 fromPosition, Vector3 toPosition, int agentTypeId)
    {
        if (_world == null)
            return float.PositiveInfinity;
        return TryEstimateNavigationDistance(fromPosition, toPosition, agentTypeId >= 0 ? agentTypeId : _world.AgentTypeId, out float distance)
            ? distance
            : float.PositiveInfinity;
    }

    private static string FormatDiagnosticCost(float cost)
    {
        return float.IsPositiveInfinity(cost) ? "INF" : cost.ToString("F3");
    }

    private static string BuildPathRepathDecisionDiagnostics(PathHandle handle, int startSectorId, int goalSectorId, int startX, int startY, int goalX, int goalY)
    {
        if (_world == null)
            return "world=null";
        if (handle == null)
            return "handle=null";
        if (startSectorId < 0 || startSectorId >= _world.Sectors.Length)
            return "invalid-start-sector";
        if (handle.PortalIds == null || handle.PortalIds.Length == 0)
            return "no-portals";

        int sectorIndex = FindSectorIndex(handle, startSectorId, Mathf.Max(0, handle.CurrentSectorIndex));
        if (sectorIndex < 0)
            return "start-sector-not-in-handle";
        if (sectorIndex >= handle.PortalIds.Length)
            return "final-sector";

        int selectedPortalId = handle.PortalIds[sectorIndex];
        int sharedAgentTypeId = ResolvePreferredAgentTypeId(_world.AgentTypeId);
        bool sharedCached = TryGetCachedSharedGoalField(goalSectorId, goalX, goalY, sharedAgentTypeId, out SharedGoalField sharedField);
        bool pending = PendingSharedGoalFieldBuildJobs.Contains(CreateSharedGoalFieldKey(goalSectorId, goalX, goalY, sharedAgentTypeId));
        if (!sharedCached)
        {
            return "selected=" + selectedPortalId
                   + " sharedCached=False pending=" + pending
                   + " queue=" + SharedGoalFieldBuildQueue.Count;
        }

        SectorData startSector = _world.Sectors[startSectorId];
        int bestPortalId = -1;
        int bestStartNodePortalId = -1;
        float selectedCost = float.PositiveInfinity;
        float bestCost = float.PositiveInfinity;
        System.Text.StringBuilder candidates = new System.Text.StringBuilder(256);
        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            int portalId = startSector.PortalIds[i];
            int startNode = EncodePortalNode(startSectorId, portalId);
            long downstreamCostRaw = long.MaxValue;
            bool hasDownstream = sharedField.SettledPortalNodes.Contains(startNode)
                                 && sharedField.NodeCosts.TryGetValue(startNode, out downstreamCostRaw);
            float accessCost = ResolvePortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            float downstreamCost = DequantizeDeterministicPortalCost(downstreamCostRaw);
            float totalCost = hasDownstream && !float.IsPositiveInfinity(accessCost)
                ? DequantizeDeterministicPortalCost(AddDeterministicPortalCosts(
                    QuantizeDeterministicPortalCost(accessCost, "diagnostic-repath-access"),
                    downstreamCostRaw))
                : float.PositiveInfinity;
            int firstCrossingPortalId = -1;
            bool hasCrossing = hasDownstream
                               && !float.IsPositiveInfinity(accessCost)
                               && TryResolveFirstCrossingPortalFromSharedGoalField(sharedField, startNode, startSectorId, goalSectorId, out firstCrossingPortalId);
            if (hasCrossing && firstCrossingPortalId == selectedPortalId && totalCost < selectedCost)
                selectedCost = totalCost;
            if (hasCrossing && totalCost < bestCost)
            {
                bestCost = totalCost;
                bestPortalId = firstCrossingPortalId;
                bestStartNodePortalId = portalId;
            }

            if (i > 0)
                candidates.Append(" | ");
            candidates.Append(portalId)
                .Append(":a=").Append(FormatDiagnosticCost(accessCost))
                .Append(",d=").Append(hasDownstream ? FormatDiagnosticCost(downstreamCost) : "missing")
                .Append(",t=").Append(FormatDiagnosticCost(totalCost))
                .Append(",firstCrossing=").Append(hasCrossing ? firstCrossingPortalId.ToString() : "missing");
        }

        bool shouldRebuild = selectedPortalId != bestPortalId
                             && selectedCost > bestCost + IntegrationSignificantImprovement;
        return "selected=" + selectedPortalId + ":" + FormatDiagnosticCost(selectedCost)
               + " best=" + bestPortalId + ":" + FormatDiagnosticCost(bestCost)
               + " bestStartNode=" + bestStartNodePortalId
               + " threshold=" + IntegrationSignificantImprovement.ToString("F3")
               + " shouldRebuild=" + shouldRebuild
               + " sharedNodes=" + sharedField.NodeCosts.Count
               + " candidates=[" + candidates + "]";
    }

    private static string BuildStartPortalChoiceDiagnostics(
        int startSectorId,
        int goalSectorId,
        int startX,
        int startY,
        int goalX,
        int goalY,
        int agentTypeId,
        Vector3 startPosition,
        Vector3 stableGoalPosition,
        PathHandle handle = null)
    {
        if (_world == null)
            return "portalChoice=world-null";
        if (startSectorId < 0 || startSectorId >= _world.Sectors.Length)
            return $"portalChoice=invalid-start-sector startSector={startSectorId}";

        if (!TryGetCachedSharedGoalField(goalSectorId, goalX, goalY, ResolvePreferredAgentTypeId(agentTypeId), out SharedGoalField sharedField))
            return "portalChoice=shared-field-not-cached";

        SectorData startSector = _world.Sectors[startSectorId];
        System.Text.StringBuilder builder = new System.Text.StringBuilder(1024);
        int selectedPortalId = ResolveSelectedPortalIdForDiagnostics(handle, startSectorId);
        builder.Append("[FlowStartPortalChoiceDiag startSector=").Append(startSectorId)
            .Append(" goalSector=").Append(goalSectorId)
            .Append(" start=(").Append(startX).Append(',').Append(startY).Append(')')
            .Append(" goal=(").Append(goalX).Append(',').Append(goalY).Append(')')
            .Append(" selectedPortal=").Append(selectedPortalId)
            .Append(" handle=").Append(FormatPathHandle(handle))
            .Append(" portals=");

        if (startSector.PortalIds.Count == 0)
        {
            builder.Append("none]");
            return builder.ToString();
        }

        for (int i = 0; i < startSector.PortalIds.Count; i++)
        {
            if (i > 0)
                builder.Append(" | ");

            int portalId = startSector.PortalIds[i];
            int startNode = EncodePortalNode(startSectorId, portalId);
            long downstreamCostRaw = long.MaxValue;
            bool hasDownstream = sharedField.SettledPortalNodes.Contains(startNode)
                                 && sharedField.NodeCosts.TryGetValue(startNode, out downstreamCostRaw);
            float accessCost = ResolvePortalAccessCost(startSector, startSectorId, portalId, startX, startY);
            float downstreamCost = DequantizeDeterministicPortalCost(downstreamCostRaw);
            float totalCost = hasDownstream && !float.IsPositiveInfinity(accessCost)
                ? DequantizeDeterministicPortalCost(AddDeterministicPortalCosts(
                    QuantizeDeterministicPortalCost(accessCost, "diagnostic-start-choice-access"),
                    downstreamCostRaw))
                : float.PositiveInfinity;
            PortalData portal = TryGetPortalById(_world, portalId, out PortalData portalData) ? portalData : null;
            int oppositeSector = portal != null ? GetOppositeSectorId(portal, startSectorId) : -1;
            Vector2Int[] cells = portal != null ? GetPortalCellsForSector(portal, startSectorId) : null;
            Vector3 center = portal != null ? portal.WorldCenter : Vector3.zero;
            string portalNav = portal != null
                ? BuildPortalCandidateNavDiagnostics(startPosition, stableGoalPosition, portal, startSectorId, agentTypeId)
                : "portal=null";
            builder.Append("{id=").Append(portalId)
                .Append(",selected=").Append(portalId == selectedPortalId)
                .Append(",opp=").Append(oppositeSector)
                .Append(",access=").Append(float.IsPositiveInfinity(accessCost) ? "INF" : accessCost.ToString("F3"))
                .Append(",downstream=").Append(hasDownstream ? downstreamCost.ToString("F3") : "missing")
                .Append(",total=").Append(float.IsPositiveInfinity(totalCost) ? "INF" : totalCost.ToString("F3"))
                .Append(",center=").Append(center)
                .Append(",cells=").Append(FormatGoalCells(cells))
                .Append(",nav=").Append(portalNav)
                .Append('}');
        }

        builder.Append("]");
        return builder.ToString();
    }

    private static int ResolveSelectedPortalIdForDiagnostics(PathHandle handle, int startSectorId)
    {
        if (handle == null || handle.SectorIds == null || handle.PortalIds == null)
            return -1;

        int index = FindSectorIndex(handle, startSectorId, Mathf.Max(0, handle.CurrentSectorIndex));
        if (index < 0 || index >= handle.PortalIds.Length)
            return -1;

        return handle.PortalIds[index];
    }

    private static string BuildPortalCandidateNavDiagnostics(Vector3 startPosition, Vector3 stableGoalPosition, PortalData portal, int sectorId, int agentTypeId)
    {
        Vector2Int[] currentCells = GetPortalCellsForSector(portal, sectorId);
        Vector2Int[] oppositeCells = GetPortalCellsForSector(portal, GetOppositeSectorId(portal, sectorId));
        Vector3 currentCenter = ResolveCellGroupCenter(currentCells);
        Vector3 oppositeCenter = ResolveCellGroupCenter(oppositeCells);
        string toCurrent = BuildGridPathDiagnostics(startPosition, currentCenter, agentTypeId);
        string toOpposite = BuildGridPathDiagnostics(startPosition, oppositeCenter, agentTypeId);
        string currentToGoal = BuildGridPathDiagnostics(currentCenter, stableGoalPosition, agentTypeId);
        string oppositeToGoal = BuildGridPathDiagnostics(oppositeCenter, stableGoalPosition, agentTypeId);
        bool startInGrid = _world.WorldToGrid(startPosition, out int startX, out int startY);
        bool gridLosCurrent = startInGrid
                              && currentCells.Length > 0
                              && HasGridLineOfSight(_world, startX, startY, currentCells[0].x, currentCells[0].y);
        string losTrace = currentCells.Length > 0 && startInGrid
            ? BuildLineOfSightCellTrace(_world, startX, startY, currentCells[0].x, currentCells[0].y)
            : "trace=unavailable";
        return "{currentCenter=" + currentCenter
               + ",oppositeCenter=" + oppositeCenter
               + ",gridLosFirstCell=" + gridLosCurrent
               + ",losTrace=" + losTrace
               + ",toCurrent=" + toCurrent
               + ",toOpposite=" + toOpposite
               + ",currentToGoal=" + currentToGoal
               + ",oppositeToGoal=" + oppositeToGoal
               + "}";
    }

    private static string BuildFlowLineOfSightDecisionDiagnostics(
        Vector3 startPosition,
        Vector3 stableGoalPosition,
        Vector3 tileTargetPosition,
        int startX,
        int startY,
        int goalX,
        int goalY,
        int agentTypeId,
        FlowTileCacheEntry tile)
    {
        System.Text.StringBuilder builder = new System.Text.StringBuilder(2048);
        builder.Append("[FlowLosDecision goal=")
            .Append(BuildLineDecisionSegmentDiagnostics(startPosition, stableGoalPosition, startX, startY, goalX, goalY, agentTypeId))
            .Append(" tileTarget=");

        if (_world != null && _world.WorldToGrid(tileTargetPosition, out int tileTargetX, out int tileTargetY))
        {
            builder.Append(BuildLineDecisionSegmentDiagnostics(startPosition, tileTargetPosition, startX, startY, tileTargetX, tileTargetY, agentTypeId));
        }
        else
        {
            builder.Append("{targetInGrid=False targetPos=").Append(tileTargetPosition).Append('}');
        }

        if (tile != null && tile.Key.GoalKind == TileGoalKind.Portal)
        {
            PortalData portal = GetPortalById(_world, tile.Key.GoalId);
            Vector2Int[] cells = GetPortalCellsForSector(portal, tile.Key.SectorId);
            builder.Append(" portalCells=[");
            for (int i = 0; i < cells.Length; i++)
            {
                if (i > 0)
                    builder.Append(" | ");
                Vector2Int cell = cells[i];
                builder.Append('i').Append(i).Append('=')
                    .Append(BuildLineDecisionSegmentDiagnostics(startPosition, _world.GridToWorldCenter(cell.x, cell.y), startX, startY, cell.x, cell.y, agentTypeId));
            }
            builder.Append(']');
        }

        builder.Append(']');
        return builder.ToString();
    }

    private static string BuildLineDecisionSegmentDiagnostics(
        Vector3 fromPosition,
        Vector3 toPosition,
        int fromX,
        int fromY,
        int toX,
        int toY,
        int agentTypeId)
    {
        if (_world == null)
            return "{world=null}";

        bool toInBounds = toX >= 0 && toX < _world.Width && toY >= 0 && toY < _world.Height;
        bool strictGridLos = toInBounds && HasGridLineOfSight(_world, fromX, fromY, toX, toY);
        bool pendingGridLos = toInBounds && HasPendingDirectLineOfSight(_world, fromX, fromY, toX, toY);
        bool softGridLos = toInBounds && HasSoftCostTolerantGridLineOfSight(_world, fromX, fromY, toX, toY, maxAllowedCost: 15);
        return "{from=(" + fromX + "," + fromY + ")"
               + ",to=(" + toX + "," + toY + ")"
               + ",toInBounds=" + toInBounds
               + ",strictGridLos=" + strictGridLos
               + ",pendingGridLos=" + pendingGridLos
               + ",softGridLos=" + softGridLos
               + ",trace=" + BuildLineOfSightDecisionCellTrace(_world, fromX, fromY, toX, toY)
               + ",registeredObstacles=" + BuildRegisteredObstacleSegmentDiagnostics(fromPosition, toPosition)
               + ",physics=" + BuildPhysicsSegmentDiagnostics(fromPosition, toPosition, agentTypeId)
               + "}";
    }

    private static string BuildLineOfSightDecisionCellTrace(NavigationWorld world, int x0, int y0, int x1, int y1)
    {
        if (world == null)
            return "world-null";
        if (x0 < 0 || x0 >= world.Width || y0 < 0 || y0 >= world.Height)
            return "start-out";
        if (x1 < 0 || x1 >= world.Width || y1 < 0 || y1 >= world.Height)
            return "target-out";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(768);
        builder.Append("[");
        int dx = Mathf.Abs(x1 - x0);
        int dy = Mathf.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1;
        int sy = y0 < y1 ? 1 : -1;
        int err = dx - dy;
        int cx = x0;
        int cy = y0;
        int previousX = x0;
        int previousY = y0;
        bool first = true;
        int count = 0;
        const int maxCells = 96;

        while (true)
        {
            if (count > 0)
                builder.Append(" -> ");

            AppendLineDecisionCell(builder, world, cx, cy, previousX, previousY, first);
            count++;

            if (cx == x1 && cy == y1)
                break;
            if (count >= maxCells)
            {
                builder.Append(" -> truncated");
                break;
            }

            previousX = cx;
            previousY = cy;
            first = false;
            int e2 = err * 2;
            if (e2 > -dy)
            {
                err -= dy;
                cx += sx;
            }

            if (e2 < dx)
            {
                err += dx;
                cy += sy;
            }
        }

        builder.Append("]");
        return builder.ToString();
    }

    private static void AppendLineDecisionCell(System.Text.StringBuilder builder, NavigationWorld world, int x, int y, int previousX, int previousY, bool first)
    {
        bool inBounds = x >= 0 && x < world.Width && y >= 0 && y < world.Height;
        builder.Append("(").Append(x).Append(',').Append(y).Append(")");
        if (!inBounds)
        {
            builder.Append("{out}");
            return;
        }

        int index = world.GetIndex(x, y);
        bool walkable = world.WalkableMask != null && world.WalkableMask.Length == world.Width * world.Height && world.WalkableMask[index];
        bool baseWalkable = world.BaseWalkableMask != null && world.BaseWalkableMask.Length == world.Width * world.Height && world.BaseWalkableMask[index];
        int cost = TryGetCostFieldValue(world, x, y, out byte resolvedCost) ? resolvedCost : -1;
        int island = world.IslandIds != null && world.IslandIds.Length == world.Width * world.Height ? world.IslandIds[index] : -1;
        bool link = first || CanTraverseNeighborCells(world, previousX, previousY, x, y);
        bool softBoundary = walkable && cost > 1 && IsBoundaryOnlySoftCostCell(world, x, y);
        bool costStamp = walkable && IsCellAffectedByCostStamp(world, x, y);
        builder.Append("{walk=").Append(walkable)
            .Append(",base=").Append(baseWalkable)
            .Append(",cost=").Append(cost)
            .Append(",softBoundary=").Append(softBoundary)
            .Append(",costStamp=").Append(costStamp)
            .Append(",island=").Append(island)
            .Append(",link=").Append(link)
            .Append("}");
    }

    private static string BuildRegisteredObstacleSegmentDiagnostics(Vector3 fromPosition, Vector3 toPosition)
    {
        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append("[boxes=");
        int count = 0;
        foreach (BoxObstacle box in BoxObstacles.Values)
        {
            Vector3 half = box.HalfExtents;
            if (!TryMeasureSegmentBoxDistance(fromPosition, toPosition, box.Center, half, out float distance, out Vector3 closestPoint))
                continue;
            float inflatedDistance = distance - Mathf.Max(0f, half.x > half.z ? half.x : half.z);
            if (distance > Mathf.Max(_world.CellSize * 4f, 2f))
                continue;

            if (count > 0)
                builder.Append(" | ");
            builder.Append("{id=").Append(box.Id)
                .Append(",center=").Append(box.Center)
                .Append(",half=").Append(box.HalfExtents)
                .Append(",dist=").Append(distance.ToString("F3"))
                .Append(",inflatedDist=").Append(inflatedDistance.ToString("F3"))
                .Append(",closest=").Append(closestPoint)
                .Append(",grid=").Append(FormatBoundsGridRange(new Bounds(box.Center, box.HalfExtents * 2f)))
                .Append("}");
            count++;
            if (count >= 8)
            {
                builder.Append(" | truncated");
                break;
            }
        }

        if (count == 0)
            builder.Append("none");
        builder.Append(" circles=");
        count = 0;
        foreach (CircleObstacle circle in CircleObstacles.Values)
        {
            if (!TryMeasureSegmentCircleDistance(fromPosition, toPosition, circle.Position, circle.Radius, out float distance, out Vector3 closestPoint))
                continue;
            if (distance > Mathf.Max(_world.CellSize * 4f, 2f))
                continue;

            if (count > 0)
                builder.Append(" | ");
            builder.Append("{id=").Append(circle.Id)
                .Append(",center=").Append(circle.Position)
                .Append(",radius=").Append(circle.Radius.ToString("F3"))
                .Append(",dist=").Append(distance.ToString("F3"))
                .Append(",closest=").Append(closestPoint)
                .Append("}");
            count++;
            if (count >= 8)
            {
                builder.Append(" | truncated");
                break;
            }
        }

        if (count == 0)
            builder.Append("none");
        builder.Append(" nearestBoxes=");
        AppendNearestRegisteredBoxes(builder, fromPosition, toPosition);
        builder.Append(']');
        return builder.ToString();
    }

    private static void AppendNearestRegisteredBoxes(System.Text.StringBuilder builder, Vector3 fromPosition, Vector3 toPosition)
    {
        const int maxNearest = 5;
        int[] nearestIds = new int[maxNearest];
        float[] nearestDistances = new float[maxNearest];
        Vector3[] nearestCenters = new Vector3[maxNearest];
        Vector3[] nearestHalfExtents = new Vector3[maxNearest];
        string[] nearestGrids = new string[maxNearest];
        for (int i = 0; i < maxNearest; i++)
        {
            nearestIds[i] = 0;
            nearestDistances[i] = float.PositiveInfinity;
            nearestCenters[i] = Vector3.zero;
            nearestHalfExtents[i] = Vector3.zero;
            nearestGrids[i] = "none";
        }

        foreach (BoxObstacle box in BoxObstacles.Values)
        {
            if (!TryMeasureSegmentBoxDistance(fromPosition, toPosition, box.Center, box.HalfExtents, out float distance, out _))
                continue;

            for (int i = 0; i < maxNearest; i++)
            {
                if (distance >= nearestDistances[i])
                    continue;

                for (int j = maxNearest - 1; j > i; j--)
                {
                    nearestIds[j] = nearestIds[j - 1];
                    nearestDistances[j] = nearestDistances[j - 1];
                    nearestCenters[j] = nearestCenters[j - 1];
                    nearestHalfExtents[j] = nearestHalfExtents[j - 1];
                    nearestGrids[j] = nearestGrids[j - 1];
                }

                nearestIds[i] = box.Id;
                nearestDistances[i] = distance;
                nearestCenters[i] = box.Center;
                nearestHalfExtents[i] = box.HalfExtents;
                nearestGrids[i] = FormatBoundsGridRange(new Bounds(box.Center, box.HalfExtents * 2f))
                    + "/nav=" + FormatBoundsGridRange(ResolveBoxObstacleNavigationBounds(_world, box));
                break;
            }
        }

        if (float.IsPositiveInfinity(nearestDistances[0]))
        {
            builder.Append("none");
            return;
        }

        for (int i = 0; i < maxNearest; i++)
        {
            if (float.IsPositiveInfinity(nearestDistances[i]))
                break;
            if (i > 0)
                builder.Append(" | ");
            builder.Append("{id=").Append(nearestIds[i])
                .Append(",center=").Append(nearestCenters[i])
                .Append(",half=").Append(nearestHalfExtents[i])
                .Append(",dist=").Append(nearestDistances[i].ToString("F3"))
                .Append(",grid=").Append(nearestGrids[i])
                .Append("}");
        }
    }

    private static bool TryMeasureSegmentBoxDistance(Vector3 segmentStart, Vector3 segmentEnd, Vector3 center, Vector3 halfExtents, out float distance, out Vector3 closestPoint)
    {
        Vector3 segment = segmentEnd - segmentStart;
        segment.y = 0f;
        float lengthSq = segment.sqrMagnitude;
        if (lengthSq <= 0.0001f)
        {
            distance = float.PositiveInfinity;
            closestPoint = segmentStart;
            return false;
        }

        Vector3 centerOffset = center - segmentStart;
        centerOffset.y = 0f;
        float t = Mathf.Clamp01(Vector3.Dot(centerOffset, segment) / lengthSq);
        closestPoint = segmentStart + segment * t;
        Vector3 closestOnBox = new Vector3(
            Mathf.Clamp(closestPoint.x, center.x - halfExtents.x, center.x + halfExtents.x),
            closestPoint.y,
            Mathf.Clamp(closestPoint.z, center.z - halfExtents.z, center.z + halfExtents.z));
        Vector3 delta = closestPoint - closestOnBox;
        delta.y = 0f;
        distance = delta.magnitude;
        return true;
    }

    private static bool TryMeasureSegmentCircleDistance(Vector3 segmentStart, Vector3 segmentEnd, Vector3 center, float radius, out float distance, out Vector3 closestPoint)
    {
        Vector3 segment = segmentEnd - segmentStart;
        segment.y = 0f;
        float lengthSq = segment.sqrMagnitude;
        if (lengthSq <= 0.0001f)
        {
            distance = float.PositiveInfinity;
            closestPoint = segmentStart;
            return false;
        }

        Vector3 centerOffset = center - segmentStart;
        centerOffset.y = 0f;
        float t = Mathf.Clamp01(Vector3.Dot(centerOffset, segment) / lengthSq);
        closestPoint = segmentStart + segment * t;
        Vector3 delta = closestPoint - center;
        delta.y = 0f;
        distance = Mathf.Max(0f, delta.magnitude - radius);
        return true;
    }

    private static string BuildPhysicsSegmentDiagnostics(Vector3 fromPosition, Vector3 toPosition, int agentTypeId)
    {
        Vector3 start = fromPosition + Vector3.up * 0.5f;
        Vector3 end = toPosition + Vector3.up * 0.5f;
        Vector3 delta = end - start;
        float distance = delta.magnitude;
        if (distance <= 0.0001f)
            return "{empty}";

        Vector3 direction = delta / distance;
        RaycastHit[] hits = Physics.RaycastAll(start, direction, distance, ~0, QueryTriggerInteraction.Ignore);
        Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));
        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append("{agentType=").Append(agentTypeId).Append(",hits=");
        int count = 0;
        for (int i = 0; i < hits.Length; i++)
        {
            Collider collider = hits[i].collider;
            if (collider == null)
                continue;
            if (count > 0)
                builder.Append(" | ");
            builder.Append("{name=").Append(collider.name)
                .Append(",layer=").Append(LayerMask.LayerToName(collider.gameObject.layer))
                .Append(",dist=").Append(hits[i].distance.ToString("F3"))
                .Append(",point=").Append(hits[i].point)
                .Append(",normal=").Append(hits[i].normal)
                .Append("}");
            count++;
            if (count >= 8)
            {
                builder.Append(" | truncated");
                break;
            }
        }

        if (count == 0)
            builder.Append("none");
        builder.Append('}');
        return builder.ToString();
    }

    private static Vector3 ResolveCellGroupCenter(Vector2Int[] cells)
    {
        if (cells == null || cells.Length == 0)
            return Vector3.zero;

        Vector3 center = Vector3.zero;
        for (int i = 0; i < cells.Length; i++)
            center += _world.GridToWorldCenter(cells[i].x, cells[i].y);
        return center / cells.Length;
    }

    private static string FormatPortal(PortalData portal)
    {
        if (portal == null)
            return "null";

        return $"(id={portal.PortalId},sectorA={portal.SectorAId},sectorB={portal.SectorBId},vertical={portal.IsVerticalBoundary},width={portal.WidthCells},narrow={portal.IsNarrow},cellsA={FormatGoalCells(portal.CellsA)},cellsB={FormatGoalCells(portal.CellsB)})";
    }

    private static string FormatIntegrationCosts(FlowTileCacheEntry tile, Vector2Int[] cells)
    {
        if (tile == null)
            return "tile=null";
        if (cells == null || cells.Length == 0)
            return "[]";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(cells.Length * 24);
        builder.Append('[');
        for (int i = 0; i < cells.Length; i++)
        {
            if (i > 0)
                builder.Append(", ");

            Vector2Int cell = cells[i];
            builder.Append('(');
            builder.Append(cell.x);
            builder.Append(',');
            builder.Append(cell.y);
            builder.Append(")=");

            if (!IsInsideSector(tile, cell.x, cell.y))
            {
                builder.Append("outside");
                continue;
            }

            float cost = GetTileIntegrationCostForDiagnostics(tile, cell.x, cell.y);
            builder.Append(float.IsPositiveInfinity(cost) ? "INF" : cost.ToString("F3"));
        }

        builder.Append(']');
        return builder.ToString();
    }

    private static string FormatSectorPortalAccessCosts(SectorData sector, int sectorId, int portalId, Vector2Int[] cells)
    {
        if (sector == null)
            return "sector=null";
        if (portalId < 0)
            return "portal=none";
        if (cells == null || cells.Length == 0)
            return "[]";

        SectorPortalAccessEntry entry = GetPrebuiltSectorPortalAccess(sector, sectorId, portalId);
        System.Text.StringBuilder builder = new System.Text.StringBuilder(cells.Length * 24);
        builder.Append('[');
        for (int i = 0; i < cells.Length; i++)
        {
            if (i > 0)
                builder.Append(", ");

            Vector2Int cell = cells[i];
            builder.Append('(');
            builder.Append(cell.x);
            builder.Append(',');
            builder.Append(cell.y);
            builder.Append(")=");

            if (!IsInsideSector(sector, cell.x, cell.y))
            {
                builder.Append("outside");
                continue;
            }

            float cost = ResolvePortalAccessIntegrationCost(_world, sector, entry, cell.x, cell.y);
            builder.Append(float.IsPositiveInfinity(cost) ? "INF" : cost.ToString("F3"));
        }

        builder.Append(']');
        return builder.ToString();
    }

    private static string DescribeTileIntegrationSummary(FlowTileCacheEntry tile)
    {
        if (tile == null)
            return "tile=null";
        if (tile.DeterministicIntegrationCosts == null)
            return "deterministic-cost=null";
        int reachableCount = 0;
        for (int i = 0; i < tile.DeterministicIntegrationCosts.Length; i++)
        {
            if (tile.DeterministicIntegrationCosts[i] != int.MaxValue)
                reachableCount++;
        }
        return $"deterministicReachable={reachableCount} cells={tile.DeterministicIntegrationCosts.Length} debugPayload={tile.DebugIntegrationPayload?.Values != null}";
    }

    private static int CountReachableFlowCells(FlowTileCacheEntry tile)
    {
        if (tile?.FlowFieldValues == null)
            return 0;

        int count = 0;
        for (int i = 0; i < tile.FlowFieldValues.Length; i++)
        {
            if (IsFlowReachable(tile, i))
                count++;
        }

        return count;
    }

    private static bool TryResolveGridEdgeData(Vector3 position, Vector3 desiredDirection, out Vector3 edgeNormal, out float edgeDistance)
    {
        if (_world == null)
            throw new InvalidOperationException("TryResolveGridEdgeData failed: world is null.");

        return TryResolveGridEdgeData(position, desiredDirection, _world.CellSize * 1.5f, out edgeNormal, out edgeDistance);
    }

    private static bool TryResolveGridEdgeData(Vector3 position, Vector3 desiredDirection, float probeDistance, out Vector3 edgeNormal, out float edgeDistance)
    {
        edgeNormal = Vector3.zero;
        edgeDistance = float.MaxValue;

        if (_world == null)
            throw new InvalidOperationException("TryResolveGridEdgeData failed: world is null.");

        if (!_world.WorldToGrid(position, out int cellX, out int cellY))
            return false;

        Vector3 accumulatedNormal = Vector3.zero;
        probeDistance = Mathf.Max(_world.CellSize * 1.5f, probeDistance);
        int radius = Mathf.CeilToInt(probeDistance / Mathf.Max(_world.CellSize, 0.001f));
        for (int y = cellY - radius; y <= cellY + radius; y++)
        {
            for (int x = cellX - radius; x <= cellX + radius; x++)
            {
                if (_world.IsWalkable(x, y))
                    continue;

                float minX = _world.Origin.x + x * _world.CellSize;
                float maxX = _world.Origin.x + (x + 1) * _world.CellSize;
                float minZ = _world.Origin.z + y * _world.CellSize;
                float maxZ = _world.Origin.z + (y + 1) * _world.CellSize;
                float nearestX = Mathf.Clamp(position.x, minX, maxX);
                float nearestZ = Mathf.Clamp(position.z, minZ, maxZ);
                float dx = position.x - nearestX;
                float dz = position.z - nearestZ;
                float distanceSq = dx * dx + dz * dz;
                if (distanceSq > probeDistance * probeDistance)
                    continue;

                Vector2 normal2D = new Vector2(dx, dz);
                if (normal2D.sqrMagnitude <= 0.000001f)
                    normal2D = ResolveNavigationRectangleBoundaryNormal(position, minX, maxX, minZ, maxZ);
                if (normal2D.sqrMagnitude <= 0.000001f)
                    continue;

                normal2D.Normalize();
                Vector3 inwardNormal = new Vector3(normal2D.x, 0f, normal2D.y);
                float distance = Mathf.Sqrt(distanceSq);
                TryAccumulateGridEdge(distance, inwardNormal, desiredDirection, ref accumulatedNormal, ref edgeDistance);
            }
        }

        if (edgeDistance == float.MaxValue || accumulatedNormal.sqrMagnitude <= 0.0001f)
            return false;

        edgeNormal = accumulatedNormal.normalized;
        return true;
    }

    private static void TryAccumulateGridEdge(
        float distanceToBoundary,
        Vector3 inwardNormal,
        Vector3 desiredDirection,
        ref Vector3 accumulatedNormal,
        ref float edgeDistance)
    {
        float headingPressure = desiredDirection.sqrMagnitude > 0.0001f
            ? Mathf.Max(0f, -Vector3.Dot(desiredDirection, inwardNormal))
            : 0f;
        if (headingPressure <= 0.05f && distanceToBoundary > _world.CellSize * 0.18f)
            return;

        float clampedDistance = Mathf.Max(0.001f, distanceToBoundary);
        float weight = (1f / clampedDistance) * Mathf.Max(0.35f, headingPressure);
        accumulatedNormal += inwardNormal * weight;
        edgeDistance = Mathf.Min(edgeDistance, distanceToBoundary);
    }

    private static bool TryResolveStableGoalCellFixed(
        AgentRuntimeData agent,
        IEntityContext self,
        FixVector2 rawGoalPosition,
        out int goalX,
        out int goalY,
        out FixVector2 stableGoalPosition,
        out bool shouldEnqueueSharedGoal)
    {
        goalX = 0;
        goalY = 0;
        stableGoalPosition = rawGoalPosition;
        shouldEnqueueSharedGoal = true;
        IEntityContext currentTarget = self?.TargetComp?.CurrentTarget;
        bool useRawGoal = currentTarget == null || ReferenceEquals(currentTarget, self);
        FixVector2 currentTargetFramePosition = default;
        if (!useRawGoal)
        {
            currentTargetFramePosition = currentTarget.LogicFramePositionFixed();
            FixVector2 targetOffset = rawGoalPosition - currentTargetFramePosition;
            Fix64 currentTargetExtent = ResolveNavigationTargetExtentFixed(currentTarget);
            Fix64 targetMatchDistance = Fix64.Max(currentTargetExtent * Fix64.FromRaw(3072), Fix64.FromRaw(1434));
            bool hasExplicitTargetGoal =
                FixVector2.SqrMagnitude(targetOffset) > targetMatchDistance * targetMatchDistance;
            useRawGoal = hasExplicitTargetGoal
                         && ShouldUseExactMovingTargetGoalFixed(self, rawGoalPosition);
        }

        if (useRawGoal)
        {
            if (!TryResolveReachableNavigationPointCellFixed(
                    self,
                    rawGoalPosition,
                    out _,
                    out _,
                    out _,
                    out _,
                    out _,
                    out _,
                    out int reachableGoalX,
                    out int reachableGoalY,
                    out FixVector2 reachableGoalWorld,
                    out _))
            {
                return false;
            }

            _perf.StableGoalRaw++;
            ClearStableGoal(agent);
            shouldEnqueueSharedGoal = currentTarget == null || ReferenceEquals(currentTarget, self);
            goalX = reachableGoalX;
            goalY = reachableGoalY;
            stableGoalPosition = reachableGoalWorld;
            return true;
        }

        if (!_world.WorldToGridFixed(currentTargetFramePosition, out int anchorRawGoalX, out int anchorRawGoalY)
            || !_world.TryGetSectorId(anchorRawGoalX, anchorRawGoalY, out _)
            || !TryResolveStartCellForReachabilityFixed(self, out int startX, out int startY, out int startIsland))
        {
            return false;
        }

        int targetId = ResolveAgentId(currentTarget);
        int agentTypeId = ResolvePreferredAgentTypeId(agent.AgentTypeId);
        MovingTargetAnchorKey anchorKey = new MovingTargetAnchorKey(targetId, agentTypeId, startIsland);
        if (!MovingTargetAnchors.TryGetValue(anchorKey, out MovingTargetAnchor anchor))
        {
            anchor = new MovingTargetAnchor { Key = anchorKey };
            MovingTargetAnchors.Add(anchorKey, anchor);
        }

        int currentFrame = GetFrameCount();
        int anchorReachableGoalX;
        int anchorReachableGoalY;
        int anchorReachableGoalSectorId;
        FixVector2 anchorReachableGoalWorld;
        if (anchor.ReachabilityFrame == currentFrame
            && anchor.ReachabilityWorldVersion == _world.Version
            && anchor.ReachabilityRawGoalX == anchorRawGoalX
            && anchor.ReachabilityRawGoalY == anchorRawGoalY)
        {
            anchorReachableGoalX = anchor.ReachabilityGoalX;
            anchorReachableGoalY = anchor.ReachabilityGoalY;
            anchorReachableGoalSectorId = anchor.ReachabilityGoalSectorId;
            anchorReachableGoalWorld = anchor.ReachabilityGoalWorldFixed;
            _perf.StableGoalReachabilityReuse++;
        }
        else
        {
            if (!TryResolveReachableGoalCellFixed(
                    _world,
                    currentTargetFramePosition,
                    anchorRawGoalX,
                    anchorRawGoalY,
                    startIsland,
                    out anchorReachableGoalX,
                    out anchorReachableGoalY,
                    out anchorReachableGoalWorld,
                    out anchorReachableGoalSectorId))
            {
                return false;
            }

            anchor.ReachabilityFrame = currentFrame;
            anchor.ReachabilityWorldVersion = _world.Version;
            anchor.ReachabilityRawGoalX = anchorRawGoalX;
            anchor.ReachabilityRawGoalY = anchorRawGoalY;
            anchor.ReachabilityGoalX = anchorReachableGoalX;
            anchor.ReachabilityGoalY = anchorReachableGoalY;
            anchor.ReachabilityGoalSectorId = anchorReachableGoalSectorId;
            anchor.ReachabilityGoalWorldFixed = anchorReachableGoalWorld;
        }

        TryPromoteMovingTargetPendingGoal(anchor, agentTypeId, -1, -1, -1);
        bool hasStableGoal = anchor.ActiveGoalX >= 0
                             && anchor.ActiveGoalY >= 0
                             && anchor.ActiveWorldVersion == _world.Version;
        int cellDelta = hasStableGoal
            ? Math.Max(Math.Abs(anchorRawGoalX - anchor.RawGoalX), Math.Abs(anchorRawGoalY - anchor.RawGoalY))
            : int.MaxValue;
        int distanceToActiveGoal = hasStableGoal
            ? Math.Max(Math.Abs(startX - anchor.ActiveGoalX), Math.Abs(startY - anchor.ActiveGoalY))
            : int.MaxValue;
        int refreshCellDelta = distanceToActiveGoal <= _world.SectorSizeInCells
            ? MovingTargetGoalRefreshCellDelta
            : Math.Max(MovingTargetGoalRefreshCellDelta, _world.SectorSizeInCells);
        bool shouldRefresh = !hasStableGoal
                             || cellDelta >= refreshCellDelta;
        if (shouldRefresh)
        {
            int demandStartSectorId = _world.TryGetSectorId(startX, startY, out int resolvedStartSectorId)
                ? resolvedStartSectorId
                : -1;
            if (!hasStableGoal)
            {
                _perf.StableGoalRefreshInitial++;
                SetMovingTargetActiveGoalFixed(
                    anchor,
                    anchorRawGoalX,
                    anchorRawGoalY,
                    anchorReachableGoalX,
                    anchorReachableGoalY,
                    anchorReachableGoalSectorId,
                    anchorReachableGoalWorld);
            }
            else
            {
                _perf.StableGoalRefreshCellDelta++;
                SetMovingTargetPendingGoalFixed(
                    anchor,
                    anchorRawGoalX,
                    anchorRawGoalY,
                    anchorReachableGoalX,
                    anchorReachableGoalY,
                    anchorReachableGoalSectorId,
                    anchorReachableGoalWorld,
                    agentTypeId,
                    demandStartSectorId,
                    startX,
                    startY);
                TryPromoteMovingTargetPendingGoal(anchor, agentTypeId, demandStartSectorId, startX, startY);
            }
        }
        else
        {
            _perf.StableGoalReuse++;
        }

        anchor.LastUsedFrame = GetFrameCount();
        agent.NavState.StableGoalTargetId = targetId;
        agent.NavState.StableGoalRawX = anchor.RawGoalX;
        agent.NavState.StableGoalRawY = anchor.RawGoalY;
        agent.NavState.StableGoalX = anchor.ActiveGoalX;
        agent.NavState.StableGoalY = anchor.ActiveGoalY;
        agent.NavState.StableGoalWorldFixed = anchor.ActiveGoalWorldFixed;
        agent.NavState.StableGoalWorld = anchor.ActiveGoalWorld;
        shouldEnqueueSharedGoal = false;
        goalX = anchor.ActiveGoalX;
        goalY = anchor.ActiveGoalY;
        stableGoalPosition = anchor.ActiveGoalWorldFixed;
        return true;
    }

    private static bool ShouldUseExactMovingTargetGoalFixed(
        IEntityContext self,
        FixVector2 rawGoalPosition)
    {
        if (!_world.WorldToGridFixed(rawGoalPosition, out int rawGoalX, out int rawGoalY)
            || !_world.TryGetSectorId(rawGoalX, rawGoalY, out _)
            || !TryResolveStartCellForReachabilityFixed(self, out int startX, out int startY, out _))
        {
            return true;
        }

        int cellDistance = Math.Max(Math.Abs(startX - rawGoalX), Math.Abs(startY - rawGoalY));
        return cellDistance <= checked(_world.SectorSizeInCells * 2);
    }

    private static bool TryResolveReachableNavigationPointCellFixed(
        IEntityContext self,
        FixVector2 rawGoalPosition,
        out int rawGoalX,
        out int rawGoalY,
        out int rawGoalSectorId,
        out int startX,
        out int startY,
        out int startIsland,
        out int reachableGoalX,
        out int reachableGoalY,
        out FixVector2 reachableGoalWorld,
        out int reachableGoalSectorId)
    {
        rawGoalX = 0;
        rawGoalY = 0;
        rawGoalSectorId = -1;
        startX = 0;
        startY = 0;
        startIsland = -1;
        reachableGoalX = 0;
        reachableGoalY = 0;
        reachableGoalWorld = rawGoalPosition;
        reachableGoalSectorId = -1;

        if (!_world.WorldToGridFixed(rawGoalPosition, out rawGoalX, out rawGoalY))
            return false;
        if (!_world.TryGetSectorId(rawGoalX, rawGoalY, out rawGoalSectorId))
            return false;
        if (!TryResolveStartCellForReachabilityFixed(self, out startX, out startY, out startIsland))
            return false;
        bool resolved = TryResolveReachableGoalCellFixed(
            _world,
            rawGoalPosition,
            rawGoalX,
            rawGoalY,
            startIsland,
            out reachableGoalX,
            out reachableGoalY,
            out reachableGoalWorld,
            out reachableGoalSectorId);
        if (resolved
            && (reachableGoalX != rawGoalX || reachableGoalY != rawGoalY)
            && IsMovementDiagnosticsEnabled())
        {
            Fix64 distance = FixVector2.Distance(rawGoalPosition, reachableGoalWorld);
            Debug.LogWarning(
                $"[FlowGoalResolvedToReachable] agent={self?.CharacterKey ?? "null"} rawGoalRaw=({rawGoalPosition.x.RawValue},{rawGoalPosition.y.RawValue}) " +
                $"rawCell=({rawGoalX},{rawGoalY}) start=({startX},{startY}) startIsland={startIsland} " +
                $"resolved=({reachableGoalX},{reachableGoalY}) resolvedRaw=({reachableGoalWorld.x.RawValue},{reachableGoalWorld.y.RawValue}) " +
                $"resolvedDistanceRaw={distance.RawValue} worldVersion={_world.Version}");
        }

        return resolved;
    }

    private static void SetMovingTargetActiveGoalFixed(
        MovingTargetAnchor anchor,
        int rawGoalX,
        int rawGoalY,
        int goalX,
        int goalY,
        int goalSectorId,
        FixVector2 goalWorld)
    {
        if (anchor == null)
            throw new InvalidOperationException("SetMovingTargetActiveGoalFixed failed: anchor is null.");

        anchor.RawGoalX = rawGoalX;
        anchor.RawGoalY = rawGoalY;
        anchor.ActiveGoalX = goalX;
        anchor.ActiveGoalY = goalY;
        anchor.ActiveGoalSectorId = goalSectorId;
        anchor.ActiveGoalWorldFixed = goalWorld;
        anchor.ActiveGoalWorld = ToWorldVector3(goalWorld);
        anchor.ActiveWorldVersion = _world.Version;
        ClearMovingTargetPendingGoal(anchor);
    }

    private static bool TryPrepareMovingTargetPendingGoalUpdate(
        MovingTargetAnchor anchor,
        int rawGoalX,
        int rawGoalY,
        int goalX,
        int goalY,
        int goalSectorId,
        int agentTypeId,
        out SharedGoalFieldKey nextPendingKey)
    {
        if (anchor == null)
            throw new ArgumentNullException(nameof(anchor));

        nextPendingKey = default;
        if (anchor.PendingGoalX >= 0
            && anchor.PendingGoalY >= 0
            && anchor.PendingWorldVersion == _world.Version)
        {
            int pendingDelta = Math.Max(Math.Abs(rawGoalX - anchor.PendingRawGoalX), Math.Abs(rawGoalY - anchor.PendingRawGoalY));
            if (pendingDelta < MovingTargetGoalRefreshCellDelta)
                return false;

            int sharedAgentTypeId = ResolvePreferredAgentTypeId(agentTypeId);
            if (!TryGetCachedSharedGoalField(anchor.PendingGoalSectorId, anchor.PendingGoalX, anchor.PendingGoalY, sharedAgentTypeId, out _))
                return false;
        }

        SharedGoalFieldKey? previousPendingKey = null;
        if (anchor.PendingGoalX >= 0
            && anchor.PendingGoalY >= 0
            && anchor.PendingGoalSectorId >= 0
            && anchor.PendingWorldVersion == _world.Version)
        {
            previousPendingKey = CreateSharedGoalFieldKey(
                anchor.PendingGoalSectorId,
                anchor.PendingGoalX,
                anchor.PendingGoalY,
                ResolvePreferredAgentTypeId(agentTypeId));
        }

        nextPendingKey = CreateSharedGoalFieldKey(goalSectorId, goalX, goalY, ResolvePreferredAgentTypeId(agentTypeId));
        if (previousPendingKey.HasValue && !previousPendingKey.Value.Equals(nextPendingKey))
            RemovePendingSharedGoalFieldBuildJob(previousPendingKey.Value);

        anchor.PendingRawGoalX = rawGoalX;
        anchor.PendingRawGoalY = rawGoalY;
        anchor.PendingGoalX = goalX;
        anchor.PendingGoalY = goalY;
        anchor.PendingGoalSectorId = goalSectorId;
        anchor.PendingWorldVersion = _world.Version;
        return true;
    }

    private static void SetMovingTargetPendingGoalFixed(
        MovingTargetAnchor anchor,
        int rawGoalX,
        int rawGoalY,
        int goalX,
        int goalY,
        int goalSectorId,
        FixVector2 goalWorld,
        int agentTypeId,
        int demandStartSectorId,
        int demandStartX,
        int demandStartY)
    {
        if (anchor == null)
            throw new InvalidOperationException("SetMovingTargetPendingGoalFixed failed: anchor is null.");

        if (!TryPrepareMovingTargetPendingGoalUpdate(
                anchor,
                rawGoalX,
                rawGoalY,
                goalX,
                goalY,
                goalSectorId,
                agentTypeId,
                out SharedGoalFieldKey nextPendingKey))
        {
            return;
        }

        anchor.PendingGoalWorldFixed = goalWorld;
        anchor.PendingGoalWorld = ToWorldVector3(goalWorld);
        EnqueueSharedGoalFieldBuild(nextPendingKey, true, demandStartSectorId, demandStartX, demandStartY);
    }

    private static bool TryPromoteMovingTargetPendingGoal(
        MovingTargetAnchor anchor,
        int agentTypeId,
        int demandStartSectorId,
        int demandStartX,
        int demandStartY)
    {
        if (anchor == null)
            throw new InvalidOperationException("TryPromoteMovingTargetPendingGoal failed: anchor is null.");

        if (anchor.PendingGoalX < 0
            || anchor.PendingGoalY < 0
            || anchor.PendingWorldVersion != _world.Version)
        {
            return false;
        }

        int sharedAgentTypeId = ResolvePreferredAgentTypeId(agentTypeId);
        bool canPromote = TryGetCachedSharedGoalField(anchor.PendingGoalSectorId, anchor.PendingGoalX, anchor.PendingGoalY, sharedAgentTypeId, out _)
                          || IsMovingTargetPendingGoalLocallyReachable(anchor, demandStartSectorId, demandStartX, demandStartY);
        if (!canPromote)
        {
            SharedGoalFieldKey pendingKey = CreateSharedGoalFieldKey(anchor.PendingGoalSectorId, anchor.PendingGoalX, anchor.PendingGoalY, sharedAgentTypeId);
            if (demandStartSectorId >= 0)
            {
                EnqueueSharedGoalFieldBuild(pendingKey, true, demandStartSectorId, demandStartX, demandStartY);
                canPromote = TryGetCachedSharedGoalField(anchor.PendingGoalSectorId, anchor.PendingGoalX, anchor.PendingGoalY, sharedAgentTypeId, out _);
            }
            else
            {
                EnqueueSharedGoalFieldBuild(pendingKey, prependToFront: true);
            }

            if (!canPromote)
                return false;
        }

        anchor.RawGoalX = anchor.PendingRawGoalX;
        anchor.RawGoalY = anchor.PendingRawGoalY;
        anchor.ActiveGoalX = anchor.PendingGoalX;
        anchor.ActiveGoalY = anchor.PendingGoalY;
        anchor.ActiveGoalSectorId = anchor.PendingGoalSectorId;
        anchor.ActiveGoalWorld = anchor.PendingGoalWorld;
        anchor.ActiveGoalWorldFixed = anchor.PendingGoalWorldFixed;
        anchor.ActiveWorldVersion = _world.Version;
        ClearMovingTargetPendingGoal(anchor);
        return true;
    }

    private static bool IsMovingTargetPendingGoalLocallyReachable(
        MovingTargetAnchor anchor,
        int demandStartSectorId,
        int demandStartX,
        int demandStartY)
    {
        if (anchor == null)
            throw new InvalidOperationException("IsMovingTargetPendingGoalLocallyReachable failed: anchor is null.");
        if (_world == null)
            throw new InvalidOperationException("IsMovingTargetPendingGoalLocallyReachable failed: world is null.");
        if (demandStartSectorId < 0 || demandStartSectorId != anchor.PendingGoalSectorId)
            return false;
        if (demandStartX < 0
            || demandStartX >= _world.Width
            || demandStartY < 0
            || demandStartY >= _world.Height)
        {
            return false;
        }

        SectorData sector = _world.Sectors[demandStartSectorId];
        return AreCellsConnectedInsideSector(sector, demandStartX, demandStartY, anchor.PendingGoalX, anchor.PendingGoalY);
    }

    private static void ClearMovingTargetPendingGoal(MovingTargetAnchor anchor)
    {
        if (anchor == null)
            throw new InvalidOperationException("ClearMovingTargetPendingGoal failed: anchor is null.");

        anchor.PendingRawGoalX = -1;
        anchor.PendingRawGoalY = -1;
        anchor.PendingGoalX = -1;
        anchor.PendingGoalY = -1;
        anchor.PendingGoalSectorId = -1;
        anchor.PendingWorldVersion = -1;
        anchor.PendingGoalWorld = Vector3.zero;
        anchor.PendingGoalWorldFixed = FixVector2.Zero;
    }

    private static bool TryResolveStartCellForReachabilityFixed(IEntityContext self, out int startX, out int startY, out int startIsland)
    {
        startX = 0;
        startY = 0;
        startIsland = -1;
        if (self == null || _world == null)
            return false;

        FixVector2 selfFramePosition = self.LogicFramePositionFixed();
        if (!_world.WorldToGridFixed(selfFramePosition, out startX, out startY))
            return false;

        if (!_world.IsWalkable(startX, startY)
            && !TryResolveNearbyStartWalkableFixed(_world, selfFramePosition, startX, startY, out startX, out startY))
        {
            return false;
        }

        startIsland = ResolveIslandIdForDiagnostics(_world, startX, startY);
        return startIsland > 0;
    }


    private static string BuildReachabilityStartDiagnostics(IEntityContext self)
    {
        if (self == null)
            return "self=null";
        Vector3 selfFramePosition = self.LogicFramePosition();
        if (_world == null)
            return $"pos={selfFramePosition} world=null";
        if (!_world.WorldToGrid(selfFramePosition, out int rawX, out int rawY))
            return $"pos={selfFramePosition} outsideGrid";

        bool rawWalkable = _world.IsWalkable(rawX, rawY);
        int rawIsland = rawWalkable ? ResolveIslandIdForDiagnostics(_world, rawX, rawY) : -1;
        bool resolved = TryResolveNearbyStartWalkable(_world, selfFramePosition, rawX, rawY, out int resolvedX, out int resolvedY);
        int resolvedIsland = resolved ? ResolveIslandIdForDiagnostics(_world, resolvedX, resolvedY) : -1;
        float radius = ResolveCollisionRadius(self);
        float requestedClearance = ResolveNavigationSegmentClearance(_world, radius);
        float clearance = ResolveNavigationQueryClearance(_world, requestedClearance);
        float violation = ResolveNavigationClearanceViolation(_world, selfFramePosition, clearance, includeRuntimeObstacleOverlay: true);
        return $"pos={selfFramePosition} raw=({rawX},{rawY}) rawWalk={rawWalkable} rawIsland={rawIsland} " +
               $"resolved={resolved} resolvedCell=({resolvedX},{resolvedY}) resolvedWalk={(resolved && _world.IsWalkable(resolvedX, resolvedY))} resolvedIsland={resolvedIsland} " +
               $"agentType={_world.AgentTypeId} radius={radius:F3} requestedClearance={requestedClearance:F3} queryClearance={clearance:F3} violation={(float.IsPositiveInfinity(violation) ? "INF" : violation.ToString("F3"))} " +
               $"worldVersion={_world.Version} islandCount={_world.IslandCount} mainIsland={_world.MainIslandId}:{_world.MainIslandSize} " +
               $"grid={FormatGridSampleDiagnostics(selfFramePosition)} obstacles={BuildNearbyObstacleDiagnostics(selfFramePosition, selfFramePosition, _world.AgentTypeId)} " +
               $"neighborhood={BuildIslandNeighborhoodDiagnostics(_world, rawX, rawY, 2)}";
    }

    private static bool TryResolveReachableNavigationQueryCellsFixed(
        NavigationWorld world,
        FixVector2 from,
        FixVector2 rawGoal,
        out int startX,
        out int startY,
        out int goalX,
        out int goalY,
        out FixVector2 reachableGoal,
        out string failureReason)
    {
        if (world == null)
            throw new InvalidOperationException("TryResolveReachableNavigationQueryCellsFixed failed: world is null.");

        startX = 0;
        startY = 0;
        goalX = 0;
        goalY = 0;
        reachableGoal = rawGoal;
        failureReason = string.Empty;
        if (!world.WorldToGridFixed(from, out startX, out startY))
        {
            failureReason = $"start is outside authored grid raw=({from.x.RawValue},{from.y.RawValue})";
            return false;
        }
        if (!world.IsWalkable(startX, startY)
            && !TryResolveNearbyStartWalkableFixed(world, from, startX, startY, out startX, out startY))
        {
            failureReason =
                $"start has no nearby walkable cell raw=({from.x.RawValue},{from.y.RawValue}) cell=({startX},{startY})";
            return false;
        }

        int startIsland = ResolveIslandIdForDiagnostics(world, startX, startY);
        if (startIsland <= 0)
        {
            failureReason = $"start cell has no navigation island cell=({startX},{startY})";
            return false;
        }
        if (!world.WorldToGridFixed(rawGoal, out int rawGoalX, out int rawGoalY))
        {
            failureReason = $"goal is outside authored grid raw=({rawGoal.x.RawValue},{rawGoal.y.RawValue})";
            return false;
        }
        if (!TryResolveReachableGoalCellFixed(
                world,
                rawGoal,
                rawGoalX,
                rawGoalY,
                startIsland,
                out goalX,
                out goalY,
                out reachableGoal,
                out _))
        {
            failureReason =
                $"goal has no reachable cell on start island raw=({rawGoal.x.RawValue},{rawGoal.y.RawValue}) " +
                $"rawCell=({rawGoalX},{rawGoalY}) start=({startX},{startY}) startIsland={startIsland}";
            return false;
        }

        return true;
    }

    private static bool TryResolveReachableGoalCellFixed(
        NavigationWorld world,
        FixVector2 rawGoalPosition,
        int rawGoalX,
        int rawGoalY,
        int startIsland,
        out int goalX,
        out int goalY,
        out FixVector2 goalWorld,
        out int goalSectorId)
    {
        if (world == null)
            throw new InvalidOperationException("TryResolveReachableGoalCellFixed failed: world is null.");

        goalX = rawGoalX;
        goalY = rawGoalY;
        goalWorld = rawGoalPosition;
        goalSectorId = -1;

        int rawGoalIsland = ResolveIslandIdForDiagnostics(world, rawGoalX, rawGoalY);
        if (world.IsWalkable(rawGoalX, rawGoalY) && rawGoalIsland == startIsland)
        {
            goalWorld = world.GridToWorldCenterFixed(rawGoalX, rawGoalY);
            return world.TryGetSectorId(goalX, goalY, out goalSectorId);
        }

        if (!TryFindNearestWalkableInIslandByWorldDistanceFixed(
                world,
                rawGoalX,
                rawGoalY,
                rawGoalPosition,
                startIsland,
                radius: 8,
                allowFullIslandSearch: true,
                out goalX,
                out goalY,
                out _))
        {
            return false;
        }

        goalWorld = world.GridToWorldCenterFixed(goalX, goalY);
        return world.TryGetSectorId(goalX, goalY, out goalSectorId);
    }


    private static string BuildReachabilityTargetDiagnostics(IEntityContext self, Vector3 rawGoalPosition, int startX, int startY)
    {
        IEntityContext target = self?.TargetComp?.CurrentTarget;
        if (target == null)
            return "target=null";

        Vector3 targetFramePosition = target.LogicFramePosition();
        bool targetInGrid = _world.WorldToGrid(targetFramePosition, out int targetX, out int targetY);
        int targetIsland = targetInGrid ? ResolveIslandIdForDiagnostics(_world, targetX, targetY) : -1;
        bool targetIsMainIsland = targetIsland > 0 && targetIsland == _world.MainIslandId;
        float rawTargetDistance = HorizontalDistanceXZ(rawGoalPosition, targetFramePosition);

        Vector3 startPosition = _world.GridToWorldCenter(startX, startY);
        string flowPath = BuildGridPathDiagnostics(startPosition, targetFramePosition, _world.AgentTypeId);

        return $"target={{key={target.CharacterKey},pos={targetFramePosition},inGrid={targetInGrid},cell=({targetX},{targetY}),island={targetIsland},main={targetIsMainIsland},rawDist={rawTargetDistance:F3},{flowPath}}}";
    }

    private static void TrimMovingTargetAnchors()
    {
        if (MovingTargetAnchors.Count == 0)
            return;

        int expireBeforeFrame = GetFrameCount() - 300;
        List<MovingTargetAnchorKey> expiredIds = null;
        bool referencedKeysBuilt = false;
        foreach (KeyValuePair<MovingTargetAnchorKey, MovingTargetAnchor> pair in MovingTargetAnchors)
        {
            if (pair.Value.LastUsedFrame >= expireBeforeFrame)
                continue;

            if (!referencedKeysBuilt)
            {
                BuildReferencedMovingTargetAnchorKeySet();
                referencedKeysBuilt = true;
            }
            if (ReferencedMovingTargetAnchorKeysScratch.Contains(pair.Key))
                continue;

            expiredIds ??= new List<MovingTargetAnchorKey>();
            expiredIds.Add(pair.Key);
        }

        ReferencedMovingTargetAnchorKeysScratch.Clear();
        if (expiredIds == null)
            return;

        for (int i = 0; i < expiredIds.Count; i++)
            MovingTargetAnchors.Remove(expiredIds[i]);
    }

    private static void BuildReferencedMovingTargetAnchorKeySet()
    {
        ReferencedMovingTargetAnchorKeysScratch.Clear();
        if (_world == null)
            return;

        foreach (AgentRuntimeData agent in Agents.Values)
        {
            if (agent == null || agent.NavState.StableGoalTargetId == int.MinValue)
                continue;
            if (!IsAgentInCurrentNavigationWorld(agent))
                continue;

            int islandId = ResolveIslandIdForDiagnostics(_world, agent.NavState.CurrentCell.x, agent.NavState.CurrentCell.y);
            if (islandId <= 0)
                continue;

            ReferencedMovingTargetAnchorKeysScratch.Add(new MovingTargetAnchorKey(
                agent.NavState.StableGoalTargetId,
                ResolvePreferredAgentTypeId(agent.AgentTypeId),
                islandId));
        }
    }

    private static void TrimCombatTargetSlotCache()
    {
        if (CombatTargetSlotCache.Count == 0)
            return;

        int expireBeforeFrame = GetFrameCount() - CombatTargetSlotCacheFrameLifetime;
        List<CombatTargetSlotKey> expiredKeys = null;
        foreach (KeyValuePair<CombatTargetSlotKey, CombatTargetSlotEntry> pair in CombatTargetSlotCache)
        {
            if (pair.Value != null && pair.Value.LastUsedFrame >= expireBeforeFrame)
                continue;

            expiredKeys ??= new List<CombatTargetSlotKey>();
            expiredKeys.Add(pair.Key);
        }

        if (expiredKeys == null)
            return;

        for (int i = 0; i < expiredKeys.Count; i++)
            CombatTargetSlotCache.Remove(expiredKeys[i]);
    }

    private static void ClearStableGoal(AgentRuntimeData agent)
    {
        if (agent == null)
            return;

        agent.NavState.StableGoalTargetId = int.MinValue;
        agent.NavState.StableGoalX = -1;
        agent.NavState.StableGoalY = -1;
        agent.NavState.StableGoalWorld = Vector3.zero;
        agent.NavState.StableGoalWorldFixed = FixVector2.Zero;
    }

    private static bool IsNavigationMovingTarget(IEntityContext target)
    {
        if (target == null)
            return false;

        IMoveComp moveComp = target.MoveComp;
        if (moveComp != null)
            return moveComp.GetType() != typeof(NoMoveComp);

        return target.MoveExecutor != null;
    }

    private static FixVector2 ResolveNavigationGoalOccupancyFixed(
        IEntityContext self,
        AgentRuntimeData agent,
        FixVector2 goalPosition)
    {
        if (self == null || agent == null)
            throw new InvalidOperationException("ResolveNavigationGoalOccupancyFixed failed: self or agent is null.");
        if (_world == null)
            throw new InvalidOperationException("ResolveNavigationGoalOccupancyFixed failed: world is null.");

        int frame = GetFrameCount();
        if (_navigationGoalReservationFrame != frame)
        {
            NavigationGoalReservations.Clear();
            _navigationGoalReservationFrame = frame;
        }
        SyncRegisteredAgentSpatialState(frame);

        FixVector2 selfFramePosition = self.LogicFramePositionFixed();
        int selfId = ResolveAgentId(self);
        if (HasExactNavigationGoalReservationFixed(selfId, goalPosition))
            return goalPosition;

        Fix64 selfRadius = Fix64.Max(ResolveCollisionRadiusFixed(self), agent.RadiusFixed);
        Fix64 requiredDistance = Fix64.Max(
            selfRadius * (Fix64)2 + NavigationGoalOccupancyPadding,
            selfRadius + Fix64.FromRaw(820));
        int ignoredTargetId = ResolveIgnoredGoalOccupancyTargetIdFixed(self, goalPosition);
        Fix64 distanceToGoal = FixVector2.Magnitude(goalPosition - selfFramePosition);
        Fix64 cellSize = _world.CellSizeFixed;
        Fix64 blockingActivationDistance = Fix64.Max(requiredDistance * (Fix64)4, cellSize * (Fix64)5);
        Fix64 reservationActivationDistance = Fix64.Max(requiredDistance * (Fix64)2, cellSize * (Fix64)2);
        if (distanceToGoal > blockingActivationDistance)
            return goalPosition;

        bool useReservations = distanceToGoal <= reservationActivationDistance;
        if (IsNavigationGoalOccupiedByOtherFixed(
                selfId,
                ignoredTargetId,
                goalPosition,
                requiredDistance,
                useReservations,
                out _))
        {
            return ResolveRotatedNearbyGoalFixed(
                self,
                goalPosition,
                ignoredTargetId,
                selfRadius,
                requiredDistance,
                preferLateral: true);
        }

        RegisterNavigationGoalReservationFixed(selfId, goalPosition, requiredDistance);
        return goalPosition;
    }

    private static int ResolveIgnoredGoalOccupancyTargetIdFixed(IEntityContext self, FixVector2 goalPosition)
    {
        IEntityContext currentTarget = self.TargetComp?.CurrentTarget;
        if (currentTarget == null)
            return 0;

        FixVector2 offset = goalPosition - currentTarget.LogicFramePositionFixed();
        Fix64 targetExtent = ResolveNavigationTargetExtentFixed(currentTarget);
        Fix64 threshold = Fix64.Max(targetExtent * Fix64.FromRaw(3072), Fix64.FromRaw(1434));
        return FixVector2.SqrMagnitude(offset) > threshold * threshold
            ? ResolveAgentId(currentTarget)
            : 0;
    }

    private static FixVector2 ResolveRotatedNearbyGoalFixed(
        IEntityContext self,
        FixVector2 goalPosition,
        int targetId,
        Fix64 selfRadius,
        Fix64 requiredDistance,
        bool preferLateral)
    {
        if (!_world.WorldToGridFixed(goalPosition, out int goalX, out int goalY)
            || !_world.TryGetSectorId(goalX, goalY, out _))
        {
            return goalPosition;
        }

        int goalIsland = ResolveIslandIdForDiagnostics(_world, goalX, goalY);
        if (goalIsland <= 0)
            return goalPosition;

        FixVector2 selfFramePosition = self.LogicFramePositionFixed();
        FixVector2 baseDirection = selfFramePosition - goalPosition;
        if (FixVector2.SqrMagnitude(baseDirection) <= Fix64.Zero)
            baseDirection = new FixVector2(Fix64.Zero, Fix64.One);
        else
            baseDirection = baseDirection.GetNormalized();

        FixVector2 bestPoint = goalPosition;
        int bestPreferenceClass = int.MaxValue;
        int bestRing = int.MaxValue;
        Fix64 bestTravelDistance = Fix64.FromRaw(long.MaxValue);
        int candidateOrderStart = preferLateral ? 1 : 0;
        for (int ring = 0; ring < NavigationGoalRingCount; ring++)
        {
            Fix64 radius = Fix64.Max(
                               selfRadius + Fix64.FromRaw(205),
                               requiredDistance - selfRadius * Fix64.FromRaw(2048))
                           + (Fix64)ring * Fix64.Max(Fix64.FromRaw(1434), selfRadius * Fix64.FromRaw(1434));
            for (int i = 0; i < NavigationGoalCandidateCount; i++)
            {
                int candidateIndex = (candidateOrderStart + i) % NavigationGoalCandidateCount;
                Fix64 angleDegrees = ResolveNavigationGoalAngleFixed(candidateIndex);
                Fix64 radians = angleDegrees * Fix64.PI / (Fix64)180;
                Fix64 sin = Fix64.Sin(radians);
                Fix64 cos = Fix64.Cos(radians);
                FixVector2 direction = new FixVector2(
                    baseDirection.x * cos - baseDirection.y * sin,
                    baseDirection.x * sin + baseDirection.y * cos);
                FixVector2 candidate = goalPosition + direction * radius;
                if (!_world.WorldToGridFixed(candidate, out int candidateX, out int candidateY)
                    || !_world.IsWalkable(candidateX, candidateY)
                    || ResolveIslandIdForDiagnostics(_world, candidateX, candidateY) != goalIsland)
                {
                    continue;
                }

                if (!TryResolveReachableNavigationPointCellFixed(
                        self,
                        candidate,
                        out _,
                        out _,
                        out _,
                        out _,
                        out _,
                        out _,
                        out int resolvedX,
                        out int resolvedY,
                        out FixVector2 resolvedWorld,
                        out _))
                {
                    continue;
                }
                if (ResolveIslandIdForDiagnostics(_world, resolvedX, resolvedY) != goalIsland
                    || !IsNavigationPointClearFixed(
                        _world,
                        resolvedWorld,
                        ResolveNavigationQueryClearanceFixed(_world, selfRadius),
                        includeRuntimeObstacleOverlay: true)
                    || IsNavigationGoalOccupiedByOtherFixed(
                        ResolveAgentId(self),
                        targetId,
                        resolvedWorld,
                        requiredDistance,
                        includeReservations: true,
                        out _))
                {
                    continue;
                }

                FixVector2 resolvedGoalOffset = resolvedWorld - goalPosition;
                Fix64 lateralArea = baseDirection.x * resolvedGoalOffset.y
                                    - baseDirection.y * resolvedGoalOffset.x;
                int preferenceClass = preferLateral && lateralArea == Fix64.Zero ? 1 : 0;
                Fix64 travelDistance = FixVector2.Magnitude(resolvedWorld - selfFramePosition);
                if (preferenceClass > bestPreferenceClass
                    || (preferenceClass == bestPreferenceClass && ring > bestRing)
                    || (preferenceClass == bestPreferenceClass && ring == bestRing && travelDistance >= bestTravelDistance))
                    continue;

                bestPreferenceClass = preferenceClass;
                bestRing = ring;
                bestTravelDistance = travelDistance;
                bestPoint = resolvedWorld;
            }
        }

        RegisterNavigationGoalReservationFixed(ResolveAgentId(self), bestPoint, requiredDistance);
        return bestPoint;
    }

    private static void RegisterNavigationGoalReservationFixed(int selfId, FixVector2 point, Fix64 requiredDistance)
    {
        int frame = GetFrameCount();
        if (_navigationGoalReservationFrame != frame)
        {
            NavigationGoalReservations.Clear();
            _navigationGoalReservationFrame = frame;
        }

        for (int i = NavigationGoalReservations.Count - 1; i >= 0; i--)
        {
            if (NavigationGoalReservations[i].SelfId == selfId)
                NavigationGoalReservations.RemoveAt(i);
        }
        NavigationGoalReservations.Add(new NavigationGoalReservation(selfId, point, requiredDistance));
    }

    private static bool HasExactNavigationGoalReservationFixed(int selfId, FixVector2 point)
    {
        for (int i = 0; i < NavigationGoalReservations.Count; i++)
        {
            NavigationGoalReservation reservation = NavigationGoalReservations[i];
            if (reservation.SelfId == selfId
                && reservation.Point.x.RawValue == point.x.RawValue
                && reservation.Point.y.RawValue == point.y.RawValue)
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsNavigationGoalOccupiedByOtherFixed(
        int selfId,
        int ignoredAgentId,
        FixVector2 position,
        Fix64 requiredDistance,
        bool includeReservations,
        out int reservingAgentId)
    {
        int frame = GetFrameCount();
        if (_navigationGoalReservationFrame != frame)
        {
            NavigationGoalReservations.Clear();
            _navigationGoalReservationFrame = frame;
        }

        reservingAgentId = 0;
        Fix64 bestDistanceSq = Fix64.FromRaw(long.MaxValue);
        if (includeReservations)
        {
            for (int i = 0; i < NavigationGoalReservations.Count; i++)
            {
                NavigationGoalReservation reservation = NavigationGoalReservations[i];
                if (reservation.SelfId == selfId)
                    continue;
                Fix64 reservationThreshold = Fix64.Max(requiredDistance, reservation.RequiredDistance);
                Fix64 reservationThresholdSq = reservationThreshold * reservationThreshold;
                Fix64 distanceSq = FixVector2.SqrMagnitude(reservation.Point - position);
                if (distanceSq >= reservationThresholdSq
                    || distanceSq > bestDistanceSq
                    || (distanceSq == bestDistanceSq && reservation.SelfId >= reservingAgentId))
                {
                    continue;
                }

                bestDistanceSq = distanceSq;
                reservingAgentId = reservation.SelfId;
            }
        }

        for (int i = 0; i < OrderedAgentIds.Count; i++)
        {
            AgentRuntimeData other = Agents[OrderedAgentIds[i]];
            if (other.Id == selfId || other.Id == ignoredAgentId || other.IgnoreAgentCollision)
                continue;

            Fix64 otherThreshold = Fix64.Max(
                requiredDistance,
                other.RadiusFixed * (Fix64)2 + NavigationGoalOccupancyPadding);
            Fix64 otherThresholdSq = otherThreshold * otherThreshold;
            Fix64 positionDistanceSq = FixVector2.SqrMagnitude(other.PositionFixed - position);
            if (positionDistanceSq < otherThresholdSq
                && (positionDistanceSq < bestDistanceSq
                    || (positionDistanceSq == bestDistanceSq && other.Id < reservingAgentId)))
            {
                bestDistanceSq = positionDistanceSq;
                reservingAgentId = other.Id;
            }

            if (!ShouldUseAgentNavigationGoalAsOccupancyFixed(other))
                continue;
            Fix64 goalDistanceSq = FixVector2.SqrMagnitude(other.NavState.LastGoalWorldFixed - position);
            if (goalDistanceSq < otherThresholdSq
                && (goalDistanceSq < bestDistanceSq
                    || (goalDistanceSq == bestDistanceSq && other.Id < reservingAgentId)))
            {
                bestDistanceSq = goalDistanceSq;
                reservingAgentId = other.Id;
            }
        }

        return reservingAgentId != 0;
    }

    private static Fix64 ResolveNavigationGoalAngleFixed(int index)
    {
        if (index == 0)
            return Fix64.Zero;

        int step = (index + 1) / 2;
        int sign = (index & 1) == 1 ? 1 : -1;
        return (Fix64)(sign * step) * (Fix64)360 / (Fix64)NavigationGoalCandidateCount;
    }

    private static float HorizontalDistanceXZ(Vector3 a, Vector3 b)
    {
        float dx = a.x - b.x;
        float dz = a.z - b.z;
        return Mathf.Sqrt(dx * dx + dz * dz);
    }

    private static bool AreCellsOnSameIsland(NavigationWorld world, int startX, int startY, int goalX, int goalY)
    {
        if (world == null)
            throw new InvalidOperationException("AreCellsOnSameIsland failed: world is null.");
        if (world.IslandIds == null || world.IslandIds.Length != world.Width * world.Height)
            throw new InvalidOperationException("AreCellsOnSameIsland failed: island field is missing or invalid.");
        if (!world.IsWalkable(startX, startY) || !world.IsWalkable(goalX, goalY))
            return false;

        int startIsland = ResolveIslandId(world, startX, startY);
        int goalIsland = ResolveIslandId(world, goalX, goalY);
        return startIsland > 0 && startIsland == goalIsland;
    }

    private static string BuildIslandMismatchFailure(IEntityContext self, Vector3 rawGoalPosition, int startX, int startY, int goalX, int goalY)
    {
        int startIsland = ResolveIslandIdForDiagnostics(_world, startX, startY);
        int goalIsland = ResolveIslandIdForDiagnostics(_world, goalX, goalY);
        string nearestGoalIsland = TryFindNearestCellInIsland(_world, startX, startY, goalIsland, 32, out int nearestGoalIslandX, out int nearestGoalIslandY, out int nearestGoalIslandDistance)
            ? $" nearestGoalIslandFromStart=({nearestGoalIslandX},{nearestGoalIslandY}) manhattan={nearestGoalIslandDistance}"
            : " nearestGoalIslandFromStart=none";
        string nearestStartIsland = TryFindNearestCellInIsland(_world, goalX, goalY, startIsland, 32, out int nearestStartIslandX, out int nearestStartIslandY, out int nearestStartIslandDistance)
            ? $" nearestStartIslandFromGoal=({nearestStartIslandX},{nearestStartIslandY}) manhattan={nearestStartIslandDistance}"
            : " nearestStartIslandFromGoal=none";

        Vector3 startWorld = _world != null ? _world.GridToWorldCenter(startX, startY) : Vector3.zero;
        Vector3 goalWorld = _world != null ? _world.GridToWorldCenter(goalX, goalY) : Vector3.zero;
        IEntityContext target = self?.TargetComp?.CurrentTarget;
        string targetInfo = target != null
            ? $" target={target.CharacterKey} targetSide={target.Side} targetPos={target.Position} targetMoveMode={(target.MoveExecutor != null ? target.MoveExecutor.MovementMode.ToString() : "null")}"
            : " target=null";
        string selfInfo = self != null
            ? $" self={self.CharacterKey} selfSide={self.Side} selfPos={self.Position} selfMoveMode={(self.MoveExecutor != null ? self.MoveExecutor.MovementMode.ToString() : "null")}"
            : " self=null";
        string startGrid = FormatGridSampleDiagnostics(startWorld);
        string goalGrid = FormatGridSampleDiagnostics(rawGoalPosition);
        string startNeighborhood = BuildIslandNeighborhoodDiagnostics(_world, startX, startY, 2);
        string goalNeighborhood = BuildIslandNeighborhoodDiagnostics(_world, goalX, goalY, 2);

        return $"island mismatch start=({startX},{startY}) island={startIsland} startWorld={startWorld} " +
               $"goal=({goalX},{goalY}) island={goalIsland} goalWorld={goalWorld} rawGoal={rawGoalPosition} " +
               $"worldVersion={_world?.Version ?? -1} agentType={_world?.AgentTypeId ?? int.MinValue} islandCount={_world?.IslandCount ?? -1} " +
               $"runtimeDirtySectors={(_activeWorldState != null ? _activeWorldState.DirtyRuntimeObstacleSectors.Count : -1)} " +
               $"runtimeDirtyReason={_lastRuntimeObstacleDirtyReason} circleObstacles={CircleObstacles.Count} boxObstacles={BoxObstacles.Count}" +
               $"{nearestGoalIsland}{nearestStartIsland}{selfInfo}{targetInfo} startGrid={startGrid} goalGrid={goalGrid} " +
               $"startNeighborhood={startNeighborhood} goalNeighborhood={goalNeighborhood}";
    }

    private static int ResolveIslandIdForDiagnostics(NavigationWorld world, int x, int y)
    {
        return ResolveIslandId(world, x, y);
    }

    private static int ResolveIslandId(NavigationWorld world, int x, int y)
    {
        if (world == null || world.IslandIds == null || x < 0 || x >= world.Width || y < 0 || y >= world.Height)
            return -1;
        if (TryGetSectorForCell(world, x, y, out SectorData sector) && sector.UniformIslandId > 0)
            return sector.UniformIslandId;

        if (world.IslandIds.Length != world.Width * world.Height)
            return -1;
        return world.IslandIds[world.GetIndex(x, y)];
    }

    private static string BuildIslandNeighborhoodDiagnostics(NavigationWorld world, int centerX, int centerY, int radius)
    {
        if (world == null)
            return "world-null";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append("[");
        bool first = true;
        for (int y = centerY - radius; y <= centerY + radius; y++)
        {
            for (int x = centerX - radius; x <= centerX + radius; x++)
            {
                if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
                    continue;

                if (!first)
                    builder.Append("; ");
                first = false;

                int index = world.GetIndex(x, y);
                builder.Append("(");
                builder.Append(x);
                builder.Append(",");
                builder.Append(y);
                builder.Append("){walk=");
                builder.Append(world.WalkableMask != null && world.WalkableMask.Length == world.Width * world.Height && world.WalkableMask[index]);
                builder.Append(",base=");
                builder.Append(world.BaseWalkableMask != null && world.BaseWalkableMask.Length == world.Width * world.Height && world.BaseWalkableMask[index]);
                builder.Append(",island=");
                builder.Append(world.IslandIds != null && world.IslandIds.Length == world.Width * world.Height ? world.IslandIds[index] : -1);
                builder.Append(",mask=0x");
                builder.Append(world.NeighborTraversalMask != null && world.NeighborTraversalMask.Length == world.Width * world.Height
                    ? world.NeighborTraversalMask[index].ToString("X2")
                    : "NA");
                builder.Append(",sector=");
                builder.Append(world.TryGetSectorId(x, y, out int sectorId) ? sectorId : -1);
                builder.Append("}");
            }
        }

        builder.Append("]");
        return builder.ToString();
    }

    private static string BuildGoalResolutionIslandDiagnostics(
        NavigationWorld world,
        IEntityContext self,
        Vector3 desiredGoal,
        int startX,
        int startY,
        int goalX,
        int goalY,
        int startIsland,
        int radiusCells,
        bool fullIslandFound,
        int fullIslandX,
        int fullIslandY,
        float fullIslandDistance)
    {
        if (world == null)
            return $"[FlowGoalResolutionIslandDiag] world=null desired={desiredGoal}";

        int goalIsland = ResolveIslandIdForDiagnostics(world, goalX, goalY);
        Vector3 startWorld = world.GridToWorldCenter(startX, startY);
        Vector3 goalWorld = world.GridToWorldCenter(goalX, goalY);
        string fullIslandResult = fullIslandFound
            ? $"fullIslandNearest=({fullIslandX},{fullIslandY}) world={world.GridToWorldCenter(fullIslandX, fullIslandY)} dist={fullIslandDistance:F3}"
            : "fullIslandNearest=none";
        IEntityContext target = self?.TargetComp?.CurrentTarget;
        string selfInfo = self != null
            ? $"self={self.CharacterKey} side={self.Side} pos={self.Position} moveMode={(self.MoveExecutor != null ? self.MoveExecutor.MovementMode.ToString() : "null")}"
            : "self=null";
        string targetInfo = target != null
            ? $"target={target.CharacterKey} side={target.Side} pos={target.Position} moveMode={(target.MoveExecutor != null ? target.MoveExecutor.MovementMode.ToString() : "null")}"
            : "target=null";
        string startNeighborhood = BuildWalkableNeighborhoodDiagnostics(world, startX, startY, 2);
        string goalNeighborhood = BuildWalkableNeighborhoodDiagnostics(world, goalX, goalY, 2);

        return $"[FlowGoalResolutionIslandDiag] local same-island goal resolution failed desired={desiredGoal} " +
               $"start=({startX},{startY}) island={startIsland} world={startWorld} " +
               $"goal=({goalX},{goalY}) island={goalIsland} world={goalWorld} radiusCells={radiusCells} " +
               $"worldVersion={world.Version} agentType={world.AgentTypeId} islandCount={world.IslandCount} " +
               $"runtimeDirtySectors={(_activeWorldState != null ? _activeWorldState.DirtyRuntimeObstacleSectors.Count : -1)} " +
               $"runtimeDirtyReason={_lastRuntimeObstacleDirtyReason} circleObstacles={CircleObstacles.Count} boxObstacles={BoxObstacles.Count} " +
               $"{fullIslandResult} {selfInfo} {targetInfo} desiredGrid={FormatGridSampleDiagnostics(desiredGoal)} " +
               $"startGrid={FormatGridSampleDiagnostics(startWorld)} goalCellGrid={FormatGridSampleDiagnostics(goalWorld)} " +
               $"startNeighborhood={startNeighborhood} startLinks={BuildNeighborLinkDiagnostics(world, startX, startY, 2)} " +
               $"goalNeighborhood={goalNeighborhood} goalLinks={BuildNeighborLinkDiagnostics(world, goalX, goalY, 2)}";
    }

    private static bool TryFindNearestCellInIsland(NavigationWorld world, int startX, int startY, int islandId, int radius, out int resultX, out int resultY, out int distance)
    {
        resultX = 0;
        resultY = 0;
        distance = int.MaxValue;
        if (world == null || world.IslandIds == null || islandId <= 0)
            return false;

        bool found = false;
        for (int y = startY - radius; y <= startY + radius; y++)
        {
            for (int x = startX - radius; x <= startX + radius; x++)
            {
                if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
                    continue;

                if (ResolveIslandId(world, x, y) != islandId)
                    continue;

                int candidateDistance = Mathf.Abs(x - startX) + Mathf.Abs(y - startY);
                if (found && candidateDistance >= distance)
                    continue;

                resultX = x;
                resultY = y;
                distance = candidateDistance;
                found = true;
            }
        }

        return found;
    }

    private static bool TryFindNearestWalkableInIslandByWorldDistanceFixed(
        NavigationWorld world,
        int centerX,
        int centerY,
        FixVector2 desiredWorld,
        int islandId,
        int radius,
        bool allowFullIslandSearch,
        out int resultX,
        out int resultY,
        out Fix64 distance)
    {
        resultX = 0;
        resultY = 0;
        distance = Fix64.FromRaw(long.MaxValue);
        if (world == null || world.IslandIds == null || islandId <= 0)
            return false;

        Fix64 bestDistanceSquared = Fix64.FromRaw(long.MaxValue);
        bool found = TryFindNearestWalkableInIslandByWorldDistanceInBounds(
            world,
            Math.Max(0, centerX - radius),
            Math.Min(world.Width - 1, centerX + radius),
            Math.Max(0, centerY - radius),
            Math.Min(world.Height - 1, centerY + radius),
            desiredWorld,
            islandId,
            ref resultX,
            ref resultY,
            ref bestDistanceSquared);
        if (!found && allowFullIslandSearch)
        {
            found = TryFindNearestWalkableInIslandByWorldDistanceInBounds(
                world,
                0,
                world.Width - 1,
                0,
                world.Height - 1,
                desiredWorld,
                islandId,
                ref resultX,
                ref resultY,
                ref bestDistanceSquared);
        }

        if (found)
            distance = Fix64.Sqrt(bestDistanceSquared);
        return found;
    }

    private static bool TryFindNearestWalkableInIslandByWorldDistance(
        NavigationWorld world,
        int centerX,
        int centerY,
        Vector3 desiredWorld,
        int islandId,
        int radius,
        bool allowFullIslandSearch,
        out int resultX,
        out int resultY,
        out float distance)
    {
        resultX = 0;
        resultY = 0;
        distance = float.PositiveInfinity;
        if (world == null || world.IslandIds == null || islandId <= 0)
            return false;

        FixVector2 desiredFixed = new FixVector2((Fix64)desiredWorld.x, (Fix64)desiredWorld.z);
        Fix64 bestDistanceSquared = Fix64.FromRaw(long.MaxValue);
        bool found = TryFindNearestWalkableInIslandByWorldDistanceInBounds(
            world,
            Mathf.Max(0, centerX - radius),
            Mathf.Min(world.Width - 1, centerX + radius),
            Mathf.Max(0, centerY - radius),
            Mathf.Min(world.Height - 1, centerY + radius),
            desiredFixed,
            islandId,
            ref resultX,
            ref resultY,
            ref bestDistanceSquared);

        if (found || !allowFullIslandSearch)
        {
            if (found)
                distance = (float)Fix64.Sqrt(bestDistanceSquared);
            return found;
        }

        found = TryFindNearestWalkableInIslandByWorldDistanceInBounds(
            world,
            0,
            world.Width - 1,
            0,
            world.Height - 1,
            desiredFixed,
            islandId,
            ref resultX,
            ref resultY,
            ref bestDistanceSquared);
        if (found)
            distance = (float)Fix64.Sqrt(bestDistanceSquared);
        return found;
    }

    private static bool TryFindNearestWalkableInIslandByWorldDistanceInBounds(
        NavigationWorld world,
        int minX,
        int maxX,
        int minY,
        int maxY,
        FixVector2 desiredWorld,
        int islandId,
        ref int resultX,
        ref int resultY,
        ref Fix64 bestDistanceSquared)
    {
        bool found = false;
        for (int y = minY; y <= maxY; y++)
        {
            for (int x = minX; x <= maxX; x++)
            {
                if (!world.IsWalkable(x, y) || ResolveIslandId(world, x, y) != islandId)
                    continue;

                FixVector2 worldCenter = world.GridToWorldCenterFixed(x, y);
                Fix64 dx = worldCenter.x - desiredWorld.x;
                Fix64 dz = worldCenter.y - desiredWorld.y;
                Fix64 candidateDistanceSquared = dx * dx + dz * dz;
                if (found && candidateDistanceSquared >= bestDistanceSquared)
                    continue;

                resultX = x;
                resultY = y;
                bestDistanceSquared = candidateDistanceSquared;
                found = true;
            }
        }

        return found;
    }

    private static string FormatGridSampleDiagnostics(Vector3 position)
    {
        if (_world == null)
            return "world-null";

        bool inGrid = _world.WorldToGrid(position, out int x, out int y);
        bool walkable = inGrid && _world.IsWalkable(x, y);
        int island = inGrid ? ResolveIslandIdForDiagnostics(_world, x, y) : -1;
        return $"grid={(inGrid ? $"({x},{y})" : "out")} walkable={walkable} island={island}";
    }

    private static string BuildGoalResolutionFailure(IEntityContext self, Vector3 goalPosition)
    {
        if (_world == null)
            return $"goal unresolved goal={goalPosition} diag=world-null";

        bool goalInGrid = _world.WorldToGrid(goalPosition, out int goalX, out int goalY);
        bool goalWalkable = goalInGrid && _world.IsWalkable(goalX, goalY);
        bool goalBaseWalkable = false;
        bool nearestWalkableFound = false;
        int nearestWalkableX = 0;
        int nearestWalkableY = 0;
        Vector3 nearestWalkableWorld = Vector3.zero;
        float nearestWalkableDistance = 0f;
        if (goalInGrid)
        {
            int index = _world.GetIndex(goalX, goalY);
            goalBaseWalkable = _world.BaseWalkableMask[index];
            nearestWalkableFound = TryFindNearestWalkable(_world, goalX, goalY, 6, out nearestWalkableX, out nearestWalkableY);
            if (nearestWalkableFound)
            {
                nearestWalkableWorld = _world.GridToWorldCenter(nearestWalkableX, nearestWalkableY);
                nearestWalkableDistance = Vector3.Distance(
                    new Vector3(goalPosition.x, 0f, goalPosition.z),
                    new Vector3(nearestWalkableWorld.x, 0f, nearestWalkableWorld.z));
            }
        }

        int selfAgentType = self is ILogicFrameEntity logicEntity ? logicEntity.NavigationAgentTypeId : 0;
        Vector3 selfPosition = self != null ? self.Position : Vector3.zero;
        bool selfInGrid = _world.WorldToGrid(selfPosition, out int selfX, out int selfY);
        bool selfWalkable = selfInGrid && _world.IsWalkable(selfX, selfY);

        bool startResolved = TryResolveStartCellForReachabilityFixed(
            self,
            out int startX,
            out int startY,
            out int startIsland);
        int startIndex = startResolved ? _world.GetIndex(startX, startY) : -1;
        int startIslandDirect = startIndex >= 0
                                && _world.IslandIds != null
                                && startIndex < _world.IslandIds.Length
            ? _world.IslandIds[startIndex]
            : -1;
        int startSectorUniformIsland = startResolved
                                       && TryGetSectorForCell(_world, startX, startY, out SectorData startSector)
            ? startSector.UniformIslandId
            : -1;
        int fullIslandX = 0;
        int fullIslandY = 0;
        Fix64 fullIslandDistance = Fix64.Zero;
        bool fullIslandFound = startResolved
                               && TryFindNearestWalkableInIslandByWorldDistanceFixed(
                                   _world,
                                   goalX,
                                   goalY,
                                   new FixVector2((Fix64)goalPosition.x, (Fix64)goalPosition.z),
                                   startIsland,
                                   radius: 8,
                                   allowFullIslandSearch: true,
                                   out fullIslandX,
                                   out fullIslandY,
                                   out fullIslandDistance);

        string currentTarget = self?.TargetComp?.CurrentTarget?.CharacterKey ?? "null";
        Vector3 currentTargetPos = self?.TargetComp?.CurrentTarget?.Position ?? Vector3.zero;

        return $"goal unresolved goal={goalPosition} " +
               $"diag=worldAgentType={_world.AgentTypeId} selfAgentType={selfAgentType} " +
               $"worldOrigin={_world.Origin} worldSize={_world.Width}x{_world.Height} cellSize={_world.CellSize:F3} " +
               $"goalCell={(goalInGrid ? $"({goalX},{goalY})" : "out")} goalWalkable={goalWalkable} baseWalkable={goalBaseWalkable} " +
               $"nearestWalkableFound={nearestWalkableFound} nearestWalkableCell={(nearestWalkableFound ? $"({nearestWalkableX},{nearestWalkableY})" : "none")} " +
               $"nearestWalkableWorld={(nearestWalkableFound ? nearestWalkableWorld.ToString() : "none")} nearestWalkableDist={nearestWalkableDistance:F3} " +
               $"goalGridSample={FormatGridSampleDiagnostics(goalPosition)} " +
               $"selfPos={selfPosition} selfCell={(selfInGrid ? $"({selfX},{selfY})" : "out")} selfWalkable={selfWalkable} " +
               $"startResolved={startResolved} startCell={(startResolved ? $"({startX},{startY})" : "none")} " +
               $"startIsland={startIsland} startIslandDirect={startIslandDirect} startSectorUniformIsland={startSectorUniformIsland} " +
               $"islandIdsLength={_world.IslandIds?.Length ?? -1} expectedIslandIdsLength={_world.Width * _world.Height} " +
               $"fullIslandFound={fullIslandFound} fullIslandCell={(fullIslandFound ? $"({fullIslandX},{fullIslandY})" : "none")} " +
               $"fullIslandDistanceRaw={(fullIslandFound ? fullIslandDistance.RawValue : -1L)} " +
               $"runtimeDirtyPending={HasPendingRuntimeDirty(_activeWorldState)} runtimeDirtyReason={_lastRuntimeObstacleDirtyReason} " +
               $"obstacles={BuildNearbyObstacleDiagnostics(goalPosition, goalPosition, _world.AgentTypeId)} " +
               $"target={currentTarget} targetPos={currentTargetPos}";
    }

    private static bool TryFindNearestWalkable(NavigationWorld world, int startX, int startY, int radius, out int resultX, out int resultY)
    {
        for (int r = 1; r <= radius; r++)
        {
            for (int y = -r; y <= r; y++)
            {
                for (int x = -r; x <= r; x++)
                {
                    int nx = startX + x;
                    int ny = startY + y;
                    if (!world.IsWalkable(nx, ny))
                        continue;

                    resultX = nx;
                    resultY = ny;
                    return true;
                }
            }
        }

        resultX = 0;
        resultY = 0;
        return false;
    }

    private static bool TryResolveNearbyStartWalkableFixed(
        NavigationWorld world,
        FixVector2 position,
        int startX,
        int startY,
        out int resultX,
        out int resultY)
    {
        resultX = startX;
        resultY = startY;
        if (world == null)
            throw new InvalidOperationException("TryResolveNearbyStartWalkableFixed failed: world is null.");

        Fix64 maxSnapDistance = ResolveNearbyStartMaxSnapDistanceFixed(
            world,
            IsRuntimeRasterOnlyBlockedCell(world, startX, startY));
        Fix64 bestDistanceSq = maxSnapDistance * maxSnapDistance;
        bool found = false;
        int searchRadiusInCells = Math.Max(1, NavigationGridFixedMath.DivideCeilingByCellSize(maxSnapDistance, world.CellSizeGridRaw));
        for (int y = startY - searchRadiusInCells; y <= startY + searchRadiusInCells; y++)
        {
            for (int x = startX - searchRadiusInCells; x <= startX + searchRadiusInCells; x++)
            {
                if (!world.IsWalkable(x, y))
                    continue;

                world.GetGridCellBoundsFixed(x, y, out FixVector2 minimum, out FixVector2 maximum);
                Fix64 dx = position.x < minimum.x
                    ? minimum.x - position.x
                    : position.x > maximum.x ? position.x - maximum.x : Fix64.Zero;
                Fix64 dz = position.y < minimum.y
                    ? minimum.y - position.y
                    : position.y > maximum.y ? position.y - maximum.y : Fix64.Zero;
                Fix64 distanceSq = dx * dx + dz * dz;
                if (distanceSq > bestDistanceSq)
                    continue;

                bestDistanceSq = distanceSq;
                resultX = x;
                resultY = y;
                found = true;
            }
        }

        return found;
    }

    private static bool TryResolveNearbyStartWalkable(NavigationWorld world, Vector3 position, int startX, int startY, out int resultX, out int resultY)
    {
        resultX = startX;
        resultY = startY;
        if (world == null)
            throw new InvalidOperationException("TryResolveNearbyStartWalkable failed: world is null.");

        Fix64 maxSnapDistance = ResolveNearbyStartMaxSnapDistanceFixed(
            world,
            IsRuntimeRasterOnlyBlockedCell(world, startX, startY));
        Fix64 bestDistanceSq = maxSnapDistance * maxSnapDistance;
        FixVector2 positionFixed = new FixVector2((Fix64)position.x, (Fix64)position.z);
        bool found = false;
        int searchRadiusInCells = Math.Max(1, NavigationGridFixedMath.DivideCeilingByCellSize(maxSnapDistance, world.CellSizeGridRaw));
        for (int y = startY - searchRadiusInCells; y <= startY + searchRadiusInCells; y++)
        {
            for (int x = startX - searchRadiusInCells; x <= startX + searchRadiusInCells; x++)
            {
                if (!world.IsWalkable(x, y))
                    continue;

                world.GetGridCellBoundsFixed(x, y, out FixVector2 minimum, out FixVector2 maximum);
                Fix64 dx = positionFixed.x < minimum.x
                    ? minimum.x - positionFixed.x
                    : positionFixed.x > maximum.x ? positionFixed.x - maximum.x : Fix64.Zero;
                Fix64 dz = positionFixed.y < minimum.y
                    ? minimum.y - positionFixed.y
                    : positionFixed.y > maximum.y ? positionFixed.y - maximum.y : Fix64.Zero;
                Fix64 distanceSq = dx * dx + dz * dz;
                if (distanceSq > bestDistanceSq)
                    continue;

                bestDistanceSq = distanceSq;
                resultX = x;
                resultY = y;
                found = true;
            }
        }

        return found;
    }

    private static bool IsRuntimeRasterOnlyBlockedCell(NavigationWorld world, int x, int y)
    {
        if (world == null)
            throw new InvalidOperationException("IsRuntimeRasterOnlyBlockedCell failed: world is null.");
        if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
            return false;
        if (world.BaseWalkableMask == null || world.BaseWalkableMask.Length != world.Width * world.Height)
            throw new InvalidOperationException("IsRuntimeRasterOnlyBlockedCell failed: base walkable mask is invalid.");

        int index = world.GetIndex(x, y);
        return world.BaseWalkableMask[index] && !world.WalkableMask[index];
    }

    private static Fix64 ResolveNearbyStartMaxSnapDistanceFixed(NavigationWorld world, bool allowRuntimeRasterHalo)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveNearbyStartMaxSnapDistanceFixed failed: world is null.");

        Fix64 cellSize = world.CellSizeFixed;
        Fix64 authoredBlockerSnapDistance = Fix64.Max(
            cellSize * Fix64.FromRaw(1844),
            Fix64.FromRaw(1024));
        if (!allowRuntimeRasterHalo)
            return authoredBlockerSnapDistance;

        Fix64 rasterClearance = Fix64.Max(
            Fix64.Zero,
            world.AgentRadiusFixed - cellSize * Fix64.FromRaw(820));
        Fix64 maximumAxisGap = rasterClearance + cellSize * Fix64.FromRaw(2048);
        Fix64 rasterDiagonalGap = Fix64.Sqrt(maximumAxisGap * maximumAxisGap * (Fix64)2);
        return Fix64.Max(authoredBlockerSnapDistance, rasterDiagonalGap);
    }

    private static bool HasGridLineOfSight(NavigationWorld world, int x0, int y0, int x1, int y1)
    {
        return HasGridLineOfSight(world, x0, y0, x1, y1, allowTargetSoftCost: false);
    }

    private static bool HasGridLineOfSight(NavigationWorld world, int x0, int y0, int x1, int y1, bool allowTargetSoftCost)
    {
        return HasSupercoverGridLineOfSight(
            world,
            x0,
            y0,
            x1,
            y1,
            GridLineOfSightCostMode.Strict,
            allowTargetSoftCost,
            maxAllowedCost: 1);
    }

    private static bool HasFixedGridLineOfSight(
        NavigationWorld world,
        FixVector2 from,
        FixVector2 to,
        bool allowTargetSoftCost)
    {
        if (!world.WorldToGridFixed(from, out int startX, out int startY)
            || !world.WorldToGridFixed(to, out int goalX, out int goalY))
        {
            return false;
        }
        if (!IsGridLineOfSightCellPassable(
                world,
                startX,
                startY,
                goalX,
                goalY,
                GridLineOfSightCostMode.DirectShortcut,
                allowTargetSoftCost,
                maxAllowedCost: 1))
        {
            return false;
        }
        if (startX == goalX && startY == goalY)
            return true;

        long fromXGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(from.x);
        long fromYGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(from.y);
        long toXGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(to.x);
        long toYGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(to.y);
        long displacementXGridRaw = checked(toXGridRaw - fromXGridRaw);
        long displacementYGridRaw = checked(toYGridRaw - fromYGridRaw);
        long absoluteXGridRaw = Math.Abs(displacementXGridRaw);
        long absoluteYGridRaw = Math.Abs(displacementYGridRaw);
        int stepX = Math.Sign(displacementXGridRaw);
        int stepY = Math.Sign(displacementYGridRaw);

        int currentX = startX;
        int currentY = startY;
        int guard = (Math.Abs(goalX - startX) + Math.Abs(goalY - startY) + 4) * 4;
        for (int i = 0; i < guard; i++)
        {
            if (currentX == goalX && currentY == goalY)
                return true;

            int stepAxis = ResolveFixedGridRayStepAxis(
                world,
                fromXGridRaw,
                fromYGridRaw,
                absoluteXGridRaw,
                absoluteYGridRaw,
                currentX,
                currentY,
                goalX,
                goalY,
                stepX,
                stepY,
                out _,
                out _);
            if (stepAxis == 0)
            {
                int sideX = currentX + stepX;
                int sideY = currentY + stepY;
                if (!IsGridLineOfSightStepPassable(world, currentX, currentY, sideX, currentY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1)
                    || !IsGridLineOfSightStepPassable(world, currentX, currentY, currentX, sideY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1)
                    || !IsGridLineOfSightStepPassable(world, sideX, currentY, sideX, sideY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1)
                    || !IsGridLineOfSightStepPassable(world, currentX, sideY, sideX, sideY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1))
                {
                    return false;
                }

                currentX = sideX;
                currentY = sideY;
                continue;
            }

            int nextX = currentX;
            int nextY = currentY;
            if (stepAxis < 0)
            {
                nextX += stepX;
            }
            else
            {
                nextY += stepY;
            }

            if (!IsGridLineOfSightStepPassable(
                    world,
                    currentX,
                    currentY,
                    nextX,
                    nextY,
                    goalX,
                    goalY,
                    GridLineOfSightCostMode.DirectShortcut,
                    allowTargetSoftCost,
                    maxAllowedCost: 1))
            {
                return false;
            }

            currentX = nextX;
            currentY = nextY;
        }

        throw new InvalidOperationException(
            $"HasFixedGridLineOfSight exceeded traversal guard start=({startX},{startY}), goal=({goalX},{goalY}), guard={guard}.");
    }

    private static string BuildFixedGridLineOfSightDecisionDiagnostic(
        NavigationWorld world,
        FixVector2 from,
        FixVector2 to,
        bool allowTargetSoftCost)
    {
        if (world == null)
            return "world-null";
        if (!world.WorldToGridFixed(from, out int startX, out int startY)
            || !world.WorldToGridFixed(to, out int goalX, out int goalY))
        {
            return "endpoint-out";
        }
        if (!IsGridLineOfSightCellPassable(
                world,
                startX,
                startY,
                goalX,
                goalY,
                GridLineOfSightCostMode.DirectShortcut,
                allowTargetSoftCost,
                maxAllowedCost: 1))
        {
            return $"start-blocked cell=({startX},{startY})";
        }
        if (startX == goalX && startY == goalY)
            return "clear-same-cell";

        long fromXGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(from.x);
        long fromYGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(from.y);
        long toXGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(to.x);
        long toYGridRaw = NavigationGridFixedMath.Fix64ToGridRaw(to.y);
        long displacementXGridRaw = checked(toXGridRaw - fromXGridRaw);
        long displacementYGridRaw = checked(toYGridRaw - fromYGridRaw);
        long absoluteXGridRaw = Math.Abs(displacementXGridRaw);
        long absoluteYGridRaw = Math.Abs(displacementYGridRaw);
        int stepX = Math.Sign(displacementXGridRaw);
        int stepY = Math.Sign(displacementYGridRaw);

        int currentX = startX;
        int currentY = startY;
        int guard = (Math.Abs(goalX - startX) + Math.Abs(goalY - startY) + 4) * 4;
        for (int i = 0; i < guard; i++)
        {
            if (currentX == goalX && currentY == goalY)
                return "clear";

            int stepAxis = ResolveFixedGridRayStepAxis(
                world,
                fromXGridRaw,
                fromYGridRaw,
                absoluteXGridRaw,
                absoluteYGridRaw,
                currentX,
                currentY,
                goalX,
                goalY,
                stepX,
                stepY,
                out long nextXBoundaryDistanceRaw,
                out long nextYBoundaryDistanceRaw);
            if (stepAxis == 0)
            {
                int sideX = currentX + stepX;
                int sideY = currentY + stepY;
                if (!IsGridLineOfSightStepPassable(world, currentX, currentY, sideX, currentY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1))
                    return BuildFixedGridLineOfSightFailureDiagnostic(world, currentX, currentY, sideX, currentY, goalX, goalY, nextXBoundaryDistanceRaw, nextYBoundaryDistanceRaw, "corner-x");
                if (!IsGridLineOfSightStepPassable(world, currentX, currentY, currentX, sideY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1))
                    return BuildFixedGridLineOfSightFailureDiagnostic(world, currentX, currentY, currentX, sideY, goalX, goalY, nextXBoundaryDistanceRaw, nextYBoundaryDistanceRaw, "corner-y");
                if (!IsGridLineOfSightStepPassable(world, sideX, currentY, sideX, sideY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1))
                    return BuildFixedGridLineOfSightFailureDiagnostic(world, sideX, currentY, sideX, sideY, goalX, goalY, nextXBoundaryDistanceRaw, nextYBoundaryDistanceRaw, "corner-x-y");
                if (!IsGridLineOfSightStepPassable(world, currentX, sideY, sideX, sideY, goalX, goalY, GridLineOfSightCostMode.DirectShortcut, allowTargetSoftCost, 1))
                    return BuildFixedGridLineOfSightFailureDiagnostic(world, currentX, sideY, sideX, sideY, goalX, goalY, nextXBoundaryDistanceRaw, nextYBoundaryDistanceRaw, "corner-y-x");

                currentX = sideX;
                currentY = sideY;
                continue;
            }

            int nextX = currentX;
            int nextY = currentY;
            if (stepAxis < 0)
            {
                nextX += stepX;
            }
            else
            {
                nextY += stepY;
            }

            if (!IsGridLineOfSightStepPassable(
                    world,
                    currentX,
                    currentY,
                    nextX,
                    nextY,
                    goalX,
                    goalY,
                    GridLineOfSightCostMode.DirectShortcut,
                    allowTargetSoftCost,
                    maxAllowedCost: 1))
            {
                return BuildFixedGridLineOfSightFailureDiagnostic(
                    world,
                    currentX,
                    currentY,
                    nextX,
                    nextY,
                    goalX,
                    goalY,
                    nextXBoundaryDistanceRaw,
                    nextYBoundaryDistanceRaw,
                    "step");
            }

            currentX = nextX;
            currentY = nextY;
        }

        return $"guard-exceeded start=({startX},{startY}) goal=({goalX},{goalY}) guard={guard}";
    }

    private static int ResolveFixedGridRayStepAxis(
        NavigationWorld world,
        long fromXGridRaw,
        long fromYGridRaw,
        long absoluteXGridRaw,
        long absoluteYGridRaw,
        int currentX,
        int currentY,
        int goalX,
        int goalY,
        int stepX,
        int stepY,
        out long nextXBoundaryDistanceRaw,
        out long nextYBoundaryDistanceRaw)
    {
        if (currentX == goalX)
        {
            nextXBoundaryDistanceRaw = -1;
            nextYBoundaryDistanceRaw = ResolveFixedGridRayBoundaryDistanceRaw(
                world.OriginZGridRaw, world.CellSizeGridRaw, currentY, stepY, fromYGridRaw);
            return 1;
        }
        if (currentY == goalY)
        {
            nextXBoundaryDistanceRaw = ResolveFixedGridRayBoundaryDistanceRaw(
                world.OriginXGridRaw, world.CellSizeGridRaw, currentX, stepX, fromXGridRaw);
            nextYBoundaryDistanceRaw = -1;
            return -1;
        }

        nextXBoundaryDistanceRaw = ResolveFixedGridRayBoundaryDistanceRaw(
            world.OriginXGridRaw, world.CellSizeGridRaw, currentX, stepX, fromXGridRaw);
        nextYBoundaryDistanceRaw = ResolveFixedGridRayBoundaryDistanceRaw(
            world.OriginZGridRaw, world.CellSizeGridRaw, currentY, stepY, fromYGridRaw);
        return CompareNonNegativeFractions(
            nextXBoundaryDistanceRaw,
            absoluteXGridRaw,
            nextYBoundaryDistanceRaw,
            absoluteYGridRaw);
    }

    private static long ResolveFixedGridRayBoundaryDistanceRaw(
        long originGridRaw,
        long cellSizeGridRaw,
        int currentCell,
        int step,
        long fromGridRaw)
    {
        if (step == 0)
            throw new InvalidOperationException("ResolveFixedGridRayBoundaryDistanceRaw failed: step is zero before reaching the goal cell.");

        long boundaryGridRaw = step > 0
            ? checked(originGridRaw + checked((long)(currentCell + 1) * cellSizeGridRaw))
            : checked(originGridRaw + checked((long)currentCell * cellSizeGridRaw));
        long distanceGridRaw = step > 0
            ? checked(boundaryGridRaw - fromGridRaw)
            : checked(fromGridRaw - boundaryGridRaw);
        if (distanceGridRaw < 0)
        {
            throw new InvalidOperationException(
                $"ResolveFixedGridRayBoundaryDistanceRaw failed: next boundary is behind the ray origin cell={currentCell}, step={step}, distanceRaw={distanceGridRaw}.");
        }

        return distanceGridRaw;
    }

    private static int CompareNonNegativeFractions(
        long leftNumerator,
        long leftDenominator,
        long rightNumerator,
        long rightDenominator)
    {
        if (leftNumerator < 0 || rightNumerator < 0 || leftDenominator <= 0 || rightDenominator <= 0)
            throw new ArgumentOutOfRangeException(nameof(leftNumerator), "Fraction comparison requires non-negative numerators and positive denominators.");

        int direction = 1;
        while (true)
        {
            long leftQuotient = leftNumerator / leftDenominator;
            long rightQuotient = rightNumerator / rightDenominator;
            if (leftQuotient != rightQuotient)
                return direction * leftQuotient.CompareTo(rightQuotient);

            long leftRemainder = leftNumerator % leftDenominator;
            long rightRemainder = rightNumerator % rightDenominator;
            if (leftRemainder == 0 || rightRemainder == 0)
            {
                if (leftRemainder == rightRemainder)
                    return 0;
                return direction * (leftRemainder == 0 ? -1 : 1);
            }

            leftNumerator = leftDenominator;
            leftDenominator = leftRemainder;
            rightNumerator = rightDenominator;
            rightDenominator = rightRemainder;
            direction = -direction;
        }
    }

    private static string BuildFixedGridLineOfSightFailureDiagnostic(
        NavigationWorld world,
        int fromX,
        int fromY,
        int toX,
        int toY,
        int goalX,
        int goalY,
        long nextXBoundaryDistanceRaw,
        long nextYBoundaryDistanceRaw,
        string stage)
    {
        bool walkable = world.IsWalkable(toX, toY);
        bool cellPassable = IsGridLineOfSightCellPassable(
            world,
            toX,
            toY,
            goalX,
            goalY,
            GridLineOfSightCostMode.DirectShortcut,
            allowTargetSoftCost: true,
            maxAllowedCost: 1);
        bool rawLink = walkable && HasRawNeighborTraversal(world, fromX, fromY, toX, toY);
        bool traversable = walkable && CanTraverseNeighborCells(world, fromX, fromY, toX, toY);
        int cost = walkable ? GetCostFieldValueStrict(world, toX, toY) : -1;
        bool costStamp = walkable && IsCellAffectedByCostStamp(world, toX, toY);
        return $"blocked stage={stage} edge=({fromX},{fromY})->({toX},{toY}) " +
               $"walkable={walkable} cellPassable={cellPassable} cost={cost} costStamp={costStamp} " +
               $"rawLink={rawLink} traversable={traversable} nextBoundaryDistanceRaw=({nextXBoundaryDistanceRaw},{nextYBoundaryDistanceRaw})";
    }

    private static bool HasClearanceGridLineOfSight(
        NavigationWorld world,
        int x0,
        int y0,
        int x1,
        int y1,
        Vector3 from,
        Vector3 to,
        float agentRadius,
        bool allowTargetSoftCost)
    {
        if (!HasGridLineOfSight(world, x0, y0, x1, y1, allowTargetSoftCost))
            return false;

        Vector3 horizontal = to - from;
        horizontal.y = 0f;
        if (horizontal.sqrMagnitude <= 0.0001f)
            return true;

        float clearance = ResolveNavigationQueryClearance(world, ResolveNavigationSegmentClearance(world, agentRadius));
        if (!IsNavigationSegmentWalkable(
                world,
                from,
                horizontal,
                clearance,
                requireClearStart: true,
                includeRuntimeObstacleOverlay: true))
            return false;

        if (clearance <= 0.0001f)
            return true;

        Vector3 normal = Vector3.Cross(Vector3.up, horizontal.normalized);
        Vector3 offset = normal * Mathf.Min(clearance, world.CellSize * 0.45f);
        return IsNavigationSegmentWalkable(
                   world,
                   from + offset,
                   horizontal,
                   clearance,
                   requireClearStart: false,
                   includeRuntimeObstacleOverlay: true)
               && IsNavigationSegmentWalkable(
                   world,
                   from - offset,
                   horizontal,
                   clearance,
                   requireClearStart: false,
                   includeRuntimeObstacleOverlay: true);
    }

    private static float ResolveNavigationSegmentClearance(NavigationWorld world, float agentRadius)
    {
        if (world == null)
            return Mathf.Max(0f, agentRadius);

        return Mathf.Max(0f, agentRadius - world.CellSize * 0.2f);
    }

    private static float ResolveNavigationQueryClearance(NavigationWorld world, float requestedClearance)
    {
        requestedClearance = Mathf.Max(0f, requestedClearance);
        if (world == null || requestedClearance <= 0.0001f)
            return requestedClearance;

        float encodedCenterClearance = ResolveNavigationSegmentClearance(world, ResolveAgentTypeRadius(world.AgentTypeId));
        return Mathf.Max(0f, requestedClearance - encodedCenterClearance);
    }

    private static Fix64 ResolveNavigationQueryClearanceFixed(NavigationWorld world, Fix64 requestedClearance)
    {
        requestedClearance = Fix64.Max(Fix64.Zero, requestedClearance);
        if (world == null || requestedClearance <= Fix64.Zero)
            return requestedClearance;

        return Fix64.Max(Fix64.Zero, requestedClearance - world.EncodedCenterClearanceFixed);
    }

    private static float ResolveNavigationExecutionClearance(NavigationWorld world, float requestedClearance)
    {
        requestedClearance = Mathf.Max(0f, requestedClearance);
        if (world == null || requestedClearance <= 0.0001f)
            return requestedClearance;

        return Mathf.Max(0f, requestedClearance - world.EncodedCenterClearance);
    }

    private static bool HasPendingDirectLineOfSight(NavigationWorld world, int x0, int y0, int x1, int y1)
    {
        return HasSupercoverGridLineOfSight(
            world,
            x0,
            y0,
            x1,
            y1,
            GridLineOfSightCostMode.Strict,
            allowTargetSoftCost: false,
            maxAllowedCost: 1);
    }

    private static bool HasSoftCostTolerantGridLineOfSight(NavigationWorld world, int x0, int y0, int x1, int y1, int maxAllowedCost)
    {
        return HasSupercoverGridLineOfSight(
            world,
            x0,
            y0,
            x1,
            y1,
            GridLineOfSightCostMode.SoftCostLimit,
            allowTargetSoftCost: false,
            maxAllowedCost);
    }

    private enum GridLineOfSightCostMode
    {
        Strict,
        DirectShortcut,
        SoftCostLimit
    }

    private static bool HasSupercoverGridLineOfSight(
        NavigationWorld world,
        int x0,
        int y0,
        int x1,
        int y1,
        GridLineOfSightCostMode costMode,
        bool allowTargetSoftCost,
        int maxAllowedCost)
    {
        if (!IsGridLineOfSightCellPassable(world, x0, y0, x1, y1, costMode, allowTargetSoftCost, maxAllowedCost))
            return false;
        if (x0 == x1 && y0 == y1)
            return true;

        int currentX = x0;
        int currentY = y0;
        int stepX = x1 > x0 ? 1 : x1 < x0 ? -1 : 0;
        int stepY = y1 > y0 ? 1 : y1 < y0 ? -1 : 0;
        float deltaX = Mathf.Abs(x1 - x0);
        float deltaY = Mathf.Abs(y1 - y0);
        float tDeltaX = stepX == 0 ? float.PositiveInfinity : 1f / deltaX;
        float tDeltaY = stepY == 0 ? float.PositiveInfinity : 1f / deltaY;
        float tMaxX = stepX == 0 ? float.PositiveInfinity : 0.5f * tDeltaX;
        float tMaxY = stepY == 0 ? float.PositiveInfinity : 0.5f * tDeltaY;
        int guard = (Mathf.Abs(x1 - x0) + Mathf.Abs(y1 - y0) + 4) * 4;

        for (int i = 0; i < guard; i++)
        {
            if (currentX == x1 && currentY == y1)
                return true;

            if (Mathf.Abs(tMaxX - tMaxY) <= 0.000001f)
            {
                int sideX = currentX + stepX;
                int sideY = currentY + stepY;
                if (!IsGridLineOfSightStepPassable(world, currentX, currentY, sideX, currentY, x1, y1, costMode, allowTargetSoftCost, maxAllowedCost))
                    return false;
                if (!IsGridLineOfSightStepPassable(world, currentX, currentY, currentX, sideY, x1, y1, costMode, allowTargetSoftCost, maxAllowedCost))
                    return false;
                if (!IsGridLineOfSightStepPassable(world, sideX, currentY, sideX, sideY, x1, y1, costMode, allowTargetSoftCost, maxAllowedCost))
                    return false;
                if (!IsGridLineOfSightStepPassable(world, currentX, sideY, sideX, sideY, x1, y1, costMode, allowTargetSoftCost, maxAllowedCost))
                    return false;

                currentX = sideX;
                currentY = sideY;
                tMaxX += tDeltaX;
                tMaxY += tDeltaY;
                continue;
            }

            int nextX = currentX;
            int nextY = currentY;
            if (tMaxX < tMaxY)
            {
                nextX += stepX;
                tMaxX += tDeltaX;
            }
            else
            {
                nextY += stepY;
                tMaxY += tDeltaY;
            }

            if (!IsGridLineOfSightStepPassable(world, currentX, currentY, nextX, nextY, x1, y1, costMode, allowTargetSoftCost, maxAllowedCost))
                return false;

            currentX = nextX;
            currentY = nextY;
        }

        return false;
    }

    private static bool IsGridLineOfSightStepPassable(
        NavigationWorld world,
        int fromX,
        int fromY,
        int toX,
        int toY,
        int goalX,
        int goalY,
        GridLineOfSightCostMode costMode,
        bool allowTargetSoftCost,
        int maxAllowedCost)
    {
        return IsGridLineOfSightCellPassable(world, toX, toY, goalX, goalY, costMode, allowTargetSoftCost, maxAllowedCost)
               && CanTraverseNeighborCells(world, fromX, fromY, toX, toY);
    }

    private static bool IsGridLineOfSightCellPassable(
        NavigationWorld world,
        int x,
        int y,
        int goalX,
        int goalY,
        GridLineOfSightCostMode costMode,
        bool allowTargetSoftCost,
        int maxAllowedCost)
    {
        if (!world.IsWalkable(x, y))
            return false;

        int cellCost = GetCostFieldValueStrict(world, x, y);
        if (costMode == GridLineOfSightCostMode.SoftCostLimit)
            return cellCost <= maxAllowedCost;
        if (costMode == GridLineOfSightCostMode.DirectShortcut)
        {
            return cellCost < byte.MaxValue
                   && (!IsCellAffectedByCostStamp(world, x, y)
                       || (allowTargetSoftCost && x == goalX && y == goalY));
        }

        return cellCost <= 1
               || IsBoundaryOnlySoftCostCell(world, x, y)
               || (allowTargetSoftCost && x == goalX && y == goalY);
    }

    private static bool IsDiagonalPassable(NavigationWorld world, int fromX, int fromY, int toX, int toY)
    {
        return world.IsWalkable(fromX, toY)
               && world.IsWalkable(toX, fromY)
               && HasRawNeighborTraversal(world, fromX, fromY, fromX, toY)
               && HasRawNeighborTraversal(world, fromX, fromY, toX, fromY)
               && HasRawNeighborTraversal(world, fromX, toY, toX, toY)
               && HasRawNeighborTraversal(world, toX, fromY, toX, toY);
    }

    private static void RebuildCostFieldForSector(NavigationWorld world, int sectorId, IReadOnlyCollection<CostStamp> costStamps)
    {
        if (world == null)
            throw new InvalidOperationException("RebuildCostFieldForSector failed: world is null.");
        if (sectorId < 0 || sectorId >= world.Sectors.Length)
            throw new InvalidOperationException($"RebuildCostFieldForSector failed: sector id out of range {sectorId}.");
        if (world.CostField == null || world.CostField.Length != world.Width * world.Height)
            world.CostField = new byte[world.Width * world.Height];

        SectorData sector = world.Sectors[sectorId];
        if (world.SourceCostField != null && world.SourceCostField.Length == world.Width * world.Height)
        {
            InitializeAuthoredCostFieldForSector(world, sector, costStamps);
            return;
        }

        int sectorMinX = sector.StartX;
        int sectorMinY = sector.StartY;
        int sectorMaxX = sector.StartX + sector.Width - 1;
        int sectorMaxY = sector.StartY + sector.Height - 1;
        int padding = ResolveWallCostPaddingCells(world, 1);
        int sourceMinX = Mathf.Max(0, sectorMinX - padding);
        int sourceMinY = Mathf.Max(0, sectorMinY - padding);
        int sourceMaxX = Mathf.Min(world.Width - 1, sectorMaxX + padding);
        int sourceMaxY = Mathf.Min(world.Height - 1, sectorMaxY + padding);
        RebuildCostFieldInBounds(world, sourceMinX, sourceMinY, sourceMaxX, sourceMaxY, sectorMinX, sectorMinY, sectorMaxX, sectorMaxY, costStamps);
        sector.IsClearCostField = IsSectorCostFieldClear(world, sector);
        sector.IsClearFlowTile = IsSectorClearFlowTile(world, sector);
    }

    private static void InitializeAuthoredCostFieldForSector(NavigationWorld world, SectorData sector, IReadOnlyCollection<CostStamp> costStamps)
    {
        if (world == null)
            throw new InvalidOperationException("InitializeAuthoredCostFieldForSector failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("InitializeAuthoredCostFieldForSector failed: sector is null.");
        if (world.CostField == null || world.CostField.Length != world.Width * world.Height)
            throw new InvalidOperationException("InitializeAuthoredCostFieldForSector failed: authored cost field is missing.");

        for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
        {
            for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
            {
                int index = world.GetIndex(x, y);
                byte cost = world.SourceCostField != null && world.SourceCostField.Length == world.Width * world.Height
                    ? world.SourceCostField[index]
                    : world.CostField[index];
                if (!world.WalkableMask[index])
                {
                    world.CostField[index] = byte.MaxValue;
                    continue;
                }

                world.CostField[index] = cost == 0 || cost == byte.MaxValue ? (byte)1 : cost;
            }
        }

        ApplyCostStampsInBounds(
            world,
            sector.StartX,
            sector.StartY,
            sector.StartX + sector.Width - 1,
            sector.StartY + sector.Height - 1,
            costStamps);
        ApplyDynamicObstacleBlurToAuthoredCostSector(world, sector);
        sector.IsClearCostField = IsSectorCostFieldClear(world, sector);
        sector.IsClearFlowTile = IsSectorClearFlowTile(world, sector);
    }

    private static void ApplyDynamicObstacleBlurToAuthoredCostSector(NavigationWorld world, SectorData sector)
    {
        if (world.SourceCostField == null || world.SourceCostField.Length != world.Width * world.Height)
            return;

        int sectorMinX = sector.StartX;
        int sectorMinY = sector.StartY;
        int sectorMaxX = sector.StartX + sector.Width - 1;
        int sectorMaxY = sector.StartY + sector.Height - 1;
        int padding = ResolveWallCostPaddingCells(world, 1);
        int sourceMinX = Mathf.Max(0, sectorMinX - padding);
        int sourceMinY = Mathf.Max(0, sectorMinY - padding);
        int sourceMaxX = Mathf.Min(world.Width - 1, sectorMaxX + padding);
        int sourceMaxY = Mathf.Min(world.Height - 1, sectorMaxY + padding);

        int sourceWidth = sourceMaxX - sourceMinX + 1;
        int sourceHeight = sourceMaxY - sourceMinY + 1;
        long[] wallDistance = CreateInitializedWallDistance(sourceWidth * sourceHeight);
        long wallCostBlurRadiusRaw = ResolveWallCostBlurRadiusCellsFixed(world).RawValue;
        DeterministicCostHeap openSet = new DeterministicCostHeap();
        for (int y = sourceMinY; y <= sourceMaxY; y++)
        {
            for (int x = sourceMinX; x <= sourceMaxX; x++)
            {
                int index = world.GetIndex(x, y);
                bool baseWalkable = world.BaseWalkableMask != null
                                    && world.BaseWalkableMask.Length == world.Width * world.Height
                                    && world.BaseWalkableMask[index];
                if (!baseWalkable)
                    continue;

                if (!world.WalkableMask[index])
                {
                    int blockedLocalIndex = GetLocalCostFieldIndex(x, y, sourceMinX, sourceMinY, sourceWidth);
                    wallDistance[blockedLocalIndex] = 0L;
                    openSet.Push(blockedLocalIndex, 0L);
                    continue;
                }

                if (TouchesDynamicBlockedOrUntraversableNeighbor(world, x, y))
                {
                    int localIndex = GetLocalCostFieldIndex(x, y, sourceMinX, sourceMinY, sourceWidth);
                    wallDistance[localIndex] = DeterministicPortalCostScale;
                    openSet.Push(localIndex, DeterministicPortalCostScale);
                }
            }
        }

        while (openSet.Count > 0)
        {
            DeterministicCostQueueNode node = openSet.Pop();
            if (node.Cost != wallDistance[node.Index])
                continue;
            if (node.Cost >= wallCostBlurRadiusRaw)
                continue;

            int worldX = sourceMinX + node.Index % sourceWidth;
            int worldY = sourceMinY + node.Index / sourceWidth;
            for (int i = 0; i < NeighborOffsetX.Length; i++)
            {
                int nextX = worldX + NeighborOffsetX[i];
                int nextY = worldY + NeighborOffsetY[i];
                if (nextX < sourceMinX || nextX > sourceMaxX || nextY < sourceMinY || nextY > sourceMaxY)
                    continue;

                int nextIndex = world.GetIndex(nextX, nextY);
                if (!world.WalkableMask[nextIndex])
                    continue;

                long stepCost = NeighborOffsetX[i] != 0 && NeighborOffsetY[i] != 0
                    ? DeterministicPortalDiagonalCost
                    : DeterministicPortalCostScale;
                long newDistance = checked(node.Cost + stepCost);
                int nextLocalIndex = GetLocalCostFieldIndex(nextX, nextY, sourceMinX, sourceMinY, sourceWidth);
                if (newDistance >= wallDistance[nextLocalIndex] || newDistance > wallCostBlurRadiusRaw)
                    continue;

                wallDistance[nextLocalIndex] = newDistance;
                openSet.Push(nextLocalIndex, newDistance);
            }
        }

        int adjacentPenalty = ResolveWallCostAdjacentPenalty(world);
        int outerPenalty = adjacentPenalty > WallCostAdjacentPenalty ? 1 : WallCostOuterPenalty;
        for (int y = sectorMinY; y <= sectorMaxY; y++)
        {
            for (int x = sectorMinX; x <= sectorMaxX; x++)
            {
                int index = world.GetIndex(x, y);
                if (!world.WalkableMask[index])
                    continue;

                long distance = wallDistance[GetLocalCostFieldIndex(x, y, sourceMinX, sourceMinY, sourceWidth)];
                if (distance == long.MaxValue || distance > wallCostBlurRadiusRaw)
                    continue;

                int penalty = ResolveWallCostPenalty(distance, wallCostBlurRadiusRaw, outerPenalty, adjacentPenalty);
                world.CostField[index] = (byte)Mathf.Clamp(Mathf.Max(world.CostField[index], 1 + penalty), 1, 254);
            }
        }
    }

    private static bool TouchesDynamicBlockedOrUntraversableNeighbor(NavigationWorld world, int x, int y)
    {
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int nx = x + NeighborOffsetX[i];
            int ny = y + NeighborOffsetY[i];
            if (nx < 0 || nx >= world.Width || ny < 0 || ny >= world.Height)
                continue;

            int neighborIndex = world.GetIndex(nx, ny);
            bool baseWalkable = world.BaseWalkableMask != null
                                && world.BaseWalkableMask.Length == world.Width * world.Height
                                && world.BaseWalkableMask[neighborIndex];
            if (baseWalkable && !world.WalkableMask[neighborIndex])
                return true;
        }

        return false;
    }

    private static void RebuildCostFieldInBounds(
        NavigationWorld world,
        int sourceMinX,
        int sourceMinY,
        int sourceMaxX,
        int sourceMaxY,
        int writeMinX,
        int writeMinY,
        int writeMaxX,
        int writeMaxY,
        IReadOnlyCollection<CostStamp> costStamps)
    {
        int sourceWidth = sourceMaxX - sourceMinX + 1;
        int sourceHeight = sourceMaxY - sourceMinY + 1;
        long[] wallDistance = CreateInitializedWallDistance(sourceWidth * sourceHeight);
        long wallCostBlurRadiusRaw = ResolveWallCostBlurRadiusCellsFixed(world).RawValue;

        DeterministicCostHeap openSet = new DeterministicCostHeap();
        for (int y = sourceMinY; y <= sourceMaxY; y++)
        {
            for (int x = sourceMinX; x <= sourceMaxX; x++)
            {
                int index = world.GetIndex(x, y);
                if (!world.WalkableMask[index])
                {
                    if (IsInsideBounds(x, y, writeMinX, writeMinY, writeMaxX, writeMaxY))
                        world.CostField[index] = 255;
                    int blockedLocalIndex = GetLocalCostFieldIndex(x, y, sourceMinX, sourceMinY, sourceWidth);
                    wallDistance[blockedLocalIndex] = 0L;
                    openSet.Push(blockedLocalIndex, 0L);
                    continue;
                }

                if (IsInsideBounds(x, y, writeMinX, writeMinY, writeMaxX, writeMaxY))
                    world.CostField[index] = 1;
                if (!TouchesBlockedOrUntraversableNeighbor(world, x, y))
                    continue;

                int localIndex = GetLocalCostFieldIndex(x, y, sourceMinX, sourceMinY, sourceWidth);
                wallDistance[localIndex] = DeterministicPortalCostScale;
                openSet.Push(localIndex, DeterministicPortalCostScale);
            }
        }

        while (openSet.Count > 0)
        {
            DeterministicCostQueueNode node = openSet.Pop();
            if (node.Cost != wallDistance[node.Index])
                continue;
            if (node.Cost >= wallCostBlurRadiusRaw)
                continue;

            int worldX = sourceMinX + node.Index % sourceWidth;
            int worldY = sourceMinY + node.Index / sourceWidth;
            for (int i = 0; i < NeighborOffsetX.Length; i++)
            {
                int nextX = worldX + NeighborOffsetX[i];
                int nextY = worldY + NeighborOffsetY[i];
                if (nextX < sourceMinX || nextX > sourceMaxX || nextY < sourceMinY || nextY > sourceMaxY)
                    continue;

                int nextIndex = world.GetIndex(nextX, nextY);
                if (!world.WalkableMask[nextIndex])
                    continue;

                long stepCost = NeighborOffsetX[i] != 0 && NeighborOffsetY[i] != 0
                    ? DeterministicPortalDiagonalCost
                    : DeterministicPortalCostScale;
                long newDistance = checked(node.Cost + stepCost);
                int nextLocalIndex = GetLocalCostFieldIndex(nextX, nextY, sourceMinX, sourceMinY, sourceWidth);
                if (newDistance >= wallDistance[nextLocalIndex] || newDistance > wallCostBlurRadiusRaw)
                    continue;

                wallDistance[nextLocalIndex] = newDistance;
                openSet.Push(nextLocalIndex, newDistance);
            }
        }

        for (int y = writeMinY; y <= writeMaxY; y++)
        {
            for (int x = writeMinX; x <= writeMaxX; x++)
            {
                int index = world.GetIndex(x, y);
                if (!world.WalkableMask[index])
                {
                    world.CostField[index] = 255;
                    continue;
                }

                int penalty = ResolveSlopeCostPenalty(world, x, y);
                long distance = wallDistance[GetLocalCostFieldIndex(x, y, sourceMinX, sourceMinY, sourceWidth)];
                if (distance != long.MaxValue && distance <= wallCostBlurRadiusRaw)
                {
                    int adjacentPenalty = ResolveWallCostAdjacentPenalty(world);
                    int outerPenalty = adjacentPenalty > WallCostAdjacentPenalty ? 1 : WallCostOuterPenalty;
                    penalty += ResolveWallCostPenalty(distance, wallCostBlurRadiusRaw, outerPenalty, adjacentPenalty);
                }

                world.CostField[index] = (byte)Mathf.Clamp(1 + penalty, 1, 254);
            }
        }

        ApplyCostStampsInBounds(world, writeMinX, writeMinY, writeMaxX, writeMaxY, costStamps);
    }

    private static Fix64 ResolveWallCostBlurRadiusCellsFixed(NavigationWorld world)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveWallCostBlurRadiusCellsFixed failed: world is null.");

        Fix64 extraRadius = Fix64.Max(
            Fix64.Zero,
            world.AgentRadiusFixed - Fix64.FromRaw(2048));
        Fix64 extraRadiusCells = NavigationGridFixedMath.DivideByCellSize(
            extraRadius,
            world.CellSizeGridRaw);
        return Fix64.FromRaw(WallCostBlurRadiusRaw) + extraRadiusCells;
    }

    private static int ResolveWallCostPaddingCells(NavigationWorld world, int extraPadding)
    {
        if (extraPadding < 0)
            throw new ArgumentOutOfRangeException(nameof(extraPadding), extraPadding, "Wall cost padding cannot be negative.");
        return checked((int)(long)Fix64.Ceiling(ResolveWallCostBlurRadiusCellsFixed(world)) + extraPadding);
    }

    private static long[] CreateInitializedWallDistance(int length)
    {
        if (length <= 0)
            throw new InvalidOperationException($"CreateInitializedWallDistance failed: invalid length {length}.");

        long[] wallDistance = new long[length];
        for (int i = 0; i < wallDistance.Length; i++)
            wallDistance[i] = long.MaxValue;

        return wallDistance;
    }

    private static int ResolveWallCostPenalty(long distanceRaw, long radiusRaw, int outerPenalty, int adjacentPenalty)
    {
        if (distanceRaw < 0 || radiusRaw <= 0 || distanceRaw > radiusRaw)
            throw new ArgumentOutOfRangeException(nameof(distanceRaw), distanceRaw, $"Invalid wall cost distance/radius distance={distanceRaw} radius={radiusRaw}.");
        if (outerPenalty < 0 || adjacentPenalty < outerPenalty)
            throw new ArgumentOutOfRangeException(nameof(outerPenalty), outerPenalty, $"Invalid wall penalties outer={outerPenalty} adjacent={adjacentPenalty}.");

        long denominatorRaw = Math.Max(Fix64.FromRaw(5).RawValue, radiusRaw - Fix64.One.RawValue);
        Fix64 t = Fix64.Clamp(
            Fix64.FromRaw(radiusRaw - distanceRaw) / Fix64.FromRaw(denominatorRaw),
            Fix64.Zero,
            Fix64.One);
        Fix64 interpolated = (Fix64)outerPenalty + (Fix64)(adjacentPenalty - outerPenalty) * t;
        return RoundNonNegativeFix64ToIntMidpointToEven(interpolated);
    }

    private static int RoundNonNegativeFix64ToIntMidpointToEven(Fix64 value)
    {
        if (value < Fix64.Zero)
            throw new ArgumentOutOfRangeException(nameof(value), value.RawValue, "Wall cost penalty cannot be negative.");

        long whole = value.RawValue / Fix64.One.RawValue;
        long remainder = value.RawValue % Fix64.One.RawValue;
        long half = Fix64.One.RawValue / 2;
        if (remainder > half || (remainder == half && (whole & 1L) != 0L))
            whole = checked(whole + 1L);
        return checked((int)whole);
    }

    private static int GetLocalCostFieldIndex(int worldX, int worldY, int minX, int minY, int width)
    {
        int localX = worldX - minX;
        int localY = worldY - minY;
        int index = localX + localY * width;
        if (localX < 0 || localX >= width || localY < 0 || index < 0)
            throw new InvalidOperationException(
                $"GetLocalCostFieldIndex failed: cell=({worldX},{worldY}) origin=({minX},{minY}) width={width} local=({localX},{localY}).");

        return index;
    }

    private static int ResolveWallCostAdjacentPenalty(NavigationWorld world)
    {
        if (world == null)
            throw new InvalidOperationException("ResolveWallCostAdjacentPenalty failed: world is null.");

        Fix64 extraRadius = Fix64.Max(
            Fix64.Zero,
            world.AgentRadiusFixed - Fix64.FromRaw(2048));
        int extraRadiusCells = NavigationGridFixedMath.DivideCeilingByCellSize(
            extraRadius,
            world.CellSizeGridRaw);
        return WallCostAdjacentPenalty + extraRadiusCells;
    }

    private static int ResolveSlopeCostPenalty(NavigationWorld world, int worldX, int worldY)
    {
        return 0;
    }

    private static void ApplyCostStampsInBounds(NavigationWorld world, int writeMinX, int writeMinY, int writeMaxX, int writeMaxY, IReadOnlyCollection<CostStamp> costStamps)
    {
        if (costStamps == null)
            costStamps = CostStamps.Values;

        if (costStamps.Count == 0)
            return;

        foreach (CostStamp stamp in costStamps)
        {
            if (stamp.AgentTypeId != AnyAgentTypeId && stamp.AgentTypeId != world.AgentTypeId)
                continue;

            world.WorldToGridFixed(stamp.BoundsMinFixed, out int rawMinX, out int rawMinY);
            world.WorldToGridFixed(stamp.BoundsMaxFixed, out int rawMaxX, out int rawMaxY);
            int minX = Mathf.Max(rawMinX, writeMinX);
            int maxX = Mathf.Min(rawMaxX, writeMaxX);
            int minY = Mathf.Max(rawMinY, writeMinY);
            int maxY = Mathf.Min(rawMaxY, writeMaxY);
            if (minX > maxX || minY > maxY)
                continue;

            for (int y = minY; y <= maxY; y++)
            {
                int rowStart = y * world.Width;
                for (int x = minX; x <= maxX; x++)
                {
                    int index = rowStart + x;
                    if (!world.WalkableMask[index] || world.CostField[index] >= 255)
                        continue;

                    if (!TryResolveCostStampCellCost(world, stamp, x, y, out byte stampCost))
                        continue;

                    world.CostField[index] = stampCost;
                }
            }
        }
    }

    private static bool TryResolveCostStampCellCost(NavigationWorld world, CostStamp stamp, int worldX, int worldY, out byte cost)
    {
        cost = stamp.Cost;
        if (stamp.Costs == null)
            return true;
        if (stamp.Width <= 0 || stamp.Height <= 0 || stamp.CellSizeGridRaw <= 0)
            throw new InvalidOperationException($"TryResolveCostStampCellCost failed: invalid grid stamp id={stamp.Id} size={stamp.Width}x{stamp.Height} cellSize={stamp.CellSize}.");
        if (stamp.Costs.Length != stamp.Width * stamp.Height)
            throw new InvalidOperationException($"TryResolveCostStampCellCost failed: grid stamp costs length {stamp.Costs.Length} does not match {stamp.Width}x{stamp.Height} id={stamp.Id}.");

        long centerXGridRaw = NavigationGridFixedMath.GridCellCenterRaw(
            world.OriginXGridRaw,
            world.CellSizeGridRaw,
            worldX);
        long centerYGridRaw = NavigationGridFixedMath.GridCellCenterRaw(
            world.OriginZGridRaw,
            world.CellSizeGridRaw,
            worldY);
        int stampX = NavigationGridFixedMath.GridRawToCell(
            centerXGridRaw,
            stamp.OriginXGridRaw,
            stamp.CellSizeGridRaw);
        int stampY = NavigationGridFixedMath.GridRawToCell(
            centerYGridRaw,
            stamp.OriginZGridRaw,
            stamp.CellSizeGridRaw);
        if (stampX < 0 || stampX >= stamp.Width || stampY < 0 || stampY >= stamp.Height)
            return false;

        cost = stamp.Costs[stampX + stampY * stamp.Width];
        return true;
    }

    private static bool IsCellAffectedByCostStamp(NavigationWorld world, int worldX, int worldY)
    {
        if (CostStamps.Count == 0)
            return false;

        foreach (CostStamp stamp in CostStamps.Values)
        {
            if (stamp.AgentTypeId != AnyAgentTypeId && stamp.AgentTypeId != world.AgentTypeId)
                continue;

            world.WorldToGridFixed(stamp.BoundsMinFixed, out int rawMinX, out int rawMinY);
            world.WorldToGridFixed(stamp.BoundsMaxFixed, out int rawMaxX, out int rawMaxY);
            if (worldX < rawMinX || worldX > rawMaxX || worldY < rawMinY || worldY > rawMaxY)
                continue;

            if (!world.WalkableMask[world.GetIndex(worldX, worldY)] || GetCostFieldValueStrict(world, worldX, worldY) >= 255)
                continue;

            if (TryResolveCostStampCellCost(world, stamp, worldX, worldY, out _))
                return true;
        }

        return false;
    }

    private static bool IsInsideBounds(int x, int y, int minX, int minY, int maxX, int maxY)
    {
        return x >= minX && x <= maxX && y >= minY && y <= maxY;
    }

    private static void ResolveSectorBounds(NavigationWorld world, HashSet<int> sectorIds, out int minX, out int minY, out int maxX, out int maxY)
    {
        minX = world.Width - 1;
        minY = world.Height - 1;
        maxX = 0;
        maxY = 0;
        bool found = false;
        foreach (int sectorId in sectorIds)
        {
            SectorData sector = world.Sectors[sectorId];
            minX = Mathf.Min(minX, sector.StartX);
            minY = Mathf.Min(minY, sector.StartY);
            maxX = Mathf.Max(maxX, sector.StartX + sector.Width - 1);
            maxY = Mathf.Max(maxY, sector.StartY + sector.Height - 1);
            found = true;
        }

        if (!found)
            throw new InvalidOperationException("ResolveSectorBounds failed: sector set is empty.");
    }

    private static HashSet<int> ExpandDirtySectorsByCellRadius(NavigationWorld world, HashSet<int> sectorIds, int radiusCells)
    {
        if (world == null)
            throw new InvalidOperationException("ExpandDirtySectorsByCellRadius failed: world is null.");
        if (sectorIds == null)
            throw new InvalidOperationException("ExpandDirtySectorsByCellRadius failed: sectorIds is null.");

        HashSet<int> expanded = new HashSet<int>(sectorIds);
        if (sectorIds.Count == 0)
            return expanded;

        int clampedRadius = Mathf.Max(0, radiusCells);
        foreach (int sectorId in sectorIds)
        {
            if (sectorId < 0 || sectorId >= world.Sectors.Length)
                throw new InvalidOperationException($"ExpandDirtySectorsByCellRadius failed: sector id out of range {sectorId}.");

            SectorData sector = world.Sectors[sectorId];
            int minX = Mathf.Max(0, sector.StartX - clampedRadius);
            int minY = Mathf.Max(0, sector.StartY - clampedRadius);
            int maxX = Mathf.Min(world.Width - 1, sector.StartX + sector.Width - 1 + clampedRadius);
            int maxY = Mathf.Min(world.Height - 1, sector.StartY + sector.Height - 1 + clampedRadius);

            int minSectorX = Mathf.Clamp(minX / world.SectorSizeInCells, 0, world.SectorCountX - 1);
            int maxSectorX = Mathf.Clamp(maxX / world.SectorSizeInCells, 0, world.SectorCountX - 1);
            int minSectorY = Mathf.Clamp(minY / world.SectorSizeInCells, 0, world.SectorCountY - 1);
            int maxSectorY = Mathf.Clamp(maxY / world.SectorSizeInCells, 0, world.SectorCountY - 1);
            for (int sy = minSectorY; sy <= maxSectorY; sy++)
            {
                for (int sx = minSectorX; sx <= maxSectorX; sx++)
                    expanded.Add(sy * world.SectorCountX + sx);
            }
        }

        return expanded;
    }

    private static bool TouchesBlockedOrUntraversableNeighbor(NavigationWorld world, int centerX, int centerY)
    {
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int nextX = centerX + NeighborOffsetX[i];
            int nextY = centerY + NeighborOffsetY[i];
            if (nextX < 0 || nextX >= world.Width || nextY < 0 || nextY >= world.Height)
                return true;
            if (!world.IsWalkable(nextX, nextY))
                return true;
            if (!CanTraverseNeighborCells(world, centerX, centerY, nextX, nextY))
                return true;
        }

        return false;
    }

    private static bool HasInternalBlockedOrUntraversableNeighbor(NavigationWorld world, int centerX, int centerY)
    {
        for (int i = 0; i < NeighborOffsetX.Length; i++)
        {
            int nextX = centerX + NeighborOffsetX[i];
            int nextY = centerY + NeighborOffsetY[i];
            if (nextX < 0 || nextX >= world.Width || nextY < 0 || nextY >= world.Height)
                continue;
            if (!world.IsWalkable(nextX, nextY))
                return true;
            if (!CanTraverseNeighborCells(world, centerX, centerY, nextX, nextY))
                return true;
        }

        return false;
    }

    private static bool IsBoundaryOnlySoftCostCell(NavigationWorld world, int centerX, int centerY)
    {
        if (IsCellAffectedByCostStamp(world, centerX, centerY))
            return false;

        int centerIndex = world.GetIndex(centerX, centerY);
        if (world.SourceCostField != null
            && world.SourceCostField.Length == world.Width * world.Height
            && world.SourceCostField[centerIndex] > 1
            && world.SourceCostField[centerIndex] < byte.MaxValue)
        {
            return false;
        }

        int radius = ResolveWallCostPaddingCells(world, 0);
        bool hasOutsideWithinRadius = false;
        for (int y = centerY - radius; y <= centerY + radius; y++)
        {
            for (int x = centerX - radius; x <= centerX + radius; x++)
            {
                int dx = x - centerX;
                int dy = y - centerY;
                if (dx * dx + dy * dy > radius * radius)
                    continue;

                if (x < 0 || x >= world.Width || y < 0 || y >= world.Height)
                {
                    hasOutsideWithinRadius = true;
                    continue;
                }

                if (!world.IsWalkable(x, y))
                    return false;
            }
        }

        if (!hasOutsideWithinRadius)
            return false;

        return !HasInternalBlockedOrUntraversableNeighbor(world, centerX, centerY);
    }

    private static float ResolveTraversalCost(NavigationWorld world, int fromX, int fromY, int toX, int toY)
    {
        int fromCost = GetCostFieldValueStrict(world, fromX, fromY);
        int toCost = GetCostFieldValueStrict(world, toX, toY);
        if (fromCost >= 255 || toCost >= 255)
            return float.PositiveInfinity;

        return Mathf.Max(1f, (fromCost + toCost) * 0.5f);
    }

    private static bool IsSectorCostFieldClear(NavigationWorld world, SectorData sector)
    {
        if (world == null)
            throw new InvalidOperationException("IsSectorCostFieldClear failed: world is null.");
        if (sector == null)
            throw new InvalidOperationException("IsSectorCostFieldClear failed: sector is null.");
        if (world.CostField == null || world.CostField.Length != world.Width * world.Height)
            return true;

        for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
        {
            int rowStart = y * world.Width;
            for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
            {
                int index = rowStart + x;
                if (world.WalkableMask[index] && world.CostField[index] != 1)
                    return false;
            }
        }

        return true;
    }

    private static bool IsSectorClearFlowTile(NavigationWorld world, SectorData sector)
    {
        if (!IsSectorCostFieldClear(world, sector))
            return false;
        if (world.NeighborTraversalMask == null || world.NeighborTraversalMask.Length != world.Width * world.Height)
            return false;

        for (int y = sector.StartY; y < sector.StartY + sector.Height; y++)
        {
            for (int x = sector.StartX; x < sector.StartX + sector.Width; x++)
            {
                if (!world.IsWalkable(x, y))
                    return false;

                for (int i = 0; i < NeighborOffsetX.Length; i++)
                {
                    int nextX = x + NeighborOffsetX[i];
                    int nextY = y + NeighborOffsetY[i];
                    if (!IsInsideSector(sector, nextX, nextY))
                        continue;
                    if (!CanTraverseNeighborCells(world, x, y, nextX, nextY))
                        return false;
                }
            }
        }

        return true;
    }

    private static bool TryGetSectorForCell(NavigationWorld world, int worldX, int worldY, out SectorData sector)
    {
        sector = null;
        if (world == null || world.Sectors == null)
            return false;
        if (!world.TryGetSectorId(worldX, worldY, out int sectorId))
            return false;

        sector = world.Sectors[sectorId];
        return sector != null;
    }

    private static bool AreSectorsSameOrAdjacent(NavigationWorld world, int sectorAId, int sectorBId)
    {
        if (world == null)
            throw new InvalidOperationException("AreSectorsSameOrAdjacent failed: world is null.");
        if (world.SectorCountX <= 0)
            throw new InvalidOperationException($"AreSectorsSameOrAdjacent failed: invalid sector grid countX={world.SectorCountX}.");
        if (sectorAId < 0 || sectorAId >= world.Sectors.Length || sectorBId < 0 || sectorBId >= world.Sectors.Length)
            return false;

        int ax = sectorAId % world.SectorCountX;
        int ay = sectorAId / world.SectorCountX;
        int bx = sectorBId % world.SectorCountX;
        int by = sectorBId / world.SectorCountX;
        return Mathf.Abs(ax - bx) <= 1 && Mathf.Abs(ay - by) <= 1;
    }

    private static void LogIslandFieldDiagnostics(NavigationWorld world, string reason)
    {
        if (world == null)
            throw new InvalidOperationException("LogIslandFieldDiagnostics failed: world is null.");
        if (world.IslandIds == null || world.IslandIds.Length != world.Width * world.Height)
            throw new InvalidOperationException("LogIslandFieldDiagnostics failed: island field is missing or invalid.");
        if (!GameDebugSettings.IsEnabled(DebugCategory.Move))
            return;

        int walkableCount = 0;
        int[] islandSizes = new int[Mathf.Max(1, world.IslandCount + 1)];
        int[] islandSampleX = new int[islandSizes.Length];
        int[] islandSampleY = new int[islandSizes.Length];
        int[] islandMinX = new int[islandSizes.Length];
        int[] islandMaxX = new int[islandSizes.Length];
        int[] islandMinY = new int[islandSizes.Length];
        int[] islandMaxY = new int[islandSizes.Length];
        for (int i = 0; i < islandSampleX.Length; i++)
        {
            islandSampleX[i] = -1;
            islandSampleY[i] = -1;
            islandMinX[i] = int.MaxValue;
            islandMaxX[i] = int.MinValue;
            islandMinY[i] = int.MaxValue;
            islandMaxY[i] = int.MinValue;
        }

        for (int y = 0; y < world.Height; y++)
        {
            for (int x = 0; x < world.Width; x++)
            {
                int index = world.GetIndex(x, y);
                if (!world.WalkableMask[index])
                    continue;

                walkableCount++;
                int islandId = world.IslandIds[index];
                if (islandId <= 0 || islandId >= islandSizes.Length)
                    continue;

                islandSizes[islandId]++;
                if (x < islandMinX[islandId])
                    islandMinX[islandId] = x;
                if (x > islandMaxX[islandId])
                    islandMaxX[islandId] = x;
                if (y < islandMinY[islandId])
                    islandMinY[islandId] = y;
                if (y > islandMaxY[islandId])
                    islandMaxY[islandId] = y;
                if (islandSampleX[islandId] < 0)
                {
                    islandSampleX[islandId] = x;
                    islandSampleY[islandId] = y;
                }
            }
        }

        int largestIslandId = 0;
        int largestIslandSize = 0;
        int smallIslandCount = 0;
        for (int islandId = 1; islandId < islandSizes.Length; islandId++)
        {
            int size = islandSizes[islandId];
            if (size > largestIslandSize)
            {
                largestIslandSize = size;
                largestIslandId = islandId;
            }

            if (size > 0 && size <= 8)
                smallIslandCount++;
        }

        if (world.IslandCount <= 1)
            return;

        System.Text.StringBuilder builder = new System.Text.StringBuilder(1024);
        builder.Append("[FlowIslandFieldDiag] reason=");
        builder.Append(reason);
        builder.Append(" worldVersion=");
        builder.Append(world.Version);
        builder.Append(" agentType=");
        builder.Append(world.AgentTypeId);
        builder.Append(" size=");
        builder.Append(world.Width);
        builder.Append("x");
        builder.Append(world.Height);
        builder.Append(" cellSize=");
        builder.Append(world.CellSize.ToString("F3"));
        builder.Append(" walkable=");
        builder.Append(walkableCount);
        builder.Append(" islandCount=");
        builder.Append(world.IslandCount);
        builder.Append(" largest=");
        builder.Append(largestIslandId);
        builder.Append(":");
        builder.Append(largestIslandSize);
        builder.Append(" smallIslands=");
        builder.Append(smallIslandCount);
        builder.Append(" samples=[");

        int appended = 0;
        for (int islandId = 1; islandId < islandSizes.Length && appended < 8; islandId++)
        {
            int size = islandSizes[islandId];
            if (size <= 0 || islandId == largestIslandId)
                continue;

            if (appended > 0)
                builder.Append(" | ");

            int sampleX = islandSampleX[islandId];
            int sampleY = islandSampleY[islandId];
            builder.Append("island=");
            builder.Append(islandId);
            builder.Append(" size=");
            builder.Append(size);
            builder.Append(" sample=(");
            builder.Append(sampleX);
            builder.Append(",");
            builder.Append(sampleY);
            builder.Append(") ");
            builder.Append("bbox=(");
            builder.Append(islandMinX[islandId]);
            builder.Append(",");
            builder.Append(islandMinY[islandId]);
            builder.Append(")-(");
            builder.Append(islandMaxX[islandId]);
            builder.Append(",");
            builder.Append(islandMaxY[islandId]);
            builder.Append(") ");
            builder.Append(BuildIslandBoundaryDiagnostics(world, islandId, largestIslandId, 6));
            builder.Append(" ");
            builder.Append(BuildNeighborLinkDiagnostics(world, sampleX, sampleY, 1, 6));
            appended++;
        }

        builder.Append("]");
        Debug.LogWarning(builder.ToString());
    }

    private static string BuildIslandBoundaryDiagnostics(NavigationWorld world, int islandId, int largestIslandId, int maxExamples)
    {
        if (world == null)
            return "boundary=world-null";
        if (world.IslandIds == null || world.IslandIds.Length != world.Width * world.Height)
            return "boundary=island-invalid";

        int blockedNeighborCount = 0;
        int baseBlockedNeighborCount = 0;
        int runtimeBlockedNeighborCount = 0;
        int otherIslandNeighborCount = 0;
        int noTraversalNeighborCount = 0;
        int largestNeighborCount = 0;
        int exampleCount = 0;
        System.Text.StringBuilder examples = new System.Text.StringBuilder(768);
        examples.Append("[");

        for (int y = 0; y < world.Height; y++)
        {
            for (int x = 0; x < world.Width; x++)
            {
                int index = world.GetIndex(x, y);
                if (world.IslandIds[index] != islandId)
                    continue;

                byte mask = world.NeighborTraversalMask[index];
                for (int i = 0; i < NeighborOffsetX.Length; i++)
                {
                    int toX = x + NeighborOffsetX[i];
                    int toY = y + NeighborOffsetY[i];
                    if (toX < 0 || toX >= world.Width || toY < 0 || toY >= world.Height)
                        continue;

                    int toIndex = world.GetIndex(toX, toY);
                    bool toWalkable = world.WalkableMask[toIndex];
                    if (!toWalkable)
                    {
                        blockedNeighborCount++;
                        bool baseWalkable = world.BaseWalkableMask != null
                                            && world.BaseWalkableMask.Length == world.WalkableMask.Length
                                            && world.BaseWalkableMask[toIndex];
                        if (baseWalkable)
                            runtimeBlockedNeighborCount++;
                        else
                            baseBlockedNeighborCount++;

                        if (exampleCount < maxExamples)
                        {
                            AppendBoundaryExamplePrefix(examples, ref exampleCount);
                            examples.Append("(");
                            examples.Append(x);
                            examples.Append(",");
                            examples.Append(y);
                            examples.Append(")->(");
                            examples.Append(toX);
                            examples.Append(",");
                            examples.Append(toY);
                            examples.Append("){blocked,base=");
                            examples.Append(baseWalkable);
                            examples.Append("}");
                        }

                        continue;
                    }

                    int toIsland = world.IslandIds[toIndex];
                    if (toIsland == islandId)
                        continue;

                    otherIslandNeighborCount++;
                    if (toIsland == largestIslandId)
                        largestNeighborCount++;

                    bool hasTraversal = (mask & (1 << i)) != 0;
                    if (!hasTraversal)
                        noTraversalNeighborCount++;

                    if (exampleCount < maxExamples)
                    {
                        AppendBoundaryExamplePrefix(examples, ref exampleCount);
                        examples.Append("(");
                        examples.Append(x);
                        examples.Append(",");
                        examples.Append(y);
                        examples.Append(")->(");
                        examples.Append(toX);
                        examples.Append(",");
                        examples.Append(toY);
                        examples.Append("){toIsland=");
                        examples.Append(toIsland);
                        examples.Append(",traverse=");
                        examples.Append(hasTraversal);
                        examples.Append("}");
                    }
                }
            }
        }

        if (exampleCount == 0)
            examples.Append("none");
        examples.Append("]");

        return "boundary={blocked="
               + blockedNeighborCount
               + ",baseBlocked="
               + baseBlockedNeighborCount
               + ",runtimeBlocked="
               + runtimeBlockedNeighborCount
               + ",otherIsland="
               + otherIslandNeighborCount
               + ",largestNeighbors="
               + largestNeighborCount
               + ",noTraversal="
               + noTraversalNeighborCount
               + ",examples="
               + examples
               + "}";
    }

    private static void AppendBoundaryExamplePrefix(System.Text.StringBuilder builder, ref int exampleCount)
    {
        if (exampleCount > 0)
            builder.Append("; ");

        exampleCount++;
    }

    private static string BuildNeighborLinkDiagnostics(NavigationWorld world, int centerX, int centerY, int radius, int maxLinks = 16)
    {
        if (world == null)
            return "links=world-null";
        if (world.NeighborTraversalMask == null || world.NeighborTraversalMask.Length != world.Width * world.Height)
            return "links=mask-invalid";

        System.Text.StringBuilder builder = new System.Text.StringBuilder(768);
        builder.Append("links=[");
        int count = 0;
        for (int y = centerY - radius; y <= centerY + radius && count < maxLinks; y++)
        {
            for (int x = centerX - radius; x <= centerX + radius && count < maxLinks; x++)
            {
                if (x < 0 || x >= world.Width || y < 0 || y >= world.Height || !world.IsWalkable(x, y))
                    continue;

                int fromIndex = world.GetIndex(x, y);
                byte mask = world.NeighborTraversalMask[fromIndex];
                int fromIsland = ResolveIslandIdForDiagnostics(world, x, y);
                for (int i = 0; i < NeighborOffsetX.Length && count < maxLinks; i++)
                {
                    int toX = x + NeighborOffsetX[i];
                    int toY = y + NeighborOffsetY[i];
                    if (toX < 0 || toX >= world.Width || toY < 0 || toY >= world.Height || !world.IsWalkable(toX, toY))
                        continue;

                    bool hasTraversal = (mask & (1 << i)) != 0;
                    int toIsland = ResolveIslandIdForDiagnostics(world, toX, toY);
                    if (hasTraversal && fromIsland == toIsland)
                        continue;

                    if (count > 0)
                        builder.Append("; ");

                    builder.Append("(");
                    builder.Append(x);
                    builder.Append(",");
                    builder.Append(y);
                    builder.Append(")->(");
                    builder.Append(toX);
                    builder.Append(",");
                    builder.Append(toY);
                    builder.Append("){fromIsland=");
                    builder.Append(fromIsland);
                    builder.Append(",toIsland=");
                    builder.Append(toIsland);
                    builder.Append(",traverse=");
                    builder.Append(hasTraversal);

                    builder.Append("}");
                    count++;
                }
            }
        }

        if (count == 0)
            builder.Append("none");
        builder.Append("]");
        return builder.ToString();
    }

    private static bool CanTraverseSamplePath(NavigationWorld world, int fromX, int fromY, int toX, int toY)
    {
        int dx = toX - fromX;
        int dy = toY - fromY;
        if (dx != 0 && dy != 0)
            return false;
        int steps = Mathf.Abs(dx) + Mathf.Abs(dy);
        if (steps == 0)
            return world.IsWalkable(fromX, fromY);

        int stepX = Math.Sign(dx);
        int stepY = Math.Sign(dy);
        int currentX = fromX;
        int currentY = fromY;
        for (int i = 0; i < steps; i++)
        {
            int nextX = currentX + stepX;
            int nextY = currentY + stepY;
            if (!CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                return false;
            currentX = nextX;
            currentY = nextY;
        }
        return true;
    }

    private static bool CanTraverseNeighborCells(NavigationWorld world, int fromX, int fromY, int toX, int toY)
    {
        if (!world.IsWalkable(fromX, fromY) || !world.IsWalkable(toX, toY))
            return false;

        int dx = Mathf.Abs(toX - fromX);
        int dy = Mathf.Abs(toY - fromY);
        if (dx > 1 || dy > 1 || (dx == 0 && dy == 0))
            return false;

        if (!HasRawNeighborTraversal(world, fromX, fromY, toX, toY))
            return false;

        if (dx == 1 && dy == 1 && !IsDiagonalPassable(world, fromX, fromY, toX, toY))
            return false;

        return true;
    }

    private static bool TryGetCommittedNavigationQueryWorld(int agentTypeId, bool allowSynchronousBuild, out NavigationWorld world)
    {
        world = null;
        try
        {
            if (!TryEnsureWorldBuilt(agentTypeId, allowSynchronousBuild))
                return false;
        }
        catch (InvalidOperationException exception)
        {
            if (GameDebugSettings.IsEnabled(DebugCategory.Move))
                Debug.LogWarning($"[FlowNavigationQuery] world unavailable agentType={agentTypeId}: {exception.Message}");
            return false;
        }

        WorldRuntimeState state = _activeWorldState;
        if (state == null || state.World == null)
            return false;

        world = state.World;
        return true;
    }

    private static bool TryGetCommittedNavigationQueryWorldReadOnly(
        int agentTypeId,
        out WorldRuntimeState state,
        out NavigationWorld world)
    {
        int resolvedAgentTypeId = ResolvePreferredAgentTypeId(agentTypeId);
        state = null;
        world = null;
        if (!WorldStates.TryGetValue(resolvedAgentTypeId, out state) || state == null)
            return false;
        if (state.AgentTypeId != resolvedAgentTypeId)
        {
            throw new InvalidOperationException(
                $"Read-only navigation world lookup found an agent type mismatch. key={resolvedAgentTypeId}, state={state.AgentTypeId}.");
        }
        if (state.IsDirty || state.BuildJob != null || state.World == null)
            return false;
        if (state.World.AgentTypeId != resolvedAgentTypeId)
        {
            throw new InvalidOperationException(
                $"Read-only navigation world lookup found a committed world mismatch. key={resolvedAgentTypeId}, world={state.World.AgentTypeId}.");
        }

        world = state.World;
        return true;
    }

    private static bool TryGetNavigationQueryWorld(int agentTypeId, bool allowSynchronousBuild, out NavigationWorld world)
    {
        if (!TryGetCommittedNavigationQueryWorld(agentTypeId, allowSynchronousBuild, out world))
            return false;

        WorldRuntimeState state = _activeWorldState;
        if (state == null || state.World == null)
            return false;

        world = HasPendingRuntimeDirty(state) ? ResolveReachabilityQueryWorld(state) : world;
        return world != null;
    }

    private static bool IsNavigationSegmentWalkable(
        NavigationWorld world,
        Vector3 position,
        Vector3 horizontalDisplacement,
        float edgeClearance = 0f,
        bool requireClearStart = true,
        bool includeRuntimeObstacleOverlay = false)
    {
        if (world == null)
            return false;
        if (!world.WorldToGrid(position, out int previousX, out int previousY) || !world.IsWalkable(previousX, previousY))
            return false;
        if (requireClearStart && !IsNavigationPointClear(world, position, edgeClearance, includeRuntimeObstacleOverlay))
            return false;

        Vector3 target = position + horizontalDisplacement;
        if (!world.WorldToGrid(target, out int targetX, out int targetY) || !world.IsWalkable(targetX, targetY))
            return false;
        if (!IsNavigationPointAllowedFromStart(world, position, target, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay))
            return false;

        float distance = horizontalDisplacement.magnitude;
        int steps = Mathf.Max(1, Mathf.CeilToInt(distance / Mathf.Max(world.CellSize * 0.45f, 0.001f)));
        for (int i = 1; i <= steps; i++)
        {
            Vector3 sample = position + horizontalDisplacement * (i / (float)steps);
            if (!world.WorldToGrid(sample, out int x, out int y) || !world.IsWalkable(x, y))
                return false;
            if (!IsNavigationPointAllowedFromStart(world, position, sample, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay))
                return false;

            if (x == previousX && y == previousY)
                continue;

            int dx = Math.Abs(x - previousX);
            int dy = Math.Abs(y - previousY);
            if (dx > 1 || dy > 1)
            {
                if (!IsNavigationCellTraceWalkable(world, previousX, previousY, x, y))
                    return false;
            }
            else if (!CanTraverseNeighborCells(world, previousX, previousY, x, y))
            {
                return false;
            }

            previousX = x;
            previousY = y;
        }

        return true;
    }

    private static string BuildNavigationSegmentWalkableDiagnostics(
        NavigationWorld world,
        Vector3 position,
        Vector3 horizontalDisplacement,
        float edgeClearance,
        bool requireClearStart,
        bool includeRuntimeObstacleOverlay)
    {
        if (world == null)
            return "world=null";
        if (!world.WorldToGrid(position, out int previousX, out int previousY))
            return $"start outside position={position}";
        if (!world.IsWalkable(previousX, previousY))
            return $"start blocked cell=({previousX},{previousY}) position={position} sample={FormatGridSampleDiagnostics(position)}";
        if (requireClearStart && !IsNavigationPointClear(world, position, edgeClearance, includeRuntimeObstacleOverlay))
        {
            float violation = ResolveNavigationClearanceViolation(world, position, edgeClearance, includeRuntimeObstacleOverlay);
            return $"start clearance failed cell=({previousX},{previousY}) clearance={edgeClearance:F3} violation={(float.IsPositiveInfinity(violation) ? "INF" : violation.ToString("F3"))}";
        }

        Vector3 target = position + horizontalDisplacement;
        if (!world.WorldToGrid(target, out int targetX, out int targetY))
            return $"target outside target={target}";
        if (!world.IsWalkable(targetX, targetY))
            return $"target blocked cell=({targetX},{targetY}) target={target} sample={FormatGridSampleDiagnostics(target)}";
        if (!IsNavigationPointAllowedFromStart(world, position, target, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay))
        {
            float violation = ResolveNavigationClearanceViolation(world, target, edgeClearance, includeRuntimeObstacleOverlay);
            return $"target clearance failed cell=({targetX},{targetY}) clearance={edgeClearance:F3} violation={(float.IsPositiveInfinity(violation) ? "INF" : violation.ToString("F3"))}";
        }

        float distance = horizontalDisplacement.magnitude;
        int steps = Mathf.Max(1, Mathf.CeilToInt(distance / Mathf.Max(world.CellSize * 0.45f, 0.001f)));
        for (int i = 1; i <= steps; i++)
        {
            Vector3 sample = position + horizontalDisplacement * (i / (float)steps);
            if (!world.WorldToGrid(sample, out int x, out int y))
                return $"sample outside step={i}/{steps} sample={sample}";
            if (!world.IsWalkable(x, y))
                return $"sample blocked step={i}/{steps} cell=({x},{y}) sample={sample} trace={BuildLineOfSightDecisionCellTrace(world, previousX, previousY, x, y)}";
            if (!IsNavigationPointAllowedFromStart(world, position, sample, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay))
            {
                float violation = ResolveNavigationClearanceViolation(world, sample, edgeClearance, includeRuntimeObstacleOverlay);
                return $"sample clearance failed step={i}/{steps} cell=({x},{y}) clearance={edgeClearance:F3} violation={(float.IsPositiveInfinity(violation) ? "INF" : violation.ToString("F3"))}";
            }

            if (x == previousX && y == previousY)
                continue;

            int dx = Math.Abs(x - previousX);
            int dy = Math.Abs(y - previousY);
            if (dx > 1 || dy > 1)
            {
                if (!IsNavigationCellTraceWalkable(world, previousX, previousY, x, y))
                    return $"trace failed from=({previousX},{previousY}) to=({x},{y}) step={i}/{steps} trace={BuildLineOfSightDecisionCellTrace(world, previousX, previousY, x, y)}";
            }
            else if (!CanTraverseNeighborCells(world, previousX, previousY, x, y))
            {
                return $"neighbor failed from=({previousX},{previousY}) to=({x},{y}) step={i}/{steps} fromSample={BuildNeighborLinkDiagnostics(world, previousX, previousY, 0, 8)} toSample={BuildNeighborLinkDiagnostics(world, x, y, 0, 8)}";
            }

            previousX = x;
            previousY = y;
        }

        return $"ok start=({previousX},{previousY}) target=({targetX},{targetY}) steps={steps} clearance={edgeClearance:F3}";
    }

    private static bool IsNavigationPointAllowedFromStart(
        NavigationWorld world,
        Vector3 start,
        Vector3 point,
        float edgeClearance,
        bool requireClearStart,
        bool includeRuntimeObstacleOverlay)
    {
        if (requireClearStart)
            return IsNavigationPointClear(world, point, edgeClearance, includeRuntimeObstacleOverlay);
        if (IsNavigationPointClear(world, point, edgeClearance, includeRuntimeObstacleOverlay))
            return true;

        Fix64 clearanceFixed = Fix64.Max(Fix64.Zero, (Fix64)edgeClearance);
        Fix64 startViolation = ResolveNavigationClearanceViolationFixed(
            world,
            new FixVector2((Fix64)start.x, (Fix64)start.z),
            clearanceFixed,
            includeRuntimeObstacleOverlay);
        Fix64 pointViolation = ResolveNavigationClearanceViolationFixed(
            world,
            new FixVector2((Fix64)point.x, (Fix64)point.z),
            clearanceFixed,
            includeRuntimeObstacleOverlay);
        return pointViolation <= startViolation;
    }

    private static bool IsNavigationCellTraceWalkable(NavigationWorld world, int fromX, int fromY, int toX, int toY)
    {
        int currentX = fromX;
        int currentY = fromY;
        int steps = Mathf.Max(Math.Abs(toX - fromX), Math.Abs(toY - fromY));
        if (steps <= 0)
            return true;

        for (int i = 1; i <= steps; i++)
        {
            int nextX = Mathf.RoundToInt(Mathf.Lerp(fromX, toX, i / (float)steps));
            int nextY = Mathf.RoundToInt(Mathf.Lerp(fromY, toY, i / (float)steps));
            if (nextX == currentX && nextY == currentY)
                continue;
            if (!CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                return false;

            currentX = nextX;
            currentY = nextY;
        }

        return true;
    }

    private static void TrySelectNavigationDisplacementCandidate(
        NavigationWorld world,
        Vector3 position,
        Vector3 candidate,
        Vector3 desired,
        float desiredDistance,
        float edgeClearance,
        bool requireClearStart,
        bool includeRuntimeObstacleOverlay,
        ref Vector3 best,
        ref float bestScore,
        bool preserveDistance = true)
    {
        candidate.y = 0f;
        if (candidate.sqrMagnitude <= 0.000001f)
            return;

        if (preserveDistance)
            candidate = candidate.normalized * desiredDistance;

        if (!IsNavigationSegmentWalkable(world, position, candidate, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay))
            return;

        if (!IsNavigationConstraintCandidateAligned(candidate, desired))
            return;

        Vector3 desiredDirection = desired.sqrMagnitude > 0.000001f ? desired.normalized : Vector3.zero;
        float score = Vector3.Dot(candidate, desiredDirection) + candidate.magnitude * 0.05f;
        if (score <= bestScore)
            return;

        bestScore = score;
        best = candidate;
    }

    private static bool IsNavigationConstraintCandidateAligned(Vector3 candidate, Vector3 desired)
    {
        candidate.y = 0f;
        desired.y = 0f;
        if (candidate.sqrMagnitude <= 0.000001f || desired.sqrMagnitude <= 0.000001f)
            return false;

        return Vector3.Dot(candidate.normalized, desired.normalized) >= NavigationConstraintMinDirectionDot;
    }

    private static void TrySelectNavigationDirectionalFanCandidate(
        NavigationWorld world,
        Vector3 position,
        Vector3 desired,
        float desiredDistance,
        float edgeClearance,
        bool requireClearStart,
        bool includeRuntimeObstacleOverlay,
        ref Vector3 best,
        ref float bestScore)
    {
        if (desired.sqrMagnitude <= 0.000001f || desiredDistance <= 0.000001f)
            return;

        Vector3 direction = desired.normalized;
        TrySelectNavigationDisplacementCandidate(world, position, direction, desired, desiredDistance, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay, ref best, ref bestScore);

        for (int angle = 15; angle <= 75; angle += 15)
        {
            Vector3 left = RotateHorizontal(direction, angle);
            Vector3 right = RotateHorizontal(direction, -angle);
            TrySelectNavigationDisplacementCandidate(world, position, left, desired, desiredDistance, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay, ref best, ref bestScore);
            TrySelectNavigationDisplacementCandidate(world, position, right, desired, desiredDistance, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay, ref best, ref bestScore);
        }

        float halfDistance = desiredDistance * 0.5f;
        if (halfDistance <= 0.000001f)
            return;

        TrySelectNavigationDisplacementCandidate(world, position, direction * halfDistance, desired, halfDistance, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay, ref best, ref bestScore, preserveDistance: false);
        for (int angle = 15; angle <= 75; angle += 15)
        {
            Vector3 left = RotateHorizontal(direction, angle) * halfDistance;
            Vector3 right = RotateHorizontal(direction, -angle) * halfDistance;
            TrySelectNavigationDisplacementCandidate(world, position, left, desired, halfDistance, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay, ref best, ref bestScore, preserveDistance: false);
            TrySelectNavigationDisplacementCandidate(world, position, right, desired, halfDistance, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay, ref best, ref bestScore, preserveDistance: false);
        }
    }

    private static Vector3 RotateHorizontal(Vector3 direction, float degrees)
    {
        float radians = degrees * Mathf.Deg2Rad;
        float sin = Mathf.Sin(radians);
        float cos = Mathf.Cos(radians);
        return new Vector3(
            direction.x * cos - direction.z * sin,
            0f,
            direction.x * sin + direction.z * cos);
    }

    private static Vector3 FindLongestWalkablePrefix(
        NavigationWorld world,
        Vector3 position,
        Vector3 desired,
        float edgeClearance,
        bool requireClearStart,
        bool includeRuntimeObstacleOverlay)
    {
        Vector3 best = Vector3.zero;
        float low = 0f;
        float high = 1f;
        for (int i = 0; i < 7; i++)
        {
            float mid = (low + high) * 0.5f;
            Vector3 candidate = desired * mid;
            if (IsNavigationSegmentWalkable(world, position, candidate, edgeClearance, requireClearStart, includeRuntimeObstacleOverlay))
            {
                best = candidate;
                low = mid;
            }
            else
            {
                high = mid;
            }
        }

        return best;
    }

    private static bool IsNavigationPointClear(NavigationWorld world, Vector3 point, float edgeClearance)
    {
        return IsNavigationPointClear(world, point, edgeClearance, includeRuntimeObstacleOverlay: false);
    }

    private static bool IsNavigationPointClear(NavigationWorld world, Vector3 point, float edgeClearance, bool includeRuntimeObstacleOverlay)
    {
        return IsNavigationPointClearFixed(
            world,
            new FixVector2((Fix64)point.x, (Fix64)point.z),
            Fix64.Max(Fix64.Zero, (Fix64)edgeClearance),
            includeRuntimeObstacleOverlay);
    }

    private static bool IsNavigationPointClearFixed(
        NavigationWorld world,
        FixVector2 point,
        Fix64 edgeClearance,
        bool includeRuntimeObstacleOverlay)
    {
        if (world == null)
            throw new InvalidOperationException("IsNavigationPointClearFixed failed: world is null.");
        if (!world.WorldToGridFixed(point, out int cellX, out int cellY) || !world.IsWalkable(cellX, cellY))
            return false;
        if (edgeClearance <= Fix64.Zero)
            return !includeRuntimeObstacleOverlay || !IsPointInsideRuntimeObstacleOverlayFixed(point, Fix64.Zero);
        if (includeRuntimeObstacleOverlay && IsPointInsideRuntimeObstacleOverlayFixed(point, edgeClearance))
            return false;

        Fix64 clearanceSq = edgeClearance * edgeClearance;
        int radius = checked(NavigationGridFixedMath.DivideCeilingByCellSize(edgeClearance, world.CellSizeGridRaw) + 1);
        for (int y = cellY - radius; y <= cellY + radius; y++)
        {
            for (int x = cellX - radius; x <= cellX + radius; x++)
            {
                if (world.IsWalkable(x, y))
                    continue;

                world.GetGridCellBoundsFixed(x, y, out FixVector2 minimum, out FixVector2 maximum);
                Fix64 nearestX = Fix64.Clamp(point.x, minimum.x, maximum.x);
                Fix64 nearestZ = Fix64.Clamp(point.y, minimum.y, maximum.y);
                Fix64 dx = nearestX - point.x;
                Fix64 dz = nearestZ - point.y;
                if (dx * dx + dz * dz < clearanceSq)
                    return false;
            }
        }

        return true;
    }

    private static float ResolveNavigationClearanceViolation(NavigationWorld world, Vector3 point, float edgeClearance)
    {
        return ResolveNavigationClearanceViolation(world, point, edgeClearance, includeRuntimeObstacleOverlay: false);
    }

    private static float ResolveNavigationClearanceViolation(NavigationWorld world, Vector3 point, float edgeClearance, bool includeRuntimeObstacleOverlay)
    {
        Fix64 violation = ResolveNavigationClearanceViolationFixed(
            world,
            new FixVector2((Fix64)point.x, (Fix64)point.z),
            Fix64.Max(Fix64.Zero, (Fix64)edgeClearance),
            includeRuntimeObstacleOverlay);
        return violation.RawValue == long.MaxValue ? float.PositiveInfinity : (float)violation;
    }

    private static Fix64 ResolveNavigationClearanceViolationFixed(
        NavigationWorld world,
        FixVector2 point,
        Fix64 edgeClearance,
        bool includeRuntimeObstacleOverlay)
    {
        if (!world.WorldToGridFixed(point, out int cellX, out int cellY) || !world.IsWalkable(cellX, cellY))
            return Fix64.FromRaw(long.MaxValue);
        if (edgeClearance <= Fix64.Zero)
            return includeRuntimeObstacleOverlay && IsPointInsideRuntimeObstacleOverlayFixed(point, Fix64.Zero)
                ? Fix64.FromRaw(long.MaxValue)
                : Fix64.Zero;

        Fix64 minDistanceSq = Fix64.FromRaw(long.MaxValue);
        int radius = checked(NavigationGridFixedMath.DivideCeilingByCellSize(edgeClearance, world.CellSizeGridRaw) + 1);
        for (int y = cellY - radius; y <= cellY + radius; y++)
        {
            for (int x = cellX - radius; x <= cellX + radius; x++)
            {
                if (world.IsWalkable(x, y))
                    continue;

                world.GetGridCellBoundsFixed(x, y, out FixVector2 minimum, out FixVector2 maximum);
                Fix64 nearestX = Fix64.Clamp(point.x, minimum.x, maximum.x);
                Fix64 nearestZ = Fix64.Clamp(point.y, minimum.y, maximum.y);
                Fix64 dx = nearestX - point.x;
                Fix64 dz = nearestZ - point.y;
                Fix64 distanceSq = dx * dx + dz * dz;
                if (distanceSq < minDistanceSq)
                    minDistanceSq = distanceSq;
            }
        }

        if (minDistanceSq.RawValue == long.MaxValue)
            return includeRuntimeObstacleOverlay
                ? ResolveRuntimeObstacleOverlayClearanceViolationFixed(point, edgeClearance)
                : Fix64.Zero;

        Fix64 distance = Fix64.Sqrt(minDistanceSq);
        Fix64 staticViolation = Fix64.Max(Fix64.Zero, edgeClearance - distance);
        if (!includeRuntimeObstacleOverlay)
            return staticViolation;

        Fix64 overlayViolation = ResolveRuntimeObstacleOverlayClearanceViolationFixed(point, edgeClearance);
        if (overlayViolation.RawValue == long.MaxValue)
            return overlayViolation;
        return Fix64.Max(staticViolation, overlayViolation);
    }

    private static bool IsPointInsideRuntimeObstacleOverlay(Vector3 point, float clearance)
    {
        return IsPointInsideRuntimeObstacleOverlayFixed(
            new FixVector2((Fix64)point.x, (Fix64)point.z),
            Fix64.Max(Fix64.Zero, (Fix64)clearance));
    }

    private static bool IsPointInsideRuntimeObstacleOverlayFixed(FixVector2 point, Fix64 clearance)
    {
        return ResolveRuntimeObstacleOverlayClearanceViolationFixed(point, clearance) > Fix64.Zero;
    }

    private static float ResolveRuntimeObstacleOverlayClearanceViolation(Vector3 point, float edgeClearance)
    {
        Fix64 violation = ResolveRuntimeObstacleOverlayClearanceViolationFixed(
            new FixVector2((Fix64)point.x, (Fix64)point.z),
            Fix64.Max(Fix64.Zero, (Fix64)edgeClearance));
        return violation.RawValue == long.MaxValue ? float.PositiveInfinity : (float)violation;
    }

    private static Fix64 ResolveRuntimeObstacleOverlayClearanceViolationFixed(FixVector2 point, Fix64 edgeClearance)
    {
        Fix64 maxViolation = Fix64.Zero;
        foreach (BoxObstacle box in BoxObstacles.Values)
        {
            Fix64 dx = Fix64.Max(Fix64.Abs(point.x - box.CenterFixed.x) - Fix64.Max(Fix64.Zero, box.HalfExtentsFixed.x), Fix64.Zero);
            Fix64 dz = Fix64.Max(Fix64.Abs(point.y - box.CenterFixed.y) - Fix64.Max(Fix64.Zero, box.HalfExtentsFixed.y), Fix64.Zero);
            Fix64 distance = Fix64.Sqrt(dx * dx + dz * dz);
            if (distance <= Fix64.Zero)
                return Fix64.FromRaw(long.MaxValue);

            maxViolation = Fix64.Max(maxViolation, edgeClearance - distance);
        }

        foreach (CircleObstacle circle in CircleObstacles.Values)
        {
            Fix64 dx = point.x - circle.PositionFixed.x;
            Fix64 dz = point.y - circle.PositionFixed.y;
            Fix64 distance = Fix64.Sqrt(dx * dx + dz * dz) - Fix64.Max(Fix64.Zero, circle.RadiusFixed);
            if (distance <= Fix64.Zero)
                return Fix64.FromRaw(long.MaxValue);

            maxViolation = Fix64.Max(maxViolation, edgeClearance - distance);
        }

        return Fix64.Max(Fix64.Zero, maxViolation);
    }

    private static float ResolvePointToBoxObstacleDistanceXZ(Vector3 point, BoxObstacle box)
    {
        if (box == null)
            throw new InvalidOperationException("ResolvePointToBoxObstacleDistanceXZ failed: box is null.");

        float dx = Mathf.Max(Mathf.Abs(point.x - box.Center.x) - Mathf.Max(0f, box.HalfExtents.x), 0f);
        float dz = Mathf.Max(Mathf.Abs(point.z - box.Center.z) - Mathf.Max(0f, box.HalfExtents.z), 0f);
        return Mathf.Sqrt(dx * dx + dz * dz);
    }

    private static float ResolvePointToCircleObstacleDistanceXZ(Vector3 point, CircleObstacle circle)
    {
        if (circle == null)
            throw new InvalidOperationException("ResolvePointToCircleObstacleDistanceXZ failed: circle is null.");

        float dx = point.x - circle.Position.x;
        float dz = point.z - circle.Position.z;
        return Mathf.Sqrt(dx * dx + dz * dz) - Mathf.Max(0f, circle.Radius);
    }

    private static bool IsNavigationCellClear(NavigationWorld world, int cellX, int cellY, float edgeClearance)
    {
        return IsNavigationCellClear(world, cellX, cellY, edgeClearance, includeRuntimeObstacleOverlay: false);
    }

    private static bool IsNavigationCellClear(NavigationWorld world, int cellX, int cellY, float edgeClearance, bool includeRuntimeObstacleOverlay)
    {
        return IsNavigationCellClearFixed(
            world,
            cellX,
            cellY,
            Fix64.Max(Fix64.Zero, (Fix64)edgeClearance),
            includeRuntimeObstacleOverlay);
    }

    private static bool IsNavigationCellClearFixed(
        NavigationWorld world,
        int cellX,
        int cellY,
        Fix64 edgeClearance,
        bool includeRuntimeObstacleOverlay)
    {
        if (!world.IsWalkable(cellX, cellY))
            return false;
        Fix64 violation = ResolveNavigationClearanceViolationFixed(
            world,
            world.GridToWorldCenterFixed(cellX, cellY),
            Fix64.Max(Fix64.Zero, edgeClearance),
            includeRuntimeObstacleOverlay);
        return violation == Fix64.Zero;
    }

    private static bool TryEstimateGridPathDistance(NavigationWorld world, int startX, int startY, int goalX, int goalY, out float distance)
    {
        return TryFindGridPath(world, startX, startY, goalX, goalY, null, default, default, out distance);
    }

    private static bool TryFindGridPath(
        NavigationWorld world,
        int startX,
        int startY,
        int goalX,
        int goalY,
        List<Vector3> pathCorners,
        Vector3 from,
        Vector3 to,
        out float distance)
    {
        distance = 0f;
        int searchId = BeginDistanceEstimateSearch(world.Width * world.Height);
        int startIndex = world.GetIndex(startX, startY);
        int goalIndex = world.GetIndex(goalX, goalY);
        DistanceEstimateCosts[startIndex] = 0f;
        DistanceEstimateVisitedMarks[startIndex] = searchId;
        if (pathCorners != null)
            DistanceEstimateParents[startIndex] = -1;
        DistanceEstimateOpenSet.Push(startIndex, EstimateGridHeuristicCost(startX, startY, goalX, goalY, world.CellSize));

        while (DistanceEstimateOpenSet.Count > 0)
        {
            int currentIndex = DistanceEstimateOpenSet.Pop().Index;
            if (DistanceEstimateClosedMarks[currentIndex] == searchId)
                continue;

            if (currentIndex == goalIndex)
            {
                distance = DistanceEstimateCosts[currentIndex];
                if (pathCorners != null)
                    BuildGridPathCorners(world, startIndex, goalIndex, from, to, pathCorners);
                return true;
            }

            DistanceEstimateClosedMarks[currentIndex] = searchId;
            int currentX = currentIndex % world.Width;
            int currentY = currentIndex / world.Width;
            float currentCost = DistanceEstimateCosts[currentIndex];
            for (int i = 0; i < NeighborOffsetX.Length; i++)
            {
                int nextX = currentX + NeighborOffsetX[i];
                int nextY = currentY + NeighborOffsetY[i];
                if (!CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                    continue;

                int nextIndex = world.GetIndex(nextX, nextY);
                if (DistanceEstimateClosedMarks[nextIndex] == searchId)
                    continue;

                float stepCost = (NeighborOffsetX[i] != 0 && NeighborOffsetY[i] != 0) ? world.CellSize * 1.41421356f : world.CellSize;
                float nextCost = currentCost + stepCost;
                if (DistanceEstimateVisitedMarks[nextIndex] == searchId && nextCost >= DistanceEstimateCosts[nextIndex])
                    continue;

                DistanceEstimateVisitedMarks[nextIndex] = searchId;
                DistanceEstimateCosts[nextIndex] = nextCost;
                if (pathCorners != null)
                    DistanceEstimateParents[nextIndex] = currentIndex;
                float priority = nextCost + EstimateGridHeuristicCost(nextX, nextY, goalX, goalY, world.CellSize);
                DistanceEstimateOpenSet.Push(nextIndex, priority);
            }
        }

        return false;
    }

    private static bool TryFindGridPathFixed(
        NavigationWorld world,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out Fix64 distance)
    {
        distance = Fix64.Zero;
        int searchId = BeginDistanceEstimateSearch(world.Width * world.Height);
        int startIndex = world.GetIndex(startX, startY);
        int goalIndex = world.GetIndex(goalX, goalY);
        FixedDistanceEstimateCosts[startIndex] = 0L;
        DistanceEstimateVisitedMarks[startIndex] = searchId;
        FixedDistanceEstimateOpenSet.Push(
            startIndex,
            EstimateGridHeuristicCostFixed(startX, startY, goalX, goalY, world.CellSizeFixed).RawValue);

        Fix64 diagonalStepCost = world.CellSizeFixed * Fix64.Sqrt((Fix64)2);
        while (FixedDistanceEstimateOpenSet.Count > 0)
        {
            int currentIndex = FixedDistanceEstimateOpenSet.Pop().Index;
            if (DistanceEstimateClosedMarks[currentIndex] == searchId)
                continue;

            if (currentIndex == goalIndex)
            {
                distance = Fix64.FromRaw(FixedDistanceEstimateCosts[currentIndex]);
                return true;
            }

            DistanceEstimateClosedMarks[currentIndex] = searchId;
            int currentX = currentIndex % world.Width;
            int currentY = currentIndex / world.Width;
            long currentCostRaw = FixedDistanceEstimateCosts[currentIndex];
            for (int i = 0; i < NeighborOffsetX.Length; i++)
            {
                int nextX = currentX + NeighborOffsetX[i];
                int nextY = currentY + NeighborOffsetY[i];
                if (!CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                    continue;

                int nextIndex = world.GetIndex(nextX, nextY);
                if (DistanceEstimateClosedMarks[nextIndex] == searchId)
                    continue;

                long stepCostRaw = NeighborOffsetX[i] != 0 && NeighborOffsetY[i] != 0
                    ? diagonalStepCost.RawValue
                    : world.CellSizeFixed.RawValue;
                long nextCostRaw = checked(currentCostRaw + stepCostRaw);
                if (DistanceEstimateVisitedMarks[nextIndex] == searchId
                    && nextCostRaw >= FixedDistanceEstimateCosts[nextIndex])
                {
                    continue;
                }

                DistanceEstimateVisitedMarks[nextIndex] = searchId;
                FixedDistanceEstimateCosts[nextIndex] = nextCostRaw;
                long priorityRaw = checked(
                    nextCostRaw
                    + EstimateGridHeuristicCostFixed(nextX, nextY, goalX, goalY, world.CellSizeFixed).RawValue);
                FixedDistanceEstimateOpenSet.Push(nextIndex, priorityRaw);
            }
        }

        return false;
    }

    private static bool TryFindSectorPathFixed(
        NavigationWorld world,
        SectorData sector,
        int startX,
        int startY,
        int goalX,
        int goalY,
        out Fix64 distance)
    {
        distance = Fix64.Zero;
        if (world == null)
            throw new ArgumentNullException(nameof(world));
        if (sector == null)
            throw new ArgumentNullException(nameof(sector));
        if (!IsInsideSector(sector, startX, startY) || !IsInsideSector(sector, goalX, goalY))
            throw new ArgumentOutOfRangeException(nameof(sector), "Sector-local path endpoints must be inside the supplied sector.");

        int searchId = BeginSectorDistanceEstimateSearch(sector.Width * sector.Height);
        int startIndex = GetSectorLocalIndex(sector, startX, startY);
        int goalIndex = GetSectorLocalIndex(sector, goalX, goalY);
        SectorDistanceEstimateCosts[startIndex] = 0L;
        SectorDistanceEstimateVisitedMarks[startIndex] = searchId;
        SectorDistanceEstimateOpenSet.Push(
            startIndex,
            EstimateGridHeuristicCostFixed(startX, startY, goalX, goalY, world.CellSizeFixed).RawValue);

        Fix64 diagonalStepCost = world.CellSizeFixed * Fix64.Sqrt((Fix64)2);
        while (SectorDistanceEstimateOpenSet.Count > 0)
        {
            int currentIndex = SectorDistanceEstimateOpenSet.Pop().Index;
            if (SectorDistanceEstimateClosedMarks[currentIndex] == searchId)
                continue;
            if (currentIndex == goalIndex)
            {
                distance = Fix64.FromRaw(SectorDistanceEstimateCosts[currentIndex]);
                return true;
            }

            SectorDistanceEstimateClosedMarks[currentIndex] = searchId;
            int currentX = sector.StartX + currentIndex % sector.Width;
            int currentY = sector.StartY + currentIndex / sector.Width;
            long currentCostRaw = SectorDistanceEstimateCosts[currentIndex];
            for (int i = 0; i < NeighborOffsetX.Length; i++)
            {
                int nextX = currentX + NeighborOffsetX[i];
                int nextY = currentY + NeighborOffsetY[i];
                if (!IsInsideSector(sector, nextX, nextY)
                    || !CanTraverseNeighborCells(world, currentX, currentY, nextX, nextY))
                {
                    continue;
                }

                int nextIndex = GetSectorLocalIndex(sector, nextX, nextY);
                if (SectorDistanceEstimateClosedMarks[nextIndex] == searchId)
                    continue;
                long stepCostRaw = NeighborOffsetX[i] != 0 && NeighborOffsetY[i] != 0
                    ? diagonalStepCost.RawValue
                    : world.CellSizeFixed.RawValue;
                long nextCostRaw = checked(currentCostRaw + stepCostRaw);
                if (SectorDistanceEstimateVisitedMarks[nextIndex] == searchId
                    && nextCostRaw >= SectorDistanceEstimateCosts[nextIndex])
                {
                    continue;
                }

                SectorDistanceEstimateVisitedMarks[nextIndex] = searchId;
                SectorDistanceEstimateCosts[nextIndex] = nextCostRaw;
                long priorityRaw = checked(
                    nextCostRaw
                    + EstimateGridHeuristicCostFixed(nextX, nextY, goalX, goalY, world.CellSizeFixed).RawValue);
                SectorDistanceEstimateOpenSet.Push(nextIndex, priorityRaw);
            }
        }

        return false;
    }

    private static int BeginSectorDistanceEstimateSearch(int cellCount)
    {
        if (cellCount <= 0)
            throw new InvalidOperationException($"BeginSectorDistanceEstimateSearch failed: invalid cellCount={cellCount}.");
        if (SectorDistanceEstimateCosts.Length < cellCount)
        {
            SectorDistanceEstimateCosts = new long[cellCount];
            SectorDistanceEstimateVisitedMarks = new int[cellCount];
            SectorDistanceEstimateClosedMarks = new int[cellCount];
            SectorDistanceEstimateSearchId = 0;
        }
        if (SectorDistanceEstimateSearchId == int.MaxValue)
        {
            Array.Clear(SectorDistanceEstimateVisitedMarks, 0, SectorDistanceEstimateVisitedMarks.Length);
            Array.Clear(SectorDistanceEstimateClosedMarks, 0, SectorDistanceEstimateClosedMarks.Length);
            SectorDistanceEstimateSearchId = 0;
        }

        SectorDistanceEstimateOpenSet.Clear();
        SectorDistanceEstimateSearchId++;
        return SectorDistanceEstimateSearchId;
    }

    private static void BuildGridPathCorners(
        NavigationWorld world,
        int startIndex,
        int goalIndex,
        Vector3 from,
        Vector3 to,
        List<Vector3> pathCorners)
    {
        DistanceEstimatePathIndices.Clear();
        int currentIndex = goalIndex;
        int remaining = world.Width * world.Height;
        while (currentIndex >= 0 && remaining-- > 0)
        {
            DistanceEstimatePathIndices.Add(currentIndex);
            if (currentIndex == startIndex)
                break;

            currentIndex = DistanceEstimateParents[currentIndex];
        }

        if (DistanceEstimatePathIndices.Count == 0
            || DistanceEstimatePathIndices[DistanceEstimatePathIndices.Count - 1] != startIndex)
        {
            throw new InvalidOperationException(
                $"BuildGridPathCorners failed: parent chain did not reach start startIndex={startIndex} goalIndex={goalIndex}.");
        }

        DistanceEstimatePathIndices.Reverse();
        pathCorners.Clear();
        pathCorners.Add(from);

        int previousDx = 0;
        int previousDy = 0;
        for (int i = 1; i < DistanceEstimatePathIndices.Count; i++)
        {
            int previousIndex = DistanceEstimatePathIndices[i - 1];
            int nextIndex = DistanceEstimatePathIndices[i];
            int dx = nextIndex % world.Width - previousIndex % world.Width;
            int dy = nextIndex / world.Width - previousIndex / world.Width;
            if (i > 1 && (dx != previousDx || dy != previousDy))
            {
                int cornerIndex = DistanceEstimatePathIndices[i - 1];
                pathCorners.Add(world.GridToWorldCenter(cornerIndex % world.Width, cornerIndex / world.Width));
            }

            previousDx = dx;
            previousDy = dy;
        }

        pathCorners.Add(to);
    }

    private static int BeginDistanceEstimateSearch(int cellCount)
    {
        if (cellCount <= 0)
            throw new InvalidOperationException($"BeginDistanceEstimateSearch failed: invalid cellCount={cellCount}.");

        if (DistanceEstimateCosts.Length < cellCount)
        {
            DistanceEstimateCosts = new float[cellCount];
            FixedDistanceEstimateCosts = new long[cellCount];
            DistanceEstimateVisitedMarks = new int[cellCount];
            DistanceEstimateClosedMarks = new int[cellCount];
            DistanceEstimateParents = new int[cellCount];
            DistanceEstimateSearchId = 0;
        }

        if (DistanceEstimateSearchId == int.MaxValue)
        {
            Array.Clear(DistanceEstimateVisitedMarks, 0, DistanceEstimateVisitedMarks.Length);
            Array.Clear(DistanceEstimateClosedMarks, 0, DistanceEstimateClosedMarks.Length);
            DistanceEstimateSearchId = 0;
        }

        DistanceEstimateOpenSet.Clear();
        FixedDistanceEstimateOpenSet.Clear();
        DistanceEstimateSearchId++;
        return DistanceEstimateSearchId;
    }

    private static float EstimateGridHeuristicCost(int fromX, int fromY, int goalX, int goalY, float cellSize)
    {
        int dx = Mathf.Abs(goalX - fromX);
        int dy = Mathf.Abs(goalY - fromY);
        int diagonal = Mathf.Min(dx, dy);
        int straight = Mathf.Max(dx, dy) - diagonal;
        return (diagonal * 1.41421356f + straight) * cellSize;
    }

    private static Fix64 EstimateGridHeuristicCostFixed(
        int fromX,
        int fromY,
        int goalX,
        int goalY,
        Fix64 cellSize)
    {
        int dx = Math.Abs(goalX - fromX);
        int dy = Math.Abs(goalY - fromY);
        int diagonal = Math.Min(dx, dy);
        int straight = Math.Max(dx, dy) - diagonal;
        return ((Fix64)diagonal * Fix64.Sqrt((Fix64)2) + (Fix64)straight) * cellSize;
    }

    private static string BuildStartCellDiagnostics(IEntityContext self, Vector3 position)
    {
        if (_world == null)
            return "diag=world-null";

        bool worldInGrid = _world.WorldToGrid(position, out int worldX, out int worldY);
        bool worldWalkable = worldInGrid && _world.IsWalkable(worldX, worldY);

        bool baseWalkable = false;
        if (worldInGrid)
        {
            int worldIndex = _world.GetIndex(worldX, worldY);
            baseWalkable = _world.BaseWalkableMask[worldIndex];
        }

        Fog3MapData mapData = Fog3Manager.Instance != null ? Fog3Manager.Instance.MapData : null;
        bool fogInGrid = false;
        int fogX = 0;
        int fogY = 0;
        bool fogWalkable = false;
        Fog3CellState fogState = Fog3CellState.Outside;
        float fogVisibility = 0f;
        if (mapData != null)
        {
            fogInGrid = mapData.WorldToGrid(position, out fogX, out fogY);
            if (fogInGrid)
            {
                fogWalkable = mapData.IsWalkable(fogX, fogY);
                fogState = mapData.GetCellState(fogX, fogY);
                fogVisibility = mapData.GetVisibility(fogX, fogY);
            }
        }

        string probeDiagnostics = worldInGrid
            ? BuildCellProbeDiagnostics(_world, worldX, worldY)
            : "probes=out";
        string neighborhoodDiagnostics = worldInGrid
            ? BuildWalkableNeighborhoodDiagnostics(_world, worldX, worldY, 2)
            : "neighborhood=out";
        string nearestSearchDiagnostics = worldInGrid
            ? BuildNearestWalkableSearchDiagnostics(_world, worldX, worldY, 6)
            : "nearestSearch=out";

        return $"diag=agentType={_world.AgentTypeId} cellSize={_world.CellSize:F3} origin={_world.Origin} size={_world.Width}x{_world.Height} " +
               $"worldCell={(worldInGrid ? $"({worldX},{worldY})" : "out")} worldWalkable={worldWalkable} " +
               $"baseWalkable={baseWalkable} fogCell={(fogInGrid ? $"({fogX},{fogY})" : "out")} fogWalkable={fogWalkable} " +
               $"fogState={fogState} fogVis={fogVisibility:F2} " +
               $"{probeDiagnostics} {nearestSearchDiagnostics} {neighborhoodDiagnostics}";
    }

    private static string BuildAgentCellDiagnostic(AgentRuntimeData agent, Vector3 position)
    {
        if (_world == null)
            return "cell=world-null";

        bool inGrid = _world.WorldToGrid(position, out int cellX, out int cellY);
        int island = inGrid ? ResolveIslandIdForDiagnostics(_world, cellX, cellY) : -1;
        bool walkable = inGrid && _world.IsWalkable(cellX, cellY);
        bool baseWalkable = false;
        if (inGrid)
            baseWalkable = _world.BaseWalkableMask[_world.GetIndex(cellX, cellY)];

        return $"cell={(inGrid ? $"({cellX},{cellY})" : "out")} island={island} walkable={walkable} baseWalkable={baseWalkable} " +
               $"navStateCell={agent.NavState.CurrentCell} navStateSector={agent.NavState.CurrentSectorId}";
    }

    private static string BuildGridEdgeDiagnostic(Vector3 position, Vector3 desiredDirection)
    {
        if (_world == null)
            return "gridEdge=world-null";

        bool hasGridEdge = TryResolveGridEdgeData(position, desiredDirection, out Vector3 gridNormal, out float gridDistance);
        return hasGridEdge
            ? $"gridEdgeNormal={gridNormal} gridEdgeDist={gridDistance:F3}"
            : "gridEdge=none";
    }

    private static string BuildExecutorGridSegmentDiagnostic(Vector3 position, Vector3 desiredHorizontalDisplacement, Vector3 inputVelocity)
    {
        if (desiredHorizontalDisplacement.sqrMagnitude <= 0.000001f)
            return "executorGrid=zero-displacement";
        if (_world == null)
            return "executorGrid=world-null";

        Vector3 end = position + desiredHorizontalDisplacement;
        bool startInGrid = _world.WorldToGrid(position, out int startX, out int startY);
        bool endInGrid = _world.WorldToGrid(end, out int endX, out int endY);
        bool startWalkable = startInGrid && _world.IsWalkable(startX, startY);
        bool endWalkable = endInGrid && _world.IsWalkable(endX, endY);
        bool clear = startInGrid && endInGrid && HasGridLineOfSight(_world, startX, startY, endX, endY);
        string trace = startInGrid && endInGrid
            ? BuildLineOfSightCellTrace(_world, startX, startY, endX, endY)
            : "trace=out";

        Vector3 edgeNormal = Vector3.zero;
        float edgeDistance = 0f;
        bool hasEdge = TryResolveGridEdgeData(position, desiredHorizontalDisplacement, out edgeNormal, out edgeDistance);
        float intoBoundary = hasEdge ? Vector3.Dot(inputVelocity, -edgeNormal) : 0f;
        return $"executorGrid={{start=({(startInGrid ? startX.ToString() : "out")},{(startInGrid ? startY.ToString() : "out")}) end=({(endInGrid ? endX.ToString() : "out")},{(endInGrid ? endY.ToString() : "out")}) startWalk={startWalkable} endWalk={endWalkable} clear={clear} edgeNormal={edgeNormal} edgeDist={edgeDistance:F3} intoBoundary={intoBoundary:F3} {trace}}}";
    }

    private static void LogMissingConstraintAgentDiagnostic(
        IEntityContext self,
        int expectedAgentId,
        Vector3 currentPosition,
        Vector3 desiredHorizontalDisplacement,
        Vector3 inputVelocity,
        string executorReason)
    {
        if (!IsMovementDiagnosticsEnabled())
            return;
        string candidates = BuildConstraintAgentCandidateDiagnostic(self, currentPosition, 6);
        string executorGrid = BuildExecutorGridSegmentDiagnostic(
            currentPosition,
            desiredHorizontalDisplacement,
            inputVelocity);

        Debug.LogWarning(
            $"[FlowConstraintDiagMissingAgent] reason={executorReason} key={self.CharacterKey} expectedId={expectedAgentId} " +
            $"selfType={self.GetType().Name} side={self.Side} pos={currentPosition} selfPos={self.Position} " +
            $"agentType={(self is ILogicFrameEntity logicEntity ? logicEntity.NavigationAgentTypeId.ToString() : "unknown")} " +
            $"inputVelocity={inputVelocity} desiredDisp={desiredHorizontalDisplacement} {executorGrid} " +
            $"agents={Agents.Count} candidates={candidates}");
    }

    private static string BuildConstraintAgentCandidateDiagnostic(IEntityContext self, Vector3 currentPosition, int maxCandidates)
    {
        System.Text.StringBuilder builder = new System.Text.StringBuilder(512);
        builder.Append('[');
        int appended = 0;
        foreach (AgentRuntimeData candidate in Agents.Values)
        {
            bool sameKey = !string.IsNullOrEmpty(self.CharacterKey) && candidate.CharacterKey == self.CharacterKey;
            float distance = Vector3.Distance(candidate.Position, currentPosition);
            if (!sameKey && distance > 1.5f)
                continue;

            if (appended > 0)
                builder.Append(" | ");

            builder.Append("id=");
            builder.Append(candidate.Id);
            builder.Append(" key=");
            builder.Append(candidate.CharacterKey);
            builder.Append(" dist=");
            builder.Append(distance.ToString("F3"));
            builder.Append(" pos=");
            builder.Append(candidate.Position);
            builder.Append(" agentType=");
            builder.Append(candidate.AgentTypeId);
            builder.Append(" source=");
            builder.Append(candidate.RegistrationSource);
            builder.Append(" synthetic=");
            builder.Append(candidate.IsSyntheticRegistration);
            builder.Append(" intent=");
            builder.Append(candidate.HasNavigationIntent);
            builder.Append(" desired=");
            builder.Append(candidate.NavState.DesiredVelocity);
            builder.Append(" resolved=");
            builder.Append(candidate.NavState.ResolvedVelocity);

            appended++;
            if (appended >= maxCandidates)
                break;
        }

        if (appended == 0)
            builder.Append("none");
        builder.Append(']');
        return builder.ToString();
    }

    private static int ResolveAgentId(IEntityContext entity)
    {
        if (entity == null)
            throw new ArgumentNullException(nameof(entity));
        if (!entity.LogicEntityId.IsValid)
            throw new InvalidOperationException($"FlowFieldCrowdMovementSystem.ResolveAgentId failed: {entity.GetType().Name} has an invalid logic entity id.");

        return entity.LogicEntityId.Value;
    }

    private static int ResolveExplicitAgentTypeId(IEntityContext entity, string caller)
    {
        if (entity == null)
            throw new InvalidOperationException($"{caller} failed: entity is null.");
        if (entity is ILogicFrameEntity logicEntity)
        {
            if (logicEntity.NavigationAgentTypeId == MAEntity.UnknownNavAgentTypeId)
            {
                throw new InvalidOperationException(
                    $"{caller} failed: entity '{entity.CharacterKey}' has Unknown navigation agent type. Runtime flow worlds require an explicit movement type.");
            }

            return logicEntity.NavigationAgentTypeId;
        }

        return 0;
    }

    private static int ResolvePreferredAgentTypeId(int preferredAgentTypeId)
    {
        if (preferredAgentTypeId != MAEntity.UnknownNavAgentTypeId)
            return preferredAgentTypeId;

        throw new InvalidOperationException("ResolvePreferredAgentTypeId failed: preferred agent type is Unknown. Runtime navigation must pass an explicit agent type.");
    }

    private static float ResolveAgentTypeRadius(int agentTypeId)
    {
        return (float)ResolveAgentTypeRadiusFixed(agentTypeId);
    }

    private static Fix64 ResolveAgentTypeRadiusFixed(int agentTypeId)
    {
#if UNITY_EDITOR
        if (TestAgentTypeRadii.TryGetValue(agentTypeId, out Fix64 testRadius))
            return testRadius;
#endif

        if (agentTypeId == MAEntity.UnknownNavAgentTypeId)
            return Fix64.FromRaw(2048);

        if (agentTypeId == AgentTypeHelper.SmallMovementTypeId)
            return GetPreparedAgentTypeRadiusFixed(agentTypeId, s_SmallAgentTypeRadiusFixed);
        if (agentTypeId == AgentTypeHelper.MediumMovementTypeId)
            return GetPreparedAgentTypeRadiusFixed(agentTypeId, s_MediumAgentTypeRadiusFixed);
        if (agentTypeId == AgentTypeHelper.LargeMovementTypeId)
            return GetPreparedAgentTypeRadiusFixed(agentTypeId, s_LargeAgentTypeRadiusFixed);

        return Fix64.FromRaw(2048);
    }

    private static Fix64 GetPreparedAgentTypeRadiusFixed(int agentTypeId, Fix64 radius)
    {
        if (!s_RuntimeAgentTypeRadiiPrepared)
        {
            throw new InvalidOperationException(
                $"FlowField runtime agent radii were not prepared before resolving agent type {agentTypeId}.");
        }
        if (radius <= Fix64.Zero)
            throw new InvalidOperationException($"Prepared FlowField agent radius is invalid. agentType={agentTypeId}, raw={radius.RawValue}.");

        return radius;
    }

    private static Fix64 ResolveConfiguredAgentTypeRadiusFixed(string configKey)
    {
        Fix64 tableRadius = FixedConfigReader.ReadRequiredPositiveFixedConfig(configKey);
        return (tableRadius);
    }

    private static float ResolveCollisionRadius(IEntityContext entity)
    {
        return (float)ResolveCollisionRadiusFixed(entity);
    }

    private static Fix64 ResolveNavigationTargetExtentFixed(IEntityContext target)
    {
        if (target == null)
            throw new InvalidOperationException("ResolveNavigationTargetExtentFixed failed: target is null.");

        LogicCombatShape shape = LogicFrameRuntime.IsTicking
            ? LogicEntityFrameSnapshotService.GetRequiredCurrent(target).CombatShape
            : target.CombatShape;
        Fix64 extent;
        switch (shape.Kind)
        {
            case LogicCombatShapeKind.Circle:
                extent = shape.Radius;
                break;
            case LogicCombatShapeKind.AxisAlignedBox:
                extent = Fix64.Max(shape.HalfExtents.x, shape.HalfExtents.y);
                break;
            default:
                throw new InvalidOperationException(
                    $"ResolveNavigationTargetExtentFixed failed: target={target.LogicEntityId.Value}, " +
                    $"key={target.CharacterKey}, shapeKind={(int)shape.Kind}.");
        }

        if (extent <= Fix64.Zero)
        {
            throw new InvalidOperationException(
                $"ResolveNavigationTargetExtentFixed failed: target={target.LogicEntityId.Value}, " +
                $"key={target.CharacterKey}, shapeKind={shape.Kind}, extentRaw={extent.RawValue}, " +
                $"radiusRaw={shape.Radius.RawValue}, " +
                $"halfExtentsRaw=({shape.HalfExtents.x.RawValue},{shape.HalfExtents.y.RawValue}).");
        }

        return extent;
    }

    private static Fix64 ResolveCollisionRadiusFixed(IEntityContext entity)
    {
        if (entity == null)
            throw new InvalidOperationException("ResolveCollisionRadiusFixed failed: entity is null.");

        Fix64 propertyRadius = entity.GetProperty(CreatureMainProperty.CollisionRadius);
        Fix64 radius = (propertyRadius);
        if (radius <= Fix64.Zero)
        {
            LogicEntityState logicState = entity as LogicEntityState;
            string unitSize = entity.CharacterData != null ? entity.CharacterData.Size.ToString() : "<none>";
            throw new InvalidOperationException(
                $"ResolveCollisionRadiusFixed failed: entity={entity.LogicEntityId.Value}, key={entity.CharacterKey}, " +
                $"type={entity.GetType().FullName}, alive={entity.Alive}, unitSize={unitSize}, " +
                $"propertyRaw={propertyRadius.RawValue}, worldRaw={radius.RawValue}, " +
                $"navAgentType={logicState?.NavigationAgentTypeId.ToString() ?? "<unavailable>"}, " +
                $"usesFlow={logicState?.UsesFlowNavigationAgent.ToString() ?? "<unavailable>"}, " +
                $"hero={logicState?.IsHeroEntity.ToString() ?? "<unavailable>"}, " +
                $"preparedMovable={logicState?.PreparedCollisionMovable.ToString() ?? "<unavailable>"}.");
        }

        return radius;
    }
}
